/* ─── MODELO DA IA — UM LUGAR SÓ (14/09/2026) ─────────────────
   O app estava pregado no Sonnet 4 de maio/2025 (claude-sonnet-4-2025-05-14), espalhado
   por 11 chamadas em 5 módulos. Trocar de modelo virava caça ao tesouro — e foi assim
   que ficamos duas gerações atrasados sem ninguém perceber.
   AGORA É AQUI E SÓ AQUI. Se for trocar de modelo, troca esta linha.
   Lista de modelos: platform.claude.com/docs/en/models/overview

   14/09/2026 — decisão do Vinicius, depois de 7 rodadas de ajuste numa copy só:
   "cara já passa pra Opus pq fiquei puto". Vale as 11 chamadas do app.
   Conta feita: ~6k tokens de entrada e ~900 de saída por reescrita de copy;
   300 reescritas/mês ≈ US$ 16 no Opus 5 contra US$ 6 no Sonnet 5. A diferença
   não paga uma hora da Hellen refazendo copy, então o critério aqui é qualidade. */
const PX_IA_MODELO = "claude-opus-5";
/* ─── QUEM ESCREVE A COPY (14/09/2026) ───────────────────────────────
   O Vinicius reprovou a copy do Opus 5 no card de piscicultura do Paraguay
   ("O peixe vive dentro da água???") e pediu GPT. A escolha do provedor da COPY
   fica aqui — só a copy, o resto do app continua no Claude.
     "openai"    → Edge Function ask-openai (precisa do secret OPENAI_KEY)
     "anthropic" → Edge Function ask-claude (o de sempre)
   Se a OpenAI falhar (chave não configurada, função não deployada, erro da API),
   `askIA` cai sozinha pro Claude — ninguém fica sem conseguir reescrever copy. */
const PX_IA_PROVEDOR_COPY = "openai";
const PX_IA_MODELO_GPT = "gpt-5.6-sol";
/* Modelo das tarefas mecânicas (traduzir, resumir): não precisa de Opus e roda mais barato. */
const PX_IA_MODELO_RAPIDO = "claude-sonnet-5";
if(typeof window!=="undefined"){ window.PX_IA_MODELO = PX_IA_MODELO; window.PX_IA_MODELO_RAPIDO = PX_IA_MODELO_RAPIDO; }

/* ─── ASK CLAUDE HELPER ─────────────────────────────
   Chama a Edge Function `ask-claude` do Supabase, que faz proxy seguro para
   a API da Anthropic. NUNCA exponha a chave da Anthropic no frontend!

   Uso:
     const data = await askClaude({
       model: PX_IA_MODELO,
       max_tokens: 500,
       system: "Você é...",
       messages: [{role:"user", content:"..."}]
     });
     const text = (data.content||[]).map(b=>b.text||"").join("");

   Requer: Edge Function "ask-claude" deployada no Supabase.
   Veja SUPABASE_EDGE_FUNCTION.md para instruções de deploy. */
async function askClaude({model=PX_IA_MODELO,max_tokens=500,system,messages=[]}){
  const sb=window._sb;
  if(!sb)throw new Error("Supabase client indisponível");
  const body={model,max_tokens,messages};
  if(system)body.system=system;
  const {data,error}=await sb.functions.invoke("ask-claude",{body});
  if(error){
    // Mensagem amigável se a Edge Function ainda não foi deployada
    if(String(error.message||"").includes("Failed to send a request")){
      throw new Error("Pixels IA indisponível: deploy a Edge Function 'ask-claude' no Supabase. Veja SUPABASE_EDGE_FUNCTION.md.");
    }
    // A function devolve o motivo real no corpo (modelo fora do ar, chave inválida,
    // sem crédito...). Sem isto o usuário só via "non-2xx status code". (13/09/2026)
    try{
      const _r=error.context;
      if(_r&&typeof _r.json==="function"){
        const _j=await _r.json();
        const _m=_j&&(_j.error||_j.message);
        if(_m)throw new Error(typeof _m==="string"?_m:(_m.message||JSON.stringify(_m)));
      }
    }catch(_e){ if(_e&&_e.message&&_e.message!=="Unexpected end of JSON input")throw _e; }
    throw error;
  }
  if(data&&data._aviso&&typeof console!=="undefined")console.info("[ask-claude]",data._aviso);
  if(data?.error)throw new Error(data.error);
  return data;
}

/* Contato de verdade pra usar no CTA. Devolve "" quando a empresa nao tem
   telefone cadastrado — e ai a legenda fecha SEM numero, nunca com um inventado.
   O playbook guarda de dois jeitos: lista [{nome,whatsapp}] ou objeto com
   {telefone,whatsapp,...} cheio de string vazia. Os dois caem aqui. */
function _pxContatoUtil(pb, unit){
  try{
    const _limpa=function(v){ return String(v==null?"":v).trim(); };
    // Devolve [{num, quando}] — "quando" é o nome/observação do playbook, usado SÓ
    // pra escolher o número certo. Ele nunca vai pra legenda.
    const _daLista=function(arr){
      if(!Array.isArray(arr)) return [];
      return arr.map(function(c){
        const _tel=_limpa(c&&(c.whatsapp||c.telefone));
        if(!_tel) return null;
        return {num:_tel, quando:_limpa(c&&c.nome)};
      }).filter(Boolean).slice(0,3);
    };
    const _porUn=(pb&&pb.contatos_por_unidade)||{};
    if(unit&&_porUn[unit]){ const _r=_daLista(_porUn[unit]); if(_r.length) return _r; }
    const _c=pb&&pb.contatos;
    if(Array.isArray(_c)){ const _r=_daLista(_c); if(_r.length) return _r; }
    if(_c&&typeof _c==="object"){
      const _tel=_limpa(_c.whatsapp)||_limpa(_c.telefone);
      if(_tel) return [{num:_tel, quando:""}];
    }
    // Sem número: devolve vazio de propósito. Melhor CTA sem número do que o
    // telefone de Castro num post de Toledo — ou um número inventado.
    return [];
  }catch(_){ return []; }
}

/* Coração na cor da marca (pedido do Vinicius, 14/09/2026): em data comemorativa o
   emoji de coração tem que ser o da cor do cliente, não um ❤️ genérico. Lê a cor do
   próprio CLIENTS e escolhe o coração de matiz mais próxima. */
function _pxCoracaoCliente(clientId){
  try{
    const c=(typeof CLIENTS!=="undefined"?CLIENTS:[]).find(function(x){return x&&x.id===clientId;});
    let hex=String((c&&c.color)||"").replace("#","").trim();
    if(hex.length===3) hex=hex[0]+hex[0]+hex[1]+hex[1]+hex[2]+hex[2];
    if(hex.length!==6) return "❤️";
    const r=parseInt(hex.slice(0,2),16)/255, g=parseInt(hex.slice(2,4),16)/255, b=parseInt(hex.slice(4,6),16)/255;
    const mx=Math.max(r,g,b), mn=Math.min(r,g,b), d=mx-mn;
    const l=(mx+mn)/2, sat=d===0?0:d/(1-Math.abs(2*l-1));
    if(sat<0.18) return l<0.5?"🖤":"🤍";           // cinza/preto/branco
    let h=0;
    if(d!==0){
      if(mx===r) h=60*(((g-b)/d)%6);
      else if(mx===g) h=60*(((b-r)/d)+2);
      else h=60*(((r-g)/d)+4);
    }
    if(h<0) h+=360;
    if(h<18||h>=330) return "❤️";                 // vermelho
    if(h<45)  return "🧡";                        // laranja
    if(h<70)  return "💛";                        // amarelo
    if(h<170) return "💚";                        // verde
    if(h<265) return "💙";                        // azul
    return "💜";                                  // roxo/magenta
  }catch(_){ return "❤️"; }
}

/* Regras de CTA e emoji que valem pra TODA legenda do sistema. */
/* ─── LEGENDA NÃO REPETE O TEXTO NA ARTE (Vinicius, 16/09/2026) ────────────────
   "ele fica repetindo a legenda igual o briefing… a legenda não pode ser o mesmo texto do texto
   na arte — falar do mesmo assunto sim, mas não ficar repetindo a mesma coisa."
   A arte já é lida por quem vê o post; a legenda complementa, não copia.
   Três camadas: regra no banco (claude_copy_regras id 39), instrução com as frases da arte
   no prompt (_pxAvisoNaoRepeteArte) e uma trava que confere a resposta e, se repetiu, pede
   uma reescrita só da legenda (_pxDesrepeteLegenda). */
/* ─── ROTEIRO DE FALA — 90s, o cliente grava (Vinicius, 16/09/2026) ─────────────────
   "roteiro é pra nós enviar pro cliente gravar.. faz 90 segundos, porque eles tem que ter uma frase
   de início, um complemento e um final.. não frases jogadas". O formato antigo (Cena N (0–8s) — o que
   aparece. Na tela: "…") virava 6 frases soltas de legenda. Agora é UM discurso em 3 partes.
   Vale pra Avaliação de copys, Gerar briefing e "Transformar em roteiro". Vídeo simples (15–30s,
   sem fala) continua existindo quando o briefing já declara "vídeo simples". */
const PX_ROTEIRO_FALA_FORMATO=
  "• ROTEIRO (vídeo de 90s — o cliente grava)\n"+
  "Cena 1 — Abertura\n(a fala: uma frase de início que prende e apresenta o assunto)\n\n"+
  "Cena 2 — Desenvolvimento\n(a fala: o complemento — explica o assunto com os fatos do card)\n\n"+
  "Cena 3 — Fechamento\n(a fala: o final que amarra a ideia e convida a falar com a empresa)\n";
const PX_ROTEIRO_FALA_REGRAS=
  "REGRAS DO ROTEIRO (é o texto que o CLIENTE vai FALAR olhando pra câmera — a gente manda pra ele gravar):\n"+
  "- 90 segundos falados: de 200 a 240 palavras NO TOTAL.\n"+
  "- As 3 cenas são UM discurso contínuo: início, complemento e final. Cada cena continua a anterior — não são frases soltas.\n"+
  "- Frases completas, do jeito que se fala, na voz da empresa (\"aqui na <marca> a gente…\"). Nada de frase de legenda nem de título de arte.\n"+
  "- PROIBIDO: marcação de tempo (0–8s), \"Na tela:\", \"o que aparece\", instrução de câmera, de gravação ou de edição.\n"+
  "- Não invente número, prazo, garantia nem dado técnico que não esteja no card.\n";
const PX_ROTEIRO_SIMPLES_FORMATO=
  "• ROTEIRO (vídeo simples — 15 a 30s)\nCena 1 — o que aparece\nCena 2 — o que aparece\nCena 3 — o que aparece\n(sem fala, sem marcação de tempo)\n";

function _pxFrasesDaArte(briefTxt){
  const t=String(briefTxt||"")
    .replace(/^[\s•·\-*]*(t[íi]tulo|texto na arte|texto en el arte|frase na arte|frase en el arte|pin no mapa|pin en el mapa|roteiro|l[âa]mina\s*\d+)[^\n]*$/gim,"\n")
    .replace(/\r/g,"");
  return t.split(/(?<=[.!?…])\s+|\n+/).map(function(x){return x.replace(/[|]/g," ").trim();})
    // saudação curta ("Feliz Dia do Gaúcho!") pode e deve se repetir no fecho — só conta frase de 6+ palavras
    .filter(function(x){return x.split(/\s+/).length>=6;});
}
function _pxNorm(x){ return String(x||"").toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g,"").replace(/[^a-z0-9\s]/g," ").replace(/\s+/g," ").trim(); }
/* Devolve as frases da arte que a legenda repetiu (igual, ou 6+ palavras seguidas iguais). */
function _pxLegendaRepeteArte(leg, briefTxt){
  const L=" "+_pxNorm(leg)+" ";
  const rep=[];
  _pxFrasesDaArte(briefTxt).forEach(function(f){
    const w=_pxNorm(f).split(" ");
    if(w.length<4) return;
    if(L.indexOf(" "+w.join(" ")+" ")>=0){ rep.push(f); return; }
    for(let i=0;i+6<=w.length;i++){ if(L.indexOf(" "+w.slice(i,i+6).join(" ")+" ")>=0){ rep.push(f); return; } }
  });
  return rep;
}
function _pxAvisoNaoRepeteArte(briefTxt){
  const fr=_pxFrasesDaArte(briefTxt);
  let u="\n⛔ A LEGENDA NÃO REPETE O TEXTO DA ARTE. Mesmo assunto, sim — mesmas frases, NUNCA. Quem vê o post já leu a arte; a legenda complementa com outras palavras e outro ângulo (outra abertura, outro detalhe, outra construção). Não copie nem parafraseie de perto nenhuma destas frases:\n";
  fr.slice(0,8).forEach(function(f){ u+="- “"+f.slice(0,160)+"”\n"; });
  return fr.length?u:"\n⛔ A LEGENDA NÃO REPETE O TEXTO DA ARTE. Mesmo assunto, sim — mesmas frases, nunca.\n";
}
async function _pxDesrepeteLegenda(leg, briefTxt, py){
  const rep=_pxLegendaRepeteArte(leg, briefTxt);
  if(!rep.length) return leg;
  try{
    const sys="Você corrige legendas de Instagram. Devolva SÓ a legenda corrigida, texto puro, sem aspas, sem comentário. "+(py?"Escreva em espanhol.":"Escreva em português do Brasil.");
    let u="LEGENDA:\n"+leg+"\n\nESTAS FRASES DA LEGENDA ESTÃO IGUAIS AO TEXTO QUE JÁ ESTÁ NA ARTE:\n";
    rep.forEach(function(f){ u+="- “"+f+"”\n"; });
    u+="\nReescreva SÓ esses trechos com outras palavras e outro ângulo, falando do mesmo assunto. Mantenha todo o resto EXATAMENTE igual: as outras frases, os emojis (mesma quantidade e posição), a linha do contato e a linha de hashtags. Mesmo tamanho aproximado.";
    const data=await askIA({model:PX_IA_MODELO,max_tokens:1400,system:sys,messages:[{role:"user",content:u}]});
    let txt=((data&&data.content)||[]).map(function(b){return (b&&b.text)||"";}).join("").trim();
    txt=txt.replace(/^```(?:text)?\s*/i,"").replace(/```\s*$/,"").replace(/^===+\s*LEGENDA\s*===+\s*/i,"").trim();
    if(txt.length<Math.min(60,leg.length*0.5)) return leg;
    return _pxLegendaRepeteArte(txt, briefTxt).length<rep.length ? txt : leg;
  }catch(_){ return leg; }
}

function _pxRegrasLegenda(pb, unit, ehComemorativa, clientId){
  const _cts=_pxContatoUtil(pb, unit);
  const _tem=_cts.length>0;
  let r=ehComemorativa?"\nFECHO DA HOMENAGEM:\n":"\nCTA E CONTATO (obrigatório em toda legenda):\n";
  if(ehComemorativa){
    // 15/09/2026 — a regra dizia "sem CTA" e logo abaixo mandava a linha do telefone.
    // O modelo obedecia as duas e a homenagem saia com "segue à disposição" + número.
    // Data comemorativa NÃO tem contato: `claude/padrao-copy-data-comemorativa-REGRA.md`.
    r+="- Esta é uma homenagem: fecha na saudação da data e para por aí.\n";
    r+="- ⛔ SEM CTA, SEM TELEFONE, SEM “estamos à disposição”, sem convite pra conversar. Nada de contato em data comemorativa.\n";
    return r+_pxRegrasEmoji(ehComemorativa,clientId,false);
  }else{
    // CTA ACOLHEDOR (Vinicius, 15/09/2026): o modelo fechava quase toda legenda em
    // "Solicite seu orçamento" — soa a cobrança. O fecho é convite pra conversa.
    r+="- Feche com um CONVITE ACOLHEDOR, de porta aberta — do tipo “Converse com a gente agora mesmo”, “Fala com a gente, estamos prontos pra te atender”, “Chama no WhatsApp que a gente te ajuda”, “Estamos à disposição pra pensar a melhor solução com você”. Varie entre os posts, nunca repita a mesma frase do post anterior.\n";
    r+="- ⛔ PROIBIDO fechar com orçamento: “Solicite seu orçamento”, “peça um orçamento”, “faça já seu orçamento”, “peça sua proposta/cotação” e qualquer variante. Convite pra CONVERSAR, nunca pedido de compra.\n";
    r+="- O tom é de quem atende, não de quem vende: gentil, próximo, na segunda pessoa (“você”). Sem urgência fabricada (“última chance”, “corre”, “só hoje”) e sem ponto de exclamação em excesso.\n";
    r+="- As legendas antigas que você recebeu como exemplo podem fechar em “Solicite seu orçamento” — era o padrão antigo, está revogado. NÃO copie esse fecho de lá.\n";
  }
  if(_tem){
    r+="- O telefone vem na linha IMEDIATAMENTE abaixo da chamada — um Enter só, SEM linha em branco entre as duas. Chamada e telefone são o mesmo bloco. Assim e SÓ assim:\n";
    r+="    📱 "+_cts[0].num+"\n";
    r+="- NADA além do emoji e do número nessa linha. Sem nome de pessoa, sem “WhatsApp:”, sem observação, sem parênteses explicativos.\n";
    if(_cts.length>1){
      r+="- Há mais de um número cadastrado. Escolha UM, o que faz sentido pro assunto do post, e use só ele:\n";
      for(let i=0;i<_cts.length;i++)
        r+="    · "+_cts[i].num+(_cts[i].quando?("  (quando usar: "+_cts[i].quando+" — esta observação é só pra você escolher, NÃO vai pra legenda)"):"")+"\n";
    }else if(_cts[0].quando){
      r+="- (“"+_cts[0].quando+"” é a anotação do playbook sobre esse número — é só pra você. NÃO escreva isso na legenda.)\n";
    }
    r+="- Não mude um dígito, não invente outro número, site, e-mail nem endereço.\n";
  }else{
    r+="- ⛔ ESTA EMPRESA NÃO TEM TELEFONE CADASTRADO NO PLAYBOOK. Feche o CTA SEM número — ex.: “chama a gente no direct”, “manda uma mensagem pra gente”. NUNCA invente um telefone, e sem o emoji de celular (não há número pra anunciar).\n";
  }
  return r+_pxRegrasEmoji(ehComemorativa,clientId,_tem);
}

/* Bloco de emoji — separado porque data comemorativa sai antes do bloco de contato. */
function _pxRegrasEmoji(ehComemorativa, clientId, _tem){
  let r="";
  // 14/09/2026 — a regra antiga terminava em "se nenhum emoji fizer sentido, não use nenhum".
  // O modelo lia isso como permissão e devolvia legenda seca em toda rodada; o Vinicius cobrou
  // ("vc ainda não começou a utilizar os emojis como eu pedi"). Agora emoji é OBRIGATÓRIO, no
  // lugar que as legendas aprovadas da equipe usam: fim da linha de abertura.
  r+="\nEMOJIS (regra fixa do padrão da agência — OBRIGATÓRIO, não é opcional):\n";
  r+="- TODA legenda leva emoji. Legenda sem nenhum emoji está ERRADA e será recusada.\n";
  r+="- SÃO 2 EMOJIS NA LEGENDA INTEIRA. Nem menos, nem mais.\n";
  r+="- Cada um vai no FIM de uma frase, e tem que ter relação direta com o que AQUELA frase diz. O 1º no fim da linha de abertura; o 2º no fim do parágrafo de fecho. É assim nas legendas aprovadas da agência: “Máquinas em campo e trabalho acontecendo. 🚜”, “Cada detalhe importa. 🛠️💚”, “Segurança hídrica + energia renovável. ✅”, “Essa lavoura não vai depender da chuva esse ano. ☕💧”.\n";
  if(ehComemorativa) r+="- ESTA É DATA COMEMORATIVA: um dos dois emojis é o CORAÇÃO NA COR DA MARCA — "+_pxCoracaoCliente(clientId)+" — no fim da frase de agradecimento. Use exatamente esse coração, não troque por outra cor nem por ❤️ genérico.\n";
  r+="- Se a legenda tiver lista de itens, cada item abre com ✔ ou com um emoji do próprio item (🏗️ 🐷 🐄 ⚙️ 📐) — nesse caso a lista inteira conta como UM dos dois.\n";
  if(_tem) r+="- A linha do telefone leva o 📱 obrigatoriamente. Ele é parte do formato do contato e NÃO entra na conta dos 2.\n";
  r+="- Nunca no meio da frase, nunca dois emojis diferentes seguidos fora dos exemplos acima, nunca na linha de hashtags.\n";
  r+="- Emoji de enfeite, que não tem a ver com o que a frase diz, não entra. Escolher o certo é parte do trabalho — não usar nenhum NÃO é alternativa.\n";
  return r;
}

/* ─── ASK GPT (OpenAI) ───────────────────────────────────────────────
   Mesmo desenho do askClaude: a chave fica SÓ no backend (Edge Function
   ask-openai, secret OPENAI_KEY). Recebe e devolve no formato do askClaude
   ({content:[{text}]}) pra nenhum chamador precisar saber quem escreveu. */
async function askGPT({model=PX_IA_MODELO_GPT,max_tokens=2000,system,messages=[]}){
  const sb=window._sb;
  if(!sb)throw new Error("Supabase client indisponível");
  const msgs=[];
  if(system)msgs.push({role:"system",content:system});
  (messages||[]).forEach(function(m){
    const c=(typeof m.content==="string")?m.content
      :((m.content||[]).map(function(b){return b&&b.text||"";}).join("\n"));
    msgs.push({role:m.role||"user",content:c});
  });
  const {data,error}=await sb.functions.invoke("ask-openai",{body:{model:model,max_tokens:max_tokens,messages:msgs}});
  if(error)throw new Error("Pixels IA (GPT) indisponível: "+(error.message||"erro"));
  if(data&&data.error)throw new Error(String(data.error.message||data.error));
  const txt=(((data||{}).choices||[])[0]||{}).message;
  const out=(txt&&txt.content)||"";
  if(!out)throw new Error("O GPT respondeu vazio.");
  return {content:[{type:"text",text:out}]};
}

/* Porta única da COPY: tenta o provedor escolhido e cai pro Claude se ele falhar. */
async function askIA(opts){
  if(PX_IA_PROVEDOR_COPY==="openai"){
    try{ return await askGPT(Object.assign({},opts,{model:PX_IA_MODELO_GPT})); }
    catch(e){ console.warn("[askIA] OpenAI falhou, usando o Claude:",(e&&e.message)||e); }
  }
  return await askClaude(opts);
}
if(typeof window!=="undefined"){ window.askGPT=askGPT; window.askIA=askIA; }

/* ─── TRADUÇÃO DA COPY DO PARAGUAY PRA CONFERÊNCIA (14/09/2026) ──────
   Pedido do Vinicius: "as copys em espanhol de paraguay tem que ter a tradução
   embaixo pra gente saber se tá bom ou não, pq ninguém aqui fala espanhol".
   É TRADUÇÃO, não revisão: não melhora, não corta, não reescreve — quem lê precisa
   saber exatamente o que está escrito em espanhol antes de aprovar.
   Roda no modelo rápido; traduzir não precisa de Opus. */
/* Assinatura do texto de origem: se a copy for reescrita, o tamanho muda e a tradução
   guardada é considerada velha. Barato e suficiente — não precisa de hash de verdade. */
function pxTraducaoSrc(task){
  const d=_pxHtmlParaTexto((task&&(task.desc||task.description))||"");
  const l=_pxHtmlParaTexto((task&&task.caption)||"");
  return d.length+"|"+l.length;
}
/* Tradução já guardada e AINDA VÁLIDA pra este card (ou null). */
function pxTraducaoSalva(task){
  const tr=task&&(task.traducaoPt||task.traducao_pt);
  if(!tr||typeof tr!=="object") return null;
  if(String(tr.src||"")!==pxTraducaoSrc(task)) return null;   // copy mudou → retraduzir
  return tr;
}
/* Traduz (uma vez) e GRAVA no card. Devolve {briefing,legenda}. */
async function pxTraduzirEGravar(task, setTasks){
  const salva=pxTraducaoSalva(task);
  if(salva) return salva;
  const r=await pxTraduzirParaPt({briefing:(task.desc||task.description||""), legenda:(task.caption||"")});
  const reg={briefing:r.briefing, legenda:r.legenda, at:new Date().toISOString(), src:pxTraducaoSrc(task)};
  try{
    if(typeof setTasks==="function") setTasks(function(p){return p.map(function(x){return x.id===task.id?Object.assign({},x,{traducaoPt:reg}):x;});});
    const sb=(typeof window!=="undefined")?window._sb:null;
    if(sb) sb.from("tasks").update({traducao_pt:reg}).eq("id",task.id).then(function(){},function(){});
  }catch(_){}
  return reg;
}
if(typeof window!=="undefined"){ window.pxTraducaoSalva=pxTraducaoSalva; window.pxTraduzirEGravar=pxTraduzirEGravar; }

async function pxTraduzirParaPt(opts){
  const briefing=_pxHtmlParaTexto((opts&&opts.briefing)||"");
  const legenda =_pxHtmlParaTexto((opts&&opts.legenda)||"");
  if(!briefing&&!legenda) return {briefing:"",legenda:""};
  if(typeof askClaude!=="function") throw new Error("Pixels IA indisponível neste ambiente.");
  const sys="Você traduz do espanhol para o português do Brasil. Tradução FIEL: não reescreva, "+
    "não melhore, não corte e não resuma — a pessoa que vai ler não fala espanhol e precisa saber "+
    "exatamente o que está escrito pra decidir se aprova. Mantenha a quebra de parágrafos, os emojis, "+
    "os números, os telefones e os endereços como estão. HASHTAG NÃO SE TRADUZ: copie igual. "+
    "Nome de produto e nome da marca também ficam como estão. "+
    "Responda EXATAMENTE neste formato, texto puro, sem nada antes nem depois:"+
    "\n===BRIEFING===\n(o briefing traduzido)\n===LEGENDA===\n(a legenda traduzida)";
  let u="BRIEFING (español):\n"+(briefing||"(vazio)")+"\n\n";
  u+="LEGENDA (español):\n"+(legenda||"(vazia)")+"\n";
  const data=await askClaude({model:PX_IA_MODELO_RAPIDO,max_tokens:2200,system:sys,messages:[{role:"user",content:u}]});
  let txt=((data&&data.content)||[]).map(function(b){return b.text||"";}).join("").trim();
  txt=txt.replace(/^[\s>*#=_-]*(BRIEFING|LEGENDA)\s*[:\s>*#=_-]*$/gim,function(_m,p1){return "==="+p1.toUpperCase()+"===";});
  const iB=txt.indexOf("===BRIEFING==="), iL=txt.indexOf("===LEGENDA===");
  let b="", l="";
  if(iB>=0||iL>=0){
    if(iB>=0) b=(iL>iB?txt.slice(iB+14,iL):txt.slice(iB+14)).trim();
    if(iL>=0) l=txt.slice(iL+13).trim();
  }else{ b=txt.trim(); }
  b=b.replace(/^===+\s*/,"").trim(); l=l.replace(/^===+\s*/,"").trim();
  if(b==="(vazio)") b=""; if(l==="(vazia)") l="";
  return {briefing:b, legenda:l};
}
if(typeof window!=="undefined") window.pxTraduzirParaPt = pxTraduzirParaPt;

/* ─── REESCRITA DE COPY PELO CLAUDE ─────────────────────────────────
   Usado pelos botões "Testar nova abordagem" e "Refazer do zero" da
   Avaliação de copys. O card NÃO sai da fila: a copy é reescrita na hora e
   trocada ali mesmo, e a versão anterior fica guardada em task.copyVersoes
   pra poder voltar atrás.

   Antes de escrever, busca o contexto do cliente com a RPC
   claude_contexto_copy: playbook do portal (tom de voz, pilares, chamadas
   aprovadas e PROIBIDAS), foco do mês/trimestre do Planejamento, regras
   aprendidas com o feedback da agência e as copys já aprovadas. */

/* ─── APRENDIZADO POR ESTILO (16/09/2026) ──────────────────────────────────
   Pedido do Vinicius: "foto de obra aprovadas fazem as próximas foto de obra aprender?"
   Antes: a IA via as últimas legendas aprovadas do cliente de QUALQUER tipo, e nenhum
   briefing aprovado (só o gerador de briefing via briefings, por content_type).
   Agora: RPC claude_exemplos_estilo devolve cards APROVADOS/PUBLICADOS do MESMO ESTILO
   (comemorativa · foto_obra · video · carrossel · arte) com BRIEFING e LEGENDA —
   primeiro do mesmo cliente/unidade (tom + estrutura), completando com outras marcas
   (só estrutura). Paraguay só aprende com Paraguay. A régua de estilo é a mesma no banco
   (claude_estilo_card) e aqui (pxEstiloCard). */
function pxEstiloCard(task){
  const id=String((task&&task.id)||""), ti=String((task&&task.title)||""), ct=String((task&&(task.contentType||task.content_type))||"").toLowerCase();
  const tags=Array.isArray(task&&task.tags)?task.tags:[];
  if(/^autocom-/i.test(id)||tags.some(function(t){return /data\s*comemorativa/i.test(String(t||""));})) return "comemorativa";
  if(ct==="foto"||/foto\s*de\s*obra/i.test(ti)) return "foto_obra";
  if(/^(video|video_short|video_feira|video_complexo|reels|corte)/.test(ct)||/(^|\s)(short|shorts|reels?)(\s|$)/i.test(ti)) return "video";
  if(ct==="carrossel") return "carrossel";
  return "arte";
}
const PX_ESTILO_LABEL={comemorativa:"data comemorativa",foto_obra:"foto de obra",video:"vídeo",carrossel:"carrossel",arte:"arte"};
async function pxExemplosEstilo(task,unit){
  const sb=window._sb; if(!sb||!task) return [];
  try{
    const {data,error}=await sb.rpc("claude_exemplos_estilo",{p_client:String(task.client||""),p_unit:String(unit||""),p_estilo:pxEstiloCard(task),p_excluir:String(task.id||""),p_limite:6});
    return (error||!Array.isArray(data))?[]:data;
  }catch(_){ return []; }
}
/* modo: "briefing" | "legenda" | "ambos" */
function _pxBlocoExemplosEstilo(ex,task,modo){
  if(!ex||!ex.length) return "";
  const est=PX_ESTILO_LABEL[pxEstiloCard(task)]||"este estilo";
  const meus=ex.filter(function(e){return e.mesmo_cliente;}), outros=ex.filter(function(e){return !e.mesmo_cliente;});
  const um=function(e,lim){
    let r="--- "+(e.titulo||"")+(e.mesmo_cliente?"":" ("+(e.cliente||"outra marca")+")")+"\n";
    if(modo!=="legenda"&&e.briefing) r+="[BRIEFING]\n"+String(e.briefing).slice(0,lim)+"\n";
    if(modo!=="briefing"&&e.legenda) r+="[LEGENDA]\n"+String(e.legenda).slice(0,lim)+"\n";
    return r;
  };
  let u="";
  if(meus.length){
    u+="✅ "+(modo==="briefing"?"BRIEFINGS":modo==="legenda"?"LEGENDAS":"BRIEFINGS E LEGENDAS")+" DE "+est.toUpperCase()+" JÁ APROVADOS DESTE CLIENTE — é este o padrão que a agência aprova pra esse estilo (estrutura, tamanho e tom). Siga o molde, com o conteúdo DESTE card:\n";
    meus.forEach(function(e){u+=um(e,700);});
    u+="\n";
  }
  if(outros.length){
    u+="✅ "+est.toUpperCase()+" APROVADOS EM OUTRAS MARCAS — use SÓ como referência de ESTRUTURA. Nunca copie frase, abertura ou tom de outra marca:\n";
    outros.forEach(function(e){u+=um(e,420);});
    u+="\n";
  }
  u+="Se algum exemplo acima contrariar as REGRAS APRENDIDAS, valem as REGRAS (os exemplos mais antigos podem ser de antes da regra).\n\n";
  return u;
}

// p_estilo (16/09/2026): COMEMORATIVA SÓ ENSINA COMEMORATIVA — o banco filtra as aprovadas e as
// recusadas pelo estilo do card (comemorativa × todo o resto), pra homenagem não contaminar copy comercial.
async function pxContextoCopy(client, unit, task){
  const sb=window._sb; if(!sb) return null;
  const d=new Date();
  try{
    const {data,error}=await sb.rpc("claude_contexto_copy",{
      p_client:String(client||""), p_unit:String(unit||""),
      p_year:d.getFullYear(), p_month:d.getMonth()+1,
      p_estilo:task?pxEstiloCard(task):null });
    if(error) return null;
    return data||null;
  }catch(_){ return null; }
}

function _pxCtxTxt(v){
  if(v==null) return "";
  if(Array.isArray(v)) return v.map(_pxCtxTxt).filter(Boolean).join(" · ");
  if(typeof v==="object") return Object.keys(v).map(function(k){
    const x=_pxCtxTxt(v[k]); return x?(k+": "+x):""; }).filter(Boolean).join(" | ");
  return String(v).trim();
}
/* TELEFONE COLADO NO CTA (Vinicius, 15/09/2026) — "sem esse espaçamento de enter entre
   telefone e a frase do CTA". A linha do 📱 é a continuação da chamada, no mesmo bloco.
   Vale pra legenda que a IA escreve agora E pras que já estão gravadas com Enter duplo. */
const _PX_RE_TEL_LINHA=/\n[ \t\u00a0]*\n+(?=[ \t\u00a0]*(?:\ud83d\udcf1|\ud83d\udcde|\u260e))/g;
function _pxColaTelefone(txt){
  return String(txt||"").replace(_PX_RE_TEL_LINHA,"\n");
}

function _pxHtmlParaTexto(html){
  return String(html||"")
    .replace(/<br\s*\/?>/gi,"\n").replace(/<\/p>\s*/gi,"\n").replace(/<\/(?:div|li|h[1-6])>/gi,"\n")
    .replace(/<[^>]+>/g,"").replace(/&nbsp;/g," ").replace(/&amp;/g,"&")
    .replace(/&lt;/g,"<").replace(/&gt;/g,">").replace(/&quot;/g,'"').replace(/&#39;/g,"'")
    .replace(/^[ \t\u00a0]+$/gm,"").replace(/[ \t\u00a0]+$/gm,"").replace(/\n{3,}/g,"\n\n")
    .replace(_PX_RE_TEL_LINHA,"\n").trim();
}

function _pxTextoParaHtml(txt){
  const linhas=_pxColaTelefone(txt).split(/\n/);
  let out="";
  for(let i=0;i<linhas.length;i++){
    const l=linhas[i].trim();
    if(!l){ out+="<p>&nbsp;</p>"; continue; }
    // A linha do telefone entra como <br> DENTRO do parágrafo do CTA. Se virasse um <p>
    // próprio ganharia a margem do parágrafo e o buraco voltava — no cartão e na avaliação.
    if(/^(?:\ud83d\udcf1|\ud83d\udcde|\u260e)/.test(l) && /<\/p>$/.test(out) && !/<p>&nbsp;<\/p>$/.test(out)){
      out=out.slice(0,-4)+"<br>"+l+"</p>"; continue;
    }
    // rótulos do briefing (• Título, • Texto na arte, • Roteiro) vão em negrito
    if(/^[•\-]\s*(T[íi]tulo|Texto na arte|Texto en el arte|Roteiro|Gui[óo]n|Pin no mapa|Pin en el mapa|Frase na arte|Frase en el arte|O que precisamos)/i.test(l)){
      out+="<p><strong>"+l.replace(/^[-]\s*/,"• ")+"</strong></p>";
    } else out+="<p>"+l+"</p>";
  }
  return out;
}

/* Devolve {briefing, legenda} em HTML, ou lança erro. */
async function pxReescreverCopy(opts){
  const task=opts&&opts.task; if(!task) throw new Error("Card não informado.");
  if(typeof askClaude!=="function") throw new Error("Pixels IA indisponível neste ambiente.");
  const tipo=String((opts&&opts.tipo)||"ajuste");
  const ehRefazer=tipo==="refazer";
  const ehAjuste=tipo==="ajuste";
  const ehAbord=!ehRefazer&&!ehAjuste;
  // ALVO DO AJUSTE (15/09/2026, Vinicius): muitas vezes só o briefing OU só a legenda está
  // ruim. Reescrever os dois gasta tempo e crédito e ainda mexe no que já estava bom.
  const _alvo=(function(a){return (a==="briefing"||a==="legenda")?a:"ambos";})(String((opts&&opts.alvo)||""));
  const soBrief=_alvo==="briefing", soLeg=_alvo==="legenda";
  const pedido=String((opts&&opts.feedback)||"").trim();
  const cliente=String((opts&&opts.clienteNome)||task.client||"");
  const unit=String(task.bioterUnit||task.bioter_unit||"");
  const py=unit==="paraguay";
  const ct=String(task.contentType||task.content_type||"").toLowerCase();
  const ehVideo=ct==="video"||ct==="video_short"||ct==="reels";
  // FOTO DE OBRA tem briefing proprio (15/09/2026): so o pin do mapa e UMA frase.
  const ehFotoObra=ct==="foto"||/foto\s*de\s*obra/i.test(String(task.title||""));
  const soStory=!!(task.somenteStory||task.somente_story);
  const _tags=Array.isArray(task.tags)?task.tags:[];
  // DUAS provas de comemorativa (14/09/2026): a tag, que humano edita, e o id "autocom-",
  // que só existe em card nascido do calendário de datas comemorativas e não some.
  const ehComemorativa=/^autocom-/i.test(String(task.id||""))
    || _tags.some(function(t){return /data\s*comemorativa/i.test(String(t||""));});

  const ctx=await pxContextoCopy(task.client, unit, task);
  let exEstilo=[]; try{ exEstilo=await pxExemplosEstilo(task,unit); }catch(_){}
  const pb=(ctx&&ctx.playbook)||{};
  const regras=(ctx&&ctx.regras)||[];
  const foco=(ctx&&ctx.foco_do_mes)||[];
  const aprov=(ctx&&ctx.aprovadas)||[];
  const recus=(ctx&&ctx.recusadas)||[];

  const sys="Você escreve copy de redes sociais para empresas do agronegócio brasileiro, na voz de cada marca. "+
    "Escreve como gente que conhece o campo: direto, concreto, sem jargão de marketing e sem frase de efeito vazia. "+
    "Nunca inventa número, cidade, prazo, garantia ou depoimento que não tenha sido informado. "+
    (py?"ESCREVA O QUE VAI NA PEÇA E A LEGENDA EM ESPANHOL (é a unidade do Paraguai). Os rótulos do briefing ficam como estão."
       :"Escreva em português do Brasil.")+
    " Responda EXATAMENTE neste formato, texto puro, sem HTML, sem markdown, sem nada antes nem depois:"+
    // Refazer do zero troca o ASSUNTO — então o nome do cartão também tem que mudar, senão a fila
    // de avaliação fica cheia de card com título de um assunto e copy de outro (14/09/2026).
    // ⛔ COMEMORATIVA NUNCA TROCA DE TÍTULO (Vinicius, 14/09/2026: "não pode mudar o
    // título dos cards de data comemorativa, nenhum, NENHUM"). O assunto é a data.
    // Nem no "refazer do zero" — lá a copy é nova, o nome do cartão continua o mesmo.
    ((ehRefazer&&!ehComemorativa)?"\n===TITULO===\n(o novo nome do cartão: o assunto em 3 a 7 palavras, em português do Brasil mesmo no Paraguay, sem ponto final)":"")+
    (soBrief?"\n===BRIEFING===\n(o briefing aqui — NÃO escreva legenda, ela não vai ser usada)"
     :soLeg?"\n===LEGENDA===\n(a legenda aqui — NÃO escreva briefing, ele não vai ser usado)"
     :"\n===BRIEFING===\n(o briefing aqui)\n===LEGENDA===\n(a legenda aqui)");

  let u="CLIENTE: "+(cliente||"—")+(unit?(" — unidade "+unit):"")+"\n";
  u+="CARD: "+(task.title||"—")+"\n";
  const dt=String(task.publishDate||task.publish_date||"").slice(0,10);
  if(dt) u+="PUBLICA EM: "+dt.slice(8,10)+"/"+dt.slice(5,7)+"/"+dt.slice(0,4)+"\n";
  u+="FORMATO: "+(ehVideo?"vídeo":(ehFotoObra?"foto de obra":(ct||"arte")))+(soStory?" (SOMENTE STORY — não escreva legenda)":"")+"\n\n";

  if(pb.comunicacao) u+="TOM DE VOZ DA MARCA:\n"+_pxCtxTxt(pb.comunicacao)+"\n\n";
  if(pb.pilares&&pb.pilares.length) u+="PILARES DE CONTEÚDO: "+_pxCtxTxt(pb.pilares)+"\n\n";
  if(pb.chamadas_proibidas&&pb.chamadas_proibidas.length)
    u+="⛔ CHAMADAS PROIBIDAS (nunca usar, nem parecido): "+_pxCtxTxt(pb.chamadas_proibidas)+"\n\n";
  if(pb.chamadas_aprovadas&&pb.chamadas_aprovadas.length)
    u+="CHAMADAS APROVADAS: "+_pxCtxTxt(pb.chamadas_aprovadas)+"\n\n";
  if(pb.marcacoes&&pb.marcacoes.length) u+="PERFIS PRA MARCAR / HASHTAGS DA MARCA: "+_pxCtxTxt(pb.marcacoes)+"\n\n";
  if(regras.length){
    u+="REGRAS APRENDIDAS COM O FEEDBACK DA AGÊNCIA (obrigatórias):\n";
    for(let i=0;i<regras.length;i++) u+="- ["+String(regras[i].tipo||"").toUpperCase()+"] "+regras[i].regra+"\n";
    u+="\n";
  }
  if(foco.length){
    u+="FOCO DO MÊS / TRIMESTRE (vem do Planejamento com o cliente):\n";
    for(let i=0;i<Math.min(foco.length,3);i++){
      const f=foco[i]; const partes=[];
      if(f.objetivo) partes.push("objetivo: "+f.objetivo);
      if(_pxCtxTxt(f.produtos_foco)) partes.push("produtos em foco: "+_pxCtxTxt(f.produtos_foco));
      if(_pxCtxTxt(f.campanhas)) partes.push("campanhas: "+_pxCtxTxt(f.campanhas));
      if(_pxCtxTxt(f.sazonalidades)) partes.push("sazonalidade: "+_pxCtxTxt(f.sazonalidades));
      if(partes.length) u+="- "+(f.mes||"?")+"/"+(f.ano||"?")+" — "+partes.join("; ")+"\n";
    }
    u+="\n";
  }
  u+=_pxBlocoExemplosEstilo(exEstilo,task,soBrief?"briefing":soLeg?"legenda":"ambos");
  if(aprov.length){
    u+="COPYS JÁ APROVADAS DESTE CLIENTE (é este o tom que funciona):\n";
    for(let i=0;i<Math.min(aprov.length,8);i++)
      u+="---\n"+_pxHtmlParaTexto(aprov[i].legenda).slice(0,700)+"\n";
    u+="\n";
  }
  if(recus.length){
    u+="COPYS RECUSADAS E O MOTIVO (não repetir o erro):\n";
    for(let i=0;i<Math.min(recus.length,5);i++)
      if(recus[i].feedback) u+="- "+(recus[i].titulo||"")+": "+recus[i].feedback+"\n";
    u+="\n";
  }

  /* ── O QUE AS OUTRAS MARCAS JÁ ESTÃO PUBLICANDO NA MESMA DATA (14/09/2026) ──
     Sem isto a IA não tinha como saber que estava repetindo: as 4 copys de Dia do
     Gaúcho (Acreforte, Clem, Construschorr e VetService) saíram idênticas, palavra
     por palavra. Quem monta essa lista é quem chama (o app tem todos os cards em
     memória); aqui só entra no prompt como "não repetir". */
  const _irmaos=Array.isArray(opts&&opts.irmaos)?opts.irmaos.filter(function(x){return x&&x.texto;}):[];
  if(_irmaos.length){
    u+="⛔ MESMA DATA, OUTRAS MARCAS — O TEXTO ABAIXO JÁ ESTÁ ESCRITO ASSIM EM OUTRO CLIENTE.\n";
    u+="CADA COPY É ÚNICA: não repita abertura, frase, imagem nem estrutura destes. Escreva algo que só faça sentido para ESTE cliente e para o público DELE.\n";
    for(let i=0;i<Math.min(_irmaos.length,6);i++)
      u+="--- "+(_irmaos[i].marca||"outra marca")+":\n"+String(_irmaos[i].texto||"").slice(0,420)+"\n";
    u+="\n";
  }

  /* ── ASSUNTOS JÁ AGENDADOS PRA ESTE CLIENTE (14/09/2026) ──
     Só importa no "refazer do zero", que escolhe assunto novo: sem esta lista ele
     podia escolher um assunto que já está marcado pra outra semana do mesmo cliente
     e o calendário ficava com dois posts do mesmo tema. */
  const _ocupados=Array.isArray(opts&&opts.assuntosOcupados)?opts.assuntosOcupados.filter(Boolean):[];
  if(ehRefazer&&_ocupados.length){
    u+="ASSUNTOS JÁ AGENDADOS PARA ESTE CLIENTE (não escolha nenhum destes, nem variação deles):\n";
    for(let i=0;i<Math.min(_ocupados.length,40);i++) u+="- "+String(_ocupados[i]).slice(0,110)+"\n";
    u+="\n";
  }

  // ── O que já foi pedido NESTE card (copyVersoes) ──────────────────────
  // Sem isto cada rodada começa do zero: na 7ª versão ele repetia erro apontado
  // na 3ª, porque só recebia o feedback que acabara de ser digitado.
  const _vs=Array.isArray(task.copyVersoes)?task.copyVersoes:(Array.isArray(task.copy_versoes)?task.copy_versoes:[]);
  const _pedidosAnteriores=_vs.map(function(v){return String((v&&v.feedback)||"").trim();})
                              .filter(Boolean);
  if(_pedidosAnteriores.length){
    u+="AJUSTES JÁ PEDIDOS NESTE MESMO CARD (do mais antigo pro mais recente) — NENHUM desses erros pode voltar:\n";
    for(let i=0;i<Math.min(_pedidosAnteriores.length,8);i++)
      u+=(i+1)+". "+_pedidosAnteriores[i]+"\n";
    u+="\n";
  }
  if(_vs.length>1){
    const _ant=_vs[_vs.length-1];
    const _antTxt=_pxHtmlParaTexto((_ant&&_ant.legenda)||"");
    if(_antTxt) u+="VERSÃO ANTERIOR (a que foi recusada agora) — não repita as frases dela:\n"+_antTxt.slice(0,600)+"\n\n";
  }

  u+="VERSÃO ATUAL — BRIEFING:\n"+(_pxHtmlParaTexto(task.desc||task.description)||"(vazio)")+"\n\n";
  u+="VERSÃO ATUAL — LEGENDA:\n"+(_pxHtmlParaTexto(task.caption)||"(vazia)")+"\n\n";

  u+=ehAjuste
    ? ("TAREFA: reescreva a copy aplicando o que a agência pediu abaixo.\n"+
       "- MANTENHA o assunto do card, a não ser que o pedido diga explicitamente pra mudar de assunto.\n"+
       "- MANTENHA o que não foi criticado. Não reescreva por reescrever.\n"+
       "- Não repita as frases da versão atual naquilo que foi criticado.\n")
    : ehAbord
    ? "TAREFA: mantenha EXATAMENTE o mesmo assunto e reescreva com OUTRA ABORDAGEM — outro ângulo, outro jeito de abrir, outra construção. Não repita as frases da versão atual.\n"
    : "TAREFA: esqueça o assunto da versão atual. Escreva uma copy NOVA, de outro assunto que faça sentido para este cliente neste mês.\n";
  u+=pedido?("O QUE A AGÊNCIA PEDIU: "+pedido+"\n"):"A agência não deu direção — escolha você o melhor caminho, diferente do atual.\n";
  if(soBrief) u+="⚠️ MEXA SÓ NO BRIEFING. A legenda atual está aprovada e continua exatamente como está — não escreva legenda. O briefing novo tem que continuar combinando com ela.\n";
  if(soLeg)   u+="⚠️ MEXA SÓ NA LEGENDA. O briefing atual está aprovado e continua exatamente como está — não escreva briefing. A legenda nova tem que continuar conversando com esse briefing.\n";

  if(ehComemorativa){
    u+="\n⚠️ ESTE CARD É DATA COMEMORATIVA. É HOMENAGEM, NÃO É POST DE VENDA.\n";
    u+="- O Título é a própria saudação da data: “Feliz Dia do Cliente!”, “Feliz Dia do Gaúcho!”, “Feliz Dia do Agrônomo!”. Nada de headline criativa nem frase de efeito.\n";
    u+="- PROIBIDO storytelling, cena inventada ou micro-história (ex.: “TEM CLIENTE QUE LIGA PRA SABER SE CHOVEU NA OBRA”). Fora do cabível numa arte de homenagem.\n";
    u+="- O conteúdo é agradecimento e reconhecimento: família, confiança, parceria, “vocês fazem parte da nossa história”.\n";
    u+="- Sem falar de produto, serviço, garantia, prazo ou preço. O fecho é de disposição, não de venda.\n";
    if(!soLeg){
      u+="\nFORMATO DO BRIEFING (obrigatório, só estas seções):\n";
      u+="• TÍTULO"+"\n(só a saudação da data, em caixa alta)\n\n• TEXTO NA ARTE"+
        "\n(curto, 180 a 340 caracteres: a linha da data em caixa alta, linha em branco, 2 a 3 frases de agradecimento, linha em branco, a saudação de fecho. NÃO repita o título aqui.)\n";
    }
    if(!soBrief){
      /* CURTA e SEM CONTATO (Vinicius, 15/09/2026) — mesmo formato do botão "Ajustar legenda"
         do cartão. Antes pedia 280–560 e ainda uma "linha do CTA com o contato" numa peça que
         a regra proibia ter CTA. Os dois caminhos de copy agora dizem a mesma coisa. */
      u+="\nFORMATO DA LEGENDA — CURTA: 150 a 300 caracteres NO TOTAL, três blocos separados por linha em branco: (1) uma frase de reconhecimento com emoji no fim; (2) uma frase de homenagem citando a marca, dizendo que essa gente faz parte da história dela; (3) a saudação da data. Depois, SÓ a linha de hashtags — no máximo 3. ⛔ Sem telefone, sem “segue à disposição”, sem linha de data em caixa alta.";
      u+=_pxRegrasLegenda(pb,unit,true,task.client);
      if(soStory) u+="\nESTE CARD É SOMENTE STORY: devolva a legenda vazia.";
    }
  }else if(ehFotoObra){
    // FOTO DE OBRA (15/09/2026, Vinicius): a arte JA EXISTE — e a foto da obra entregue.
    // O briefing so diz a cidade do pin e a frase que vai estampada. Nada de headline,
    // apoio, fecho, laminas nem assinatura de data.
    u+="\n⚠️ ESTE CARD É FOTO DE OBRA. A arte é a PRÓPRIA FOTO da obra entregue, não um layout de texto.\n";
    u+="- O briefing tem só DUAS linhas: a cidade que vai no pin do mapa e UMA frase pra estampar na foto.\n";
    u+="- A cidade/UF sai do que a equipe já escreveu no card (briefing atual, título ou comentários). NUNCA invente cidade.\n";
    u+="- PROIBIDO título criativo, headline, texto de apoio, fecho, storytelling, lâminas e assinatura de data.\n";
    if(!soLeg){
      u+="\nFORMATO DO BRIEFING (obrigatório, só estas seções):\n";
      u+="• Pin no mapa\n(Cidade/UF — só isso)\n\n• Frase na arte\n"+
         "(UMA frase só, curta — 45 a 90 caracteres — estilo CTA, com o benefício principal do produto que aparece na foto. "+
         "Sem segunda frase, sem subtítulo, sem explicação depois.)\n";
    }
    if(!soBrief){
      u+="\nFORMATO DA LEGENDA: 400 a 750 caracteres, em blocos separados por linha em branco — abertura, o que foi entregue nesta obra, a marca entra na história, fecho com CTA e contato, e a linha de hashtags — NO MÁXIMO 5 HASHTAGS, é o limite do Instagram.";
      /* Mesmo aperto do botão "Gerar/Ajustar legenda" (Vinicius, 15/09/2026). */
      u+="\n- A legenda tem que NOMEAR O PRODUTO da foto (lagoa de piscicultura, lagoa de estabilização, cisterna inflada, ETA, biodigestor, geomembrana, piso vazado…) e dizer o BENEFÍCIO PRINCIPAL dele — o mesmo da “Frase na arte”.";
      u+="\n- ⛔ Nada de “cada etapa da implantação importa”, “estrutura adequada às necessidades da produção”, “infraestrutura pensada para aquilo que realmente importa”. Se serve pra qualquer obra, está genérica.";
      u+=_pxRegrasLegenda(pb,unit,false,task.client);
      if(soStory) u+="\nESTE CARD É SOMENTE STORY: devolva a legenda como string vazia.";
    }
  }else{
  if(!soLeg){
  u+="\nFORMATO DO BRIEFING (obrigatório, só estas seções):\n";
  u+=ehVideo
    ? (/v[íi]deo simples/i.test(_pxHtmlParaTexto(task.desc||task.description)) ? PX_ROTEIRO_SIMPLES_FORMATO : (PX_ROTEIRO_FALA_FORMATO+"\n"+PX_ROTEIRO_FALA_REGRAS))
    : ("• TÍTULO"+"\n(a headline que vai na peça, em caixa alta)\n\n• TEXTO NA ARTE"+
       "\n(⚠️ NÃO REPITA O TÍTULO AQUI — ele já está na arte, repetir faz o colaborador ler a mesma coisa duas vezes. "+
       "Comece direto pelo apoio: 2 frases que desenvolvem a ideia, linha em branco, fecho — 260 a 480 caracteres. "+
       "Se for carrossel, no lugar disso use “Lâmina 1 — …” até no máximo “Lâmina 5 — …”, sendo a 5 o CTA.)\n");
  }
  if(!soBrief){
  u+="\nFORMATO DA LEGENDA: 400 a 750 caracteres, em blocos separados por linha em branco — abertura, desenvolvimento, a marca entra na história, fecho com CTA e contato, e a linha de hashtags — NO MÁXIMO 5 HASHTAGS, é o limite do Instagram.";
  u+=_pxRegrasLegenda(pb,unit,false,task.client);
  if(soStory) u+="\nESTE CARD É SOMENTE STORY: devolva a legenda como string vazia.";
  }
  }

  if(!soBrief&&!soStory) u+=soLeg?_pxAvisoNaoRepeteArte(_pxHtmlParaTexto(task.desc||task.description)):"\n⛔ A LEGENDA NÃO REPETE O TEXTO DA ARTE que você escreveu no briefing. Mesmo assunto, sim — mesmas frases, nunca. A legenda complementa com outras palavras e outro ângulo.\n";
  const data=await askIA({model:PX_IA_MODELO,max_tokens:3600,system:sys,messages:[{role:"user",content:u}]});
  let txt=((data&&data.content)||[]).map(function(b){return b.text||"";}).join("").trim();
  txt=txt.replace(/^```(?:json|text)?\s*/i,"").replace(/```\s*$/,"").trim();
  // Aceita ===BRIEFING===, ###BRIEFING###, **BRIEFING**, BRIEFING: etc. Normaliza tudo antes de cortar.
  txt=txt.replace(/^[\s>*#=_-]*(TITULO|T\u00cdTULO|BRIEFING|LEGENDA)\s*(DA COPY|DO CARD)?\s*[:\s>*#=_-]*$/gim,function(_m,p1){return "===" + (p1.toUpperCase()==="T\u00cdTULO"?"TITULO":p1.toUpperCase()) + "===";});
  let brief="",leg="",titulo="";
  const iT=txt.indexOf("===TITULO===");
  const iB=txt.indexOf("===BRIEFING==="), iL=txt.indexOf("===LEGENDA===");
  if(iT>=0&&iB>iT){ titulo=txt.slice(iT+12,iB).trim().replace(/^===+\s*/,"").replace(/^["\u201c]|["\u201d]$/g,"").replace(/\.$/,"").trim(); }
  if(iB>=0||iL>=0){
    if(iB>=0) brief=(iL>iB?txt.slice(iB+14,iL):txt.slice(iB+14)).trim();
    else brief=txt.slice(0,iL).trim();
    if(iL>=0) leg=txt.slice(iL+13).trim();
  }else{
    // Ultimo recurso: se veio JSON (formato antigo) aproveita; senao trata tudo como briefing.
    const a=txt.indexOf("{"), z=txt.lastIndexOf("}");
    let ok=false;
    if(a>=0&&z>a){ try{ const o=JSON.parse(txt.slice(a,z+1)); brief=String(o.briefing||"").trim(); leg=String(o.legenda||"").trim(); ok=!!brief; }catch(_){} }
    if(!ok){ brief=txt.trim(); leg=""; }
  }
  brief=brief.replace(/^===+\s*/,"").trim();
  leg=leg.replace(/^===+\s*/,"").trim();
  // TRAVA: legenda que repete o texto da arte volta pra reescrever (só os trechos repetidos)
  if(leg&&!soBrief&&!soStory){ leg=await _pxDesrepeteLegenda(leg, soLeg?_pxHtmlParaTexto(task.desc||task.description):(brief||_pxHtmlParaTexto(task.desc||task.description)), py); }
  const _tituloOk=(ehRefazer&&!ehComemorativa&&titulo&&titulo.length<=90)?titulo:"";
  // AJUSTE PARCIAL: o lado que não foi pedido volta IGUAL ao que já estava no card.
  if(soLeg){
    if(!leg&&brief) leg=brief;            // veio tudo num bloco só: é a legenda
    if(!leg) throw new Error("A IA respondeu vazio. Tente de novo.");
    return { briefing:String(task.desc||task.description||""),
             legenda: soStory?"":_pxTextoParaHtml(leg),
             titulo:"" };
  }
  if(!brief) throw new Error("A IA respondeu vazio. Tente de novo.");
  if(soBrief) return { briefing:_pxTextoParaHtml(brief),
                       legenda:String(task.caption||""),
                       titulo:_tituloOk };
  return { briefing:_pxTextoParaHtml(brief),
           legenda: soStory?"":_pxTextoParaHtml(leg),
           titulo:_tituloOk };
}


/* ─── GERAR LEGENDA DO ZERO (botão "Gerar legenda" da aba Legenda) ───────
   Nasceu de Foto de obra e Short: são os cards que não dá pra automatizar,
   porque dependem da Hellen subir o arquivo. O botão fica em TODO card — quem
   já tem legenda simplesmente não usa.

   Ela escreve um briefing curto (produto, cidade, um dado) e a IA devolve 3
   opções escritas no padrão daquela empresa: tom de voz do playbook, chamadas
   proibidas, regras aprendidas com o feedback da agência, foco do mês e as
   legendas JÁ APROVADAS como referência de estilo.

   Regra dura: não inventa número, cidade, prazo, garantia nem depoimento que
   não esteja no briefing que ela escreveu. */

/* Legendas aprovadas de cards do MESMO tipo (outras "Foto de obra" do mesmo
   cliente, por exemplo). Molde muito melhor do que uma legenda de arte comum. */
async function pxLegendasDoMesmoTipo(client,unit,titulo,excluirId){
  const sb=window._sb; if(!sb||!client) return [];
  const t=String(titulo||"").toLowerCase();
  let chave="";
  if(/foto\s*de\s*obra/.test(t)) chave="foto de obra";
  else if(/\bshort\b|\bshorts\b/.test(t)) chave="short";
  else {
    // usa as 2 primeiras palavras significativas do título ("Folder Linha X" -> "folder linha")
    const _p=t.replace(/[^0-9a-zà-ú\s]/gi," ").split(/\s+/).filter(function(w){return w.length>2;});
    chave=_p.slice(0,2).join(" ");
  }
  if(chave.length<3) return [];
  try{
    // caption vazia vem como '' (nao NULL) na maioria dos cards — filtrar so por
    // "is not null" enchia o limite de linhas vazias e descartava as boas.
    let q=sb.from("tasks").select("title,caption,publish_date,status")
      .eq("client",client)
      .ilike("title","%"+chave+"%")
      .is("deleted_at",null)
      .not("caption","is",null)
      .neq("caption","")
      .order("publish_date",{ascending:false,nullsFirst:false})
      .limit(20);
    if(unit) q=q.eq("bioter_unit",unit);
    if(excluirId) q=q.neq("id",String(excluirId));
    const {data,error}=await q;
    if(error||!Array.isArray(data)) return [];
    return data.filter(function(r){
      return r && _pxHtmlParaTexto(r.caption).length>60;
    }).slice(0,4);
  }catch(_){ return []; }
}

/* Devolve um array com 3 legendas em TEXTO PURO (quem chama converte pra HTML). */
async function pxGerarLegendas(opts){
  const task=(opts&&opts.task)||null;
  if(!task) throw new Error("Card não informado.");
  if(typeof askClaude!=="function") throw new Error("Pixels IA indisponível neste ambiente.");
  const briefing=String((opts&&opts.briefing)||"").trim();
  const modo=String((opts&&opts.modo)||"gerar")==="alterar"?"alterar":"gerar";
  const legAtual=_pxHtmlParaTexto((opts&&opts.legendaAtual)||"");
  const historico=Array.isArray(opts&&opts.historico)?opts.historico:[];
  // QUANTAS LEGENDAS (15/09/2026): o botão da aba Legenda pede 3 pra escolher; o
  // "briefing + legenda" da aba Briefing pede 1 — não faz sentido gastar o triplo
  // de saída pra oferecer escolha num fluxo que já está mostrando a proposta.
  const quantas=Math.max(1,Math.min(3,parseInt((opts&&opts.quantas)||3,10)||3));
  if(briefing.length<3) throw new Error(modo==="alterar"
    ? "Escreva o que precisa ajustar antes de gerar."
    : "Escreva um briefing curto antes de gerar (produto, cidade, ou o que aparece na foto).");
  if(modo==="alterar"&&legAtual.length<20) throw new Error("Este card ainda não tem legenda pra ajustar.");

  const cliente=String((opts&&opts.clienteNome)||task.client||"");
  const unit=String(task.bioterUnit||task.bioter_unit||"");
  const py=unit==="paraguay";
  const ct=String(task.contentType||task.content_type||"").toLowerCase();
  const titulo=String(task.title||"");
  const ehVideo=/^(video|video_short|reels|corte_video|video_basico|video_dinamico)$/.test(ct)||/short|reel|v[íi]deo/i.test(titulo);
  const ehFotoObra=/foto\s*de\s*obra/i.test(titulo);
  const soStory=!!(task.somenteStory||task.somente_story);
  const _tags=Array.isArray(task.tags)?task.tags:[];
  // DUAS provas de comemorativa (14/09/2026): a tag, que humano edita, e o id "autocom-",
  // que só existe em card nascido do calendário de datas comemorativas e não some.
  const ehComemorativa=/^autocom-/i.test(String(task.id||""))
    || _tags.some(function(t){return /data\s*comemorativa/i.test(String(t||""));});

  const ctx=await pxContextoCopy(task.client,unit,task);
  const pb=(ctx&&ctx.playbook)||{};
  const regras=(ctx&&ctx.regras)||[];
  const foco=(ctx&&ctx.foco_do_mes)||[];
  const aprov=(ctx&&ctx.aprovadas)||[];
  const recus=(ctx&&ctx.recusadas)||[];
  let mesmoTipo=[];
  let exEstilo=[]; try{ exEstilo=await pxExemplosEstilo(task,unit); }catch(_){}
  // (16/09/2026) só cai no "mesmo título" antigo se não houver nenhum aprovado do mesmo estilo
  if(!exEstilo.length){ try{ mesmoTipo=await pxLegendasDoMesmoTipo(task.client,unit,titulo,task.id); }catch(_){} }

  const sys="Você escreve legendas de Instagram para empresas do agronegócio e da construção no Brasil, "+
    "sempre na voz da marca que te passarem. Escreve como gente que conhece o campo e a obra: direto, "+
    "concreto, sem jargão de marketing e sem frase de efeito vazia. "+
    "REGRA MAIS IMPORTANTE: você só pode usar os fatos do BRIEFING. Nunca invente número, medida, cidade, "+
    "prazo, preço, garantia, nome de cliente nem depoimento que não esteja escrito ali. Se faltar dado, "+
    "escreva a legenda sem ele em vez de preencher com suposição. "+
    (py?"ESCREVA AS TRÊS LEGENDAS EM ESPANHOL (é a unidade do Paraguai)."
       :"Escreva em português do Brasil.")+
    (modo==="alterar"?"Você está AJUSTANDO uma legenda que já existe: mexa só no que foi criticado e devolva o texto inteiro. ":"")+
    "\nResponda EXATAMENTE neste formato, texto puro, sem markdown, sem comentário antes nem depois:"+
    (quantas===1?"\n===OPCAO 1===\n(a legenda)"
     :quantas===2?"\n===OPCAO 1===\n(legenda)\n===OPCAO 2===\n(legenda)"
     :"\n===OPCAO 1===\n(legenda)\n===OPCAO 2===\n(legenda)\n===OPCAO 3===\n(legenda)");

  let u="CLIENTE: "+(cliente||"—")+(unit?(" — unidade "+unit):"")+"\n";
  u+="CARD: "+(titulo||"—")+"\n";
  const dt=String(task.publishDate||task.publish_date||"").slice(0,10);
  if(dt) u+="PUBLICA EM: "+dt.slice(8,10)+"/"+dt.slice(5,7)+"/"+dt.slice(0,4)+"\n";
  u+="FORMATO: "+(ehVideo?"vídeo curto (reels/short)":(ehFotoObra?"foto de obra":(ct||"arte")))+"\n\n";

  if(modo==="alterar"){
    u+="════ LEGENDA ATUAL (é esta que você vai ajustar) ════\n"+legAtual+"\n\n";
    u+="════ O QUE PRECISA AJUSTAR ════\n"+briefing+"\n\n";
    if(historico.length){
      u+="AJUSTES JÁ PEDIDOS NESTA MESMA RODADA — não repita nenhum desses erros:\n";
      for(let i=0;i<Math.min(historico.length,6);i++){
        const _f=String(historico[i]||"").trim(); if(_f) u+="- "+_f+"\n";
      }
      u+="\n";
    }
  }else{
    u+="════ BRIEFING QUE A AGÊNCIA ESCREVEU (única fonte de fatos) ════\n"+briefing+"\n\n";
    if(historico.length){
      u+="O QUE JÁ FOI RECUSADO NESTA RODADA — não repita:\n";
      for(let i=0;i<Math.min(historico.length,6);i++){
        const _f=String(historico[i]||"").trim(); if(_f) u+="- "+_f+"\n";
      }
      u+="\n";
    }
  }

  if(pb.sobre) u+="SOBRE A EMPRESA:\n"+_pxCtxTxt(pb.sobre).slice(0,900)+"\n\n";
  if(pb.comunicacao) u+="TOM DE VOZ DA MARCA:\n"+_pxCtxTxt(pb.comunicacao)+"\n\n";
  if(pb.pilares&&pb.pilares.length) u+="PILARES DE CONTEÚDO: "+_pxCtxTxt(pb.pilares)+"\n\n";
  if(pb.chamadas_proibidas&&pb.chamadas_proibidas.length)
    u+="⛔ CHAMADAS PROIBIDAS (nunca usar, nem parecido): "+_pxCtxTxt(pb.chamadas_proibidas)+"\n\n";
  if(pb.chamadas_aprovadas&&pb.chamadas_aprovadas.length)
    u+="CHAMADAS APROVADAS: "+_pxCtxTxt(pb.chamadas_aprovadas)+"\n\n";
  if(pb.marcacoes&&pb.marcacoes.length) u+="PERFIS PRA MARCAR / HASHTAGS DA MARCA: "+_pxCtxTxt(pb.marcacoes)+"\n\n";
  if(regras.length){
    u+="REGRAS APRENDIDAS COM O FEEDBACK DA AGÊNCIA (obrigatórias):\n";
    for(let i=0;i<regras.length;i++) u+="- ["+String(regras[i].tipo||"").toUpperCase()+"] "+regras[i].regra+"\n";
    u+="\n";
  }
  if(foco.length){
    u+="FOCO DO MÊS / TRIMESTRE (vem do Planejamento com o cliente):\n";
    for(let i=0;i<Math.min(foco.length,2);i++){
      const f=foco[i]; const partes=[];
      if(f.objetivo) partes.push("objetivo: "+f.objetivo);
      if(_pxCtxTxt(f.produtos_foco)) partes.push("produtos em foco: "+_pxCtxTxt(f.produtos_foco));
      if(_pxCtxTxt(f.campanhas)) partes.push("campanhas: "+_pxCtxTxt(f.campanhas));
      if(partes.length) u+="- "+(f.mes||"?")+"/"+(f.ano||"?")+" — "+partes.join("; ")+"\n";
    }
    u+="\n";
  }
  u+=_pxBlocoExemplosEstilo(exEstilo,task,"legenda");
  if(mesmoTipo.length){
    u+="LEGENDAS DE CARDS DO MESMO TIPO (\""+titulo+"\") JÁ PUBLICADOS — COPIE A ESTRUTURA, NÃO O CONTEÚDO:\n";
    for(let i=0;i<mesmoTipo.length;i++)
      u+="---\n"+_pxHtmlParaTexto(mesmoTipo[i].caption).slice(0,650)+"\n";
    u+="\n";
  }
  if(aprov.length){
    u+="OUTRAS LEGENDAS JÁ APROVADAS DESTE CLIENTE (é este o tom que funciona):\n";
    for(let i=0;i<Math.min(aprov.length,8);i++)
      u+="---\n"+_pxHtmlParaTexto(aprov[i].legenda).slice(0,600)+"\n";
    u+="\n";
  }
  if(recus.length){
    u+="LEGENDAS RECUSADAS E O MOTIVO (não repetir o erro):\n";
    for(let i=0;i<Math.min(recus.length,5);i++)
      if(recus[i].feedback) u+="- "+(recus[i].titulo||"")+": "+recus[i].feedback+"\n";
    u+="\n";
  }

  if(modo==="alterar"){
    u+="TAREFA: reescreva a LEGENDA ATUAL aplicando o ajuste pedido"+(quantas>1?(", em "+quantas+" versões"):"")+".\n";
    u+="- MANTENHA tudo que não foi criticado, com as mesmas palavras. Não reescreva o que já está bom.\n";
    u+="- Não invente dado novo pra preencher o que foi tirado.\n";
    if(quantas>1) u+="- As "+quantas+" versões corrigem a MESMA coisa — mas são REESCRITAS diferentes, não a mesma frase com sinônimo trocado: abertura diferente, ordem das frases diferente. Assunto é um só.\n";
    u+="- Devolva a legenda INTEIRA já corrigida, nunca só o pedaço que mudou.\n";
  }else{
    if(quantas===1){
      u+="TAREFA: escreva A LEGENDA deste post a partir do briefing acima.\n";
    }else{
      u+="TAREFA: escreva "+quantas+" LEGENDAS DIFERENTES para este post, todas a partir do mesmo briefing.\n";
      u+="Elas precisam ser caminhos de verdade diferentes (abertura diferente, ângulo diferente), não a mesma legenda com sinônimo trocado.\n";
    }
  }
  if(ehFotoObra){
    /* NOME DO PRODUTO + BENEFÍCIO (Vinicius, 15/09/2026, Terra Boa/PR): a legenda vinha
       genérica — "cada etapa da implantação importa", "infraestrutura pensada para aquilo
       que realmente importa" — e o benefício que estava na Frase na arte não aparecia.
       Regra 38 de `claude_copy_regras` diz o mesmo; aqui fica o ramo específico. */
    u+="É uma FOTO DE OBRA: o post mostra serviço entregue. Fale do que foi feito e de onde, com orgulho e sem exagero. Nada de promessa nem número que não esteja no briefing.\n";
    u+="- DIGA O NOME DO PRODUTO com todas as letras (lagoa de piscicultura, lagoa de estabilização, cisterna inflada, ETA, biodigestor, geomembrana, piso vazado…). “obra”, “estrutura” e “infraestrutura” sozinhos não valem.\n";
    u+="- DIGA O BENEFÍCIO PRINCIPAL desse produto, concreto — o MESMO que está na “Frase na arte” do briefing (reduzir perda de água, estanqueidade, manejo de dejetos, sanidade, durabilidade…).\n";
    u+="- ⛔ PROIBIDA frase de enchimento que serve pra qualquer obra: “cada etapa da implantação importa”, “estrutura adequada às necessidades da produção”, “infraestrutura pensada para aquilo que realmente importa”, “colocar a atividade para funcionar”, “mais uma obra entregue”.\n";
    u+="- TESTE antes de devolver: se dá pra trocar o produto por outro da empresa e o texto continuar fazendo sentido, está genérica — reescreva.\n";
  }
  if(ehVideo&&!ehFotoObra) u+="É um VÍDEO CURTO: a legenda complementa o vídeo, não narra cena por cena. Primeira linha precisa segurar quem está passando o feed.\n";
  if(ehComemorativa){
    u+="É DATA COMEMORATIVA: é homenagem, não é post de venda. Sem CTA, sem telefone, sem falar de produto, prazo ou garantia.\n";
    /* CURTA (Vinicius, 15/09/2026): "ficou um monte de coisa e tudo parecida, deixa menor".
       Era 280–560 e ainda mandava linha de CTA com contato — saia um post de venda fantasiado
       de homenagem. Agora é o formato do padrão: agradecimento, homenagem, saudação. */
    u+="\nFORMATO DE CADA LEGENDA — CURTA: 150 a 300 caracteres NO TOTAL, três blocos separados por linha em branco:\n";
    u+="  1) uma frase de reconhecimento, com emoji no fim;\n";
    u+="  2) uma frase de homenagem citando a marca — tem que dizer que essa gente faz parte da história da marca;\n";
    u+="  3) a saudação da data (“Feliz Dia de X!”).\n";
    u+="Depois dos três blocos, SÓ a linha de hashtags: no máximo 3, e nenhuma linha a mais.\n";
    u+="⛔ NÃO ESCREVA: telefone, “segue à disposição”, “conte com a gente”, linha de data em caixa alta, produto, número, promessa. Legenda de homenagem que passa de 300 caracteres está errada.\n";
  }else{
    u+="\nFORMATO DE CADA LEGENDA: 400 a 750 caracteres, em blocos separados por linha em branco — abertura, desenvolvimento, a marca entra na história, fecho com CTA e contato, e a linha de hashtags. NO MÁXIMO 5 HASHTAGS, é o limite do Instagram.";
  }
  /* AS OPÇÕES TÊM QUE SER DIFERENTES DE VERDADE (Vinicius, 15/09/2026):
     "ficou um monte de coisa e tudo parecida, uma completamente distinta da outra".
     As três vinham com a mesma abertura e sinônimo trocado no meio — escolher entre elas
     não era escolha nenhuma. A regra vale pros dois modos (gerar e ajustar). */
  if(quantas>1){
    u+="\n\nAS "+quantas+" OPÇÕES SÃO CAMINHOS DIFERENTES, NÃO VARIAÇÕES:\n";
    u+="- Cada uma começa de um jeito. ⛔ PROIBIDO duas opções começarem com as mesmas 3 palavras.\n";
    u+="- Cada uma entra por um ângulo diferente"+(ehComemorativa
        ? ": (1) a gente que é homenageada e o trabalho dela; (2) o que a data representa; (3) a relação dessa gente com a marca. Uma delas NÃO começa pela data."
        : ": ganchos, ordem das ideias e ritmo de frase diferentes entre elas.")+"\n";
    u+="- Se dá pra trocar uma opção pela outra e ninguém notar, as duas estão erradas. Reescreva.\n";
    u+="- Mesma data, mesma marca, mesmo sentido de homenagem — o que muda é o caminho, nunca o assunto.\n";
  }
  u+=_pxRegrasLegenda(pb,unit,ehComemorativa,task.client);
  const _artePx=_pxHtmlParaTexto(task.desc||task.description)||briefing;
  if(!soStory) u+=_pxAvisoNaoRepeteArte(_artePx);
  if(soStory) u+="\nESTE CARD É SOMENTE STORY: escreva "+(quantas===1?"a legenda":"as "+quantas)+" curta (até 220 caracteres) e sem hashtags.";

  const data=await askIA({model:PX_IA_MODELO,max_tokens:(quantas===1?1400:3000),system:sys,messages:[{role:"user",content:u}]});
  let txt=((data&&data.content)||[]).map(function(b){return (b&&b.text)||"";}).join("").trim();
  txt=txt.replace(/^```(?:json|text)?\s*/i,"").replace(/```\s*$/,"").trim();
  // Normaliza variações do separador (**OPÇÃO 1**, ### Opcao 1, OPÇÃO 1:) antes de cortar
  txt=txt.replace(/^[\s>*#=_-]*OP[ÇC][ÃA]O\s*([123])\s*[:\s>*#=_-]*$/gim,function(_m,n){return "===OPCAO "+n+"===";});
  const partes=txt.split(/===OPCAO\s*[123]===/i).map(function(p){return p.trim();}).filter(function(p){return p.length>40;});
  const out=(partes.length?partes:[txt]).map(function(p){
    return p.replace(/^===+\s*/,"").replace(/\s*===+$/,"").trim();
  }).filter(Boolean);
  if(!out.length) throw new Error("A IA respondeu vazio. Tente de novo.");
  const _fin=out.slice(0,quantas);
  if(!soStory){ for(let i=0;i<_fin.length;i++){ _fin[i]=await _pxDesrepeteLegenda(_fin[i], _artePx, py); } }
  return _fin;
}

/* ─── GERAR BRIEFING (botão "Gerar briefing" da aba Briefing) ─────────────
   A pessoa escreve o que precisa em linguagem normal ("vídeo mostrando a obra
   de Toledo pronta, falar do prazo") e a IA devolve DUAS coisas:
     1. o TIPO DE CONTEÚDO (um dos 8 do seletor do card);
     2. o briefing no formato que a equipe já usa.
   O tipo volta pra quem chamou marcar o seletor e puxar o responsável certo —
   vídeo entra com o Guilherme, igual ao clique manual no seletor.

   Os tipos são os MESMOS ids do seletor em 10_radar_entrega. Se mudar lá, muda aqui. */
const PX_TIPOS_CONTEUDO=[
  {id:"foto",           label:"Ajuste de template", grupo:"design", quando:"só trocar foto e/ou texto num template que já existe; nada é criado do zero"},
  {id:"arte",           label:"Arte única",         grupo:"design", quando:"uma peça estática só, criada do zero"},
  {id:"carrossel",      label:"Carrossel",          grupo:"design", quando:"o conteúdo precisa de várias lâminas em sequência"},
  {id:"folder",         label:"Folder",             grupo:"design", quando:"material impresso ou PDF de várias páginas, pra entregar ou imprimir"},
  {id:"corte",          label:"Corte de vídeo",     grupo:"video",  quando:"já existe um vídeo gravado e é só cortar, legendar ou adaptar"},
  {id:"video_feira",    label:"Vídeo básico",       grupo:"video",  quando:"vídeo simples, pouca edição — registro de feira, bastidor, recado rápido"},
  {id:"video",          label:"Vídeo",              grupo:"video",  quando:"vídeo editado de verdade, com roteiro, cenas e trilha"},
  {id:"video_complexo", label:"Vídeo dinâmico",     grupo:"video",  quando:"motion, animação, efeitos — edição pesada"},
];
function pxTipoEhVideo(id){
  const t=PX_TIPOS_CONTEUDO.find(function(x){return x.id===String(id||"");});
  return !!(t&&t.grupo==="video");
}

/* Briefings de cards já aprovados/publicados do cliente — servem de molde de
   FORMATO (como a equipe escreve), não de conteúdo. */
async function pxBriefingsAprovados(client,unit,tipo){
  const sb=window._sb; if(!sb||!client) return [];
  try{
    let q=sb.from("tasks").select("title,description,content_type,publish_date")
      .eq("client",client)
      .is("deleted_at",null)
      .in("status",["aprovado","aprovacao_final","agendado","publicado"])
      .not("description","is",null).neq("description","")
      .order("publish_date",{ascending:false,nullsFirst:false})
      .limit(30);
    if(unit) q=q.eq("bioter_unit",unit);
    const {data,error}=await q;
    if(error||!Array.isArray(data)) return [];
    const bons=data.filter(function(r){return r&&_pxHtmlParaTexto(r.description).length>80;});
    // prioriza os do mesmo tipo de conteúdo; completa com os outros
    const mesmo=bons.filter(function(r){return String(r.content_type||"")===String(tipo||"");});
    const resto=bons.filter(function(r){return String(r.content_type||"")!==String(tipo||"");});
    return mesmo.concat(resto).slice(0,4);
  }catch(_){ return []; }
}

/* Devolve {tipo, tipoLabel, porque, briefing(HTML)} ou lança erro. */
async function pxGerarBriefing(opts){
  const task=(opts&&opts.task)||null;
  if(!task) throw new Error("Card não informado.");
  if(typeof askClaude!=="function") throw new Error("Pixels IA indisponível neste ambiente.");
  const pedido=String((opts&&opts.necessidade)||"").trim();
  const modo=String((opts&&opts.modo)||"gerar")==="alterar"?"alterar":"gerar";
  const briefAtual=_pxHtmlParaTexto((opts&&opts.briefingAtual)||"");
  const historico=Array.isArray(opts&&opts.historico)?opts.historico:[];
  if(pedido.length<5) throw new Error(modo==="alterar"
    ? "Escreva o que precisa ajustar antes de gerar."
    : "Escreva o que precisa ser feito antes de gerar.");
  if(modo==="alterar"&&briefAtual.length<20) throw new Error("Este card ainda não tem briefing pra alterar.");

  const cliente=String((opts&&opts.clienteNome)||task.client||"");
  const unit=String(task.bioterUnit||task.bioter_unit||"");
  const py=unit==="paraguay";
  const tipoAtual=String(task.contentType||task.content_type||"");

  const ctx=await pxContextoCopy(task.client,unit,task);
  const pb=(ctx&&ctx.playbook)||{};
  const regras=(ctx&&ctx.regras)||[];
  const foco=(ctx&&ctx.foco_do_mes)||[];
  let moldes=[];
  try{ moldes=await pxBriefingsAprovados(task.client,unit,tipoAtual); }catch(_){}
  let exEstilo=[]; try{ exEstilo=await pxExemplosEstilo(task,unit); }catch(_){}

  const sys="Você prepara briefings de produção para a equipe interna de uma agência que atende "+
    "agronegócio e construção no Brasil. Quem lê é o designer ou o editor de vídeo: o briefing precisa "+
    "ser executável sem ninguém perguntar nada depois. "+
    "NUNCA invente número, medida, cidade, prazo, preço, garantia nem nome de cliente que não esteja no pedido. "+
    "Se faltar dado, escreva o briefing sem ele — nunca preencha com suposição. "+
    (py?"O TÍTULO E O TEXTO DA PEÇA VÃO EM ESPANHOL (é a unidade do Paraguai); os rótulos do briefing ficam em português."
       :"Escreva em português do Brasil.")+
    (modo==="alterar"?"Você está AJUSTANDO um briefing que já existe: mexa só no que foi criticado e devolva o texto inteiro. ":"")+
    "\nResponda EXATAMENTE neste formato, texto puro, sem markdown, sem nada antes nem depois:"+
    "\n===TIPO===\n(só o id do tipo)\n===PORQUE===\n"+(modo==="alterar"?"(uma frase curta dizendo o que você mudou)":"(uma frase curta dizendo por que esse tipo)")+"\n===BRIEFING===\n(o briefing)";

  let u="CLIENTE: "+(cliente||"—")+(unit?(" — unidade "+unit):"")+"\n";
  u+="CARD: "+(task.title||"—")+"\n";
  const dt=String(task.publishDate||task.publish_date||"").slice(0,10);
  if(dt) u+="PUBLICA EM: "+dt.slice(8,10)+"/"+dt.slice(5,7)+"/"+dt.slice(0,4)+"\n";
  if(tipoAtual){
    const _ta=PX_TIPOS_CONTEUDO.find(function(x){return x.id===tipoAtual;});
    u+="TIPO JÁ MARCADO NO CARD: "+((_ta&&_ta.label)||tipoAtual)+" (só mude se o pedido abaixo disser outra coisa)\n";
  }
  if(modo==="alterar"){
    u+="\n════ BRIEFING ATUAL (é este que você vai ajustar) ════\n"+briefAtual+"\n\n";
    u+="════ O QUE PRECISA AJUSTAR ════\n"+pedido+"\n\n";
    if(historico.length){
      u+="AJUSTES JÁ PEDIDOS NESTA MESMA RODADA — não repita nenhum desses erros:\n";
      for(let i=0;i<Math.min(historico.length,6);i++){
        const _f=String((historico[i]&&historico[i].pedido)||"").trim();
        if(_f) u+="- "+_f+"\n";
      }
      u+="\n";
    }
  }else{
    u+="\n════ O QUE A AGÊNCIA PEDIU (única fonte de fatos) ════\n"+pedido+"\n\n";
    if(historico.length){
      u+="VERSÕES JÁ RECUSADAS NESTA RODADA E O QUE FOI DITO — não repita:\n";
      for(let i=0;i<Math.min(historico.length,6);i++){
        const _f=String((historico[i]&&historico[i].pedido)||"").trim();
        if(_f) u+="- "+_f+"\n";
      }
      u+="\n";
    }
  }

  u+="ESCOLHA UM TIPO DESTA LISTA (responda só o id):\n";
  for(let i=0;i<PX_TIPOS_CONTEUDO.length;i++)
    u+="- "+PX_TIPOS_CONTEUDO[i].id+" ("+PX_TIPOS_CONTEUDO[i].label+"): "+PX_TIPOS_CONTEUDO[i].quando+"\n";
  u+="Se o pedido já disser o formato (\"faz um carrossel\", \"vídeo curto\", \"só troca a foto do template\"), OBEDEÇA — não escolha outro.\n";
  if(modo==="alterar") u+="ESTE É UM AJUSTE: MANTENHA o tipo que já está no card, a não ser que o pedido de ajuste peça outro explicitamente.\n";
  u+="Na dúvida entre arte única e carrossel, escolha arte única. Na dúvida entre vídeo e vídeo dinâmico, escolha vídeo.\n\n";

  if(pb.comunicacao) u+="TOM DE VOZ DA MARCA:\n"+_pxCtxTxt(pb.comunicacao)+"\n\n";
  if(pb.chamadas_proibidas&&pb.chamadas_proibidas.length)
    u+="⛔ CHAMADAS PROIBIDAS (nunca usar, nem parecido): "+_pxCtxTxt(pb.chamadas_proibidas)+"\n\n";
  if(regras.length){
    u+="REGRAS APRENDIDAS COM O FEEDBACK DA AGÊNCIA (obrigatórias):\n";
    for(let i=0;i<regras.length;i++) u+="- ["+String(regras[i].tipo||"").toUpperCase()+"] "+regras[i].regra+"\n";
    u+="\n";
  }
  if(foco.length){
    const f=foco[0]; const partes=[];
    if(f.objetivo) partes.push("objetivo: "+f.objetivo);
    if(_pxCtxTxt(f.produtos_foco)) partes.push("produtos em foco: "+_pxCtxTxt(f.produtos_foco));
    if(partes.length) u+="FOCO DO MÊS: "+partes.join("; ")+"\n\n";
  }
  u+=_pxBlocoExemplosEstilo(exEstilo,task,"briefing");
  if(moldes.length){
    u+="BRIEFINGS DE CARDS JÁ APROVADOS DESTE CLIENTE — COPIE O FORMATO, NÃO O CONTEÚDO:\n";
    for(let i=0;i<moldes.length;i++)
      u+="---\n"+_pxHtmlParaTexto(moldes[i].description).slice(0,900)+"\n";
    u+="\n";
  }

  if(modo==="alterar"){
    u+="\nTAREFA: reescreva o BRIEFING ATUAL aplicando o ajuste pedido.\n";
    u+="- MANTENHA tudo que não foi criticado, com as mesmas palavras. Não reescreva o que já está bom.\n";
    u+="- Não invente dado novo pra preencher o que foi tirado.\n";
    u+="- Devolva o briefing INTEIRO já corrigido, nunca só o pedaço que mudou.\n\n";
  }
  u+="FORMATO DO BRIEFING, conforme o tipo que você escolher:\n";
  u+="- qualquer tipo de vídeo (corte, video_feira, video, video_complexo) → roteiro de FALA pro cliente gravar, neste formato:\n"+PX_ROTEIRO_FALA_FORMATO+PX_ROTEIRO_FALA_REGRAS+"  (só se o pedido disser \"vídeo simples\"/sem fala: "+PX_ROTEIRO_SIMPLES_FORMATO.replace(/\n/g," ")+")\n";
  u+="- design que não é carrossel (foto, arte, folder) → seção \"• TÍTULO\" (a headline que vai na peça, em caixa alta) e seção \"• TEXTO NA ARTE\".\n";
  u+="  ⚠️ O TEXTO NA ARTE NÃO PODE REPETIR O TÍTULO. O título já está na peça; repetir faz o colaborador ler a mesma coisa duas vezes. Comece direto pelo apoio: 2 frases que desenvolvem a ideia, linha em branco, fecho — 260 a 480 caracteres.\n";
  u+="- carrossel → \"Lâmina 1 — …\" até no máximo \"Lâmina 5 — …\", a 5 é o CTA.\n";
  u+="Os rótulos de seção vão SEMPRE EM MAIÚSCULO, exatamente assim: • TÍTULO, • TEXTO NA ARTE, • ROTEIRO, • O QUE PRECISAMOS.\n";
  u+="Depois do briefing, acrescente sempre uma última seção \"• O QUE PRECISAMOS\" listando em tópicos o que a equipe precisa ter em mãos pra executar (foto da obra, logo do cliente, take gravado, dado técnico). Se não faltar nada, escreva \"nada além do que já está no card\".\n";
  u+="Não escreva legenda de Instagram aqui — legenda é outra etapa.";

  const data=await askIA({model:PX_IA_MODELO,max_tokens:2600,system:sys,messages:[{role:"user",content:u}]});
  let txt=((data&&data.content)||[]).map(function(b){return (b&&b.text)||"";}).join("").trim();
  txt=txt.replace(/^```(?:json|text)?\s*/i,"").replace(/```\s*$/,"").trim();
  txt=txt.replace(/^[\s>*#=_-]*(TIPO|PORQUE|POR\s*QUE|BRIEFING)\s*[:\s>*#=_-]*$/gim,function(_m,p1){
    const k=p1.toUpperCase().replace(/\s+/g,"");
    return "==="+(k==="PORQUE"?"PORQUE":k)+"===";
  });
  const _fatia=function(ini,fim){
    const a=txt.indexOf(ini); if(a<0) return "";
    const b=fim?txt.indexOf(fim,a):-1;
    return (b>a?txt.slice(a+ini.length,b):txt.slice(a+ini.length)).trim();
  };
  let tipo=_fatia("===TIPO===","===PORQUE===")||_fatia("===TIPO===","===BRIEFING===");
  const porque=_fatia("===PORQUE===","===BRIEFING===");
  let brief=_fatia("===BRIEFING===","");
  if(!brief){ brief=txt.replace(/^===+\s*/,"").trim(); }
  // ── normaliza o tipo: id > rótulo > apelido > formato do briefing > tipo atual ──
  const _bruto=String(tipo||"").toLowerCase();
  tipo=_bruto.replace(/[^a-z_]/g,"");
  let achado=PX_TIPOS_CONTEUDO.find(function(x){return x.id===tipo;});
  if(!achado){
    // rótulo: testa do MAIS LONGO pro mais curto, senão "Vídeo dinâmico" casa em "Vídeo"
    const _porTam=PX_TIPOS_CONTEUDO.slice().sort(function(a,b){return b.label.length-a.label.length;});
    achado=_porTam.find(function(x){return _bruto.indexOf(x.label.toLowerCase())>=0;});
  }
  if(!achado){
    // apelidos que aparecem no dia a dia
    const _apelidos=[
      [/reels?|shorts?|tiktok|motion|anima/,"video"],
      [/dinamic|dinâmic|efeito/,"video_complexo"],
      [/corte|legenda(r|gem)|recorte/,"corte"],
      [/feira|bastidor|recado|simples/,"video_feira"],
      [/v[íi]deo|filmagem|grava/,"video"],
      [/carrossel|l[âa]mina|sequ[êe]ncia/,"carrossel"],
      [/folder|panfleto|flyer|impress|catalog/,"folder"],
      [/template|ajuste|trocar\s+(a\s+)?foto/,"foto"],
      [/arte|post|card|pe[çc]a|est[áa]tic/,"arte"],
    ];
    for(let i=0;i<_apelidos.length&&!achado;i++)
      if(_apelidos[i][0].test(_bruto))
        achado=PX_TIPOS_CONTEUDO.find(function(x){return x.id===_apelidos[i][1];});
  }
  if(!achado){
    // último recurso antes do tipo atual: o próprio formato que ele escreveu
    const _b=String(brief||"").toLowerCase();
    const _id=/(^|\n)\s*(•\s*)?roteiro|cena\s*1\b/.test(_b) ? "video"
            : /(^|\n)\s*l[âa]mina\s*1/.test(_b) ? "carrossel"
            : /(^|\n)\s*(•\s*)?t[íi]tulo/.test(_b) ? "arte" : "";
    if(_id) achado=PX_TIPOS_CONTEUDO.find(function(x){return x.id===_id;});
  }
  if(!achado) achado=PX_TIPOS_CONTEUDO.find(function(x){return x.id===tipoAtual;})||PX_TIPOS_CONTEUDO[1];
  if(!brief) throw new Error("A IA respondeu vazio. Tente de novo.");
  return { tipo:achado.id, tipoLabel:achado.label, ehVideo:achado.grupo==="video", modo:modo,
           porque:porque||"", briefing:_pxTextoParaHtml(brief), briefingTexto:brief };
}

/* ═══════════════════════════════════════════════════════════════════
   SPRINT HELPERS — lógica de cálculo de sprint e previsão de entrega
   Toda a lógica vive aqui pra ser testável e reusable.
═══════════════════════════════════════════════════════════════════ */

// Default config (fallback se Supabase ainda não retornou)
const SPRINT_CONFIG_DEFAULT = {
  id: 1,
  dia_inicio: 1,           // 0=dom, 1=seg, ..., 6=sáb
  dia_limite: 3,           // até quando aceita demanda na sprint atual (ex: quarta)
  horario_limite: "18:00",
  prazo_padrao_dias: 5,    // dias úteis
  texto_cliente: "Esta demanda entrou na sprint de {inicio} a {fim}. Previsão de entrega: {fim}.",
  texto_aguardando: "O prazo pode ser ajustado após o envio das informações pendentes.",
  texto_urgente: "Urgência em análise — a equipe definirá um prazo personalizado em breve.",
};

// Cache global em memória pra evitar fetch repetido
let _sprintConfigCache = null;
async function loadSprintConfig(){
  if(_sprintConfigCache)return _sprintConfigCache;
  if(typeof window!=="undefined"&&window._sb){
    try{
      const {data,error}=await window._sb.from("sprint_config").select("*").eq("id",1).single();
      if(!error&&data){_sprintConfigCache=data;return data;}
    }catch(e){console.warn("[sprint] load config:",e);}
  }
  return SPRINT_CONFIG_DEFAULT;
}
function invalidateSprintConfigCache(){_sprintConfigCache=null;}

// Formato data: 'YYYY-MM-DD'
function _ymd(d){
  const yyyy=d.getFullYear(),mm=String(d.getMonth()+1).padStart(2,"0"),dd=String(d.getDate()).padStart(2,"0");
  return yyyy+"-"+mm+"-"+dd;
}
// Formato pt-br: 'DD/MM'
function _ddmm(d){return String(d.getDate()).padStart(2,"0")+"/"+String(d.getMonth()+1).padStart(2,"0");}
// Cópia de data zerando hora
function _atMidnight(d){const x=new Date(d);x.setHours(0,0,0,0);return x;}
// Adiciona N dias úteis (pula sáb=6 e dom=0)
function _addBusinessDays(date,n){
  let d=new Date(date);
  let added=0;
  while(added<n){
    d.setDate(d.getDate()+1);
    const w=d.getDay();
    if(w!==0&&w!==6)added++;
  }
  return d;
}

// Calcula o início da sprint pra uma data qualquer.
// Ex: hoje é quinta (4), dia_inicio=1 (seg) → volta 3 dias → segunda dessa semana.
function sprintInicioPara(date,config){
  const cfg=config||SPRINT_CONFIG_DEFAULT;
  const d=_atMidnight(date);
  const diaSemana=d.getDay();
  let diff=diaSemana-cfg.dia_inicio;
  if(diff<0)diff+=7;
  d.setDate(d.getDate()-diff);
  return d;
}

// ID semântico da sprint (ex: '2026-W23').
function sprintIdPara(date,config){
  const inicio=sprintInicioPara(date,config);
  // ISO week number
  const tmp=new Date(Date.UTC(inicio.getFullYear(),inicio.getMonth(),inicio.getDate()));
  const dayNum=(tmp.getUTCDay()+6)%7; // 0=seg ... 6=dom
  tmp.setUTCDate(tmp.getUTCDate()-dayNum+3); // quinta da mesma semana
  const week1=new Date(Date.UTC(tmp.getUTCFullYear(),0,4));
  const weekNum=1+Math.round(((tmp-week1)/86400000-3+((week1.getUTCDay()+6)%7))/7);
  return tmp.getUTCFullYear()+"-W"+String(weekNum).padStart(2,"0");
}

// Sprint ATUAL (baseada em hoje).
function sprintAtual(config){
  const cfg=config||SPRINT_CONFIG_DEFAULT;
  const hoje=new Date();
  const inicio=sprintInicioPara(hoje,cfg);
  const fim=_addBusinessDays(inicio,cfg.prazo_padrao_dias-1);
  return {
    id: sprintIdPara(inicio,cfg),
    data_inicio: _ymd(inicio),
    data_fim: _ymd(fim),
    prazo_dias: cfg.prazo_padrao_dias,
  };
}

// Sprint pra uma demanda nova (considera cutoff: se passou do dia/horário limite, vai pra próxima)
function sprintParaDemanda(dataSolicitacao,config){
  const cfg=config||SPRINT_CONFIG_DEFAULT;
  const d=dataSolicitacao?new Date(dataSolicitacao):new Date();
  const diaSemana=d.getDay();
  const inicioAtual=sprintInicioPara(d,cfg);
  // Cutoff: dia da semana atual passou do dia_limite?
  // Ex: dia_limite=3 (quarta), hoje é quinta (4) → passou
  // Ex: hoje é quarta (3) e horário > horario_limite → passou
  let cutoffPassou=false;
  if(diaSemana>cfg.dia_limite){
    cutoffPassou=true;
  }else if(diaSemana===cfg.dia_limite){
    const [h,m]=cfg.horario_limite.split(":").map(function(x){return parseInt(x,10)||0;});
    if(d.getHours()>h||(d.getHours()===h&&d.getMinutes()>=m))cutoffPassou=true;
  }
  // Se passou, vai pra próxima sprint (+7 dias)
  const inicio=cutoffPassou?(function(){const n=new Date(inicioAtual);n.setDate(n.getDate()+7);return n;})():inicioAtual;
  const fim=_addBusinessDays(inicio,cfg.prazo_padrao_dias-1);
  return {
    id: sprintIdPara(inicio,cfg),
    data_inicio: _ymd(inicio),
    data_fim: _ymd(fim),
    prazo_dias: cfg.prazo_padrao_dias,
    cutoff_passou: cutoffPassou,
  };
}

// Calcula a data de entrega prevista pra uma sprint
function calcularPrazoEntrega(sprint){
  if(!sprint||!sprint.data_fim)return null;
  return sprint.data_fim; // data_fim JÁ é a previsão de entrega (último dia útil da sprint)
}

// Status do prazo da demanda
// Retorna: "no_prazo" | "atrasado" | "entregue" | "aguardando" | "urgencia_pendente" | "sem_sprint"
// Aceita tanto camelCase (completedAt) quanto snake_case (completed_at).
function statusPrazo(task){
  if(!task)return "sem_sprint";
  const _entregueEm=task.completedAt||task.completed_at||task.data_real_entrega;
  if(_entregueEm)return "entregue";
  if(task.urgente&&!task.data_prevista_entrega)return "urgencia_pendente";
  if(task.aguardando_info)return "aguardando";
  if(!task.sprint_id||!task.data_prevista_entrega)return "sem_sprint";
  const hoje=_atMidnight(new Date());
  const prevista=_atMidnight(new Date(task.data_prevista_entrega+"T12:00:00"));
  return hoje>prevista?"atrasado":"no_prazo";
}

// Renderiza o texto pro cliente (substitui placeholders {inicio} e {fim})
function textoSprintCliente(sprint,config){
  if(!sprint)return "";
  const cfg=config||SPRINT_CONFIG_DEFAULT;
  const ini=new Date(sprint.data_inicio+"T12:00:00");
  const fim=new Date(sprint.data_fim+"T12:00:00");
  return (cfg.texto_cliente||SPRINT_CONFIG_DEFAULT.texto_cliente)
    .replace(/\{inicio\}/g,_ddmm(ini))
    .replace(/\{fim\}/g,_ddmm(fim));
}

