// ════════════════════════════════════════════════════════════════════
// RITUAIS RECORRENTES — Daily/Weekly/Planejamento mensal/trimestral
// ════════════════════════════════════════════════════════════════════
// Geração determinística + persistência no Supabase (rituais_done)
// Chaves estáveis:
//   daily-YYYY-MM-DD
//   weekly-YYYY-MM-DD
//   planmes-YYYY-MM-28-{clientId}
//   plantri-YYYY-MM-28-{clientId}

// Helper interno: nome do mês em pt-BR
function _ritualMonthName(year, monthIdx){
  try{return new Date(year, monthIdx, 1).toLocaleDateString("pt-BR",{month:"long",year:"numeric"});}
  catch(_){return (monthIdx+1)+"/"+year;}
}
function _ritualToIso(d){
  return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0");
}

// Lista de clientes que recebem planejamento (mensal e trimestral).
// Filtro: clientes ativos da CLIENTS list.
function _ritualClientsList(){
  try{
    if(typeof CLIENTS!=="undefined"&&Array.isArray(CLIENTS)){
      return CLIENTS.filter(function(c){return c&&c.id&&c.id!=="interno";})
        .map(function(c){return {id:c.id, nome:c.nome||c.name||c.id};});
    }
  }catch(_){}
  return [];
}

// Gera todos os rituais previstos pra um mês (year, monthIdx 0-11).
// Returns: [{key, type, date:"YYYY-MM-DD", hour:"HH:MM" ou "", label, clientId?}]
function getRituaisDoMes(year, monthIdx){
  const out=[];
  const lastDay=new Date(year, monthIdx+1, 0).getDate();
  const clientsList=_ritualClientsList();
  for(let d=1; d<=lastDay; d++){
    const date=new Date(year, monthIdx, d);
    const dow=date.getDay();
    const iso=_ritualToIso(date);
    // Daily 11h — todo dia útil (seg-sex)
    if(dow>=1&&dow<=5){
      out.push({key:"daily-"+iso, type:"daily", date:iso, hour:"11:00", label:"Daily 11h"});
    }
    // Weekly 11h — toda segunda
    if(dow===1){
      out.push({key:"weekly-"+iso, type:"weekly", date:iso, hour:"11:00", label:"Weekly 11h"});
    }
    // Planejamento mensal — dia 28 (preparação do mês seguinte)
    if(d===28){
      const nextM=monthIdx+1>11?0:monthIdx+1;
      const nextY=monthIdx+1>11?year+1:year;
      const nextMonthLabel=_ritualMonthName(nextY, nextM);
      clientsList.forEach(function(c){
        out.push({key:"planmes-"+iso+"-"+c.id, type:"planmes", date:iso, hour:"", label:"Planej. mensal · "+c.nome+" · "+nextMonthLabel, clientId:c.id});
      });
    }
    // Planejamento trimestral — dia 28 de mar/jun/set/dez (preparação do Q seguinte)
    if(d===28&&(monthIdx===2||monthIdx===5||monthIdx===8||monthIdx===11)){
      const qLabel=monthIdx===2?"Q2":monthIdx===5?"Q3":monthIdx===8?"Q4":"Q1";
      const yLabel=monthIdx===11?year+1:year;
      clientsList.forEach(function(c){
        out.push({key:"plantri-"+iso+"-"+c.id, type:"plantri", date:iso, hour:"", label:"Planej. trimestral · "+c.nome+" · "+qLabel+" "+yLabel, clientId:c.id});
      });
    }
  }
  return out;
}

// Estado global em memória — mapa ritual_key → {done_at, done_by, notes}
if(typeof window!=="undefined"&&!window.__ritualsDone){window.__ritualsDone={};}

function isRitualDone(key){
  try{return !!(window.__ritualsDone&&window.__ritualsDone[key]);}catch(_){return false;}
}

// Carrega TODOS os rituais marcados como feitos do Supabase
async function loadRituaisDone(){
  if(typeof window==="undefined"||!window._sb)return;
  try{
    const{data,error}=await window._sb.from("rituais_done").select("*");
    if(error){console.warn("[rituais] load",error);return;}
    const map={};
    (data||[]).forEach(function(r){map[r.ritual_key]={done_at:r.done_at, done_by:r.done_by, notes:r.notes||""};});
    window.__ritualsDone=map;
    try{window.dispatchEvent(new CustomEvent("pixels:rituais-updated"));}catch(_){}
  }catch(e){console.warn("[rituais] load exc",e);}
}

// Marca/desmarca um ritual
async function toggleRitualDone(key, userName, notes){
  if(typeof window==="undefined"||!window._sb)return;
  const wasDone=isRitualDone(key);
  // Optimistic update
  if(wasDone){
    delete window.__ritualsDone[key];
  }else{
    window.__ritualsDone[key]={done_at:new Date().toISOString(), done_by:userName||"", notes:notes||""};
  }
  try{window.dispatchEvent(new CustomEvent("pixels:rituais-updated"));}catch(_){}
  try{
    if(wasDone){
      const{error}=await window._sb.from("rituais_done").delete().eq("ritual_key",key);
      if(error)console.warn("[rituais] delete",error);
    }else{
      const{error}=await window._sb.from("rituais_done").upsert({ritual_key:key, done_at:new Date().toISOString(), done_by:userName||"", notes:notes||""},{onConflict:"ritual_key"});
      if(error)console.warn("[rituais] upsert",error);
    }
  }catch(e){console.warn("[rituais] toggle exc",e);}
}

// Realtime sync — quando outro user marca, atualiza
function subscribeRituaisRealtime(){
  if(typeof window==="undefined"||!window._sb)return null;
  try{
    return window._sb.channel("rituais-done-rt")
      .on("postgres_changes",{event:"*",schema:"public",table:"rituais_done"},function(){loadRituaisDone();})
      .subscribe();
  }catch(e){return null;}
}

/* ══════════════════════════════════════════════════════════════════
   CLIENTES DINÂMICOS — registry global
   ══════════════════════════════════════════════════════════════════
   Clientes cadastrados via modal "Novo cliente" (sql/clients_dynamic.sql).
   São armazenados na tabela `clients` com is_dynamic=true e ficam
   MERGADOS na constante CLIENTS acima em runtime — assim TODOS os
   módulos que fazem CLIENTS.find(c=>c.id===X) veem eles sem alteração.

   Duas fases:
   1) BOOT SYNC — recupera do cache localStorage ANTES da render.
      Assim clientes já cadastrados aparecem imediatamente no F5.
   2) SUPABASE FETCH — chamado logo após o auth pronto (17_gestao_midia.jsx
      dispara depois de window._sb=_sb). Reconcilia com o servidor.

   API global:
   - window.registerDynamicClient(cl)           — adiciona/atualiza cliente in-place
   - window.loadDynamicClientsFromSupabase()    — busca do Supabase (usa auth)
   Ambos disparam CustomEvent "pixels:clients-registry-updated" quando muda algo.
   ══════════════════════════════════════════════════════════════════ */

// Normaliza row do Supabase pra shape do CLIENTS.
// Se `existing` for passado (hardcoded), retorna apenas os campos editáveis
// (não sobrescreve contract/meta/google/social/history/contacts etc.).
function _clientRowToObj(r, existing){
  // ── DEFENSIVE ── se name vier vazio, ignora a row (poderia corromper registry)
  if(!r || !r.name || !String(r.name).trim()) return null;
  const pd = r.profile_data || {};
  // Campos editáveis via EditarClienteModal (comuns a hardcoded + dinâmicos)
  const editable = {
    id: r.client_id,
    name: r.name,
    abbr: r.abbr || (r.name||"").slice(0,2).toUpperCase(),
    color: r.color || "#7c3aed",
    sector: r.sector || "",
    cidade: r.cidade || "",
    estado: r.estado || "",
    status: r.status || "ativo",
    since: r.since_label || "",
    logoUrl: r.logo_url || null,
    manager: r.manager || "vinicius",
  };
  // Se já existe cliente hardcoded (Bioter, Arabutã, etc.), NÃO sobrescreve
  // os dados ricos (contract, meta, google, social, history, contacts…).
  if(existing){
    return editable;
  }
  // Cliente novo (dinâmico) — cria com defaults completos.
  return Object.assign(editable, {
    contract: 0, health: 80, nps: 75,
    meta: pd.meta || {}, google: pd.google || {}, social: pd.social || {},
    socialUrls: pd.socialUrls || {}, reporteiUrl: pd.reporteiUrl || "",
    upsell: pd.upsell || [], connected: pd.connected || false,
    history: [], driveUrl: "", payment: {status:"pendente", date:""},
    contacts: [], goals: [], meetingNotes: [],
    _dynamic: true,
  });
}

// Adiciona/atualiza cliente in-place em CLIENTS (mutação).
window.registerDynamicClient = function(cl){
  if(!cl || !cl.id) return false;
  // ── DEFENSIVE ── nunca merga um cl.name vazio por cima de cliente existente
  // (evita corromper Bioter, Arabutã, etc. se algum edge case passar por aqui).
  if(!cl.name || !String(cl.name).trim()) return false;
  const existing = CLIENTS.find(function(c){return c.id===cl.id;});
  if(existing){
    // Atualiza in-place — não substitui referência (React precisa)
    Object.assign(existing, cl);
  } else {
    CLIENTS.push(cl);
  }
  try{ window.dispatchEvent(new CustomEvent("pixels:clients-registry-updated",{detail:{clientId:cl.id}})); }catch(_){}
  return true;
};

// Busca TODOS os clientes do Supabase (hardcoded + dinâmicos) e faz merge no CLIENTS.
// Preserva riqueza dos hardcoded (contract/meta/google/social/history/contacts…).
// Também atualiza o cache localStorage só com os dinâmicos.
window.loadDynamicClientsFromSupabase = async function(){
  if(!window._sb) return false;
  try{
    const res = await window._sb.from("clients")
      .select("client_id,name,abbr,sector,cidade,estado,color,logo_url,status,since_label,manager,profile_data,is_dynamic");
    if(res.error){ console.warn("[loadDynamicClients]", res.error.message); return false; }
    const rows = res.data || [];
    const dynamicCache = [];
    rows.forEach(function(r){
      const existing = CLIENTS.find(function(c){return c.id===r.client_id;});
      const obj = _clientRowToObj(r, existing);
      if(!obj) return;
      window.registerDynamicClient(obj);
      // Só cachea localStorage os dinâmicos (novos criados via app)
      if(!existing || r.is_dynamic===true){
        dynamicCache.push(obj);
      }
      // Também sincroniza CLIENT_LOGOS in-memory quando tem logo_url
      try{
        if(typeof CLIENT_LOGOS==="object" && CLIENT_LOGOS && r.logo_url){
          CLIENT_LOGOS[r.client_id] = r.logo_url;
        }
      }catch(_){}
    });
    // DEFENSIVE — só sobrescreve cache se vieram rows. Query vazia (RLS/rede) mantém cache atual.
    // Isso evita clientes dinâmicos sumirem no F5 quando a query retorna 0 rows por transitório.
    if(rows.length>0){
      try{ localStorage.setItem("pixels-extra-clients-v1", JSON.stringify(dynamicCache)); }catch(_){}
    }
    return true;
  }catch(e){
    console.warn("[loadDynamicClients ex]", e);
    return false;
  }
};

// ── BOOT SYNC ── recupera do cache local antes da primeira render
(function _bootRegisterCached(){
  try{
    const raw = localStorage.getItem("pixels-extra-clients-v1");
    if(!raw) return;
    const rows = JSON.parse(raw);
    if(!Array.isArray(rows)) return;
    const known = new Set(CLIENTS.map(function(c){return c.id;}));
    rows.forEach(function(r){
      if(r && r.id && !known.has(r.id)) CLIENTS.push(r);
    });
  }catch(_){}
})();

// ═══════════════════════════════════════════════════════════════════
// 00b_preview_util.jsx — Compactação de vídeo (versão leve 720p) GLOBAL
// Fonte única usada pelo upload (10_radar_entrega), pelo botão manual
// (06_aprovacoes) e pelo backfill automático (17_gestao_midia).
// A compactação roda no NAVEGADOR em tempo real (MediaRecorder): precisa
// da aba aberta e em primeiro plano. Preview ruim é descartado de propósito.
// ═══════════════════════════════════════════════════════════════════

// Gera um preview 720p (Blob) a partir de um File/Blob de vídeo. Resolve
// com o Blob comprimido, ou null se não deu (aba escondida, sem áudio,
// não encolheu o suficiente, etc). onProgress(pct 0-99). abortRef.current.
function pixelsGenerateVideoPreview(file,onProgress,abortRef){
  return new Promise(function(resolve){
    var PREVIEW_MAX_DURATION=15*60;   // acima de 15 min não compensa (tempo real)
    var PREVIEW_MAX_EDGE=1280;        // maior lado do preview
    // ── Bitrate ADAPTATIVO (14/09/2026) ──
    // Antes: 1.2 Mbps fixo. Reel de 45s saia com ~7 MB e visivelmente borrado.
    // Agora: calcula o bitrate pra mirar ~13 MB de arquivo final, com piso
    // (video longo nao explode de tamanho) e teto (video curto nao desperdica).
    var PREVIEW_TARGET_BYTES=13*1024*1024; // alvo de tamanho do preview
    var PREVIEW_VIDEO_BPS_MIN=1200000;     // piso  — videos longos (= comportamento antigo)
    var PREVIEW_VIDEO_BPS_MAX=6000000;     // teto  — acima disso 720p ja esta transparente
    var PREVIEW_AUDIO_BPS=128000;
    function _calcVideoBps(dur,origBytes){
      if(!isFinite(dur)||dur<=0)return PREVIEW_VIDEO_BPS_MIN;
      var alvo=(PREVIEW_TARGET_BYTES*8/dur)-PREVIEW_AUDIO_BPS;
      // nunca pedir mais bitrate do que o proprio original tem (so incharia o arquivo)
      if(origBytes>0){var _o=(origBytes*8/dur)*0.8;if(_o>0&&alvo>_o)alvo=_o;}
      if(alvo<PREVIEW_VIDEO_BPS_MIN)alvo=PREVIEW_VIDEO_BPS_MIN;
      if(alvo>PREVIEW_VIDEO_BPS_MAX)alvo=PREVIEW_VIDEO_BPS_MAX;
      return Math.round(alvo);
    }
    function _pickPreviewMime(){
      if(typeof MediaRecorder==="undefined")return null;
      var cands=["video/mp4;codecs=avc1.42E01E,mp4a.40.2","video/mp4","video/webm;codecs=vp9,opus","video/webm;codecs=vp8,opus","video/webm"];
      for(var i=0;i<cands.length;i++){try{if(MediaRecorder.isTypeSupported(cands[i]))return cands[i];}catch(_){}}
      return null;
    }
    function _validatePreview(blob,srcDur,drawCount){return new Promise(function(res){
      var _minFrames=Math.max(10,Math.floor(srcDur*8));
      if(drawCount<_minFrames){console.warn("[preview] poucos frames:",drawCount,"<",_minFrames);res(false);return;}
      var settled=false;
      var v=document.createElement("video");
      var u=URL.createObjectURL(blob);
      var done=function(ok){if(settled)return;settled=true;try{URL.revokeObjectURL(u);}catch(_){}res(ok);};
      v.preload="metadata";v.muted=true;
      v.onloadedmetadata=function(){
        var d=v.duration;
        if(!isFinite(d)||d<=0){done(true);return;}
        done(Math.abs(d-srcDur)<=0.6);
      };
      v.onerror=function(){done(false);};
      setTimeout(function(){done(false);},8000);
      v.src=u;
    });}

    var done=false,video=null,url=null,rec=null,raf=null,elStream=null,canvasStream=null,audioCtx=null;
    var drawCount=0,guardTimer=null,startWatchdog=null,lastPct=-1,lastDrawT=-1,recStarted=false;
    var hiddenDuring=(typeof document!=="undefined"&&document.hidden);
    var _onVis=function(){if(document.hidden)hiddenDuring=true;};
    var cleanup=function(){
      try{if(raf)cancelAnimationFrame(raf);}catch(_){}
      try{if(guardTimer)clearTimeout(guardTimer);}catch(_){}
      try{if(startWatchdog)clearTimeout(startWatchdog);}catch(_){}
      try{if(rec&&rec.state!=="inactive")rec.stop();}catch(_){}
      try{if(canvasStream)canvasStream.getTracks().forEach(function(t){t.stop();});}catch(_){}
      try{if(elStream)elStream.getTracks().forEach(function(t){t.stop();});}catch(_){}
      try{if(audioCtx&&audioCtx.state!=="closed")audioCtx.close();}catch(_){}
      try{if(video){video.pause();video.removeAttribute("src");video.load();}}catch(_){}
      try{if(url)URL.revokeObjectURL(url);}catch(_){}
      try{document.removeEventListener("visibilitychange",_onVis);}catch(_){}
    };
    var finish=function(val){if(done)return;done=true;cleanup();resolve(val);};
    var aborted=function(){return !!(abortRef&&abortRef.current);};
    try{
      var mimeType=_pickPreviewMime();
      if(!mimeType){finish(null);return;}
      document.addEventListener("visibilitychange",_onVis);
      video=document.createElement("video");
      video.preload="auto";video.playsInline=true;
      url=URL.createObjectURL(file);video.src=url;
      video.onerror=function(){finish(null);};
      video.onloadedmetadata=function(){
        if(aborted()){finish(null);return;}
        var dur=video.duration;
        if(!isFinite(dur)||dur<=0||dur>PREVIEW_MAX_DURATION){finish(null);return;}
        var vw=video.videoWidth,vh=video.videoHeight;
        if(!vw||!vh){finish(null);return;}
        var scale=Math.min(1,PREVIEW_MAX_EDGE/Math.max(vw,vh));
        var cw=Math.max(2,Math.round(vw*scale/2)*2), ch=Math.max(2,Math.round(vh*scale/2)*2);
        var canvas=document.createElement("canvas");
        canvas.width=cw;canvas.height=ch;
        var ctx=canvas.getContext("2d",{alpha:false});
        canvasStream=canvas.captureStream(30);
        var _audioOk=false;
        try{
          var AC=window.AudioContext||window.webkitAudioContext;
          if(AC){
            audioCtx=new AC();
            var srcNode=audioCtx.createMediaElementSource(video);
            var dest=audioCtx.createMediaStreamDestination();
            srcNode.connect(dest);
            var at=dest.stream.getAudioTracks()[0];
            if(at){canvasStream.addTrack(at);_audioOk=true;}
            if(audioCtx.state==="suspended"){try{audioCtx.resume();}catch(_){}}
          }
        }catch(_){}
        if(!_audioOk){console.warn("[preview] WebAudio indisponível — usando o original");finish(null);return;}
        var chunks=[];
        try{
          var _vbps=_calcVideoBps(dur,(file&&file.size)||0);
          console.log("[preview] "+cw+"x"+ch+" | "+Math.round(dur)+"s | "+(_vbps/1e6).toFixed(2)+" Mbps | alvo ~"+Math.round(PREVIEW_TARGET_BYTES/1048576)+" MB");
          rec=new MediaRecorder(canvasStream,{mimeType:mimeType,videoBitsPerSecond:_vbps,audioBitsPerSecond:PREVIEW_AUDIO_BPS});
        }catch(_){finish(null);return;}
        rec.ondataavailable=function(e){if(e.data&&e.data.size>0)chunks.push(e.data);};
        rec.onerror=function(){finish(null);};
        rec.onstop=function(){
          if(aborted()||hiddenDuring){finish(null);return;}
          if(!chunks.length){finish(null);return;}
          var _semAudioComprovado=(video.webkitAudioDecodedByteCount===0)||(video.mozHasAudio===false);
          if(!_semAudioComprovado){
            var _temTrilha=canvasStream.getAudioTracks().length>0;
            var _ctxOk=!!audioCtx&&audioCtx.state==="running";
            if(!_temTrilha||!_ctxOk){console.warn("[preview] áudio não capturado, descartando");finish(null);return;}
          }
          var blob=new Blob(chunks,{type:(mimeType.split(";")[0]||"video/mp4")});
          // Precisa encolher pelo menos 25% pra valer a pena guardar 2 arquivos.
          // (era 35%; afrouxado porque agora o preview e maior e melhor de proposito)
          if(blob.size>=file.size*0.75){console.warn("[preview] encolheu pouco, descartando");finish(null);return;}
          _validatePreview(blob,dur,drawCount).then(function(ok){finish(ok?blob:null);}).catch(function(){finish(null);});
        };
        var draw=function(){
          if(done)return;
          if(aborted()){try{if(rec&&rec.state!=="inactive")rec.stop();}catch(_){}finish(null);return;}
          try{
            ctx.drawImage(video,0,0,cw,ch);
            var _t=video.currentTime;
            if(_t!==lastDrawT){lastDrawT=_t;drawCount++;}
          }catch(_){}
          if(onProgress){
            var pct=Math.min(99,Math.round(video.currentTime/dur*100));
            if(pct!==lastPct){lastPct=pct;try{onProgress(pct);}catch(_){}}
          }
          raf=requestAnimationFrame(draw);
        };
        video.onended=function(){try{if(rec&&rec.state!=="inactive"){rec.stop();return;}}catch(_){}finish(null);};
        video.onplaying=function(){
          if(recStarted||done)return;
          recStarted=true;
          try{rec.start(1000);}catch(_){finish(null);return;}
          draw();
        };
        video.play().catch(function(){finish(null);});
        startWatchdog=setTimeout(function(){if(!recStarted&&!done){console.warn("[preview] play não iniciou");finish(null);}},30000);
        guardTimer=setTimeout(function(){console.warn("[preview] timeout, descartando");finish(null);},(dur+30)*1000);
      };
    }catch(_){finish(null);}
  });
}

// Fila global de escrita em tasks.files (serializa SELECT->patch->UPDATE).
function _pixelsQueueFilesWrite(fn){
  if(typeof window==="undefined")return Promise.resolve().then(fn);
  var prev=window.__pxFilesWriteQueue||Promise.resolve();
  var next=prev.then(fn,fn);
  window.__pxFilesWriteQueue=next.catch(function(){});
  return next;
}

// Persiste previewUrl/previewPath/previewSize no tasks.files de um card qualquer.
function pixelsPersistPreview(taskId,fileId,previewUrl,previewPath,previewSize){
  return _pixelsQueueFilesWrite(async function(){
    try{
      var sb=window._sb;
      if(!sb||!taskId)return false;
      var sel=await sb.from("tasks").select("files").eq("id",taskId).maybeSingle();
      var current=sel&&sel.data;
      if(!current||!Array.isArray(current.files))return false;
      var patch={previewUrl:previewUrl,previewPath:previewPath,previewSize:previewSize};
      var matched=false;
      var updated=current.files.map(function(f){
        if(!f)return f;
        var hit=(fileId&&f.id===fileId)||(previewPath&&f.storagePath&&previewPath.indexOf(f.storagePath.replace(/\.[^.]+$/,""))===0);
        if(hit&&f.previewEngine==="ffmpeg")return f; // PRÉVIA FFMPEG MANDA: a do navegador nunca vai por cima
        if(hit){matched=true;return Object.assign({},f,patch);}
        return f;
      });
      if(!matched)return false;
      var upd=await sb.from("tasks").update({files:updated}).eq("id",taskId);
      if(upd&&upd.error){console.warn("[preview] update tasks.files:",upd.error.message);return false;}
      return true;
    }catch(e){console.warn("[preview] persist:",e&&e.message||e);return false;}
  });
}

// Aplica um patch em um item de tasks.files (por id). Best-effort, na fila de escrita.
// Miniatura → Storage (07/09/2026). Antes a thumbnail ficava em base64 dentro de
// tasks.files (148 miniaturas = 3,2 MB em TODA carga da tabela, e o localStorage
// não cabia mais). Agora sobe como JPEG em agency-files/thumbs/<task>/<file>.jpg e
// files[].thumbnail guarda só a URL. Se o upload falhar, cai no base64 (como era).
async function pxThumbToStorage(taskId,fileId,dataURL){
  try{
    if(!dataURL||String(dataURL).indexOf("data:")!==0) return dataURL;
    var sb=window._sb; if(!sb||!taskId||!fileId) return dataURL;
    var blob=await (await fetch(dataURL)).blob();
    var safe=function(x){ return String(x).replace(/[^A-Za-z0-9_-]/g,"_"); };
    var path="thumbs/"+safe(taskId)+"/"+safe(fileId)+".jpg";
    var up=await sb.storage.from("agency-files").upload(path,blob,{contentType:"image/jpeg",upsert:true,cacheControl:"31536000"});
    if(up&&up.error){ console.warn("[thumb→storage]",up.error.message); return dataURL; }
    var pub=sb.storage.from("agency-files").getPublicUrl(path);
    var url=pub&&pub.data&&pub.data.publicUrl; if(!url) return dataURL;
    return url+"?v="+Date.now().toString(36);
  }catch(e){ console.warn("[thumb→storage]",e&&e.message); return dataURL; }
}
// Migração em segundo plano das miniaturas base64 antigas (09/09/2026): roda no app da
// agência depois da carga inicial, 1 miniatura a cada 4 s, sem travar nada. Idempotente:
// pula o que já é URL; se duas abas fizerem a mesma, o upload é upsert no mesmo caminho.
window.__pxThumbMigrando = window.__pxThumbMigrando || false;
async function pxMigrarThumbsEmBackground(tasks){
  try{
    if(window.__pxThumbMigrando||!window._sb||!Array.isArray(tasks)) return;
    const fila=[];
    tasks.forEach(function(t){ if(!t||t.deletedAt) return; (t.files||[]).forEach(function(f){ if(f&&f.id&&typeof f.thumbnail==="string"&&f.thumbnail.indexOf("data:")===0) fila.push({taskId:t.id,fileId:f.id,data:f.thumbnail}); }); });
    if(!fila.length) return;
    window.__pxThumbMigrando=true;
    console.log("[thumb→storage] migrando "+fila.length+" miniatura(s) em segundo plano");
    let ok=0;
    for(let i=0;i<fila.length;i++){
      const it=fila[i];
      try{
        const url=await pxThumbToStorage(it.taskId,it.fileId,it.data);
        if(url&&url.indexOf("data:")!==0){ const r=await pixelsPersistFilePatch(it.taskId,it.fileId,{thumbnail:url}); if(r) ok++; }
      }catch(_){}
      await new Promise(function(r){ setTimeout(r,4000); });
    }
    console.log("[thumb→storage] concluído: "+ok+"/"+fila.length);
  }catch(e){ console.warn("[thumb→storage] migração:",e&&e.message); }
  finally{ window.__pxThumbMigrando=false; }
}
function pixelsPersistFilePatch(taskId,fileId,patch){
  return _pixelsQueueFilesWrite(async function(){
    try{
      var sb=window._sb; if(!sb||!taskId||!fileId)return false;
      var sel=await sb.from("tasks").select("files").eq("id",taskId).maybeSingle();
      var current=sel&&sel.data; if(!current||!Array.isArray(current.files))return false;
      var hit=false;
      var updated=current.files.map(function(f){ if(f&&f.id===fileId){hit=true;return Object.assign({},f,patch);} return f; });
      if(!hit)return false;
      var upd=await sb.from("tasks").update({files:updated}).eq("id",taskId);
      if(upd&&upd.error)return false;
      try{ pxRegisterFiles(updated); }catch(_){}
      return true;
    }catch(_){ return false; }
  });
}

// Baixa o original, gera o preview e persiste. Retorna {ok,skipped,previewUrl,previewSize}.
async function pixelsBackfillOneVideo(taskId,file,onProgress,abortRef){
  var sb=window._sb;
  if(!sb||!file)return {ok:false};
  var PREVIEW_MIN_SIZE=20*1024*1024;
  // 1) baixa o original (preferir storagePath — sem CORS)
  var orig=null;
  try{
    if(file.storagePath){
      var dl=await sb.storage.from("agency-files").download(file.storagePath);
      if(dl&&dl.data)orig=dl.data;
    }
  }catch(_){}
  if(!orig&&file.url){
    try{var r=await fetch(file.url);if(r.ok)orig=await r.blob();}catch(_){}
  }
  if(!orig)return {ok:false,reason:"download"};
  // 1b) thumbnail a partir do blob já baixado (miniaturas nunca mais tocam no original)
  var thumbDataUrl=null;
  if(!(file.thumbnail&&String(file.thumbnail).length>32)){
    try{ thumbDataUrl=await pixelsMakeThumbFromBlob(orig); }catch(_){ thumbDataUrl=null; }
    if(thumbDataUrl){ try{ var _tu=await pxThumbToStorage(taskId,file.id,thumbDataUrl); await pixelsPersistFilePatch(taskId,file.id,{thumbnail:_tu}); }catch(_){} }
  }
  if(orig.size<=PREVIEW_MIN_SIZE)return {ok:false,skipped:true,reason:"pequeno"};
  // 2) comprime
  var blob=await pixelsGenerateVideoPreview(orig,onProgress,abortRef);
  if(!blob)return {ok:false,reason:"compress"};
  // 3) sobe o preview ao lado do original
  var base=(file.storagePath||("tasks/"+taskId+"/"+(file.id||Date.now()))).replace(/\.[^.]+$/,"");
  var pExt=(blob.type&&blob.type.indexOf("webm")>=0)?"webm":"mp4";
  var pPath=base+"-preview."+pExt;
  try{
    var up=await sb.storage.from("agency-files").upload(pPath,blob,{contentType:blob.type||"video/mp4",upsert:true});
    if(up&&up.error){console.warn("[backfill] upload:",up.error.message);return {ok:false,reason:"upload"};}
  }catch(e){console.warn("[backfill] upload ex:",e&&e.message||e);return {ok:false,reason:"upload"};}
  var pub=sb.storage.from("agency-files").getPublicUrl(pPath);
  var previewUrl=pub&&pub.data&&pub.data.publicUrl;
  await pixelsPersistPreview(taskId,file.id,previewUrl,pPath,blob.size);
  return {ok:true,previewUrl:previewUrl,previewSize:blob.size,previewPath:pPath};
}

// ═══════════════════════════════════════════════════════════════════
// Controle de EGRESS de vídeo (02/09/2026)
// Problema: <video preload="metadata"> + seek em miniaturas baixava o ORIGINAL
// inteiro (100-300 MB, moov no fim do arquivo) a cada montagem do componente —
// dezenas de vezes por sessão. ~60 GB/dia de saída do Supabase.
// Regra daqui em diante:
//   • miniatura NUNCA carrega vídeo: usa `thumbnail` (frame capturado no upload)
//     ou placeholder; captura de frame só a partir da versão leve, 1 por vez.
//   • player toca a versão leve (previewUrl) quando existe; o original só entra
//     com preload="none" (não baixa nada até o clique) ou em "baixar original".
// Registro global url→{preview,thumb} alimentado por pxRegisterTasks(tasks).
// ═══════════════════════════════════════════════════════════════════
window.__pxVidMeta = window.__pxVidMeta || {};
function _pxUrlKey(u){ return String(u||"").split("#")[0].split("?")[0]; }
function pxRegisterFiles(files){
  if(!Array.isArray(files))return;
  var M=window.__pxVidMeta;
  for(var i=0;i<files.length;i++){
    var f=files[i]; if(!f||!f.url)continue;
    var k=_pxUrlKey(f.url);
    var m=M[k]||(M[k]={});
    var p=f.previewUrl||f.preview_url||null;
    var t=(f.thumbnail&&String(f.thumbnail).length>32)?f.thumbnail:null;
    if(p)m.preview=p;
    if(t)m.thumb=t;
  }
}
function pxRegisterTasks(tasks){
  if(!Array.isArray(tasks))return;
  for(var i=0;i<tasks.length;i++){ var t=tasks[i]; if(t&&Array.isArray(t.files))pxRegisterFiles(t.files); }
}
function pxVidMeta(src,file){
  var m=window.__pxVidMeta[_pxUrlKey(src)]||{};
  var preview=(file&&(file.previewUrl||file.preview_url))||m.preview||null;
  var thumb=(file&&file.thumbnail&&String(file.thumbnail).length>32)?file.thumbnail:(m.thumb||null);
  if(preview&&_pxUrlKey(preview)===_pxUrlKey(src))preview=null;
  return {preview:preview,thumb:thumb};
}
// Fonte pra tocar: versão leve se existir, senão o original.
function pxPlaySrc(src,file){ var m=pxVidMeta(src,file); return m.preview||src; }
function pxThumbOf(src,file){ return pxVidMeta(src,file).thumb; }

// Captura de frame em fila (1 por vez na aba) a partir de uma URL; usada só pra
// versões leves (~20 MB). Cache positivo e NEGATIVO em localStorage pra não
// repetir download a cada montagem.
window.__pxThumbQueue = window.__pxThumbQueue || Promise.resolve();
// Cache em MEMÓRIA além do localStorage (04/09/2026): quando o localStorage está cheio
// (cache de tasks ocupa quase tudo), setItem falha em silêncio e cada montagem baixava a
// versão leve de novo — 150 downloads do mesmo vídeo em 10 min. Agora cada URL é
// capturada NO MÁXIMO uma vez por sessão, com sucesso ou não; e requisições em
// andamento pra mesma URL compartilham a mesma Promise.
window.__pxThumbMem = window.__pxThumbMem || {};
function pxCaptureFrame(url){
  var key="vt6:"+_pxUrlKey(url);
  var mem=window.__pxThumbMem[key];
  if(mem!==undefined){ return (mem&&typeof mem.then==="function")?mem:Promise.resolve(mem||null); }
  try{ var c=localStorage.getItem(key); if(c){ if(c.indexOf("data:")===0){ window.__pxThumbMem[key]=c; return Promise.resolve(c); } if(c.indexOf("fail:")===0&&Date.now()-parseInt(c.slice(5),10)<7*864e5){ window.__pxThumbMem[key]=null; return Promise.resolve(null); } } }catch(_){}
  var run=function(){ return new Promise(function(resolve){
    var done=false,timer=null;
    var v=document.createElement("video");
    var finish=function(data){
      if(done)return; done=true; clearTimeout(timer);
      try{v.pause();v.removeAttribute("src");v.load();v.remove();}catch(_){}
      window.__pxThumbMem[key]=data||null;
      try{ localStorage.setItem(key, data?data:("fail:"+Date.now())); }catch(_){ try{ if(!data) localStorage.setItem(key,"fail:"+Date.now()); }catch(__){} }
      resolve(data||null);
    };
    try{
      v.crossOrigin="anonymous"; v.muted=true; v.playsInline=true; v.preload="metadata";
      v.onloadedmetadata=function(){ try{ var d=v.duration; v.currentTime=(isFinite(d)&&d>3)?1.5:Math.max(0,Math.min((d||0)*0.2,(d||0.2)-0.01)); }catch(_){ finish(null); } };
      v.onseeked=function(){
        try{
          var w=v.videoWidth||400,h=v.videoHeight||300,scale=Math.min(1,480/w);
          var canvas=document.createElement("canvas");
          canvas.width=Math.round(w*scale); canvas.height=Math.round(h*scale);
          canvas.getContext("2d").drawImage(v,0,0,canvas.width,canvas.height);
          finish(canvas.toDataURL("image/jpeg",0.72));
        }catch(e){ finish(null); }
      };
      v.onerror=function(){ finish(null); };
      timer=setTimeout(function(){ finish(null); },45000);
      v.src=url;
    }catch(_){ finish(null); }
  }); };
  var p=window.__pxThumbQueue.then(run,run);
  window.__pxThumbQueue=p.catch(function(){});
  window.__pxThumbMem[key]=p;
  return p;
}

// Gera thumbnail (dataURL jpeg 320px) a partir de um File/Blob local — sem rede.
function pixelsMakeThumbFromBlob(blob){
  return new Promise(function(resolve){
    try{
      var v=document.createElement("video"),done=false,u=URL.createObjectURL(blob);
      var fin=function(d){ if(done)return; done=true; try{URL.revokeObjectURL(u);}catch(_){} resolve(d||null); };
      v.preload="metadata"; v.muted=true; v.playsInline=true;
      v.onloadedmetadata=function(){ try{ v.currentTime=Math.min(1,(v.duration||2)/2); }catch(_){ fin(null); } };
      v.onseeked=function(){
        try{
          var w=Math.min(320,v.videoWidth||320),r=w/(v.videoWidth||320);
          var c=document.createElement("canvas"); c.width=w; c.height=Math.round((v.videoHeight||180)*r);
          c.getContext("2d").drawImage(v,0,0,c.width,c.height);
          fin(c.toDataURL("image/jpeg",0.6));
        }catch(_){ fin(null); }
      };
      v.onerror=function(){ fin(null); };
      setTimeout(function(){ fin(null); },8000);
      v.src=u;
    }catch(_){ resolve(null); }
  });
}

// Miniatura de vídeo que NÃO baixa o original. Ordem: thumbnail salvo → frame
// capturado da versão leve (fila) → placeholder. Nunca toca no arquivo cru.
function PxVideoThumb(props){
  var src=props.src||"", file=props.file||null;
  var meta=pxVidMeta(src,file);
  var _st=useState(meta.thumb||null), thumb=_st[0], setThumb=_st[1];
  useEffect(function(){
    if(meta.thumb){ setThumb(meta.thumb); return; }
    setThumb(null);
    if(!meta.preview)return;
    var alive=true;
    pxCaptureFrame(meta.preview).then(function(d){
      if(!alive)return;
      if(d){ setThumb(d); if(typeof props.onCaptured==="function"){ try{props.onCaptured(d);}catch(_){} } }
    });
    return function(){ alive=false; };
  },[src, meta.preview, meta.thumb]);
  var st=Object.assign({width:"100%",height:"100%",objectFit:"cover",display:"block",background:"#0f172a"},props.style||{});
  if(thumb) return <img src={thumb} alt="" draggable={false} onClick={props.onClick} style={st}/>;
  var ph=Object.assign({},st,{background:"linear-gradient(135deg,#4c1d95 0%,#312e81 55%,#0f172a 100%)",display:"flex",alignItems:"center",justifyContent:"center",color:"#c4b5fd",position:"relative"});
  return <div onClick={props.onClick} style={ph}>
    <svg width="30" height="30" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" style={{opacity:.9}}>
      <rect x="2" y="2" width="20" height="20" rx="2.5"/><line x1="7" y1="2" x2="7" y2="22"/><line x1="17" y1="2" x2="17" y2="22"/><line x1="2" y1="12" x2="22" y2="12"/>
    </svg>
  </div>;
}

// Player: toca a versão leve quando existe. Original entra só com preload="none"
// (nada é baixado até o usuário dar play). `original` força o arquivo cru.
function PxVideo(props){
  var src=props.src||"", file=props.file||null;
  var meta=pxVidMeta(src,file);
  var real=(props.original||!meta.preview)?src:meta.preview;
  var isPreview=real!==src;
  var _fb=useState(false), fellBack=_fb[0], setFellBack=_fb[1];
  if(fellBack)real=src;
  var preload=props.preload||(isPreview&&!fellBack?"metadata":"none");
  var rest={};
  for(var k in props){ if(props.hasOwnProperty(k)&&k!=="src"&&k!=="file"&&k!=="original"&&k!=="preload"&&k!=="poster"&&k!=="onError"&&k!=="videoRef")rest[k]=props[k]; }
  var onError=function(e){
    var me=e&&e.currentTarget&&e.currentTarget.error;
    if(me&&me.code===1)return;
    if(isPreview&&!fellBack){ console.warn("[video] versão leve falhou, caindo pro original:",src); setFellBack(true); return; }
    if(typeof props.onError==="function")props.onError(e);
  };
  return <video {...rest} ref={props.videoRef} key={real} src={real} poster={props.poster||meta.thumb||undefined} preload={preload} onError={onError}/>;
}

// ═══ Classificação vídeo × design de um card (fonte ÚNICA — 02/09/2026) ═══
// Usada pela tela de Avaliações (06_aprovacoes) E pelos contadores do menu
// (17_gestao_midia). Eram duas cópias e divergiam: card ia pra uma aba e o
// badge vermelho contava na outra. A TAG (contentType) manda; setor e arquivos
// só decidem quando o card não tem tipo definido.
function pxIsVideoTask(t){
  if(!t)return false;
  var ct=String(t.contentType||t.tipo||"").toLowerCase();
  if(ct==="video"||ct==="vídeo"||ct==="video_short"||ct==="corte"||ct==="corte de vídeo"||ct==="corte_de_video"||ct==="video_complexo"||ct==="video_feira"||ct==="video_dinamico")return true;
  if(ct)return false;
  var sect=String(t.sector||"").toLowerCase();
  if(sect==="video"||sect==="vídeo"||sect==="edicao"||sect==="edição")return true;
  var isVidByUrl=function(u){return typeof u==="string" && /\.(mp4|m4v|mov|webm|mkv|ogv|avi|wmv|3gp)(\?|#|$|\/)/i.test(u);};
  var files=Array.isArray(t.files)?t.files:[];
  for(var i=0;i<files.length;i++){
    var f=files[i]; if(!f||f.isAnnotation===true||!f.url)continue;
    if(String(f.type||"").toLowerCase().indexOf("video/")===0)return true;
    if(isVidByUrl(f.url))return true;
  }
  if(t.cover&&isVidByUrl(t.cover))return true;
  return false;
}

// ═══ Formato da arte: FEED × STORY (03/09/2026) ═══
// Arte estática pode ser entregue nos dois tamanhos. O formato fica em
// files[].formato ("feed"|"story"); quando não existe, deduz pela proporção
// (w/h gravados no upload). Story = mais alto que 4:5 (h/w >= 1.45, cobre 9:16).
// Vídeo não entra nessa divisão.
function pxFormatoArte(f){
  if(!f)return "feed";
  var fm=String(f.formato||"").toLowerCase();
  if(fm==="story"||fm==="feed")return fm;
  var w=Number(f.w)||0,h=Number(f.h)||0;
  if(w>0&&h>0&&h/w>=1.45)return "story";
  return "feed";
}
function pxEhStory(f){ return pxFormatoArte(f)==="story"; }
// Ordena estável: feed primeiro, story depois (vídeo conta como feed).
function pxOrdenarFeedStory(arr){
  if(!Array.isArray(arr))return [];
  var feed=[],story=[];
  for(var i=0;i<arr.length;i++){ var f=arr[i]; var isImg=String((f&&f.type)||"").indexOf("image/")===0; (isImg&&pxEhStory(f)?story:feed).push(f); }
  return feed.concat(story);
}
// Dimensões de um File/Blob de imagem (sem rede). Resolve {w,h} ou null.
function pxImageDims(file){
  return new Promise(function(resolve){
    try{
      var u=URL.createObjectURL(file), img=new Image(), done=false;
      var fin=function(v){ if(done)return; done=true; try{URL.revokeObjectURL(u);}catch(_){} resolve(v); };
      img.onload=function(){ fin({w:img.naturalWidth||0,h:img.naturalHeight||0}); };
      img.onerror=function(){ fin(null); };
      setTimeout(function(){ fin(null); },8000);
      img.src=u;
    }catch(_){ resolve(null); }
  });
}

// ═══ "Pronto pra postar" (rosinha no calendário) — 03/09/2026 ═══
// Regra geral: aprovado internamente já vale como pronto. Clientes que usam o portal
// e aprovam eles mesmos precisam do "Aprovado pelo cliente" (aprovacao_final).
// Por enquanto só a Acreforte. Pra incluir outro cliente, adiciona o id aqui.
var PX_CLIENTES_APROVACAO_DO_CLIENTE = ["acreforte"];
function pxProntoPraPostar(t){
  if(!t)return false;
  var st=String(t.status||"");
  if(st==="agendado"||st==="aprovacao_final")return true;
  if(st==="aprovado") return PX_CLIENTES_APROVACAO_DO_CLIENTE.indexOf(String(t.client||""))<0;
  return false;
}

// ═══ Faststart NO UPLOAD (04/09/2026) ═══
// Move o átomo `moov` (índice) pro início do MP4/MOV antes de subir. Sem isso o
// navegador precisa baixar o arquivo inteiro pra começar a tocar ou pra pular na
// barra — cada arrastada virava um download de 100-300 MB (egress do Supabase).
// Não recodifica: mesmos bytes de áudio/vídeo, mesmo tamanho. Se qualquer coisa
// sair do esperado, devolve o arquivo original intacto.
function pxFaststartFile(file){
  var MAX = 700*1024*1024; // acima disso não cabe com folga na memória do navegador
  return new Promise(function(resolve){
    try{
      if(!file || file.size > MAX) { resolve(file); return; }
      var name=String(file.name||"").toLowerCase();
      if(!/\.(mp4|m4v|mov)$/.test(name) && String(file.type||"").indexOf("video/")!==0) { resolve(file); return; }
      var fr=new FileReader();
      fr.onerror=function(){ resolve(file); };
      fr.onload=function(){
        try{
          var buf=fr.result, dv=new DataView(buf), size=buf.byteLength;
          var readAtoms=function(start,end){
            var out=[], off=start;
            while(off+8<=end){
              var alen=dv.getUint32(off), atype=String.fromCharCode(dv.getUint8(off+4),dv.getUint8(off+5),dv.getUint8(off+6),dv.getUint8(off+7)), hsz=8;
              if(alen===1){ if(off+16>end) break; alen=Number(dv.getBigUint64(off+8)); hsz=16; }
              else if(alen===0){ alen=end-off; }
              if(alen<hsz) break;
              out.push({off:off,len:alen,type:atype,hsz:hsz});
              off+=alen;
            }
            return out;
          };
          var atoms=readAtoms(0,size);
          var total=0; for(var i=0;i<atoms.length;i++) total+=atoms[i].len;
          if(!atoms.length || total!==size || atoms[0].type!=="ftyp") { resolve(file); return; }
          var imoov=-1, imdat=-1;
          for(var j=0;j<atoms.length;j++){ if(atoms[j].type==="moov"&&imoov<0) imoov=j; if(atoms[j].type==="mdat"&&imdat<0) imdat=j; }
          if(imoov<0 || imdat<0 || imoov<imdat) { resolve(file); return; } // já é faststart (ou sem moov/mdat)
          for(var k=imoov+1;k<atoms.length;k++){ if(atoms[k].type!=="free"&&atoms[k].type!=="skip"){ resolve(file); return; } }
          var m=atoms[imoov];
          var moov=new Uint8Array(buf.slice(m.off, m.off+m.len));
          // moov comprimido (cmov) → não mexe
          for(var c=0;c<Math.min(64,moov.length-4);c++){ if(moov[c]===0x63&&moov[c+1]===0x6d&&moov[c+2]===0x6f&&moov[c+3]===0x76){ resolve(file); return; } }
          var mdv=new DataView(moov.buffer), delta=m.len, ntab=0, ok=true;
          var CONT={moov:1,trak:1,mdia:1,minf:1,stbl:1};
          var walk=function(start,end){
            var off=start;
            while(off+8<=end){
              var alen=mdv.getUint32(off), t=String.fromCharCode(moov[off+4],moov[off+5],moov[off+6],moov[off+7]), hsz=8;
              if(alen===1){ alen=Number(mdv.getBigUint64(off+8)); hsz=16; } else if(alen===0){ alen=end-off; }
              if(alen<hsz || off+alen>end){ ok=false; return; }
              if(CONT[t]){ walk(off+hsz, off+alen); if(!ok) return; }
              else if(t==="stco"){
                var cnt=mdv.getUint32(off+hsz+4), p=off+hsz+8;
                if(p+cnt*4>off+alen){ ok=false; return; }
                for(var i2=0;i2<cnt;i2++){ var v=mdv.getUint32(p+i2*4)+delta; if(v>0xFFFFFFFF){ ok=false; return; } mdv.setUint32(p+i2*4, v); }
                ntab++;
              } else if(t==="co64"){
                var cnt2=mdv.getUint32(off+hsz+4), p2=off+hsz+8;
                if(p2+cnt2*8>off+alen){ ok=false; return; }
                for(var i3=0;i3<cnt2;i3++){ var v2=mdv.getBigUint64(p2+i3*8)+BigInt(delta); mdv.setBigUint64(p2+i3*8, v2); }
                ntab++;
              }
              off+=alen;
            }
          };
          walk(m.hsz, moov.length);
          if(!ok || ntab===0) { resolve(file); return; }
          var parts=[buf.slice(atoms[0].off, atoms[0].off+atoms[0].len), moov];
          for(var q=1;q<atoms.length;q++){ if(q===imoov) continue; parts.push(buf.slice(atoms[q].off, atoms[q].off+atoms[q].len)); }
          var out=new File(parts, file.name, {type:file.type||"video/mp4", lastModified:file.lastModified||Date.now()});
          if(out.size!==file.size){ resolve(file); return; }
          console.log("[faststart] moov movido pro início:", file.name, ntab+" tabela(s)");
          resolve(out);
        }catch(e){ console.warn("[faststart] falhou, subindo original:", e&&e.message); resolve(file); }
      };
      fr.readAsArrayBuffer(file);
    }catch(_){ resolve(file); }
  });
}

/* ═══════════════════════════════════════════════════════════════════════
   pxDuplicarCard — "copiar e colar" um card COM os arquivos (09/09/2026).
   Pedido pra Hellen fazer versões em espanhol sem refazer tudo.

   Cada anexo (original + preview comprimido) é COPIADO fisicamente no
   Storage pra `tasks/<novoId>/…`. Sem isso os dois cards apontariam pro
   mesmo objeto e apagar um anexo num deles sumia com o arquivo do outro.
   Se a cópia de um arquivo falhar, o anexo entra sem storagePath (só a
   URL antiga) e a função devolve `avisos` pra quem chamou avisar.

   O que vem junto: título "(cópia)", descrição, legenda, cliente/unidade,
   setor, prioridade, tipo, tags, responsáveis, checklist (desmarcado),
   capa, data de publicação. O que zera: comentários, histórico, status
   (volta pra Rascunhos — a versão nova passa pelo fluxo de novo).
   ═══════════════════════════════════════════════════════════════════════ */
async function pxDuplicarCard(t, opts){
  opts=opts||{};
  const sb=window._sb;
  const bucket=sb&&sb.storage?sb.storage.from("agency-files"):null;
  const user=opts.user||(typeof CURRENT_USER!=="undefined"?CURRENT_USER:{id:"",name:"Sistema"});
  const newId=(typeof crypto!=="undefined"&&crypto.randomUUID)?crypto.randomUUID():("dup-"+Date.now()+"-"+Math.random().toString(36).slice(2,7));
  const now=new Date();
  const nowFmt=now.toLocaleDateString("pt-BR")+" às "+now.toLocaleTimeString("pt-BR",{hour:"2-digit",minute:"2-digit"});
  const avisos=[];
  const urlMap={}; // url antiga → url nova (pra capa)
  const _copiar=async function(srcPath){
    if(!srcPath||!bucket||typeof bucket.copy!=="function") return null;
    const base=String(srcPath).split("/").pop();
    const dst="tasks/"+newId+"/"+base;
    const r=await bucket.copy(srcPath,dst);
    if(r&&r.error) throw new Error(r.error.message||"copy falhou");
    const pub=bucket.getPublicUrl(dst);
    return {path:dst,url:(pub&&pub.data&&pub.data.publicUrl)||null};
  };
  const files=[];
  for(const f0 of (Array.isArray(t.files)?t.files:[])){
    if(!f0||f0.uploading) continue;
    const f=Object.assign({},f0,{id:(typeof crypto!=="undefined"&&crypto.randomUUID)?crypto.randomUUID():("f-"+Date.now()+"-"+Math.random().toString(36).slice(2,7))});
    if(f0.purged){ files.push(f); continue; }
    try{
      if(f0.storagePath){
        const c=await _copiar(f0.storagePath);
        if(c){ f.storagePath=c.path; if(c.url){ urlMap[_pxUrlKey(f0.url)]=c.url; f.url=c.url; } }
        else { f.storagePath=null; avisos.push(f0.name||"arquivo"); }
      }
      if(f0.previewPath){
        const p=await _copiar(f0.previewPath);
        if(p){ f.previewPath=p.path; if(p.url&&f0.previewUrl){ urlMap[_pxUrlKey(f0.previewUrl)]=p.url; f.previewUrl=p.url; } }
        else { f.previewPath=null; }
      }
    }catch(e){
      console.warn("[pxDuplicarCard] copia falhou:",f0.name,e&&e.message?e.message:e);
      f.storagePath=null; f.previewPath=null; avisos.push(f0.name||"arquivo");
    }
    files.push(f);
  }
  const _cover=t.cover?(urlMap[_pxUrlKey(t.cover)]||t.cover):null;
  const dup=Object.assign({},t,{
    id:newId,
    title:String(t.title||"Demanda")+" (cópia)",
    status:"rascunhos",
    files:files,
    cover:_cover,
    comments:[],
    checklist:(t.checklist||[]).map(function(c){return Object.assign({},c,{id:"ck-"+Date.now()+"-"+Math.random().toString(36).slice(2,7),done:false});}),
    timeline:[{type:"created",label:"Copiado do card \""+(t.title||"")+"\" por "+user.name+(files.length?" — "+files.length+" arquivo(s) copiado(s)":""),at:now.toISOString(),atFmt:nowFmt,user:user.name}],
    ajustar:false, isAlteracao:false, ajusteOrigin:null,
    completedAt:null, score:null, deletedAt:null, paidAt:null,
    colEnteredAt:now.toISOString(),
    startDate:now.toISOString().split("T")[0],
    createdAt:nowFmt, createdBy:user.name,
    _isDraft:false, _planDraft:false, fromDrive:false,
  });
  return {dup:dup, avisos:avisos};
}
// Wrapper com toast + setTasks, usado pelos três "Duplicar" (CardModal, kanban, calendário)
function pxDuplicarCardEColar(t, setTasks, onDone){
  if(typeof pixelsToast!=="undefined") pixelsToast.info("Copiando card"+((t.files||[]).length?" e "+(t.files||[]).length+" arquivo(s)":"")+"…",2500);
  pxDuplicarCard(t).then(function(r){
    setTasks(function(p){ return (p||[]).concat([r.dup]); });
    if(typeof pixelsToast!=="undefined"){
      if(r.avisos.length) pixelsToast.warning("Card copiado, mas "+r.avisos.length+" arquivo(s) não foram copiados ("+r.avisos.slice(0,2).join(", ")+"). Eles apontam pro original.",7000);
      else pixelsToast.success("Card copiado pra Rascunhos: \""+r.dup.title+"\".",4500);
    }
    if(onDone) onDone(r.dup);
  }).catch(function(e){
    console.warn("[pxDuplicarCardEColar]",e);
    if(typeof pixelsToast!=="undefined") pixelsToast.error("Não consegui copiar o card: "+(e&&e.message?e.message:e));
  });
}

// ═══ Recorrência "anual no mesmo dia da semana" — yearly_nth (09/09/2026) ═══
// Dia dos Pais = 2º domingo de agosto, Dia das Mães = 2º domingo de maio. A regra sai da
// própria data original do evento: mês + dia da semana + ordinal (1º..5º). Sem campo novo.
function pxNthMatch(origISO, candISO){
  try{
    const o=new Date(String(origISO).slice(0,10)+"T12:00"), c=new Date(String(candISO).slice(0,10)+"T12:00");
    return o.getMonth()===c.getMonth() && o.getDay()===c.getDay() && Math.ceil(o.getDate()/7)===Math.ceil(c.getDate()/7);
  }catch(_){ return false; }
}
function pxNthDateInYear(origISO, year){
  const o=new Date(String(origISO).slice(0,10)+"T12:00");
  const n=Math.ceil(o.getDate()/7), dow=o.getDay(), m=o.getMonth();
  const first=new Date(year,m,1);
  let d=1+((dow-first.getDay()+7)%7)+(n-1)*7;
  const last=new Date(year,m+1,0).getDate();
  while(d>last) d-=7; // "5º domingo" que não existe naquele ano → último
  return year+"-"+String(m+1).padStart(2,"0")+"-"+String(d).padStart(2,"0");
}
// ═══ Recorrência "anual atrelada à Páscoa" — yearly_easter (09/09/2026) ═══
// Carnaval (Páscoa−47), Quarta de Cinzas (−46), Sexta-feira Santa (−2), Páscoa (0),
// Corpus Christi (+60). O deslocamento sai da própria data original do evento
// (data − Páscoa daquele ano). Sem campo novo. Páscoa pelo algoritmo de Meeus/Jones/Butcher.
function pxEaster(year){
  const a=year%19, b=Math.floor(year/100), c=year%100, d=Math.floor(b/4), e=b%4,
        f=Math.floor((b+8)/25), g=Math.floor((b-f+1)/3), h=(19*a+b-d-g+15)%30,
        i=Math.floor(c/4), k=c%4, l=(32+2*e+2*i-h-k)%7, m=Math.floor((a+11*h+22*l)/451),
        mo=Math.floor((h+l-7*m+114)/31), da=((h+l-7*m+114)%31)+1;
  return new Date(year,mo-1,da,12);
}
function pxEasterOffset(origISO){
  const o=new Date(String(origISO).slice(0,10)+"T12:00");
  return Math.round((o-pxEaster(o.getFullYear()))/86400000);
}
function pxEasterDateInYear(origISO, year){
  const off=pxEasterOffset(origISO);
  const d=pxEaster(year); d.setDate(d.getDate()+off);
  return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0");
}
function pxEasterMatch(origISO, candISO){
  try{ return pxEasterDateInYear(origISO, Number(String(candISO).slice(0,4)))===String(candISO).slice(0,10); }catch(_){ return false; }
}
function pxEasterLabel(origISO){
  try{
    const off=pxEasterOffset(origISO);
    const nomes={"-48":"segunda de Carnaval","-47":"terça de Carnaval","-46":"Quarta de Cinzas","-3":"Quinta-feira Santa","-2":"Sexta-feira Santa","-1":"Sábado de Aleluia","0":"Páscoa","60":"Corpus Christi"};
    if(nomes[String(off)]) return nomes[String(off)];
    return "Páscoa "+(off<0?"−":"+")+Math.abs(off)+" dia"+(Math.abs(off)===1?"":"s");
  }catch(_){ return ""; }
}
function pxNthLabel(origISO){
  try{
    const o=new Date(String(origISO).slice(0,10)+"T12:00");
    const dias=["domingo","segunda","terça","quarta","quinta","sexta","sábado"];
    const meses=["janeiro","fevereiro","março","abril","maio","junho","julho","agosto","setembro","outubro","novembro","dezembro"];
    return Math.ceil(o.getDate()/7)+"º "+dias[o.getDay()]+" de "+meses[o.getMonth()];
  }catch(_){ return ""; }
}

// ═══════════════════════════════════════════════════════════════════
// pxEscurecerCor — escurece um hex pra usar como fundo de chip em cima
// de um card colorido (tag "SOMENTE STORY" no Calendário de publicações).
// f = 0..1 (quanto maior, mais escuro). Devolve sempre um hex de 6.
// ═══════════════════════════════════════════════════════════════════
function pxEscurecerCor(hex,f){
  var h=String(hex||"").trim().replace("#","");
  if(h.length===3) h=h[0]+h[0]+h[1]+h[1]+h[2]+h[2];
  if(!/^[0-9a-fA-F]{6}$/.test(h)) return "#0f172a";
  var k=(typeof f==="number"?f:0.42);
  if(k<0)k=0; if(k>1)k=1;
  function _c(i){
    var v=Math.round(parseInt(h.slice(i,i+2),16)*(1-k));
    if(v<0)v=0; if(v>255)v=255;
    var s=v.toString(16);
    return s.length<2?("0"+s):s;
  }
  return "#"+_c(0)+_c(2)+_c(4);
}

// ======= 01_dashboard.jsx =======

// Barra de progresso simples
const Bar=({v,color,h=6})=>(
  <div style={{width:"100%",height:h,background:C.b1,borderRadius:99,overflow:"hidden"}}>
    <div style={{width:`${Math.min(100,Math.max(0,v))}%`,height:"100%",background:color||C.a,borderRadius:99,transition:"width .4s ease"}}/>
  </div>
);

/* ─── DASHBOARD ADMIN PREMIUM (Vinicius, Gustavo) ───
   Nível V4/G4: visão executiva completa com foco OPERACIONAL primeiro
   Estrutura:
   1. Banner de AÇÕES URGENTES (portal, atrasos, publicações, aprovações)
   2. Pipeline Operacional (3 fluxos lado a lado)
   3. Andamento de CADA Colaborador (tabela rica)
   4. Aprovações Pendentes (copys + artes)
   5. Publicações (hoje/semana/atrasadas)
   6. Solicitações do Portal
   7. KPIs Financeiros (MRR, ROAS, LTV, Churn, NPS)
   8. Top Clientes + Clientes em Risco
   9. Panorama completo dos Clientes
   10. Pagamentos em Atraso + Demandas Atrasadas
*/
function DashPartner({user,isViewing,tasks:propTasks,setTasks:propSetTasks,notifs,isMob}){
  const [openCard,setOpenCard]=useState(null);
  // ═══ TAB ATIVA ═══ (alerta | demandas | metricas | metas)
  const [activeTab,setActiveTab]=useState(()=>{
    try{return localStorage.getItem("pixels-dash-tab")||"alerta";}catch{return "alerta";}
  });
  // ═══ Mês selecionado pro card de Pagamento por Demanda (default: mês corrente) ═══
  const [payMonth,setPayMonth]=useState(()=>{
    try{
      const saved=localStorage.getItem("pixels-pay-month");
      if(saved)return saved;
    }catch(e){}
    const now=new Date();
    return now.getFullYear()+"-"+String(now.getMonth()+1).padStart(2,"0");
  });
  useEffect(()=>{try{localStorage.setItem("pixels-pay-month",payMonth);}catch(e){}},[payMonth]);
  useEffect(()=>{try{localStorage.setItem("pixels-dash-tab",activeTab);}catch(e){}},[activeTab]);
  const setTasks=propSetTasks||(()=>{});
  const adminCardPerms=(()=>{try{const s=localStorage.getItem("pixels-perms-"+(CURRENT_USER).id);return s?{...DEFAULT_PERMS,...JSON.parse(s)}:DEFAULT_PERMS;}catch{return DEFAULT_PERMS;}})();
  const allTasks=propTasks||[];
  const active=allTasks.filter(t=>!t.deletedAt);
  const ativas=active.filter(t=>t.status!=="aprovado"&&t.status!=="publicado"&&t.status!=="pausado");
  const hojeStr=(()=>{const d=new Date();return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0");})();
  const hoje=new Date();hoje.setHours(0,0,0,0);
  const ha7d=new Date(hoje);ha7d.setDate(hoje.getDate()-7);
  const ha30d=new Date(hoje);ha30d.setDate(hoje.getDate()-30);
  const daqui7d=new Date(hoje);daqui7d.setDate(hoje.getDate()+7);

  // ═══ Demandas CLIENTES (kanban normal) ═══
  const clientStatuses=["demanda","alteracao_copy","preencher_material","recebida","execucao","avaliacao","aprovado","agendado","publicado","pausado","reprovado"];
  const clientTasks=active.filter(t=>clientStatuses.includes(t.status));
  const clientAtivas=clientTasks.filter(t=>t.status!=="aprovado"&&t.status!=="publicado"&&t.status!=="pausado");

  // ═══ Demandas INTERNAS ═══
  const internStatuses=["interno_demanda","interno_execucao","interno_avaliacao","interno_aprovado","interno_executado"];
  const internTasks=active.filter(t=>internStatuses.includes(t.status));
  const internAtivas=internTasks.filter(t=>t.status!=="interno_aprovado"&&t.status!=="interno_executado");

  // ═══ Solicitações do PORTAL (origem=portal) ═══
  const portalRequests=active.filter(t=>t.origem==="portal");
  const portalPendentes=portalRequests.filter(t=>t.status==="interno_demanda"||(t.assignees||[]).length===0);
  const portalRecentes=portalRequests.filter(t=>t.createdAt&&new Date(t.createdAt)>=ha7d);

  // ═══ KPIs Executivos ═══
  const mrr=CLIENTS.reduce((a,c)=>a+c.contract,0);
  const avgRoas=(CLIENTS.reduce((a,c)=>a+(c.meta?.roas||0),0)/CLIENTS.length).toFixed(1);
  const totalLeads=CLIENTS.reduce((a,c)=>a+(c.meta?.leads||0)+(c.google?.leads||0),0);
  const avgHealth=Math.round(CLIENTS.reduce((a,c)=>a+c.health,0)/CLIENTS.length);
  const avgNps=Math.round(CLIENTS.reduce((a,c)=>a+(c.nps||0),0)/CLIENTS.length);
  const atrasadas=ativas.filter(t=>{const d=daysLeft(t.deadline);return d!==null&&d<0;});
  const noPrazoCount=ativas.length-atrasadas.length;
  const noPrazoPct=ativas.length>0?Math.round((noPrazoCount/ativas.length)*100):100;
  const ltvMedio=Math.round(CLIENTS.reduce((a,c)=>a+(c.contract*24),0)/CLIENTS.length); // LTV = 24 meses médios
  const clientesAtivos=CLIENTS.length;

  // ═══ Riscos críticos (exigem ação agora) ═══
  const riscosCriticos=[];
  CLIENTS.forEach(c=>{
    if(c.health<60)riscosCriticos.push({type:"saude",client:c,msg:`Saúde em ${c.health}%`,color:"#dc2626"});
    if(c.payment&&c.payment.status==="atrasado")riscosCriticos.push({type:"pag",client:c,msg:"Pagamento atrasado",color:"#dc2626"});
    if(c.lastMeeting){
      const p=c.lastMeeting.split("/");
      const diasSemReuniao=Math.floor((new Date()-new Date(p[2]+"-"+p[1]+"-"+p[0]))/(1000*60*60*24));
      if(diasSemReuniao>30)riscosCriticos.push({type:"reuniao",client:c,msg:`Reunião há ${diasSemReuniao}d`,color:"#ea580c"});
    }
  });
  TEAM.filter(u=>u.level>1).forEach(u=>{
    const uTasks=ativas.filter(t=>t.assignee===u.id||(t.assignees||[]).includes(u.id));
    if(uTasks.length>=10)riscosCriticos.push({type:"sobrecarga",user:u,msg:`Sobrecarga: ${uTasks.length} demandas ativas`,color:"#ea580c"});
  });

  // ═══ Pipeline (funil) ═══
  const pipeline=[
    {label:"Copys",status:"demanda",color:"#a140ff",icon:"📝"},
    {label:"Recebidas",status:"recebida",color:"#ec4899",icon:"📥"},
    {label:"Execução",status:"execucao",color:"#eab308",icon:"⚙"},
    {label:"Avaliação",status:"avaliacao",color:"#f97316",icon:"👀"},
    {label:"Aprovadas",status:"aprovado",color:"#16a34a",icon:"✅"},
    {label:"Agendadas",status:"agendado",color:"#2563eb",icon:"📅"},
  ].map(s=>({...s,count:active.filter(t=>t.status===s.status).length}));
  const pipelineMax=Math.max(...pipeline.map(p=>p.count),1);

  // ═══ Top Clientes por MRR ═══
  const topClientes=[...CLIENTS].sort((a,b)=>b.contract-a.contract).slice(0,5);

  // ═══ Clientes em risco ═══
  const clientesRisco=CLIENTS.filter(c=>c.health<60||(c.payment&&c.payment.status==="atrasado"))
    .sort((a,b)=>a.health-b.health);

  // ═══ Produtividade da equipe (últimos 30d) — reusa hoje/ha30d já declarados acima
  const equipeStats=TEAM.filter(u=>u.level>1).map(u=>{
    const done30d=active.filter(t=>{
      if(t.status!=="aprovado"||!t.completedAt)return false;
      if(t.assignee!==u.id&&!(t.assignees||[]).includes(u.id))return false;
      return new Date(t.completedAt)>=ha30d;
    }).length;
    const activeNow=ativas.filter(t=>t.assignee===u.id||(t.assignees||[]).includes(u.id)).length;
    const lateNow=atrasadas.filter(t=>t.assignee===u.id||(t.assignees||[]).includes(u.id)).length;
    return {user:u,done30d,activeNow,lateNow};
  }).sort((a,b)=>b.done30d-a.done30d);
  const maxDone=Math.max(...equipeStats.map(e=>e.done30d),1);

  // ═══ Histórico de produção da agência (mini-charts + chart evolutivo) ═══
  const agencyCompletedSeries=(()=>{
    const compute=(days)=>{
      const today=new Date();today.setHours(0,0,0,0);
      const arr=Array(days).fill(0);
      (allTasks||[]).forEach(t=>{
        if(!t.completedAt)return;
        const d=new Date(t.completedAt);d.setHours(0,0,0,0);
        const diff=Math.floor((today-d)/86400000);
        if(diff>=0&&diff<days)arr[days-1-diff]++;
      });
      return arr;
    };
    return{"7d":compute(7),"30d":compute(30),"90d":compute(90)};
  })();
  const last6AgencyCompletions=agencyCompletedSeries["7d"].slice(-6);

  // ═══ Pagamentos atrasados ═══
  const pagAtras=CLIENTS.filter(c=>c.payment&&c.payment.status==="atrasado");

  // ═══ Minhas Demandas (card grande + 5 laterais) — tanto clientes quanto internas ═══
  const myTasks=active.filter(t=>{
    const isMine=t.assignee===user.id||(t.assignees||[]).includes(user.id);
    if(!isMine)return false;
    // Ignora concluídas/publicadas/pausadas
    if(["aprovado","publicado","pausado","interno_aprovado","interno_executado"].includes(t.status))return false;
    return true;
  });
  // Usa o sortByPriority do 12_dashboard.jsx (disponível no bundle)
  const mySorted=typeof sortByPriority==="function"?sortByPriority(myTasks):myTasks;
  const myMain=mySorted[0]||null;
  const myNext=mySorted.slice(1,6);
  const myMainPrio=myMain&&typeof getDemandPriority==="function"?getDemandPriority(myMain):null;
  const myMainCl=myMain?CLIENTS.find(c=>c.id===myMain.client):null;

  // ═══ Publicações ═══
  const agendadas=active.filter(t=>t.status==="agendado");
  const pubHoje=agendadas.filter(t=>t.publishDate===hojeStr);
  const pubAtrasadas=agendadas.filter(t=>t.publishDate&&t.publishDate<hojeStr);
  const pubSemana=agendadas.filter(t=>{
    if(!t.publishDate)return false;
    const pd=new Date(t.publishDate);
    return pd>=hoje&&pd<=daqui7d;
  });

  // ═══ Aprovações pendentes ═══
  const copysPendentes=clientTasks.filter(t=>t.status==="demanda"&&!t.ajustar);
  const artesPendentes=clientTasks.filter(t=>t.status==="avaliacao");
  const aprovacoesInternas=internTasks.filter(t=>t.status==="interno_avaliacao");

  // ═══ Andamento detalhado por colaborador ═══
  const equipeDetalhe=TEAM.filter(u=>u.level>1).map(u=>{
    const todas=active.filter(t=>t.assignee===u.id||(t.assignees||[]).includes(u.id));
    const emAtv=todas.filter(t=>!["aprovado","publicado","pausado","interno_aprovado","interno_executado"].includes(t.status));
    const emExec=emAtv.filter(t=>t.status==="execucao"||t.status==="interno_execucao");
    const emAval=emAtv.filter(t=>t.status==="avaliacao"||t.status==="interno_avaliacao");
    const atras=emAtv.filter(t=>{const d=daysLeft(t.deadline);return d!==null&&d<0;});
    const urg=emAtv.filter(t=>{const d=daysLeft(t.deadline);return d===0;});
    const done30d=todas.filter(t=>{
      if(t.status!=="aprovado"&&t.status!=="interno_aprovado"&&t.status!=="interno_executado"&&t.status!=="publicado")return false;
      if(!t.completedAt)return false;
      return new Date(t.completedAt)>=ha30d;
    }).length;
    const prazoPct=emAtv.length>0?Math.round(((emAtv.length-atras.length-urg.length)/emAtv.length)*100):100;
    const saudeC=prazoPct>=80?"#16a34a":prazoPct>=60?"#eab308":"#dc2626";
    return {user:u,emAtv:emAtv.length,emExec:emExec.length,emAval:emAval.length,atras:atras.length,urg:urg.length,done30d,prazoPct,saudeC};
  }).sort((a,b)=>b.done30d-a.done30d);

  // ═══ Ações urgentes (tudo que precisa atenção AGORA) ═══
  const acoesUrgentes=[];
  if(portalPendentes.length>0)acoesUrgentes.push({type:"portal",count:portalPendentes.length,label:"Nova(s) solicitação(ões) do portal",color:"#2563eb",icon:"📩"});
  if(pubAtrasadas.length>0)acoesUrgentes.push({type:"pubatras",count:pubAtrasadas.length,label:"Publicação(ões) atrasada(s)",color:"#dc2626",icon:"📤"});
  if(atrasadas.length>0)acoesUrgentes.push({type:"atras",count:atrasadas.length,label:"Demanda(s) atrasada(s)",color:"#dc2626",icon:"🔥"});
  if(copysPendentes.length>0)acoesUrgentes.push({type:"copys",count:copysPendentes.length,label:"Copy(s) aguardando aprovação",color:"#7c3aed",icon:"📝"});
  if(artesPendentes.length>0)acoesUrgentes.push({type:"artes",count:artesPendentes.length,label:"Arte(s) aguardando aprovação",color:"#16a34a",icon:"🎨"});
  if(pubHoje.length>0)acoesUrgentes.push({type:"pubhoje",count:pubHoje.length,label:"Publicação(ões) hoje",color:"#2563eb",icon:"🚀"});
  if(pagAtras.length>0)acoesUrgentes.push({type:"pag",count:pagAtras.length,label:"Pagamento(s) atrasado(s)",color:"#dc2626",icon:"💸"});

  // ═══ NOVAS COMPUTAÇÕES PARA AS TABS ═══

  // Brief do Dia — narrativa que sintetiza ações urgentes em texto
  const briefParts=[];
  if(atrasadas.length>0)briefParts.push(`${atrasadas.length} demanda${atrasadas.length>1?"s atrasadas":" atrasada"}`);
  if(pagAtras.length>0)briefParts.push(`${pagAtras.length} pagamento${pagAtras.length>1?"s vencidos":" vencido"}`);
  if(pubAtrasadas.length>0)briefParts.push(`${pubAtrasadas.length} publicação${pubAtrasadas.length>1?"ões atrasadas":" atrasada"}`);
  if(pubHoje.length>0)briefParts.push(`${pubHoje.length} publicação${pubHoje.length>1?"ões hoje":" hoje"}`);
  const aprovTotal=copysPendentes.length+artesPendentes.length;
  if(aprovTotal>0)briefParts.push(`${aprovTotal} aprovação${aprovTotal>1?"ões pendentes":" pendente"}`);

  // Total de alertas para badge na tab
  const alertaCount=atrasadas.length+pagAtras.length+pubAtrasadas.length+clientesRisco.length;

  // Tab Demandas — KPIs operacionais
  const emProducao=active.filter(t=>t.status==="execucao"||t.status==="interno_execucao").length;
  const emAvaliacao=active.filter(t=>t.status==="avaliacao"||t.status==="interno_avaliacao").length;
  const aprovadasTotal=active.filter(t=>t.status==="aprovado"||t.status==="interno_aprovado").length;
  const publicadasMes=active.filter(t=>{
    if(t.status!=="publicado"||!t.completedAt)return false;
    const d=new Date(t.completedAt);
    return d.getFullYear()===hoje.getFullYear()&&d.getMonth()===hoje.getMonth();
  }).length;

  // Carga por pessoa (avatar + barra horizontal)
  const cargaPorPessoa=TEAM.filter(u=>u.level>1).map(u=>{
    const count=ativas.filter(t=>t.assignee===u.id||(t.assignees||[]).includes(u.id)).length;
    return {user:u,count};
  }).sort((a,b)=>b.count-a.count);
  const maxCarga=Math.max(...cargaPorPessoa.map(c=>c.count),1);

  // Velocity — entregas por semana (4 últimas semanas)
  const velocity=[3,2,1,0].map(weeksAgo=>{
    const start=new Date(hoje);start.setDate(hoje.getDate()-(weeksAgo+1)*7);
    const end=new Date(hoje);end.setDate(hoje.getDate()-weeksAgo*7);
    return active.filter(t=>{
      if(t.status!=="aprovado"&&t.status!=="publicado"&&t.status!=="interno_aprovado"&&t.status!=="interno_executado")return false;
      if(!t.completedAt)return false;
      const d=new Date(t.completedAt);
      return d>=start&&d<end;
    }).length;
  });
  const velocityMax=Math.max(...velocity,1);
  const velocityAvg=(velocity.reduce((a,b)=>a+b,0)/velocity.length).toFixed(1);
  const velocityTrend=velocity[3]>velocity[0]?"↑":velocity[3]<velocity[0]?"↓":"→";

  // Gargalos detectados — coluna com cards parados há 4+ dias
  const gargalos=pipeline.map(p=>{
    const stuck=active.filter(t=>{
      if(t.status!==p.status||!t.colEnteredAt)return false;
      const days=Math.floor((new Date()-new Date(t.colEnteredAt))/(1000*60*60*24));
      return days>=4;
    }).length;
    return {label:p.label,color:p.color,stuck};
  }).filter(g=>g.stuck>0);

  // Tab Métricas — 4 hero numbers
  const spendTotal=CLIENTS.reduce((a,c)=>a+(c.meta?.spend||0)+(c.google?.spend||0),0);
  const followersTotal=CLIENTS.reduce((a,c)=>a+(c.social?.followers||0),0);
  // totalLeads e avgRoas já calculados acima

  // Top 5 ROAS / Bottom (alerta)
  const top5Roas=[...CLIENTS].filter(c=>(c.meta?.roas||0)>0).sort((a,b)=>(b.meta?.roas||0)-(a.meta?.roas||0)).slice(0,5);
  const bottomRoas=CLIENTS.filter(c=>(c.meta?.roas||0)>0&&(c.meta?.roas||0)<2).sort((a,b)=>(a.meta?.roas||0)-(b.meta?.roas||0));

  // Tab Metas — metas hardcoded (depois cria tela editável)
  const METAS={mrr:75000,novosClientesMes:3,nps:90,churn:3};
  const novosClientesMes=CLIENTS.filter(c=>{
    if(!c.since)return false;
    // since formato "Mar 2025" — comparação simplificada com mês atual
    const meses=["Jan","Fev","Mar","Abr","Mai","Jun","Jul","Ago","Set","Out","Nov","Dez"];
    const atual=meses[hoje.getMonth()]+" "+hoje.getFullYear();
    return c.since===atual;
  }).length;
  const churnPct=0; // placeholder — sem tracking real ainda

  // Health Score composto da agência (0-100)
  const slaScore=noPrazoPct;
  const npsScore=avgNps;
  const churnScore=Math.max(0,100-churnPct*20);
  const growthScore=80; // placeholder — depois conectar com histórico real
  const healthScore=Math.round(slaScore*0.3+npsScore*0.3+churnScore*0.2+growthScore*0.2);

  // Receita histórica 12 meses — placeholder com dados sintéticos crescentes
  const receita12m=Array.from({length:12},(_,i)=>{
    const fator=0.55+i*0.04; // crescimento simulado
    return Math.round(mrr*fator);
  });
  const receita12mMax=Math.max(...receita12m);

  // ── Auto-normalizar títulos antigos ─────────────────────────
  // Roda silenciosamente uma vez por navegador (flag em localStorage).
  // Só sócios disparam (level 1) — pra evitar problemas de RLS com colaboradores.
  // smartFormatTitle é idempotente, então rodar de novo sem flag não causa nenhum efeito.
  const _migratedRef=useRef(false);
  useEffect(()=>{
    if(_migratedRef.current)return;
    if(!user||user.level!==1)return;
    if(!allTasks||allTasks.length===0)return;
    const FLAG_KEY="pixels-title-migration-v8";
    try{if(localStorage.getItem(FLAG_KEY))return;}catch(e){}
    const candidates=allTasks.filter(t=>{
      if(!t||!t.title||t.deletedAt)return false;
      return smartFormatTitle(t.title)!==t.title;
    });
    if(candidates.length>0){
      setTasks(prev=>prev.map(t=>{
        if(!t||!t.title)return t;
        const newTitle=smartFormatTitle(t.title);
        return newTitle===t.title?t:{...t,title:newTitle};
      }));
      pixelsToast.info(`${candidates.length} título(s) padronizado(s) automaticamente.`,5000);
    }
    try{localStorage.setItem(FLAG_KEY,"1");}catch(e){}
    _migratedRef.current=true;
  },[allTasks.length]);

  return <div style={{display:"flex",flexDirection:"column",gap:16,maxWidth:1600,margin:"0 auto",width:"100%",padding:isMob?"0 4px":0}}>
    {openCard&&<CardModal task={openCard} tasks={allTasks} setTasks={setTasks} onClose={()=>setOpenCard(null)} currentUser={CURRENT_USER} cardPerms={adminCardPerms}/>}
    {isViewing&&<div style={{display:"inline-flex",alignItems:"center",gap:10,background:"linear-gradient(135deg,#fff7ed 0%,#ffedd5 100%)",border:"1px solid #fed7aa",borderRadius:12,padding:"7px 15px 7px 9px",boxShadow:"0 2px 10px rgba(234,88,12,.10)",alignSelf:"flex-start"}}>
      <span style={{width:27,height:27,borderRadius:9,background:"linear-gradient(135deg,#f59e0b,#ea580c)",display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0,boxShadow:"0 3px 8px rgba(234,88,12,.35)"}}>
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="2.3" strokeLinecap="round" strokeLinejoin="round"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>
      </span>
      <span style={{lineHeight:1.2}}>
        <span style={{display:"block",color:"#c2410c",fontSize:9,fontWeight:800,letterSpacing:.7,textTransform:"uppercase"}}>Visualizando como</span>
        <span style={{display:"block",color:"#7c2d12",fontSize:13.5,fontWeight:800,letterSpacing:-.25}}>{user.name}</span>
      </span>
    </div>}

    {/* ═══ PAGAMENTO POR DEMANDA — Bloco consolidado (André + Maria + Guilherme) ═══ */}
    <FreelancerPaymentsBlock tasks={allTasks} refMonth={payMonth} onChangeMonth={setPayMonth} isMob={isMob}/>

    {/* ═══ HEADER FIXO — MINHAS DEMANDAS ═══ */}
    {myTasks.length>0&&(
      <div style={{display:"grid",gridTemplateColumns:isMob?"1fr":"minmax(0,1fr) 280px",gap:12}}>
        {/* CARD GRANDE — prioridade máxima */}
        {myMain&&(
          <div onClick={()=>setOpenCard(myMain)}
            style={{background:"#fff",border:"0.5px solid #e5e7eb",borderLeft:`5px solid ${myMainPrio?.bg||"#16a34a"}`,borderRadius:12,padding:"18px 20px",cursor:"pointer",display:"flex",flexDirection:"column",gap:12,transition:"all .12s"}}
            onMouseEnter={e=>{e.currentTarget.style.borderColor="#a140ff";}}
            onMouseLeave={e=>{e.currentTarget.style.borderColor="#e5e7eb";}}>
            <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:10}}>
              <div style={{display:"flex",alignItems:"center",gap:8}}>
                {myMainPrio&&<span style={{background:myMainPrio.bg,color:"#fff",borderRadius:5,padding:"2px 8px",fontSize:9,fontWeight:600,letterSpacing:.5}}>
                  {myMainPrio.level===0?"ALTERAÇÃO":myMainPrio.level===1?"ATRASADO":myMainPrio.level===2?"URGENTE":"NO PRAZO"}
                </span>}
                <span style={{color:"#64748b",fontSize:10,fontWeight:600,textTransform:"uppercase",letterSpacing:.4}}>Minha próxima demanda</span>
              </div>
              {myMainCl&&<span style={{background:"#f1f5f9",color:"#475569",borderRadius:5,padding:"2px 8px",fontSize:10,fontWeight:700}}>{myMainCl.abbr}</span>}
            </div>
            <div style={{color:"#0f172a",fontWeight:700,fontSize:18,lineHeight:1.3,letterSpacing:-.3}}>{myMain.title}</div>
            {myMain.desc&&<div style={{color:"#64748b",fontSize:12,lineHeight:1.6}}>{myMain.desc.replace(/<[^>]*>/g,"").slice(0,120)}{myMain.desc.length>120?"...":""}</div>}
            <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",paddingTop:10,borderTop:"0.5px solid #f1f5f9",marginTop:"auto"}}>
              <span style={{color:myMainPrio?.bg||"#16a34a",fontSize:11,fontWeight:700}}>
                {myMainPrio?.icon&&myMainPrio.icon+" "}{myMainPrio?.label||"No prazo"}
              </span>
              <span style={{color:"#2563eb",fontSize:12,fontWeight:600}}>Abrir →</span>
            </div>
          </div>
        )}

        {/* 5 CARDS LATERAIS — próximas */}
        <div style={{display:"flex",flexDirection:"column",gap:6}}>
          {myNext.length===0&&<div style={{background:"#f8fafc",border:"0.5px solid #e5e7eb",borderRadius:10,padding:"18px",textAlign:"center"}}>
            <div style={{fontSize:24,marginBottom:6}}>🎉</div>
            <div style={{color:"#64748b",fontSize:11,fontWeight:600}}>Só a principal por enquanto</div>
          </div>}
          {myNext.map(t=>{
            const prio=typeof getDemandPriority==="function"?getDemandPriority(t):{bg:"#94a3b8",label:"",icon:""};
            const cl=CLIENTS.find(c=>c.id===t.client);
            const dl=typeof daysLeft==="function"?daysLeft(t.deadline):null;
            return <div key={t.id} onClick={()=>setOpenCard(t)}
              style={{background:"#fff",border:"0.5px solid #e5e7eb",borderLeft:`3px solid ${prio.bg}`,borderRadius:8,padding:"10px 12px",cursor:"pointer",display:"flex",alignItems:"center",gap:10,transition:"all .1s"}}
              onMouseEnter={e=>{e.currentTarget.style.transform="translateX(2px)";e.currentTarget.style.borderColor="#cbd5e1";}}
              onMouseLeave={e=>{e.currentTarget.style.transform="";e.currentTarget.style.borderColor="#e5e7eb";}}>
              <div style={{flex:1,minWidth:0}}>
                <div style={{color:"#0f172a",fontWeight:600,fontSize:12,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{t.title}</div>
                <div style={{color:"#94a3b8",fontSize:10,marginTop:2}}>{cl?.abbr||(t.status?.startsWith("interno_")?"Interna":"—")}</div>
              </div>
              <span style={{color:prio.bg,fontWeight:700,fontSize:10,flexShrink:0}}>
                {prio.level<=1?prio.label:dl===null?"—":dl===0?"Hoje":dl+"d"}
              </span>
            </div>;
          })}
          {/* Mini totais */}
          <div style={{display:"grid",gridTemplateColumns:_pxMob()?"1fr":"1fr 1fr",gap:6,marginTop:2}}>
            <div style={{background:"#f8fafc",border:"0.5px solid #e5e7eb",borderRadius:8,padding:"8px",textAlign:"center"}}>
              <div style={{color:"#0f172a",fontWeight:600,fontSize:16}}>{myTasks.length}</div>
              <div style={{color:"#94a3b8",fontSize:9,fontWeight:600,textTransform:"uppercase"}}>Minhas</div>
            </div>
            <div style={{background:"#f8fafc",border:"0.5px solid #e5e7eb",borderRadius:8,padding:"8px",textAlign:"center"}}>
              <div style={{color:"#dc2626",fontWeight:600,fontSize:16}}>{myTasks.filter(t=>{const d=daysLeft(t.deadline);return d!==null&&d<0;}).length}</div>
              <div style={{color:"#94a3b8",fontSize:9,fontWeight:600,textTransform:"uppercase"}}>Atrasadas</div>
            </div>
          </div>
        </div>
      </div>
    )}

    {/* ═══ TAB BAR (roxo Pixels) ═══ */}
    <div style={{display:"flex",gap:isMob?4:6,padding:isMob?4:6,background:"#fff",border:"0.5px solid #e5e7eb",borderRadius:12,overflowX:"auto"}}>
      {[
        {id:"alerta",label:isMob?"Alerta":"Alerta",badge:alertaCount},
        {id:"demandas",label:isMob?"Demandas":"Demandas"},
        {id:"metricas",label:isMob?"Métricas":"Métricas"},
        {id:"metas",label:isMob?"Metas":"Metas"},
      ].map(t=>(
        <button key={t.id} onClick={()=>setActiveTab(t.id)} style={{
          flex:isMob?"0 0 auto":1,
          background:activeTab===t.id?"#a140ff":"transparent",
          border:"none",borderRadius:8,padding:isMob?"8px 14px":"10px 18px",
          fontSize:isMob?12:13,fontWeight:activeTab===t.id?700:500,
          color:activeTab===t.id?"#fff":"#64748b",cursor:"pointer",
          boxShadow:activeTab===t.id?"0 4px 14px rgba(161,64,255,0.35)":"none",
          whiteSpace:"nowrap",transition:"all .18s",
          display:"flex",alignItems:"center",justifyContent:"center",gap:7,
        }}>
          {t.label}
          {t.badge>0&&<span style={{background:activeTab===t.id?"rgba(255,255,255,0.25)":"#a140ff",color:"#fff",borderRadius:99,padding:"1px 7px",fontSize:10,fontWeight:600,minWidth:18,textAlign:"center"}}>{t.badge}</span>}
        </button>
      ))}
    </div>

    {/* ═══ TAB ALERTA — Brief do Dia ═══ */}
    {activeTab==="alerta"&&(
      <div style={{background:"#faf5ff",border:"0.5px solid #e9d5ff",borderRadius:12,padding:"16px 18px"}}>
        <div style={{color:"#a140ff",fontSize:10,fontWeight:700,textTransform:"uppercase",letterSpacing:.6,marginBottom:8}}>Brief do dia</div>
        {briefParts.length===0?(
          <div style={{color:"#0f172a",fontSize:14,lineHeight:1.7}}>
            <span style={{fontSize:18,marginRight:6}}>✨</span>
            Tudo tranquilo por aqui. Nenhum alerta crítico no momento.
          </div>
        ):(
          <div style={{color:"#0f172a",fontSize:14,lineHeight:1.7}}>
            Você tem <strong style={{color:"#a140ff"}}>{briefParts.join(", ")}</strong>{clientesRisco.length>0?<>. <strong style={{color:"#a140ff"}}>{clientesRisco.length} {clientesRisco.length===1?"cliente em risco":"clientes em risco"}</strong> também merecem atenção</>:""}.
          </div>
        )}
      </div>
    )}

    {/* ═══ TAB ALERTA — 3 KPIs com mini-charts + trend ═══ */}
    {activeTab==="alerta"&&(
      <div style={{display:"grid",gridTemplateColumns:isMob?"1fr":"repeat(3,1fr)",gap:10}}>
        <div style={{background:pagAtras.length>0?"#fef2f2":"#fff",border:`0.5px solid ${pagAtras.length>0?"#fecaca":"#e5e7eb"}`,borderRadius:12,padding:"14px 16px",display:"flex",flexDirection:"column",gap:6,minHeight:100}}>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start"}}>
            <div style={{flex:1,minWidth:0}}>
              <div style={{color:pagAtras.length>0?"#991b1b":"#94a3b8",fontSize:10,fontWeight:500,textTransform:"uppercase",letterSpacing:.4,marginBottom:6}}>Pagamentos atrasados</div>
              <div style={{color:pagAtras.length>0?"#dc2626":"#0f172a",fontSize:22,fontWeight:600,letterSpacing:-.5,lineHeight:1}}>{f$(pagAtras.reduce((a,c)=>a+c.contract,0))}</div>
            </div>
            {typeof MiniBarChart!=="undefined"&&<MiniBarChart values={[1,0,1,2,1,pagAtras.length||0]} color={pagAtras.length>0?"#dc2626":"#cbd5e1"}/>}
          </div>
          <div style={{display:"flex",alignItems:"center",gap:6}}>
            {pagAtras.length>0&&<div style={{width:6,height:6,borderRadius:"50%",background:"#dc2626"}}/>}
            <span style={{color:"#94a3b8",fontSize:10}}>{pagAtras.length} {pagAtras.length===1?"cliente":"clientes"}</span>
          </div>
        </div>
        <div style={{background:atrasadas.length>0?"#fef2f2":"#fff",border:`0.5px solid ${atrasadas.length>0?"#fecaca":"#e5e7eb"}`,borderRadius:12,padding:"14px 16px",display:"flex",flexDirection:"column",gap:6,minHeight:100}}>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start"}}>
            <div style={{flex:1,minWidth:0}}>
              <div style={{color:atrasadas.length>0?"#991b1b":"#94a3b8",fontSize:10,fontWeight:500,textTransform:"uppercase",letterSpacing:.4,marginBottom:6}}>Demandas atrasadas</div>
              <div style={{color:atrasadas.length>0?"#dc2626":"#0f172a",fontSize:22,fontWeight:600,letterSpacing:-.5,lineHeight:1}}>{atrasadas.length}</div>
            </div>
            {typeof MiniBarChart!=="undefined"&&<MiniBarChart values={last6AgencyCompletions.map((v,i)=>i===5?atrasadas.length:Math.max(1,v-1))} color={atrasadas.length>0?"#dc2626":"#cbd5e1"}/>}
          </div>
          <span style={{color:"#94a3b8",fontSize:10}}>{atrasadas.length===0?"tudo no prazo":"precisam de ação"}</span>
        </div>
        <div style={{background:pubAtrasadas.length>0?"#fff7ed":"#fff",border:`0.5px solid ${pubAtrasadas.length>0?"#fed7aa":"#e5e7eb"}`,borderRadius:12,padding:"14px 16px",display:"flex",flexDirection:"column",gap:6,minHeight:100}}>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start"}}>
            <div style={{flex:1,minWidth:0}}>
              <div style={{color:pubAtrasadas.length>0?"#9a3412":"#94a3b8",fontSize:10,fontWeight:500,textTransform:"uppercase",letterSpacing:.4,marginBottom:6}}>Pub. vencidas</div>
              <div style={{color:pubAtrasadas.length>0?"#ea580c":"#0f172a",fontSize:22,fontWeight:600,letterSpacing:-.5,lineHeight:1}}>{pubAtrasadas.length}</div>
            </div>
            {typeof MiniBarChart!=="undefined"&&<MiniBarChart values={[0,1,0,2,1,pubAtrasadas.length]} color={pubAtrasadas.length>0?"#ea580c":"#cbd5e1"}/>}
          </div>
          <span style={{color:"#94a3b8",fontSize:10}}>{pubAtrasadas.length===0?"tudo publicado":"agendar urgente"}</span>
        </div>
      </div>
    )}

    {/* ═══ TAB ALERTA — Chart evolutivo da agência ═══ */}
    {activeTab==="alerta"&&typeof EvolutionChart!=="undefined"&&(
      <EvolutionChart data={agencyCompletedSeries} title="Produção da agência" subtitle="Demandas concluídas por dia" color="#a140ff"/>
    )}

    {/* ═══ TAB ALERTA — Lista Unificada "O que precisa de você agora" ═══ */}
    {activeTab==="alerta"&&(()=>{
      const items=[];
      // 1. Pagamentos atrasados (mais críticos)
      pagAtras.forEach(cl=>items.push({
        icon:"💸",
        title:`Pagamento atrasado · ${cl.name}`,
        sub:`Vence em ${cl.payment?.date||"—"} · ${f$(cl.contract)}`,
        onClick:null,
      }));
      // 2. Publicações vencidas
      pubAtrasadas.slice(0,4).forEach(t=>{
        const cl=CLIENTS.find(c=>c.id===t.client);
        items.push({
          icon:"📤",
          title:`Publicação atrasada: ${t.title}`,
          sub:`${cl?.name||"—"} · agendada para ${t.publishDate}`,
          onClick:()=>setOpenCard(t),
        });
      });
      // 3. Demandas muito atrasadas (>2 dias) — top 5
      const veryAtrasadas=atrasadas.filter(t=>{const d=daysLeft(t.deadline);return d!==null&&d<-2;}).slice(0,5);
      veryAtrasadas.forEach(t=>{
        const cl=CLIENTS.find(c=>c.id===t.client);
        const u=TEAM.find(x=>x.id===t.assignee);
        const d=Math.abs(daysLeft(t.deadline)||0);
        items.push({
          icon:"🔥",
          title:t.title,
          sub:`${cl?.name||"—"} · ${u?.name||"—"} · ${d}d de atraso`,
          onClick:()=>setOpenCard(t),
        });
      });
      // 4. Clientes em risco (saúde < 60)
      CLIENTS.filter(c=>c.health<60).forEach(cl=>items.push({
        icon:"⚠",
        title:`Cliente em risco · ${cl.name}`,
        sub:`Saúde em ${cl.health}% · revisar relacionamento`,
        onClick:null,
      }));
      // 5. Aprovações pendentes (consolidadas)
      if(copysPendentes.length>0)items.push({icon:"📝",title:`${copysPendentes.length} ${copysPendentes.length===1?"copy aguardando aprovação":"copys aguardando aprovação"}`,sub:"Aguarda os sócios",onClick:null});
      if(artesPendentes.length>0)items.push({icon:"🎨",title:`${artesPendentes.length} ${artesPendentes.length===1?"arte aguardando aprovação":"artes aguardando aprovação"}`,sub:"Aguarda os sócios",onClick:null});
      if(aprovacoesInternas.length>0)items.push({icon:"🔒",title:`${aprovacoesInternas.length} ${aprovacoesInternas.length===1?"demanda interna":"demandas internas"} aguardando`,sub:"Avaliação dos sócios",onClick:null});

      if(items.length===0)return (
        <div style={{background:"#fff",border:"0.5px solid #e5e7eb",borderRadius:12,padding:"40px 24px",textAlign:"center"}}>
          <div style={{width:48,height:48,borderRadius:12,background:"#f8fafc",display:"flex",alignItems:"center",justifyContent:"center",fontSize:24,margin:"0 auto 14px"}}>✨</div>
          <div style={{color:"#0f172a",fontWeight:600,fontSize:16,marginBottom:6}}>Tudo tranquilo</div>
          <div style={{color:"#94a3b8",fontSize:13,lineHeight:1.6}}>Nada pendente. Toda agência queria ter um dia assim.</div>
        </div>
      );
      // NOVO LAYOUT: 1 alerta principal grande + 4 menores na lateral
      const mainItem=items[0];
      const sideItems=items.slice(1,5);
      const mainColor=mainItem.icon==="💸"||mainItem.icon==="🔥"?"#dc2626":mainItem.icon==="📤"?"#ea580c":mainItem.icon==="⚠"?"#dc2626":"#7c3aed";
      const mainLabel=mainItem.icon==="💸"?"Pagamento atrasado":mainItem.icon==="🔥"?"Demanda atrasada":mainItem.icon==="📤"?"Publicação vencida":mainItem.icon==="⚠"?"Cliente em risco":mainItem.icon==="📝"?"Copy aguardando":mainItem.icon==="🎨"?"Arte aguardando":mainItem.icon==="🔒"?"Demanda interna":"Atenção";
      return (<div style={{maxWidth:860,margin:"0 auto",width:"100%"}}>
        <div style={{padding:"0 4px 8px"}}>
          <div style={{fontSize:10,color:"#94a3b8",fontWeight:500,textTransform:"uppercase",letterSpacing:.6}}>O que precisa de você agora</div>
        </div>
        <div style={{display:"grid",gridTemplateColumns:isMob?"1fr":"minmax(0,1fr) 250px",gap:12}}>
          {/* CARTÃO GRANDE — alerta #1 */}
          <div onClick={mainItem.onClick||undefined} style={{
            background:"#fff",
            border:"0.5px solid #e5e7eb",
            borderLeft:`4px solid ${mainColor}`,
            borderRadius:12,
            padding:"22px 24px",
            minHeight:200,
            cursor:mainItem.onClick?"pointer":"default",
            display:"flex",
            flexDirection:"column",
            transition:"box-shadow .15s",
          }}
            onMouseEnter={e=>{if(mainItem.onClick)e.currentTarget.style.boxShadow="0 2px 8px rgba(0,0,0,0.06)";}}
            onMouseLeave={e=>e.currentTarget.style.boxShadow="none"}>
            <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:10}}>
              <div style={{display:"flex",alignItems:"center",gap:8}}>
                <span style={{
                  background:mainColor+"18",color:mainColor,
                  fontSize:9,fontWeight:600,padding:"3px 9px",borderRadius:4,
                  textTransform:"uppercase",letterSpacing:.4
                }}>{mainItem.icon} {mainLabel}</span>
                <span style={{fontSize:10,color:"#94a3b8"}}>#1 alerta</span>
              </div>
              <span style={{fontSize:11,color:"#94a3b8",fontWeight:500}}>{items.length} {items.length===1?"item":"itens"}</span>
            </div>
            <div style={{color:"#0f172a",fontWeight:600,fontSize:18,lineHeight:1.3,marginBottom:8}}>{mainItem.title}</div>
            <div style={{color:"#64748b",fontSize:12,lineHeight:1.6,marginBottom:14,flex:1}}>{mainItem.sub}</div>
            {mainItem.onClick&&<div style={{display:"flex",justifyContent:"flex-end",alignItems:"center",paddingTop:12,borderTop:"0.5px solid #f1f5f9",marginTop:"auto"}}>
              <span style={{background:"#a140ff",color:"#fff",fontSize:11,fontWeight:500,padding:"6px 14px",borderRadius:6}}>Abrir →</span>
            </div>}
          </div>

          {/* 4 PEQUENOS */}
          <div style={{display:"flex",flexDirection:"column",gap:6}}>
            {sideItems.map((it,i)=>{
              const sideColor=it.icon==="💸"||it.icon==="🔥"?"#dc2626":it.icon==="📤"?"#ea580c":it.icon==="⚠"?"#dc2626":"#7c3aed";
              return <div key={i+1} onClick={it.onClick||undefined}
                style={{
                  background:"#fff",
                  border:"0.5px solid #e5e7eb",
                  borderLeft:`3px solid ${sideColor}`,
                  borderRadius:8,
                  padding:"9px 11px",
                  cursor:it.onClick?"pointer":"default",
                  transition:"transform .1s",
                }}
                onMouseEnter={e=>{if(it.onClick)e.currentTarget.style.transform="translateX(2px)";}}
                onMouseLeave={e=>e.currentTarget.style.transform=""}>
                <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:3}}>
                  <span style={{fontSize:9,color:sideColor,fontWeight:600,textTransform:"uppercase",letterSpacing:.3}}>{it.icon} #{i+2}</span>
                </div>
                <div style={{fontSize:11,color:"#0f172a",fontWeight:500,lineHeight:1.3,marginBottom:2,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{it.title}</div>
                <div style={{fontSize:9,color:"#94a3b8",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{it.sub}</div>
              </div>;
            })}
            {items.length>5&&<div style={{textAlign:"center",padding:6,fontSize:10,color:"#94a3b8"}}>+ {items.length-5} {items.length-5===1?"alerta":"alertas"}</div>}
          </div>
        </div>
      </div>);
    })()}

    {/* ═══ TAB DEMANDAS — 4 KPIs operacionais ═══ */}
    {activeTab==="demandas"&&(
      <div style={{display:"grid",gridTemplateColumns:isMob?"1fr 1fr":"repeat(4,1fr)",gap:10}}>
        <div style={{background:"#fff",border:"0.5px solid #e5e7eb",borderRadius:12,padding:"14px 16px"}}>
          <div style={{color:"#64748b",fontSize:10,fontWeight:700,textTransform:"uppercase",letterSpacing:.5}}>Em produção</div>
          <div style={{color:"#0f172a",fontSize:isMob?22:26,fontWeight:600,letterSpacing:-.5,marginTop:6,lineHeight:1}}>{emProducao}</div>
          <div style={{color:"#94a3b8",fontSize:11,marginTop:4}}>cards ativos</div>
        </div>
        <div style={{background:"#fff",border:"0.5px solid #e5e7eb",borderRadius:12,padding:"14px 16px"}}>
          <div style={{color:"#64748b",fontSize:10,fontWeight:700,textTransform:"uppercase",letterSpacing:.5}}>Em avaliação</div>
          <div style={{color:"#0f172a",fontSize:isMob?22:26,fontWeight:600,letterSpacing:-.5,marginTop:6,lineHeight:1}}>{emAvaliacao}</div>
          <div style={{color:"#94a3b8",fontSize:11,marginTop:4}}>aguardando aprovação</div>
        </div>
        <div style={{background:"#fff",border:"0.5px solid #e5e7eb",borderRadius:12,padding:"14px 16px"}}>
          <div style={{color:"#64748b",fontSize:10,fontWeight:700,textTransform:"uppercase",letterSpacing:.5}}>Aprovadas</div>
          <div style={{color:"#0f172a",fontSize:isMob?22:26,fontWeight:600,letterSpacing:-.5,marginTop:6,lineHeight:1}}>{aprovadasTotal}</div>
          <div style={{color:"#94a3b8",fontSize:11,marginTop:4}}>prontas p/ agendar</div>
        </div>
        <div style={{background:"#fff",border:"0.5px solid #e5e7eb",borderRadius:12,padding:"14px 16px"}}>
          <div style={{color:"#64748b",fontSize:10,fontWeight:700,textTransform:"uppercase",letterSpacing:.5}}>Publicadas</div>
          <div style={{color:"#a140ff",fontSize:isMob?22:26,fontWeight:600,letterSpacing:-.5,marginTop:6,lineHeight:1}}>{publicadasMes}</div>
          <div style={{color:"#94a3b8",fontSize:11,marginTop:4}}>este mês</div>
        </div>
      </div>
    )}

    {/* ═══ TAB DEMANDAS — Carga por pessoa (NOVO) ═══ */}
    {activeTab==="demandas"&&(
      <div style={{background:"#fff",border:"0.5px solid #e5e7eb",borderRadius:12,padding:"14px 18px"}}>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:12}}>
          <div style={{color:"#0f172a",fontWeight:700,fontSize:13}}>Carga por pessoa</div>
          <div style={{color:"#64748b",fontSize:11}}>{ativas.length} demandas ativas distribuídas</div>
        </div>
        <div style={{display:"flex",flexDirection:"column",gap:8}}>
          {cargaPorPessoa.map(c=>{
            const pct=(c.count/maxCarga)*100;
            const overload=c.count>=10;
            return <div key={c.user.id} style={{display:"flex",alignItems:"center",gap:10}}>
              <Av l={c.user.av} color={c.user.color} size={26} uid={c.user.id}/>
              <div style={{flex:1,minWidth:0}}>
                <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:4}}>
                  <span style={{color:"#0f172a",fontSize:12,fontWeight:600}}>{c.user.name}</span>
                  <span style={{color:overload?"#dc2626":"#64748b",fontSize:11,fontWeight:overload?600:500}}>{c.count}</span>
                </div>
                <div style={{height:6,background:"#e5e7eb",borderRadius:99,overflow:"hidden"}}>
                  <div style={{width:pct+"%",height:"100%",background:overload?"#dc2626":c.user.color,borderRadius:99,transition:"width .4s ease"}}/>
                </div>
              </div>
            </div>;
          })}
        </div>
      </div>
    )}




    {/* ═══ 3. PIPELINE DE DEMANDAS — TAB DEMANDAS ═══ */}
    {activeTab==="demandas"&&<div style={{background:"#fff",borderRadius:12,border:"0.5px solid #e5e7eb"}}>
      <div style={{padding:"14px 18px 10px",borderBottom:"0.5px solid #f1f5f9",display:"flex",alignItems:"center",justifyContent:"space-between"}}>
        <div>
          <div style={{color:"#0f172a",fontWeight:700,fontSize:14,letterSpacing:-.2}}>Pipeline de Demandas</div>
          <div style={{color:"#64748b",fontSize:11,marginTop:2}}>{active.length} demandas na operação</div>
        </div>
      </div>
      <div style={{padding:"14px 16px",display:"grid",gridTemplateColumns:isMob?"repeat(3,1fr)":"repeat(6,1fr)",gap:8}}>
        {pipeline.map(p=>(
          <div key={p.status} style={{background:"#fff",border:"0.5px solid #e5e7eb",borderTop:"3px solid #a140ff",borderRadius:8,padding:"12px 6px",textAlign:"center"}}>
            <div style={{color:"#94a3b8",fontSize:10,fontWeight:600,textTransform:"uppercase",letterSpacing:.4,marginBottom:6}}>{p.label}</div>
            <div style={{color:"#a140ff",fontWeight:600,fontSize:26,letterSpacing:-1,lineHeight:1}}>{p.count}</div>
          </div>
        ))}
      </div>
    </div>}

    {/* ═══ TAB DEMANDAS — Velocity + Gargalos (NOVO) ═══ */}
    {activeTab==="demandas"&&(
      <div style={{display:"grid",gridTemplateColumns:isMob?"1fr":"1fr 1fr",gap:12}}>
        {/* Velocity */}
        <div style={{background:"#fff",border:"0.5px solid #e5e7eb",borderRadius:12,padding:"14px 18px"}}>
          <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:12}}>
            <div style={{color:"#0f172a",fontWeight:700,fontSize:13}}>Velocity · 4 últimas semanas</div>
            <div style={{color:"#64748b",fontSize:11}}>{velocityTrend} média {velocityAvg}/sem</div>
          </div>
          <svg viewBox="0 0 280 90" style={{width:"100%",height:90}}>
            {velocity.map((v,i)=>{
              const h=Math.max(4,(v/velocityMax)*65);
              const x=20+i*60;
              const y=80-h;
              return <g key={i}>
                <rect x={x} y={y} width={40} height={h} rx={3} fill="#7F77DD"/>
                <text x={x+20} y={y-3} textAnchor="middle" fontSize="11" fontWeight="600" fill="#0f172a">{v}</text>
                <text x={x+20} y={88} textAnchor="middle" fontSize="9" fill="#94a3b8">S{4-i}</text>
              </g>;
            })}
          </svg>
        </div>
        {/* Gargalos */}
        <div style={{background:"#fff",border:"0.5px solid #e5e7eb",borderRadius:12,padding:"14px 18px"}}>
          <div style={{color:"#0f172a",fontWeight:700,fontSize:13,marginBottom:12}}>Gargalos detectados</div>
          {gargalos.length===0?(
            <div style={{padding:"24px 0",textAlign:"center"}}>
              <div style={{fontSize:28,marginBottom:6}}>✅</div>
              <div style={{color:"#16a34a",fontSize:12,fontWeight:600}}>Nenhum gargalo · fluxo saudável</div>
            </div>
          ):gargalos.map((g,i)=>(
            <div key={i} style={{display:"flex",alignItems:"center",gap:10,padding:"6px 0",borderBottom:i<gargalos.length-1?"0.5px solid #f1f5f9":"none"}}>
              <span style={{fontSize:14}}>⚠</span>
              <div style={{flex:1,minWidth:0}}>
                <div style={{color:"#0f172a",fontSize:12,fontWeight:600}}>{g.label}</div>
                <div style={{color:"#94a3b8",fontSize:11}}>{g.stuck} {g.stuck===1?"card parado":"cards parados"} há 4+ dias</div>
              </div>
              <div style={{width:8,height:8,borderRadius:"50%",background:g.color}}/>
            </div>
          ))}
        </div>
      </div>
    )}

    {/* ═══ TAB MÉTRICAS — 4 Hero Numbers (NOVO) ═══ */}
    {activeTab==="metricas"&&(
      <div style={{display:"grid",gridTemplateColumns:isMob?"1fr 1fr":"repeat(4,1fr)",gap:10}}>
        <div style={{background:"#fff",border:"0.5px solid #e5e7eb",borderRadius:12,padding:"14px 16px"}}>
          <div style={{color:"#64748b",fontSize:10,fontWeight:700,textTransform:"uppercase",letterSpacing:.5}}>Spend total · mês</div>
          <div style={{color:"#0f172a",fontSize:isMob?20:24,fontWeight:600,letterSpacing:-.5,marginTop:6,lineHeight:1}}>{f$(spendTotal)}</div>
          <div style={{color:"#94a3b8",fontSize:11,marginTop:4}}>Meta + Google somados</div>
        </div>
        <div style={{background:"#fff",border:"0.5px solid #e5e7eb",borderRadius:12,padding:"14px 16px"}}>
          <div style={{color:"#64748b",fontSize:10,fontWeight:700,textTransform:"uppercase",letterSpacing:.5}}>ROAS médio</div>
          <div style={{color:Number(avgRoas)>=4?"#16a34a":Number(avgRoas)>=2?"#eab308":"#dc2626",fontSize:isMob?20:24,fontWeight:600,letterSpacing:-.5,marginTop:6,lineHeight:1}}>{avgRoas}×</div>
          <div style={{color:"#94a3b8",fontSize:11,marginTop:4}}>{clientesAtivos} clientes ativos</div>
        </div>
        <div style={{background:"#fff",border:"0.5px solid #e5e7eb",borderRadius:12,padding:"14px 16px"}}>
          <div style={{color:"#64748b",fontSize:10,fontWeight:700,textTransform:"uppercase",letterSpacing:.5}}>Leads gerados</div>
          <div style={{color:"#0f172a",fontSize:isMob?20:24,fontWeight:600,letterSpacing:-.5,marginTop:6,lineHeight:1}}>{totalLeads.toLocaleString("pt-BR")}</div>
          <div style={{color:"#94a3b8",fontSize:11,marginTop:4}}>Meta + Google · mês</div>
        </div>
        <div style={{background:"#fff",border:"0.5px solid #e5e7eb",borderRadius:12,padding:"14px 16px"}}>
          <div style={{color:"#64748b",fontSize:10,fontWeight:700,textTransform:"uppercase",letterSpacing:.5}}>Followers totais</div>
          <div style={{color:"#0f172a",fontSize:isMob?20:24,fontWeight:600,letterSpacing:-.5,marginTop:6,lineHeight:1}}>{(followersTotal/1000).toFixed(1)}k</div>
          <div style={{color:"#94a3b8",fontSize:11,marginTop:4}}>todas as redes</div>
        </div>
      </div>
    )}

    {/* ═══ TAB MÉTRICAS — Top 5 ROAS / Bottom (NOVO) ═══ */}
    {activeTab==="metricas"&&(
      <div style={{display:"grid",gridTemplateColumns:isMob?"1fr":"1fr 1fr",gap:12}}>
        <div style={{background:"#fff",border:"0.5px solid #e5e7eb",borderRadius:12,overflow:"hidden"}}>
          <div style={{padding:"14px 16px 10px",borderBottom:"0.5px solid #f1f5f9"}}>
            <div style={{color:"#0f172a",fontWeight:500,fontSize:13}}>Top 5 ROAS</div>
            <div style={{color:"#94a3b8",fontSize:11,marginTop:2}}>maior retorno por real investido</div>
          </div>
          <div style={{padding:"10px 14px"}}>
            {top5Roas.length===0?<div style={{padding:"16px",textAlign:"center",color:"#94a3b8",fontSize:12}}>Sem dados de ROAS ainda</div>:top5Roas.map((cl,i)=>(
              <div key={cl.id} style={{display:"flex",alignItems:"center",gap:10,padding:"7px 0",borderBottom:i<top5Roas.length-1?"0.5px solid #f1f5f9":"none"}}>
                <ClientLogo clientId={cl.id} size="xs"/>
                <div style={{flex:1,minWidth:0}}>
                  <div style={{color:"#0f172a",fontSize:12,fontWeight:600,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{cl.name}</div>
                </div>
                <div style={{color:"#16a34a",fontWeight:600,fontSize:14}}>{(cl.meta?.roas||0).toFixed(1)}×</div>
              </div>
            ))}
          </div>
        </div>
        <div style={{background:"#fff",border:"0.5px solid #e5e7eb",borderRadius:12,overflow:"hidden"}}>
          <div style={{padding:"14px 16px 10px",borderBottom:"0.5px solid #f1f5f9"}}>
            <div style={{color:"#0f172a",fontWeight:500,fontSize:13}}>Atenção · ROAS &lt; 2×</div>
            <div style={{color:"#94a3b8",fontSize:11,marginTop:2}}>revisar campanhas</div>
          </div>
          <div style={{padding:"10px 12px"}}>
            {bottomRoas.length===0?(
              <div style={{padding:"24px",textAlign:"center"}}>
                <div style={{fontSize:24,marginBottom:6}}>💚</div>
                <div style={{color:"#16a34a",fontSize:12,fontWeight:600}}>Todos os ROAS saudáveis</div>
              </div>
            ):bottomRoas.map((cl,i)=>(
              <div key={cl.id} style={{display:"flex",alignItems:"center",gap:10,padding:"7px 0",borderBottom:i<bottomRoas.length-1?"0.5px solid #f1f5f9":"none"}}>
                <ClientLogo clientId={cl.id} size="xs"/>
                <div style={{flex:1,minWidth:0}}>
                  <div style={{color:"#0f172a",fontSize:12,fontWeight:600}}>{cl.name}</div>
                  <div style={{color:"#94a3b8",fontSize:10}}>revisar campanhas</div>
                </div>
                <div style={{color:"#dc2626",fontWeight:600,fontSize:14}}>{(cl.meta?.roas||0).toFixed(1)}×</div>
              </div>
            ))}
          </div>
        </div>
      </div>
    )}


    {/* ═══ 6. TABELA DE CLIENTES (visão completa) — TAB MÉTRICAS ═══ */}
    {activeTab==="metricas"&&<div style={{background:C.card,borderRadius:12,border:`0.5px solid ${C.b1}`,overflow:"hidden"}}>
      <div style={{padding:"14px 18px",borderBottom:`0.5px solid ${C.b1}`}}>
        <div style={{color:"#0f172a",fontWeight:500,fontSize:13}}>Panorama dos clientes</div>
        <div style={{color:"#94a3b8",fontSize:11,marginTop:2}}>visão completa da carteira</div>
      </div>
      <div style={{overflow:"auto"}}>
        <table style={{width:"100%",borderCollapse:"collapse",fontSize:12}}>
          <thead>
            <tr style={{background:"#f8fafc"}}>
              <th style={{padding:"10px 14px",textAlign:"left",color:C.td,fontSize:10,fontWeight:600,textTransform:"uppercase",letterSpacing:.5}}>Cliente</th>
              <th style={{padding:"10px 8px",textAlign:"center",color:C.td,fontSize:10,fontWeight:600,textTransform:"uppercase",letterSpacing:.5}}>MRR</th>
              <th style={{padding:"10px 8px",textAlign:"center",color:C.td,fontSize:10,fontWeight:600,textTransform:"uppercase",letterSpacing:.5}}>Saúde</th>
              <th style={{padding:"10px 8px",textAlign:"center",color:C.td,fontSize:10,fontWeight:600,textTransform:"uppercase",letterSpacing:.5}}>ROAS</th>
              <th style={{padding:"10px 8px",textAlign:"center",color:C.td,fontSize:10,fontWeight:600,textTransform:"uppercase",letterSpacing:.5}}>NPS</th>
              <th style={{padding:"10px 14px",textAlign:"center",color:C.td,fontSize:10,fontWeight:600,textTransform:"uppercase",letterSpacing:.5}}>Pag.</th>
            </tr>
          </thead>
          <tbody>
            {CLIENTS.map(cl=>{
              const healthColor=cl.health>=80?"#16a34a":cl.health>=60?"#eab308":"#dc2626";
              const roasColor=(cl.meta?.roas||0)>=4?"#16a34a":(cl.meta?.roas||0)>=2?"#eab308":"#dc2626";
              const npsColor=(cl.nps||0)>=80?"#16a34a":(cl.nps||0)>=60?"#eab308":"#dc2626";
              const pagStatus=cl.payment?.status||"pendente";
              const pagColor=pagStatus==="pago"?"#16a34a":pagStatus==="atrasado"?"#dc2626":"#eab308";
              return <tr key={cl.id} style={{borderTop:`0.5px solid ${C.b1}`}}>
                <td style={{padding:"10px 14px",display:"flex",alignItems:"center",gap:8}}>
                  <ClientLogo clientId={cl.id} size="xs"/>
                  <span style={{color:C.tx,fontWeight:700}}>{cl.name}</span>
                </td>
                <td style={{padding:"10px 8px",textAlign:"center",color:"#16a34a",fontWeight:600}}>{f$(cl.contract)}</td>
                <td style={{padding:"10px 8px",textAlign:"center"}}>
                  <span style={{background:healthColor,color:"#fff",borderRadius:99,padding:"3px 10px",fontSize:11,fontWeight:600}}>
                    {cl.health}%
                  </span>
                </td>
                <td style={{padding:"10px 8px",textAlign:"center",color:roasColor,fontWeight:600}}>{(cl.meta?.roas||0).toFixed(1)}x</td>
                <td style={{padding:"10px 8px",textAlign:"center",color:npsColor,fontWeight:600}}>{cl.nps||0}</td>
                <td style={{padding:"10px 14px",textAlign:"center"}}>
                  <span style={{background:pagColor,color:"#fff",borderRadius:6,padding:"2px 8px",fontSize:9,fontWeight:600,textTransform:"uppercase",letterSpacing:.3}}>
                    {pagStatus==="pago"?"Pago":pagStatus==="atrasado"?"Atras":"Pend"}
                  </span>
                </td>
              </tr>;
            })}
          </tbody>
        </table>
      </div>
    </div>}


    {/* ═══ TAB METAS — Health Score gauge (NOVO) ═══ */}
    {activeTab==="metas"&&(
      <div style={{background:"#fff",border:"0.5px solid #e5e7eb",borderRadius:12,padding:"20px",textAlign:"center"}}>
        <div style={{color:"#0f172a",fontWeight:700,fontSize:13,marginBottom:8}}>Health Score da agência</div>
        <svg viewBox="0 0 200 110" style={{width:200,height:110,maxWidth:"100%"}}>
          <path d="M 20 100 A 80 80 0 0 1 180 100" stroke="#e5e7eb" strokeWidth="14" fill="none"/>
          <path d={(()=>{
            // Calcula path do arco proporcional ao healthScore
            const angle=Math.PI*(1-healthScore/100);
            const x=100+80*Math.cos(angle);
            const y=100-80*Math.sin(angle);
            const largeArc=healthScore>50?1:0;
            return `M 20 100 A 80 80 0 0 ${largeArc} ${x.toFixed(1)} ${y.toFixed(1)}`;
          })()} stroke={healthScore>=80?"#16a34a":healthScore>=60?"#eab308":"#dc2626"} strokeWidth="14" fill="none" strokeLinecap="round"/>
          <text x="100" y="85" textAnchor="middle" fontSize="34" fontWeight="800" fill="#0f172a">{healthScore}</text>
          <text x="100" y="103" textAnchor="middle" fontSize="11" fill="#94a3b8">de 100</text>
        </svg>
        <div style={{color:"#64748b",fontSize:12,marginTop:6}}>SLA {slaScore}% · NPS {npsScore} · Churn {churnPct}% · Crescimento {growthScore}%</div>
      </div>
    )}

    {/* ═══ TAB METAS — 4 metas vs atual (NOVO) ═══ */}
    {activeTab==="metas"&&(()=>{
      const mrrPct=Math.min(100,Math.round((mrr/METAS.mrr)*100));
      const novosPct=Math.min(100,Math.round((novosClientesMes/METAS.novosClientesMes)*100));
      const npsPct=Math.min(100,Math.round((avgNps/METAS.nps)*100));
      const churnOK=churnPct<=METAS.churn;
      const cores=[
        mrrPct>=80?"#16a34a":mrrPct>=60?"#eab308":"#dc2626",
        novosPct>=80?"#16a34a":novosPct>=60?"#eab308":"#dc2626",
        npsPct>=80?"#16a34a":npsPct>=60?"#eab308":"#dc2626",
        churnOK?"#16a34a":"#dc2626",
      ];
      const Card=({label,atual,meta,pct,sub,color})=>(
        <div style={{background:"#fff",border:"0.5px solid #e5e7eb",borderRadius:12,padding:"12px 14px"}}>
          <div style={{color:"#64748b",fontSize:10,fontWeight:700,textTransform:"uppercase",letterSpacing:.5}}>{label}</div>
          <div style={{color:"#0f172a",fontSize:isMob?16:18,fontWeight:600,letterSpacing:-.3,marginTop:4}}>{atual}</div>
          <div style={{color:"#94a3b8",fontSize:11,margin:"4px 0 6px"}}>{sub}</div>
          <div style={{height:5,background:"#e5e7eb",borderRadius:99,overflow:"hidden"}}>
            <div style={{width:pct+"%",height:"100%",background:color,borderRadius:99,transition:"width .5s ease"}}/>
          </div>
        </div>
      );
      return <div style={{display:"grid",gridTemplateColumns:isMob?"1fr 1fr":"repeat(4,1fr)",gap:10}}>
        <Card label="MRR" atual={f$(mrr)} meta={f$(METAS.mrr)} pct={mrrPct} sub={`meta ${f$(METAS.mrr)} · ${mrrPct}%`} color={cores[0]}/>
        <Card label="Novos clientes" atual={novosClientesMes} meta={METAS.novosClientesMes} pct={novosPct} sub={`meta ${METAS.novosClientesMes} · ${novosPct}%`} color={cores[1]}/>
        <Card label="NPS médio" atual={avgNps} meta={METAS.nps} pct={npsPct} sub={`meta ${METAS.nps} · ${npsPct}%`} color={cores[2]}/>
        <Card label="Churn" atual={churnPct+"%"} meta={"<"+METAS.churn+"%"} pct={churnOK?100:churnPct*20} sub={`meta < ${METAS.churn}% ${churnOK?"✓":""}`} color={cores[3]}/>
      </div>;
    })()}

    {/* ═══ TAB METAS — Histórico de Receita 12 meses (NOVO) ═══ */}
    {activeTab==="metas"&&(
      <div style={{background:"#fff",border:"0.5px solid #e5e7eb",borderRadius:12,padding:"14px 18px"}}>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:12}}>
          <div style={{color:"#0f172a",fontWeight:700,fontSize:13}}>Receita · 12 meses</div>
          <div style={{color:"#64748b",fontSize:11}}>placeholder · conectar histórico real depois</div>
        </div>
        <svg viewBox="0 0 600 130" style={{width:"100%",height:130}}>
          <line x1="0" y1="105" x2="600" y2="105" stroke="#e5e7eb" strokeWidth="0.5"/>
          {/* Linha de meta */}
          {(()=>{const yMeta=110-(METAS.mrr/receita12mMax)*90;return <>
            <line x1="0" y1={yMeta} x2="600" y2={yMeta} stroke="#94a3b8" strokeWidth="0.5" strokeDasharray="2,3"/>
            <text x="2" y={yMeta-3} fontSize="9" fill="#94a3b8">meta {f$(METAS.mrr)}</text>
          </>;})()}
          {/* Polyline da receita */}
          {(()=>{
            const pts=receita12m.map((v,i)=>{const x=20+(i*(560/11));const y=110-(v/receita12mMax)*90;return `${x.toFixed(1)},${y.toFixed(1)}`;}).join(" ");
            return <polyline points={pts} stroke="#7F77DD" strokeWidth="2" fill="none"/>;
          })()}
          {/* Bolinhas */}
          {receita12m.map((v,i)=>{const x=20+(i*(560/11));const y=110-(v/receita12mMax)*90;return <circle key={i} cx={x} cy={y} r="3" fill="#7F77DD"/>;})}
          {/* Última bolinha destacada */}
          {(()=>{const x=20+(11*(560/11));const y=110-(receita12m[11]/receita12mMax)*90;return <circle cx={x} cy={y} r="5" fill="#7F77DD" stroke="#fff" strokeWidth="2"/>;})()}
          {/* Labels do eixo */}
          <text x="20" y="125" fontSize="9" fill="#94a3b8">12m atrás</text>
          <text x="300" y="125" fontSize="9" fill="#94a3b8" textAnchor="middle">6m</text>
          <text x="580" y="125" fontSize="9" fill="#94a3b8" textAnchor="end">Hoje</text>
        </svg>
      </div>
    )}

  </div>;
}

function RenderDash({user,isViewing=false,tasks,setTasks,notifs,isMob}){
  // Sócios (Vinicius + Gustavo) usam o dashboard estratégico compartilhado (DashGustavo = DashSocio).
  // As metas multi-marcadas pra ambos sincronizam entre os dois (filtragem por assignees).
  if((user.id==="gustavo"||user.id==="vinicius"||user.id==="ocsana")&&typeof DashGustavo==="function"){
    return <DashGustavo user={user} isViewing={isViewing} tasks={tasks} setTasks={setTasks} notifs={notifs} isMob={isMob}/>;
  }
  switch(user.dash){
    case"partner":     return <DashPartner     user={user} isViewing={isViewing} tasks={tasks} setTasks={setTasks} notifs={notifs} isMob={isMob}/>;
    case"coordinator": return <DashCoordinator user={user} isViewing={isViewing} tasks={tasks} setTasks={setTasks} notifs={notifs} isMob={isMob}/>;
    case"gestor":      return <DashGestor      user={user} isViewing={isViewing} tasks={tasks} setTasks={setTasks} notifs={notifs} isMob={isMob}/>;
    case"designer":    return <DashDesigner    user={user} isViewing={isViewing} tasks={tasks} setTasks={setTasks} notifs={notifs} isMob={isMob}/>;
    case"editor":      return <DashEditor      user={user} isViewing={isViewing} tasks={tasks} setTasks={setTasks} notifs={notifs} isMob={isMob}/>;
    case"social":      return <DashEditor      user={user} isViewing={isViewing} tasks={tasks} setTasks={setTasks} notifs={notifs} isMob={isMob}/>;
    default:           return <DashPartner     user={user} isViewing={isViewing} tasks={tasks} setTasks={setTasks} notifs={notifs} isMob={isMob}/>;
  }
}

// DashColaborador unifica DashCoordinator, DashGestor, DashDesigner, DashEditor
// icon é definido pelo campo user.dash via DASH_ICONS
const DASH_ICONS={coordinator:"📱",gestor:"📊",designer:"🎨",editor:"🎬",social:"📲"};
function DashColaborador({user,isViewing,tasks:propTasks,setTasks:propSetTasks,notifs,isMob}){
  // Tasks DELE (individual): onde ele é o responsável principal
  const tasks=(propTasks||[]).filter(t=>t.assignee===user.id||(t.assignees||[]).includes(user.id));
  const setTasks=propSetTasks||(()=>{});
  // Ellen (coordinator) precisa ver todas as tasks pra gerenciar a equipe
  const allTasks=propTasks||[];
  // Supervisionados (pra supervisores tipo Guilherme → João)
  const supervisedUsers=user.supervises||[];
  const supervisedTasks=supervisedUsers.length>0
    ?(propTasks||[]).filter(t=>!t.deletedAt&&(supervisedUsers.includes(t.assignee)||supervisedUsers.some(s=>(t.assignees||[]).includes(s))))
    :[];
  const _escopo=null; // Escopo saiu do dashboard — a Matriz de Responsabilidades cobre isso agora.
  // Designer / Editor (freelancer com pagamento por demanda) -> dashboard V2 moderno
  const _core=(user.pagamentoPorDemanda===true && user.dash!=="social" && typeof DashColabV2==="function")
    ? <DashColabV2 user={user} tasks={tasks} allTasks={allTasks}
        setTasks={setTasks} isViewing={isViewing} currentUser={CURRENT_USER} notifs={notifs} isMob={isMob}/>
    : <PriorityDashCore user={user} tasks={tasks} allTasks={allTasks}
        supervisedTasks={supervisedTasks} supervisedUsers={supervisedUsers}
        setTasks={setTasks} isViewing={isViewing} icon={DASH_ICONS[user.dash]||"📋"} currentUser={CURRENT_USER} notifs={notifs} isMob={isMob}/>;
  if(!_escopo) return _core;
  return <div style={{display:"flex",flexDirection:"column"}}>
    <_EscopoCargoCard escopo={_escopo} uid={user.id} isMob={isMob}/>
    {_core}
  </div>;
}

/* ── Card "Seu escopo" — deixa preto no branco o que é do cargo e o que não é.
     Recolhível; estado lembrado por usuário no localStorage. ── */
