function ClienteConcorrencia({cl,tab,setTab,readOnly}){
  // ═══ CONCORRÊNCIA v3 — lista única, sem abas ═══
  // Persistência: clients.concorrencia_data (JSONB)
  //   { _v:2, competitors:[ {id, name, logo, redes:{instagram, facebook, tiktok, youtube}} ] }
  // Formato antigo (por rede: instagram.competitors[] etc.) é migrado na leitura e preservado no JSON.
  // Benchmark e "Posts virais" foram descontinuados (decisão 02/09/2026).

  const REDES = [
    {id:"instagram", label:"Instagram", cor:"#E4405F", ph:"@perfil ou link"},
    {id:"facebook",  label:"Facebook",  cor:"#1877F2", ph:"nome da página ou link"},
    {id:"tiktok",    label:"TikTok",    cor:"#111827", ph:"@usuario ou link"},
    {id:"youtube",   label:"YouTube",   cor:"#FF0000", ph:"@canal ou link"},
  ];

  const _isSocio = (typeof CURRENT_USER!=="undefined")&&CURRENT_USER&&CURRENT_USER.level===1;
  const _canEdit = !readOnly && (_isSocio || (typeof CURRENT_USER!=="undefined" && CURRENT_USER && CURRENT_USER.level<=2));

  const [data, setData] = useState({});
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [modal, setModal] = useState(null); // {} novo | competitor pra editar | null

  // Migra o formato por-rede pra lista única. Agrupa pelo nome normalizado.
  function _migrar(d){
    if(d && Array.isArray(d.competitors)) return d;
    const byName = {}; const ordem = [];
    REDES.forEach(function(r){
      const plat = d && d[r.id];
      (plat && Array.isArray(plat.competitors) ? plat.competitors : []).forEach(function(c){
        const k = String(c.name||c.handle||"").trim().toLowerCase();
        if(!k) return;
        if(!byName[k]){ byName[k] = {id:c.id||("cmp-"+Date.now()+"-"+Math.random().toString(36).slice(2,7)), name:c.name||c.handle||"", logo:c.logo||"", redes:{}}; ordem.push(k); }
        if(c.handle && !byName[k].redes[r.id]) byName[k].redes[r.id] = c.handle;
      });
    });
    return Object.assign({}, d||{}, {_v:2, competitors: ordem.map(function(k){return byName[k];})});
  }

  useEffect(function(){
    if(!cl || !cl.id || typeof window==="undefined" || !window._sb){ setLoading(false); return; }
    let alive = true;
    window._sb.from("clients").select("concorrencia_data").eq("client_id",cl.id).maybeSingle()
      .then(function(r){
        if(!alive) return;
        const raw = (r && r.data && r.data.concorrencia_data) || {};
        const mig = _migrar(raw);
        setData(mig);
        setLoading(false);
        // Persiste a migração uma vez (só quem pode editar), preservando as chaves antigas
        if(_canEdit && !(raw && Array.isArray(raw.competitors)) && mig.competitors.length>0){
          window._sb.from("clients").upsert({client_id:cl.id, concorrencia_data:mig},{onConflict:"client_id"}).then(function(){}).catch(function(){});
        }
      })
      .catch(function(){ if(alive) setLoading(false); });
    return function(){ alive=false; };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  },[cl.id]);

  function save(next){
    setData(next);
    if(!cl || !cl.id || typeof window==="undefined" || !window._sb) return;
    setSaving(true);
    window._sb.from("clients").upsert({client_id:cl.id, concorrencia_data:next},{onConflict:"client_id"})
      .then(function(r){
        setSaving(false);
        if(r && r.error){
          console.warn("[concorrencia save]", r.error);
          if(typeof pixelsToast!=="undefined") pixelsToast.error("Falha ao salvar concorrência: "+(r.error.message||"erro"),4000);
        }
      })
      .catch(function(e){ setSaving(false); console.warn("[concorrencia save ex]", e); });
  }

  const _comps = Array.isArray(data.competitors) ? data.competitors : [];
  function _setComps(list){ save(Object.assign({}, data, {_v:2, competitors:list})); }
  function addCompetitor(c){ _setComps(_comps.concat([Object.assign({id:"cmp-"+Date.now()+"-"+Math.random().toString(36).slice(2,7)}, c)])); }
  function updateCompetitor(id, patch){ _setComps(_comps.map(function(c){ return c.id===id ? Object.assign({},c,patch) : c; })); }
  function delCompetitor(id){
    const go = function(){ _setComps(_comps.filter(function(c){ return c.id!==id; })); };
    if(typeof pixelsConfirm==="function"){ pixelsConfirm("Excluir este concorrente?",{danger:true,okText:"Excluir",cancelText:"Cancelar"}).then(function(y){ if(y) go(); }); }
    else if(confirm("Excluir este concorrente?")) go();
  }

  // Monta a URL pública a partir do que foi digitado (handle ou link). Link https comum:
  // no celular o iOS/Android abrem o app nativo sozinhos; no desktop abre o navegador.
  function _urlRede(redeId, v){
    let x = String(v||"").trim();
    if(!x) return "";
    if(/^https?:\/\//i.test(x)) return x;
    if(/^(www\.)?[a-z0-9-]+\.[a-z]{2,}(\/|$)/i.test(x)) return "https://"+x.replace(/^\/+/,"");
    x = x.replace(/^@/,"").replace(/^\/+|\/+$/g,"");
    if(redeId==="instagram") return "https://instagram.com/"+x;
    if(redeId==="facebook")  return "https://facebook.com/"+x;
    if(redeId==="tiktok")    return "https://tiktok.com/@"+x;
    if(redeId==="youtube")   return "https://youtube.com/@"+x;
    return "";
  }
  function _handlePrincipal(c){
    const r = c.redes||{};
    const v = r.instagram||r.facebook||r.tiktok||r.youtube||"";
    if(!v) return "";
    if(/^https?:\/\//i.test(v)) return v.replace(/^https?:\/\/(www\.)?/i,"");
    return v.charAt(0)==="@" ? v : "@"+v;
  }

  function _LogoSvg(id, sz){
    if(id==="facebook") return <svg width={sz} height={sz} viewBox="0 0 24 24" fill="currentColor"><path d="M24 12.07C24 5.4 18.63 0 12 0S0 5.4 0 12.07C0 18.1 4.39 23.1 10.13 24v-8.44H7.08v-3.49h3.05V9.41c0-3.02 1.79-4.69 4.53-4.69 1.31 0 2.68.24 2.68.24v2.97h-1.51c-1.49 0-1.96.93-1.96 1.89v2.25h3.33l-.53 3.49h-2.8V24C19.61 23.1 24 18.1 24 12.07z"/></svg>;
    if(id==="tiktok")   return <svg width={sz} height={sz} viewBox="0 0 24 24" fill="currentColor"><path d="M16.6 5.82a4.28 4.28 0 0 1-1.06-2.82h-3.2v12.4a2.6 2.6 0 1 1-2.6-2.6c.27 0 .53.04.78.12V9.66a5.83 5.83 0 0 0-.78-.06 5.8 5.8 0 1 0 5.8 5.8V9.03a7.5 7.5 0 0 0 4.36 1.4V7.23a4.3 4.3 0 0 1-3.3-1.41z"/></svg>;
    if(id==="youtube")  return <svg width={sz} height={sz} viewBox="0 0 24 24" fill="currentColor"><path d="M23.5 6.2a3 3 0 0 0-2.1-2.1C19.5 3.6 12 3.6 12 3.6s-7.5 0-9.4.5A3 3 0 0 0 .5 6.2 31 31 0 0 0 0 12a31 31 0 0 0 .5 5.8 3 3 0 0 0 2.1 2.1c1.9.5 9.4.5 9.4.5s7.5 0 9.4-.5a3 3 0 0 0 2.1-2.1A31 31 0 0 0 24 12a31 31 0 0 0-.5-5.8zM9.5 15.6V8.4l6.3 3.6z"/></svg>;
    return <svg width={sz} height={sz} viewBox="0 0 24 24" fill="currentColor"><path d="M12 2.16c3.2 0 3.58.01 4.85.07 1.17.05 1.8.25 2.23.41.56.22.96.48 1.38.9.42.42.68.82.9 1.38.16.42.36 1.06.41 2.23.06 1.27.07 1.65.07 4.85s-.01 3.58-.07 4.85c-.05 1.17-.25 1.8-.41 2.23-.22.56-.48.96-.9 1.38-.42.42-.82.68-1.38.9-.42.16-1.06.36-2.23.41-1.27.06-1.65.07-4.85.07s-3.58-.01-4.85-.07c-1.17-.05-1.8-.25-2.23-.41-.56-.22-.96-.48-1.38-.9-.42-.42-.68-.82-.9-1.38-.16-.42-.36-1.06-.41-2.23C2.17 15.58 2.16 15.2 2.16 12s.01-3.58.07-4.85c.05-1.17.25-1.8.41-2.23.22-.56.48-.96.9-1.38.42-.42.82-.68 1.38-.9.42-.16 1.06-.36 2.23-.41C8.42 2.17 8.8 2.16 12 2.16M12 0C8.74 0 8.33.01 7.05.07 5.78.13 4.9.33 4.14.63c-.79.3-1.46.72-2.13 1.38C1.35 2.68.93 3.35.63 4.14.33 4.9.13 5.78.07 7.05.01 8.33 0 8.74 0 12s.01 3.67.07 4.95c.06 1.27.26 2.15.56 2.91.3.79.72 1.46 1.38 2.13.67.66 1.34 1.08 2.13 1.38.76.3 1.64.5 2.91.56C8.33 23.99 8.74 24 12 24s3.67-.01 4.95-.07c1.27-.06 2.15-.26 2.91-.56.79-.3 1.46-.72 2.13-1.38.66-.67 1.08-1.34 1.38-2.13.3-.76.5-1.64.56-2.91.06-1.28.07-1.69.07-4.95s-.01-3.67-.07-4.95c-.06-1.27-.26-2.15-.56-2.91-.3-.79-.72-1.46-1.38-2.13C21.32 1.35 20.65.93 19.86.63c-.76-.3-1.64-.5-2.91-.56C15.67.01 15.26 0 12 0z"/><path d="M12 5.84A6.16 6.16 0 1 0 18.16 12 6.16 6.16 0 0 0 12 5.84zM12 16a4 4 0 1 1 4-4 4 4 0 0 1-4 4z"/><circle cx="18.41" cy="5.59" r="1.44"/></svg>;
  }

  const FF = "'Inter',system-ui,sans-serif";
  const ACC = "#E4405F";

  if(loading) return <div style={{padding:40,textAlign:"center",color:"#94a3b8",fontFamily:FF}}>Carregando concorrência…</div>;

  return <div style={{display:"flex",flexDirection:"column",gap:16,fontFamily:FF}}>

    <section style={{background:"#fff",border:"1px solid #e9eef5",borderRadius:16,padding:"20px 22px",boxShadow:"0 1px 3px rgba(15,23,42,.05)"}}>
      <div style={{display:"flex",alignItems:"flex-start",gap:14,flexWrap:"wrap",marginBottom:18}}>
        <div>
          <div style={{color:"#0f172a",fontSize:15,fontWeight:800,letterSpacing:-.2}}>Concorrentes</div>
          <div style={{color:"#94a3b8",fontSize:11.5,marginTop:3}}>Cadastre aqui uma vez e clique na rede pra abrir o perfil</div>
        </div>
        <div style={{marginLeft:"auto",display:"flex",alignItems:"center",gap:10}}>
          {saving && <span style={{color:"#94a3b8",fontSize:11}}>salvando…</span>}
          {_canEdit && <button type="button" onClick={function(){setModal({});}}
            style={{background:ACC,color:"#fff",border:"none",borderRadius:10,padding:"10px 16px",fontSize:12.5,fontWeight:700,cursor:"pointer",fontFamily:FF,display:"inline-flex",alignItems:"center",gap:7,boxShadow:"0 3px 10px rgba(228,64,95,.3)"}}>
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
            Adicionar concorrente
          </button>}
        </div>
      </div>

      {_comps.length===0
        ? <div style={{padding:"40px 20px",textAlign:"center",color:"#94a3b8",fontSize:13,background:"#f8fafc",borderRadius:12,border:"1px dashed #cbd5e1"}}>
            Nenhum concorrente cadastrado ainda.{_canEdit?" Clique em “Adicionar concorrente”.":""}
          </div>
        : <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(280px,1fr))",gap:14}}>
            {_comps.map(function(c){
              const redes = c.redes||{};
              return <div key={c.id} style={{border:"1px solid #e9eef5",borderRadius:15,padding:"15px 16px 14px",background:"#fff",transition:"box-shadow .18s,transform .18s",position:"relative"}}
                onMouseEnter={function(e){e.currentTarget.style.boxShadow="0 8px 22px rgba(15,23,42,.09)";e.currentTarget.style.transform="translateY(-1px)";}}
                onMouseLeave={function(e){e.currentTarget.style.boxShadow="none";e.currentTarget.style.transform="";}}>
                <div style={{display:"flex",alignItems:"center",gap:11,marginBottom:13}}>
                  <div style={{width:42,height:42,borderRadius:13,background:"#f1f5fb",display:"flex",alignItems:"center",justifyContent:"center",fontWeight:900,fontSize:16,color:"#64748b",flexShrink:0,boxShadow:"inset 0 0 0 1px #e4ebf5",overflow:"hidden"}}>
                    {c.logo
                      ? <img src={c.logo} alt="" style={{width:"100%",height:"100%",objectFit:"cover"}} onError={function(e){e.currentTarget.style.display="none";}}/>
                      : (c.name||"?").charAt(0).toUpperCase()}
                  </div>
                  <div style={{minWidth:0,flex:1}}>
                    <div style={{fontSize:13.5,fontWeight:800,letterSpacing:-.2,lineHeight:1.25,color:"#0f172a",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{c.name||"—"}</div>
                    <div style={{fontSize:10.5,color:"#94a3b8",marginTop:3,fontWeight:600,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{_handlePrincipal(c)}</div>
                  </div>
                  {_canEdit && <div style={{display:"flex",gap:4,flexShrink:0}}>
                    <button type="button" onClick={function(e){e.stopPropagation();setModal(c);}} title="Editar"
                      style={{background:"#fff",border:"1px solid #e2e8f0",borderRadius:7,width:26,height:26,cursor:"pointer",display:"inline-flex",alignItems:"center",justifyContent:"center",color:"#64748b"}}>
                      <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><path d="M11 4H4a2 2 0 00-2 2v14a2 2 0 002 2h14a2 2 0 002-2v-7"/><path d="M18.5 2.5a2.12 2.12 0 013 3L12 15l-4 1 1-4z"/></svg>
                    </button>
                    <button type="button" onClick={function(e){e.stopPropagation();delCompetitor(c.id);}} title="Excluir"
                      style={{background:"#fff",border:"1px solid #fecaca",borderRadius:7,width:26,height:26,cursor:"pointer",display:"inline-flex",alignItems:"center",justifyContent:"center",color:"#ef4444"}}>
                      <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14a2 2 0 01-2 2H8a2 2 0 01-2-2L5 6"/><path d="M10 11v6M14 11v6"/><path d="M9 6V4a1 1 0 011-1h4a1 1 0 011 1v2"/></svg>
                    </button>
                  </div>}
                </div>
                {/* Logos das redes: colorido quando cadastrada (clicável), cinza apagado quando não */}
                <div style={{display:"flex",gap:9,paddingTop:12,borderTop:"1px solid #f4f7fb"}}>
                  {REDES.map(function(r){
                    const url = _urlRede(r.id, redes[r.id]);
                    const base = {width:40,height:40,borderRadius:12,display:"flex",alignItems:"center",justifyContent:"center",textDecoration:"none",flexShrink:0,transition:"transform .15s,box-shadow .15s"};
                    if(!url) return <span key={r.id} title={r.label+" não cadastrado"} style={Object.assign({},base,{background:"#f4f7fb",color:"#cbd5e1",cursor:"not-allowed",boxShadow:"inset 0 0 0 1px #eaf0f6"})}>{_LogoSvg(r.id,20)}</span>;
                    return <a key={r.id} href={url} target="_blank" rel="noopener noreferrer" title={"Abrir no "+r.label}
                      style={Object.assign({},base,{background:r.cor,color:"#fff",boxShadow:"0 3px 10px "+r.cor+"59"})}
                      onMouseEnter={function(e){e.currentTarget.style.transform="translateY(-2px) scale(1.05)";}}
                      onMouseLeave={function(e){e.currentTarget.style.transform="";}}>
                      {_LogoSvg(r.id,20)}
                    </a>;
                  })}
                </div>
              </div>;
            })}
          </div>
      }

      {_comps.length>0 && <div style={{marginTop:16,display:"flex",gap:20,flexWrap:"wrap",fontSize:11,color:"#64748b",alignItems:"center"}}>
        <span style={{display:"inline-flex",alignItems:"center",gap:7}}><i style={{width:14,height:14,borderRadius:4,background:ACC,display:"inline-block"}}/> Rede cadastrada — clica e abre o perfil</span>
        <span style={{display:"inline-flex",alignItems:"center",gap:7}}><i style={{width:14,height:14,borderRadius:4,background:"#f4f7fb",boxShadow:"inset 0 0 0 1px #eaf0f6",display:"inline-block"}}/> Não cadastrada</span>
      </div>}
    </section>

    {modal && <_ConcCompModal redes={REDES} logoSvg={_LogoSvg} initial={modal} onClose={function(){setModal(null);}} onSave={function(v){
      if(modal.id) updateCompetitor(modal.id, v); else addCompetitor(v);
      setModal(null);
    }}/>}

  </div>;
}

// ── Sub: modal Concorrente — nome + as quatro redes juntas ──
function _ConcCompModal({redes,logoSvg,initial,onClose,onSave}){
  const [name,setName]=useState(initial.name||"");
  const [logo,setLogo]=useState(initial.logo||"");
  const [rd,setRd]=useState(Object.assign({instagram:"",facebook:"",tiktok:"",youtube:""}, initial.redes||{}));
  const FF="'Inter',system-ui,sans-serif";
  const _temAlguma = Object.keys(rd).some(function(k){return String(rd[k]||"").trim();});
  const inp={width:"100%",border:"1px solid #e2e8f0",borderRadius:10,padding:"10px 12px",fontSize:13,fontFamily:FF,outline:"none",background:"#fbfdff",boxSizing:"border-box",color:"#0f172a"};
  const lbl={display:"block",fontSize:9.5,fontWeight:800,letterSpacing:.7,textTransform:"uppercase",color:"#94a3b8",marginBottom:6};
  function salvar(){
    if(!name.trim()){ if(typeof pixelsToast!=="undefined") pixelsToast.warning("Informe o nome do concorrente.",3000); return; }
    if(!_temAlguma){ if(typeof pixelsToast!=="undefined") pixelsToast.warning("Cadastre pelo menos uma rede social.",3000); return; }
    const clean={}; Object.keys(rd).forEach(function(k){ const v=String(rd[k]||"").trim(); if(v) clean[k]=v; });
    onSave({name:name.trim(), logo:logo.trim(), redes:clean});
  }
  return <div onMouseDown={function(e){if(e.target===e.currentTarget)onClose();}}
    style={{position:"fixed",inset:0,zIndex:600,background:"rgba(15,23,42,0.55)",backdropFilter:"blur(6px)",display:"flex",alignItems:"flex-start",justifyContent:"center",padding:16,paddingTop:70,fontFamily:FF}}>
    <div style={{background:"#fff",borderRadius:18,width:"100%",maxWidth:520,boxShadow:"0 30px 70px rgba(15,23,42,0.25)",border:"1px solid #f1f5f9",overflow:"hidden",maxHeight:"88vh",overflowY:"auto"}}>
      <div style={{padding:"16px 20px",borderBottom:"1px solid #f2f6fa",display:"flex",alignItems:"center",gap:10}}>
        <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="#0f172a" strokeWidth="2.2" strokeLinecap="round"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
        <b style={{fontSize:14,fontWeight:800,color:"#0f172a",flex:1}}>{initial.id?"Editar concorrente":"Adicionar concorrente"}</b>
        <button type="button" onClick={onClose} style={{background:"none",border:"none",color:"#94a3b8",cursor:"pointer",fontSize:20,lineHeight:1,padding:"2px 6px"}}>×</button>
      </div>
      <div style={{padding:"18px 20px 20px"}}>
        <div style={{marginBottom:14}}>
          <label style={lbl}>Nome</label>
          <input value={name} onChange={function(e){setName(e.target.value);}} placeholder="Ex: LJS Soluções Ambientais" style={inp} autoFocus/>
        </div>
        <div style={{marginBottom:14}}>
          <label style={lbl}>Redes sociais — deixe em branco o que não tiver</label>
          {redes.map(function(r){
            return <div key={r.id} style={{display:"flex",alignItems:"center",gap:10,marginBottom:9}}>
              <span style={{width:32,height:32,borderRadius:9,background:r.cor,color:"#fff",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>{logoSvg(r.id,16)}</span>
              <input value={rd[r.id]||""} onChange={function(e){const v=e.target.value;setRd(function(p){return Object.assign({},p,{[r.id]:v});});}}
                placeholder={r.ph+" — opcional"} style={Object.assign({},inp,{flex:1})}/>
            </div>;
          })}
        </div>
        <div style={{marginBottom:16}}>
          <label style={lbl}>Logo (URL) — opcional</label>
          <input value={logo} onChange={function(e){setLogo(e.target.value);}} placeholder="https://…" style={inp}/>
        </div>
        <button type="button" onClick={salvar}
          style={{background:"#0f172a",border:"none",borderRadius:10,padding:"11px 0",width:"100%",color:"#fff",fontSize:13,fontWeight:700,cursor:"pointer",fontFamily:FF}}>
          {initial.id?"Salvar alterações":"Salvar concorrente"}
        </button>
      </div>
    </div>
  </div>;
}

// ======= 03_cliente_ferramentas.jsx =======
// Ferramentas do cliente: CFerramentas + CInfo, CMetricas, CBriefing, CContatos, CTimeline, CMetas, CDrive

/* ── CChecklistOnboarding ── */
function CChecklistOnboarding({cl}){
  const CHECKLIST_DEFAULT=[
    {id:"briefing",    label:"Briefing preenchido",               done:true},
    {id:"acesso_meta", label:"Acesso ao Meta Ads concedido",      done:true},
    {id:"acesso_google",label:"Acesso ao Google Ads concedido",   done:false},
    {id:"pixel",       label:"Pixel Meta instalado no site",      done:true},
    {id:"tag",         label:"Google Tag Manager configurado",    done:false},
    {id:"criativos",   label:"Criativos iniciais aprovados",      done:true},
    {id:"planilha",    label:"Planilha de acompanhamento enviada",done:false},
    {id:"reuniao",     label:"Reunião de kick-off realizada",     done:true},
  ];
  const [items,setItems]=useState(()=>{
    try{const s=localStorage.getItem("pixels-checklist-"+cl.id);return s?JSON.parse(s):CHECKLIST_DEFAULT;}
    catch{return CHECKLIST_DEFAULT;}
  });
  const toggle=(id)=>{
    const next=items.map(i=>i.id===id?{...i,done:!i.done}:i);
    setItems(next);
    try{localStorage.setItem("pixels-checklist-"+cl.id,JSON.stringify(next));}catch{}
  };
  const done=items.filter(i=>i.done).length;
  const pct=Math.round(done/items.length*100);
  return(
    <div style={{display:"flex",flexDirection:"column",gap:12}}>
      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:4}}>
        <div style={{color:C.tx,fontWeight:700,fontSize:13}}>Onboarding — {cl.name}</div>
        <div style={{color:pct===100?C.gr:C.a,fontWeight:800,fontSize:13}}>{done}/{items.length} · {pct}%</div>
      </div>
      <div style={{background:C.b1,borderRadius:99,height:6,overflow:"hidden",marginBottom:8}}>
        <div style={{width:pct+"%",height:"100%",background:pct===100?C.gr:C.a,borderRadius:99,transition:"width .3s"}}/>
      </div>
      {items.map(item=>(
        <div key={item.id} onClick={()=>toggle(item.id)}
          style={{display:"flex",alignItems:"center",gap:10,padding:"10px 14px",background:C.card,borderRadius:10,
            border:"1px solid "+(item.done?C.gr+"44":C.b1),cursor:"pointer",transition:"all .15s"}}>
          <div style={{width:20,height:20,borderRadius:6,border:"2px solid "+(item.done?C.gr:C.b1),
            background:item.done?C.gr:"transparent",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
            {item.done&&<span style={{color:"#fff",fontSize:11,fontWeight:900}}>✓</span>}
          </div>
          <span style={{color:item.done?C.ts:C.tx,fontSize:13,textDecoration:item.done?"line-through":"none"}}>{item.label}</span>
        </div>
      ))}
    </div>
  );
}

/* ── ROIChannelCard ── */
function ROIChannelCard({channel,color,icon,invest,setInvest,roas,setRoas,receita,setReceita,cplRoas,setCplRoas,marg,setMarg,liveCl,result,showAcr,setShowAcr,acr,setAcr,ticket,setTicket}){
  const channelLabel=channel==="meta"?"Meta Ads":"Google Ads";
  const liveData=channel==="meta"?liveCl?.meta:liveCl?.google;
  const inp={background:C.s1,border:"1px solid "+C.b1,borderRadius:9,padding:"8px 10px",color:C.tx,fontSize:12,outline:"none",width:"100%",boxSizing:"border-box",fontFamily:"inherit"};
  const lbl={color:C.ts,fontSize:9,fontWeight:700,textTransform:"uppercase",letterSpacing:.8,marginBottom:3,display:"block"};
  return(
    <div style={{background:C.card,border:"2px solid "+color+"33",borderRadius:14,padding:16,height:"100%",boxSizing:"border-box",display:"flex",flexDirection:"column",gap:10}}>
      <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:2}}>
        <span style={{fontSize:20}}>{icon}</span>
        <div style={{color,fontWeight:800,fontSize:13}}>{channelLabel}</div>
        {liveData&&<div style={{marginLeft:"auto",color:C.td,fontSize:9}}>atual: R${(liveData.spend||0).toLocaleString("pt-BR")} · ROAS {liveData.roas||"—"}x</div>}
      </div>
      <div style={{display:"grid",gridTemplateColumns:_pxMob()?"1fr":"1fr 1fr",gap:8}}>
        <div><label style={lbl}>Investimento R$</label><input value={invest} onChange={e=>setInvest(e.target.value)} placeholder="Ex: 5000" style={{...inp,borderColor:invest?color+"55":C.b1}}/></div>
        <div><label style={lbl}>ROAS esperado</label><input value={roas} onChange={e=>setRoas(e.target.value)} placeholder="Ex: 4.5" style={inp}/></div>
        <div><label style={lbl}>Receita real R$ (opt)</label><input value={receita} onChange={e=>setReceita(e.target.value)} placeholder="Substitui ROAS" style={inp}/></div>
        <div><label style={lbl}>CPL R$ (leads)</label><input value={cplRoas} onChange={e=>setCplRoas(e.target.value)} placeholder="Ex: 40" style={inp}/></div>
        <div><label style={lbl}>Margem %</label><input value={marg} onChange={e=>setMarg(e.target.value)} placeholder="Ex: 30" style={inp}/></div>
        <div><label style={lbl}>Ticket médio R$ (opt)</label><input value={ticket} onChange={e=>setTicket(e.target.value)} placeholder="Ex: 800" style={inp}/></div>
      </div>
      <div>
        <button onClick={()=>setShowAcr(!showAcr)} style={{background:"none",border:"none",color:C.ts,fontSize:11,cursor:"pointer",padding:0,fontWeight:600}}>
          {showAcr?"▼":"▶"} Simular acréscimo de investimento
        </button>
        {showAcr&&<input value={acr} onChange={e=>setAcr(e.target.value)} placeholder="+ R$ a acrescentar" style={{...inp,marginTop:6}}/>}
      </div>
      {result&&(
        <div style={{background:color+"0d",border:"1px solid "+color+"33",borderRadius:10,padding:"10px 12px",marginTop:4}}>
          <div style={{display:"grid",gridTemplateColumns:_pxMob()?"1fr":"1fr 1fr",gap:6}}>
            <div><div style={{color:C.td,fontSize:8}}>RECEITA</div><div style={{color,fontWeight:900,fontSize:15}}>R${Math.round(result.receita).toLocaleString("pt-BR")}</div></div>
            <div><div style={{color:C.td,fontSize:8}}>LUCRO LÍQ.</div><div style={{color:result.lucroLiq>=0?"#16a34a":"#dc2626",fontWeight:900,fontSize:15}}>R${Math.round(result.lucroLiq).toLocaleString("pt-BR")}</div></div>
            <div><div style={{color:C.td,fontSize:8}}>ROAS REAL</div><div style={{color,fontWeight:700,fontSize:12}}>{result.roas.toFixed(2)}x</div></div>
            <div><div style={{color:C.td,fontSize:8}}>ROI</div><div style={{color:result.roi>=0?"#16a34a":"#dc2626",fontWeight:700,fontSize:12}}>{result.roi.toFixed(0)}%</div></div>
          </div>
          {result.leadsEst&&<div style={{color:C.ts,fontSize:9,marginTop:6}}>~{result.leadsEst.min}–{result.leadsEst.max} leads estimados</div>}
        </div>
      )}
    </div>
  );
}

// Ferramentas do cliente: CFerramentas + CInfo, CMetricas, CBriefing, CContatos, CTimeline, CMetas, CDrive
// + helpers de dados: genTrend, buildMetaData, buildGoogleData, buildInstaData

function CFerramentas({cl,onMindmap}){
  let[toolTab,setToolTab]=useState("mindmap");
  let live=getLiveClient(cl.id)||cl;
  // ROI Calculator — por canal
  let[channels,setChannels]=useState({meta:true,google:false});
  // Meta — Atual
  let[investMetaA,setInvestMetaA]=useState(()=>live.meta&&live.meta.spend?String(Math.round(live.meta.spend)):"");
  let[roasMetaA,setRoasMetaA]=useState(()=>live.meta&&live.meta.roas?String(live.meta.roas):"");
  let[recMetaA,setRecMetaA]=useState("");
  let[cplMetaA,setCplMetaA]=useState(()=>{let l=live.meta;return l&&l.leads>0&&l.spend>0?String(Math.round(l.spend/l.leads)):"";});
  // Google — Atual
  let[investGoogA,setInvestGoogA]=useState(()=>live.google&&live.google.spend?String(Math.round(live.google.spend)):"");
  let[roasGoogA,setRoasGoogA]=useState(()=>live.google&&live.google.roas?String(live.google.roas):"");
  let[recGoogA,setRecGoogA]=useState("");
  let[cplGoogA,setCplGoogA]=useState(()=>{let g=live.google;return g&&g.leads>0&&g.spend>0?String(Math.round(g.spend/g.leads)):"";});
  // Margem única — usada em TODOS os cálculos (atual + previsões)
  let[margOtim,setMargOtim]=useState("30");
  // Aumentar investimento — toggle + valor acrescido por canal
  let[showAcrMeta,setShowAcrMeta]=useState(false);
  let[acrMeta,setAcrMeta]=useState("");
  let[showAcrGoog,setShowAcrGoog]=useState(false);
  let[acrGoog,setAcrGoog]=useState("");
  // Ticket médio por canal
  let[ticketMeta,setTicketMeta]=useState("");
  let[ticketGoog,setTicketGoog]=useState("");
  // Histórico de simulações
  let[simulations,setSimulations]=useState(function(){
    try{return JSON.parse(localStorage.getItem("pixels-roi-sims-"+cl.id)||"[]");}catch(e){return[];}
  });
  let[showSimHistory,setShowSimHistory]=useState(false);
  // Modo apresentação
  let[apresentacao,setApresentacao]=useState(false);

  let TOOLS=[
    {id:"mindmap",label:"Mapa Mental"},
    {id:"checklist",label:"Checklist Onboarding"},
    {id:"roi",label:"Calculadora ROI"},
    {id:"links",label:"Links Úteis"},
  ];

  let[links,setLinks]=useState(function(){
    try{let s=localStorage.getItem("pixels-links-"+cl.id);if(s)return JSON.parse(s);}catch(e){}
    return [];
  });
  let[linkForm,setLinkForm]=useState({label:"",url:""});
  let[showLinkForm,setShowLinkForm]=useState(false);

  let addLink=function(){
    if(!linkForm.url.trim())return;
    let next=[...links,{id:Date.now(),...linkForm}];
    setLinks(next);
    try{localStorage.setItem("pixels-links-"+cl.id,JSON.stringify(next));}catch(e){}
    setLinkForm({label:"",url:""});setShowLinkForm(false);
    if(window._sb)window._sb.from("clients").update({links:next,updated_by:CURRENT_USER.name}).eq("client_id",cl.id).then(()=>{}).catch(e=>console.warn("[cliente_ferramentas] db update falhou:",e?.message||e));
  };

  let inp={background:C.s1,border:"1px solid "+C.b1,borderRadius:9,padding:"8px 10px",color:C.tx,fontSize:12,outline:"none",width:"100%",boxSizing:"border-box",fontFamily:"inherit"};

  return(<div style={{display:"flex",flexDirection:"column",gap:0}}>
    {/* Tool tabs */}
    <div style={{display:"flex",gap:4,marginBottom:20,flexWrap:"wrap"}}>
      {TOOLS.map(function(t){
        return(<button key={t.id} onClick={()=>setToolTab(t.id)}
          style={{background:toolTab===t.id?C.a+"18":"transparent",border:"1px solid "+(toolTab===t.id?C.a:C.b1),borderRadius:99,padding:"7px 16px",color:toolTab===t.id?C.a:C.ts,fontWeight:toolTab===t.id?700:400,fontSize:12,cursor:"pointer",transition:"all .12s"}}>
          {t.label}
        </button>);
      })}
    </div>

    {/* Mapa Mental */}
    {toolTab==="mindmap"&&(<div style={{background:C.card,borderRadius:16,border:"1px solid "+C.b1,padding:"24px",textAlign:"center"}}>
      <div style={{fontSize:40,marginBottom:12}}>🧠</div>
      <div style={{color:C.tx,fontWeight:700,fontSize:16,marginBottom:6}}>Mapa Mental do Cliente</div>
      <div style={{color:C.td,fontSize:12,marginBottom:20}}>Visualize a estratégia, concorrentes e oportunidades do {cl.name}</div>
      <button onClick={onMindmap}
        style={{background:"linear-gradient(135deg,"+C.a+","+C.aD+")",color:"#fff",border:"none",borderRadius:12,padding:"12px 28px",fontWeight:700,fontSize:14,cursor:"pointer",boxShadow:"0 4px 18px "+C.a+"40"}}>
        Abrir Mapa Mental
      </button>
    </div>)}

    {/* Checklist Onboarding */}
    {toolTab==="checklist"&&<CChecklistOnboarding cl={cl}/>}

    {/* Calculadora ROI */}
    {toolTab==="roi"&&(()=>{
      let pn=v=>parseFloat(String(v).replace(",","."))||0;
      let fmt=v=>v.toLocaleString("pt-BR",{minimumFractionDigits:0,maximumFractionDigits:0});
      let fmtR=v=>"R$ "+fmt(v);
      let leadsRange=(inv,cplV)=>{if(!cplV||pn(cplV)<=0)return null;let mid=Math.round(pn(inv)/pn(cplV));return{mid,min:Math.round(mid*0.80),max:Math.round(mid*1.20)};};

      let calc=(invest,roas,receitaReal,margin,cplV)=>{
        let i=pn(invest),m=pn(margin)||30;
        if(!i)return null;
        let receita=receitaReal&&pn(receitaReal)>0?pn(receitaReal):(roas&&pn(roas)>0?i*pn(roas):0);
        if(!receita)return null;
        let r=receita/i;
        let lucroLiq=receita*(m/100)-i;
        let roi=i>0?(lucroLiq/i)*100:0;
        let leadsEst=cplV&&pn(cplV)>0?leadsRange(i,cplV):null;
        return{receita,lucroLiq,roi,leadsEst,invest:i,roas:r};
      };

      let rMetaA  = channels.meta  ? calc(investMetaA, roasMetaA, recMetaA, margOtim, cplMetaA) : null;
      let rGoogA  = channels.google? calc(investGoogA, roasGoogA, recGoogA, margOtim, cplGoogA) : null;

      let totalInvestA = (rMetaA?rMetaA.invest:0)+(rGoogA?rGoogA.invest:0);
      let totalRecA    = (rMetaA?rMetaA.receita:0)+(rGoogA?rGoogA.receita:0);
      let totalRoasA   = totalInvestA>0?totalRecA/totalInvestA:0;

      // Effective invest B — atual + acrescido (se toggle ativo)
      let effMetaInvest = channels.meta ? (showAcrMeta&&pn(acrMeta)>0 ? pn(investMetaA)+pn(acrMeta) : pn(investMetaA)) : 0;
      let effGoogInvest = channels.google? (showAcrGoog&&pn(acrGoog)>0 ? pn(investGoogA)+pn(acrGoog) : pn(investGoogA)) : 0;
      let totalInvestB  = effMetaInvest + effGoogInvest;

      let baseRoas = totalRoasA>0?totalRoasA:(live.meta&&live.meta.roas||3);
      let mOtim    = pn(margOtim)||30;

      // FIX 1: leads com investimento fixo (não multiplicado por f.mult)
      let FORECASTS = totalInvestB>0?[
        {id:"pessimist",label:"Pessimista",emoji:"😐",color:"#f59e0b",mult:0.80,desc:"ROAS −20%"},
        {id:"healthy",  label:"Saudável",  emoji:"✅",color:"#16a34a",mult:1.00,desc:"ROAS estável"},
        {id:"great",    label:"Otimista",  emoji:"🚀",color:"#4f46e8",mult:1.20,desc:"ROAS +20%"},
        {id:"super",    label:"Incrível",  emoji:"⚡",color:"#c026d3",mult:1.40,desc:"ROAS +40%"},
      ].map(f=>{
        let r=baseRoas*f.mult;
        let receita=totalInvestB*r;
        let lucroLiq=receita*(mOtim/100)-totalInvestB;
        let roi=totalInvestB>0?(lucroLiq/totalInvestB)*100:0;
        let diffReceita=totalRecA>0?receita-totalRecA:null; // FIX 2
        let metaLeads=channels.meta&&effMetaInvest>0&&pn(cplMetaA)>0?leadsRange(effMetaInvest,pn(cplMetaA)):null; // FIX 1
        let googLeads=channels.google&&effGoogInvest>0&&pn(cplGoogA)>0?leadsRange(effGoogInvest,pn(cplGoogA)):null;
        return{...f,roas:r,receita,lucroLiq,roi,diffReceita,metaLeads,googLeads};
      }):[];

      let bothCh = channels.meta&&channels.google;

      return(<div style={{display:"flex",flexDirection:"column",gap:14}}>

        {/* ── Seleção de canais + margem ── */}
        <div style={{display:"flex",alignItems:"center",gap:12,flexWrap:"wrap",justifyContent:"space-between"}}>
          <div style={{display:"flex",alignItems:"center",gap:8,flexWrap:"wrap"}}>
            <span style={{color:C.tx,fontWeight:700,fontSize:13}}>Calculadora ROI</span>
            <span style={{color:C.ts,fontSize:11}}>Canais:</span>
            {[{id:"meta",label:"Meta Ads",color:"#1877f2",icon:"meta"},{id:"google",label:"Google Ads",color:"#34a853",icon:"google"}].map(ch=>(
              <button key={ch.id} onClick={()=>setChannels(p=>({...p,[ch.id]:!p[ch.id]}))}
                style={{display:"flex",alignItems:"center",gap:5,background:channels[ch.id]?ch.color+"18":"var(--s1,#f8fafc)",color:channels[ch.id]?ch.color:"var(--ts,#94a3b8)",border:"2px solid "+(channels[ch.id]?ch.color:"var(--b1,#e2e8f0)"),borderRadius:9,padding:"5px 12px",fontSize:11,fontWeight:700,cursor:"pointer",transition:"all .15s"}}>
                <PlatformLogo id={ch.icon} size={14}/>{ch.label}
                {channels[ch.id]&&<span style={{background:ch.color,color:"#fff",borderRadius:"50%",width:13,height:13,display:"flex",alignItems:"center",justifyContent:"center",fontSize:7}}>✓</span>}
              </button>
            ))}
          </div>
        </div>

        {/* ══ GRID 4 COLUNAS ══ */}
        {(channels.meta||channels.google)&&(
          <div style={{display:"grid",gridTemplateColumns:_pxMob()?"1fr":"1fr 1fr 1fr 1fr",gap:12,alignItems:"start"}}>

            {/* Meta Ads — span 2 rows */}
            {channels.meta&&(
              <div style={{gridColumn:_pxMob()?"auto":(bothCh?"1":"1/3"),gridRow:_pxMob()?"auto":"1/3"}}>
                <ROIChannelCard channel="meta" color="#1877f2" icon="📘"
                  invest={investMetaA} setInvest={setInvestMetaA}
                  roas={roasMetaA} setRoas={setRoasMetaA}
                  receita={recMetaA} setReceita={setRecMetaA}
                  cplRoas={cplMetaA} setCplRoas={setCplMetaA}
                  marg={margOtim} setMarg={setMargOtim}
                  liveCl={live} result={rMetaA}
                  showAcr={showAcrMeta} setShowAcr={setShowAcrMeta}
                  acr={acrMeta} setAcr={setAcrMeta}
                  ticket={ticketMeta} setTicket={setTicketMeta}/>
              </div>
            )}

            {/* Google Ads — span 2 rows */}
            {channels.google&&(
              <div style={{gridColumn:_pxMob()?"auto":(bothCh?"2":"1/3"),gridRow:_pxMob()?"auto":"1/3"}}>
                <ROIChannelCard channel="google" color="#34a853" icon="🔍"
                  invest={investGoogA} setInvest={setInvestGoogA}
                  roas={roasGoogA} setRoas={setRoasGoogA}
                  receita={recGoogA} setReceita={setRecGoogA}
                  cplRoas={cplGoogA} setCplRoas={setCplGoogA}
                  marg={margOtim} setMarg={setMargOtim}
                  liveCl={live} result={rGoogA}
                  showAcr={showAcrGoog} setShowAcr={setShowAcrGoog}
                  acr={acrGoog} setAcr={setAcrGoog}
                  ticket={ticketGoog} setTicket={setTicketGoog}/>
              </div>
            )}

            {/* 4 Previsões — cols 3-4, rows 1-2 */}
            {FORECASTS.length>0?FORECASTS.map((f,i)=>(
              <div key={f.id} style={{gridColumn:_pxMob()?"auto":(i%2===0?"3":"4"),gridRow:_pxMob()?"auto":(i<2?"1":"2")}}>
                <div style={{background:f.color+"10",border:"1px solid "+f.color+"44",borderRadius:12,padding:"13px",height:"100%",boxSizing:"border-box",display:"flex",flexDirection:"column",gap:6}}>
                  {/* Header */}
                  <div style={{display:"flex",alignItems:"center",gap:6,marginBottom:2}}>
                    <span style={{fontSize:18}}>{f.emoji}</span>
                    <div>
                      <div style={{color:f.color,fontWeight:800,fontSize:12}}>{f.label}</div>
                      <div style={{color:"var(--ts,#94a3b8)",fontSize:8}}>ROAS {f.roas.toFixed(2)}x · {f.desc}</div>
                    </div>
                  </div>
                  {/* Receita */}
                  <div style={{background:"rgba(255,255,255,0.65)",borderRadius:8,padding:"7px 9px"}}>
                    <div style={{color:"var(--ts,#94a3b8)",fontSize:8}}>RECEITA</div>
                    <div style={{color:f.color,fontWeight:900,fontSize:16,letterSpacing:-0.5}}>{fmtR(f.receita)}</div>
                  </div>
                  {/* Lucro */}
                  <div style={{background:"rgba(255,255,255,0.65)",borderRadius:8,padding:"7px 9px"}}>
                    <div style={{color:"var(--ts,#94a3b8)",fontSize:8}}>LUCRO LÍQ.</div>
                    <div style={{color:f.lucroLiq>=0?"#16a34a":"#dc2626",fontWeight:900,fontSize:16,letterSpacing:-0.5}}>{fmtR(f.lucroLiq)}</div>
                  </div>
                  {/* ROI + VS ATUAL */}
                  <div style={{display:"grid",gridTemplateColumns:_pxMob()?"1fr":"1fr 1fr",gap:5}}>
                    <div style={{background:"rgba(255,255,255,0.65)",borderRadius:7,padding:"5px 7px",textAlign:"center"}}>
                      <div style={{color:"var(--ts,#94a3b8)",fontSize:7}}>ROI</div>
                      <div style={{color:f.roi>=0?"#16a34a":"#dc2626",fontWeight:800,fontSize:12}}>{f.roi.toFixed(0)}%</div>
                    </div>
                    <div style={{background:"rgba(255,255,255,0.65)",borderRadius:7,padding:"5px 7px",textAlign:"center"}}>
                      <div style={{color:"var(--ts,#94a3b8)",fontSize:7}}>VS ATUAL</div>
                      <div style={{color:f.diffReceita!=null?(f.diffReceita>=0?"#16a34a":"#dc2626"):C.td,fontWeight:800,fontSize:11}}>
                        {f.diffReceita!=null?((f.diffReceita>=0?"+":"")+fmtR(f.diffReceita)):"—"}
                      </div>
                    </div>
                  </div>
                  {/* Leads */}
                  {(f.metaLeads||f.googLeads)&&(
                    <div style={{display:"flex",flexDirection:"column",gap:3}}>
                      {f.metaLeads&&<div style={{background:"#1877f218",borderRadius:6,padding:"3px 7px",fontSize:8,color:"#1877f2",fontWeight:600}}>
                        <PlatformLogo id="meta" size={8}/> {fmt(f.metaLeads.min)}–{fmt(f.metaLeads.max)} leads est.
                      </div>}
                      {f.googLeads&&<div style={{background:"#34a85318",borderRadius:6,padding:"3px 7px",fontSize:8,color:"#34a853",fontWeight:600}}>
                        <PlatformLogo id="google" size={8}/> {fmt(f.googLeads.min)}–{fmt(f.googLeads.max)} leads est.
                      </div>}
                    </div>
                  )}
                </div>
              </div>
            )):(
              /* Placeholder quando sem resultado ainda */
              <div style={{gridColumn:_pxMob()?"auto":"3/5",gridRow:_pxMob()?"auto":"1/3",display:"flex",alignItems:"center",justifyContent:"center",background:C.s1,borderRadius:12,border:"1px dashed "+C.b1,minHeight:180}}>
                <div style={{textAlign:"center",color:C.td,fontSize:12,padding:20}}>
                  <div style={{fontSize:28,marginBottom:8}}>📊</div>
                  Preencha o investimento e o ROAS<br/>para ver as 4 previsões
                </div>
              </div>
            )}
          </div>
        )}

        {/* ══ PROJEÇÃO ANUAL — full width ══ */}
        {FORECASTS.length>0&&(<>
          <div style={{background:"linear-gradient(135deg,#4f46e818,#16a34a18)",border:"1px solid #4f46e833",borderRadius:12,padding:"14px 18px"}}>
            <div style={{color:C.tx,fontWeight:700,fontSize:12,marginBottom:10}}>📅 Projeção anual (12 meses) · âncora ROAS {baseRoas.toFixed(2)}x</div>
            <div style={{display:"grid",gridTemplateColumns:_pxMob()?"1fr":"repeat(4,1fr)",gap:8}}>
              {FORECASTS.map(f=>(
                <div key={f.id} style={{textAlign:"center",background:"rgba(255,255,255,0.55)",borderRadius:10,padding:"12px 8px"}}>
                  <div style={{fontSize:18,marginBottom:4}}>{f.emoji}</div>
                  <div style={{color:f.color,fontWeight:900,fontSize:16,letterSpacing:-0.5}}>{fmtR(f.receita*12)}</div>
                  <div style={{color:"var(--ts,#94a3b8)",fontSize:9,marginTop:2}}>{f.label}</div>
                  <div style={{color:f.lucroLiq*12>=0?"#16a34a":"#dc2626",fontSize:10,fontWeight:700,marginTop:2}}>lucro {fmtR(f.lucroLiq*12)}</div>
                </div>
              ))}
            </div>
          </div>

          {/* Aviso */}
          <div style={{background:"#fef3c7",border:"1px solid #fbbf24",borderRadius:8,padding:"10px 14px",fontSize:10,color:"#92400e",lineHeight:1.7}}>
            ⚠ <b>Projeções, não garantias.</b> Baseadas no ROAS histórico de {baseRoas.toFixed(2)}x. Leads com variação ±20%.
            Use para <b>planejar orçamento</b> e <b>alinhar expectativas</b> — nunca como promessa ao cliente.
          </div>
        </>)}

        {/* ══ BARRA DE AÇÕES ══ */}
        {(rMetaA||rGoogA)&&(()=>{
          let saveSim=()=>{
            let snap={
              id:Date.now(),
              date:new Date().toLocaleDateString("pt-BR",{day:"2-digit",month:"2-digit",year:"numeric",hour:"2-digit",minute:"2-digit"}),
              client:cl.name,
              meta:channels.meta?{invest:investMetaA,roas:roasMetaA,receita:recMetaA,cpl:cplMetaA,acr:showAcrMeta?acrMeta:"",result:rMetaA}:null,
              google:channels.google?{invest:investGoogA,roas:roasGoogA,receita:recGoogA,cpl:cplGoogA,acr:showAcrGoog?acrGoog:"",result:rGoogA}:null,
              marg:margOtim,
              forecasts:FORECASTS.map(f=>({label:f.label,emoji:f.emoji,color:f.color,receita:f.receita,lucroLiq:f.lucroLiq,roi:f.roi,roas:f.roas})),
            };
            let next=[snap,...simulations].slice(0,15);
            setSimulations(next);
            try{localStorage.setItem("pixels-roi-sims-"+cl.id,JSON.stringify(next));}catch(e){}
          };

          return(
            <div style={{display:"flex",gap:8,flexWrap:"wrap",alignItems:"center",justifyContent:"flex-end",paddingTop:4}}>
              <button onClick={()=>setShowSimHistory(v=>!v)}
                style={{display:"flex",alignItems:"center",gap:5,background:C.s1,border:"1px solid "+C.b1,borderRadius:9,padding:"7px 14px",color:C.ts,fontSize:11,fontWeight:600,cursor:"pointer"}}>
                🕒 Histórico {simulations.length>0&&<span style={{background:C.a+"22",color:C.a,borderRadius:99,padding:"1px 6px",fontSize:9,fontWeight:800}}>{simulations.length}</span>}
              </button>
              <button onClick={saveSim}
                style={{display:"flex",alignItems:"center",gap:5,background:C.a+"18",border:"1px solid "+C.a+"44",borderRadius:9,padding:"7px 14px",color:C.a,fontSize:11,fontWeight:700,cursor:"pointer"}}>
                💾 Salvar simulação
              </button>
              <button onClick={()=>setApresentacao(true)}
                style={{display:"flex",alignItems:"center",gap:5,background:"linear-gradient(135deg,"+C.a+","+C.aD+")",border:"none",borderRadius:9,padding:"7px 16px",color:"#fff",fontSize:11,fontWeight:700,cursor:"pointer",boxShadow:"0 3px 12px "+C.a+"40"}}>
                🖥 Modo Apresentação
              </button>
            </div>
          );
        })()}

        {/* ══ HISTÓRICO DE SIMULAÇÕES ══ */}
        {showSimHistory&&simulations.length>0&&(
          <div style={{background:C.card,borderRadius:14,border:"1px solid "+C.b1,overflow:"hidden"}}>
            <div style={{padding:"12px 16px",borderBottom:"1px solid "+C.b1,display:"flex",alignItems:"center",justifyContent:"space-between"}}>
              <span style={{color:C.tx,fontWeight:700,fontSize:13}}>🕒 Histórico de Simulações</span>
              <div style={{display:"flex",gap:6}}>
                <button onClick={()=>{setSimulations([]);try{localStorage.removeItem("pixels-roi-sims-"+cl.id);}catch(e){}}}
                  style={{background:"none",border:"1px solid "+C.b1,borderRadius:7,padding:"3px 9px",color:C.rd,fontSize:10,cursor:"pointer"}}>Limpar</button>
                <button onClick={()=>setShowSimHistory(false)}
                  style={{background:"none",border:"none",color:C.td,fontSize:14,cursor:"pointer",padding:"0 4px"}}>×</button>
              </div>
            </div>
            <div style={{maxHeight:320,overflowY:"auto"}}>
              {simulations.map((sim,si)=>(
                <div key={sim.id} style={{padding:"12px 16px",borderBottom:`1px solid ${C.b1}`,display:"flex",flexDirection:"column",gap:8}}>
                  <div style={{display:"flex",alignItems:"center",justifyContent:"space-between"}}>
                    <span style={{color:C.ts,fontSize:10,fontWeight:600}}>{sim.date}</span>
                    <span style={{color:C.td,fontSize:9}}>Margem {sim.marg}%</span>
                  </div>
                  <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(120px,1fr))",gap:6}}>
                    {sim.meta&&sim.meta.result&&(
                      <div style={{background:"#1877f210",borderRadius:8,padding:"7px 10px"}}>
                        <div style={{display:"flex",alignItems:"center",gap:4,marginBottom:3}}>
                          <PlatformLogo id="meta" size={10}/><span style={{color:"#1877f2",fontSize:9,fontWeight:700}}>Meta</span>
                        </div>
                        <div style={{color:C.tx,fontWeight:800,fontSize:12}}>R$ {sim.meta.result.receita.toLocaleString("pt-BR",{maximumFractionDigits:0})}</div>
                        <div style={{color:C.ts,fontSize:9}}>ROAS {sim.meta.result.roas.toFixed(2)}x · ROI {sim.meta.result.roi.toFixed(0)}%</div>
                      </div>
                    )}
                    {sim.google&&sim.google.result&&(
                      <div style={{background:"#34a85310",borderRadius:8,padding:"7px 10px"}}>
                        <div style={{display:"flex",alignItems:"center",gap:4,marginBottom:3}}>
                          <PlatformLogo id="google" size={10}/><span style={{color:"#34a853",fontSize:9,fontWeight:700}}>Google</span>
                        </div>
                        <div style={{color:C.tx,fontWeight:800,fontSize:12}}>R$ {sim.google.result.receita.toLocaleString("pt-BR",{maximumFractionDigits:0})}</div>
                        <div style={{color:C.ts,fontSize:9}}>ROAS {sim.google.result.roas.toFixed(2)}x · ROI {sim.google.result.roi.toFixed(0)}%</div>
                      </div>
                    )}
                    {sim.forecasts&&sim.forecasts.map(f=>(
                      <div key={f.label} style={{background:f.color+"10",borderRadius:8,padding:"7px 10px"}}>
                        <div style={{color:f.color,fontSize:9,fontWeight:700,marginBottom:2}}>{f.emoji} {f.label}</div>
                        <div style={{color:C.tx,fontWeight:800,fontSize:12}}>R$ {f.receita.toLocaleString("pt-BR",{maximumFractionDigits:0})}</div>
                        <div style={{color:C.ts,fontSize:9}}>ROI {f.roi.toFixed(0)}%</div>
                      </div>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* ══ MODO APRESENTAÇÃO — OVERLAY ══ */}
        {apresentacao&&(()=>{
          let fmtAp=v=>v.toLocaleString("pt-BR",{minimumFractionDigits:0,maximumFractionDigits:0});
          let fmtRAp=v=>"R$ "+fmtAp(v);
          let totalRecA2=(rMetaA?rMetaA.receita:0)+(rGoogA?rGoogA.receita:0);
          let totalLucA2=(rMetaA?rMetaA.lucroLiq:0)+(rGoogA?rGoogA.lucroLiq:0);
          let totalInvA2=(rMetaA?rMetaA.invest:0)+(rGoogA?rGoogA.invest:0);
          let totalRoasA2=totalInvA2>0?totalRecA2/totalInvA2:0;
          let dateStr=new Date().toLocaleDateString("pt-BR",{month:"long",year:"numeric"});
          let tsStr=new Date().toLocaleString("pt-BR");

          // ── Gera HTML limpo para PDF/PNG ─────────────────────
          let buildHTML=(forPrint)=>{
            let cards=(f,big)=>`
              <div style="background:${f.color}10;border:2px solid ${f.color}44;border-radius:14px;padding:${big?"20px":"16px"};text-align:center;break-inside:avoid;">
                <div style="font-size:${big?"32":"24"}px;margin-bottom:6px">${f.emoji}</div>
                <div style="color:${f.color};font-weight:800;font-size:${big?"16":"13"}px;margin-bottom:8px">${f.label}</div>
                <div style="color:#0f172a;font-weight:900;font-size:${big?"22":"18"}px;letter-spacing:-.5px">${fmtRAp(f.receita)}</div>
                <div style="color:#64748b;font-size:10px;margin:3px 0 10px">receita mensal est.</div>
                <div style="background:${f.color}18;border-radius:8px;padding:8px;margin-bottom:6px">
                  <div style="color:#94a3b8;font-size:9px">LUCRO LÍQ.</div>
                  <div style="color:${f.lucroLiq>=0?"#16a34a":"#dc2626"};font-weight:800;font-size:${big?"16":"13"}px">${fmtRAp(f.lucroLiq)}</div>
                </div>
                <div style="display:grid;grid-template-columns:1fr 1fr;gap:5px">
                  <div style="background:${f.color}18;border-radius:7px;padding:5px">
                    <div style="color:#94a3b8;font-size:8px">ROAS</div>
                    <div style="color:${f.color};font-weight:800;font-size:13px">${f.roas.toFixed(2)}x</div>
                  </div>
                  <div style="background:${f.color}18;border-radius:7px;padding:5px">
                    <div style="color:#94a3b8;font-size:8px">ROI</div>
                    <div style="color:${f.roi>=0?"#16a34a":"#dc2626"};font-weight:800;font-size:13px">${f.roi.toFixed(0)}%</div>
                  </div>
                </div>
              </div>`;

            let metaCard=rMetaA?`
              <div style="background:#fff;border-radius:14px;padding:16px;border:1px solid #1877f244;break-inside:avoid">
                <div style="display:flex;align-items:center;gap:8px;margin-bottom:10px">
                  <div style="width:28px;height:28px;background:#1877f218;border-radius:8px;display:flex;align-items:center;justify-content:center;font-size:14px">📘</div>
                  <span style="color:#1877f2;font-weight:700;font-size:13px">Meta Ads</span>
                </div>
                <div style="color:#0f172a;font-weight:900;font-size:22px;letter-spacing:-.5px">${fmtRAp(rMetaA.receita)}</div>
                <div style="color:#64748b;font-size:11px;margin-top:4px">Investimento: ${fmtRAp(rMetaA.invest)}</div>
                <div style="display:flex;gap:8px;margin-top:10px;flex-wrap:wrap">
                  <span style="background:#1877f218;color:#1877f2;border-radius:6px;padding:4px 10px;font-size:11px;font-weight:700">ROAS ${rMetaA.roas.toFixed(2)}x</span>
                  <span style="background:${rMetaA.roi>=0?"#16a34a18":"#dc262618"};color:${rMetaA.roi>=0?"#16a34a":"#dc2626"};border-radius:6px;padding:4px 10px;font-size:11px;font-weight:700">ROI ${rMetaA.roi.toFixed(0)}%</span>
                  <span style="background:#64748b18;color:#64748b;border-radius:6px;padding:4px 10px;font-size:11px">Lucro ${fmtRAp(rMetaA.lucroLiq)}</span>
                </div>
              </div>`:"";

            let googCard=rGoogA?`
              <div style="background:#fff;border-radius:14px;padding:16px;border:1px solid #34a85344;break-inside:avoid">
                <div style="display:flex;align-items:center;gap:8px;margin-bottom:10px">
                  <div style="width:28px;height:28px;background:#34a85318;border-radius:8px;display:flex;align-items:center;justify-content:center;font-size:14px">🔍</div>
                  <span style="color:#34a853;font-weight:700;font-size:13px">Google Ads</span>
                </div>
                <div style="color:#0f172a;font-weight:900;font-size:22px;letter-spacing:-.5px">${fmtRAp(rGoogA.receita)}</div>
                <div style="color:#64748b;font-size:11px;margin-top:4px">Investimento: ${fmtRAp(rGoogA.invest)}</div>
                <div style="display:flex;gap:8px;margin-top:10px;flex-wrap:wrap">
                  <span style="background:#34a85318;color:#34a853;border-radius:6px;padding:4px 10px;font-size:11px;font-weight:700">ROAS ${rGoogA.roas.toFixed(2)}x</span>
                  <span style="background:${rGoogA.roi>=0?"#16a34a18":"#dc262618"};color:${rGoogA.roi>=0?"#16a34a":"#dc2626"};border-radius:6px;padding:4px 10px;font-size:11px;font-weight:700">ROI ${rGoogA.roi.toFixed(0)}%</span>
                  <span style="background:#64748b18;color:#64748b;border-radius:6px;padding:4px 10px;font-size:11px">Lucro ${fmtRAp(rGoogA.lucroLiq)}</span>
                </div>
              </div>`:"";

            let totalCard=totalRecA2>0&&rMetaA&&rGoogA?`
              <div style="background:linear-gradient(135deg,#a140ff18,#6600cc10);border-radius:14px;padding:16px;border:1px solid #a140ff33;break-inside:avoid">
                <div style="color:#a140ff;font-weight:700;font-size:11px;margin-bottom:10px">⬡ TOTAL COMBINADO</div>
                <div style="color:#0f172a;font-weight:900;font-size:22px;letter-spacing:-.5px">${fmtRAp(totalRecA2)}</div>
                <div style="color:#64748b;font-size:11px;margin-top:4px">Investimento: ${fmtRAp(totalInvA2)}</div>
                <div style="display:flex;gap:8px;margin-top:10px;flex-wrap:wrap">
                  <span style="background:#a140ff18;color:#a140ff;border-radius:6px;padding:4px 10px;font-size:11px;font-weight:700">ROAS ${totalRoasA2.toFixed(2)}x</span>
                  <span style="background:${totalLucA2>=0?"#16a34a18":"#dc262618"};color:${totalLucA2>=0?"#16a34a":"#dc2626"};border-radius:6px;padding:4px 10px;font-size:11px;font-weight:700">Lucro ${fmtRAp(totalLucA2)}</span>
                </div>
              </div>`:"";

            let forecastSection=FORECASTS.length>0?`
              <div style="break-before:${forPrint?"avoid":"auto"}">
                <div style="font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.8px;color:#64748b;margin-bottom:14px;margin-top:8px">🎯 Projeções de Crescimento — Margem ${margOtim}%</div>
                <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:12px">
                  ${FORECASTS.map(f=>cards(f,true)).join("")}
                </div>
              </div>
              <div>
                <div style="font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.8px;color:#64748b;margin-bottom:14px;margin-top:8px">📅 Projeção Anual (12 meses) · ROAS âncora ${baseRoas.toFixed(2)}x</div>
                <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:12px">
                  ${FORECASTS.map(f=>`
                    <div style="background:linear-gradient(135deg,${f.color}20,${f.color}08);border:1px solid ${f.color}44;border-radius:14px;padding:18px;text-align:center;break-inside:avoid">
                      <div style="font-size:22px;margin-bottom:6px">${f.emoji}</div>
                      <div style="color:${f.color};font-weight:900;font-size:20px;letter-spacing:-.5px">${fmtRAp(f.receita*12)}</div>
                      <div style="color:#64748b;font-size:10px;margin-top:4px">${f.label}</div>
                      <div style="color:${f.lucroLiq*12>=0?"#16a34a":"#dc2626"};font-size:12px;font-weight:700;margin-top:8px">lucro ${fmtRAp(f.lucroLiq*12)}</div>
                    </div>`).join("")}
                </div>
              </div>`:"";

            return `
              <div style="font-family:'Outfit',system-ui,sans-serif;background:#fff;color:#0f172a">
                <!-- Header -->
                <div style="background:linear-gradient(135deg,#a140ff,#6600cc);padding:28px 36px;border-radius:16px 16px 0 0;margin-bottom:0">
                  <div style="color:rgba(255,255,255,0.65);font-size:10px;font-weight:700;letter-spacing:1px;text-transform:uppercase;margin-bottom:6px">ANÁLISE DE PERFORMANCE · PIXELS AGÊNCIA</div>
                  <div style="color:#fff;font-weight:900;font-size:26px;letter-spacing:-.5px">${cl.name}</div>
                  <div style="color:rgba(255,255,255,0.65);font-size:12px;margin-top:4px">${dateStr}</div>
                </div>
                <!-- Body -->
                <div style="padding:28px 36px;display:flex;flex-direction:column;gap:24px;border:1px solid #e2e8f0;border-top:none;border-radius:0 0 16px 16px">
                  <div>
                    <div style="font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.8px;color:#64748b;margin-bottom:14px">📊 Situação Atual</div>
                    <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:12px">
                      ${metaCard}${googCard}${totalCard}
                    </div>
                  </div>
                  ${forecastSection}
                  <!-- Rodapé -->
                  <div style="text-align:center;color:#94a3b8;font-size:9px;padding-top:12px;border-top:1px solid #e2e8f0">
                    Simulação gerada em ${tsStr} · Pixels Agência OS · Projeções baseadas em dados históricos — não são garantias de resultado.
                  </div>
                </div>
              </div>`;
          };

          // ── Exportar PDF ──────────────────────────────────────
          let handlePDF=()=>{
            // escape de texto interpolado em HTML — evita injeção via cl.name
            const esc=s=>String(s||"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");
            const html=`<!DOCTYPE html><html lang="pt-BR"><head>
              <meta charset="UTF-8"/>
              <title>Análise ${esc(cl.name)} — Pixels Agência</title>
              <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap" rel="stylesheet"/>
              <style>
                *{margin:0;padding:0;box-sizing:border-box;}
                body{font-family:'Inter',system-ui,sans-serif;background:#fff;padding:24px;}
                @media print{
                  body{padding:0;}
                  @page{margin:10mm;size:A4;}
                  .no-print{display:none!important;}
                  div{break-inside:avoid-column;}
                }
              </style>
            </head><body>
              <div class="no-print" style="background:#f1f5f9;padding:12px 20px;margin-bottom:20px;border-radius:8px;display:flex;align-items:center;justify-content:space-between;gap:12px">
                <span style="font-family:system-ui;font-size:13px;color:#475569;font-weight:600">📄 Pronto para salvar como PDF</span>
                <div style="display:flex;gap:8px">
                  <button onclick="window.print()" style="background:#a140ff;color:#fff;border:none;border-radius:8px;padding:8px 20px;font-size:13px;font-weight:700;cursor:pointer;font-family:system-ui">
                    🖨 Salvar como PDF
                  </button>
                  <button onclick="window.close()" style="background:#e2e8f0;color:#475569;border:none;border-radius:8px;padding:8px 14px;font-size:13px;cursor:pointer;font-family:system-ui">
                    ✕
                  </button>
                </div>
              </div>
              ${buildHTML(true)}
            </body></html>`;
            // Em vez de document.write (descontinuado e com riscos de parser),
            // entregamos o HTML como Blob URL para a nova janela.
            try{
              const blob=new Blob([html],{type:"text/html;charset=utf-8"});
              const url=URL.createObjectURL(blob);
              const w=window.open(url,"_blank","width=1000,height=750");
              if(!w){URL.revokeObjectURL(url);pixelsToast.warning("Permita pop-ups para abrir o PDF.");return;}
              // libera a URL após a janela carregar (60s margem de segurança)
              setTimeout(()=>{try{URL.revokeObjectURL(url);}catch(e){}},60000);
            }catch(e){
              console.warn("Falha ao gerar PDF:",e);
              pixelsToast.error("Não foi possível abrir a janela do PDF.");
            }
          };

          // ── Exportar PNG via html2canvas ──────────────────────
          let[exporting,setExporting]=useState(false);
          let[exportMsg,setExportMsg]=useState("");
          let handlePNG=()=>{
            setExporting(true);
            setExportMsg("Preparando imagem...");
            let doCapture=()=>{
              let el=document.getElementById("ap-capture");
              if(!el||!window.html2canvas){setExporting(false);setExportMsg("Erro ao carregar biblioteca.");return;}
              setExportMsg("Capturando...");
              window.html2canvas(el,{
                scale:2,
                useCORS:true,
                allowTaint:true,
                backgroundColor:"#ffffff",
                logging:false,
                windowWidth:1000,
              }).then(canvas=>{
                let link=document.createElement("a");
                link.download="Analise_"+cl.name.replace(/\s+/g,"_")+"_"+new Date().toLocaleDateString("pt-BR").replace(/\//g,"-")+".png";
                link.href=canvas.toDataURL("image/png",1.0);
                link.click();
                setExporting(false);
                setExportMsg("");
              }).catch(()=>{setExporting(false);setExportMsg("Erro na captura. Tente o PDF.");});
            };
            if(window.html2canvas){doCapture();return;}
            let s=document.createElement("script");
            s.src="https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js";
            s.onload=doCapture;
            s.onerror=()=>{setExporting(false);setExportMsg("Sem conexão para carregar biblioteca.");};
            document.head.appendChild(s);
          };

          return(
            <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.88)",zIndex:2000,display:"flex",alignItems:"center",justifyContent:"center",padding:20,backdropFilter:"blur(8px)"}}
              onClick={e=>{if(e.target===e.currentTarget)setApresentacao(false);}}>
              <div style={{background:"#f8fafc",borderRadius:20,width:"100%",maxWidth:960,maxHeight:"92vh",overflow:"hidden",boxShadow:"0 32px 80px rgba(0,0,0,0.5)",display:"flex",flexDirection:"column"}}>

                {/* Toolbar — fora do conteúdo exportável */}
                <div style={{background:"#fff",borderBottom:"1px solid #e2e8f0",padding:"12px 20px",display:"flex",alignItems:"center",justifyContent:"space-between",flexShrink:0,borderRadius:"20px 20px 0 0"}}>
                  <div style={{display:"flex",alignItems:"center",gap:6}}>
                    <span style={{color:"#64748b",fontSize:12,fontWeight:600}}>⬡</span>
                    <span style={{color:"#0f172a",fontSize:13,fontWeight:700}}>{cl.name} — Análise de Performance</span>
                  </div>
                  <div style={{display:"flex",alignItems:"center",gap:8}}>
                    {exportMsg&&<span style={{color:"#64748b",fontSize:11}}>{exportMsg}</span>}
                    {/* PNG */}
                    <button onClick={handlePNG} disabled={exporting}
                      style={{display:"flex",alignItems:"center",gap:6,background:exporting?"#e2e8f0":"#0f172a",color:exporting?"#94a3b8":"#fff",border:"none",borderRadius:9,padding:"8px 16px",fontSize:12,fontWeight:700,cursor:exporting?"not-allowed":"pointer",transition:"all .15s"}}>
                      🖼 {exporting?"Gerando...":"Exportar PNG"}
                    </button>
                    {/* PDF */}
                    <button onClick={handlePDF}
                      style={{display:"flex",alignItems:"center",gap:6,background:"linear-gradient(135deg,#a140ff,#6600cc)",color:"#fff",border:"none",borderRadius:9,padding:"8px 16px",fontSize:12,fontWeight:700,cursor:"pointer",boxShadow:"0 3px 12px #a140ff40"}}>
                      📄 Exportar PDF
                    </button>
                    <button onClick={()=>setApresentacao(false)}
                      style={{background:"#f1f5f9",border:"none",borderRadius:8,width:32,height:32,cursor:"pointer",fontSize:14,color:"#64748b",display:"flex",alignItems:"center",justifyContent:"center"}}>
                      ✕
                    </button>
                  </div>
                </div>

                {/* Conteúdo capturável */}
                <div style={{overflowY:"auto",flex:1,padding:"20px"}}>
                  <div id="ap-capture" style={{background:"#fff",borderRadius:16,overflow:"hidden",boxShadow:"0 2px 20px rgba(0,0,0,0.08)"}}>

                    {/* Header */}
                    <div style={{background:"linear-gradient(135deg,#a140ff,#6600cc)",padding:"28px 32px"}}>
                      <div style={{color:"rgba(255,255,255,0.6)",fontSize:10,fontWeight:700,letterSpacing:1,textTransform:"uppercase",marginBottom:6}}>Análise de Performance · Pixels Agência</div>
                      <div style={{color:"#fff",fontWeight:900,fontSize:24,letterSpacing:-.5}}>{cl.name}</div>
                      <div style={{color:"rgba(255,255,255,0.6)",fontSize:12,marginTop:4}}>{dateStr}</div>
                    </div>

                    {/* Corpo */}
                    <div style={{padding:"28px 32px",display:"flex",flexDirection:"column",gap:24,background:"#fff"}}>

                      {/* Situação atual */}
                      <div>
                        <div style={{fontSize:10,fontWeight:700,textTransform:"uppercase",letterSpacing:.8,color:"#64748b",marginBottom:14}}>📊 Situação Atual</div>
                        <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(200px,1fr))",gap:12}}>
                          {rMetaA&&(
                            <div style={{background:"#fff",borderRadius:14,padding:"16px",border:"1px solid #1877f233"}}>
                              <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:10}}>
                                <div style={{width:28,height:28,background:"#1877f218",borderRadius:8,display:"flex",alignItems:"center",justifyContent:"center",fontSize:14}}>📘</div>
                                <span style={{color:"#1877f2",fontWeight:700,fontSize:13}}>Meta Ads</span>
                              </div>
                              <div style={{color:"#0f172a",fontWeight:900,fontSize:22,letterSpacing:-.5}}>{fmtRAp(rMetaA.receita)}</div>
                              <div style={{color:"#64748b",fontSize:11,marginTop:4}}>Investimento: {fmtRAp(rMetaA.invest)}</div>
                              <div style={{display:"flex",gap:6,marginTop:10,flexWrap:"wrap"}}>
                                <span style={{background:"#1877f218",color:"#1877f2",borderRadius:6,padding:"4px 10px",fontSize:11,fontWeight:700}}>ROAS {rMetaA.roas.toFixed(2)}x</span>
                                <span style={{background:rMetaA.roi>=0?"#16a34a18":"#dc262618",color:rMetaA.roi>=0?"#16a34a":"#dc2626",borderRadius:6,padding:"4px 10px",fontSize:11,fontWeight:700}}>ROI {rMetaA.roi.toFixed(0)}%</span>
                                <span style={{background:"#64748b12",color:"#64748b",borderRadius:6,padding:"4px 10px",fontSize:11}}>Lucro {fmtRAp(rMetaA.lucroLiq)}</span>
                              </div>
                            </div>
                          )}
                          {rGoogA&&(
                            <div style={{background:"#fff",borderRadius:14,padding:"16px",border:"1px solid #34a85333"}}>
                              <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:10}}>
                                <div style={{width:28,height:28,background:"#34a85318",borderRadius:8,display:"flex",alignItems:"center",justifyContent:"center",fontSize:14}}>🔍</div>
                                <span style={{color:"#34a853",fontWeight:700,fontSize:13}}>Google Ads</span>
                              </div>
                              <div style={{color:"#0f172a",fontWeight:900,fontSize:22,letterSpacing:-.5}}>{fmtRAp(rGoogA.receita)}</div>
                              <div style={{color:"#64748b",fontSize:11,marginTop:4}}>Investimento: {fmtRAp(rGoogA.invest)}</div>
                              <div style={{display:"flex",gap:6,marginTop:10,flexWrap:"wrap"}}>
                                <span style={{background:"#34a85318",color:"#34a853",borderRadius:6,padding:"4px 10px",fontSize:11,fontWeight:700}}>ROAS {rGoogA.roas.toFixed(2)}x</span>
                                <span style={{background:rGoogA.roi>=0?"#16a34a18":"#dc262618",color:rGoogA.roi>=0?"#16a34a":"#dc2626",borderRadius:6,padding:"4px 10px",fontSize:11,fontWeight:700}}>ROI {rGoogA.roi.toFixed(0)}%</span>
                                <span style={{background:"#64748b12",color:"#64748b",borderRadius:6,padding:"4px 10px",fontSize:11}}>Lucro {fmtRAp(rGoogA.lucroLiq)}</span>
                              </div>
                            </div>
                          )}
                          {totalRecA2>0&&rMetaA&&rGoogA&&(
                            <div style={{background:"linear-gradient(135deg,#a140ff10,#6600cc06)",borderRadius:14,padding:"16px",border:"1px solid #a140ff33"}}>
                              <div style={{color:"#a140ff",fontWeight:700,fontSize:11,marginBottom:10}}>⬡ TOTAL COMBINADO</div>
                              <div style={{color:"#0f172a",fontWeight:900,fontSize:22,letterSpacing:-.5}}>{fmtRAp(totalRecA2)}</div>
                              <div style={{color:"#64748b",fontSize:11,marginTop:4}}>Investimento: {fmtRAp(totalInvA2)}</div>
                              <div style={{display:"flex",gap:6,marginTop:10,flexWrap:"wrap"}}>
                                <span style={{background:"#a140ff18",color:"#a140ff",borderRadius:6,padding:"4px 10px",fontSize:11,fontWeight:700}}>ROAS {totalRoasA2.toFixed(2)}x</span>
                                <span style={{background:totalLucA2>=0?"#16a34a18":"#dc262618",color:totalLucA2>=0?"#16a34a":"#dc2626",borderRadius:6,padding:"4px 10px",fontSize:11,fontWeight:700}}>Lucro {fmtRAp(totalLucA2)}</span>
                              </div>
                            </div>
                          )}
                        </div>
                      </div>

                      {/* Projeções */}
                      {FORECASTS.length>0&&(
                        <div>
                          <div style={{fontSize:10,fontWeight:700,textTransform:"uppercase",letterSpacing:.8,color:"#64748b",marginBottom:14}}>🎯 Projeções de Crescimento — Margem {margOtim}%</div>
                          <div style={{display:"grid",gridTemplateColumns:_pxMob()?"1fr":"repeat(4,1fr)",gap:12}}>
                            {FORECASTS.map(f=>(
                              <div key={f.id} style={{background:f.color+"0e",border:"2px solid "+f.color+"44",borderRadius:14,padding:"18px",textAlign:"center"}}>
                                <div style={{fontSize:28,marginBottom:8}}>{f.emoji}</div>
                                <div style={{color:f.color,fontWeight:800,fontSize:14,marginBottom:10}}>{f.label}</div>
                                <div style={{color:"#0f172a",fontWeight:900,fontSize:20,letterSpacing:-.5}}>{fmtRAp(f.receita)}</div>
                                <div style={{color:"#94a3b8",fontSize:10,marginTop:3,marginBottom:12}}>receita mensal est.</div>
                                <div style={{background:f.color+"18",borderRadius:9,padding:"8px",marginBottom:6}}>
                                  <div style={{color:"#94a3b8",fontSize:9}}>LUCRO LÍQ.</div>
                                  <div style={{color:f.lucroLiq>=0?"#16a34a":"#dc2626",fontWeight:800,fontSize:15}}>{fmtRAp(f.lucroLiq)}</div>
                                </div>
                                <div style={{display:"grid",gridTemplateColumns:_pxMob()?"1fr":"1fr 1fr",gap:5}}>
                                  <div style={{background:f.color+"18",borderRadius:7,padding:"6px"}}>
                                    <div style={{color:"#94a3b8",fontSize:8}}>ROAS</div>
                                    <div style={{color:f.color,fontWeight:800,fontSize:13}}>{f.roas.toFixed(2)}x</div>
                                  </div>
                                  <div style={{background:f.color+"18",borderRadius:7,padding:"6px"}}>
                                    <div style={{color:"#94a3b8",fontSize:8}}>ROI</div>
                                    <div style={{color:f.roi>=0?"#16a34a":"#dc2626",fontWeight:800,fontSize:13}}>{f.roi.toFixed(0)}%</div>
                                  </div>
                                </div>
                              </div>
                            ))}
                          </div>
                        </div>
                      )}

                      {/* Projeção anual */}
                      {FORECASTS.length>0&&(
                        <div>
                          <div style={{fontSize:10,fontWeight:700,textTransform:"uppercase",letterSpacing:.8,color:"#64748b",marginBottom:14}}>📅 Projeção Anual (12 meses) · ROAS âncora {baseRoas.toFixed(2)}x</div>
                          <div style={{display:"grid",gridTemplateColumns:_pxMob()?"1fr":"repeat(4,1fr)",gap:12}}>
                            {FORECASTS.map(f=>(
                              <div key={f.id} style={{background:"linear-gradient(135deg,"+f.color+"18,"+f.color+"06)",borderRadius:14,padding:"18px",border:"1px solid "+f.color+"33",textAlign:"center"}}>
                                <div style={{fontSize:22,marginBottom:6}}>{f.emoji}</div>
                                <div style={{color:f.color,fontWeight:900,fontSize:19,letterSpacing:-.5}}>{fmtRAp(f.receita*12)}</div>
                                <div style={{color:"#64748b",fontSize:10,marginTop:4}}>{f.label}</div>
                                <div style={{color:f.lucroLiq*12>=0?"#16a34a":"#dc2626",fontSize:12,fontWeight:700,marginTop:8}}>lucro {fmtRAp(f.lucroLiq*12)}</div>
                              </div>
                            ))}
                          </div>
                        </div>
                      )}

                      {/* Rodapé */}
                      <div style={{textAlign:"center",color:"#94a3b8",fontSize:9,paddingTop:12,borderTop:"1px solid #f1f5f9"}}>
                        Simulação gerada em {tsStr} · Pixels Agência OS · Projeções baseadas em dados históricos — não são garantias de resultado.
                      </div>
                    </div>
                  </div>
                </div>

              </div>
            </div>
          );
        })()}

      </div>);
    })()}

    {/* Links Úteis */}
    {toolTab==="links"&&(<div style={{background:C.card,borderRadius:16,border:"1px solid "+C.b1,overflow:"hidden"}}>
      <div style={{padding:"14px 18px",borderBottom:"1px solid "+C.b1,display:"flex",alignItems:"center",justifyContent:"space-between"}}>
        <div style={{color:C.tx,fontWeight:700,fontSize:13}}>Links Úteis do Cliente</div>
        <button onClick={()=>setShowLinkForm(true)} style={{background:C.a+"18",color:C.a,border:"1px solid "+C.a+"33",borderRadius:8,padding:"4px 12px",fontSize:11,fontWeight:700,cursor:"pointer"}}>+ Link</button>
      </div>
      {showLinkForm&&(<div style={{padding:"14px 18px",borderBottom:"1px solid "+C.b1,display:"flex",flexDirection:"column",gap:8}}>
        <div><div style={{color:C.td,fontSize:10,marginBottom:3}}>Nome do link</div><input value={linkForm.label} onChange={e=>setLinkForm(function(p){return{...p,label:e.target.value};})} placeholder="Ex: Site, Drive, Relatório..." style={inp}/></div>
        <div><div style={{color:C.td,fontSize:10,marginBottom:3}}>URL</div><input value={linkForm.url} onChange={e=>setLinkForm(function(p){return{...p,url:e.target.value};})} placeholder="https://..." style={inp}/></div>
        <div style={{display:"flex",gap:8}}>
          <button onClick={()=>setShowLinkForm(false)} style={{flex:1,background:C.s1,border:"1px solid "+C.b1,borderRadius:9,padding:"7px 0",color:C.ts,fontSize:12,cursor:"pointer"}}>Cancelar</button>
          <button onClick={addLink} style={{flex:2,background:C.a,color:"#fff",border:"none",borderRadius:9,padding:"7px 0",fontWeight:700,fontSize:12,cursor:"pointer"}}>Salvar</button>
        </div>
      </div>)}
      <div style={{padding:"8px 0"}}>
        {links.length===0&&<div style={{padding:"24px",textAlign:"center",color:C.td,fontSize:12}}>Nenhum link cadastrado. Adicione sites, drives, relatórios...</div>}
        {links.map(function(l,i){
          return(<div key={l.id} style={{display:"flex",alignItems:"center",gap:10,padding:"10px 18px",borderBottom:i<links.length-1?"1px solid "+C.b1+"33":"none"}}>
            <div style={{width:28,height:28,borderRadius:8,background:C.a+"18",display:"flex",alignItems:"center",justifyContent:"center",fontSize:13,flexShrink:0}}>🔗</div>
            <div style={{flex:1,minWidth:0}}>
              <div style={{color:C.tx,fontWeight:600,fontSize:12}}>{l.label||l.url}</div>
              <div style={{color:C.td,fontSize:10,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{l.url}</div>
            </div>
            <a href={l.url} target="_blank" rel="noopener" style={{background:C.a,color:"#fff",borderRadius:8,padding:"5px 12px",fontSize:11,fontWeight:700,textDecoration:"none",flexShrink:0}}>Abrir</a>
            <button onClick={()=>{let next=links.filter(function(x){return x.id!==l.id;});setLinks(next);try{localStorage.setItem("pixels-links-"+cl.id,JSON.stringify(next));}catch(e){}if(window._sb)window._sb.from("clients").update({links:next,updated_by:CURRENT_USER.name}).eq("client_id",cl.id).then(()=>{}).catch(e=>console.warn("[cliente_ferramentas] db update falhou:",e?.message||e));}}
              style={{background:"none",border:"none",color:C.td,cursor:"pointer",fontSize:13,padding:"4px"}}>×</button>
          </div>);
        })}
      </div>
    </div>)}
  </div>);
}

/* ── INFORMAÇÕES TAB ───────────────────────── */
function CInfo({cl}){
  let[infoTab,setInfoTab]=useState("briefing");
  let isSocio=CURRENT_USER&&CURRENT_USER.level===1;
  let INFO_TABS=[
    {id:"briefing",    label:"Briefing"},
    {id:"orientacoes", label:"Orientações para a equipe"},
    {id:"contatos",    label:"Contatos"},
    {id:"timeline",    label:"Linha do Tempo"},
    {id:"metas",       label:"Metas"},
    {id:"drive",       label:"Drive"},
  ];
  if(isSocio)INFO_TABS.push({id:"metricas",label:"Métricas ✏"});
  return(<div style={{display:"flex",flexDirection:"column",gap:0}}>
    <div style={{display:"flex",gap:4,marginBottom:20,flexWrap:"wrap"}}>
      {INFO_TABS.map(function(t){
        return(<button key={t.id} onClick={()=>setInfoTab(t.id)}
          style={{background:infoTab===t.id?C.a+"18":"transparent",border:"1px solid "+(infoTab===t.id?C.a:C.b1),borderRadius:99,padding:"7px 16px",color:infoTab===t.id?C.a:C.ts,fontWeight:infoTab===t.id?700:400,fontSize:12,cursor:"pointer",transition:"all .12s"}}>
          {t.label}
        </button>);
      })}
    </div>
    {infoTab==="briefing"&&<CBriefing cl={cl}/>}
    {infoTab==="orientacoes"&&<COrientacoes cl={cl}/>}
    {infoTab==="contatos"&&<CContatos cl={cl}/>}
    {infoTab==="timeline"&&<CTimeline cl={cl}/>}
    {infoTab==="metas"&&<CMetasWithUnits cl={cl}/>}
    {infoTab==="drive"&&<CDrive cl={cl}/>}
    {infoTab==="metricas"&&isSocio&&<CMetricas cl={cl}/>}
  </div>);
}

/* ── MÉTRICAS EDITÁVEIS (sócios) ──────────── */
function CMetricas({cl}){
  let live=getLiveClient(cl.id);
  let[meta,setMeta]=useState({spend:live.meta&&live.meta.spend||0,budget:live.meta&&live.meta.budget||0,roas:live.meta&&live.meta.roas||0,leads:live.meta&&live.meta.leads||0,cpc:live.meta&&live.meta.cpc||0,ctr:live.meta&&live.meta.ctr||0});
  let[google,setGoogle]=useState({spend:live.google&&live.google.spend||0,budget:live.google&&live.google.budget||0,roas:live.google&&live.google.roas||0,leads:live.google&&live.google.leads||0,cpc:live.google&&live.google.cpc||0,ctr:live.google&&live.google.ctr||0});
  let[social,setSocial]=useState({followers:live.social&&live.social.followers||0,growth:live.social&&live.social.growth||0,reach:live.social&&live.social.reach||0,eng:live.social&&live.social.eng||0,posts:live.social&&live.social.posts||0});
  let[contract,setContract]=useState(live.contract||0);
  let[health,setHealth]=useState(live.health||0);
  let[nps,setNps]=useState(live.nps||0);
  let[saved,setSaved]=useState(false);
  let ninp={background:C.s1,border:"1px solid "+C.b1,borderRadius:8,padding:"7px 10px",color:C.tx,fontSize:13,outline:"none",width:"100%",boxSizing:"border-box",fontFamily:"inherit"};
  let lbl={color:C.ts,fontSize:11,fontWeight:600,marginBottom:3,display:"block"};
  function save(){
    saveLiveClient(cl.id,{
      meta:{spend:+meta.spend,budget:+meta.budget,roas:+meta.roas,leads:+meta.leads,cpc:+meta.cpc,ctr:+meta.ctr},
      google:{spend:+google.spend,budget:+google.budget,roas:+google.roas,leads:+google.leads,cpc:+google.cpc,ctr:+google.ctr},
      social:{followers:+social.followers,growth:+social.growth,reach:+social.reach,eng:+social.eng,posts:+social.posts},
      contract:+contract,health:+health,nps:+nps,
    });
    setSaved(true);setTimeout(()=>setSaved(false),2000);
  }
  function F(label,val,set,k){return(<div><span style={lbl}>{label}</span><input type="number" inputMode="decimal" value={val} style={ninp} onChange={e=>set(p=>({...p,[k]:e.target.value}))}/></div>);}
  return(<div style={{display:"flex",flexDirection:"column",gap:20}}>
    <div style={{background:"#fef3c7",border:"1px solid #fbbf24",borderRadius:10,padding:"10px 14px",fontSize:12,color:"#92400e"}}>
      ✏ Edição salva em <b>pixels-live-{cl.id}</b> — dados reais substituem os hardcoded em toda a plataforma. Somente sócios.
    </div>
    <div>
      <div style={{color:C.tx,fontWeight:700,fontSize:13,marginBottom:12}}>📋 Contrato {"&"} Indicadores</div>
      <div style={{display:"grid",gridTemplateColumns:_pxMob()?"1fr":"1fr 1fr 1fr",gap:10}}>
        <div><span style={lbl}>Mensalidade (R$)</span><input type="number" inputMode="decimal" value={contract} style={ninp} onChange={e=>setContract(e.target.value)}/></div>
        <div><span style={lbl}>Saúde (0-100)</span><input type="number" inputMode="decimal" value={health} style={ninp} onChange={e=>setHealth(e.target.value)}/></div>
        <div><span style={lbl}>NPS (0-100)</span><input type="number" inputMode="decimal" value={nps} style={ninp} onChange={e=>setNps(e.target.value)}/></div>
      </div>
    </div>
    <div>
      <div style={{color:"#1877f2",fontWeight:700,fontSize:13,marginBottom:12}}>📘 Meta Ads</div>
      <div style={{display:"grid",gridTemplateColumns:_pxMob()?"1fr":"repeat(3,1fr)",gap:10}}>
        {F("Investimento (R$)",meta.spend,setMeta,"spend")}{F("Budget (R$)",meta.budget,setMeta,"budget")}{F("ROAS",meta.roas,setMeta,"roas")}
        {F("Leads",meta.leads,setMeta,"leads")}{F("CPC (R$)",meta.cpc,setMeta,"cpc")}{F("CTR (%)",meta.ctr,setMeta,"ctr")}
      </div>
    </div>
    <div>
      <div style={{color:"#34a853",fontWeight:700,fontSize:13,marginBottom:12}}>🔍 Google Ads</div>
      <div style={{display:"grid",gridTemplateColumns:_pxMob()?"1fr":"repeat(3,1fr)",gap:10}}>
        {F("Investimento (R$)",google.spend,setGoogle,"spend")}{F("Budget (R$)",google.budget,setGoogle,"budget")}{F("ROAS",google.roas,setGoogle,"roas")}
        {F("Leads",google.leads,setGoogle,"leads")}{F("CPC (R$)",google.cpc,setGoogle,"cpc")}{F("CTR (%)",google.ctr,setGoogle,"ctr")}
      </div>
    </div>
    <div>
      <div style={{color:"#c13584",fontWeight:700,fontSize:13,marginBottom:12}}>📱 Social Media</div>
      <div style={{display:"grid",gridTemplateColumns:_pxMob()?"1fr":"repeat(3,1fr)",gap:10}}>
        {F("Seguidores",social.followers,setSocial,"followers")}{F("Crescimento (%)",social.growth,setSocial,"growth")}{F("Alcance",social.reach,setSocial,"reach")}
        {F("Engajamento (%)",social.eng,setSocial,"eng")}{F("Posts/mês",social.posts,setSocial,"posts")}
      </div>
    </div>
    <button onClick={save} style={{background:saved?"#1D9E75":C.a,color:"#fff",border:"none",borderRadius:10,padding:"12px 24px",fontWeight:700,fontSize:13,cursor:"pointer",transition:"background .2s",alignSelf:"flex-start"}}>
      {saved?"✓ Salvo!":"💾 Salvar métricas"}
    </button>
  </div>);
}

/* ── BRIEFING ─────────────────────────────── */
function CBriefing({cl}){
  let DEFAULT_FIELDS=[
    {id:"empresa",      title:"Sobre a Empresa",          placeholder:"Descreva a empresa, história, missão, visão e valores..."},
    {id:"produto",      title:"Produto / Serviço",         placeholder:"O que vende? Diferenciais, preços, principais linhas..."},
    {id:"publico",      title:"Público-alvo",              placeholder:"Idade, gênero, localização, dores, desejos, comportamentos..."},
    {id:"concorrentes", title:"Principais Concorrentes",   placeholder:"Quem são? Pontos fortes e fracos de cada um..."},
    {id:"objetivos",    title:"Objetivos de Marketing",    placeholder:"O que quer alcançar? Leads, vendas, reconhecimento..."},
    {id:"tom",          title:"Tom de Voz / Identidade",   placeholder:"Como a marca fala? Formal, descontraído, técnico..."},
    {id:"canais",       title:"Canais Prioritários",       placeholder:"Meta, Google, Instagram, TikTok, etc. Por quê?"},
    {id:"obs",          title:"Observações Gerais",        placeholder:"Qualquer outra informação importante sobre esse cliente..."},
  ];

  let STORAGE_KEY="pixels-briefing-"+cl.id;

  // ── Carrega estado salvo (Supabase + localStorage fallback) ──
  let loadSaved=function(){
    try{let s=localStorage.getItem(STORAGE_KEY);if(s)return JSON.parse(s);}catch(e){}
    return {};
  };
  let saved0=loadSaved();

  // ── Carrega do Supabase ao montar ──
  useEffect(()=>{
    if(!window._sb)return;
    window._sb.from("clients").select("briefing").eq("client_id",cl.id).single()
      .then(({data})=>{
        if(data?.briefing){
          try{
            const bf=JSON.parse(data.briefing);
            if(bf.rawText!==undefined)setRawText(bf.rawText);
            if(bf.answers)setAnswers(bf.answers);
            if(bf.fields&&bf.fields.length)setFields(bf.fields);
          }catch(e){}
        }
      }).catch(()=>{});
  },[cl.id]);

  let[tab,setTab]=useState("documento"); // "documento" | "campos"
  let[rawText,setRawText]=useState(saved0.rawText||"");
  let[answers,setAnswers]=useState(saved0.answers||{});
  let[fields,setFields]=useState(saved0.fields&&saved0.fields.length?saved0.fields:DEFAULT_FIELDS);
  let[savedOk,setSavedOk]=useState(false);
  let[dragOver,setDragOver]=useState(false);
  let[loading,setLoading]=useState(false);
  let[loadingMsg,setLoadingMsg]=useState("");
  let[aiError,setAiError]=useState("");
  let[editingField,setEditingField]=useState(null);
  let[editTitle,setEditTitle]=useState("");
  let[editPlaceholder,setEditPlaceholder]=useState("");
  let[addingField,setAddingField]=useState(false);
  let[newTitle,setNewTitle]=useState("");
  let[newPlaceholder,setNewPlaceholder]=useState("");
  let fileRef=useRef(null);

  // ── Salvar tudo junto — localStorage + Supabase ──
  let persist=function(rt,ans,flds){
    let toSave={rawText:rt!==undefined?rt:rawText, answers:ans||answers, fields:flds||fields};
    try{localStorage.setItem(STORAGE_KEY,JSON.stringify(toSave));setSavedOk(true);setTimeout(()=>setSavedOk(false),2500);}catch(e){}
    if(window._sb){
      window._sb.from("clients").update({
        briefing:JSON.stringify(toSave),
        updated_by:CURRENT_USER.name,
      }).eq("client_id",cl.id).then(()=>{}).catch(err=>console.error("briefing save:",err));
    }
  };

  let saveRaw=function(){persist(rawText,answers,fields);};

  let saveAnswers=function(a){setAnswers(a);persist(rawText,a,fields);};
  let saveFields=function(f){setFields(f);persist(rawText,answers,f);};

  // ── Ler arquivo ─────────────────────────────────
  let handleFile=function(file){
    if(!file)return;
    let isTXT=file.type.startsWith("text/")||file.name.endsWith(".txt")||file.name.endsWith(".md");
    let isDOCX=file.name.endsWith(".docx");
    let isPDF=file.type==="application/pdf";
    if(isTXT){
      let r=new FileReader();
      r.onload=function(e){setRawText(e.target.result);};
      r.readAsText(file,"UTF-8");
    } else if(isPDF||isDOCX){
      // PDF/DOCX: não lemos o conteúdo binário diretamente, avisamos
      setAiError("Para PDF ou Word, abra o arquivo, selecione tudo (Ctrl+A), copie (Ctrl+C) e cole aqui.");
    } else {
      setAiError("Formato não suportado. Use .txt, .md, ou cole o texto diretamente.");
    }
  };
  let handleDrop=function(e){e.preventDefault();setDragOver(false);handleFile(e.dataTransfer.files[0]);};

  // ── IA: preencher campos a partir do texto ──────
  let fillWithAI=async function(){
    if(!rawText.trim()){setAiError("Cole o briefing antes de usar a IA.");return;}
    setLoading(true);setAiError("");setLoadingMsg("Analisando com IA…");
    let fieldsList=fields.map(function(f){return '"'+f.id+'": "" // '+f.title;}).join("\n");
    let prompt='Você recebeu o briefing de um cliente de agência de marketing chamado "'+cl.name+'".\nExtraia e organize as informações nos campos abaixo. Para cada campo, escreva apenas o conteúdo relevante em português. Se não houver informação para um campo, deixe "".\n\nResponda SOMENTE com um objeto JSON válido, sem nenhum texto antes ou depois:\n{\n'+fieldsList+'\n}';
    try{
      let res=await fetch("/api/anthropic/v1/messages",{
        method:"POST",headers:{"Content-Type":"application/json"},
        body:JSON.stringify({model:PX_IA_MODELO,max_tokens:2000,
          messages:[{role:"user",content:[{type:"text",text:rawText},{type:"text",text:prompt}]}]})
      });
      if(!res.ok){let t=await res.text();setAiError("Erro HTTP "+res.status+": "+t.slice(0,100));setLoading(false);setLoadingMsg("");return;}
      let json=await res.json();
      if(json.error){setAiError("Erro da API: "+json.error.message);setLoading(false);setLoadingMsg("");return;}
      let raw=(json.content||[]).map(function(b){return b.type==="text"?b.text:"";}).join("").trim();
      let match=raw.match(/\{[\s\S]*\}/);
      if(!match){setAiError("Resposta inesperada da IA. Tente novamente.");setLoading(false);setLoadingMsg("");return;}
      let parsed=JSON.parse(match[0]);
      let merged={...answers};
      Object.keys(parsed).forEach(function(k){if(parsed[k]&&parsed[k].trim())merged[k]=parsed[k];});
      saveAnswers(merged);
      setTab("campos");
      let filled=Object.keys(merged).filter(function(k){return merged[k];}).length;
      setLoadingMsg("✓ "+filled+" campo(s) preenchido(s)!");
      setTimeout(function(){setLoadingMsg("");},3000);
    }catch(err){
      setAiError("Erro de conexão: "+err.message+". Verifique sua rede.");
    }
    setLoading(false);
  };

  // ── Campos: gerenciar ────────────────────────────
  let startEditField=function(f){setEditingField(f.id);setEditTitle(f.title);setEditPlaceholder(f.placeholder||"");};
  let confirmEditField=function(){
    if(!editTitle.trim()){setEditingField(null);return;}
    saveFields(fields.map(function(f){return f.id===editingField?{...f,title:editTitle.trim(),placeholder:editPlaceholder.trim()}:f;}));
    setEditingField(null);
  };
  let deleteField=async function(id){
    if(!await pixelsConfirm("Remover este campo?",{okText:"Remover",danger:true}))return;
    let updated=fields.filter(function(f){return f.id!==id;});
    let a2={...answers};delete a2[id];setAnswers(a2);saveFields(updated);
  };
  let addField=function(){
    if(!newTitle.trim())return;
    saveFields([...fields,{id:"custom_"+Date.now(),title:newTitle.trim(),placeholder:newPlaceholder.trim()||"Digite aqui..."}]);
    setNewTitle("");setNewPlaceholder("");setAddingField(false);
  };

  let pctFilled=fields.length>0?Math.round((fields.filter(function(f){return answers[f.id]&&answers[f.id].trim();}).length/fields.length)*100):0;
  let hasRaw=rawText.trim().length>0;
  let ninp={background:C.s1,border:"1px solid "+C.b1,borderRadius:8,padding:"7px 10px",color:C.tx,fontSize:12,outline:"none",width:"100%",boxSizing:"border-box",fontFamily:"inherit"};
  let tinp={width:"100%",border:"none",background:"transparent",color:C.tx,fontSize:13,resize:"vertical",outline:"none",fontFamily:"'DM Sans',system-ui,sans-serif",lineHeight:1.8,padding:"14px 16px",boxSizing:"border-box"};

  return(<div style={{display:"flex",flexDirection:"column",gap:14}}>

    {/* ── Header ── */}
    <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",flexWrap:"wrap",gap:8}}>
      <div style={{display:"flex",alignItems:"center",gap:10}}>
        <div style={{color:C.tx,fontWeight:700,fontSize:14}}>Briefing</div>
        {hasRaw&&<span style={{background:C.gr+"18",color:C.gr,borderRadius:99,padding:"2px 9px",fontSize:10,fontWeight:700}}>✓ Documento salvo</span>}
        {pctFilled>0&&<span style={{background:C.a+"18",color:C.a,borderRadius:99,padding:"2px 9px",fontSize:10,fontWeight:700}}>{pctFilled}% campos</span>}
        {savedOk&&<span style={{color:C.gr,fontSize:11,fontWeight:700}}>✓ Salvo!</span>}
      </div>
    </div>

    {/* ── Tabs ── */}
    <div style={{display:"flex",gap:3,background:C.s1,borderRadius:10,padding:3}}>
      {[["documento","📄 Documento"],["campos","⚙ Campos estruturados"]].map(([id,lbl])=>(
        <button key={id} onClick={()=>setTab(id)}
          style={{flex:1,background:tab===id?C.card:"transparent",border:"none",borderRadius:8,padding:"8px 0",fontSize:12,fontWeight:tab===id?700:400,color:tab===id?C.a:C.ts,cursor:"pointer",transition:"all .15s"}}>
          {lbl}
        </button>
      ))}
    </div>

    {/* ══ ABA DOCUMENTO ══ */}
    {tab==="documento"&&(<div style={{display:"flex",flexDirection:"column",gap:12}}>

      {/* Info box */}
      <div style={{background:C.a+"0a",border:"1px solid "+C.a+"22",borderRadius:10,padding:"10px 14px",fontSize:11,color:C.ts,lineHeight:1.6}}>
        Cole o briefing do cliente aqui, suba um arquivo <b>.txt</b>, ou arraste direto na área abaixo.
        Depois clique <b>💾 Salvar</b> — o conteúdo fica disponível no CardModal das demandas e na Pixels IA.
      </div>

      {/* Drop zone + textarea */}
      <div
        onDragOver={e=>{e.preventDefault();setDragOver(true);}}
        onDragLeave={()=>setDragOver(false)}
        onDrop={handleDrop}
        style={{border:"2px solid "+(dragOver?C.a:C.b1),borderRadius:14,overflow:"hidden",background:dragOver?C.a+"06":C.card,transition:"all .2s",minHeight:300,display:"flex",flexDirection:"column"}}>
        <textarea
          value={rawText}
          onChange={e=>setRawText(e.target.value)}
          placeholder={"Cole o briefing do "+cl.name+" aqui...\n\nPode incluir:\n• Descrição da empresa\n• Produtos e serviços\n• Público-alvo\n• Objetivos de marketing\n• Tom de voz\n• Qualquer informação relevante"}
          style={{...tinp,flex:1,minHeight:280}}
        />
        {/* Rodapé drop zone */}
        <div
          onClick={()=>fileRef.current&&fileRef.current.click()}
          style={{padding:"10px 16px",borderTop:"1px solid "+C.b1,display:"flex",alignItems:"center",gap:8,cursor:"pointer",background:C.s1+"88"}}
          onMouseEnter={e=>e.currentTarget.style.background=C.a+"0a"}
          onMouseLeave={e=>e.currentTarget.style.background=C.s1+"88"}>
          <span style={{fontSize:14}}>📎</span>
          <span style={{color:C.ts,fontSize:11}}>Clique para subir um arquivo .txt — ou arraste aqui</span>
          <input ref={fileRef} type="file" accept=".txt,.md,text/*" style={{display:"none"}} onChange={e=>handleFile(e.target.files[0])}/>
        </div>
      </div>

      {/* Erro */}
      {aiError&&<div style={{background:C.rd+"12",border:"1px solid "+C.rd+"33",borderRadius:9,padding:"10px 14px",color:C.rd,fontSize:12,lineHeight:1.5}}>⚠ {aiError}</div>}

      {/* Feedback IA */}
      {loadingMsg&&loadingMsg.startsWith("✓")&&<div style={{background:C.gr+"12",border:"1px solid "+C.gr+"33",borderRadius:9,padding:"10px 14px",color:C.gr,fontSize:12,fontWeight:700}}>{loadingMsg}</div>}
      {loading&&<div style={{background:C.a+"10",border:"1px solid "+C.a+"33",borderRadius:9,padding:"10px 14px",color:C.a,fontSize:12,textAlign:"center",fontWeight:600}}>⏳ {loadingMsg||"Processando…"}</div>}

      {/* Ações */}
      <div style={{display:"flex",gap:8,justifyContent:"space-between",flexWrap:"wrap"}}>
        {/* Opcional: preencher campos com IA */}
        <button onClick={fillWithAI} disabled={!hasRaw||loading}
          title="Usa a IA para preencher os Campos Estruturados a partir deste texto"
          style={{display:"flex",alignItems:"center",gap:6,background:hasRaw&&!loading?C.a+"14":"transparent",color:hasRaw&&!loading?C.a:C.td,border:"1px solid "+(hasRaw&&!loading?C.a+"44":C.b1),borderRadius:9,padding:"8px 16px",fontSize:11,fontWeight:600,cursor:hasRaw&&!loading?"pointer":"not-allowed",transition:"all .15s"}}>
          ✦ Organizar em campos com IA <span style={{fontSize:9,opacity:.7}}>(opcional)</span>
        </button>
        <button onClick={saveRaw} disabled={!hasRaw}
          style={{background:hasRaw?"linear-gradient(135deg,"+C.a+","+C.aD+")":C.b1,color:hasRaw?"#fff":C.td,border:"none",borderRadius:9,padding:"8px 22px",fontWeight:700,fontSize:12,cursor:hasRaw?"pointer":"not-allowed",boxShadow:hasRaw?"0 3px 12px "+C.a+"40":"none"}}>
          💾 Salvar briefing
        </button>
      </div>

      {/* Preview do que está salvo */}
      {hasRaw&&rawText.trim()&&(
        <div style={{background:C.s1,borderRadius:10,padding:"12px 14px",fontSize:11,color:C.ts,lineHeight:1.6,maxHeight:80,overflow:"hidden",position:"relative"}}>
          <div style={{fontWeight:700,color:C.tx,marginBottom:4,fontSize:10,textTransform:"uppercase",letterSpacing:.5}}>📄 Conteúdo salvo</div>
          {rawText.slice(0,200)}{rawText.length>200?"…":""}
        </div>
      )}
    </div>)}

    {/* ══ ABA CAMPOS ══ */}
    {tab==="campos"&&(<div style={{display:"flex",flexDirection:"column",gap:12}}>
      <div style={{background:C.s1,borderRadius:10,padding:"9px 14px",fontSize:11,color:C.ts,lineHeight:1.5}}>
        Campos estruturados — preenchidos manualmente ou via IA a partir do documento.
        {hasRaw&&<span style={{color:C.a,fontWeight:600,cursor:"pointer",marginLeft:6}} onClick={()=>{setTab("documento");}}>← Voltar ao documento</span>}
      </div>

      {fields.map(function(sec){
        let isEditing=editingField===sec.id;
        return(<div key={sec.id} style={{background:C.card,borderRadius:14,overflow:"hidden",border:"1px solid "+(isEditing?C.a:C.b1),transition:"border .15s"}}>
          <div style={{padding:"9px 14px",borderBottom:"1px solid "+C.b1,display:"flex",alignItems:"center",gap:8}}>
            {isEditing?(
              <div style={{display:"flex",flex:1,gap:6,alignItems:"center"}}>
                <input value={editTitle} onChange={e=>setEditTitle(e.target.value)} style={{...ninp,flex:1,fontSize:12,fontWeight:700}} placeholder="Título"/>
                <input value={editPlaceholder} onChange={e=>setEditPlaceholder(e.target.value)} style={{...ninp,flex:2,fontSize:11}} placeholder="Dica"/>
                <button onClick={confirmEditField} style={{background:C.a,color:"#fff",border:"none",borderRadius:7,padding:"5px 12px",fontSize:11,fontWeight:700,cursor:"pointer"}}>✓</button>
                <button onClick={()=>setEditingField(null)} style={{background:C.s1,border:"1px solid "+C.b1,borderRadius:7,padding:"5px 10px",fontSize:11,cursor:"pointer"}}>✕</button>
              </div>
            ):(
              <>
                <span style={{color:C.tx,fontWeight:700,fontSize:12,flex:1}}>{sec.title}</span>
                {answers[sec.id]&&<span style={{color:C.gr,fontSize:10,fontWeight:700}}>✓</span>}
                <button onClick={()=>startEditField(sec)} style={{background:"none",border:"none",color:C.ts,cursor:"pointer",fontSize:13,padding:"2px 6px"}}>✏</button>
                <button onClick={()=>deleteField(sec.id)} style={{background:"none",border:"none",color:C.ts,cursor:"pointer",fontSize:13,padding:"2px 6px"}}>🗑</button>
              </>
            )}
          </div>
          <textarea value={answers[sec.id]||""} onChange={e=>{let d={...answers};d[sec.id]=e.target.value;saveAnswers(d);}}
            placeholder={sec.placeholder||"Digite aqui..."} rows={3}
            style={{...tinp,minHeight:60,padding:"10px 14px"}}/>
        </div>);
      })}

      {addingField?(
        <div style={{background:C.card,borderRadius:14,padding:"14px",border:"2px dashed "+C.a,display:"flex",flexDirection:"column",gap:8}}>
          <div style={{color:C.a,fontWeight:700,fontSize:12}}>Novo campo</div>
          <input value={newTitle} onChange={e=>setNewTitle(e.target.value)} placeholder="Título do campo" style={ninp} autoFocus/>
          <input value={newPlaceholder} onChange={e=>setNewPlaceholder(e.target.value)} placeholder="Dica de preenchimento (opcional)" style={ninp}/>
          <div style={{display:"flex",gap:6}}>
            <button onClick={addField} style={{background:C.a,color:"#fff",border:"none",borderRadius:9,padding:"7px 16px",fontSize:12,fontWeight:700,cursor:"pointer"}}>+ Adicionar</button>
            <button onClick={()=>{setAddingField(false);setNewTitle("");setNewPlaceholder("");}} style={{background:C.s1,border:"1px solid "+C.b1,borderRadius:9,padding:"7px 14px",fontSize:12,cursor:"pointer",color:C.ts}}>Cancelar</button>
          </div>
        </div>
      ):(
        <div style={{display:"flex",gap:8}}>
          <button onClick={()=>setAddingField(true)} style={{background:C.a+"14",color:C.a,border:"1px dashed "+C.a+"66",borderRadius:10,padding:"9px 16px",fontSize:12,fontWeight:700,cursor:"pointer",flex:1}}>
            + Adicionar campo
          </button>
          <button onClick={async()=>{if(await pixelsConfirm("Restaurar campos padrão?",{okText:"Restaurar"}))saveFields(DEFAULT_FIELDS);}} style={{background:C.s1,border:"1px solid "+C.b1,borderRadius:10,padding:"9px 12px",fontSize:11,color:C.ts,cursor:"pointer"}}>↺</button>
        </div>
      )}
    </div>)}

  </div>);
}

/* ── CONTATOS (Info) ──────────────────────── */
function CContatos({cl}){
  let[contacts,setContacts]=useState(function(){
    try{let s=localStorage.getItem("pixels-contacts-"+cl.id);if(s)return JSON.parse(s);}catch(e){}
    return cl.contacts||[];
  });
  let[adding,setAdding]=useState(false);
  let[form,setForm]=useState({name:"",role:"",phone:"",email:"",birthday:"",photo:"",notes:""});
  let[editing,setEditing]=useState(null);

  let save=function(list){
    setContacts(list);
    try{localStorage.setItem("pixels-contacts-"+cl.id,JSON.stringify(list));}catch(e){}
    if(window._sb)window._sb.from("clients").update({contatos:list,updated_by:CURRENT_USER.name}).eq("client_id",cl.id).then(()=>{}).catch(e=>console.warn("[cliente_ferramentas] db update falhou:",e?.message||e));
  };

  let addOrUpdate=function(){
    if(!form.name.trim())return;
    if(editing!==null){
      let updated=contacts.map(function(c,i){return i===editing?{...c,...form}:c;});
      save(updated);setEditing(null);
    } else {
      save([...contacts,{...form,id:Date.now()}]);
    }
    setForm({name:"",role:"",phone:"",email:"",birthday:"",photo:"",notes:""});
    setAdding(false);
  };

  let startEdit=function(i){
    setForm({...contacts[i]});setEditing(i);setAdding(true);
  };

  let inp={background:C.s1,border:"1px solid "+C.b1,borderRadius:9,padding:"8px 10px",color:C.tx,fontSize:12,outline:"none",width:"100%",boxSizing:"border-box",fontFamily:"inherit"};

  return(<div style={{display:"flex",flexDirection:"column",gap:12}}>
    <div style={{display:"flex",alignItems:"center",justifyContent:"space-between"}}>
      <div style={{color:C.tx,fontWeight:700,fontSize:14}}>Contatos do Cliente</div>
      <button onClick={()=>{setAdding(true);setEditing(null);setForm({name:"",role:"",phone:"",email:"",birthday:"",photo:"",notes:""}); }}
        style={{background:C.a+"18",color:C.a,border:"1px solid "+C.a+"33",borderRadius:9,padding:"6px 14px",fontSize:12,fontWeight:700,cursor:"pointer"}}>
        + Adicionar
      </button>
    </div>

    {adding&&(<div style={{background:C.card,borderRadius:14,padding:"16px",border:"1px solid "+C.b1,display:"flex",flexDirection:"column",gap:10}}>
      <div style={{color:C.tx,fontWeight:700,fontSize:13,marginBottom:4}}>{editing!==null?"Editar contato":"Novo contato"}</div>
      <div style={{display:"grid",gridTemplateColumns:_pxMob()?"1fr":"1fr 1fr",gap:8}}>
        {[{k:"name",p:"Nome *"},{k:"role",p:"Cargo"},{k:"phone",p:"WhatsApp"},{k:"email",p:"E-mail"},{k:"birthday",p:"Aniversário (DD/MM)"},{k:"photo",p:"URL da foto (opcional)"}].map(function(f){
          return(<div key={f.k}>
            <div style={{color:C.td,fontSize:10,marginBottom:3}}>{f.p}</div>
            <input value={form[f.k]||""} onChange={e=>{let n={...form};n[f.k]=e.target.value;setForm(n);}} style={inp}/>
          </div>);
        })}
        <div style={{gridColumn:"1/-1"}}>
          <div style={{color:C.td,fontSize:10,marginBottom:3}}>Observações / Notas</div>
          <textarea value={form.notes||""} onChange={e=>setForm(function(p){return{...p,notes:e.target.value};})} rows={2}
            style={{...inp,resize:"vertical"}}/>
        </div>
      </div>
      <div style={{display:"flex",gap:8,justifyContent:"flex-end"}}>
        <button onClick={()=>{setAdding(false);setEditing(null);}} style={{background:C.s1,border:"1px solid "+C.b1,borderRadius:9,padding:"7px 14px",color:C.ts,fontSize:12,cursor:"pointer"}}>Cancelar</button>
        <button onClick={addOrUpdate} style={{background:C.a,color:"#fff",border:"none",borderRadius:9,padding:"7px 16px",fontWeight:700,fontSize:12,cursor:"pointer"}}>Salvar</button>
      </div>
    </div>)}

    {contacts.length===0&&!adding&&(<div style={{background:C.card,borderRadius:14,padding:"32px",textAlign:"center",border:"1px solid "+C.b1}}>
      <div style={{fontSize:32,marginBottom:8}}>👥</div>
      <div style={{color:C.ts,fontSize:13}}>Nenhum contato cadastrado</div>
    </div>)}

    <div style={{display:"flex",flexDirection:"column",gap:8}}>
      {contacts.map(function(c,i){
        let today=new Date().toLocaleDateString("pt-BR",{day:"2-digit",month:"2-digit"});
        let isbirthday=c.birthday&&c.birthday.startsWith(today.slice(0,5));
        return(<div key={c.id||i} style={{background:C.card,borderRadius:14,padding:"14px 18px",border:"1px solid "+(isbirthday?C.yw:C.b1),display:"flex",alignItems:"center",gap:14}}>
          <div style={{width:48,height:48,borderRadius:"50%",overflow:"hidden",flexShrink:0,border:"2px solid "+cl.color+"44",background:cl.color+"18",display:"flex",alignItems:"center",justifyContent:"center"}}>
            {c.photo?<img src={c.photo} alt={c.name} style={{width:"100%",height:"100%",objectFit:"cover"}}/>
              :<span style={{color:cl.color,fontWeight:900,fontSize:18}}>{(c.name||"?")[0].toUpperCase()}</span>}
          </div>
          <div style={{flex:1,minWidth:0}}>
            <div style={{display:"flex",alignItems:"center",gap:6}}>
              <div style={{color:C.tx,fontWeight:700,fontSize:13}}>{c.name}</div>
              {isbirthday&&<span style={{fontSize:14}}>🎂</span>}
            </div>
            <div style={{color:C.td,fontSize:11,marginTop:1}}>{c.role||"—"}</div>
            {c.birthday&&<div style={{color:C.td,fontSize:10,marginTop:1}}>🎂 {c.birthday}</div>}
            {c.notes&&<div style={{color:C.ts,fontSize:11,marginTop:4,fontStyle:"italic"}}>{c.notes}</div>}
          </div>
          <div style={{display:"flex",flexDirection:"column",gap:5,alignItems:"flex-end"}}>
            {c.phone&&(<a href={"https://wa.me/55"+c.phone.replace(/\D/g,"")} target="_blank" rel="noopener"
              style={{background:"#25d366",color:"#fff",borderRadius:8,padding:"5px 10px",fontSize:10,fontWeight:700,textDecoration:"none"}}>
              WhatsApp
            </a>)}
            {c.email&&(<a href={"mailto:"+c.email}
              style={{background:C.s1,border:"1px solid "+C.b1,color:C.ts,borderRadius:8,padding:"5px 10px",fontSize:10,fontWeight:600,textDecoration:"none"}}>
              E-mail
            </a>)}
            <button onClick={()=>startEdit(i)} style={{background:"none",border:"none",color:C.td,cursor:"pointer",fontSize:11,padding:"2px"}}>✏ Editar</button>
          </div>
        </div>);
      })}
    </div>
  </div>);
}

/* ── TIMELINE (Info) ─────────────────────── */
/* ── TIMELINE (Info) — com contatos e tarefas internas ─ */
function CTimeline({cl}){
  let[notes,setNotes]=useState(function(){
    try{let s=localStorage.getItem("pixels-notes-"+cl.id);if(s)return JSON.parse(s);}catch(e){}
    return [];
  });

  // All contacts: team + client contacts from localStorage
  let clientContacts=useState(function(){
    try{let s=localStorage.getItem("pixels-contacts-"+cl.id);if(s)return JSON.parse(s);}catch(e){}
    return cl.contacts||[];
  })[0];

  let allContacts=[
    ...TEAM.map(function(u){return{id:"team_"+u.id,name:u.name,role:u.role,photo:"",color:u.color,av:u.av,source:"equipe"};}),
    ...clientContacts.map(function(c){return{id:c.id||("client_"+c.name),name:c.name,role:c.role||"Cliente",photo:c.photo||"",color:cl.color,av:(c.name||"?")[0],source:"cliente"};})
  ];

  let[form,setForm]=useState({
    date:new Date().toLocaleDateString("pt-BR"),
    type:"reuniao",
    contactIds:[],
    text:"",
    tasks:[],
  });
  let[newTask,setNewTask]=useState({title:"",deadline:"",priority:"media"});
  let[showForm,setShowForm]=useState(false);
  let[expandedNote,setExpandedNote]=useState(null);
  let[filterType,setFilterType]=useState("todos");
  let[filterContact,setFilterContact]=useState("");
  let[search,setSearch]=useState("");

  let typeConfig={
    reuniao:   {label:"Reunião",        color:"#3b82f6", icon:"📅"},
    contato:   {label:"Contato",        color:"#22c55e", icon:"💬"},
    feedback:  {label:"Feedback",       color:"#eab308", icon:"⭐"},
    demanda:   {label:"Demanda Interna",color:"#a140ff", icon:"🎯"},
    marco:     {label:"Marco",          color:"#ec4899", icon:"🏆"},
    alerta:    {label:"Alerta",         color:"#ef4444", icon:"🔥"},
    nota:      {label:"Nota",           color:"#64748b", icon:"📝"},
  };

  let addTask=function(){
    if(!newTask.title.trim())return;
    setForm(function(p){return{...p,tasks:[...p.tasks,{id:Date.now(),...newTask,done:false}]};});
    setNewTask({title:"",deadline:"",priority:"media"});
  };

  let removeFormTask=function(id){
    setForm(function(p){return{...p,tasks:p.tasks.filter(function(t){return t.id!==id;})};});
  };

  let toggleContact=function(id){
    setForm(function(p){
      let has=p.contactIds.includes(id);
      return{...p,contactIds:has?p.contactIds.filter(function(x){return x!==id;}):[...p.contactIds,id]};
    });
  };

  let saveNote=function(){
    if(!form.text.trim()&&form.tasks.length===0)return;
    let selectedContacts=allContacts.filter(function(c){return form.contactIds.includes(c.id);});
    let entry={
      id:Date.now(),
      date:form.date,
      type:form.type,
      contactIds:form.contactIds,
      contacts:selectedContacts.map(function(c){return{id:c.id,name:c.name,role:c.role,photo:c.photo,color:c.color,av:c.av};}),
      text:form.text.trim(),
      tasks:form.tasks,
    };
    let list=[entry,...notes];
    setNotes(list);
    try{localStorage.setItem("pixels-notes-"+cl.id,JSON.stringify(list));}catch(e){}
    if(window._sb)window._sb.from("clients").update({notas:list,updated_by:CURRENT_USER.name}).eq("client_id",cl.id).then(()=>{}).catch(e=>console.warn("[cliente_ferramentas] db update falhou:",e?.message||e));
    setForm({date:new Date().toLocaleDateString("pt-BR"),type:"reuniao",contactIds:[],text:"",tasks:[]});
    setNewTask({title:"",deadline:"",priority:"media"});
    setShowForm(false);

    // Dispatch event so calendar picks up new tasks
    try{window.dispatchEvent(new CustomEvent("pixels-notes-updated"));}catch(e){}
  };

  let toggleTask=function(noteId,taskId){
    let updated=notes.map(function(note){
      if(note.id!==noteId)return note;
      return{...note,tasks:(note.tasks||[]).map(function(t){return t.id===taskId?{...t,done:!t.done}:t;})};
    });
    setNotes(updated);
    try{localStorage.setItem("pixels-notes-"+cl.id,JSON.stringify(updated));}catch(e){}
    if(window._sb)window._sb.from("clients").update({notas:updated,updated_by:CURRENT_USER.name}).eq("client_id",cl.id).then(()=>{}).catch(e=>console.warn("[cliente_ferramentas] db update falhou:",e?.message||e));
    try{window.dispatchEvent(new CustomEvent("pixels-notes-updated"));}catch(e){}
  };

  let deleteNote=function(noteId){
    let updated=notes.filter(function(n){return n.id!==noteId;});
    setNotes(updated);
    try{localStorage.setItem("pixels-notes-"+cl.id,JSON.stringify(updated));}catch(e){}
    if(window._sb)window._sb.from("clients").update({notas:updated,updated_by:CURRENT_USER.name}).eq("client_id",cl.id).then(()=>{}).catch(e=>console.warn("[cliente_ferramentas] db update falhou:",e?.message||e));
  };

  // Filters
  let filtered=notes.filter(function(note){
    if(filterType!=="todos"&&note.type!==filterType)return false;
    if(filterContact&&!(note.contactIds||[]).includes(filterContact)&&!(note.contacts||[]).find(function(c){return c.id===filterContact;}))return false;
    if(search&&!note.text.toLowerCase().includes(search.toLowerCase())&&!(note.tasks||[]).some(function(t){return t.title.toLowerCase().includes(search.toLowerCase());}))return false;
    return true;
  });

  let totalPending=notes.reduce(function(sum,n){return sum+(n.tasks||[]).filter(function(t){return !t.done;}).length;},0);

  let inp={background:C.s1,border:"1px solid "+C.b1,borderRadius:9,padding:"8px 10px",color:C.tx,fontSize:12,outline:"none",width:"100%",boxSizing:"border-box",fontFamily:"inherit"};
  let prioColors={alta:C.rd,media:C.yw,baixa:C.gr};

  // Parse date string dd/mm/yyyy or yyyy-mm-dd
  let parseDate=function(ds){
    if(!ds)return null;
    if(ds.includes("-"))return new Date(ds);
    let p=ds.split("/");
    if(p.length===3)return new Date(p[2]+"-"+p[1]+"-"+p[0]);
    return null;
  };

  let daysLeft=function(ds){
    let d=parseDate(ds);
    if(!d)return null;
    return Math.ceil((d-new Date())/(1000*60*60*24));
  };

  // Format date for input[type=date] <-> display
  let toInputDate=function(ds){
    if(!ds)return "";
    if(ds.includes("-"))return ds;
    let p=ds.split("/");
    return p.length===3?p[2]+"-"+p[1]+"-"+p[0]:"";
  };

  let fromInputDate=function(val){
    if(!val)return "";
    let p=val.split("-");
    return p.length===3?p[2]+"/"+p[1]+"/"+p[0]:val;
  };

  return(<div style={{display:"flex",flexDirection:"column",gap:14}}>

    {/* Header */}
    <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",flexWrap:"wrap",gap:10}}>
      <div>
        <div style={{display:"flex",alignItems:"center",gap:8}}>
          <div style={{color:C.tx,fontWeight:700,fontSize:14}}>Linha do Tempo</div>
          {totalPending>0&&<span style={{background:C.a+"22",color:C.a,borderRadius:99,padding:"1px 8px",fontSize:10,fontWeight:700}}>{totalPending} tarefa(s) pendente(s)</span>}
        </div>
        <div style={{color:C.td,fontSize:11,marginTop:2}}>Histórico completo — reuniões, contatos e demandas internas</div>
      </div>
      <button onClick={()=>setShowForm(true)}
        style={{background:"linear-gradient(135deg,"+C.a+","+C.aD+")",color:"#fff",border:"none",borderRadius:10,padding:"8px 18px",fontWeight:700,fontSize:12,cursor:"pointer",boxShadow:"0 2px 12px "+C.a+"40",whiteSpace:"nowrap"}}>
        + Registrar
      </button>
    </div>

    {/* Filters */}
    <div style={{display:"flex",gap:6,flexWrap:"wrap",alignItems:"center"}}>
      {/* Type filter */}
      <div style={{display:"flex",gap:3,background:C.s1,borderRadius:10,padding:3,flexWrap:"wrap"}}>
        <button onClick={()=>setFilterType("todos")} style={{background:filterType==="todos"?C.a:"transparent",border:"none",borderRadius:7,padding:"5px 10px",color:filterType==="todos"?"#fff":C.ts,fontSize:11,cursor:"pointer",fontWeight:filterType==="todos"?700:400}}>Todos</button>
        {Object.entries(typeConfig).map(function(entry){
          let k=entry[0],v=entry[1];
          return(<button key={k} onClick={()=>setFilterType(k)}
            style={{background:filterType===k?v.color:"transparent",border:"none",borderRadius:7,padding:"5px 10px",color:filterType===k?"#fff":C.ts,fontSize:11,cursor:"pointer",fontWeight:filterType===k?700:400,whiteSpace:"nowrap"}}>
            {v.icon} {v.label}
          </button>);
        })}
      </div>

      {/* Contact filter */}
      <select value={filterContact} onChange={e=>setFilterContact(e.target.value)}
        style={{...inp,width:"auto",fontSize:11}}>
        <option value="">Todas as pessoas</option>
        <optgroup label="Equipe">
          {TEAM.map(function(u){return<option key={u.id} value={"team_"+u.id}>{u.name}</option>;})}
        </optgroup>
        <optgroup label="Contatos do cliente">
          {clientContacts.map(function(c){return<option key={c.id||c.name} value={c.id||("client_"+c.name)}>{c.name}</option>;})}
        </optgroup>
      </select>

      {/* Search */}
      <div style={{position:"relative",flex:1,minWidth:140}}>
        <span style={{position:"absolute",left:9,top:"50%",transform:"translateY(-50%)",color:C.td,fontSize:11,pointerEvents:"none"}}>🔍</span>
        <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar..."
          style={{...inp,paddingLeft:28}}/>
      </div>
    </div>

    {/* Add Form */}
    {showForm&&(<div style={{background:C.card,borderRadius:16,border:"2px solid "+C.a+"44",overflow:"hidden"}}>
      <div style={{padding:"14px 18px",borderBottom:"1px solid "+C.b1,background:C.a+"10"}}>
        <div style={{color:C.a,fontWeight:700,fontSize:13}}>Novo registro</div>
      </div>
      <div style={{padding:"16px 18px",display:"flex",flexDirection:"column",gap:12}}>

        {/* Type + Date */}
        <div style={{display:"grid",gridTemplateColumns:_pxMob()?"1fr":"2fr 1fr",gap:10}}>
          <div>
            <div style={{color:C.td,fontSize:10,marginBottom:4}}>Tipo de registro</div>
            <select value={form.type} onChange={e=>setForm(function(p){return{...p,type:e.target.value};})} style={inp}>
              {Object.entries(typeConfig).map(function(entry){
                return<option key={entry[0]} value={entry[0]}>{entry[1].icon} {entry[1].label}</option>;
              })}
            </select>
          </div>
          <div>
            <div style={{color:C.td,fontSize:10,marginBottom:4}}>Data</div>
            <input type="date" value={toInputDate(form.date)} onChange={e=>setForm(function(p){return{...p,date:fromInputDate(e.target.value)};})} style={inp}/>
          </div>
        </div>

        {/* Contacts */}
        <div>
          <div style={{color:C.td,fontSize:10,marginBottom:6}}>Com quem (selecione todos os envolvidos)</div>
          <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
            {/* Equipe */}
            <div style={{width:"100%",color:C.td,fontSize:9,fontWeight:700,textTransform:"uppercase",marginBottom:2}}>Equipe Pixels</div>
            {TEAM.map(function(u){
              let sel=form.contactIds.includes("team_"+u.id);
              return(<button key={u.id} onClick={()=>toggleContact("team_"+u.id)}
                style={{display:"flex",alignItems:"center",gap:6,background:sel?u.color+"22":"transparent",border:"1px solid "+(sel?u.color:C.b1),borderRadius:99,padding:"4px 10px",cursor:"pointer",transition:"all .12s"}}>
                <div style={{width:16,height:16,borderRadius:"50%",background:u.color,display:"flex",alignItems:"center",justifyContent:"center",color:"#fff",fontWeight:900,fontSize:8,flexShrink:0}}>{u.av}</div>
                <span style={{color:sel?u.color:C.ts,fontSize:11,fontWeight:sel?700:400}}>{u.name}</span>
              </button>);
            })}
            {/* Client contacts */}
            {clientContacts.length>0&&(<>
              <div style={{width:"100%",color:C.td,fontSize:9,fontWeight:700,textTransform:"uppercase",marginTop:4,marginBottom:2}}>Contatos do Cliente</div>
              {clientContacts.map(function(c){
                let cid=c.id||("client_"+c.name);
                let sel=form.contactIds.includes(cid);
                return(<button key={cid} onClick={()=>toggleContact(cid)}
                  style={{display:"flex",alignItems:"center",gap:6,background:sel?cl.color+"22":"transparent",border:"1px solid "+(sel?cl.color:C.b1),borderRadius:99,padding:"4px 10px",cursor:"pointer",transition:"all .12s"}}>
                  <div style={{width:16,height:16,borderRadius:"50%",overflow:"hidden",flexShrink:0,background:cl.color+"22",border:"1px solid "+cl.color+"44",display:"flex",alignItems:"center",justifyContent:"center"}}>
                    {c.photo?<img src={c.photo} alt="" style={{width:"100%",height:"100%",objectFit:"cover"}}/>
                      :<span style={{color:cl.color,fontWeight:900,fontSize:8}}>{(c.name||"?")[0]}</span>}
                  </div>
                  <span style={{color:sel?cl.color:C.ts,fontSize:11,fontWeight:sel?700:400}}>{c.name}</span>
                  {c.role&&<span style={{color:C.td,fontSize:9}}>· {c.role}</span>}
                </button>);
              })}
            </>)}
          </div>
        </div>

        {/* Text — proper textarea with line breaks */}
        <div>
          <div style={{color:C.td,fontSize:10,marginBottom:4}}>O que foi discutido / aconteceu</div>
          <textarea
            value={form.text}
            onChange={e=>setForm(function(p){return{...p,text:e.target.value};})}
            rows={5}
            placeholder={"Descreva o que foi conversado...\n\nUse Enter para separar parágrafos.\nEx:\n- Discutimos a campanha de inverno\n- Cliente aprovou a estratégia de reels\n- Próximo passo: criar 4 artes até 15/04"}
            style={{...inp,resize:"vertical",lineHeight:1.7,whiteSpace:"pre-wrap"}}
          />
          <div style={{color:C.td,fontSize:9,marginTop:3}}>Dica: use Enter para quebrar parágrafos. O texto será exibido formatado.</div>
        </div>

        {/* Internal tasks */}
        <div style={{background:C.s1,borderRadius:12,padding:"12px 14px"}}>
          <div style={{color:C.tx,fontWeight:700,fontSize:12,marginBottom:10}}>🎯 Tarefas / Demandas internas geradas nessa interação</div>
          {form.tasks.length>0&&(<div style={{display:"flex",flexDirection:"column",gap:5,marginBottom:10}}>
            {form.tasks.map(function(t){
              let dl=daysLeft(t.deadline);
              return(<div key={t.id} style={{display:"flex",alignItems:"center",gap:8,background:C.card,borderRadius:8,padding:"7px 10px"}}>
                <div style={{width:6,height:6,borderRadius:"50%",background:prioColors[t.priority]||C.a,flexShrink:0}}/>
                <span style={{flex:1,color:C.tx,fontSize:11}}>{t.title}</span>
                {t.deadline&&<span style={{color:C.td,fontSize:10}}>{t.deadline}</span>}
                <span style={{background:prioColors[t.priority]+"18",color:prioColors[t.priority],borderRadius:99,padding:"1px 6px",fontSize:9,fontWeight:700}}>{t.priority}</span>
                <button onClick={()=>removeFormTask(t.id)} style={{background:"none",border:"none",color:C.td,cursor:"pointer",fontSize:13,padding:"0 2px"}}>×</button>
              </div>);
            })}
          </div>)}
          <div style={{display:"grid",gridTemplateColumns:"1fr auto auto auto",gap:6,alignItems:"end"}}>
            <div>
              <div style={{color:C.td,fontSize:9,marginBottom:3}}>Título da tarefa</div>
              <input value={newTask.title} onChange={e=>setNewTask(function(p){return{...p,title:e.target.value};})}
                onKeyDown={e=>{if(e.key==="Enter"){e.preventDefault();addTask();}}}
                placeholder="Ex: Fazer capa aniversário Facebook" style={inp}/>
            </div>
            <div>
              <div style={{color:C.td,fontSize:9,marginBottom:3}}>Prazo</div>
              <input type="date" value={toInputDate(newTask.deadline)} onChange={e=>setNewTask(function(p){return{...p,deadline:fromInputDate(e.target.value)};})} style={{...inp,width:130}}/>
            </div>
            <div>
              <div style={{color:C.td,fontSize:9,marginBottom:3}}>Prioridade</div>
              <select value={newTask.priority} onChange={e=>setNewTask(function(p){return{...p,priority:e.target.value};})} style={{...inp,width:90}}>
                <option value="alta">Alta</option>
                <option value="media">Média</option>
                <option value="baixa">Baixa</option>
              </select>
            </div>
            <button onClick={addTask} style={{background:C.a,color:"#fff",border:"none",borderRadius:9,padding:"8px 14px",fontWeight:700,fontSize:12,cursor:"pointer",whiteSpace:"nowrap",alignSelf:"end"}}>+ Add</button>
          </div>
        </div>

        <div style={{display:"flex",gap:10,justifyContent:"flex-end"}}>
          <button onClick={()=>setShowForm(false)} style={{background:C.s1,border:"1px solid "+C.b1,borderRadius:10,padding:"9px 18px",color:C.ts,fontSize:12,cursor:"pointer"}}>Cancelar</button>
          <button onClick={saveNote} disabled={!form.text.trim()&&form.tasks.length===0}
            style={{background:"linear-gradient(135deg,"+C.a+","+C.aD+")",color:"#fff",border:"none",borderRadius:10,padding:"9px 24px",fontWeight:700,fontSize:12,cursor:"pointer",boxShadow:"0 2px 12px "+C.a+"40"}}>
            Salvar
          </button>
        </div>
      </div>
    </div>)}

    {/* Timeline entries */}
    {filtered.length===0&&(<div style={{textAlign:"center",padding:"40px",color:C.td,fontSize:13,background:C.card,borderRadius:14,border:"1px solid "+C.b1}}>
      {notes.length===0?"Linha do tempo vazia. Registre o primeiro evento acima.":"Nenhum registro encontrado com esses filtros."}
    </div>)}

    <div style={{position:"relative",paddingLeft:36}}>
      <div style={{position:"absolute",left:15,top:0,bottom:0,width:2,background:C.b1,borderRadius:99}}/>
      {filtered.map(function(note,i){
        let cfg=typeConfig[note.type]||typeConfig.nota;
        let pendingTasks=(note.tasks||[]).filter(function(t){return !t.done;}).length;
        let expanded=expandedNote===note.id;
        let noteContacts=note.contacts||[];

        return(<div key={note.id} style={{position:"relative",marginBottom:14}}>
          {/* Timeline dot */}
          <div style={{position:"absolute",left:-28,top:14,width:22,height:22,borderRadius:"50%",background:cfg.color+"22",border:"2px solid "+cfg.color,display:"flex",alignItems:"center",justifyContent:"center",fontSize:10,zIndex:1}}>
            {cfg.icon}
          </div>

          <div style={{background:C.card,borderRadius:14,border:"1px solid "+C.b1,overflow:"hidden"}}>
            {/* Header row */}
            <div onClick={()=>setExpandedNote(expanded?null:note.id)}
              style={{display:"flex",alignItems:"flex-start",gap:10,padding:"12px 16px",cursor:"pointer",transition:"background .1s"}}
              onMouseEnter={e=>e.currentTarget.style.background=C.s1}
              onMouseLeave={e=>e.currentTarget.style.background="transparent"}>

              {/* Contact avatars */}
              {noteContacts.length>0&&(<div style={{display:"flex",marginRight:2,flexShrink:0}}>
                {noteContacts.slice(0,3).map(function(c,ci){
                  return(<div key={ci} title={c.name} style={{width:28,height:28,borderRadius:"50%",overflow:"hidden",border:"2px solid "+C.card,marginLeft:ci>0?-8:0,flexShrink:0,background:c.color+"22",display:"flex",alignItems:"center",justifyContent:"center",zIndex:3-ci}}>
                    {c.photo?<img src={c.photo} alt={c.name} style={{width:"100%",height:"100%",objectFit:"cover"}}/>
                      :<span style={{color:c.color||C.a,fontWeight:900,fontSize:10}}>{c.av||(c.name||"?")[0]}</span>}
                  </div>);
                })}
                {noteContacts.length>3&&<div style={{width:28,height:28,borderRadius:"50%",border:"2px solid "+C.card,marginLeft:-8,background:C.s1,display:"flex",alignItems:"center",justifyContent:"center",color:C.td,fontSize:9,fontWeight:700}}>+{noteContacts.length-3}</div>}
              </div>)}

              <div style={{flex:1,minWidth:0}}>
                {/* Tags row */}
                <div style={{display:"flex",alignItems:"center",gap:5,marginBottom:4,flexWrap:"wrap"}}>
                  <span style={{background:cfg.color+"18",color:cfg.color,borderRadius:99,padding:"2px 8px",fontSize:9,fontWeight:700,flexShrink:0}}>{cfg.label}</span>
                  {noteContacts.map(function(c,ci){
                    return(<span key={ci} style={{color:C.td,fontSize:10}}>{ci>0?"·":""} {c.name}</span>);
                  })}
                  {pendingTasks>0&&<span style={{background:C.a+"22",color:C.a,borderRadius:99,padding:"1px 6px",fontSize:9,fontWeight:700,flexShrink:0}}>🎯 {pendingTasks} pendente(s)</span>}
                </div>

                {/* Text preview — FORMATTED */}
                {note.text&&(<div style={{color:C.tx,fontSize:12,lineHeight:1.7,whiteSpace:"pre-wrap",overflow:"hidden",maxHeight:expanded?"none":"4.2em",display:"-webkit-box",WebkitLineClamp:expanded?undefined:3,WebkitBoxOrient:expanded?"unset":"vertical"}}>
                  {note.text}
                </div>)}
                {!expanded&&note.text&&note.text.split("\n").length>3&&<span style={{color:C.a,fontSize:11,cursor:"pointer",fontWeight:600}}>Ver mais</span>}
              </div>

              <div style={{display:"flex",gap:6,alignItems:"center",flexShrink:0}}>
                <span style={{color:C.td,fontSize:10,whiteSpace:"nowrap"}}>{note.date}</span>
                <button onClick={async function(e){e.stopPropagation();if(await pixelsConfirm("Excluir este registro?",{okText:"Excluir",danger:true}))deleteNote(note.id);}}
                  style={{background:"none",border:"none",color:C.td,cursor:"pointer",fontSize:12,padding:"2px 4px",lineHeight:1}}
                  onMouseEnter={e=>e.currentTarget.style.color=C.rd}
                  onMouseLeave={e=>e.currentTarget.style.color=C.td}>🗑</button>
                <span style={{color:C.td,fontSize:13,transition:"transform .2s",display:"inline-block",transform:expanded?"rotate(90deg)":"rotate(0deg)",lineHeight:1}}>›</span>
              </div>
            </div>

            {/* Expanded: tasks */}
            {expanded&&(note.tasks||[]).length>0&&(<div style={{borderTop:"1px solid "+C.b1+"66",padding:"12px 16px"}}>
              <div style={{color:C.td,fontSize:10,fontWeight:700,textTransform:"uppercase",marginBottom:8}}>Tarefas / Demandas internas</div>
              <div style={{display:"flex",flexDirection:"column",gap:5}}>
                {(note.tasks||[]).map(function(t){
                  let dl=daysLeft(t.deadline);
                  let late=dl!==null&&dl<0;
                  let urgent=dl!==null&&dl<=2&&dl>=0;
                  return(<button key={t.id} onClick={()=>toggleTask(note.id,t.id)}
                    style={{display:"flex",alignItems:"center",gap:8,background:t.done?C.gr+"08":late?C.rd+"08":C.s1,border:"1px solid "+(t.done?C.gr+"44":late?C.rd+"44":C.b1),borderRadius:9,padding:"8px 12px",cursor:"pointer",textAlign:"left",transition:"all .12s"}}>
                    <div style={{width:16,height:16,borderRadius:4,border:"2px solid "+(t.done?C.gr:prioColors[t.priority]||C.a),background:t.done?C.gr:"transparent",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
                      {t.done&&<span style={{color:"#fff",fontSize:9,lineHeight:1}}>✓</span>}
                    </div>
                    <span style={{flex:1,color:t.done?C.td:C.tx,fontSize:11,textDecoration:t.done?"line-through":"none"}}>{t.title}</span>
                    {t.deadline&&<span style={{color:t.done?C.gr:late?C.rd:urgent?C.yw:C.td,fontSize:10,fontWeight:late||urgent?700:400,whiteSpace:"nowrap"}}>{t.deadline}</span>}
                    <span style={{background:prioColors[t.priority]+"18",color:prioColors[t.priority],borderRadius:99,padding:"1px 6px",fontSize:9,fontWeight:700,flexShrink:0}}>{t.priority}</span>
                  </button>);
                })}
              </div>
            </div>)}
          </div>
        </div>);
      })}
    </div>
  </div>);
}

/* ─── COrientacoes — orientações para a equipe (logos, paleta, fontes, voz) ─── */
/* ─── _PlaybookSection: wrapper das seções do COrientacoes.
   CRÍTICO: top-level do módulo, NÃO redefinir dentro de componentes
   (causou bug "uma letra por vez" no input). */
function _PlaybookSection({title, subtitle, icon, accent, idx, children}){
  // Sub-secao do playbook — cabeçalho em COR SÓLIDA seguindo o rainbow da Linha de
  // produção (mesmas cores das colunas do kanban, sem as cinzas — igual aos Scripts
  // do onboarding). A cor vem da POSIÇÃO (`idx`) entre as seções visíveis, então
  // esconder seção por cadeira rebalanceia sozinho. Texto sempre branco.
  // `accent` virou legado (ignorado).
  const _RAINBOW = (typeof KANBAN_COLS!=="undefined" && Array.isArray(KANBAN_COLS) && KANBAN_COLS.length)
    ? KANBAN_COLS.filter(function(c){ return c && c.color && ["rascunhos","pausado","reprovado"].indexOf(c.id)<0; }).map(function(c){ return c.color; })
    : ["#dc2626","#ea580c","#f97316","#f59e0b","#ca8a04","#84cc16","#16a34a","#059669","#9333ea"];
  const _i   = typeof idx==="number" ? idx : 0;
  const _cor = _RAINBOW[((_i%_RAINBOW.length)+_RAINBOW.length)%_RAINBOW.length];
  // Sub-seção LEVE (09/09/2026): dentro de um bloco que já tem barra sólida, outra barra
  // sólida pesava. Aqui a cor fica só no ícone e num fio fino embaixo do cabeçalho.
  return <div style={{background:"#fff",borderRadius:14,border:"1px solid #e9edf3",padding:0,overflow:"hidden",marginBottom:14,fontFamily:"'Inter',system-ui,sans-serif",boxShadow:"0 1px 2px rgba(15,23,42,0.025)"}}>
    <div style={{display:"flex",alignItems:"center",gap:10,padding:"11px 16px 11px 14px",background:"#fbfcfd",borderBottom:"1px solid #eef1f5"}}>
      {icon && <div style={{width:30,height:30,borderRadius:9,background:_cor+"14",color:_cor,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
        {typeof Ico!=="undefined" && <Ico n={icon} size={15} color={_cor}/>}
      </div>}
      <div style={{flex:1,minWidth:0}}>
        <div style={{color:"#0f172a",fontWeight:800,fontSize:13.5,letterSpacing:-.2,lineHeight:1.25}}>{title}</div>
        {subtitle&&<div style={{color:"#94a3b8",fontSize:11.5,marginTop:2,fontWeight:500,lineHeight:1.4}}>{subtitle}</div>}
      </div>
    </div>
    <div style={{padding:"15px 20px 17px"}}>{children}</div>
  </div>;
}

/* ═══ Projeto — início, fim e os meses do plano (10/09/2026) ═══════════════
   Pedido do Vinicius: no Orientações (que os sócios também abrem) ter a data de
   início e fim do projeto, com mês 1 / mês 2 / mês 3, no espírito da linha do
   tempo do portal do cliente.
   O mês é o PERÍODO EXATO a partir da data de início (começou 19/08 → mês 1 vai
   até 18/09), igual ao contador de conteúdos do Calendário de publicações.
   Mostra também quantos conteúdos já têm data marcada em cada mês. */
const _PBPROJ_RITMO = {
  starter: {1:"2 posts por semana · setup e go-live", 2:"1 post por semana · campanhas ativas", 3:"1 post por semana · consolidação"},
};
function _pbProjSomaMes(startISO, n){
  // Sem "clamp" de propósito: quando o mês é curto (começou dia 31 e o mês seguinte
  // tem 30), a data transborda pro dia 1 do mês seguinte — que é exatamente onde
  // _pxProjMes() vira o mês. As duas contas precisam bater dia a dia.
  const s=String(startISO).slice(0,10).split("-").map(Number);
  return new Date(s[0], s[1]-1+n, s[2]);
}
function _pbProjFmt(d){ return d?String(d.getDate()).padStart(2,"0")+"/"+String(d.getMonth()+1).padStart(2,"0")+"/"+d.getFullYear():""; }
function _PBProjeto({cl, idx}){
  const [fase,setFase]=useState(null);
  const [datas,setDatas]=useState(null);
  useEffect(function(){
    let vivo=true;
    const sb=window._sb;
    if(!sb||!cl||!cl.id){ setFase(false); return; }
    Promise.all([
      sb.from("client_onboarding").select("items").eq("client_id",cl.id).maybeSingle(),
      sb.from("client_meta").select("production_schedule").eq("client_id",cl.id).maybeSingle(),
      // Mesma regra do calendário: fora lixeira, pausado, reprovado e folder
      sb.from("tasks").select("publish_date,status,content_type").eq("client",cl.id).is("deleted_at",null).not("publish_date","is",null),
    ]).then(function(rs){
      if(!vivo) return;
      let f=null;
      const it=(rs[0]&&rs[0].data&&rs[0].data.items)||null;
      if(it&&it.__start_date__) f={preset:it.__preset__||"completo",start:String(it.__start_date__).slice(0,10)};
      const ps=(rs[1]&&rs[1].data&&rs[1].data.production_schedule)||null;
      if(ps&&ps.start&&ps.package) f={preset:ps.package,start:String(ps.start).slice(0,10)};
      setFase(f||false);
      setDatas(((rs[2]&&rs[2].data)||[])
        .filter(function(r){ return r.status!=="pausado"&&r.status!=="reprovado"&&r.content_type!=="folder"&&!r.nao_publica; })
        .map(function(r){ return String(r.publish_date).slice(0,10); }));
    }).catch(function(){ if(vivo) setFase(false); });
    return function(){ vivo=false; };
  },[cl&&cl.id]);

  if(fase===null||!fase||!fase.start) return null;   // sem projeto registrado: não mostra nada

  const preset=String(fase.preset||"").toLowerCase();
  const starter=preset==="starter";
  const nMeses=starter?3:1;
  const ini0=_pbProjSomaMes(fase.start,0);
  const fimProj=new Date(_pbProjSomaMes(fase.start,nMeses)); fimProj.setDate(fimProj.getDate()-1);
  const hojeISO=(function(){ const d=new Date(); return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0"); })();
  const mesHoje=(typeof _pxProjMes==="function")?_pxProjMes(fase.start,hojeISO):0;
  const diaHoje=Math.round((new Date(hojeISO+"T00:00:00")-new Date(fase.start+"T00:00:00"))/864e5)+1;
  const totalDias=Math.round((fimProj-ini0)/864e5)+1;

  // Contagem SEQUENCIAL por cota, igual ao chip do calendário: os 8 primeiros
  // conteúdos são o mês 1, os 4 seguintes o mês 2, e assim por diante — não é
  // pela data em que caíram. As datas ao lado são o período contratado.
  const totalConteudos=(datas||[]).filter(function(d){
    return (typeof _pxProjMes==="function") && _pxProjMes(fase.start,d)>=1;
  }).length;
  const linhas=[];
  let usados=0;
  for(let n=1;n<=nMeses;n++){
    const ini=_pbProjSomaMes(fase.start,n-1);
    const fim=new Date(_pbProjSomaMes(fase.start,n)); fim.setDate(fim.getDate()-1);
    const cota=(typeof _pxCotaMes==="function")?_pxCotaMes(preset,n):0;
    const feitos=cota>0?Math.max(0,Math.min(cota,totalConteudos-usados)):0;
    usados+=cota>0?cota:0;
    linhas.push({n:n,ini:ini,fim:fim,cota:cota,feitos:feitos,agora:mesHoje===n,passado:mesHoje>n});
  }

  return <_PlaybookSection idx={idx} icon="calendar" title="Projeto" subtitle={starter?"Plano Starter · 3 meses — início, fim e ritmo de cada mês":"Início e período do projeto"}>
    <div style={{display:"flex",alignItems:"center",gap:10,flexWrap:"wrap",marginBottom:12,paddingBottom:12,borderBottom:"1px solid #f1f5f9"}}>
      <span style={{background:"#7c3aed14",color:"#7c3aed",fontSize:10,fontWeight:800,letterSpacing:.6,textTransform:"uppercase",padding:"4px 10px",borderRadius:99}}>{starter?"Plano Starter":(preset||"Projeto")}</span>
      <span style={{color:"#0f172a",fontSize:13,fontWeight:700,fontFeatureSettings:"'tnum'"}}>{_pbProjFmt(ini0)} → {_pbProjFmt(fimProj)}</span>
      {diaHoje>=1&&diaHoje<=totalDias
        ? <span style={{marginLeft:"auto",display:"inline-flex",alignItems:"center",gap:6,background:"#0f172a",color:"#fff",fontSize:10.5,fontWeight:800,padding:"4px 11px",borderRadius:99,fontFeatureSettings:"'tnum'"}}>
            <span style={{width:6,height:6,borderRadius:"50%",background:"#4ade80",boxShadow:"0 0 0 3px rgba(74,222,128,.25)"}}/>
            Dia {diaHoje} de {totalDias}
          </span>
        : <span style={{marginLeft:"auto",color:"#94a3b8",fontSize:11,fontWeight:700}}>{diaHoje>totalDias?"Projeto encerrado":"Ainda não começou"}</span>}
    </div>
    <div style={{display:"flex",flexDirection:"column",gap:8}}>
      {linhas.map(function(l){
        const cor=l.agora?"#7c3aed":(l.passado?"#16a34a":"#94a3b8");
        const okCota=l.cota&&l.feitos>=l.cota;
        return <div key={l.n} style={{display:"flex",alignItems:"center",gap:11,flexWrap:"wrap",border:"1px solid "+(l.agora?"#ddd6fe":"#eef0f4"),background:l.agora?"#faf8ff":"#fff",borderRadius:12,padding:"10px 13px"}}>
          <span style={{background:l.agora?"#7c3aed":(l.passado?"#16a34a":"#eef0f4"),color:(l.agora||l.passado)?"#fff":"#64748b",fontSize:10,fontWeight:900,letterSpacing:.6,textTransform:"uppercase",padding:"4px 9px",borderRadius:99,flexShrink:0}}>Mês {l.n}</span>
          <span style={{color:"#0f172a",fontSize:12.5,fontWeight:700,fontFeatureSettings:"'tnum'",flexShrink:0}}>{_pbProjFmt(l.ini)} – {_pbProjFmt(l.fim)}</span>
          <span style={{color:"#94a3b8",fontSize:11.5,fontWeight:500,minWidth:0,flex:1}}>{(_PBPROJ_RITMO[preset]||{})[l.n]||""}</span>
          {l.cota>0&&<span title={l.feitos+" de "+l.cota+" conteúdos deste bloco já marcados — a contagem é sequencial (os "+l.cota+" seguintes da fila), não pela data"}
            style={{background:okCota?"#16a34a14":"#f1f5f9",color:okCota?"#16a34a":"#475569",fontSize:11.5,fontWeight:800,padding:"4px 10px",borderRadius:99,fontFeatureSettings:"'tnum'",flexShrink:0}}>{l.feitos}/{l.cota}</span>}
          {l.agora&&<span style={{background:"#0f172a",color:"#fff",fontSize:9.5,fontWeight:900,letterSpacing:.5,textTransform:"uppercase",padding:"4px 9px",borderRadius:99,flexShrink:0}}>Estamos aqui</span>}
        </div>;
      })}
    </div>
    <div style={{color:"#cbd5e1",fontSize:10.5,marginTop:9,lineHeight:1.5}}>As datas são o período contratado (mês exato a partir do início). Já o contador é sequencial: os 8 primeiros conteúdos são o mês 1, os 4 seguintes o mês 2 — igual ao número que aparece no card do Calendário de publicações.</div>
  </_PlaybookSection>;
}

function COrientacoes({cl, sections}){
  // sections: opcional. Array com IDs das secoes a mostrar. Se nao passar, mostra todas.
  // IDs: 'logos', 'paleta', 'fontes', 'tom', 'hashtags', 'cta', 'naofazer', 'siteredes'
  // "projeto" aparece sempre (é info do contrato, serve pra todo mundo que abre o cartão)
  const _showSec = function(id){ return id==="projeto" || !sections || sections.indexOf(id)!==-1; };
  // Posição da seção entre as VISÍVEIS → cor do rainbow no cabeçalho (_PlaybookSection idx)
  const _SEC_ORDER = ["projeto","logos","paleta","fontes","tom","hashtags","cta","naofazer","siteredes"];
  const _secVis = _SEC_ORDER.filter(_showSec);
  const _secIdx = function(id){ return Math.max(0,_secVis.indexOf(id)); };
  const sb=window._sb;
  const [data,setData]=useState({logos:[],paleta:[],fontes:[],tomDeVoz:"",hashtags:[],ctaPadrao:"",naoFazer:"",site:"",redes:{instagram:"",facebook:"",youtube:"",linkedin:"",tiktok:""},driveUrl:"",byUnit:{}});
  // ── Unidade Bioter ativa pra Site e redes oficiais (per-unit) ──
  // So aparece se cl.id === "bioter". Default: primeira unidade.
  const _isBioterCli = cl && cl.id === "bioter";
  const _bioterUnits = (_isBioterCli && typeof BIOTER_UNITS !== "undefined") ? BIOTER_UNITS : [];
  const [_unitTab, _setUnitTab] = useState(_bioterUnits[0] ? _bioterUnits[0].id : "");
  const [savedOk,setSavedOk]=useState(false);
  const [uploading,setUploading]=useState(null);
  const fileInputLogo=useRef(null);
  const fileInputFonte=useRef(null);
  const [pendingLogo,setPendingLogo]=useState(null); // {nome, modo:"upload"|"link"}
  const [pendingFonte,setPendingFonte]=useState(null);
  // Adicionar fonte pelo nome (sem upload/link) — padrao das Cores acima
  const [newFonteInline,setNewFonteInline]=useState({nome:"",uso:""});
  const addFonteInline=()=>{
    const _n=(newFonteInline.nome||"").trim();
    if(!_n)return;
    persist({...data,fontes:[...(data.fontes||[]),{nome:_n,uso:(newFonteInline.uso||"").trim(),url:"",formato:"NOME",externo:false}]});
    setNewFonteInline({nome:"",uso:""});
  };
  const [newColor,setNewColor]=useState({nome:"",hex:"#a140ff"});
  const [newHashtag,setNewHashtag]=useState("");

  useEffect(()=>{
    if(!sb)return;
    // Reset ANTES do fetch — evita paleta/logos do cliente anterior vazarem
    // (bug: user trocava de Arabutã pra Climaves e via cores da Arabutã)
    const _empty={logos:[],paleta:[],fontes:[],tomDeVoz:"",hashtags:[],ctaPadrao:"",naoFazer:"",site:"",redes:{instagram:"",facebook:"",youtube:"",linkedin:"",tiktok:""},driveUrl:"",byUnit:{}};
    setData(_empty);
    sb.from("clients").select("orientacoes").eq("client_id",cl.id).single()
      .then(({data:row})=>{
        if(row?.orientacoes){
          const o=typeof row.orientacoes==="string"?JSON.parse(row.orientacoes):row.orientacoes;
          // Merge sobre o RESET (nao sobre estado anterior) — dados do cliente antigo somem
          setData({..._empty,...o,redes:{..._empty.redes,...(o.redes||{})}});
        }
        // Se row?.orientacoes for null, data ja foi resetado acima → vazio correto
      })
      .catch(e=>console.warn("[orientacoes] load:",e?.message||e));
  },[cl.id]);

  const persist=(next)=>{
    setData(next);
    if(!sb)return;
    sb.from("clients").update({orientacoes:next,updated_by:CURRENT_USER.name}).eq("client_id",cl.id)
      .then(({error})=>{
        if(error){console.warn("[orientacoes] save:",error.message);return;}
        setSavedOk(true);setTimeout(()=>setSavedOk(false),2000);
      })
      .catch(e=>console.warn("[orientacoes] save:",e?.message||e));
  };

  const uploadFile=async(file,kind)=>{
    if(!file||!sb)return null;
    setUploading(kind);
    try{
      const ext=(file.name.split(".").pop()||"bin").replace(/[^a-zA-Z0-9]/g,"").toLowerCase();
      const rnd=Math.random().toString(36).slice(2,11);
      const path=`orientacoes/${cl.id}/${kind}/${Date.now()}-${rnd}.${ext}`;
      const {error}=await sb.storage.from("agency-files").upload(path,file,{cacheControl:"3600",upsert:false});
      if(error)throw error;
      const {data:pub}=sb.storage.from("agency-files").getPublicUrl(path);
      setUploading(null);
      return{url:pub.publicUrl,formato:ext.toUpperCase(),path};
    }catch(e){
      setUploading(null);
      pixelsToast.error("Erro no upload: "+(e?.message||"desconhecido"));
      return null;
    }
  };

  const onSelectLogoFile=async(e)=>{
    const file=e.target.files?.[0];
    e.target.value="";
    if(!file)return;
    // Pede o nome DEPOIS de o arquivo ser escolhido — agora o picker já abriu sem fricção.
    let nome=(pendingLogo&&pendingLogo.nome)||"";
    if(!nome){
      try{
        nome=await pixelsPrompt("Nome do logo (ex: Principal, Branca, Ícone):");
      }catch(_){nome=null;}
      if(!nome)nome=file.name.replace(/\.[^.]+$/,"");
    }
    const up=await uploadFile(file,"logo");
    if(!up)return;
    const novo={nome:nome.trim(),url:up.url,formato:up.formato,path:up.path};
    persist({...data,logos:[...(data.logos||[]),novo]});
    setPendingLogo(null);
  };

  const onSelectFonteFile=async(e)=>{
    const file=e.target.files?.[0];
    e.target.value="";
    if(!file)return;
    let nome=(pendingFonte&&pendingFonte.nome)||"";
    let uso=(pendingFonte&&pendingFonte.uso)||"";
    if(!nome){
      try{
        nome=await pixelsPrompt("Nome da fonte (ex: Poppins SemiBold):");
      }catch(_){nome=null;}
      if(!nome)nome=file.name.replace(/\.[^.]+$/,"");
      try{
        uso=await pixelsPrompt("Uso (ex: Títulos, Corpo) — opcional:")||"";
      }catch(_){uso="";}
    }
    const up=await uploadFile(file,"fonte");
    if(!up)return;
    const novo={nome:nome.trim(),uso:(uso||"").trim(),url:up.url,formato:up.formato,path:up.path};
    persist({...data,fontes:[...(data.fontes||[]),novo]});
    setPendingFonte(null);
  };

  const addLogoLink=async()=>{
    const url=await pixelsPrompt("Cole a URL do logo (Drive, Dropbox, etc):");
    if(!url||!url.trim())return;
    const nome=await pixelsPrompt("Nome do logo (ex: Principal colorido, Branca, Ícone):");
    if(!nome)return;
    persist({...data,logos:[...(data.logos||[]),{nome:nome.trim(),url:url.trim(),formato:"LINK",externo:true}]});
  };

  const addFonteLink=async()=>{
    const url=await pixelsPrompt("Cole a URL da fonte (Drive, Dropbox, Google Fonts...):");
    if(!url||!url.trim())return;
    const nome=await pixelsPrompt("Nome da fonte (ex: Poppins SemiBold):");
    if(!nome)return;
    const uso=await pixelsPrompt("Uso (ex: Títulos, Corpo, Destaques) — opcional:");
    persist({...data,fontes:[...(data.fontes||[]),{nome:nome.trim(),uso:(uso||"").trim(),url:url.trim(),formato:"LINK",externo:true}]});
  };

  const removeItem=async(arr,idx,key)=>{
    if(!await pixelsConfirm("Remover esse item?",{okText:"Remover",danger:true}))return;
    const item=data[arr][idx];
    // Se foi upload nosso, deleta do storage
    if(item?.path&&!item.externo){try{sb.storage.from("agency-files").remove([item.path]).catch(()=>{});}catch(e){}}
    persist({...data,[arr]:data[arr].filter((_,i)=>i!==idx)});
  };

  const addColor=()=>{
    if(!newColor.nome.trim())return;
    // Normaliza hex: garante # inicial. Se invalido, usa preto.
    let _hex = String(newColor.hex||"").trim();
    if(_hex && !_hex.startsWith("#")) _hex = "#" + _hex;
    if(!/^#([0-9a-fA-F]{3}|[0-9a-fA-F]{6}|[0-9a-fA-F]{8})$/.test(_hex)) _hex = "#000000";
    persist({...data,paleta:[...(data.paleta||[]),{nome:newColor.nome.trim(),hex:_hex.toLowerCase()}]});
    setNewColor({nome:"",hex:"#a140ff"});
  };
  const removeColor=(idx)=>persist({...data,paleta:data.paleta.filter((_,i)=>i!==idx)});

  const addHashtag=()=>{
    let t=newHashtag.trim().replace(/^#+/,"");
    if(!t)return;
    if(!t.startsWith("#"))t="#"+t;
    if((data.hashtags||[]).includes(t))return;
    persist({...data,hashtags:[...(data.hashtags||[]),t]});
    setNewHashtag("");
  };
  const removeHashtag=(t)=>persist({...data,hashtags:(data.hashtags||[]).filter(x=>x!==t)});

  const inp={background:"#fafbfc",border:"1px solid #e2e8f0",borderRadius:9,padding:"10px 13px",color:"#0f172a",fontSize:13,outline:"none",width:"100%",boxSizing:"border-box",fontFamily:"'Inter',system-ui,sans-serif",transition:"border-color .12s, background .12s"};

  return(<div style={{display:"flex",flexDirection:"column",gap:0}}>
    <input ref={fileInputLogo} type="file" accept="image/*,.svg,.pdf" style={{display:"none"}} onChange={onSelectLogoFile}/>
    <input ref={fileInputFonte} type="file" accept=".ttf,.otf,.woff,.woff2,.zip" style={{display:"none"}} onChange={onSelectFonteFile}/>

    {savedOk&&<div style={{background:"#dcfce7",border:"0.5px solid #86efac",color:"#166534",padding:"6px 12px",borderRadius:8,fontSize:11,marginBottom:12,textAlign:"center"}}>Salvo automaticamente</div>}

    <_PBProjeto cl={cl} idx={_secIdx("projeto")}/>

    {_showSec("logos") && <_PlaybookSection idx={_secIdx("logos")} icon="image" accent="#7c3aed" title="Logos" subtitle="Variações da logo do cliente — designer baixa direto do app">
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(160px,1fr))",gap:8,marginBottom:10}}>
        {(data.logos||[]).map((l,i)=>(
          <div key={i} style={{background:C.s1,border:"0.5px solid "+C.b1,borderRadius:10,overflow:"hidden",position:"relative"}}>
            <div style={{aspectRatio:"1.4",background:"#fff",display:"flex",alignItems:"center",justifyContent:"center",padding:8}}>
              <img src={l.url} alt={l.nome} style={{maxWidth:"100%",maxHeight:"100%",objectFit:"contain"}} onError={e=>{e.currentTarget.style.display="none";}}/>
            </div>
            <div style={{padding:"8px 10px"}}>
              <div style={{color:C.tx,fontSize:11,fontWeight:500,marginBottom:4,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{l.nome}</div>
              <div style={{display:"flex",gap:4,alignItems:"center",justifyContent:"space-between"}}>
                <a href={l.url} target="_blank" rel="noopener noreferrer" download={l.externo?undefined:l.nome} style={{color:"#a140ff",fontSize:10,textDecoration:"none",fontWeight:500}}>{l.externo?"Abrir ↗":"Baixar ↓"}</a>
                <button type="button" onClick={()=>removeItem("logos",i)} style={{background:"transparent",border:"none",color:C.td,cursor:"pointer",fontSize:14,padding:0}}>×</button>
              </div>
            </div>
          </div>
        ))}
      </div>
      <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
        <button type="button" onClick={()=>{setPendingLogo({nome:""});fileInputLogo.current?.click();}} disabled={uploading==="logo"} style={{background:"linear-gradient(135deg,#a855f7,#7c3aed)",color:"#fff",border:"none",borderRadius:10,padding:"10px 18px",fontSize:12.5,fontWeight:700,cursor:"pointer",fontFamily:"'Inter',system-ui,sans-serif",boxShadow:"0 4px 12px rgba(124,58,237,.25)",transition:"transform .12s, box-shadow .12s",letterSpacing:-.1}}>{uploading==="logo"?"Enviando...":"+ Upload de logo"}</button>
        <button type="button" onClick={addLogoLink} style={{background:"#fff",color:"#475569",border:"1px solid #e2e8f0",borderRadius:10,padding:"10px 18px",fontSize:12.5,fontWeight:600,cursor:"pointer",fontFamily:"'Inter',system-ui,sans-serif",transition:"border-color .12s"}}>+ Adicionar via link</button>
      </div>
    </_PlaybookSection>}

    {_showSec("paleta") && <_PlaybookSection idx={_secIdx("paleta")} icon="sparkles" accent="#ec4899" title="Paleta de cores" subtitle="Cores da marca — equipe copia o hex direto da aba Orientações no cartão">
      {(data.paleta||[]).length>0&&<div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(140px,1fr))",gap:8,marginBottom:10}}>
        {data.paleta.map((c,i)=>(
          <div key={i} style={{background:c.hex,borderRadius:10,padding:10,border:"0.5px solid "+C.b1,minHeight:64,display:"flex",flexDirection:"column",justifyContent:"space-between",position:"relative"}}>
            <button type="button" onClick={()=>removeColor(i)} style={{position:"absolute",top:4,right:6,background:"rgba(255,255,255,0.7)",border:"none",borderRadius:4,color:"#000",cursor:"pointer",fontSize:11,padding:"0 6px",fontWeight:500}}>×</button>
            <div style={{color:"#fff",fontSize:11,fontWeight:500,textShadow:"0 1px 2px rgba(0,0,0,0.4)"}}>{c.nome}</div>
            <div style={{color:"#fff",fontSize:11,fontFamily:"monospace",textShadow:"0 1px 2px rgba(0,0,0,0.4)"}}>{c.hex.toUpperCase()}</div>
          </div>
        ))}
      </div>}
      <div style={{display:"flex",gap:6,alignItems:"center",flexWrap:"wrap"}}>
        <input type="text" value={newColor.nome} onChange={e=>setNewColor(p=>({...p,nome:e.target.value}))} placeholder="Nome da cor" style={{...inp,width:160}}/>
        <input type="color" value={newColor.hex} onChange={e=>setNewColor(p=>({...p,hex:e.target.value}))} style={{width:48,height:36,border:"0.5px solid "+C.b1,borderRadius:8,cursor:"pointer",padding:2,background:C.s1}}/>
        <input type="text" value={newColor.hex} onChange={e=>{
          let _v = e.target.value.trim();
          // Se user digitou sem #, adiciona automatico pra sincronizar com o picker
          if(_v && !_v.startsWith("#")) _v = "#" + _v;
          setNewColor(p=>({...p,hex:_v}));
        }} onBlur={e=>{
          // Ao sair do input, garante formato valido; senao mantém o antigo
          let _v = String(e.target.value||"").trim();
          if(_v && !_v.startsWith("#")) _v = "#" + _v;
          if(_v && !/^#([0-9a-fA-F]{3}|[0-9a-fA-F]{6})$/.test(_v)){
            setNewColor(p=>({...p,hex:"#a140ff"}));
          }
        }} style={{...inp,width:110,fontFamily:"monospace",textTransform:"lowercase"}} placeholder="#000000"/>
        <button type="button" onClick={addColor} style={{background:"linear-gradient(135deg,#a855f7,#7c3aed)",color:"#fff",border:"none",borderRadius:10,padding:"10px 18px",fontSize:12.5,fontWeight:700,cursor:"pointer",fontFamily:"'Inter',system-ui,sans-serif",boxShadow:"0 4px 12px rgba(124,58,237,.25)",transition:"transform .12s, box-shadow .12s",letterSpacing:-.1}}>+ Adicionar</button>
      </div>
    </_PlaybookSection>}

    {_showSec("fontes") && <_PlaybookSection idx={_secIdx("fontes")} icon="file-text" accent="#0ea5e9" title="Fontes" subtitle="Tipografias oficiais — equipe baixa o arquivo TTF/OTF/WOFF pra instalar">
      {(data.fontes||[]).length>0&&<div style={{display:"flex",flexDirection:"column",gap:6,marginBottom:10}}>
        {data.fontes.map((f,i)=>(
          <div key={i} style={{background:C.s1,border:"0.5px solid "+C.b1,borderRadius:10,padding:"10px 14px",display:"flex",alignItems:"center",gap:10}}>
            <div style={{width:36,height:36,borderRadius:8,background:"#a140ff15",color:"#a140ff",display:"flex",alignItems:"center",justifyContent:"center",fontSize:14,fontWeight:500,flexShrink:0}}>Aa</div>
            <div style={{flex:1,minWidth:0}}>
              <div style={{color:C.tx,fontSize:13,fontWeight:500}}>{f.nome}</div>
              <div style={{color:C.td,fontSize:10,marginTop:2}}>{f.uso?f.uso+" · ":""}{f.formato}{f.externo?" · link externo":""}</div>
            </div>
            {f.url && <a href={f.url} target="_blank" rel="noopener noreferrer" download={f.externo?undefined:f.nome} style={{color:"#a140ff",fontSize:11,textDecoration:"none",fontWeight:500,flexShrink:0}}>{f.externo?"Abrir ↗":"Baixar ↓"}</a>}
            <button type="button" onClick={()=>removeItem("fontes",i)} style={{background:"transparent",border:"none",color:C.td,cursor:"pointer",fontSize:16,padding:0}}>×</button>
          </div>
        ))}
      </div>}
      {/* Input inline pra registrar so o nome da fonte (sem obrigar upload/link) */}
      <div style={{display:"flex",gap:8,alignItems:"center",flexWrap:"wrap",marginBottom:10}}>
        <input value={newFonteInline.nome} onChange={e=>setNewFonteInline(p=>({...p,nome:e.target.value}))}
          onKeyDown={e=>{if(e.key==="Enter"){e.preventDefault();addFonteInline();}}}
          placeholder="Nome da fonte (ex: Poppins)" style={{...inp,flex:1,minWidth:160}}/>
        <input value={newFonteInline.uso} onChange={e=>setNewFonteInline(p=>({...p,uso:e.target.value}))}
          onKeyDown={e=>{if(e.key==="Enter"){e.preventDefault();addFonteInline();}}}
          placeholder="Uso (ex: Titulos, Corpo)" style={{...inp,flex:1,minWidth:140}}/>
        <button type="button" onClick={addFonteInline} disabled={!(newFonteInline.nome||"").trim()}
          style={{background:"linear-gradient(135deg,#a855f7,#7c3aed)",color:"#fff",border:"none",borderRadius:10,padding:"10px 18px",fontSize:12.5,fontWeight:700,cursor:(newFonteInline.nome||"").trim()?"pointer":"not-allowed",opacity:(newFonteInline.nome||"").trim()?1:.5,fontFamily:"'Inter',system-ui,sans-serif",boxShadow:"0 4px 12px rgba(124,58,237,.25)",letterSpacing:-.1}}>+ Adicionar</button>
      </div>
      {/* Botoes: upload de arquivo OU link externo */}
      <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
        <button type="button" onClick={()=>{setPendingFonte({nome:"",uso:""});fileInputFonte.current?.click();}} disabled={uploading==="fonte"} style={{background:"#fff",color:"#475569",border:"1px solid #e2e8f0",borderRadius:10,padding:"10px 18px",fontSize:12.5,fontWeight:600,cursor:"pointer",fontFamily:"'Inter',system-ui,sans-serif",transition:"border-color .12s"}}>{uploading==="fonte"?"Enviando...":"+ Upload de fonte"}</button>
        <button type="button" onClick={addFonteLink} style={{background:"#fff",color:"#475569",border:"1px solid #e2e8f0",borderRadius:10,padding:"10px 18px",fontSize:12.5,fontWeight:600,cursor:"pointer",fontFamily:"'Inter',system-ui,sans-serif",transition:"border-color .12s"}}>+ Adicionar via link</button>
      </div>
    </_PlaybookSection>}

    {_showSec("tom") && <_PlaybookSection idx={_secIdx("tom")} icon="message" accent="#16a34a" title="Tom de voz" subtitle="Como a marca fala — exemplos práticos ajudam">
      <textarea value={data.tomDeVoz||""} onChange={e=>setData(p=>({...p,tomDeVoz:e.target.value}))} onBlur={()=>persist(data)} placeholder='Ex: "Técnico mas acessível. Linguagem direta, evita gírias. Foca em resultado prático na fazenda. Usa produtor em vez de cliente."' rows={4} style={{...inp,minHeight:80,resize:"vertical",lineHeight:1.5}}/>
    </_PlaybookSection>}

    {_showSec("hashtags") && <_PlaybookSection idx={_secIdx("hashtags")} icon="tag" accent="#7c3aed" title="Hashtags padrão" subtitle="Tags que sempre entram nos posts desse cliente">
      {(data.hashtags||[]).length>0&&<div style={{display:"flex",gap:6,flexWrap:"wrap",marginBottom:10}}>
        {data.hashtags.map((t)=>(
          <span key={t} style={{background:"#a140ff15",color:"#a140ff",borderRadius:99,padding:"4px 10px",fontSize:11,fontWeight:500,display:"flex",alignItems:"center",gap:6}}>
            {t}
            <button type="button" onClick={()=>removeHashtag(t)} style={{background:"transparent",border:"none",color:"#a140ff",cursor:"pointer",fontSize:13,padding:0,lineHeight:1}}>×</button>
          </span>
        ))}
      </div>}
      <div style={{display:"flex",gap:6}}>
        <input value={newHashtag} onChange={e=>setNewHashtag(e.target.value)} onKeyDown={e=>{if(e.key==="Enter"){e.preventDefault();addHashtag();}}} placeholder="#bioter" style={{...inp,flex:1}}/>
        <button type="button" onClick={e=>{e.preventDefault();addHashtag();}} style={{background:"linear-gradient(135deg,#a855f7,#7c3aed)",color:"#fff",border:"none",borderRadius:10,padding:"10px 18px",fontSize:12.5,fontWeight:700,cursor:"pointer",fontFamily:"'Inter',system-ui,sans-serif",boxShadow:"0 4px 12px rgba(124,58,237,.25)",transition:"transform .12s, box-shadow .12s",letterSpacing:-.1}}>+ Adicionar</button>
      </div>
    </_PlaybookSection>}

    {_showSec("cta") && <_PlaybookSection idx={_secIdx("cta")} icon="send" accent="#f59e0b" title="CTA padrão" subtitle="Chamada pra ação que costuma fechar os posts">
      <input value={data.ctaPadrao||""} onChange={e=>setData(p=>({...p,ctaPadrao:e.target.value}))} onBlur={()=>persist(data)} placeholder='Ex: "Acesse o link na bio →"' style={inp}/>
    </_PlaybookSection>}

    {_showSec("naofazer") && <_PlaybookSection idx={_secIdx("naofazer")} icon="alert" accent="#dc2626" title="O que NÃO fazer" subtitle="Palavras proibidas, temas sensíveis, posturas a evitar">
      <textarea value={data.naoFazer||""} onChange={e=>setData(p=>({...p,naoFazer:e.target.value}))} onBlur={()=>persist(data)} placeholder='Ex: "Nunca usar a palavra barato. Não comparar diretamente com concorrentes. Evitar emojis em posts institucionais."' rows={3} style={{...inp,minHeight:60,resize:"vertical",lineHeight:1.5}}/>
    </_PlaybookSection>}

    {_showSec("siteredes") && <_PlaybookSection idx={_secIdx("siteredes")} icon="globe" accent="#0d9488" title="Site e redes oficiais" subtitle={_isBioterCli?"Cada unidade tem seu site, drive e perfis próprios — trocar aba pra editar":"Pra usar em arte, em links de bio, em posts"}>
      {/* Tabs por unidade (só Bioter) */}
      {_isBioterCli && _bioterUnits.length>0 && <div style={{display:"flex",gap:5,flexWrap:"wrap",marginBottom:14,paddingBottom:14,borderBottom:"1px solid #e2e8f0"}}>
        {_bioterUnits.map(function(u){
          const active = _unitTab===u.id;
          return <button key={u.id} type="button" onClick={function(){_setUnitTab(u.id);}}
            style={{background:active?u.color:"#fff",border:"1px solid "+(active?u.color:"#e2e8f0"),color:active?"#fff":"#475569",borderRadius:99,padding:"6px 14px",fontSize:12,fontWeight:active?800:600,cursor:"pointer",fontFamily:"'Inter',system-ui,sans-serif",letterSpacing:-.1,transition:"all .12s",boxShadow:active?"0 4px 12px "+u.color+"33":"none"}}>
            {u.pickerLabel||u.label}
          </button>;
        })}
      </div>}
      {(function(){
        // Helpers de get/set — pra Bioter usa data.byUnit[_unitTab], se nao usa root
        const _get = function(key, isRede){
          if(_isBioterCli){
            const un = (data.byUnit||{})[_unitTab]||{};
            if(isRede) return (un.redes||{})[key]||"";
            return un[key]||"";
          }
          if(isRede) return (data.redes||{})[key]||"";
          return data[key]||"";
        };
        const _set = function(key, isRede, val){
          if(_isBioterCli){
            setData(function(p){
              const byUnit = {...(p.byUnit||{})};
              const cur = {...(byUnit[_unitTab]||{redes:{}})};
              if(isRede) cur.redes = {...(cur.redes||{}), [key]:val};
              else cur[key] = val;
              byUnit[_unitTab] = cur;
              return {...p, byUnit};
            });
          } else {
            if(isRede) setData(function(p){return {...p,redes:{...(p.redes||{}),[key]:val}};});
            else setData(function(p){return {...p,[key]:val};});
          }
        };
        // Placeholder com o nome do PRÓPRIO cliente (só sugestão de formato — não é o @ real)
        const _phSlug = String((cl&&(cl.nome||cl.name||cl.id))||"cliente").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]/g,"") || "cliente";
        return <div style={{display:"grid",gridTemplateColumns:_pxMob()?"1fr":"1fr 1fr",gap:8}}>
          {[
            {key:"site",label:"Site oficial",placeholder:"https://www."+_phSlug+".com.br",isRede:false},
            {key:"driveUrl",label:"Pasta no Drive",placeholder:"https://drive.google.com/...",isRede:false},
            {key:"instagram",label:"Instagram",placeholder:"@"+_phSlug,isRede:true},
            {key:"facebook",label:"Facebook",placeholder:"@"+_phSlug,isRede:true},
            {key:"youtube",label:"YouTube",placeholder:"@"+_phSlug,isRede:true},
            {key:"linkedin",label:"LinkedIn",placeholder:"linkedin.com/company/"+_phSlug,isRede:true},
            {key:"tiktok",label:"TikTok",placeholder:"@"+_phSlug,isRede:true},
          ].map(function(f){
            return <div key={f.key}>
              <div style={{color:"#64748b",fontSize:11,marginBottom:5,fontWeight:700,letterSpacing:.3,textTransform:"uppercase"}}>{f.label}</div>
              <input
                value={_get(f.key, f.isRede)}
                onChange={function(e){_set(f.key, f.isRede, e.target.value);}}
                onBlur={function(){persist(data);}}
                placeholder={f.placeholder}
                style={inp}/>
            </div>;
          })}
        </div>;
      })()}
    </_PlaybookSection>}
  </div>);
}

// ── METAS ─────────────────────────────────────────────────
// Estrutura fixa de agência: 4 pilares (Seguidores, Engajamento, Leads, Vendas).
// Cada pilar tem `target` (combinado com cliente no início do ciclo) e
// `current` (atualizado pela equipe ou puxado de relatório).
// Salvo em Supabase `clients.metas` (JSONB) — mesma fonte que o Portal lê,
// então tudo aqui aparece automático no Portal do cliente.
/* ─── Wrapper: se cl é Grupo Bioter, renderiza Grupo + todas unidades empilhadas ─── */
function CMetasWithUnits({cl, accentColor, readOnly}){
  const _isBioterGroup = cl && cl.id === "bioter";
  if(!_isBioterGroup) return <CMetas cl={cl} accentColor={accentColor} readOnly={readOnly}/>;
  const _units = (typeof BIOTER_GROUP_UNITS !== "undefined" && Array.isArray(BIOTER_GROUP_UNITS)) ? BIOTER_GROUP_UNITS : [];
  return <div style={{display:"flex",flexDirection:"column",gap:22}}>
    <CMetas cl={cl} accentColor={accentColor} readOnly={readOnly}/>
    {_units.map(function(u){
      // unitId sem o prefixo "bioter_" pra ficar limpo no JSONB (chapeco, toledo, etc)
      const _uid = String(u.id||"").replace(/^bioter_/,"");
      return <CMetas key={u.id} cl={cl} accentColor={accentColor} readOnly={readOnly}
        unitId={_uid} unitLabel={u.name}/>;
    })}
  </div>;
}

function CMetas({cl, accentColor, readOnly, unitId, unitLabel}){
  const accent = accentColor || cl.color || "#9F43F6";
  const sb = window._sb;
  // unitId opcional: isola persistência por unidade (Bioter Chapecó, Toledo, etc)
  // localStorage: pixels-goals-{cl.id}-unit-{unitId}
  // Supabase: metas.byUnit[unitId] em vez de metas root
  const _uSuffix = unitId ? ("-unit-"+unitId) : "";

  // ── Mês de referência (YYYY-MM) — controla qual snapshot é editado e gráfico ──
  function _ymKey(d){ return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0"); }
  function _ymLabel(ym){
    const parts=String(ym||"").split("-"); if(parts.length<2) return ym||"";
    const mn=["Janeiro","Fevereiro","Março","Abril","Maio","Junho","Julho","Agosto","Setembro","Outubro","Novembro","Dezembro"];
    const m=parseInt(parts[1],10)-1;
    return (mn[m]||"?")+" "+parts[0];
  }
  function _ymShift(ym, delta){
    const p=String(ym||"").split("-"); if(p.length<2) return ym;
    let y=parseInt(p[0],10), m=parseInt(p[1],10)-1+delta;
    while(m<0){m+=12;y-=1;}
    while(m>11){m-=12;y+=1;}
    return y+"-"+String(m+1).padStart(2,"0");
  }
  const _currentYM = _ymKey(new Date());
  const [refMonth, setRefMonth] = useState(_currentYM);

  const PILARES = [
    {key:"seguidores",  label:"Seguidores",  ico:"users",       color:"#0ea5e9", redes:true,
     desc:"Crescimento da audiência em cada rede",             unit:"", scope:"acumulado"},
    {key:"leads",       label:"Leads",       ico:"flame",       color:"#f59e0b",
     desc:"Leads gerados via tráfego pago",         unit:"", scope:"mensal"},
    {key:"vendas",      label:"Vendas digital",     ico:"trending-up", color:"#16a34a",
     desc:"Vendas/conversões atribuídas ao marketing",         unit:"",  scope:"mensal"},
    {key:"faturamento", label:"Faturamento digital",ico:"dollar",      color:"#14b8a6",
     desc:"Receita gerada por canais digitais (R$)",           unit:"",  scope:"mensal"},
    {key:"roi",         label:"ROI",                ico:"chart",       color:"#7c3aed",
     desc:"Retorno sobre investimento em mídia paga",          unit:"x", scope:"mensal"},
  ];

  // Seguidores tem um número por rede: metas["seguidores_facebook"] e metas["seguidores_instagram"].
  // O legado metas["seguidores"] (sem rede) é lido como Instagram até a primeira edição.
  const REDES = [
    {id:"facebook",  label:"Facebook",  cor:"#1877F2"},
    {id:"instagram", label:"Instagram", cor:"#E4405F"},
  ];
  const _slotKey = function(p, redeId){ return p.redes ? (p.key+"_"+redeId) : p.key; };
  const SLOTS = PILARES.reduce(function(acc,p){
    if(p.redes) REDES.forEach(function(r){ acc.push(_slotKey(p,r.id)); }); else acc.push(p.key);
    return acc;
  },[]);
  const _logoRede = function(id, sz){
    if(id==="facebook") return <svg width={sz} height={sz} viewBox="0 0 24 24" fill="currentColor"><path d="M24 12.07C24 5.4 18.63 0 12 0S0 5.4 0 12.07C0 18.1 4.39 23.1 10.13 24v-8.44H7.08v-3.49h3.05V9.41c0-3.02 1.79-4.69 4.53-4.69 1.31 0 2.68.24 2.68.24v2.97h-1.51c-1.49 0-1.96.93-1.96 1.89v2.25h3.33l-.53 3.49h-2.8V24C19.61 23.1 24 18.1 24 12.07z"/></svg>;
    return <svg width={sz} height={sz} viewBox="0 0 24 24" fill="currentColor"><path d="M12 2.16c3.2 0 3.58.01 4.85.07 1.17.05 1.8.25 2.23.41.56.22.96.48 1.38.9.42.42.68.82.9 1.38.16.42.36 1.06.41 2.23.06 1.27.07 1.65.07 4.85s-.01 3.58-.07 4.85c-.05 1.17-.25 1.8-.41 2.23-.22.56-.48.96-.9 1.38-.42.42-.82.68-1.38.9-.42.16-1.06.36-2.23.41-1.27.06-1.65.07-4.85.07s-3.58-.01-4.85-.07c-1.17-.05-1.8-.25-2.23-.41-.56-.22-.96-.48-1.38-.9-.42-.42-.68-.82-.9-1.38-.16-.42-.36-1.06-.41-2.23C2.17 15.58 2.16 15.2 2.16 12s.01-3.58.07-4.85c.05-1.17.25-1.8.41-2.23.22-.56.48-.96.9-1.38.42-.42.82-.68 1.38-.9.42-.16 1.06-.36 2.23-.41C8.42 2.17 8.8 2.16 12 2.16M12 0C8.74 0 8.33.01 7.05.07 5.78.13 4.9.33 4.14.63c-.79.3-1.46.72-2.13 1.38C1.35 2.68.93 3.35.63 4.14.33 4.9.13 5.78.07 7.05.01 8.33 0 8.74 0 12s.01 3.67.07 4.95c.06 1.27.26 2.15.56 2.91.3.79.72 1.46 1.38 2.13.67.66 1.34 1.08 2.13 1.38.76.3 1.64.5 2.91.56C8.33 23.99 8.74 24 12 24s3.67-.01 4.95-.07c1.27-.06 2.15-.26 2.91-.56.79-.3 1.46-.72 2.13-1.38.66-.67 1.08-1.34 1.38-2.13.3-.76.5-1.64.56-2.91.06-1.28.07-1.69.07-4.95s-.01-3.67-.07-4.95c-.06-1.27-.26-2.15-.56-2.91-.3-.79-.72-1.46-1.38-2.13C21.32 1.35 20.65.93 19.86.63c-.76-.3-1.64-.5-2.91-.56C15.67.01 15.26 0 12 0z"/><path d="M12 5.84A6.16 6.16 0 1 0 18.16 12 6.16 6.16 0 0 0 12 5.84zM12 16a4 4 0 1 1 4-4 4 4 0 0 1-4 4z"/><circle cx="18.41" cy="5.59" r="1.44"/></svg>;
  };

  function _legacyToPilares(arr){
    const out={};
    (arr||[]).forEach(function(g){
      const t=(g.title||"").toLowerCase();
      let k=null;
      if(t.indexOf("seguidor")>=0) k="seguidores";
      else if(t.indexOf("alcance")>=0||t.indexOf("impress")>=0||t.indexOf("reach")>=0) k="alcance";
      else if(t.indexOf("engaj")>=0||t.indexOf("eng.")>=0) k="engajamento";
      else if(t.indexOf("lead")>=0) k="leads";
      else if(t.indexOf("venda")>=0||t.indexOf("conver")>=0) k="vendas";
      else if(t.indexOf("faturament")>=0||t.indexOf("receita")>=0) k="faturamento";
      else if(t.indexOf("roi")>=0||t.indexOf("retorno")>=0) k="roi";
      if(k && !out[k]) out[k]={target:Number(g.target)||0,current:Number(g.current)||0};
    });
    return out;
  }

  const _initialMetas = (function(){
    try{
      const s=localStorage.getItem("pixels-goals-"+cl.id+_uSuffix);
      if(s){
        const parsed=JSON.parse(s);
        if(parsed && !Array.isArray(parsed) && typeof parsed==="object") return parsed;
        if(Array.isArray(parsed)) return _legacyToPilares(parsed);
      }
    }catch(e){}
    // Fallback pra dados legacy só quando não é unidade (unitId==null)
    if(!unitId){
      if(Array.isArray(cl.goals)) return _legacyToPilares(cl.goals);
      if(Array.isArray(cl.metas)) return _legacyToPilares(cl.metas);
      if(cl.metas && typeof cl.metas==="object") return cl.metas;
    }
    return {};
  })();

  const [metas,setMetas] = useState(_initialMetas);
  const [redeSel,setRedeSel] = useState("instagram"); // rede exibida no card Seguidores
  const [savedAt,setSavedAt] = useState(0);

  useEffect(function(){
    if(!sb) return;
    let alive = true;
    function reload(){
      sb.from("clients").select("metas").eq("client_id",cl.id).single()
        .then(function(r){
          if(!alive) return;
          if(r.error) return;
          const remoteAll = r.data && r.data.metas;
          if(!remoteAll || typeof remoteAll!=="object") return;
          if(unitId){
            // Lê sub-campo byUnit[unitId]
            const sub = remoteAll.byUnit && remoteAll.byUnit[unitId];
            if(sub && typeof sub==="object" && !Array.isArray(sub)) setMetas(sub);
          } else {
            // Ignora byUnit — só pega os campos root (metas do grupo/cliente principal)
            const rootOnly = {};
            Object.keys(remoteAll).forEach(function(k){ if(k!=="byUnit") rootOnly[k]=remoteAll[k]; });
            if(!Array.isArray(remoteAll)) setMetas(rootOnly);
            else setMetas(_legacyToPilares(remoteAll));
          }
        })
        .catch(function(){});
    }
    reload();
    const ch = sb.channel("clients-metas-"+cl.id+_uSuffix)
      .on("postgres_changes",{event:"UPDATE",schema:"public",table:"clients",filter:"client_id=eq."+cl.id},
        function(){ reload(); })
      .subscribe();
    function onFocus(){ reload(); }
    window.addEventListener("focus",onFocus);
    return function(){
      alive=false;
      try{ sb.removeChannel(ch); }catch(e){}
      window.removeEventListener("focus",onFocus);
    };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  },[cl.id, unitId]);

  function persist(next){
    setMetas(next);
    try{ localStorage.setItem("pixels-goals-"+cl.id+_uSuffix, JSON.stringify(next)); }catch(e){}
    if(!sb) return;
    if(unitId){
      // Merge: pega o objeto atual, escreve byUnit[unitId]=next
      sb.from("clients").select("metas").eq("client_id",cl.id).single()
        .then(function(r){
          const current = (r.data && r.data.metas && typeof r.data.metas==="object" && !Array.isArray(r.data.metas)) ? r.data.metas : {};
          const merged = Object.assign({}, current, {byUnit: Object.assign({}, current.byUnit||{}, {[unitId]: next})});
          sb.from("clients").update({metas:merged,updated_by:(typeof CURRENT_USER!=="undefined"?CURRENT_USER.name:"system")}).eq("client_id",cl.id)
            .then(function(r2){
              if(r2.error){ console.warn("[metas] save unit:",r2.error.message); return; }
              setSavedAt(Date.now());
            })
            .catch(function(e){ console.warn("[metas] save unit:",e?.message||e); });
        });
    } else {
      // Salva root, preserva byUnit se existir
      sb.from("clients").select("metas").eq("client_id",cl.id).single()
        .then(function(r){
          const current = (r.data && r.data.metas && typeof r.data.metas==="object" && !Array.isArray(r.data.metas)) ? r.data.metas : {};
          const byUnitPreserved = current.byUnit ? {byUnit: current.byUnit} : {};
          const merged = Object.assign({}, next, byUnitPreserved);
          sb.from("clients").update({metas:merged,updated_by:(typeof CURRENT_USER!=="undefined"?CURRENT_USER.name:"system")}).eq("client_id",cl.id)
            .then(function(r2){
              if(r2.error){ console.warn("[metas] save:",r2.error.message); return; }
              setSavedAt(Date.now());
            })
            .catch(function(e){ console.warn("[metas] save:",e?.message||e); });
        });
    }
  }

  function _readSnapshot(key, ym){
    let m = metas[key] || {};
    if(Object.keys(m).length===0 && /_instagram$/.test(key)){
      const legado = metas[key.replace(/_instagram$/,"")];
      if(legado && typeof legado==="object") m = legado;
    }
    if(m.history && m.history[ym]) return {target:Number(m.history[ym].target||0), current:Number(m.history[ym].current||0)};
    // Fallback: se ainda não tem history mas é o mês atual, usa o root (legado)
    if(ym===_currentYM) return {target:Number(m.target||0), current:Number(m.current||0)};
    // Pra meses sem dado, herdamos a meta (target) do snapshot mais recente conhecido pra não obrigar redigitar
    let inheritedTarget = 0;
    if(m.history){
      const keys = Object.keys(m.history).filter(function(k){return k<=ym;}).sort();
      if(keys.length>0) inheritedTarget = Number(m.history[keys[keys.length-1]].target||0);
    }
    if(!inheritedTarget) inheritedTarget = Number(m.target||0);
    return {target: inheritedTarget, current: 0};
  }
  function setField(key,field,val){
    if(readOnly) return;
    const num = val===""?0:Number(val);
    const safeVal = isFinite(num)?num:0;
    const cur = metas[key] || {};
    const history = Object.assign({}, cur.history||{});
    const prevSnap = _readSnapshot(key, refMonth);
    history[refMonth] = Object.assign({}, prevSnap, {[field]: safeVal});
    const nextPilar = Object.assign({}, cur, {history:history});
    // Mantém root current/target sincronizados com o mês CORRENTE (não com refMonth) pra leituras legacy
    if(refMonth===_currentYM){
      nextPilar.target  = Number(history[refMonth].target||0);
      nextPilar.current = Number(history[refMonth].current||0);
    }
    const next = Object.assign({}, metas, {[key]: nextPilar});
    persist(next);
  }

  const FF="'Inter',system-ui,-apple-system,sans-serif";

  const atingidos = SLOTS.filter(function(k){
    const snap = _readSnapshot(k, refMonth);
    if(!snap.target) return false;
    return snap.current >= snap.target;
  }).length;

  return <div style={{display:"flex",flexDirection:"column",gap:14,fontFamily:FF}}>

    <div style={{background:"#fff",border:"0.5px solid #e2e8f0",borderRadius:14,padding:"16px 20px",display:"flex",alignItems:"center",justifyContent:"space-between",gap:14,flexWrap:"wrap"}}>
      <div style={{display:"flex",alignItems:"center",gap:14,minWidth:0}}>
        <div style={{width:44,height:44,borderRadius:12,background:accent+"15",border:"1px solid "+accent+"33",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
          {typeof Ico==="function"
            ? <Ico n="target" size={20} color={accent}/>
            : <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke={accent} strokeWidth="2.2"><circle cx="12" cy="12" r="10"/><circle cx="12" cy="12" r="6"/><circle cx="12" cy="12" r="2"/></svg>}
        </div>
        <div>
          <div style={{color:"#0f172a",fontWeight:700,fontSize:15,letterSpacing:-.2}}>Metas — {unitLabel || cl.name}</div>
        </div>
      </div>
      <div style={{display:"flex",alignItems:"center",gap:10,flexWrap:"wrap"}}>
        {savedAt>0 && Date.now()-savedAt<3000 && <span style={{color:"#16a34a",fontSize:11,fontWeight:600}}>Salvo</span>}
        {/* Seletor de mês de referência */}
        <div style={{display:"inline-flex",alignItems:"center",background:"#fff",border:"1px solid #e2e8f0",borderRadius:11,padding:3,boxShadow:"0 1px 2px rgba(15,23,42,0.03)"}}>
          <button type="button" title="Mês anterior" onClick={function(e){e.preventDefault();e.stopPropagation();setRefMonth(_ymShift(refMonth,-1));}}
            style={{background:"transparent",border:"none",borderRadius:8,width:28,height:28,display:"inline-flex",alignItems:"center",justifyContent:"center",cursor:"pointer",color:"#64748b",transition:"all .12s"}}
            onMouseEnter={function(e){e.currentTarget.style.background="#f1f5f9";e.currentTarget.style.color="#0f172a";}}
            onMouseLeave={function(e){e.currentTarget.style.background="transparent";e.currentTarget.style.color="#64748b";}}>
            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><polyline points="15 18 9 12 15 6"/></svg>
          </button>
          <div style={{padding:"0 12px",minWidth:120,textAlign:"center",fontSize:11.5,fontWeight:700,color:accent,letterSpacing:-.1,fontFeatureSettings:"'tnum'",textTransform:"capitalize"}}>{_ymLabel(refMonth)}</div>
          <button type="button" title="Próximo mês" onClick={function(e){e.preventDefault();e.stopPropagation();setRefMonth(_ymShift(refMonth,1));}}
            style={{background:"transparent",border:"none",borderRadius:8,width:28,height:28,display:"inline-flex",alignItems:"center",justifyContent:"center",cursor:"pointer",color:"#64748b",transition:"all .12s"}}
            onMouseEnter={function(e){e.currentTarget.style.background="#f1f5f9";e.currentTarget.style.color="#0f172a";}}
            onMouseLeave={function(e){e.currentTarget.style.background="transparent";e.currentTarget.style.color="#64748b";}}>
            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><polyline points="9 18 15 12 9 6"/></svg>
          </button>
        </div>
        <div style={{background:atingidos===SLOTS.length?"#dcfce7":"#f1f5f9",color:atingidos===SLOTS.length?"#15803d":"#0f172a",border:"1px solid "+(atingidos===SLOTS.length?"#bbf7d0":"#e2e8f0"),borderRadius:99,padding:"4px 11px",fontSize:11,fontWeight:700,letterSpacing:-.1}}>
          {atingidos}/{SLOTS.length} atingidas
        </div>
      </div>
    </div>

    <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(260px,1fr))",gap:12}}>
      {PILARES.map(function(p){
        // Pilar por rede: status do card = pior rede (se alguma está definida)
        const _slotsDoPilar = p.redes ? REDES.map(function(r){return _slotKey(p,r.id);}) : [p.key];
        const _snaps = _slotsDoPilar.map(function(k){ return _readSnapshot(k, refMonth); });
        const _defs = _snaps.filter(function(sn){return sn.target>0;});
        const m = _defs.length ? _defs.reduce(function(a,b){ return (a.current/a.target) <= (b.current/b.target) ? a : b; }) : (_snaps[0]||{target:0,current:0});
        const tgt = Number(m.target||0);
        const cur = Number(m.current||0);
        const pct = tgt>0 ? Math.min(100, Math.round(cur/tgt*100)) : 0;
        const ok = _defs.length>0 && _defs.every(function(sn){return sn.current>=sn.target;});
        const status = ok ? {label:"Meta atingida", color:"#16a34a", bg:"#dcfce7", border:"#bbf7d0"}
                          : pct>=70 ? {label:"No caminho",      color:"#a16207", bg:"#fef3c7", border:"#fde68a"}
                          : pct>=40 ? {label:"Em progresso",    color:"#9a3412", bg:"#ffedd5", border:"#fed7aa"}
                          : tgt===0 ? {label:"Não definida",    color:"#64748b", bg:"#f1f5f9", border:"#e2e8f0"}
                                    : {label:"Atrasada",        color:"#991b1b", bg:"#fee2e2", border:"#fecaca"};

        return <div key={p.key} style={{background:"#fff",border:"0.5px solid #e2e8f0",borderRadius:14,padding:"18px 18px 16px",display:"flex",flexDirection:"column",gap:12,fontFamily:FF,boxShadow:"0 1px 3px rgba(15,23,42,0.04)"}}>
          <div style={{display:"flex",alignItems:"center",gap:11}}>
            <div style={{width:38,height:38,borderRadius:11,background:p.color,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0,boxShadow:"0 4px 12px "+p.color+"55"}}>
              {typeof Ico==="function" && <Ico n={p.ico} size={18} color="#fff"/>}
            </div>
            <div style={{flex:1,minWidth:0}}>
              <div style={{color:"#0f172a",fontWeight:700,fontSize:14,letterSpacing:-.2}}>{p.label}</div>
              <div style={{color:"#94a3b8",fontSize:10.5,marginTop:1,textTransform:"uppercase",letterSpacing:.4,fontWeight:600}}>
                {p.scope==="acumulado"?"Nas redes sociais":"Por mês"}
              </div>
            </div>
            <span style={{background:status.bg,color:status.color,border:"1px solid "+status.border,borderRadius:99,padding:"3px 9px",fontSize:9.5,fontWeight:800,letterSpacing:.3,textTransform:"uppercase",whiteSpace:"nowrap"}}>
              {status.label}
            </span>
          </div>

          {(function(){
            // Pilar por rede: mostra UMA rede por vez (setinha alterna) pra manter a altura dos outros cards
            const rede = p.redes ? (REDES.find(function(r){return r.id===redeSel;})||REDES[0]) : null;
            const slotKey = rede ? _slotKey(p, rede.id) : p.key;
            const sm = _readSnapshot(slotKey, refMonth);
            const stgt = Number(sm.target||0), scur = Number(sm.current||0);
            const corNum = rede ? rede.cor : p.color;
            const _idx = rede ? REDES.findIndex(function(r){return r.id===rede.id;}) : -1;
            return <div style={{display:"flex",flexDirection:"column",gap:10}}>
              {rede && <div style={{display:"flex",alignItems:"center",gap:8}}>
                {/* Seletor de rede: os dois logos lado a lado, o escolhido colorido, o outro cinza claro */}
                {REDES.map(function(r){
                  const on = r.id===rede.id;
                  return <button key={r.id} type="button" title={on?r.label:("Ver "+r.label)} onClick={function(e){e.preventDefault();e.stopPropagation();setRedeSel(r.id);}}
                    style={{display:"inline-flex",alignItems:"center",gap:6,background:"none",border:"none",padding:0,cursor:on?"default":"pointer",fontFamily:FF,transition:"opacity .15s"}}
                    onMouseEnter={function(e){if(!on)e.currentTarget.style.opacity=".75";}}
                    onMouseLeave={function(e){e.currentTarget.style.opacity="1";}}>
                    <span style={{width:22,height:22,borderRadius:6,background:on?r.cor:"#e2e8f0",color:on?"#fff":"#cbd5e1",display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0,transition:"background .15s"}}>{_logoRede(r.id,13)}</span>
                    {on && <span style={{color:r.cor,fontSize:11.5,fontWeight:800,letterSpacing:-.1}}>{r.label}</span>}
                  </button>;
                })}
              </div>}
              <div style={{display:"grid",gridTemplateColumns:_pxMob()?"1fr":"1fr 1fr",gap:8}}>
                <div>
                  <div style={{color:"#64748b",fontSize:10,fontWeight:700,textTransform:"uppercase",letterSpacing:.5,marginBottom:4}}>Meta</div>
                  <div style={{position:"relative"}}>
                    <input type="number" inputMode="decimal" value={stgt||""} placeholder="0"
                      onChange={function(e){ setField(slotKey,"target",e.target.value); }}
                      disabled={readOnly}
                      style={{width:"100%",boxSizing:"border-box",background:readOnly?"#f8fafc":"#fff",border:"1px solid #e2e8f0",borderRadius:8,padding:"9px 11px",fontSize:18,fontWeight:800,color:"#0f172a",outline:"none",fontFamily:FF,fontFeatureSettings:"'tnum'"}}/>
                    {p.unit && <span style={{position:"absolute",right:11,top:"50%",transform:"translateY(-50%)",color:"#94a3b8",fontSize:11,fontWeight:600,pointerEvents:"none"}}>{p.unit}</span>}
                  </div>
                </div>
                <div>
                  <div style={{color:"#64748b",fontSize:10,fontWeight:700,textTransform:"uppercase",letterSpacing:.5,marginBottom:4}}>Executado</div>
                  <div style={{position:"relative"}}>
                    <input type="number" inputMode="decimal" value={scur||""} placeholder="0"
                      onChange={function(e){ setField(slotKey,"current",e.target.value); }}
                      disabled={readOnly}
                      style={{width:"100%",boxSizing:"border-box",background:readOnly?"#f8fafc":"#fff",border:"1px solid #e2e8f0",borderRadius:8,padding:"9px 11px",fontSize:18,fontWeight:800,color:corNum,outline:"none",fontFamily:FF,fontFeatureSettings:"'tnum'"}}/>
                    {p.unit && <span style={{position:"absolute",right:11,top:"50%",transform:"translateY(-50%)",color:"#94a3b8",fontSize:11,fontWeight:600,pointerEvents:"none"}}>{p.unit}</span>}
                  </div>
                </div>
              </div>
            </div>;
          })()}

          <div style={{color:"#94a3b8",fontSize:11,lineHeight:1.45}}>{p.desc}</div>
        </div>;
      })}
    </div>


  </div>;
}

// ── ONGOING ─────────────────────────────────────────────────────────
// Rotina contínua do cliente depois do onboarding. 4 seções:
//   1) Resumo (5 mini-cards: última/próxima reunião, plan. mensal/trim, indicação)
//   2) Reuniões — registra datas, tipo, observações
//   3) Rotina mensal — checklist de 7 itens padrão por mês
//   4) Rotina trimestral — checklist de 7 itens padrão por trimestre
//   5) Pendências — lista simples de coisas que dependem do cliente
// Persistido em Supabase clients.ongoing (JSONB) — pattern igual metas/orientacoes.
function COngoing({cl, isMob}){
  const FF = "'Inter',system-ui,-apple-system,sans-serif";
  const accent = cl.color || "#9F43F6";
  const sb = window._sb;

  // Schema padrão dos itens recorrentes
  const MONTHLY_ITEMS = [
    {id:"resultados",  label:"Analisar resultados do mês"},
    {id:"relatorio",   label:"Preparar relatório mensal"},
    {id:"reuniao",     label:"Realizar reunião mensal com o cliente"},
    {id:"metas",       label:"Atualizar metas do cliente"},
    {id:"conteudos",   label:"Planejar conteúdos do próximo mês"},
    {id:"campanhas",   label:"Verificar campanhas e oportunidades"},
    {id:"materiais",   label:"Solicitar materiais importantes para o cliente"},
  ];
  const QUARTERLY_ITEMS = [
    {id:"posicionamento", label:"Revisar posicionamento do cliente"},
    {id:"ofertas",        label:"Revisar principais ofertas/produtos/serviços"},
    {id:"plano3m",        label:"Planejar próximos 3 meses"},
    {id:"evolucao",       label:"Analisar evolução dos resultados"},
    {id:"oportunidades",  label:"Levantar novas oportunidades comerciais"},
    {id:"indicacao",      label:"Pedir indicação para o cliente"},
    {id:"depoimento",     label:"Solicitar depoimento/case (se fizer sentido)"},
  ];

  // Period helpers
  function _currentMonth(){
    const d = new Date();
    return d.getFullYear() + "-" + String(d.getMonth()+1).padStart(2,"0");
  }
  function _currentQuarter(){
    const d = new Date();
    const q = Math.floor(d.getMonth()/3) + 1;
    return d.getFullYear() + "-Q" + q;
  }

  // ── State + persistência ──────────────────────
  const [data, setData] = useState({
    reunioes: {ultima:"", proxima:"", tipo:"alinhamento", obs:""},
    proximos: {planMensal:"", planTrimestral:"", indicacao:""},
    mensal: {},        // {"2026-06": {resultados:{done:true,resp:"vinicius",due:"2026-06-30",at:"..."}}}
    trimestral: {},    // {"2026-Q2": {...}}
    pendencias: [],    // [{id, title, date, status}]
    atas: []           // [{id, date, title, notes, participants:[uid], by, createdAt}]
  });
  const [savedAt, setSavedAt] = useState(0);
  const [periodMonth, setPeriodMonth] = useState(_currentMonth());
  const [periodQuarter, setPeriodQuarter] = useState(_currentQuarter());

  useEffect(function(){
    if(!sb) return;
    let alive = true;
    sb.from("clients").select("ongoing").eq("client_id",cl.id).single()
      .then(function(r){
        if(!alive) return;
        if(r.error) return;
        const remote = r.data && r.data.ongoing;
        if(remote && typeof remote==="object"){
          setData(function(prev){
            return Object.assign({}, prev, remote, {
              reunioes: Object.assign({}, prev.reunioes, remote.reunioes||{}),
              proximos: Object.assign({}, prev.proximos, remote.proximos||{}),
              mensal: remote.mensal||{},
              trimestral: remote.trimestral||{},
              pendencias: Array.isArray(remote.pendencias)?remote.pendencias:[],
              atas: Array.isArray(remote.atas)?remote.atas:[]
            });
          });
        }
      })
      .catch(function(){});
    return function(){ alive = false; };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  },[cl.id]);

  function persist(next){
    setData(next);
    if(!sb) return;
    sb.from("clients").update({ongoing:next,updated_by:(typeof CURRENT_USER!=="undefined"?CURRENT_USER.name:"system")}).eq("client_id",cl.id)
      .then(function(r){
        if(r.error){ console.warn("[ongoing] save:", r.error.message); return; }
        setSavedAt(Date.now());
      })
      .catch(function(e){ console.warn("[ongoing] save exception:", e?.message||e); });
  }

  // ── Helpers de status visual ──────────────────
  function _dateBR(iso){
    if(!iso || iso.length<10) return "—";
    return iso.slice(8,10)+"/"+iso.slice(5,7)+"/"+iso.slice(0,4);
  }
  function _daysUntil(iso){
    if(!iso || iso.length<10) return null;
    const d = new Date(iso+"T00:00:00");
    const today = new Date(); today.setHours(0,0,0,0);
    return Math.round((d-today)/(1000*60*60*24));
  }
  function _statusForFuture(iso){
    const days = _daysUntil(iso);
    if(days === null) return {label:"Sem data", color:"#94a3b8", bg:"#f1f5f9", border:"#e2e8f0"};
    if(days < 0) return {label:"Atrasado", color:"#991b1b", bg:"#fee2e2", border:"#fecaca"};
    if(days <= 7) return {label:"Próximo", color:"#a16207", bg:"#fef3c7", border:"#fde68a"};
    return {label:"Em dia", color:"#15803d", bg:"#dcfce7", border:"#bbf7d0"};
  }

  // ── Reuniões: marcar realizada ────────────────
  function markMeetingDone(){
    const today = new Date().toISOString().slice(0,10);
    const next = Object.assign({}, data, {
      reunioes: Object.assign({}, data.reunioes, {ultima: data.reunioes.proxima || today, proxima:""})
    });
    persist(next);
  }
  function setReuniaoField(field, val){
    const next = Object.assign({}, data, {reunioes: Object.assign({}, data.reunioes, {[field]:val})});
    persist(next);
  }
  function setProximoField(field, val){
    const next = Object.assign({}, data, {proximos: Object.assign({}, data.proximos, {[field]:val})});
    persist(next);
  }

  // ── Checklist (mensal/trimestral) ─────────────
  function getChecklistItem(scope, period, itemId){
    const bucket = (data[scope]||{})[period] || {};
    return bucket[itemId] || {done:false, resp:"", due:"", at:""};
  }
  function setChecklistField(scope, period, itemId, field, val){
    const allBucket = data[scope] || {};
    const periodBucket = allBucket[period] || {};
    const item = periodBucket[itemId] || {done:false, resp:"", due:"", at:""};    const newItem = Object.assign({}, item, {[field]:val});
    if(field==="done"){
      newItem.at = val ? new Date().toISOString() : "";
    }
    const newPeriod = Object.assign({}, periodBucket, {[itemId]:newItem});
    const newAll = Object.assign({}, allBucket, {[period]:newPeriod});
    persist(Object.assign({}, data, {[scope]:newAll}));
  }
  function _itemStatus(item){
    if(item.done) return {label:"Concluído", color:"#15803d", bg:"#dcfce7", border:"#bbf7d0"};
    const days = _daysUntil(item.due);
    if(days===null) return {label:"Pendente", color:"#64748b", bg:"#f1f5f9", border:"#e2e8f0"};
    if(days<0) return {label:"Atrasado", color:"#991b1b", bg:"#fee2e2", border:"#fecaca"};
    return {label:"Pendente", color:"#64748b", bg:"#f1f5f9", border:"#e2e8f0"};
  }

  // Pendências
  function addPendencia(){
    const id = "p"+Date.now();
    const item = {id, title:"", date:new Date().toISOString().slice(0,10), status:"pendente"};
    persist(Object.assign({}, data, {pendencias: data.pendencias.concat([item])}));
  }
  function updatePendencia(id, field, val){
    const next = data.pendencias.map(function(p){ return p.id===id ? Object.assign({},p,{[field]:val}) : p; });
    persist(Object.assign({}, data, {pendencias: next}));
  }
  function removePendencia(id){
    persist(Object.assign({}, data, {pendencias: data.pendencias.filter(function(p){return p.id!==id;})}));
  }

  function shiftMonth(delta){
    const parts = periodMonth.split("-");
    let y = parseInt(parts[0],10); let m = parseInt(parts[1],10)+delta;
    while(m<1){m+=12;y--;} while(m>12){m-=12;y++;}
    setPeriodMonth(y+"-"+String(m).padStart(2,"0"));
  }
  function shiftQuarter(delta){
    const parts = periodQuarter.split("-Q");
    let y = parseInt(parts[0],10); let q = parseInt(parts[1],10)+delta;
    while(q<1){q+=4;y--;} while(q>4){q-=4;y++;}
    setPeriodQuarter(y+"-Q"+q);
  }
  function monthLabel(p){
    if(!p) return "";
    const mn = ["Janeiro","Fevereiro","Março","Abril","Maio","Junho","Julho","Agosto","Setembro","Outubro","Novembro","Dezembro"];
    const parts = p.split("-");
    return (mn[parseInt(parts[1],10)-1]||"?")+" de "+parts[0];
  }
  function quarterLabel(p){
    if(!p) return "";
    const parts = p.split("-Q");
    return parts[1]+"º trimestre de "+parts[0];
  }

  // Whitelist explícito da agência pra Responsável (Gustavo, Vinicius, Hellen, Ocsana, Erick)
  const _RESP_IDS = ["gustavo","vinicius","ellen","ocsana","erick"];
  const TEAM_OPTS = (typeof TEAM!=="undefined"?TEAM:[]).filter(function(u){return _RESP_IDS.indexOf(u.id)>=0;});

  function _sectionCard(){
    return {background:"#fff",border:"1px solid #e2e8f0",borderRadius:14,padding:"18px 20px",boxShadow:"0 1px 3px rgba(15,23,42,0.04)"};
  }

  // ── DateField — botão moderno que abre o picker nativo ao clicar ──
  function DateField(props){
    const inputRef = useRef(null);
    function _open(){
      try{
        if(inputRef.current){
          if(typeof inputRef.current.showPicker==="function") inputRef.current.showPicker();
          else inputRef.current.focus();
        }
      }catch(e){
        if(inputRef.current) inputRef.current.focus();
      }
    }
    const hasVal = !!props.value;
    const labelBR = hasVal ? (props.value.slice(8,10)+"/"+props.value.slice(5,7)+"/"+props.value.slice(0,4)) : (props.placeholder||"Selecionar data");
    const _size = props.size||"sm"; // sm | md
    const _h = _size==="md" ? 38 : 32;
    const _fs = _size==="md" ? 13 : 11.5;
    return <div onClick={function(e){e.stopPropagation();_open();}}
      style={{display:"inline-flex",alignItems:"center",gap:7,background:hasVal?"#fff":"#fafbfc",border:"1px solid "+(hasVal?accent+"33":"#e2e8f0"),borderRadius:9,padding:"0 11px",height:_h,fontSize:_fs,color:hasVal?"#0f172a":"#94a3b8",fontWeight:hasVal?700:600,fontFamily:FF,cursor:"pointer",transition:"all .12s",userSelect:"none",position:"relative",fontFeatureSettings:"'tnum'",minWidth:_size==="md"?160:120,boxSizing:"border-box"}}
      onMouseEnter={function(e){e.currentTarget.style.borderColor=accent+"66";e.currentTarget.style.background="#fff";}}
      onMouseLeave={function(e){e.currentTarget.style.borderColor=hasVal?accent+"33":"#e2e8f0";e.currentTarget.style.background=hasVal?"#fff":"#fafbfc";}}>
      <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke={hasVal?accent:"#94a3b8"} strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" style={{flexShrink:0}}>
        <rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/>
      </svg>
      <span style={{whiteSpace:"nowrap"}}>{labelBR}</span>
      {hasVal && !props.readOnly && <button type="button" onClick={function(e){e.preventDefault();e.stopPropagation();props.onChange&&props.onChange("");}} title="Limpar data"
        style={{marginLeft:"auto",background:"transparent",border:"none",cursor:"pointer",padding:0,display:"inline-flex",alignItems:"center",color:"#94a3b8"}}
        onMouseEnter={function(e){e.currentTarget.style.color="#dc2626";}}
        onMouseLeave={function(e){e.currentTarget.style.color="#94a3b8";}}>
        <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
      </button>}
      <input ref={inputRef} type="date" value={props.value||""} onChange={function(e){props.onChange&&props.onChange(e.target.value);}}
        style={{position:"absolute",left:0,top:0,width:"100%",height:"100%",opacity:0,pointerEvents:"none"}}/>
    </div>;
  }

  // ── RespAvatars — fileira de fotos circulares pra selecionar responsável ──
  function RespAvatars(props){
    const sel = props.value||"";
    const sz = props.size||26;
    return <div style={{display:"inline-flex",alignItems:"center",gap:5,flexShrink:0}}>
      {TEAM_OPTS.map(function(u){
        const active = sel===u.id;
        const photo = (u.profile_data && u.profile_data.photo) || ((typeof getProfilePhoto!=="undefined" && getProfilePhoto(u.id))||null);
        const ini = (u.av||(u.name||"?")[0]||"?").toUpperCase();
        return <button key={u.id} type="button"
          title={u.name+(active?" (selecionado)":" — clique pra atribuir")}
          onClick={function(e){e.stopPropagation();props.onChange&&props.onChange(active?"":u.id);}}
          style={{background:"transparent",border:"none",padding:0,cursor:"pointer",borderRadius:"50%",lineHeight:0,position:"relative",transition:"transform .12s",transform:active?"scale(1.0)":"scale(.94)",opacity:sel&&!active?0.45:1,filter:sel&&!active?"grayscale(.6)":"none"}}
          onMouseEnter={function(e){e.currentTarget.style.transform="scale(1.05)";e.currentTarget.style.opacity=1;e.currentTarget.style.filter="none";}}
          onMouseLeave={function(e){e.currentTarget.style.transform=active?"scale(1.0)":"scale(.94)";e.currentTarget.style.opacity=sel&&!active?0.45:1;e.currentTarget.style.filter=sel&&!active?"grayscale(.6)":"none";}}>
          {photo
            ? <img src={photo} alt={u.name} style={{width:sz,height:sz,borderRadius:"50%",objectFit:"cover",display:"block",boxShadow:active?"0 0 0 2.5px "+(u.color||accent)+", 0 2px 6px rgba(15,23,42,0.15)":"0 0 0 1.5px #e2e8f0"}}/>
            : <span style={{display:"inline-flex",width:sz,height:sz,borderRadius:"50%",background:u.color||"#94a3b8",color:"#fff",alignItems:"center",justifyContent:"center",fontWeight:800,fontSize:Math.floor(sz*0.42),fontFamily:FF,boxShadow:active?"0 0 0 2.5px "+(u.color||accent)+", 0 2px 6px rgba(15,23,42,0.15)":"0 0 0 1.5px #e2e8f0"}}>{ini}</span>
          }
          {active && <span style={{position:"absolute",right:-2,bottom:-2,width:11,height:11,borderRadius:"50%",background:"#16a34a",border:"2px solid #fff",display:"inline-flex",alignItems:"center",justifyContent:"center"}}>
            <svg width="6" height="6" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
          </span>}
        </button>;
      })}
    </div>;
  }

  function MiniResume(props){
    const st = _statusForFuture(props.date);
    return <div style={{background:"#fff",border:"1px solid #e2e8f0",borderRadius:12,padding:"12px 14px",display:"flex",flexDirection:"column",gap:6,minWidth:0}}>
      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:6}}>
        <div style={{color:"#94a3b8",fontSize:10,fontWeight:700,textTransform:"uppercase",letterSpacing:.5,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{props.label}</div>
        <span style={{background:st.bg,color:st.color,border:"1px solid "+st.border,fontSize:9,fontWeight:800,padding:"2px 7px",borderRadius:99,letterSpacing:.3,whiteSpace:"nowrap",textTransform:"uppercase"}}>{st.label}</span>
      </div>
      <div style={{color:"#0f172a",fontWeight:800,fontSize:15,letterSpacing:-.3,fontFeatureSettings:"'tnum'"}}>{_dateBR(props.date)}</div>
      {props.date && (function(){
        const d = _daysUntil(props.date);
        if(d===null) return null;
        const txt = d<0 ? "Há "+Math.abs(d)+" "+(Math.abs(d)===1?"dia":"dias") : d===0 ? "Hoje" : "Em "+d+" "+(d===1?"dia":"dias");
        return <div style={{color:"#94a3b8",fontSize:11,fontWeight:500}}>{txt}</div>;
      })()}
    </div>;
  }

  return <div style={{display:"flex",flexDirection:"column",gap:16,fontFamily:FF}}>

    <div style={_sectionCard()}>
      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:12,flexWrap:"wrap",marginBottom:14}}>
        <div style={{display:"flex",alignItems:"center",gap:12,minWidth:0}}>
          <div style={{width:42,height:42,borderRadius:12,background:accent+"15",border:"1px solid "+accent+"33",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
            {typeof Ico==="function" && <Ico n="infinity" size={20} color={accent}/>}
          </div>
          <div>
            <div style={{color:"#0f172a",fontWeight:800,fontSize:17,letterSpacing:-.3}}>Ongoing</div>
            <div style={{color:"#64748b",fontSize:12,marginTop:2}}>Rotina de acompanhamento contínuo do cliente</div>
          </div>
        </div>
        {savedAt>0 && Date.now()-savedAt<3000 && <span style={{color:"#16a34a",fontSize:11,fontWeight:700}}>Salvo</span>}
      </div>
      <div style={{display:"grid",gridTemplateColumns:isMob?"1fr 1fr":"repeat(5,1fr)",gap:10}}>
        <MiniResume label="Última reunião" date={data.reunioes.ultima}/>
        <MiniResume label="Próxima reunião" date={data.reunioes.proxima}/>
        <MiniResume label="Plan. mensal" date={data.proximos.planMensal}/>
        <MiniResume label="Plan. trimestral" date={data.proximos.planTrimestral}/>
        <MiniResume label="Pedido de indicação" date={data.proximos.indicacao}/>
      </div>
    </div>

    <div style={_sectionCard()}>
      <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:14}}>
        {typeof Ico==="function" && <Ico n="calendar" size={16} color={accent}/>}
        <div style={{color:"#0f172a",fontWeight:800,fontSize:15,letterSpacing:-.2}}>Reuniões</div>
      </div>
      <div style={{display:"grid",gridTemplateColumns:isMob?"1fr":"1fr 1fr",gap:12}}>
        <div>
          <div style={{color:"#64748b",fontSize:11,fontWeight:700,textTransform:"uppercase",letterSpacing:.5,marginBottom:5}}>Última reunião</div>
          <DateField size="md" value={data.reunioes.ultima||""} onChange={function(v){setReuniaoField("ultima",v);}}/>
        </div>
        <div>
          <div style={{color:"#64748b",fontSize:11,fontWeight:700,textTransform:"uppercase",letterSpacing:.5,marginBottom:5}}>Próxima reunião</div>
          <DateField size="md" value={data.reunioes.proxima||""} onChange={function(v){setReuniaoField("proxima",v);}}/>
        </div>
        <div>
          <div style={{color:"#64748b",fontSize:11,fontWeight:700,textTransform:"uppercase",letterSpacing:.5,marginBottom:5}}>Tipo da reunião</div>
          <select value={data.reunioes.tipo||"alinhamento"} onChange={function(e){setReuniaoField("tipo",e.target.value);}}
            style={{width:"100%",boxSizing:"border-box",background:"#fff",border:"1px solid #e2e8f0",borderRadius:9,padding:"9px 11px",fontSize:13,color:"#0f172a",outline:"none",fontFamily:FF,cursor:"pointer"}}>
            <option value="alinhamento">Alinhamento</option>
            <option value="resultado">Resultado</option>
            <option value="planejamento">Planejamento</option>
            <option value="outro">Outro</option>
          </select>
        </div>
        <div style={{display:"flex",alignItems:"flex-end"}}>
          <button onClick={markMeetingDone} disabled={!data.reunioes.proxima}
            style={{width:"100%",background:data.reunioes.proxima?accent:"#f1f5f9",color:data.reunioes.proxima?"#fff":"#94a3b8",border:"none",borderRadius:9,padding:"10px 14px",fontSize:12.5,fontWeight:700,cursor:data.reunioes.proxima?"pointer":"not-allowed",fontFamily:FF,transition:"all .15s"}}>
            ✓ Marcar próxima como realizada
          </button>
        </div>
        <div style={{gridColumn:isMob?"1":"1/-1"}}>
          <div style={{color:"#64748b",fontSize:11,fontWeight:700,textTransform:"uppercase",letterSpacing:.5,marginBottom:5}}>Observações rápidas</div>
          <textarea value={data.reunioes.obs||""} onChange={function(e){setReuniaoField("obs",e.target.value);}}
            rows={3}
            placeholder="O que precisa lembrar pra próxima conversa..."
            style={{width:"100%",boxSizing:"border-box",background:"#fff",border:"1px solid #e2e8f0",borderRadius:9,padding:"9px 11px",fontSize:13,color:"#0f172a",outline:"none",fontFamily:FF,resize:"vertical",lineHeight:1.5}}/>
        </div>
      </div>
    </div>

    <div style={_sectionCard()}>
      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:10,flexWrap:"wrap",marginBottom:14}}>
        <div style={{display:"flex",alignItems:"center",gap:8}}>
          {typeof Ico==="function" && <Ico n="checkCircle" size={16} color={accent}/>}
          <div style={{color:"#0f172a",fontWeight:800,fontSize:15,letterSpacing:-.2}}>Rotina mensal</div>
        </div>
        <div style={{display:"inline-flex",alignItems:"center",background:"#fff",border:"1px solid #e2e8f0",borderRadius:9,padding:3}}>
          <button onClick={function(){shiftMonth(-1);}} style={{background:"transparent",border:"none",borderRadius:6,width:28,height:28,cursor:"pointer",color:"#64748b",display:"inline-flex",alignItems:"center",justifyContent:"center"}}>
            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><polyline points="15 18 9 12 15 6"/></svg>
          </button>
          <span style={{padding:"0 12px",fontSize:12.5,fontWeight:700,color:accent,minWidth:130,textAlign:"center"}}>{monthLabel(periodMonth)}</span>
          <button onClick={function(){shiftMonth(1);}} style={{background:"transparent",border:"none",borderRadius:6,width:28,height:28,cursor:"pointer",color:"#64748b",display:"inline-flex",alignItems:"center",justifyContent:"center"}}>
            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><polyline points="9 18 15 12 9 6"/></svg>
          </button>
        </div>
      </div>
      <div style={{display:"flex",flexDirection:"column",gap:6}}>
        {MONTHLY_ITEMS.map(function(item){
          const it = getChecklistItem("mensal", periodMonth, item.id);
          const st = _itemStatus(it);
          return <ChecklistRow key={item.id} item={item} it={it} st={st} accent={accent} teamOpts={TEAM_OPTS} RespAvatars={RespAvatars} DateField={DateField}
            onToggle={function(){setChecklistField("mensal", periodMonth, item.id, "done", !it.done);}}
            onResp={function(v){setChecklistField("mensal", periodMonth, item.id, "resp", v);}}
            onDue={function(v){setChecklistField("mensal", periodMonth, item.id, "due", v);}}/>;
        })}
      </div>
    </div>

    <div style={_sectionCard()}>
      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:10,flexWrap:"wrap",marginBottom:14}}>
        <div style={{display:"flex",alignItems:"center",gap:8}}>
          {typeof Ico==="function" && <Ico n="layers" size={16} color={accent}/>}
          <div style={{color:"#0f172a",fontWeight:800,fontSize:15,letterSpacing:-.2}}>Rotina trimestral</div>
        </div>
        <div style={{display:"inline-flex",alignItems:"center",background:"#fff",border:"1px solid #e2e8f0",borderRadius:9,padding:3}}>
          <button onClick={function(){shiftQuarter(-1);}} style={{background:"transparent",border:"none",borderRadius:6,width:28,height:28,cursor:"pointer",color:"#64748b",display:"inline-flex",alignItems:"center",justifyContent:"center"}}>
            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><polyline points="15 18 9 12 15 6"/></svg>
          </button>
          <span style={{padding:"0 12px",fontSize:12.5,fontWeight:700,color:accent,minWidth:130,textAlign:"center"}}>{quarterLabel(periodQuarter)}</span>
          <button onClick={function(){shiftQuarter(1);}} style={{background:"transparent",border:"none",borderRadius:6,width:28,height:28,cursor:"pointer",color:"#64748b",display:"inline-flex",alignItems:"center",justifyContent:"center"}}>
            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><polyline points="9 18 15 12 9 6"/></svg>
          </button>
        </div>
      </div>
      <div style={{display:"flex",flexDirection:"column",gap:6}}>
        {QUARTERLY_ITEMS.map(function(item){
          const it = getChecklistItem("trimestral", periodQuarter, item.id);
          const st = _itemStatus(it);
          return <ChecklistRow key={item.id} item={item} it={it} st={st} accent={accent} teamOpts={TEAM_OPTS} RespAvatars={RespAvatars} DateField={DateField}
            onToggle={function(){setChecklistField("trimestral", periodQuarter, item.id, "done", !it.done);}}
            onResp={function(v){setChecklistField("trimestral", periodQuarter, item.id, "resp", v);}}
            onDue={function(v){setChecklistField("trimestral", periodQuarter, item.id, "due", v);}}/>;
        })}
      </div>
    </div>

    <div style={_sectionCard()}>
      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:10,marginBottom:14}}>
        <div style={{display:"flex",alignItems:"center",gap:8}}>
          {typeof Ico==="function" && <Ico n="alert" size={16} color={accent}/>}
          <div style={{color:"#0f172a",fontWeight:800,fontSize:15,letterSpacing:-.2}}>Pendências do cliente</div>
          <span style={{background:"#f1f5f9",color:"#64748b",fontSize:10.5,fontWeight:700,padding:"2px 8px",borderRadius:99}}>{(data.pendencias||[]).filter(function(p){return p.status!=="resolvido";}).length} abertas</span>
        </div>
        <button onClick={addPendencia}
          style={{background:accent+"15",border:"1px solid "+accent+"33",borderRadius:9,padding:"7px 13px",color:accent,fontSize:12,fontWeight:700,cursor:"pointer",fontFamily:FF,display:"inline-flex",alignItems:"center",gap:6,transition:"all .15s"}}
          onMouseEnter={function(e){e.currentTarget.style.background=accent;e.currentTarget.style.color="#fff";}}
          onMouseLeave={function(e){e.currentTarget.style.background=accent+"15";e.currentTarget.style.color=accent;}}>
          + Nova pendência
        </button>
      </div>
      {(data.pendencias||[]).length===0
        ? <div style={{background:"#fafbfc",border:"1px dashed #e2e8f0",borderRadius:10,padding:"22px 14px",textAlign:"center",color:"#94a3b8",fontSize:12.5}}>Nenhuma pendência. Tudo no jeito.</div>
        : <div style={{display:"flex",flexDirection:"column",gap:6}}>
            {data.pendencias.map(function(p){
              const stColor = p.status==="resolvido" ? {bg:"#dcfce7",color:"#15803d",border:"#bbf7d0"} : {bg:"#fef3c7",color:"#a16207",border:"#fde68a"};
              return <div key={p.id} style={{display:"flex",alignItems:"center",gap:10,background:p.status==="resolvido"?"#fafbfc":"#fff",border:"1px solid #f1f5f9",borderRadius:10,padding:"9px 12px",opacity:p.status==="resolvido"?0.7:1}}>
                <input type="checkbox" checked={p.status==="resolvido"} onChange={function(){updatePendencia(p.id, "status", p.status==="resolvido"?"pendente":"resolvido");}}
                  style={{width:16,height:16,cursor:"pointer",accentColor:accent}}/>
                <input value={p.title||""} onChange={function(e){updatePendencia(p.id, "title", e.target.value);}} placeholder="O que está faltando do cliente..."
                  style={{flex:1,minWidth:0,background:"transparent",border:"none",outline:"none",color:"#0f172a",fontSize:13,fontWeight:600,fontFamily:FF,textDecoration:p.status==="resolvido"?"line-through":"none"}}/>
                <DateField value={p.date||""} onChange={function(v){updatePendencia(p.id, "date", v);}} placeholder="Sem prazo"/>
                <span style={{background:stColor.bg,color:stColor.color,border:"1px solid "+stColor.border,fontSize:9.5,fontWeight:800,padding:"3px 9px",borderRadius:99,letterSpacing:.3,textTransform:"uppercase",whiteSpace:"nowrap"}}>{p.status==="resolvido"?"Resolvido":"Pendente"}</span>
                <button onClick={function(){removePendencia(p.id);}} title="Remover pendência" style={{background:"transparent",border:"none",cursor:"pointer",color:"#94a3b8",padding:4,display:"inline-flex",alignItems:"center"}}>
                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
                </button>
              </div>;
            })}
          </div>
      }
    </div>

    <div style={_sectionCard()}>
      <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:12}}>
        {typeof Ico==="function" && <Ico n="target" size={16} color={accent}/>}
        <div style={{color:"#0f172a",fontWeight:800,fontSize:15,letterSpacing:-.2}}>Próximos eventos do cliente</div>
      </div>
      <div style={{display:"grid",gridTemplateColumns:isMob?"1fr":"repeat(3,1fr)",gap:12}}>
        <div>
          <div style={{color:"#64748b",fontSize:11,fontWeight:700,textTransform:"uppercase",letterSpacing:.5,marginBottom:5}}>Próximo planejamento mensal</div>
          <DateField size="md" value={data.proximos.planMensal||""} onChange={function(v){setProximoField("planMensal",v);}}/>
        </div>
        <div>
          <div style={{color:"#64748b",fontSize:11,fontWeight:700,textTransform:"uppercase",letterSpacing:.5,marginBottom:5}}>Próximo planejamento trimestral</div>
          <DateField size="md" value={data.proximos.planTrimestral||""} onChange={function(v){setProximoField("planTrimestral",v);}}/>
        </div>
        <div>
          <div style={{color:"#64748b",fontSize:11,fontWeight:700,textTransform:"uppercase",letterSpacing:.5,marginBottom:5}}>Próximo pedido de indicação</div>
          <DateField size="md" value={data.proximos.indicacao||""} onChange={function(v){setProximoField("indicacao",v);}}/>
        </div>
      </div>
    </div>

    {/* ── ATAS DAS REUNIÕES — histórico ── */}
    {(function(){
      function _addAta(){
        const newAta = {
          id: "ata_"+Date.now(),
          date: new Date().toISOString().slice(0,10),
          title: "",
          notes: "",
          participants: [],
          by: (typeof CURRENT_USER!=="undefined"?CURRENT_USER.id:""),
          createdAt: new Date().toISOString()
        };
        const next = Object.assign({}, data, {atas: [newAta, ...(data.atas||[])]});
        persist(next);
      }
      function _updAta(id, field, val){
        const next = Object.assign({}, data, {atas: (data.atas||[]).map(function(a){return a.id===id?Object.assign({},a,{[field]:val}):a;})});
        persist(next);
      }
      function _delAta(id){
        const next = Object.assign({}, data, {atas: (data.atas||[]).filter(function(a){return a.id!==id;})});
        persist(next);
      }
      function _togglePart(id, uid){
        const ata = (data.atas||[]).find(function(a){return a.id===id;});
        if(!ata) return;
        const cur = Array.isArray(ata.participants)?ata.participants:[];
        const next_parts = cur.indexOf(uid)>=0 ? cur.filter(function(x){return x!==uid;}) : cur.concat([uid]);
        _updAta(id, "participants", next_parts);
      }
      const atas = data.atas||[];
      const sorted = atas.slice().sort(function(a,b){return String(b.date||b.createdAt||"").localeCompare(String(a.date||a.createdAt||""));});
      return <div style={_sectionCard()}>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:10,marginBottom:14,flexWrap:"wrap"}}>
          <div style={{display:"flex",alignItems:"center",gap:8}}>
            {typeof Ico==="function" && <Ico n="fileText" size={16} color={accent}/>}
            <div style={{color:"#0f172a",fontWeight:800,fontSize:15,letterSpacing:-.2}}>Atas das reuniões</div>
            <span style={{background:"#f1f5f9",color:"#64748b",fontSize:10.5,fontWeight:700,padding:"2px 8px",borderRadius:99}}>{sorted.length} {sorted.length===1?"registrada":"registradas"}</span>
          </div>
          <button onClick={_addAta}
            style={{background:accent+"15",border:"1px solid "+accent+"33",borderRadius:9,padding:"7px 13px",color:accent,fontSize:12,fontWeight:700,cursor:"pointer",fontFamily:FF,display:"inline-flex",alignItems:"center",gap:6,transition:"all .15s"}}
            onMouseEnter={function(e){e.currentTarget.style.background=accent;e.currentTarget.style.color="#fff";}}
            onMouseLeave={function(e){e.currentTarget.style.background=accent+"15";e.currentTarget.style.color=accent;}}>
            + Nova ata
          </button>
        </div>
        {sorted.length===0
          ? <div style={{background:"#fafbfc",border:"1px dashed #e2e8f0",borderRadius:10,padding:"30px 20px",textAlign:"center",display:"flex",flexDirection:"column",alignItems:"center",gap:8}}>
              <div style={{width:46,height:46,borderRadius:"50%",background:"#fff",display:"flex",alignItems:"center",justifyContent:"center",color:"#cbd5e1"}}>
                {typeof Ico==="function" && <Ico n="fileText" size={20} color="#cbd5e1"/>}
              </div>
              <div style={{color:"#0f172a",fontSize:13,fontWeight:700,letterSpacing:-.2}}>Nenhuma ata registrada ainda</div>
              <div style={{color:"#94a3b8",fontSize:11.5,fontWeight:500,maxWidth:380,lineHeight:1.5}}>Use "+ Nova ata" depois de cada reunião pra registrar decisões, encaminhamentos e participantes. O histórico aparece aqui.</div>
            </div>
          : <div style={{display:"flex",flexDirection:"column",gap:11}}>
              {sorted.map(function(ata){
                const dataFmtBR = ata.date ? (ata.date.slice(8,10)+"/"+ata.date.slice(5,7)+"/"+ata.date.slice(0,4)) : "—";
                const participants = Array.isArray(ata.participants)?ata.participants:[];
                return <div key={ata.id} style={{background:"#fff",border:"1px solid #eef0f3",borderRadius:12,padding:"14px 16px",display:"flex",flexDirection:"column",gap:10}}>
                  {/* Header: data + título + delete */}
                  <div style={{display:"flex",alignItems:"center",gap:10,flexWrap:"wrap"}}>
                    <DateField value={ata.date||""} onChange={function(v){_updAta(ata.id,"date",v);}}/>
                    <input value={ata.title||""} onChange={function(e){_updAta(ata.id,"title",e.target.value);}} placeholder="Título da reunião (ex: Planejamento de junho)"
                      style={{flex:1,minWidth:200,background:"transparent",border:"none",outline:"none",color:"#0f172a",fontSize:14.5,fontWeight:800,letterSpacing:-.2,fontFamily:FF}}/>
                    <button onClick={function(){if(window.confirm("Apagar essa ata?")) _delAta(ata.id);}} title="Apagar ata"
                      style={{background:"transparent",border:"none",cursor:"pointer",color:"#94a3b8",padding:6,borderRadius:6,display:"inline-flex",alignItems:"center"}}
                      onMouseEnter={function(e){e.currentTarget.style.color="#dc2626";e.currentTarget.style.background="#fef2f2";}}
                      onMouseLeave={function(e){e.currentTarget.style.color="#94a3b8";e.currentTarget.style.background="transparent";}}>
                      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14a2 2 0 01-2 2H8a2 2 0 01-2-2L5 6"/><path d="M10 11v6"/><path d="M14 11v6"/></svg>
                    </button>
                  </div>

                  {/* Participantes */}
                  <div style={{display:"flex",alignItems:"center",gap:9,flexWrap:"wrap"}}>
                    <span style={{color:"#94a3b8",fontSize:9.5,fontWeight:800,textTransform:"uppercase",letterSpacing:.6}}>Participantes</span>
                    <div style={{display:"inline-flex",gap:5,alignItems:"center"}}>
                      {TEAM_OPTS.map(function(u){
                        const active = participants.indexOf(u.id)>=0;
                        const photo = (u.profile_data && u.profile_data.photo) || ((typeof getProfilePhoto!=="undefined" && getProfilePhoto(u.id))||null);
                        const ini = (u.av||(u.name||"?")[0]||"?").toUpperCase();
                        const sz = 24;
                        return <button key={u.id} type="button" title={u.name}
                          onClick={function(){_togglePart(ata.id, u.id);}}
                          style={{background:"transparent",border:"none",padding:0,cursor:"pointer",borderRadius:"50%",lineHeight:0,transition:"all .12s",transform:active?"scale(1.0)":"scale(.9)",opacity:active?1:0.45,filter:active?"none":"grayscale(.6)"}}
                          onMouseEnter={function(e){e.currentTarget.style.transform="scale(1.05)";e.currentTarget.style.opacity=1;e.currentTarget.style.filter="none";}}
                          onMouseLeave={function(e){e.currentTarget.style.transform=active?"scale(1.0)":"scale(.9)";e.currentTarget.style.opacity=active?1:0.45;e.currentTarget.style.filter=active?"none":"grayscale(.6)";}}>
                          {photo
                            ? <img src={photo} alt={u.name} style={{width:sz,height:sz,borderRadius:"50%",objectFit:"cover",display:"block",boxShadow:active?"0 0 0 2.5px "+(u.color||accent):"0 0 0 1.5px #e2e8f0"}}/>
                            : <span style={{display:"inline-flex",width:sz,height:sz,borderRadius:"50%",background:u.color||"#94a3b8",color:"#fff",alignItems:"center",justifyContent:"center",fontWeight:800,fontSize:Math.floor(sz*0.42),fontFamily:FF,boxShadow:active?"0 0 0 2.5px "+(u.color||accent):"0 0 0 1.5px #e2e8f0"}}>{ini}</span>}
                        </button>;
                      })}
                    </div>
                  </div>

                  {/* Notas */}
                  <textarea value={ata.notes||""} onChange={function(e){_updAta(ata.id,"notes",e.target.value);}} placeholder="Decisões, encaminhamentos, próximos passos..."
                    rows={3}
                    style={{width:"100%",boxSizing:"border-box",background:"#fafbfc",border:"1px solid #f1f5f9",borderRadius:10,padding:"10px 12px",fontSize:13,color:"#0f172a",outline:"none",fontFamily:FF,resize:"vertical",lineHeight:1.55}}/>
                </div>;
              })}
            </div>
        }
      </div>;
    })()}

    {/* Os scripts sairam daqui em 08/2026 — vivem na aba Scripts (CScriptsTab). */}

  </div>;
}

function ChecklistRow({item, it, st, accent, teamOpts, onToggle, onResp, onDue, RespAvatars, DateField}){
  const FF = "'Inter',system-ui,-apple-system,sans-serif";
  return <div style={{display:"flex",alignItems:"center",gap:12,background:it.done?"#fafbfc":"#fff",border:"1px solid #f1f5f9",borderRadius:10,padding:"10px 14px",opacity:it.done?0.75:1,transition:"all .15s",flexWrap:"wrap"}}>
    <input type="checkbox" checked={!!it.done} onChange={onToggle}
      style={{width:17,height:17,cursor:"pointer",accentColor:accent,flexShrink:0}}/>
    <span style={{flex:1,minWidth:200,color:"#0f172a",fontSize:13,fontWeight:600,textDecoration:it.done?"line-through":"none",overflow:"hidden",textOverflow:"ellipsis",fontFamily:FF}}>{item.label}</span>
    {RespAvatars ? <RespAvatars value={it.resp||""} onChange={function(v){onResp(v);}}/> : null}
    {DateField  ? <DateField  value={it.due||""}  onChange={function(v){onDue(v);}} placeholder="Sem prazo"/> : null}
    <span style={{background:st.bg,color:st.color,border:"1px solid "+st.border,fontSize:9.5,fontWeight:800,padding:"3px 9px",borderRadius:99,letterSpacing:.3,textTransform:"uppercase",whiteSpace:"nowrap",flexShrink:0}}>{st.label}</span>
  </div>;
}

/* ── DRIVE (Info) ────────────────────────── */
function CDrive({cl}){
  let[driveUrl,setDriveUrl]=useState(function(){
    try{let s=localStorage.getItem("pixels-drive-"+cl.id);if(s)return s;}catch(e){}
    return cl.driveUrl||"";
  });
  let[editing,setEditing]=useState(!driveUrl);
  let[saved,setSaved]=useState(false);

  let save=function(){
    cl.driveUrl=driveUrl.trim();
    try{localStorage.setItem("pixels-drive-"+cl.id,driveUrl.trim());setSaved(true);setTimeout(()=>setSaved(false),2000);setEditing(false);}catch(e){}
  };

  let inp={background:C.s1,border:"1px solid "+C.b1,borderRadius:10,padding:"9px 12px",color:C.tx,fontSize:12,outline:"none",width:"100%",boxSizing:"border-box",fontFamily:"inherit"};

  return(<div style={{display:"flex",flexDirection:"column",gap:14}}>
    <div style={{background:C.card,borderRadius:16,border:"1px solid "+C.b1,overflow:"hidden"}}>
      <div style={{padding:"14px 18px",borderBottom:"1px solid "+C.b1,display:"flex",alignItems:"center",justifyContent:"space-between"}}>
        <div style={{display:"flex",alignItems:"center",gap:8}}>
          <svg width="18" height="18" viewBox="0 0 87.3 78" xmlns="http://www.w3.org/2000/svg"><path d="m6.6 66.85 3.85 6.65c.8 1.4 1.95 2.5 3.3 3.3l13.75-23.8h-27.5c0 1.55.4 3.1 1.2 4.5z" fill="#0066da"/><path d="m43.65 25-13.75-23.8c-1.35.8-2.5 1.9-3.3 3.3l-25.4 44a9.06 9.06 0 0 0 -1.2 4.5h27.5z" fill="#00ac47"/><path d="m73.55 76.8c1.35-.8 2.5-1.9 3.3-3.3l1.6-2.75 7.65-13.25c.8-1.4 1.2-2.95 1.2-4.5h-27.502l5.852 11.5z" fill="#ea4335"/><path d="m43.65 25 13.75-23.8c-1.35-.8-2.9-1.2-4.5-1.2h-18.5c-1.6 0-3.15.45-4.5 1.2z" fill="#00832d"/><path d="m59.8 53h-32.3l-13.75 23.8c1.35.8 2.9 1.2 4.5 1.2h50.8c1.6 0 3.15-.45 4.5-1.2z" fill="#2684fc"/><path d="m73.4 26.5-12.7-22c-.8-1.4-1.95-2.5-3.3-3.3l-13.75 23.8 16.15 28h27.45c0-1.55-.4-3.1-1.2-4.5z" fill="#ffba00"/></svg>
          <div style={{color:C.tx,fontWeight:700,fontSize:13}}>Pasta no Google Drive</div>
        </div>
        <div style={{display:"flex",gap:6}}>
          {!editing&&driveUrl&&<button onClick={()=>setEditing(true)} style={{background:C.s1,border:"1px solid "+C.b1,borderRadius:8,padding:"5px 12px",color:C.ts,fontSize:11,cursor:"pointer"}}>Editar</button>}
          {!editing&&driveUrl&&<a href={driveUrl} target="_blank" rel="noopener" style={{background:"#1a73e8",color:"#fff",borderRadius:8,padding:"5px 14px",fontSize:11,fontWeight:700,textDecoration:"none"}}>Abrir →</a>}
        </div>
      </div>
      <div style={{padding:"16px 18px"}}>
        {editing?(<div style={{display:"flex",flexDirection:"column",gap:10}}>
          <div style={{color:C.ts,fontSize:11}}>Cole o link da pasta compartilhada do Google Drive para este cliente.</div>
          <div style={{display:"flex",gap:8}}>
            <input value={driveUrl} onChange={e=>setDriveUrl(e.target.value)} placeholder="https://drive.google.com/drive/folders/..." style={inp}/>
            <button onClick={save} disabled={!driveUrl.trim()}
              style={{background:driveUrl.trim()?"#1a73e8":C.b1,color:driveUrl.trim()?"#fff":C.td,border:"none",borderRadius:10,padding:"9px 18px",fontWeight:700,fontSize:12,cursor:driveUrl.trim()?"pointer":"not-allowed",whiteSpace:"nowrap"}}>
              {saved?"✓ Salvo!":"Salvar"}
            </button>
            {driveUrl&&<button onClick={()=>setEditing(false)} style={{background:C.s1,border:"1px solid "+C.b1,borderRadius:10,padding:"9px 12px",color:C.ts,fontSize:12,cursor:"pointer"}}>Cancelar</button>}
          </div>
        </div>):driveUrl?(<div style={{display:"flex",alignItems:"center",gap:10,background:C.s1,borderRadius:10,padding:"10px 14px"}}>
          <svg width="16" height="16" viewBox="0 0 87.3 78" xmlns="http://www.w3.org/2000/svg"><path d="m6.6 66.85 3.85 6.65c.8 1.4 1.95 2.5 3.3 3.3l13.75-23.8h-27.5c0 1.55.4 3.1 1.2 4.5z" fill="#0066da"/><path d="m43.65 25-13.75-23.8c-1.35.8-2.5 1.9-3.3 3.3l-25.4 44a9.06 9.06 0 0 0 -1.2 4.5h27.5z" fill="#00ac47"/><path d="m73.55 76.8c1.35-.8 2.5-1.9 3.3-3.3l1.6-2.75 7.65-13.25c.8-1.4 1.2-2.95 1.2-4.5h-27.502l5.852 11.5z" fill="#ea4335"/><path d="m43.65 25 13.75-23.8c-1.35-.8-2.9-1.2-4.5-1.2h-18.5c-1.6 0-3.15.45-4.5 1.2z" fill="#00832d"/><path d="m59.8 53h-32.3l-13.75 23.8c1.35.8 2.9 1.2 4.5 1.2h50.8c1.6 0 3.15-.45 4.5-1.2z" fill="#2684fc"/><path d="m73.4 26.5-12.7-22c-.8-1.4-1.95-2.5-3.3-3.3l-13.75 23.8 16.15 28h27.45c0-1.55-.4-3.1-1.2-4.5z" fill="#ffba00"/></svg>
          <div style={{flex:1,minWidth:0}}>
            <div style={{color:C.tx,fontSize:12,fontWeight:600}}>Pasta configurada</div>
            <div style={{color:C.td,fontSize:10,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{driveUrl}</div>
          </div>
          <span style={{color:C.gr,fontSize:14}}>✓</span>
        </div>):(<div style={{textAlign:"center",padding:"20px 0",color:C.td,fontSize:12}}>
          Nenhuma pasta configurada.
          <button onClick={()=>setEditing(true)} style={{display:"block",margin:"8px auto 0",background:C.s1,border:"1px solid "+C.b1,borderRadius:8,padding:"6px 14px",color:C.ts,fontSize:11,cursor:"pointer"}}>+ Configurar</button>
        </div>)}
      </div>
    </div>

    {/* Dados cadastrais */}
    <div style={{background:C.card,borderRadius:14,border:"1px solid "+C.b1,overflow:"hidden"}}>
      <div style={{padding:"12px 18px",borderBottom:"1px solid "+C.b1,color:C.tx,fontWeight:700,fontSize:13}}>Dados Cadastrais</div>
      <div style={{display:"grid",gridTemplateColumns:_pxMob()?"1fr":"1fr 1fr"}}>
        {[{l:"Setor",v:cl.sector},{l:"Status",v:cl.status},{l:"Na Pixels desde",v:cl.since||"—"},{l:"Gestor",v:(TEAM.find(function(u){return u.id===cl.manager;})||{}).name||cl.manager},{l:"MRR",v:"R$ "+cl.contract.toLocaleString("pt-BR")},{l:"NPS",v:(cl.nps||0)+"/100"},{l:"Meta Account ID",v:cl.metaId||"—"},{l:"Google Account ID",v:cl.googleId||"—"}].map(function(r,i){
          return(<div key={r.l} style={{padding:"11px 18px",borderBottom:i<6?"1px solid "+C.b1:"none",borderRight:i%2===0?"1px solid "+C.b1:"none"}}>
            <div style={{color:C.td,fontSize:10,marginBottom:3}}>{r.l}</div>
            <div style={{color:C.tx,fontSize:13,fontWeight:600}}>{r.v}</div>
          </div>);
        })}
      </div>
    </div>
  </div>);
}

