// Contratos por grupo econômico
// Estado padrão dos contratos — usado como seed se não houver dados salvos.
// IMPORTANTE: campo `pagDia` (dia do vencimento) por contrato/unidade.
// Campos de cobranca (envios[], contatoNome/Email/Whats) sao preenchidos pelo modal.
const GF_CONTRATOS_DEFAULT = [
  {
    grupo:"Bioter", grupoEcon:true, cor:"#166534", clientId:"bioter",
    unidades:[
      {nome:"Chapecó",            valor:3000, unitId:"chapeco",    pagDia:5},
      {nome:"Toledo",             valor:2000, unitId:"toledo",     pagDia:5},
      {nome:"Castro",             valor:2500, unitId:"castro",     pagDia:5},
      {nome:"Glória de Dourados", valor:500,  unitId:"gloria",     pagDia:5},
      {nome:"Uberlândia",         valor:500,  unitId:"uberlandia", pagDia:5},
      {nome:"Paraguay",           valor:0,    unitId:"paraguay",   pagDia:5},
    ],
  },
  {grupo:"Construschorr",        cor:"#dc2626", valor:4000, clientId:"construschorr", pagDia:10},
  {grupo:"Arabutã Pré-Moldados", cor:"#d97706", valor:4500, clientId:"arabuta",       pagDia:10},
  {grupo:"Climaves",             cor:"#0284c7", valor:2500, clientId:"climaves",      pagDia:10},
];

// Puxa TODO cliente ativo que ainda não está na lista de contratos.
// Antes o seed era fixo: cliente novo (Acreforte, VetService, Lero, Clem…)
// nunca aparecia em "Contratos ativos" e ficava fora do MRR. Agora a lista
// se completa sozinha — o valor entra como 0 ("definir valor") até alguém
// abrir o card e preencher. Quem foi arquivado à mão não volta (_gfArquivados).
function _gfArquivados(){
  try{
    const raw=typeof localStorage!=="undefined"?localStorage.getItem("pixels-contratos-arquivados"):null;
    const arr=raw?JSON.parse(raw):[];
    return Array.isArray(arr)?arr.map(function(x){return String(x).toLowerCase();}):[];
  }catch(_){return [];}
}
function _gfMergeClientesAtivos(lista){
  const arr=Array.isArray(lista)?lista.slice():[];
  try{
    if(typeof CLIENTS==="undefined"||!Array.isArray(CLIENTS))return arr;
    const jaTem={};
    arr.forEach(function(c){ if(c&&c.clientId) jaTem[String(c.clientId).toLowerCase()]=true; });
    const fora=_gfArquivados();
    CLIENTS.forEach(function(cl){
      if(!cl||!cl.id)return;
      if(cl.id==="pixels")return;                                   // a própria agência
      if(cl.status&&cl.status!=="ativo")return;                     // pausado/encerrado/interno
      const id=String(cl.id).toLowerCase();
      if(jaTem[id]||fora.indexOf(id)>=0)return;
      arr.push({
        grupo: cl.name||cl.id,
        cor: cl.color||"#7c3aed",
        valor: Number(cl.contract)||0,
        clientId: cl.id,
        pagDia: 10,
        _auto: true,   // entrou sozinho: valor ainda precisa ser conferido
      });
    });
  }catch(_){}
  return arr;
}
// Carrega contratos do localStorage com merge dos campos novos (pagDia, envios, contato) sobre o seed.
function _gfLoadContratos(){
  try{
    const raw=typeof localStorage!=="undefined"?localStorage.getItem("pixels-contratos-ativos"):null;
    if(!raw)return _gfMergeClientesAtivos(GF_CONTRATOS_DEFAULT);
    const parsed=JSON.parse(raw);
    if(!Array.isArray(parsed)||parsed.length===0)return _gfMergeClientesAtivos(GF_CONTRATOS_DEFAULT);
    return _gfMergeClientesAtivos(parsed);
  }catch(_){return _gfMergeClientesAtivos(GF_CONTRATOS_DEFAULT);}
}
function _gfSaveContratos(arr){
  try{
    if(typeof localStorage!=="undefined")localStorage.setItem("pixels-contratos-ativos",JSON.stringify(arr||[]));
    // Espelha por client_id pra o Portal Cliente ROI ler como default de pixels_service
    const flat={};
    (arr||[]).forEach(function(c){
      if(c.grupoEcon&&Array.isArray(c.unidades)){
        c.unidades.forEach(function(u){
          if(c.clientId&&u.unitId)flat[c.clientId+"_"+u.unitId]={valor:u.valor||0,pagDia:u.pagDia||c.pagDia||5};
        });
      } else if(c.clientId){
        flat[c.clientId]={valor:c.valor||0,pagDia:c.pagDia||5};
      }
    });
    if(typeof localStorage!=="undefined")localStorage.setItem("pixels-contratos-ativos-flat",JSON.stringify(flat));
    // Supabase: a fonte única agora é client_contracts (02b_contratos_core) — gravada por _updateContratos.
  }catch(_){}
}

