const GF_RESERVA_CAIXA_PCT = 0.10;

// Meta de margem (configurável)
const GF_META_MARGEM_PCT = 0.50;

// Componente de lista editável de custos — usado pra Custo Fixo e Custo Servir
function _CustosEditableList({state, accent, isSocio, brl, isMob}){
  const [editingId, setEditingId] = useState(null);
  const [editDraft, setEditDraft] = useState({label:"",valor:""});
  const [addingCat, setAddingCat] = useState(null); // categoria onde vai adicionar
  const [addDraft, setAddDraft] = useState({label:"",valor:""});
  const [newCatOpen, setNewCatOpen] = useState(false);
  const [newCatName, setNewCatName] = useState("");
  const _addLabelRef = useRef(null);
  const custos = state.custos||[];
  // Agrupa por categoria, ordena itens DENTRO por valor decrescente,
  // e ordena CATEGORIAS por soma total decrescente (a mais cara vai pro topo).
  // Usa array explicito de {cat, sum, items} pra garantir ordem estavel no React.
  const _catMap = {};
  custos.forEach(function(c){
    if(!_catMap[c.categoria]){ _catMap[c.categoria]=[]; }
    _catMap[c.categoria].push(c);
  });
  const _catEntries = Object.keys(_catMap).map(function(cat){
    const items = _catMap[cat].slice().sort(function(a,b){ return Number(b.valor||0) - Number(a.valor||0); });
    const sum = items.reduce(function(s,it){return s+Number(it.valor||0);},0);
    return {cat: cat, items: items, sum: sum};
  });
  _catEntries.sort(function(a,b){ return b.sum - a.sum; });
  const cats = _catEntries.map(function(e){return e.cat;});
  const catMap = {};
  _catEntries.forEach(function(e){ catMap[e.cat] = e.items; });

  function _startEdit(item){
    setEditingId(item.id);
    setEditDraft({label:item.label, valor:String(item.valor)});
  }
  function _saveEdit(item){
    const patch={label:editDraft.label.trim(), valor:Number(editDraft.valor)||0};
    if(!patch.label) return;
    state.updateItem(item.id, patch);
    setEditingId(null);
  }
  function _startAdd(cat){
    setAddingCat(cat);
    setAddDraft({label:"",valor:""});
  }
  function _saveAdd(continueMode){
    if(!addDraft.label.trim()) return;
    const _catAtual = addingCat;
    state.addItem(addingCat, addDraft.label.trim(), Number(addDraft.valor)||0);
    setAddDraft({label:"",valor:""});
    if(continueMode){
      // Mantem aberto pra criar proximo item da mesma categoria + refoca no label
      setAddingCat(_catAtual);
      setTimeout(function(){ if(_addLabelRef.current) _addLabelRef.current.focus(); }, 0);
    } else {
      setAddingCat(null);
    }
  }
  function _saveNewCat(continueMode){
    if(!newCatName.trim() || !addDraft.label.trim()) return;
    const _novaCat = newCatName.trim();
    state.addItem(_novaCat, addDraft.label.trim(), Number(addDraft.valor)||0);
    setAddDraft({label:"",valor:""});
    setNewCatOpen(false);
    setNewCatName("");
    if(continueMode){
      // Abre input de "adicionar item" na categoria recem-criada
      setAddingCat(_novaCat);
      setTimeout(function(){ if(_addLabelRef.current) _addLabelRef.current.focus(); }, 0);
    }
  }

  return <div style={{display:"flex",flexDirection:"column",gap:12}}>
    {cats.map(function(cat){
      const items = catMap[cat];
      const subtotal = items.reduce(function(s,it){return s+Number(it.valor||0);},0);
      return <div key={cat}>
        <div style={{display:"flex",alignItems:"baseline",justifyContent:"space-between",gap:8,marginBottom:5,paddingBottom:3,borderBottom:"1px solid "+accent+"22"}}>
          <div style={{color:accent,fontWeight:700,fontSize:10,letterSpacing:.5,textTransform:"uppercase",display:"flex",alignItems:"center",gap:6}}>
            {cat}
            {isSocio && <button type="button" onClick={function(){_startAdd(cat);}} title="Adicionar item nesta categoria"
              style={{background:"transparent",border:"none",color:accent,cursor:"pointer",padding:"1px 4px",borderRadius:5,fontSize:14,lineHeight:1,opacity:.55,transition:"opacity .12s"}}
              onMouseEnter={function(e){e.currentTarget.style.opacity=1;}}
              onMouseLeave={function(e){e.currentTarget.style.opacity=.55;}}>+</button>}
          </div>
          <div style={{color:"#94a3b8",fontWeight:600,fontSize:10.5,fontFeatureSettings:"'tnum'"}}>{brl(subtotal)}</div>
        </div>
        <div style={{display:"flex",flexDirection:"column"}}>
          {items.map(function(it,i){
            const isEditing = editingId===it.id;
            if(isEditing){
              return <div key={it.id} style={{display:"flex",alignItems:"center",gap:6,padding:"5px 0",borderBottom:i<items.length-1?"1px dashed #f1f5f9":"none"}}>
                <input value={editDraft.label} onChange={function(e){setEditDraft(Object.assign({},editDraft,{label:e.target.value}));}}
                  onKeyDown={function(e){if(e.key==="Enter")_saveEdit(it); if(e.key==="Escape")setEditingId(null);}}
                  style={{flex:1,border:"1px solid "+accent+"55",borderRadius:6,padding:"4px 8px",fontSize:12,outline:"none",fontFamily:"inherit"}}/>
                <input value={editDraft.valor} onChange={function(e){setEditDraft(Object.assign({},editDraft,{valor:e.target.value}));}}
                  onKeyDown={function(e){if(e.key==="Enter")_saveEdit(it); if(e.key==="Escape")setEditingId(null);}}
                  type="number" inputMode="decimal" step="0.01"
                  style={{width:80,border:"1px solid "+accent+"55",borderRadius:6,padding:"4px 8px",fontSize:12,outline:"none",fontFamily:"inherit",fontFeatureSettings:"'tnum'",textAlign:"right"}}/>
                <button type="button" onClick={function(){_saveEdit(it);}} style={{background:accent,color:"#fff",border:"none",borderRadius:6,padding:"4px 8px",fontSize:11,fontWeight:700,cursor:"pointer"}}>OK</button>
                <button type="button" onClick={function(){setEditingId(null);}} style={{background:"#fff",color:"#94a3b8",border:"1px solid #e2e8f0",borderRadius:6,padding:"4px 8px",fontSize:11,fontWeight:600,cursor:"pointer"}}>×</button>
              </div>;
            }
            return <div key={it.id} style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"4px 0",borderBottom:i<items.length-1?"1px dashed #f1f5f9":"none",gap:6}}>
              {isSocio
                ? <input value={it.label} onChange={function(e){state.updateItem(it.id,{label:e.target.value});}}
                    title="Clique pra editar"
                    style={{flex:1,minWidth:0,background:"#fff",border:"1px solid #e2e8f0",borderRadius:6,padding:"5px 8px",fontSize:12.5,fontWeight:500,color:"#475569",fontFamily:"inherit",outline:"none",transition:"all .12s"}}
                    onMouseEnter={function(e){if(document.activeElement!==e.currentTarget) e.currentTarget.style.borderColor=accent+"66";}}
                    onMouseLeave={function(e){if(document.activeElement!==e.currentTarget) e.currentTarget.style.borderColor="#e2e8f0";}}
                    onFocus={function(e){e.currentTarget.style.borderColor=accent;e.currentTarget.style.background=accent+"08";}}
                    onBlur={function(e){e.currentTarget.style.borderColor="#e2e8f0";e.currentTarget.style.background="#fff";}}/>
                : <span style={{color:"#475569",fontSize:12.5,fontWeight:500,flex:1,minWidth:0,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{it.label}</span>}
              {isSocio
                ? <input value={it.valor} onChange={function(e){state.updateItem(it.id,{valor:Number(e.target.value)||0});}} type="number" inputMode="decimal" step="0.01"
                    title="Clique pra editar valor"
                    style={{width:110,background:"#fff",border:"1px solid #e2e8f0",borderRadius:6,padding:"5px 8px",fontSize:13,fontWeight:700,color:"#0f172a",fontFamily:"inherit",fontFeatureSettings:"'tnum'",textAlign:"right",outline:"none",transition:"all .12s"}}
                    onMouseEnter={function(e){if(document.activeElement!==e.currentTarget) e.currentTarget.style.borderColor=accent+"66";}}
                    onMouseLeave={function(e){if(document.activeElement!==e.currentTarget) e.currentTarget.style.borderColor="#e2e8f0";}}
                    onFocus={function(e){e.currentTarget.style.borderColor=accent;e.currentTarget.style.background=accent+"08";}}
                    onBlur={function(e){e.currentTarget.style.borderColor="#e2e8f0";e.currentTarget.style.background="#fff";}}/>
                : <span style={{color:"#0f172a",fontSize:12.5,fontWeight:600,fontFeatureSettings:"'tnum'",flexShrink:0}}>{brl(it.valor)}</span>}
              {isSocio && <button type="button" onClick={async function(){if(await pixelsConfirm("Excluir "+it.label+"?",{okText:"Excluir",danger:true})) state.removeItem(it.id);}} title="Excluir" style={{background:"transparent",border:"none",cursor:"pointer",color:"#cbd5e1",padding:"3px 5px",borderRadius:4,flexShrink:0,transition:"color .12s"}}
                onMouseEnter={function(e){e.currentTarget.style.color="#dc2626";}}
                onMouseLeave={function(e){e.currentTarget.style.color="#cbd5e1";}}>
                <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.3" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/><path d="M10 11v6M14 11v6"/></svg>
              </button>}
            </div>;
          })}
          {addingCat===cat && <div style={{display:"flex",alignItems:"center",gap:6,padding:"5px 0",borderTop:"1px dashed "+accent+"33"}}>
            <input ref={_addLabelRef} value={addDraft.label} onChange={function(e){setAddDraft(Object.assign({},addDraft,{label:e.target.value}));}}
              onKeyDown={function(e){if(e.key==="Enter")_saveAdd(true); if(e.key==="Escape")setAddingCat(null);}}
              placeholder="Nome do item" autoFocus
              style={{flex:1,border:"1px solid "+accent+"55",borderRadius:6,padding:"4px 8px",fontSize:12,outline:"none",fontFamily:"inherit"}}/>
            <input value={addDraft.valor} onChange={function(e){setAddDraft(Object.assign({},addDraft,{valor:e.target.value}));}}
              onKeyDown={function(e){if(e.key==="Enter")_saveAdd(true); if(e.key==="Escape")setAddingCat(null);}}
              type="number" inputMode="decimal" step="0.01" placeholder="0"
              style={{width:80,border:"1px solid "+accent+"55",borderRadius:6,padding:"4px 8px",fontSize:12,outline:"none",fontFamily:"inherit",fontFeatureSettings:"'tnum'",textAlign:"right"}}/>
            <button type="button" onClick={function(){_saveAdd(false);}} title="Salvar e fechar" style={{background:accent,color:"#fff",border:"none",borderRadius:6,padding:"4px 8px",fontSize:11,fontWeight:700,cursor:"pointer"}}>+</button>
            <button type="button" onClick={function(){setAddingCat(null);}} style={{background:"#fff",color:"#94a3b8",border:"1px solid #e2e8f0",borderRadius:6,padding:"4px 8px",fontSize:11,fontWeight:600,cursor:"pointer"}}>×</button>
          </div>}
        </div>
      </div>;
    })}
    {isSocio && <div style={{paddingTop:8,borderTop:"1px solid #f1f5f9"}}>
      {newCatOpen ? (
        <div style={{display:"flex",flexDirection:"column",gap:6,padding:"6px 0"}}>
          <input value={newCatName} onChange={function(e){setNewCatName(e.target.value);}}
            onKeyDown={function(e){if(e.key==="Enter")_saveNewCat(true); if(e.key==="Escape"){setNewCatOpen(false);setNewCatName("");}}}
            placeholder="Nome da categoria (ex: Marketing)" autoFocus
            style={{border:"1px solid "+accent+"55",borderRadius:6,padding:"5px 8px",fontSize:12,outline:"none",fontFamily:"inherit"}}/>
          <div style={{display:"flex",gap:6}}>
            <input value={addDraft.label} onChange={function(e){setAddDraft(Object.assign({},addDraft,{label:e.target.value}));}}
              onKeyDown={function(e){if(e.key==="Enter")_saveNewCat(true); if(e.key==="Escape"){setNewCatOpen(false);setNewCatName("");}}}
              placeholder="Primeiro item"
              style={{flex:1,border:"1px solid "+accent+"55",borderRadius:6,padding:"5px 8px",fontSize:12,outline:"none",fontFamily:"inherit"}}/>
            <input value={addDraft.valor} onChange={function(e){setAddDraft(Object.assign({},addDraft,{valor:e.target.value}));}}
              onKeyDown={function(e){if(e.key==="Enter")_saveNewCat(true); if(e.key==="Escape"){setNewCatOpen(false);setNewCatName("");}}}
              type="number" inputMode="decimal" step="0.01" placeholder="0"
              style={{width:80,border:"1px solid "+accent+"55",borderRadius:6,padding:"5px 8px",fontSize:12,outline:"none",fontFamily:"inherit",fontFeatureSettings:"'tnum'",textAlign:"right"}}/>
            <button type="button" onClick={function(){_saveNewCat(false);}} style={{background:accent,color:"#fff",border:"none",borderRadius:6,padding:"5px 12px",fontSize:11,fontWeight:700,cursor:"pointer"}}>Criar</button>
            <button type="button" onClick={function(){setNewCatOpen(false);setNewCatName("");}} style={{background:"#fff",color:"#94a3b8",border:"1px solid #e2e8f0",borderRadius:6,padding:"5px 10px",fontSize:11,fontWeight:600,cursor:"pointer"}}>×</button>
          </div>
        </div>
      ) : (
        <button type="button" onClick={function(){setNewCatOpen(true);setAddDraft({label:"",valor:""});}}
          style={{background:accent+"08",color:accent,border:"1px dashed "+accent+"55",borderRadius:8,padding:"7px 12px",fontSize:11.5,fontWeight:700,cursor:"pointer",fontFamily:"inherit",width:"100%",display:"flex",alignItems:"center",justifyContent:"center",gap:5}}
          onMouseEnter={function(e){e.currentTarget.style.background=accent+"12";}}
          onMouseLeave={function(e){e.currentTarget.style.background=accent+"08";}}>+ Nova categoria</button>
      )}
    </div>}
    {state.loading && <div style={{color:"#94a3b8",fontSize:11,textAlign:"center",padding:8}}>Carregando…</div>}
  </div>;
}

