// Hook que carrega custos editáveis do Supabase (fallback pros defaults).
// Retorna {custos, addItem, updateItem, removeItem, addCategoria, loading}
function _useCustos(tipo, refMonth){
  const _DEFAULT = tipo==="fixo" ? _CUSTOS_DEFAULT_FIXO : _CUSTOS_DEFAULT_SERVIR;
  // Chave por mês (fallback pra chave sem mês pra backward compat)
  const _key = refMonth ? ("pixels-custos-"+tipo+"-"+refMonth) : ("pixels-custos-"+tipo);
  const _keyLegacy = "pixels-custos-"+tipo;
  // Walk-back: procura o mês mais recente que tem dados (pra herdar)
  function _findInherited(){
    if(!refMonth) return null;
    try{
      const p=refMonth.split("-"); let y=parseInt(p[0],10), m=parseInt(p[1],10);
      // Vai voltando até 12 meses
      for(let i=0;i<12;i++){
        m-=1; if(m<1){m=12;y-=1;}
        const yk=y+"-"+String(m).padStart(2,"0");
        const s=localStorage.getItem("pixels-custos-"+tipo+"-"+yk);
        if(s) return JSON.parse(s);
      }
    }catch(_){}
    return null;
  }
  const [custos, setCustos] = useState(function(){
    try{ const cached=localStorage.getItem(_key); if(cached) return JSON.parse(cached); }catch(_){}
    // Herda do mês anterior mais recente
    const inherited = _findInherited();
    if(inherited) return inherited;
    // Ou usa dados atuais (backward compat)
    if(refMonth){ try{ const s=localStorage.getItem(_keyLegacy); if(s) return JSON.parse(s); }catch(_){} }
    return _DEFAULT.map(function(x,i){ return Object.assign({id:"local-"+i}, x); });
  });
  const [loading, setLoading] = useState(false);

  // Reload quando muda refMonth
  // Estratégia: cache local do mês → walk-back local → Supabase (fonte da verdade global) → defaults
  useEffect(function(){
    let alive=true;
    async function _reload(){
      try{
        // 1) Cache do mês corrente selecionado
        const cached=localStorage.getItem(_key);
        if(cached){ setCustos(JSON.parse(cached)); return; }
        // 2) Walk-back nos meses anteriores (localStorage)
        const inherited = _findInherited();
        if(inherited){ setCustos(inherited); return; }
        // 3) Fallback Supabase: pra qualquer mês (inclusive futuros), busca o template atual
        //    Assim o mês novo herda os itens/valores atuais em vez de cair nos defaults hardcoded.
        try{
          const sb=window._sb;
          if(sb){
            const {data,error}=await sb.from("pixels_custos_editaveis").select("*").eq("tipo",tipo).order("ordem",{ascending:true});
            if(!error && alive && Array.isArray(data) && data.length>0){
              // Copia os valores tal como estão no Supabase (o "template ativo")
              // Não persiste no localStorage do mês novo — só grava se o usuário editar
              setCustos(data);
              return;
            }
          }
        }catch(_){}
        // 4) Legacy sem mês
        if(refMonth){ const s=localStorage.getItem(_keyLegacy); if(s){ setCustos(JSON.parse(s)); return; } }
        // 5) Defaults hardcoded (último recurso)
        setCustos(_DEFAULT.map(function(x,i){ return Object.assign({id:"local-"+i}, x); }));
      }catch(_){}
    }
    _reload();
    return function(){ alive=false; };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  },[refMonth]);

  // Sync do Supabase (só se sem refMonth ou refMonth === mês atual)
  const _isCurrentMonth = !refMonth || (function(){const d=new Date();return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")===refMonth;})();
  useEffect(function(){
    let alive=true;
    async function _load(){
      if(!_isCurrentMonth) return; // só carrega Supabase pro mês atual
      try{
        const sb=window._sb;
        if(!sb) return;
        setLoading(true);
        const {data,error}=await sb.from("pixels_custos_editaveis").select("*").eq("tipo",tipo).order("ordem",{ascending:true});
        if(error){ console.warn("[custos] load:",error.message); return; }
        if(!alive) return;
        if(data && data.length>0){
          setCustos(data);
          try{ localStorage.setItem(_key, JSON.stringify(data)); }catch(_){}
        }else{
          const seed = _DEFAULT.map(function(x){ return Object.assign({tipo:tipo}, x); });
          const {data:seeded,error:e2} = await sb.from("pixels_custos_editaveis").insert(seed).select();
          if(!e2 && seeded){ setCustos(seeded); try{ localStorage.setItem(_key, JSON.stringify(seeded)); }catch(_){} }
        }
      }catch(e){ console.warn("[custos] fail:", e?.message); }
      finally{ if(alive) setLoading(false); }
    }
    _load();
    return function(){ alive=false; };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  },[tipo, refMonth]);

  const _persist = function(next){
    setCustos(next);
    try{ localStorage.setItem(_key, JSON.stringify(next)); }catch(_){}
  };

  async function addItem(categoria, label, valor){
    const sb=window._sb;
    const maxOrdem=custos.reduce(function(m,x){return Math.max(m,x.ordem||0);},0);
    const novo={tipo:tipo, categoria:categoria, label:label, valor:Number(valor)||0, ordem:maxOrdem+1};
    try{
      if(sb && _isCurrentMonth){
        const {data,error}=await sb.from("pixels_custos_editaveis").insert(novo).select().maybeSingle();
        if(error) throw error;
        _persist(custos.concat([data]));
        if(typeof pixelsToast!=="undefined") pixelsToast.success("Item adicionado",2000);
        return;
      }
    }catch(e){ if(typeof pixelsToast!=="undefined") pixelsToast.error("Erro: "+(e.message||"desconhecido")); }
    // Fallback: local only (histórico ou fora do mês atual)
    _persist(custos.concat([Object.assign({id:"local-"+Date.now()}, novo)]));
  }

  async function updateItem(id, patch){
    const sb=window._sb;
    const next=custos.map(function(x){ return x.id===id ? Object.assign({}, x, patch) : x; });
    _persist(next);
    try{
      if(sb && _isCurrentMonth && String(id).indexOf("local-")!==0){
        const {error}=await sb.from("pixels_custos_editaveis").update(patch).eq("id",id);
        if(error) throw error;
      }
    }catch(e){ if(typeof pixelsToast!=="undefined") pixelsToast.error("Erro salvar: "+(e.message||"desconhecido")); }
  }

  async function removeItem(id){
    const sb=window._sb;
    _persist(custos.filter(function(x){ return x.id!==id; }));
    try{
      if(sb && _isCurrentMonth && String(id).indexOf("local-")!==0){
        const {error}=await sb.from("pixels_custos_editaveis").delete().eq("id",id);
        if(error) throw error;
        if(typeof pixelsToast!=="undefined") pixelsToast.success("Item removido",2000);
      }
    }catch(e){ if(typeof pixelsToast!=="undefined") pixelsToast.error("Erro deletar: "+(e.message||"desconhecido")); }
  }

  return {custos:custos, addItem:addItem, updateItem:updateItem, removeItem:removeItem, loading:loading};
}

// ═══ DRE Helpers ═══
function _DRELinha({kind, pos, label, valor, cor, subtitle, op, isMob}){
  const brl=function(n){return "R$ "+Number(n||0).toLocaleString("pt-BR",{minimumFractionDigits:2,maximumFractionDigits:2});};
  const bgHead=kind==="header"?"linear-gradient(90deg,"+cor+"12,"+cor+"04)":"transparent";
  const brdHead=kind==="header"?"1px solid "+cor+"33":"none";
  const brdSub=kind==="subtotal"?"1px dashed #e2e8f0":brdHead;
  // Padrão único: [N.] pill colorido + operador colorido + label + valor
  return <div style={{background:bgHead,border:brdHead,borderRadius:kind==="header"?11:0,borderTop:brdSub,padding:kind==="header"?"14px 16px":"12px 16px",display:"flex",alignItems:"center",justifyContent:"space-between",gap:12,flexWrap:"wrap"}}>
    <div style={{display:"flex",alignItems:"center",gap:10}}>
      <span style={{background:cor,color:"#fff",fontSize:12,fontWeight:800,width:32,height:32,borderRadius:8,display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0,fontFeatureSettings:"'tnum'"}}>{pos}</span>
      {op && <span style={{color:cor,fontWeight:800,fontSize:16,width:14,textAlign:"center",flexShrink:0}}>{op}</span>}
      <div>
        <div style={{color:"#0f172a",fontSize:14,fontWeight:800,letterSpacing:-.2}}>{label}</div>
        {subtitle&&<div style={{color:"#94a3b8",fontSize:11,marginTop:1}}>{subtitle}</div>}
      </div>
    </div>
    <span style={{color:cor,fontWeight:800,fontSize:22,letterSpacing:-.6,fontFeatureSettings:"'tnum'",lineHeight:1,paddingRight:26}}>{brl(valor)}</span>
  </div>;
}

function _DRESecao({pos, op, label, total, cor, subtitle, state, isSocio, brl, isMob, extra, extraBottom, defaultExpanded}){
  const [expanded, setExpanded] = useState(!!defaultExpanded);
  return <div style={{border:"1px solid #f1f5f9",borderRadius:11,overflow:"hidden"}}>
    <div onClick={function(){setExpanded(!expanded);}} style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:12,padding:"12px 16px",cursor:"pointer",background:expanded?cor+"08":"#fff",transition:"background .12s",flexWrap:"wrap"}}
      onMouseEnter={function(e){e.currentTarget.style.background=cor+"10";}}
      onMouseLeave={function(e){e.currentTarget.style.background=expanded?cor+"08":"#fff";}}>
      <div style={{display:"flex",alignItems:"center",gap:10}}>
        <span style={{background:cor,color:"#fff",fontSize:12,fontWeight:800,width:32,height:32,borderRadius:8,display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0,fontFeatureSettings:"'tnum'"}}>{pos}</span>
        <span style={{color:cor,fontWeight:800,fontSize:16,width:14,textAlign:"center",flexShrink:0}}>{op}</span>
        <div>
          <div style={{color:"#0f172a",fontSize:14,fontWeight:800,letterSpacing:-.2}}>{label}</div>
          {subtitle&&<div style={{color:"#94a3b8",fontSize:11,marginTop:1}}>{subtitle}</div>}
        </div>
      </div>
      <div style={{display:"flex",alignItems:"center",gap:10}}>
        <span style={{color:cor,fontWeight:800,fontSize:22,fontFeatureSettings:"'tnum'",letterSpacing:-.6}}>{brl(total)}</span>
        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#94a3b8" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" style={{transform:expanded?"rotate(180deg)":"rotate(0)",transition:"transform .15s"}}><polyline points="6 9 12 15 18 9"/></svg>
      </div>
    </div>
    {expanded && <div style={{padding:"8px 16px 14px",background:"#fafbfc",borderTop:"1px solid #f1f5f9"}}>
      {extra && (Array.isArray(extra)?extra:[extra]).filter(Boolean).map(function(ex,exIdx){
        if(ex.render) return <div key={exIdx} style={{marginBottom:10}}>{ex.render()}</div>;
        return <div key={exIdx} style={{padding:"8px 12px",background:cor+"12",borderRadius:8,marginBottom:10,display:"flex",justifyContent:"space-between",alignItems:"center",gap:8}}>
          <div>
            <div style={{color:cor,fontSize:11,fontWeight:800,textTransform:"uppercase",letterSpacing:.4}}>{ex.label}</div>
            {ex.hint&&<div style={{color:"#64748b",fontSize:10.5,marginTop:1}}>{ex.hint}</div>}
          </div>
          <span style={{color:cor,fontWeight:800,fontSize:16,fontFeatureSettings:"'tnum'",letterSpacing:-.3}}>{brl(ex.valor)}</span>
        </div>;
      })}
      <_CustosEditableList state={state} accent={cor} isSocio={isSocio} brl={brl} isMob={isMob}/>
      {extraBottom && <div style={{marginTop:14}}>{extraBottom}</div>}
    </div>}
  </div>;
}

/* ─── Gráfico Evolução DRE: 6 meses × 5 categorias, layout premium ─── */
function _DREEvolucaoChart({dreMonth, cores, isMob}){
  // Últimos 6 meses até dreMonth
  const meses = [];
  const p=dreMonth.split("-"); let y=parseInt(p[0],10), m=parseInt(p[1],10);
  for(let i=5;i>=0;i--){
    let mm=m-i, yy=y;
    while(mm<1){mm+=12;yy-=1;}
    meses.push(yy+"-"+String(mm).padStart(2,"0"));
  }
  const _sum = function(arr){return (arr||[]).reduce(function(s,it){return s+Number(it.valor||0);},0);};
  function _readMes(tipo, mes){
    try{
      const s=localStorage.getItem("pixels-custos-"+tipo+"-"+mes);
      if(s) return _sum(JSON.parse(s));
      const s2=localStorage.getItem("pixels-custos-"+tipo);
      if(s2) return _sum(JSON.parse(s2));
    }catch(_){}
    return 0;
  }
  function _receitaMes(){
    try{
      const src = (typeof _gfLoadContratos==="function") ? _gfLoadContratos() : (typeof GF_CONTRATOS_DEFAULT!=="undefined"?GF_CONTRATOS_DEFAULT:[]);
      const flat = (src||[]).flatMap(function(c){
        if(c.unidades) return c.unidades.map(function(u){return Number(u.valor||0);});
        return [Number(c.valor||0)];
      });
      return flat.reduce(function(s,v){return s+v;},0);
    }catch(_){ return 0; }
  }
  const receitaAtual = _receitaMes();
  const CUSTO_KEYS = ["imposto","csp","despesa_direta","despesa_operacional","prolabore"];
  function _despesaTotal(mes){ return CUSTO_KEYS.reduce(function(s,k){return s+_readMes(k,mes);},0); }
  const dados = meses.map(function(mes){
    const receita = receitaAtual;
    const despesa = _despesaTotal(mes);
    const lucro = receita - despesa;
    const margem = receita>0 ? (lucro/receita)*100 : 0;
    return {mes, receita, despesa, lucro, margem};
  });
  const maxVal = Math.max(1, ...dados.map(function(d){return Math.max(d.receita, Math.max(d.lucro,0));}));
  const avgReceita = dados.reduce(function(s,d){return s+d.receita;},0)/dados.length;
  const avgLucro   = dados.reduce(function(s,d){return s+d.lucro;},0)/dados.length;
  const avgMargem  = avgReceita>0 ? (avgLucro/avgReceita)*100 : 0;

  function _brlK(n){
    if(n>=1000000) return "R$ "+(n/1000000).toFixed(1).replace(".0","")+"M";
    if(n>=1000) return "R$ "+Math.round(n/1000)+"k";
    return "R$ "+Math.round(n);
  }
  function _brl(n){return "R$ "+Number(n||0).toLocaleString("pt-BR",{minimumFractionDigits:0,maximumFractionDigits:0});}
  function _mLabel(mes){const p=mes.split("-");const mn=["Jan","Fev","Mar","Abr","Mai","Jun","Jul","Ago","Set","Out","Nov","Dez"];return (mn[parseInt(p[1],10)-1]||"")+"/"+p[0].slice(2);}
  function _margemCor(pct){ return pct>=30 ? "#16a34a" : pct>=15 ? "#f59e0b" : "#dc2626"; }
  function _margemBg(pct){  return pct>=30 ? "#dcfce7" : pct>=15 ? "#fef3c7" : "#fee2e2"; }

  const BAR_AREA_H = 130; // altura da área de barras em px

  return <section style={{background:"#fff",border:"1px solid #e2e8f0",borderRadius:14,padding:isMob?"16px 14px":"18px 22px",display:"flex",flexDirection:"column",gap:14,fontFamily:"'Inter',system-ui,sans-serif"}}>
    {/* Header com KPIs médios */}
    <div style={{display:"flex",alignItems:"flex-start",justifyContent:"space-between",gap:14,flexWrap:"wrap"}}>
      <div style={{display:"flex",alignItems:"center",gap:11}}>
        <div style={{width:36,height:36,borderRadius:10,background:"linear-gradient(135deg,#0f172a,#1e293b)",display:"flex",alignItems:"center",justifyContent:"center",boxShadow:"0 4px 12px rgba(15,23,42,0.18)"}}>
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><line x1="12" y1="20" x2="12" y2="10"/><line x1="18" y1="20" x2="18" y2="4"/><line x1="6" y1="20" x2="6" y2="16"/></svg>
        </div>
        <div>
          <div style={{color:"#0f172a",fontWeight:800,fontSize:15,letterSpacing:-.3}}>Evolução mensal</div>
          <div style={{color:"#64748b",fontSize:11.5,marginTop:1}}>Receita vs Lucro líquido · últimos 6 meses</div>
        </div>
      </div>
      <div style={{display:"flex",gap:14,flexWrap:"wrap"}}>
        {[
          {label:"Receita média",  value:_brl(avgReceita), color:"#16a34a"},
          {label:"Lucro médio",    value:_brl(avgLucro),   color:"#7c3aed"},
          {label:"Margem média",   value:avgMargem.toFixed(1)+"%", color:_margemCor(avgMargem)},
        ].map(function(k,idx){
          return <div key={idx} style={{textAlign:"right"}}>
            <div style={{color:"#94a3b8",fontSize:9.5,fontWeight:800,letterSpacing:.5,textTransform:"uppercase"}}>{k.label}</div>
            <div style={{color:k.color,fontWeight:800,fontSize:15,letterSpacing:-.4,fontFeatureSettings:"'tnum'",marginTop:2}}>{k.value}</div>
          </div>;
        })}
      </div>
    </div>

    {/* Grid de 6 meses com barras agrupadas */}
    <div style={{display:"grid",gridTemplateColumns:"repeat(6,1fr)",gap:isMob?6:12,paddingTop:6}}>
      {dados.map(function(d,i){
        const hRec = maxVal>0 ? Math.max(4,(d.receita/maxVal)*BAR_AREA_H) : 4;
        const hLuc = maxVal>0 ? Math.max(4,(Math.max(d.lucro,0)/maxVal)*BAR_AREA_H) : 4;
        return <div key={i} style={{display:"flex",flexDirection:"column",alignItems:"center",gap:8}}>
          {/* Chip da margem % no topo */}
          <div style={{background:_margemBg(d.margem),color:_margemCor(d.margem),fontWeight:800,fontSize:10.5,padding:"3px 9px",borderRadius:99,letterSpacing:.2,fontFeatureSettings:"'tnum'",whiteSpace:"nowrap"}}>{d.margem.toFixed(1)}%</div>

          {/* Área das barras */}
          <div style={{width:"100%",height:BAR_AREA_H,display:"flex",alignItems:"flex-end",justifyContent:"center",gap:isMob?3:6,position:"relative"}}>
            {/* Linha de base sutil */}
            <div style={{position:"absolute",left:0,right:0,bottom:0,height:1,background:"#e2e8f0"}}/>
            {/* Barra Receita */}
            <div style={{flex:1,maxWidth:isMob?18:32,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"flex-end",height:"100%"}}>
              <div style={{color:"#16a34a",fontSize:isMob?8.5:9.5,fontWeight:800,letterSpacing:-.1,marginBottom:3,whiteSpace:"nowrap",fontFeatureSettings:"'tnum'"}}>{_brlK(d.receita)}</div>
              <div style={{width:"100%",height:hRec,background:"linear-gradient(180deg,#22c55e 0%,#16a34a 100%)",borderRadius:"6px 6px 0 0",boxShadow:"0 2px 6px rgba(22,163,74,0.25)",transition:"all .18s"}}/>
            </div>
            {/* Barra Lucro */}
            <div style={{flex:1,maxWidth:isMob?18:32,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"flex-end",height:"100%"}}>
              <div style={{color:"#7c3aed",fontSize:isMob?8.5:9.5,fontWeight:800,letterSpacing:-.1,marginBottom:3,whiteSpace:"nowrap",fontFeatureSettings:"'tnum'"}}>{_brlK(Math.max(d.lucro,0))}</div>
              <div style={{width:"100%",height:hLuc,background:"linear-gradient(180deg,#a855f7 0%,#7c3aed 100%)",borderRadius:"6px 6px 0 0",boxShadow:"0 2px 6px rgba(124,58,237,0.25)",transition:"all .18s"}}/>
            </div>
          </div>

          {/* Rótulo do mês */}
          <div style={{color:"#64748b",fontSize:11,fontWeight:700,letterSpacing:-.2,fontFeatureSettings:"'tnum'"}}>{_mLabel(d.mes)}</div>
        </div>;
      })}
    </div>

    {/* Legenda rodapé */}
    <div style={{display:"flex",alignItems:"center",gap:16,flexWrap:"wrap",paddingTop:6,borderTop:"1px dashed #f1f5f9"}}>
      <div style={{display:"inline-flex",alignItems:"center",gap:7,fontSize:11.5,fontWeight:700,color:"#334155"}}>
        <span style={{width:12,height:12,borderRadius:3,background:"linear-gradient(180deg,#22c55e,#16a34a)"}}/>Receita
      </div>
      <div style={{display:"inline-flex",alignItems:"center",gap:7,fontSize:11.5,fontWeight:700,color:"#334155"}}>
        <span style={{width:12,height:12,borderRadius:3,background:"linear-gradient(180deg,#a855f7,#7c3aed)"}}/>Lucro líquido
      </div>
      <div style={{marginLeft:"auto",color:"#94a3b8",fontSize:10.5,fontWeight:600}}>Chip do topo = margem líquida do mês</div>
    </div>
  </section>;
}


/* ═══ MODAL EDITAR CONTRATO — Gestao > Financeiro > Contratos ativos ═══
   Fields: valor, pagDia, metodoPag (PIX/Boleto/Cartao), dataInicio,
           envios[] (quando disparar cobranca + NFSe), contatoNome/Email/Whats,
           observacoes.
   Removidos 08/2026: respFin (responsavel financeiro) e nfAsaas (NF pelo Asaas). */

// Quando enviar a cobranca e a NFSe. Multipla escolha — o financeiro pode
// mandar lembrete antes e a nota no dia, por exemplo.
/* Contrato agora é editado SÓ no Comercial (decisão do Vinicius, 10/09/2026).
   Aqui no Financeiro a lista é leitura — alimenta o DRE — e manda pro Comercial. */
function _gfIrParaComercial(){
  try{
    if(typeof window.pixelsNav==="function"){ window.pixelsNav("comercial"); return; }
  }catch(_){}
  if(typeof pixelsToast!=="undefined") pixelsToast.info("Abra Comercial › Contratos pra editar.",3500);
}

const _GF_ENVIO_OPTS = [
  {id:"venc",   label:"No dia do vencimento",        off:0},
  {id:"5dias",  label:"5 dias antes do vencimento",  off:5},
  {id:"10dias", label:"10 dias antes do vencimento", off:10},
  {id:"dia1",   label:"1º dia do mês do vencimento", off:null},
];

// Mascara leve de telefone BR — (49) 99999-9999
function _gfFmtWhats(v){
  const n = String(v||"").replace(/\D/g,"").slice(0,11);
  if(n.length<=2)  return n;
  if(n.length<=6)  return "("+n.slice(0,2)+") "+n.slice(2);
  if(n.length<=10) return "("+n.slice(0,2)+") "+n.slice(2,6)+"-"+n.slice(6);
  return "("+n.slice(0,2)+") "+n.slice(2,7)+"-"+n.slice(7);
}

function _GFEditContratoModal({editContrato, contratos, updateContratos, onClose}){
  const _c = editContrato;
  const _isUnit = _c.unitIdx !== null && _c.unitIdx !== undefined;
  const _initDraft = _c.draft || {};
  const [d, setD] = useState({
    valor:       _initDraft.valor       || 0,
    pagDia:      _initDraft.pagDia      || 10,
    metodoPag:   _initDraft.metodoPag   || "PIX",
    dataInicio:  _initDraft.dataInicio  || "",
    envios:      Array.isArray(_initDraft.envios) ? _initDraft.envios.slice() : [],
    contatoNome: _initDraft.contatoNome || "",
    contatoEmail:_initDraft.contatoEmail|| "",
    contatoWhats:_initDraft.contatoWhats|| "",
    observacoes: _initDraft.observacoes || "",
    pacoteId:    _initDraft.pacoteId    || "",
  });
  const set = function(k,v){ setD(function(p){return Object.assign({},p,{[k]:v});}); };
  const _toggleEnvio = function(id){
    setD(function(p){
      const _cur = Array.isArray(p.envios)?p.envios:[];
      const _next = _cur.indexOf(id)>=0 ? _cur.filter(function(x){return x!==id;}) : _cur.concat([id]);
      return Object.assign({},p,{envios:_next});
    });
  };
  // Mostra em que dia do mes cada opcao cai, a partir do dia do vencimento
  const _diaDe = function(o){
    if(o.off===null) return "dia 1";
    const _r = (Number(d.pagDia)||10) - o.off;
    return _r>=1 ? ("dia "+_r) : "mês anterior";
  };

  if(typeof useEscToClose==="function") useEscToClose(true, onClose);

  function _save(){
    updateContratos(function(prev){
      return (prev||[]).map(function(row){
        if(row.grupo !== _c.grupo) return row;
        if(_isUnit && Array.isArray(row.unidades)){
          const _newUnits = row.unidades.slice();
          _newUnits[_c.unitIdx] = Object.assign({}, _newUnits[_c.unitIdx], d);
          return Object.assign({}, row, {unidades:_newUnits});
        }
        // Cliente unico
        return Object.assign({}, row, d);
      });
    });
    onClose();
  }

  const _MET_OPTS = [
    {id:"PIX",    ico:<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><path d="M12 2l4.5 4.5L12 11 7.5 6.5z"/><path d="M12 13l4.5 4.5L12 22l-4.5-4.5z"/><path d="M2 12l4.5-4.5L11 12l-4.5 4.5z"/><path d="M13 12l4.5-4.5L22 12l-4.5 4.5z"/></svg>},
    {id:"Boleto", ico:<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><line x1="4" y1="4" x2="4" y2="20"/><line x1="8" y1="4" x2="8" y2="20"/><line x1="12" y1="4" x2="12" y2="20"/><line x1="16" y1="4" x2="16" y2="20"/><line x1="20" y1="4" x2="20" y2="20"/></svg>},
    {id:"Cartão", ico:<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><rect x="2" y="5" width="20" height="14" rx="2"/><line x1="2" y1="10" x2="22" y2="10"/></svg>},
  ];

  const _title = _isUnit
    ? "Editar unidade — "+_c.grupo+" · "+(_initDraft.nome||"")
    : "Editar contrato — "+_c.grupo;

  const _mob = _pxMob();
  const _LBL = {color:"#94a3b8",fontSize:10,fontWeight:800,textTransform:"uppercase",letterSpacing:.7,marginBottom:6};
  const _INP = {width:"100%",background:"#fff",border:"1px solid #e2e8f0",borderRadius:10,padding:"10px 13px",color:"#0f172a",fontSize:13,fontWeight:600,outline:"none",fontFamily:"inherit",boxSizing:"border-box",transition:"all .12s"};
  const _foco = function(e){ e.currentTarget.style.borderColor="#a855f7"; e.currentTarget.style.boxShadow="0 0 0 3px rgba(168,85,247,.13)"; };
  const _blur = function(e){ e.currentTarget.style.borderColor="#e2e8f0"; e.currentTarget.style.boxShadow="none"; };
  // Cabecalho de secao — divisor + rotulo, mesmo padrao do resto do app
  const _Sec = function(p){
    return <div style={{display:"flex",alignItems:"center",gap:9,marginTop:p.first?0:6}}>
      <span style={{display:"inline-flex",alignItems:"center",justifyContent:"center",width:22,height:22,borderRadius:7,background:"#f5f3ff",color:"#7c3aed",flexShrink:0}}>{p.ico}</span>
      <span style={{color:"#0f172a",fontSize:12,fontWeight:800,letterSpacing:-.1,whiteSpace:"nowrap"}}>{p.label}</span>
      <span style={{flex:1,height:1,background:"linear-gradient(90deg,#e2e8f0,transparent)"}}/>
    </div>;
  };

  return <div onMouseDown={function(e){if(e.target===e.currentTarget)onClose();}}
    style={{position:"fixed",inset:0,background:"rgba(15,23,42,0.55)",backdropFilter:"blur(4px)",zIndex:500,display:"flex",alignItems:"center",justifyContent:"center",padding:16,fontFamily:"'Inter',system-ui,sans-serif"}}>
    <div onMouseDown={function(e){e.stopPropagation();}}
      style={{background:"#fff",borderRadius:18,width:"100%",maxWidth:600,maxHeight:"92vh",overflow:"auto",boxShadow:"0 24px 64px rgba(15,23,42,0.28)"}}>

      {/* ── Header ── */}
      <div style={{background:"linear-gradient(135deg,#1e1b4b 0%,#4c1d95 52%,#7c3aed 100%)",padding:"18px 22px",color:"#fff",display:"flex",justifyContent:"space-between",alignItems:"flex-start",gap:12,position:"relative",overflow:"hidden"}}>
        <div style={{position:"absolute",right:-40,top:-60,width:180,height:180,borderRadius:"50%",background:"radial-gradient(circle,rgba(255,255,255,.14),transparent 70%)",pointerEvents:"none"}}/>
        <div style={{display:"flex",alignItems:"center",gap:12,position:"relative",minWidth:0}}>
          <div style={{width:38,height:38,borderRadius:11,background:"rgba(255,255,255,.15)",border:"1px solid rgba(255,255,255,.24)",display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="9" y1="15" x2="15" y2="15"/></svg>
          </div>
          <div style={{minWidth:0}}>
            <div style={{fontWeight:800,fontSize:16,letterSpacing:-.3,lineHeight:1.25,overflow:"hidden",textOverflow:"ellipsis"}}>{_title}</div>
            <div style={{fontSize:11.5,opacity:.78,marginTop:2,fontWeight:500}}>Valores, cobrança e contato financeiro</div>
          </div>
        </div>
        <button onClick={onClose} title="Fechar"
          style={{background:"rgba(255,255,255,.14)",border:"1px solid rgba(255,255,255,.2)",borderRadius:9,width:30,height:30,color:"#fff",cursor:"pointer",display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0,position:"relative",transition:"background .12s"}}
          onMouseEnter={function(e){e.currentTarget.style.background="rgba(255,255,255,.26)";}}
          onMouseLeave={function(e){e.currentTarget.style.background="rgba(255,255,255,.14)";}}>
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
        </button>
      </div>

      <div style={{padding:"20px 22px 22px",display:"flex",flexDirection:"column",gap:13}}>

        {/* ══ CONTRATO ══ */}
        <_Sec first label="Contrato" ico={<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round"><line x1="12" y1="1" x2="12" y2="23"/><path d="M17 5H9.5a3.5 3.5 0 000 7h5a3.5 3.5 0 010 7H6"/></svg>}/>

        {/* Produto contratado — escolher preenche o valor de tabela, mas segue editável */}
        {(function(){
          const _pacs=(typeof _pjPacotesComercial==="function")?_pjPacotesComercial():[];
          if(!_pacs.length) return null;
          const _num=function(v){ return Number(String(v||"").replace(/[^0-9,]/g,"").replace(",",".")) || 0; };
          const _sel=_pacs.find(function(x){return x.id===d.pacoteId;});
          return <div>
            <div style={_LBL}>Produto contratado</div>
            <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
              {_pacs.map(function(pc){
                const _on=d.pacoteId===pc.id;
                return <button key={pc.id} type="button" onClick={function(){
                  if(_on){ set("pacoteId",""); return; }
                  setD(function(p){
                    const _v=_num(pc.valor);
                    // valor de tabela só entra se ainda não tem valor digitado (não sobrescreve negociação)
                    return Object.assign({},p,{pacoteId:pc.id, valor:(_v>0&&(!p.valor||p.valor===0))?_v:p.valor});
                  });
                }}
                  style={{background:_on?"linear-gradient(135deg,#a855f7,#7c3aed)":"#fff",color:_on?"#fff":"#475569",border:"1px solid "+(_on?"#7c3aed":"#e2e8f0"),borderRadius:99,padding:"6px 12px",fontSize:11.5,fontWeight:_on?800:600,cursor:"pointer",fontFamily:"inherit",transition:"all .12s",boxShadow:_on?"0 4px 12px rgba(124,58,237,.26)":"none"}}>
                  {pc.label}{pc.valor?<span style={{opacity:.66,marginLeft:6,fontWeight:600}}>{pc.valor}</span>:null}
                </button>;
              })}
            </div>
            {_sel&&_num(_sel.valor)>0&&Number(d.valor)!==_num(_sel.valor)&&
              <div style={{marginTop:6,display:"flex",alignItems:"center",gap:7,flexWrap:"wrap"}}>
                <span style={{color:"#94a3b8",fontSize:11}}>Tabela: {_sel.valor} — este contrato está diferente.</span>
                <button type="button" onClick={function(){ set("valor",_num(_sel.valor)); }}
                  style={{background:"#f5f3ff",color:"#7c3aed",border:"1px solid #ddd6fe",borderRadius:8,padding:"3px 9px",fontSize:10.5,fontWeight:800,cursor:"pointer",fontFamily:"inherit"}}>Usar valor de tabela</button>
              </div>}
          </div>;
        })()}

        <div style={{display:"grid",gridTemplateColumns:_mob?"1fr":"1fr 1fr",gap:10}}>
          <div>
            <div style={_LBL}>Valor mensal</div>
            <div style={{position:"relative",display:"flex",alignItems:"center"}}>
              <span style={{position:"absolute",left:13,color:"#94a3b8",fontSize:13,fontWeight:700,pointerEvents:"none"}}>R$</span>
              <input type="number" inputMode="decimal" min="0" step="100" placeholder="0"
                value={(d.valor===0||d.valor===null||d.valor===undefined)?"":d.valor}
                onChange={function(e){ const v=e.target.value; set("valor", v===""?0:(Number(v)||0)); }}
                onFocus={function(e){ _foco&&_foco(e); try{e.currentTarget.select();}catch(_){} }} onBlur={_blur}
                style={Object.assign({},_INP,{paddingLeft:37,fontSize:15,fontWeight:800,fontFeatureSettings:"'tnum'"})}/>
            </div>
          </div>
          <div>
            <div style={_LBL}>Dia do vencimento</div>
            <div style={{position:"relative",display:"flex",alignItems:"center"}}>
              <input type="number" inputMode="decimal" min="1" max="31" value={d.pagDia||10}
                onChange={function(e){set("pagDia", Math.max(1,Math.min(31, Number(e.target.value)||10)));}}
                onFocus={_foco} onBlur={_blur}
                style={Object.assign({},_INP,{paddingRight:96,fontSize:15,fontWeight:800,fontFeatureSettings:"'tnum'"})}/>
              <span style={{position:"absolute",right:13,color:"#94a3b8",fontSize:11.5,fontWeight:600,pointerEvents:"none"}}>de cada mês</span>
            </div>
          </div>
        </div>

        <div style={{display:"grid",gridTemplateColumns:_mob?"1fr":"1fr 1fr",gap:10}}>
          <div>
            <div style={_LBL}>Método de pagamento</div>
            <div style={{display:"flex",gap:5}}>
              {_MET_OPTS.map(function(m){
                const _sel = d.metodoPag===m.id;
                return <button key={m.id} onClick={function(){set("metodoPag", m.id);}} type="button"
                  style={{flex:1,background:_sel?"linear-gradient(135deg,#a855f7,#7c3aed)":"#fff",color:_sel?"#fff":"#64748b",border:"1px solid "+(_sel?"#7c3aed":"#e2e8f0"),borderRadius:10,padding:"9px 8px",fontSize:11.5,fontWeight:_sel?800:600,cursor:"pointer",fontFamily:"inherit",transition:"all .12s",display:"inline-flex",alignItems:"center",justifyContent:"center",gap:5,boxShadow:_sel?"0 4px 12px rgba(124,58,237,.28)":"none"}}>
                  {m.ico}{m.id}
                </button>;
              })}
            </div>
          </div>
          <div>
            <div style={_LBL}>Início do contrato</div>
            <input type="date" value={d.dataInicio||""}
              onChange={function(e){set("dataInicio", e.target.value);}}
              onFocus={_foco} onBlur={_blur}
              style={Object.assign({},_INP,{fontWeight:600})}/>
          </div>
        </div>

        {/* ══ ENVIO DA COBRANCA E NFSe ══ */}
        <_Sec label="Data de envio da cobrança e NFSe" ico={<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M22 2L11 13"/><path d="M22 2l-7 20-4-9-9-4 20-7z"/></svg>}/>
        <div style={{display:"grid",gridTemplateColumns:_mob?"1fr":"1fr 1fr",gap:8}}>
          {_GF_ENVIO_OPTS.map(function(o){
            const _on = (d.envios||[]).indexOf(o.id)>=0;
            return <button key={o.id} type="button" onClick={function(){_toggleEnvio(o.id);}}
              style={{background:_on?"#f5f3ff":"#fff",border:"1px solid "+(_on?"#a855f7":"#e2e8f0"),borderRadius:11,padding:"11px 13px",cursor:"pointer",fontFamily:"inherit",display:"flex",alignItems:"center",gap:10,textAlign:"left",transition:"all .12s",boxShadow:_on?"0 0 0 3px rgba(168,85,247,.10)":"none"}}
              onMouseEnter={function(e){if(!_on)e.currentTarget.style.borderColor="#cbd5e1";}}
              onMouseLeave={function(e){if(!_on)e.currentTarget.style.borderColor="#e2e8f0";}}>
              <span style={{width:18,height:18,borderRadius:6,border:"1.5px solid "+(_on?"#7c3aed":"#cbd5e1"),background:_on?"#7c3aed":"#fff",display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0,transition:"all .12s"}}>
                {_on && <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="3.4" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12"/></svg>}
              </span>
              <span style={{flex:1,minWidth:0,color:_on?"#0f172a":"#475569",fontSize:12,fontWeight:_on?700:600,lineHeight:1.35}}>{o.label}</span>
              <span style={{background:_on?"#ede9fe":"#f8fafc",color:_on?"#6d28d9":"#94a3b8",fontSize:9.5,fontWeight:800,padding:"3px 7px",borderRadius:99,flexShrink:0,whiteSpace:"nowrap",fontFeatureSettings:"'tnum'"}}>{_diaDe(o)}</span>
            </button>;
          })}
        </div>

        {/* ══ CONTATO FINANCEIRO ══ */}
        <_Sec label="Contato financeiro" ico={<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M20 21v-2a4 4 0 00-4-4H8a4 4 0 00-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>}/>
        <div>
          <div style={_LBL}>Nome do contato</div>
          <input type="text" value={d.contatoNome||""} placeholder="Quem recebe a cobrança"
            onChange={function(e){set("contatoNome", e.target.value);}}
            onFocus={_foco} onBlur={_blur} style={_INP}/>
        </div>
        <div style={{display:"grid",gridTemplateColumns:_mob?"1fr":"1fr 1fr",gap:10}}>
          <div>
            <div style={_LBL}>E-mail</div>
            <input type="email" value={d.contatoEmail||""} placeholder="financeiro@empresa.com.br"
              onChange={function(e){set("contatoEmail", e.target.value);}}
              onFocus={_foco} onBlur={_blur} style={Object.assign({},_INP,{fontWeight:500})}/>
          </div>
          <div>
            <div style={_LBL}>WhatsApp</div>
            <div style={{position:"relative",display:"flex",alignItems:"center"}}>
              <input type="tel" value={d.contatoWhats||""} placeholder="(49) 99999-9999"
                onChange={function(e){set("contatoWhats", _gfFmtWhats(e.target.value));}}
                onFocus={_foco} onBlur={_blur}
                style={Object.assign({},_INP,{fontWeight:600,fontFeatureSettings:"'tnum'",paddingRight:String(d.contatoWhats||"").replace(/\D/g,"").length>=10?38:13})}/>
              {String(d.contatoWhats||"").replace(/\D/g,"").length>=10 &&
                <a href={"https://wa.me/55"+String(d.contatoWhats||"").replace(/\D/g,"")} target="_blank" rel="noreferrer" title="Abrir conversa no WhatsApp"
                  style={{position:"absolute",right:9,display:"inline-flex",alignItems:"center",justifyContent:"center",width:24,height:24,borderRadius:7,background:"#dcfce7",color:"#16a34a",textDecoration:"none",transition:"background .12s"}}
                  onMouseEnter={function(e){e.currentTarget.style.background="#bbf7d0";}}
                  onMouseLeave={function(e){e.currentTarget.style.background="#dcfce7";}}>
                  <svg width="13" height="13" viewBox="0 0 24 24" fill="currentColor"><path d="M17.47 14.38c-.3-.15-1.74-.86-2.01-.96-.27-.1-.47-.15-.66.15-.2.3-.76.96-.93 1.15-.17.2-.34.22-.64.08-.3-.15-1.25-.46-2.38-1.47-.88-.78-1.47-1.75-1.65-2.05-.17-.3-.02-.46.13-.6.13-.13.3-.35.45-.52.15-.17.2-.3.3-.5.1-.2.05-.37-.02-.52-.08-.15-.66-1.6-.9-2.18-.24-.57-.48-.5-.66-.5h-.56c-.2 0-.52.07-.79.37-.27.3-1.03 1.01-1.03 2.46s1.06 2.86 1.2 3.06c.15.2 2.08 3.18 5.04 4.46.7.3 1.25.48 1.68.62.7.22 1.35.19 1.86.12.57-.09 1.74-.71 1.99-1.4.25-.69.25-1.28.17-1.4-.07-.13-.27-.2-.57-.35zM12 2a10 10 0 00-8.6 15.07L2 22l5.07-1.33A10 10 0 1012 2z"/></svg>
                </a>}
            </div>
          </div>
        </div>

        {/* ══ OBSERVACOES ══ */}
        <_Sec label="Observações" ico={<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><line x1="4" y1="7" x2="20" y2="7"/><line x1="4" y1="12" x2="20" y2="12"/><line x1="4" y1="17" x2="14" y2="17"/></svg>}/>
        <textarea rows={3} value={d.observacoes||""}
          onChange={function(e){set("observacoes", e.target.value);}}
          onFocus={_foco} onBlur={_blur}
          placeholder="Notas internas: renegociar em Nov, tem desconto de fidelidade, etc."
          style={Object.assign({},_INP,{fontSize:12.5,fontWeight:500,resize:"vertical",minHeight:72,lineHeight:1.55})}/>

      </div>

      <div style={{padding:"14px 22px 18px",borderTop:"1px solid #f1f5f9",display:"flex",justifyContent:"flex-end",gap:8}}>
        <button onClick={onClose} type="button"
          style={{background:"#fff",color:"#64748b",border:"1px solid #e2e8f0",borderRadius:10,padding:"10px 18px",fontWeight:700,fontSize:13,cursor:"pointer",fontFamily:"inherit",transition:"all .12s"}}
          onMouseEnter={function(e){e.currentTarget.style.background="#f8fafc";}}
          onMouseLeave={function(e){e.currentTarget.style.background="#fff";}}>Cancelar</button>
        <button onClick={_save} type="button"
          style={{background:"linear-gradient(135deg,#a855f7,#7c3aed)",color:"#fff",border:"none",borderRadius:10,padding:"10px 22px",fontWeight:800,fontSize:13,cursor:"pointer",fontFamily:"inherit",boxShadow:"0 6px 16px rgba(124,58,237,.32)",display:"inline-flex",alignItems:"center",gap:7,transition:"all .12s"}}
          onMouseEnter={function(e){e.currentTarget.style.transform="translateY(-1px)";}}
          onMouseLeave={function(e){e.currentTarget.style.transform="";}}>
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.8" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
          Salvar contrato
        </button>
      </div>
    </div>
  </div>;
}

function PageGestaoFinanceiro({isMob,tasks,setTasks}){
  // Mês de referência da DRE (histórico persistido por mês em localStorage)
  const [dreMonth,setDreMonth]=useState(function(){const d=new Date();return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0");});
  function _dreShift(delta){
    const p=dreMonth.split("-"); let y=parseInt(p[0],10), m=parseInt(p[1],10)-1+delta;
    while(m<0){m+=12;y-=1;} while(m>11){m-=12;y+=1;}
    setDreMonth(y+"-"+String(m+1).padStart(2,"0"));
  }
  function _dreLabel(ym){
    const p=ym.split("-"); const mn=["Janeiro","Fevereiro","Março","Abril","Maio","Junho","Julho","Agosto","Setembro","Outubro","Novembro","Dezembro"];
    return (mn[parseInt(p[1],10)-1]||"?")+" de "+p[0];
  }
  const [contratosExpand,setContratosExpand]=useState({Bioter:true});
  // Custos editáveis por mês (Supabase pro mês atual, localStorage pros históricos)
  const _custosImpostos = _useCustos("imposto", dreMonth);
  const _custosCSP = _useCustos("csp", dreMonth);
  const _custosDespDireta = _useCustos("despesa_direta", dreMonth);
  const _custosDespOp = _useCustos("despesa_operacional", dreMonth);
  const _custosProlabore = _useCustos("prolabore", dreMonth);
  const _isSocio = (typeof CURRENT_USER!=="undefined" && CURRENT_USER && CURRENT_USER.level===1);
  const [contratos,setContratos]=useState(function(){return _gfLoadContratos();});
  // Clientes dinâmicos chegam do Supabase depois do primeiro render — re-roda o
  // merge pra que Acreforte/Lero/Clem apareçam sem precisar de F5.
  useEffect(function(){
    const t=setTimeout(function(){
      setContratos(function(prev){
        const next=_gfMergeClientesAtivos(prev);
        return next.length!==prev.length ? next : prev;
      });
    },1500);
    return function(){ clearTimeout(t); };
  },[]);
  const [editContrato,setEditContrato]=useState(null); // {grupo, unitIdx?, draft}
  // ── Fonte única (client_contracts): Supabase manda; localStorage é só cache ──
  // Migração automática: linha ainda "seed" no banco + valor editado neste navegador → sobe o local uma vez.
  const _ct=(typeof usePxContracts==="function")?usePxContracts():{list:[],byId:{},loading:true};
  useEffect(function(){
    if(_ct.loading||typeof pxCtToFin!=="function") return;
    setContratos(function(prev){
      const local={}; (prev||[]).forEach(function(c){ if(c&&c.clientId) local[String(c.clientId).toLowerCase()]=c; });
      const rows=(_ct.list||[]).filter(function(c){ return c.status!=="encerrado"; });
      rows.forEach(function(c){
        const l=local[String(c.client_id).toLowerCase()];
        if(c.seed&&l&&!l._auto){
          const fin=pxCtToFin(c);
          const difere=Number(l.valor||0)!==Number(fin.valor||0)||JSON.stringify(l.unidades||[])!==JSON.stringify(fin.unidades||[])||(l.pagDia||10)!==(fin.pagDia||10)||(l.metodoPag||"PIX")!==(fin.metodoPag||"PIX")||(l.contatoNome||"")!==(fin.contatoNome||"")||JSON.stringify(l.envios||[])!==JSON.stringify(fin.envios||[]);
          if(difere){ try{ pxCtSave(Object.assign(pxCtFromFin(l),{data_inicio:c.data_inicio||l.dataInicio||null,status:c.status,tipo:c.tipo}),{quiet:true,skipClients:true}); }catch(_){} }
        }
      });
      const next=rows.map(pxCtToFin);
      // preserva campos só-locais (cor customizada) e nomes de grupo já usados
      next.forEach(function(n){ const l=local[String(n.clientId).toLowerCase()]; if(l){ if(l.cor) n.cor=l.cor; if(l.grupo) n.grupo=l.grupo; } });
      return _gfMergeClientesAtivos(next);
    });
  },[_ct.list,_ct.loading]);
  const _updateContratos=function(updater){
    setContratos(function(prev){
      const next=typeof updater==="function"?updater(prev):updater;
      _gfSaveContratos(next);
      // grava no Supabase só o que mudou (fonte única → Comercial, Clientes e Onboarding)
      try{
        if(typeof pxCtSave==="function"&&typeof pxCtFromFin==="function"){
          (next||[]).forEach(function(n){
            if(!n||!n.clientId) return;
            const p=(prev||[]).find(function(x){return x&&x.clientId===n.clientId;});
            if(p&&JSON.stringify(p)===JSON.stringify(n)) return;
            const cur=_ct.byId[n.clientId]||{};
            const row=Object.assign(pxCtFromFin(n),{data_inicio:n.dataInicio||cur.data_inicio||null,status:cur.status||"ativo",tipo:cur.tipo||"mensal",servicos:cur.servicos||[],observacoes:n.observacoes||cur.observacoes||null});
            pxCtSave(row,{quiet:true}).catch(function(e){ if(typeof pixelsToast!=="undefined") pixelsToast.error("Contrato: "+(e&&e.message)); });
          });
        }
      }catch(_){}
      return next;
    });
  };
  const _brl=function(n){return "R$ "+Number(n||0).toLocaleString("pt-BR",{minimumFractionDigits:0,maximumFractionDigits:0});};
  const _brlF=function(n){return "R$ "+Number(n||0).toLocaleString("pt-BR",{minimumFractionDigits:2,maximumFractionDigits:2});};
  const _pct=function(n){return Number(n||0).toLocaleString("pt-BR",{minimumFractionDigits:2,maximumFractionDigits:2})+"%";};

  // ── Cálculos ──
  // Usa o state reativo `contratos` (não o default const) pra refletir edições do usuário.
  // Fallback defensivo pra GF_CONTRATOS_DEFAULT caso o state ainda não tenha carregado.
  const _contratosSrc=Array.isArray(contratos)&&contratos.length>0?contratos:(typeof GF_CONTRATOS_DEFAULT!=="undefined"?GF_CONTRATOS_DEFAULT:[]);
  const flatContratos=_contratosSrc.flatMap(function(c){
    if(c.unidades)return c.unidades.map(function(u){return {grupo:c.grupo,valor:u.valor};});
    return [{grupo:c.grupo,valor:c.valor}];
  });
  const ativos=flatContratos.filter(function(x){return x.valor>0;});
  const mrrContrato=ativos.reduce(function(s,x){return s+x.valor;},0);
  // Vendas pontuais do mês selecionado somam automaticamente ao MRR
  const vendasMesTotal = (function(){
    try{
      const all = (typeof _vpLoad==="function") ? _vpLoad() : [];
      return all.filter(function(v){return String(v.mes_ref||"")===dreMonth;}).reduce(function(s,v){return s+Number(v.valor||0);},0);
    }catch(_){ return 0; }
  })();
  const mrr = mrrContrato + vendasMesTotal;
  const projecao12m=mrr*12;
  const unidadesFaturadas=ativos.length;
  const clientesAtivos=_contratosSrc.length;
  // Contrato sem valor definido (cliente novo que entrou sozinho na lista) não
  // pode diluir o ticket médio — conta só quem tem valor fechado.
  const _valorDoContrato=function(c){
    if(c&&c.unidades)return c.unidades.reduce(function(s,u){return s+Number(u.valor||0);},0);
    return Number(c&&c.valor||0);
  };
  const clientesSemValor=_contratosSrc.filter(function(c){return _valorDoContrato(c)<=0;}).length;
  const clientesFaturados=clientesAtivos-clientesSemValor;
  const ticketCliente=clientesFaturados>0?mrr/clientesFaturados:0;
  const ticketUnidade=unidadesFaturadas>0?mrr/unidadesFaturadas:0;

  // ═══ Cálculos DRE em cascata ═══
  const _sum=function(arr){return (arr||[]).reduce(function(s,it){return s+Number(it.valor||0);},0);};
  const impostosTotal=useMemo(function(){return _sum(_custosImpostos.custos);},[_custosImpostos.custos]);
  const cspFixoTotal=useMemo(function(){return _sum(_custosCSP.custos);},[_custosCSP.custos]);
  const despDiretaTotal=useMemo(function(){return _sum(_custosDespDireta.custos);},[_custosDespDireta.custos]);
  const despOpTotal=useMemo(function(){return _sum(_custosDespOp.custos);},[_custosDespOp.custos]);
  const prolaboreTotal=useMemo(function(){return _sum(_custosProlabore.custos);},[_custosProlabore.custos]);
  const freelancersTotal=useMemo(function(){
    return (typeof TEAM!=="undefined"?TEAM:[]).filter(function(u){return u.pagamentoPorDemanda;}).reduce(function(s,u){
      const c=(typeof calcDesignerPayments==="function")?calcDesignerPayments(tasks||[],u.id,dreMonth):{total:0};
      return s+(c.total||0);
    },0);
  },[tasks,dreMonth]);
  const cspTotal=cspFixoTotal+freelancersTotal;
  const receitaLiquida=mrr-impostosTotal;
  const lucroBruto=receitaLiquida-cspTotal;
  const margemContribuicao=lucroBruto-despDiretaTotal;
  const pctMC=mrr>0?(margemContribuicao/mrr)*100:0;
  const isMCSaudavel=pctMC>=50;
  const lucroLiquido=margemContribuicao-despOpTotal;
  const custoFixoTotal=despOpTotal;
  const custoServirFixoTotal=cspFixoTotal;

  // Impostos
  const imposto=GF_IMPOSTOS_VALOR;
  const impostoPctAtual=mrr>0?imposto/mrr:0;

  // Caixinhas PJ (Reserva/Growth/Networking) — 1/3 do lucro líquido cada
  const caixinhaValor=Math.max(0,lucroLiquido/3);

  // Sócios (legacy, só pra Meta de margem)
  const _legacyProlaboreTotal=GF_SOCIOS.prolabore.reduce(function(s,p){return s+p.valor;},0);
  const lucrosTotal=GF_SOCIOS.lucros.reduce(function(s,p){return s+p.valor;},0);

  // Margem líquida = lucro líquido / receita — mesma métrica do card de Lucro Líquido
  const resultadoOp=lucroLiquido;
  const margemAntesImpostos=mrr>0?(mrr-cspTotal-custoFixoTotal)/mrr:0;
  const margemApos=mrr>0?resultadoOp/mrr:0;

  // ── Meta de margem 50% — modelo que ESCALA a produção junto com a receita ──
  // O modelo antigo assumia custo parado: bastava faturar mais. Na prática cada
  // real novo de entrega puxa mais produção (freelancers, CSP, mídia direta).
  //   · PRODUÇÃO (CSP + despesas diretas) cresce proporcional à receita:
  //     taxa v = (CSP + despDireta) / receita atual — é a "probabilidade" tirada
  //     do que gastamos HOJE pra entregar o que entregamos hoje;
  //   · ESTRUTURA (despesas operacionais) fica parada.
  //   Margem(R) = 1 - i - v - CF/R  →  R* = CF / (1 - i - v - meta)
  const _txProducao = mrr>0 ? (cspTotal+despDiretaTotal)/mrr : 0;
  const _denomInt = 1 - impostoPctAtual - _txProducao - GF_META_MARGEM_PCT;
  const metaAtingivel = _denomInt > 0.0001;
  const mrrNecessario = metaAtingivel ? custoFixoTotal/_denomInt : 0;
  const faltaVender = metaAtingivel ? Math.max(0, mrrNecessario-mrr) : 0;
  const gapMargem=(GF_META_MARGEM_PCT-margemApos)*100;
  const clientesAdic=(metaAtingivel&&ticketCliente>0)?Math.ceil(faltaVender/ticketCliente):0;
  // Quanto cada frente de produção cresce no cenário da meta (proporcional)
  const _fatorEscala=(metaAtingivel&&mrr>0&&mrrNecessario>mrr)?mrrNecessario/mrr:1;
  const custoExtraProducao=(cspTotal+despDiretaTotal)*(_fatorEscala-1);
  const _escalaItens=(function(){
    const itens=[];
    ((_custosCSP&&_custosCSP.custos)||[]).forEach(function(c){
      if(Number(c.valor)>0) itens.push({label:c.label||"Custo CSP", atual:Number(c.valor)});
    });
    if(freelancersTotal>0) itens.push({label:"Freelancers (pagamentos por demanda)", atual:freelancersTotal});
    if(despDiretaTotal>0) itens.push({label:"Despesas variáveis diretas", atual:despDiretaTotal});
    return itens.map(function(it){
      return Object.assign({},it,{futuro:it.atual*_fatorEscala, extra:it.atual*(_fatorEscala-1)});
    }).sort(function(a,b){return b.extra-a.extra;});
  })();

  // ── Helpers visuais ──
  const Block=function(props){
    return <section style={{background:"#fff",border:"1px solid #e2e8f0",borderRadius:14,padding:"14px 18px",display:"flex",flexDirection:"column",gap:10,...(props.style||{})}}>
      {props.children}
    </section>;
  };
  const BlockHeader=function(props){
    return <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:10,flexWrap:"wrap"}}>
      <div style={{display:"flex",alignItems:"center",gap:10}}>
        {props.ico&&<div style={{width:34,height:34,borderRadius:9,background:props.color+"15",display:"flex",alignItems:"center",justifyContent:"center"}}>
          <Ico n={props.ico} size={17} color={props.color}/>
        </div>}
        <div>
          <div style={{color:"#0f172a",fontWeight:800,fontSize:15,letterSpacing:-.2}}>{props.title}</div>
          {props.subtitle&&<div style={{color:"#64748b",fontSize:11.5,marginTop:1}}>{props.subtitle}</div>}
        </div>
      </div>
      {props.right}
    </div>;
  };
  // Big stat (usado em vários lugares)
  const BigStat=function(props){
    return <div style={{display:"flex",flexDirection:"column",gap:3,...(props.style||{})}}>
      <div style={{color:"#94a3b8",fontSize:10,fontWeight:700,textTransform:"uppercase",letterSpacing:.5}}>{props.label}</div>
      <div style={{color:props.color||"#0f172a",fontWeight:800,fontSize:props.size||22,letterSpacing:-.6,fontFeatureSettings:"'tnum'",lineHeight:1.15}}>{props.value}</div>
      {props.hint&&<div style={{color:"#94a3b8",fontSize:10.5}}>{props.hint}</div>}
    </div>;
  };

  return <div style={{display:"flex",flexDirection:"column",gap:12,fontFamily:"'Inter',system-ui,sans-serif",width:"100%"}}>

    {/* Header simples */}
    <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:12,flexWrap:"wrap"}}>
      <div style={{display:"flex",alignItems:"center",gap:11}}>
        <div style={{width:42,height:42,borderRadius:11,background:"#16a34a15",display:"flex",alignItems:"center",justifyContent:"center"}}>
          <Ico n="wallet" size={22} color="#16a34a"/>
        </div>
        <div>
          <div style={{color:"#0f172a",fontWeight:800,fontSize:22,letterSpacing:-.5}}>Financeiro</div>
          <div style={{color:"#64748b",fontSize:13,marginTop:2}}>Visão executiva da saúde financeira da Pixels.</div>
        </div>
      </div>
    </div>

    {/* ════ 1. CABEÇALHO EXECUTIVO — compacto (1 linha só) ════ */}
    <div style={{background:"linear-gradient(135deg,#0f172a,#1e293b)",borderRadius:14,padding:"16px 22px",color:"#fff",boxShadow:"0 6px 20px rgba(15,23,42,0.18)",display:"flex",alignItems:"center",justifyContent:"space-between",gap:14,flexWrap:"wrap"}}>
      <div style={{display:"flex",alignItems:"center",gap:24,flexWrap:"wrap"}}>
        <div>
          <div style={{fontSize:10,fontWeight:700,letterSpacing:.7,textTransform:"uppercase",opacity:.65,marginBottom:2}}>Receita do mês</div>
          <div style={{fontSize:26,fontWeight:800,letterSpacing:-.8,lineHeight:1,fontFeatureSettings:"'tnum'"}}>{_brl(mrr)}</div>
          {vendasMesTotal>0 && <div style={{fontSize:10.5,fontWeight:600,opacity:.65,marginTop:3,letterSpacing:.1}}>{_brl(mrrContrato)} contratos + {_brl(vendasMesTotal)} pontuais</div>}
        </div>
        <div style={{width:1,height:32,background:"rgba(255,255,255,0.12)"}}/>
        <div>
          <div style={{fontSize:10,fontWeight:700,letterSpacing:.7,textTransform:"uppercase",opacity:.65,marginBottom:2}}>MRR recorrente</div>
          <div style={{fontSize:22,fontWeight:800,letterSpacing:-.5,lineHeight:1,fontFeatureSettings:"'tnum'"}}>{_brl(mrrContrato)}<span style={{fontSize:11,fontWeight:600,opacity:.65,marginLeft:5}}>/mês</span></div>
        </div>
        <div style={{width:1,height:32,background:"rgba(255,255,255,0.12)"}}/>
        <div>
          <div style={{fontSize:10,fontWeight:700,letterSpacing:.7,textTransform:"uppercase",opacity:.65,marginBottom:2}}>Clientes</div>
          <div style={{fontSize:22,fontWeight:800,letterSpacing:-.5,lineHeight:1,fontFeatureSettings:"'tnum'"}}>{clientesAtivos}</div>
        </div>
        <div style={{width:1,height:32,background:"rgba(255,255,255,0.12)"}}/>
        <div>
          <div style={{fontSize:10,fontWeight:700,letterSpacing:.7,textTransform:"uppercase",opacity:.65,marginBottom:2}}>Ticket médio</div>
          <div style={{fontSize:22,fontWeight:800,letterSpacing:-.5,lineHeight:1,fontFeatureSettings:"'tnum'"}}>{_brl(ticketCliente)}</div>
        </div>
      </div>
      <span style={{background:margemApos>=GF_META_MARGEM_PCT?"#22c55e22":"#fbbf2422",color:margemApos>=GF_META_MARGEM_PCT?"#86efac":"#fde047",borderRadius:99,padding:"6px 14px",fontSize:11,fontWeight:800,letterSpacing:.3,textTransform:"uppercase",border:"1px solid "+(margemApos>=GF_META_MARGEM_PCT?"#22c55e44":"#fbbf2444")}}>
        Margem {_pct(margemApos*100)}
      </span>
    </div>

    {/* ════ 2b. VENDAS PONTUAIS DO MÊS — antes da DRE, soma no MRR ════ */}
    {(function(){
      const vendasAll = (typeof _vpLoad==="function") ? _vpLoad() : [];
      const vendasMes = vendasAll.filter(function(v){return String(v.mes_ref||"")===dreMonth;});
      const totalVendasMes = vendasMes.reduce(function(s,v){return s+Number(v.valor||0);},0);
      if(vendasMes.length===0 && totalVendasMes===0) return null;
      // Agrupa por cliente
      const byClient = {};
      vendasMes.forEach(function(v){ if(!byClient[v.cliente_id]) byClient[v.cliente_id]=[]; byClient[v.cliente_id].push(v); });
      return <Block>
        <BlockHeader ico="sparkles" color="#7c3aed" title="Vendas pontuais do mês" subtitle="Captações, projetos avulsos e extras — soma automática ao MRR"/>
        <div style={{display:"grid",gridTemplateColumns:isMob?"1fr":"repeat(auto-fill,minmax(240px,1fr))",gap:10}}>
          {Object.keys(byClient).map(function(cid){
            const arr = byClient[cid];
            const totalC = arr.reduce(function(s,v){return s+Number(v.valor||0);},0);
            const cli = (typeof CLIENTS!=="undefined"?CLIENTS:[]).find(function(c){return c.id===cid;});
            return <div key={cid} style={{background:"#faf5ff",border:"1px solid #e9d5ff",borderRadius:11,padding:"12px 14px"}}>
              <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:8,marginBottom:6}}>
                <div style={{color:"#0f172a",fontWeight:800,fontSize:13,letterSpacing:-.2}}>{cli?cli.name:cid}</div>
                <div style={{color:"#7c3aed",fontWeight:800,fontSize:14,letterSpacing:-.3,fontFeatureSettings:"'tnum'"}}>{_brlF(totalC)}</div>
              </div>
              {arr.map(function(v){
                return <div key={v.id} style={{display:"flex",justifyContent:"space-between",gap:6,fontSize:11,color:"#64748b",padding:"3px 0"}}>
                  <span style={{overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{v.descricao}</span>
                  {arr.length>1 && <span style={{fontFeatureSettings:"'tnum'",flexShrink:0}}>{_brlF(v.valor)}</span>}
                </div>;
              })}
            </div>;
          })}
        </div>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",gap:10,paddingTop:10,borderTop:"1px dashed #e9d5ff"}}>
          <div style={{color:"#7c3aed",fontSize:11,fontWeight:800,textTransform:"uppercase",letterSpacing:.5}}>Total pontual do mês</div>
          <div style={{color:"#7c3aed",fontWeight:800,fontSize:18,letterSpacing:-.4,fontFeatureSettings:"'tnum'"}}>{_brlF(totalVendasMes)}</div>
        </div>
      </Block>;
    })()}

    {/* ════ 3. DRE — DEMONSTRAÇÃO DO RESULTADO ════ */}
    <section style={{background:"#fff",border:"1px solid #e2e8f0",borderRadius:14,padding:"22px 26px",display:"flex",flexDirection:"column",gap:16}}>
      <BlockHeader ico="funnel" color="#0f172a" title="DRE — Demonstração do resultado" subtitle="Da receita bruta até o lucro líquido, com cada dedução explícita" right={
        <div style={{display:"inline-flex",alignItems:"center",background:"#fff",border:"1px solid #e2e8f0",borderRadius:11,padding:3,boxShadow:"0 1px 2px rgba(15,23,42,0.03)"}}>
          <button type="button" title="Mês anterior" onClick={function(){_dreShift(-1);}}
            style={{background:"transparent",border:"none",borderRadius:8,width:28,height:28,display:"inline-flex",alignItems:"center",justifyContent:"center",cursor:"pointer",color:"#64748b",transition:"all .12s"}}
            onMouseEnter={function(e){e.currentTarget.style.background="#f1f5f9";e.currentTarget.style.color="#0f172a";}}
            onMouseLeave={function(e){e.currentTarget.style.background="transparent";e.currentTarget.style.color="#64748b";}}>
            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><polyline points="15 18 9 12 15 6"/></svg>
          </button>
          <div style={{padding:"0 12px",minWidth:140,textAlign:"center",fontSize:12,fontWeight:700,color:"#0f172a",letterSpacing:-.1,fontFeatureSettings:"'tnum'"}}>{_dreLabel(dreMonth)}</div>
          <button type="button" title="Próximo mês" onClick={function(){_dreShift(1);}}
            style={{background:"transparent",border:"none",borderRadius:8,width:28,height:28,display:"inline-flex",alignItems:"center",justifyContent:"center",cursor:"pointer",color:"#64748b",transition:"all .12s"}}
            onMouseEnter={function(e){e.currentTarget.style.background="#f1f5f9";e.currentTarget.style.color="#0f172a";}}
            onMouseLeave={function(e){e.currentTarget.style.background="transparent";e.currentTarget.style.color="#64748b";}}>
            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><polyline points="9 18 15 12 9 6"/></svg>
          </button>
        </div>
      }/>

      {/* Arco-íris coerente: vermelho → laranja → âmbar → verde-lima → teal → ciano → azul → índigo → roxo */}
      <_DRELinha kind="header" pos="1." label="Receita total" valor={mrr} cor="#ef4444" isMob={isMob} subtitle={vendasMesTotal>0
        ? _brlF(mrrContrato)+" MRR ("+clientesAtivos+" clientes) + "+_brlF(vendasMesTotal)+" em vendas pontuais"
        : "MRR de "+clientesAtivos+" clientes · vendas pontuais do mês entram automaticamente"}/>

      <_DRESecao pos="2." op="−" label="Impostos e deduções" total={impostosTotal} cor="#f97316" state={_custosImpostos} isSocio={_isSocio} brl={_brlF} isMob={isMob}/>

      <_DRELinha kind="subtotal" pos="3." op="=" label="Receita líquida" valor={receitaLiquida} cor="#f59e0b" isMob={isMob}/>

      <_DRESecao pos="4." op="−" label="CSP (Custo do Serviço Prestado)" total={cspTotal} cor="#84cc16" state={_custosCSP} isSocio={_isSocio} brl={_brlF} isMob={isMob} defaultExpanded={true}
        extra={{label:"Freelancers do mês (cálculo auto)", valor:freelancersTotal, hint:"Via Pagamentos por demanda"}}
        extraBottom={<div style={{padding:"12px 16px",background:"#f7fee7",borderLeft:"3px solid #84cc16",borderRadius:8}}>
          <FreelancerPaymentsBlock tasks={tasks||[]} setTasks={setTasks} refMonth={dreMonth} onChangeMonth={setDreMonth} isMob={isMob} compact={true}/>
        </div>}
      />

      <_DRELinha kind="subtotal" pos="5." op="=" label="Lucro bruto" valor={lucroBruto} cor="#14b8a6" isMob={isMob}/>

      <_DRESecao pos="6." op="−" label="Despesas variáveis diretas" total={despDiretaTotal} cor="#06b6d4" subtitle="Mídia vinculada ao projeto, ferramentas, comissões, terceirizações pontuais, taxas e deslocamentos." state={_custosDespDireta} isSocio={_isSocio} brl={_brlF} isMob={isMob}/>

      <div style={{background:"transparent",borderTop:"1px dashed #e2e8f0",padding:"12px 16px",display:"flex",alignItems:"center",justifyContent:"space-between",gap:12,flexWrap:"wrap"}}>
        <div style={{display:"flex",alignItems:"center",gap:10}}>
          <span style={{background:"#3b82f6",color:"#fff",fontSize:12,fontWeight:800,width:32,height:32,borderRadius:8,display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0,fontFeatureSettings:"'tnum'"}}>7.</span>
          <span style={{color:"#3b82f6",fontWeight:800,fontSize:16,width:14,textAlign:"center",flexShrink:0}}>=</span>
          <div>
            <div style={{color:"#0f172a",fontSize:14,fontWeight:800,letterSpacing:-.2}}>Margem de contribuição</div>
            <div style={{color:isMCSaudavel?"#1d4ed8":"#a16207",fontSize:11.5,fontWeight:700,marginTop:1,display:"inline-flex",alignItems:"center",gap:5}}>
              <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round">
                {isMCSaudavel?<polyline points="20 6 9 17 4 12"/>:<><circle cx="12" cy="12" r="10"/><path d="M12 8v4M12 16h.01"/></>}
              </svg>
              {isMCSaudavel?"Saudável — acima de 50%":"Abaixo de 50% — atenção"}
            </div>
          </div>
        </div>
        <div style={{textAlign:"right",paddingRight:26}}>
          <div style={{color:"#3b82f6",fontWeight:800,fontSize:22,letterSpacing:-.6,fontFeatureSettings:"'tnum'",lineHeight:1}}>{_brlF(margemContribuicao)}</div>
          <div style={{color:"#64748b",fontSize:11,fontWeight:700,marginTop:3,fontFeatureSettings:"'tnum'"}}>{_pct(pctMC)}</div>
        </div>
      </div>

      <_DRESecao pos="8." op="−" label="Despesas operacionais" total={despOpTotal} cor="#6366f1" subtitle="Salários fixos, contabilidade, softwares, treinamentos, plano de saúde" state={_custosDespOp} isSocio={_isSocio} brl={_brlF} isMob={isMob}/>


      <div style={{background:lucroLiquido>=0?"linear-gradient(135deg,#7e22ce,#c026d3)":"linear-gradient(135deg,#0f172a,#7f1d1d)",borderRadius:12,padding:"18px 22px",color:"#fff",display:"flex",alignItems:"center",justifyContent:"space-between",gap:12,flexWrap:"wrap",boxShadow:"0 10px 30px rgba(126,34,206,0.25)"}}>
        <div style={{display:"flex",alignItems:"center",gap:14}}>
          <span style={{background:"rgba(255,255,255,0.14)",color:"#fff",fontSize:16,fontWeight:800,width:40,height:40,borderRadius:11,display:"inline-flex",alignItems:"center",justifyContent:"center",border:"1px solid rgba(255,255,255,0.2)"}}>=</span>
          <div>
            <div style={{color:"#fff",fontSize:11,fontWeight:800,letterSpacing:.5,textTransform:"uppercase",opacity:.75}}>9 · Resultado do exercício</div>
            <div style={{color:"#fff",fontSize:16,fontWeight:800,letterSpacing:-.3,marginTop:2}}>{lucroLiquido>=0?"Lucro líquido":"Prejuízo do período"}</div>
          </div>
        </div>
        <div style={{textAlign:"right",paddingRight:26}}>
          <div style={{color:"#fff",fontWeight:800,fontSize:22,letterSpacing:-.6,fontFeatureSettings:"'tnum'",lineHeight:1}}>{_brlF(lucroLiquido)}</div>
          <div style={{color:"#fff",opacity:.65,fontSize:11,fontWeight:600,marginTop:4,fontFeatureSettings:"'tnum'"}}>{mrr>0?_pct((lucroLiquido/mrr)*100)+" margem líquida":"—"}</div>
        </div>
      </div>

      {/* ════ 11. CAIXINHAS PJ NUBANK — divisão igual do lucro líquido ════ */}
      {lucroLiquido>0 && (function(){
        const _caixinhas=[
          {id:"reserva",   nome:"Reserva de caixa", sub:"Fundo de emergência · 3-6 meses de custo", ico:"lock"},
          {id:"growth",    nome:"Growth",           sub:"Investimento em crescimento · ads, ferramentas, contratação", ico:"trending-up"},
          {id:"networking",nome:"Networking",       sub:"Eventos, mentorias, viagens, relacionamento", ico:"users"},
        ];
        return <div style={{marginTop:14,paddingTop:16,borderTop:"1px dashed #e9d5ff"}}>
          <div style={{display:"flex",alignItems:"center",gap:9,marginBottom:12}}>
            <div style={{width:26,height:26,borderRadius:7,background:"linear-gradient(135deg,#7c3aed,#c026d3)",display:"flex",alignItems:"center",justifyContent:"center"}}>
              <Ico n="wallet" size={13} color="#fff"/>
            </div>
            <div style={{flex:1,minWidth:0}}>
              <div style={{color:"#0f172a",fontWeight:800,fontSize:13,letterSpacing:-.2}}>Destinação do lucro · Caixinhas PJ Nubank</div>
              <div style={{color:"#64748b",fontSize:11,marginTop:1}}>Lucro dividido igualmente entre 3 investimentos · <span style={{color:"#7c3aed",fontWeight:700}}>33,33% cada</span></div>
            </div>
          </div>
          <div style={{display:"grid",gridTemplateColumns:isMob?"1fr":"repeat(3,1fr)",gap:10}}>
            {_caixinhas.map(function(cx){
              return <div key={cx.id} style={{background:"linear-gradient(135deg,#7e22ce,#c026d3)",borderRadius:12,padding:"14px 16px",color:"#fff",boxShadow:"0 8px 22px rgba(124,58,237,0.22)",position:"relative",overflow:"hidden"}}>
                <div style={{position:"absolute",top:-30,right:-30,width:110,height:110,borderRadius:"50%",background:"radial-gradient(circle,rgba(255,255,255,0.10),transparent 65%)",pointerEvents:"none"}}/>
                <div style={{position:"relative",display:"flex",alignItems:"center",gap:9,marginBottom:9}}>
                  <div style={{width:30,height:30,borderRadius:8,background:"rgba(255,255,255,0.16)",display:"flex",alignItems:"center",justifyContent:"center",border:"1px solid rgba(255,255,255,0.20)"}}>
                    <Ico n={cx.ico} size={14} color="#fff"/>
                  </div>
                  <div style={{flex:1,minWidth:0}}>
                    <div style={{color:"#fff",fontWeight:800,fontSize:13,letterSpacing:-.2,lineHeight:1.2}}>{cx.nome}</div>
                    <div style={{color:"#fff",opacity:.65,fontSize:10,fontWeight:700,marginTop:1,letterSpacing:.3,textTransform:"uppercase"}}>33,33% do lucro</div>
                  </div>
                </div>
                <div style={{position:"relative",color:"#fff",fontWeight:800,fontSize:22,letterSpacing:-.6,fontFeatureSettings:"'tnum'",lineHeight:1}}>{_brlF(caixinhaValor)}</div>
                <div style={{position:"relative",color:"#fff",opacity:.60,fontSize:10.5,marginTop:5,lineHeight:1.4}}>{cx.sub}</div>
              </div>;
            })}
          </div>
        </div>;
      })()}
    </section>

    {/* ════ 7a. GRÁFICO EVOLUÇÃO DRE ════ */}
    <_DREEvolucaoChart dreMonth={dreMonth} isMob={isMob} cores={{imposto:"#f97316", csp:"#84cc16", despDir:"#06b6d4", despOp:"#6366f1", prolabore:"#a855f7"}}/>

    {/* ════ 7b. RECEITA E CARTEIRA — depois da DRE, contexto complementar ════ */}
    <Block>
      <BlockHeader ico="chart" color="#16a34a" title="Receita e carteira" subtitle="Recorrência, projeção e qualidade do faturamento"/>
      <div style={{display:"grid",gridTemplateColumns:isMob?"1fr 1fr":"repeat(3,1fr)",gap:14}}>
        <BigStat label="MRR atual"       value={_brl(mrr)}        color="#16a34a"/>
        <BigStat label="Receita do mês"  value={_brl(mrr)}        color="#0d9488"/>
        <BigStat label="Projeção 12m"    value={_brl(projecao12m)} color="#7c3aed"/>
      </div>
    </Block>

        {/* ════ 8. META DE MARGEM 50% — bloco destaque clean ════ */}
    <section style={{background:"#fff",border:"1px solid #e2e8f0",borderRadius:14,padding:"22px 26px",display:"flex",flexDirection:"column",gap:20,position:"relative",overflow:"hidden"}}>
      {/* Acento sutil no canto */}
      <div style={{position:"absolute",top:-40,right:-40,width:180,height:180,borderRadius:"50%",background:"radial-gradient(circle,#ede9fe,transparent 70%)",pointerEvents:"none"}}/>

      {/* Header */}
      <div style={{display:"flex",alignItems:"flex-start",justifyContent:"space-between",gap:14,flexWrap:"wrap",position:"relative"}}>
        <div style={{display:"flex",alignItems:"center",gap:11}}>
          <div style={{width:38,height:38,borderRadius:10,background:"linear-gradient(135deg,#7c3aed,#a855f7)",display:"flex",alignItems:"center",justifyContent:"center",boxShadow:"0 4px 12px rgba(124,58,237,0.25)"}}>
            <Ico n="sparkles" size={18} color="#fff"/>
          </div>
          <div>
            <div style={{color:"#0f172a",fontWeight:800,fontSize:15,letterSpacing:-.2}}>Meta de margem 50%</div>
            <div style={{color:"#64748b",fontSize:11.5,marginTop:1}}>Quanto faturar pra chegar lá — já contando que a produção cresce junto com a entrega</div>
          </div>
        </div>
        <span style={{background:margemApos>=GF_META_MARGEM_PCT?"#dcfce7":"#fef3c7",color:margemApos>=GF_META_MARGEM_PCT?"#15803d":"#a16207",padding:"5px 12px",borderRadius:99,fontSize:10.5,fontWeight:800,letterSpacing:.4,textTransform:"uppercase",border:"1px solid "+(margemApos>=GF_META_MARGEM_PCT?"#86efac":"#fde047")}}>
          {margemApos>=GF_META_MARGEM_PCT?"Meta batida":"Em construção"}
        </span>
      </div>

      {/* Visualização principal: Atual vs Meta */}
      <div style={{display:"flex",alignItems:"flex-end",gap:18,padding:"14px 4px 0",position:"relative"}}>
        <div style={{flex:1}}>
          <div style={{color:"#94a3b8",fontSize:10,fontWeight:700,textTransform:"uppercase",letterSpacing:.5,marginBottom:4}}>Margem atual</div>
          <div style={{color:"#7c3aed",fontWeight:800,fontSize:36,letterSpacing:-1.2,lineHeight:1,fontFeatureSettings:"'tnum'"}}>{_pct(margemApos*100)}</div>
        </div>
        <div style={{flex:"0 0 auto",display:"flex",alignItems:"center",gap:6,paddingBottom:8}}>
          <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#cbd5e1" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="5" y1="12" x2="19" y2="12"/><polyline points="12 5 19 12 12 19"/></svg>
        </div>
        <div style={{flex:1,textAlign:"right"}}>
          <div style={{color:"#94a3b8",fontSize:10,fontWeight:700,textTransform:"uppercase",letterSpacing:.5,marginBottom:4}}>Meta</div>
          <div style={{color:"#0f172a",fontWeight:800,fontSize:36,letterSpacing:-1.2,lineHeight:1,fontFeatureSettings:"'tnum'"}}>{_pct(GF_META_MARGEM_PCT*100)}</div>
        </div>
      </div>

      {/* Barra de progresso elegante */}
      <div style={{position:"relative"}}>
        <div style={{background:"#f1f5f9",borderRadius:99,height:8,overflow:"hidden"}}>
          <div style={{width:Math.min(100,Math.max(2,(margemApos/GF_META_MARGEM_PCT)*100))+"%",height:"100%",background:"linear-gradient(90deg,#a855f7,#7c3aed)",borderRadius:99,transition:"width .3s",boxShadow:"0 1px 4px rgba(124,58,237,0.4)"}}/>
        </div>
        <div style={{display:"flex",justifyContent:"space-between",marginTop:6,fontSize:10.5,color:"#94a3b8",fontWeight:600}}>
          <span>{Math.round((margemApos/GF_META_MARGEM_PCT)*100)}% do caminho</span>
          <span>Gap: <strong style={{color:"#7c3aed"}}>{gapMargem.toFixed(1)} pp</strong></span>
        </div>
      </div>

      {/* 3 KPIs em cards limpos */}
      <div style={{display:"grid",gridTemplateColumns:isMob?"1fr":"repeat(3,1fr)",gap:12,position:"relative"}}>
        <div style={{background:"#fafbfc",border:"1px solid #f1f5f9",borderRadius:11,padding:"14px 16px"}}>
          <div style={{color:"#94a3b8",fontSize:10,fontWeight:700,textTransform:"uppercase",letterSpacing:.5,marginBottom:4}}>MRR necessário</div>
          <div style={{color:"#0f172a",fontWeight:800,fontSize:22,letterSpacing:-.5,fontFeatureSettings:"'tnum'",lineHeight:1.1}}>{metaAtingivel?_brl(mrrNecessario):"—"}</div>
          <div style={{color:"#64748b",fontSize:10.5,marginTop:3}}>{metaAtingivel?"produção escalada junto":"meta não fecha só com escala"}</div>
        </div>
        <div style={{background:"#fafbfc",border:"1px solid #f1f5f9",borderRadius:11,padding:"14px 16px"}}>
          <div style={{color:"#94a3b8",fontSize:10,fontWeight:700,textTransform:"uppercase",letterSpacing:.5,marginBottom:4}}>Falta vender</div>
          <div style={{color:"#7c3aed",fontWeight:800,fontSize:22,letterSpacing:-.5,fontFeatureSettings:"'tnum'",lineHeight:1.1}}>{_brl(faltaVender)}</div>
          <div style={{color:"#64748b",fontSize:10.5,marginTop:3}}>por mês</div>
        </div>
        <div style={{background:"linear-gradient(135deg,#faf5ff,#f3e8ff)",border:"1px solid #e9d5ff",borderRadius:11,padding:"14px 16px"}}>
          <div style={{color:"#7c3aed",fontSize:10,fontWeight:700,textTransform:"uppercase",letterSpacing:.5,marginBottom:4,display:"flex",alignItems:"center",gap:5}}>
            <Ico n="users" size={11} color="#7c3aed"/> Clientes a vender
          </div>
          <div style={{color:"#7c3aed",fontWeight:800,fontSize:22,letterSpacing:-.5,fontFeatureSettings:"'tnum'",lineHeight:1.1}}>+{clientesAdic}</div>
          <div style={{color:"#64748b",fontSize:10.5,marginTop:3}}>ticket médio {_brl(ticketCliente)}</div>
        </div>
      </div>

      {/* ── A conta honesta: quanto a produção cresce até a meta ── */}
      {!metaAtingivel
        ? <div style={{background:"#fffbeb",border:"1px solid #fde68a",borderRadius:11,padding:"14px 16px",display:"flex",gap:11,alignItems:"flex-start"}}>
            <Ico n="alertTriangle" size={16} color="#b45309"/>
            <div style={{color:"#92400e",fontSize:12,lineHeight:1.6}}>
              <strong>Só faturar mais não chega na meta.</strong> Hoje a produção consome <strong>{_pct(_txProducao*100)}</strong> de cada real entregue
              (+{_pct(impostoPctAtual*100)} de imposto). Sobra menos de {_pct(GF_META_MARGEM_PCT*100)} antes da estrutura — em qualquer faturamento.
              O caminho é baratear a entrega: ticket maior pelo mesmo escopo, produção mais eficiente ou reajuste de contratos.
            </div>
          </div>
        : (_fatorEscala>1.001&&_escalaItens.length>0)&&<div style={{background:"#fafbfc",border:"1px solid #f1f5f9",borderRadius:12,padding:"14px 16px"}}>
            <div style={{display:"flex",alignItems:"baseline",justifyContent:"space-between",gap:10,flexWrap:"wrap",marginBottom:10}}>
              <div style={{color:"#0f172a",fontSize:12.5,fontWeight:800,letterSpacing:-.2,display:"inline-flex",alignItems:"center",gap:7}}>
                <Ico n="users" size={13} color="#7c3aed"/> O time cresce junto — produção estimada na meta
              </div>
              <span style={{color:"#64748b",fontSize:10.5,fontWeight:700,fontFeatureSettings:"'tnum'"}}>
                estimativa proporcional: cada R$ 1 entregue custa {_pct(_txProducao*100)} de produção hoje
              </span>
            </div>
            <div style={{display:"flex",flexDirection:"column",gap:6}}>
              {_escalaItens.map(function(it,i){
                return <div key={i} style={{display:"flex",alignItems:"center",gap:10,padding:"7px 10px",background:"#fff",border:"1px solid #f1f5f9",borderRadius:9}}>
                  <span style={{color:"#334155",fontSize:11.5,fontWeight:700,flex:1,minWidth:0,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{it.label}</span>
                  <span style={{color:"#94a3b8",fontSize:11,fontFeatureSettings:"'tnum'",whiteSpace:"nowrap"}}>{_brl(it.atual)}</span>
                  <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="#cbd5e1" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" style={{flexShrink:0}}><line x1="5" y1="12" x2="19" y2="12"/><polyline points="12 5 19 12 12 19"/></svg>
                  <span style={{color:"#0f172a",fontSize:11.5,fontWeight:800,fontFeatureSettings:"'tnum'",whiteSpace:"nowrap"}}>{_brl(it.futuro)}</span>
                  <span style={{background:"#faf5ff",color:"#7c3aed",fontSize:10,fontWeight:800,padding:"2px 8px",borderRadius:99,fontFeatureSettings:"'tnum'",whiteSpace:"nowrap"}}>+{_brl(it.extra)}</span>
                </div>;
              })}
            </div>
            <div style={{color:"#64748b",fontSize:10.5,marginTop:10,lineHeight:1.55,paddingTop:9,borderTop:"1px dashed #e2e8f0"}}>
              No MRR da meta ({_brl(mrrNecessario)}), a produção total sobe <strong style={{color:"#7c3aed"}}>+{_brl(custoExtraProducao)}/mês</strong> — a estrutura fixa ({_brl(custoFixoTotal)}) fica parada. É estimativa proporcional ao custo atual por entrega; contratação real acontece em degraus.
            </div>
          </div>}
    </section>

    {/* ════ 9. CONTRATOS ATIVOS — cards grandes coloridos com logo ════ */}
    <Block>
      <BlockHeader ico="fileText" color="#475569" title="Contratos ativos" subtitle={clientesAtivos+" clientes · MRR "+_brl(mrrContrato)+(vendasMesTotal>0?" · +"+_brl(vendasMesTotal)+" pontuais":"")+(clientesSemValor>0?" · "+clientesSemValor+" sem valor definido":"")}/>
      <div style={{display:"flex",alignItems:"center",gap:9,flexWrap:"wrap",background:"#f8fafc",border:"1px solid #eef0f4",borderRadius:11,padding:"9px 13px",marginBottom:12}}>
        <span style={{color:"#64748b",fontSize:11.5,fontWeight:500,flex:1,minWidth:180}}>Esta lista alimenta o DRE. O cadastro do contrato — valor, produto, cobrança e NFSe — é editado no Comercial.</span>
        <button type="button" onClick={_gfIrParaComercial}
          style={{background:"#0f172a",color:"#fff",border:"none",borderRadius:9,padding:"7px 13px",fontSize:11.5,fontWeight:800,cursor:"pointer",fontFamily:"inherit",display:"inline-flex",alignItems:"center",gap:6,flexShrink:0}}>
          Editar no Comercial
          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round"><line x1="5" y1="12" x2="19" y2="12"/><polyline points="12 5 19 12 12 19"/></svg>
        </button>
      </div>
      <div style={{display:"grid",gridTemplateColumns:isMob?"1fr":"repeat(auto-fill,minmax(300px,1fr))",gap:12}}>
        {contratos.map(function(c,idx){
          // Resolve cliente real pra pegar logo
          const clKey=(c.grupo||"").toLowerCase().split(" ")[0];
          const realCl=(typeof CLIENTS!=="undefined"?CLIENTS:[]).find(function(x){return x.id===clKey||(x.name||"").toLowerCase().startsWith(clKey);});
          const logoUrl=realCl&&typeof CLIENT_LOGOS!=="undefined"?CLIENT_LOGOS[realCl.id]:null;

          if(c.grupoEcon&&c.unidades){
            const totalGrupo=c.unidades.reduce(function(s,u){return s+u.valor;},0);
            const ativosGrupo=c.unidades.filter(function(u){return u.valor>0;}).length;
            const expanded=contratosExpand[c.grupo]!==false;
            return <div key={idx} style={{background:"linear-gradient(135deg,"+c.cor+"06,"+c.cor+"12)",border:"1px solid "+c.cor+"33",borderRadius:14,overflow:"hidden",display:"flex",flexDirection:"column",transition:"transform .15s, box-shadow .15s"}}
              onMouseEnter={function(e){e.currentTarget.style.transform="translateY(-1px)";e.currentTarget.style.boxShadow="0 6px 20px "+c.cor+"22";}}
              onMouseLeave={function(e){e.currentTarget.style.transform="none";e.currentTarget.style.boxShadow="none";}}>
              <div onClick={function(){setContratosExpand(function(p){return Object.assign({},p,{[c.grupo]:!expanded});});}}
                style={{padding:"14px 16px",cursor:"pointer",display:"flex",flexDirection:"column",gap:10}}>
                {/* Linha topo: logo + nome + chevron */}
                <div style={{display:"flex",alignItems:"center",gap:11}}>
                  <div style={{width:48,height:48,borderRadius:12,background:"#fff",border:"1px solid "+c.cor+"22",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0,overflow:"hidden",boxShadow:"0 1px 4px rgba(15,23,42,0.06)"}}>
                    {logoUrl?<img src={logoUrl} alt={c.grupo} style={{maxWidth:38,maxHeight:38,objectFit:"contain"}}/>:<span style={{color:c.cor,fontWeight:900,fontSize:18,letterSpacing:-.4}}>{c.grupo.charAt(0)}</span>}
                  </div>
                  <div style={{flex:1,minWidth:0}}>
                    <div style={{color:"#0f172a",fontWeight:800,fontSize:15,letterSpacing:-.2,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{c.grupo}</div>
                    <div style={{color:c.cor,fontSize:10.5,fontWeight:700,marginTop:1,textTransform:"uppercase",letterSpacing:.4}}>Grupo · {ativosGrupo} unidades</div>
                  </div>
                  <span style={{color:c.cor,fontSize:14,fontWeight:800,transform:expanded?"rotate(90deg)":"rotate(0)",transition:"transform .2s"}}>›</span>
                </div>
                {/* MRR grande */}
                <div style={{display:"flex",alignItems:"baseline",gap:6,paddingTop:6,borderTop:"1px solid "+c.cor+"1c"}}>
                  <span style={{color:c.cor,fontWeight:900,fontSize:22,letterSpacing:-.6,fontFeatureSettings:"'tnum'",lineHeight:1}}>{_brl(totalGrupo)}</span>
                  <span style={{color:"#64748b",fontSize:11,fontWeight:600}}>/mês</span>
                </div>
              </div>
              {expanded&&<div style={{padding:"4px 16px 12px",background:"rgba(255,255,255,0.6)"}}>
                {c.unidades.map(function(u,j){
                  return <div key={j} onClick={function(e){e.stopPropagation();_gfIrParaComercial();}} style={{padding:"7px 0",borderBottom:j<c.unidades.length-1?"1px dashed "+c.cor+"22":"none",display:"flex",alignItems:"center",justifyContent:"space-between",gap:10,cursor:"pointer",borderRadius:6,paddingLeft:6,paddingRight:6,marginLeft:-6,marginRight:-6,transition:"background .12s"}}
                    onMouseEnter={function(e){e.currentTarget.style.background=c.cor+"0d";}}
                    onMouseLeave={function(e){e.currentTarget.style.background="transparent";}}>
                    <div style={{display:"flex",alignItems:"center",gap:8,minWidth:0,flex:1}}>
                      <div style={{width:6,height:6,borderRadius:"50%",background:u.valor>0?c.cor:"#cbd5e1",flexShrink:0}}/>
                      <span style={{color:"#0f172a",fontSize:12,fontWeight:600}}>{u.nome}</span>
                      {u.pagDia&&u.valor>0&&<span style={{color:"#94a3b8",fontSize:10,fontWeight:600}}>· dia {u.pagDia}</span>}
                      {u.valor===0&&<span style={{background:"#f1f5f9",color:"#94a3b8",fontSize:9,fontWeight:700,padding:"1px 6px",borderRadius:99,letterSpacing:.3,textTransform:"uppercase"}}>—</span>}
                    </div>
                    <div style={{color:u.valor>0?"#0f172a":"#94a3b8",fontWeight:700,fontSize:12,fontFeatureSettings:"'tnum'"}}>{u.valor>0?_brl(u.valor):"—"}</div>
                  </div>;
                })}
              </div>}
            </div>;
          }
          // Cliente individual (sem unidades) — clicável pra editar
          return <div key={idx} onClick={function(){_gfIrParaComercial();}} style={{background:"linear-gradient(135deg,"+c.cor+"06,"+c.cor+"12)",border:"1px solid "+c.cor+"33",borderRadius:14,padding:"14px 16px",display:"flex",flexDirection:"column",gap:10,transition:"transform .15s, box-shadow .15s",cursor:"pointer"}}
            onMouseEnter={function(e){e.currentTarget.style.transform="translateY(-1px)";e.currentTarget.style.boxShadow="0 6px 20px "+c.cor+"22";}}
            onMouseLeave={function(e){e.currentTarget.style.transform="none";e.currentTarget.style.boxShadow="none";}}>
            <div style={{display:"flex",alignItems:"center",gap:11}}>
              <div style={{width:48,height:48,borderRadius:12,background:"#fff",border:"1px solid "+c.cor+"22",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0,overflow:"hidden",boxShadow:"0 1px 4px rgba(15,23,42,0.06)"}}>
                {logoUrl?<img src={logoUrl} alt={c.grupo} style={{maxWidth:38,maxHeight:38,objectFit:"contain"}}/>:<span style={{color:c.cor,fontWeight:900,fontSize:18,letterSpacing:-.4}}>{c.grupo.charAt(0)}</span>}
              </div>
              <div style={{flex:1,minWidth:0}}>
                <div style={{color:"#0f172a",fontWeight:800,fontSize:15,letterSpacing:-.2,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{c.grupo}</div>
                <div style={{color:c.cor,fontSize:10.5,fontWeight:700,marginTop:1,textTransform:"uppercase",letterSpacing:.4}}>Cliente único</div>
              </div>
              <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke={c.cor} strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" style={{opacity:.5}}><path d="M12 20h9"/><path d="M16.5 3.5a2.121 2.121 0 113 3L7 19l-4 1 1-4L16.5 3.5z"/></svg>
            </div>
            <div style={{display:"flex",alignItems:"baseline",gap:6,paddingTop:6,borderTop:"1px solid "+c.cor+"1c",flexWrap:"wrap"}}>
              {Number(c.valor)>0
                ? <><span style={{color:c.cor,fontWeight:900,fontSize:22,letterSpacing:-.6,fontFeatureSettings:"'tnum'",lineHeight:1}}>{_brl(c.valor)}</span>
                    <span style={{color:"#64748b",fontSize:11,fontWeight:600}}>/mês</span></>
                : <span title="Editar em Comercial › Contratos" style={{background:"#fef3c7",color:"#92400e",fontSize:11,fontWeight:800,padding:"5px 11px",borderRadius:99,display:"inline-flex",alignItems:"center",gap:6}}>
                    <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round"><path d="M12 9v4"/><path d="M12 17h.01"/><circle cx="12" cy="12" r="10"/></svg>
                    Definir valor do contrato
                  </span>}
            </div>
            {/* Metadados do contrato — badges modernos */}
            <div style={{display:"flex",gap:6,flexWrap:"wrap",paddingTop:6,borderTop:"1px dashed "+c.cor+"1c"}}>
              {c.pagDia&&<span style={{background:"#f1f5f9",color:"#0f172a",fontSize:10,fontWeight:700,padding:"3px 9px",borderRadius:99,display:"inline-flex",alignItems:"center",gap:4}}>
                <svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>
                dia {c.pagDia}</span>}
              {c.metodoPag&&<span style={{background:"#eff6ff",color:"#1d4ed8",fontSize:10,fontWeight:700,padding:"3px 9px",borderRadius:99}}>{c.metodoPag}</span>}
              {/* Quantos avisos de cobranca/NFSe estao programados */}
              {Array.isArray(c.envios)&&c.envios.length>0&&<span title={"Envio da cobranca e NFSe: "+c.envios.length+" data(s) programada(s)"}
                style={{background:"#f5f3ff",color:"#7c3aed",fontSize:10,fontWeight:700,padding:"3px 9px",borderRadius:99,display:"inline-flex",alignItems:"center",gap:4}}>
                <svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round"><path d="M22 2L11 13"/><path d="M22 2l-7 20-4-9-9-4 20-7z"/></svg>
                {c.envios.length} envio{c.envios.length>1?"s":""}</span>}
              {/* Contato financeiro cadastrado */}
              {(c.contatoNome||c.contatoWhats||c.contatoEmail)&&<span title={[c.contatoNome,c.contatoWhats,c.contatoEmail].filter(Boolean).join(" · ")}
                style={{background:"#f0fdf4",color:"#15803d",fontSize:10,fontWeight:700,padding:"3px 9px",borderRadius:99,display:"inline-flex",alignItems:"center",gap:4,maxWidth:150,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>
                <svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round"><path d="M20 21v-2a4 4 0 00-4-4H8a4 4 0 00-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>
                {c.contatoNome||"contato"}</span>}
            </div>
          </div>;
        })}
      </div>
    </Block>

    {/* Modal de edicao do contrato — abre ao clicar em qualquer card ou unidade */}
    {editContrato && <_GFEditContratoModal
      editContrato={editContrato}
      contratos={contratos}
      updateContratos={_updateContratos}
      onClose={function(){setEditContrato(null);}}/>}

  </div>;
}



/* ═══════════════════════════════════════════════════════════════════
   PROJEÇÃO FINANCEIRA — Gestão > Projeção financeira
   MESMO DRE do Financeiro (mesma cascata, mesmas cores, mesmos números),
   mas 100% editável: serve pra simular cenários sem tocar nos dados reais.
   Ao abrir pela primeira vez, IMPORTA os gastos já especificados no
   Financeiro (impostos, CSP, despesas diretas, operacionais + pró-labore
   e o MRR dos contratos) como ponto de partida — depois é tudo manual.
   Persistência: app_data "projecao_financeira" + espelho localStorage.
═══════════════════════════════════════════════════════════════════ */
// Lê os itens de custo do Financeiro (cache localStorage sincronizado do Supabase):
// mês atual → walk-back 12 meses → chave legada.
function _projLerCustos(tipo){
  try{
    const now=new Date(); let y=now.getFullYear(), m=now.getMonth()+1;
    for(let i=0;i<12;i++){
      const k="pixels-custos-"+tipo+"-"+y+"-"+String(m).padStart(2,"0");
      const raw=localStorage.getItem(k);
      if(raw){ const arr=JSON.parse(raw); if(Array.isArray(arr)&&arr.length) return arr; }
      m-=1; if(m<1){m=12;y-=1;}
    }
    const raw2=localStorage.getItem("pixels-custos-"+tipo);
    if(raw2){ const arr=JSON.parse(raw2); if(Array.isArray(arr)) return arr; }
  }catch(_){}
  return [];
}
function _projImportarDoFinanceiro(){
  const _map=function(arr){ return (arr||[]).filter(function(x){return x&&(x.label||Number(x.valor)>0);}).map(function(x){ return {l:String(x.label||""), v:String(Number(x.valor)||0)}; }); };
  // Receita: contratos ativos (mesma fonte do Financeiro)
  let mrr=0;
  try{
    const src=(typeof _gfLoadContratos==="function")?_gfLoadContratos():[];
    (src||[]).forEach(function(c){
      if(c&&c.unidades) c.unidades.forEach(function(u){ mrr+=Number(u.valor||0); });
      else if(c) mrr+=Number(c.valor||0);
    });
  }catch(_){}
  const desp=_map(_projLerCustos("despesa_operacional")).concat(
    _map(_projLerCustos("prolabore")).map(function(x){ return {l:x.l, v:x.v}; }));
  return {
    receitas:[{l:"MRR dos contratos ativos", v:String(mrr||0)},{l:"Vendas pontuais", v:""}],
    impostos: _map(_projLerCustos("imposto")),
    csp:      _map(_projLerCustos("csp")).concat([{l:"Freelancers (estimativa)", v:""}]),
    despDireta:_map(_projLerCustos("despesa_direta")),
    despOp:   desp,
  };
}
/* Seção editável da Projeção — MÓDULO (não recriar por render: recriar fazia o
   React remontar a seção a cada tecla e o input perdia o foco = "uma letra por vez"). */
function _ProjSecao({pos,label,cor,subtitle,sec,dados,mut,brl}){
    const [exp,setExp]=useState(false);
    const total=(dados[sec]||[]).reduce(function(a,it){
      const n=parseFloat(String(it.v==null?"":it.v).replace(",","."));
      return a+(isNaN(n)?0:n);
    },0);
    return <div style={{border:"1px solid #f1f5f9",borderRadius:11,overflow:"hidden"}}>
      <div onClick={function(){setExp(!exp);}} style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:12,padding:"12px 16px",cursor:"pointer",background:exp?cor+"08":"#fff",transition:"background .12s"}}
        onMouseEnter={function(e){e.currentTarget.style.background=cor+"10";}}
        onMouseLeave={function(e){e.currentTarget.style.background=exp?cor+"08":"#fff";}}>
        <div style={{display:"flex",alignItems:"center",gap:10}}>
          <span style={{background:cor,color:"#fff",fontSize:12,fontWeight:800,width:32,height:32,borderRadius:8,display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>{pos}</span>
          <span style={{color:cor,fontWeight:800,fontSize:16,width:14,textAlign:"center",flexShrink:0}}>−</span>
          <div>
            <div style={{color:"#0f172a",fontSize:14,fontWeight:800,letterSpacing:-.2}}>{label}</div>
            {subtitle&&<div style={{color:"#94a3b8",fontSize:11,marginTop:1}}>{subtitle}</div>}
          </div>
        </div>
        <div style={{display:"flex",alignItems:"center",gap:10}}>
          <span style={{color:cor,fontWeight:800,fontSize:22,fontFeatureSettings:"'tnum'",letterSpacing:-.6}}>{brl(total)}</span>
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#94a3b8" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" style={{transform:exp?"rotate(180deg)":"none",transition:"transform .15s"}}><polyline points="6 9 12 15 18 9"/></svg>
        </div>
      </div>
      {exp&&<div style={{padding:"8px 16px 14px",background:"#fafbfc",borderTop:"1px solid #f1f5f9",display:"flex",flexDirection:"column",gap:6}}>
        {(dados[sec]||[]).map(function(it,idx){
          return <div key={idx} style={{display:"flex",alignItems:"center",gap:8,background:"#fff",border:"1px solid #eef0f5",borderRadius:9,padding:"7px 10px"}}>
            <input value={it.l} placeholder="Descrição"
              onChange={function(e){const v=e.target.value;mut(function(d){d[sec][idx].l=v;return d;});}}
              style={{flex:1,minWidth:0,border:"none",outline:"none",fontSize:12.5,fontWeight:600,color:"#0f172a",fontFamily:"inherit",background:"transparent"}}/>
            <span style={{color:"#cbd5e1",fontSize:11,fontWeight:700}}>R$</span>
            <input value={it.v} placeholder="0" inputMode="decimal"
              onChange={function(e){const v=e.target.value.replace(/[^0-9.,]/g,"");mut(function(d){d[sec][idx].v=v;return d;});}}
              style={{width:100,border:"none",outline:"none",fontSize:13,fontWeight:800,color:cor,textAlign:"right",fontFamily:"inherit",fontFeatureSettings:"'tnum'",background:"transparent"}}/>
            <button onClick={function(){mut(function(d){d[sec].splice(idx,1);return d;});}} title="Remover"
              style={{background:"none",border:"none",color:"#cbd5e1",cursor:"pointer",padding:2,display:"inline-flex"}}
              onMouseEnter={function(e){e.currentTarget.style.color="#dc2626";}}
              onMouseLeave={function(e){e.currentTarget.style.color="#cbd5e1";}}>
              <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
            </button>
          </div>;
        })}
        <button onClick={function(){mut(function(d){(d[sec]=d[sec]||[]).push({l:"",v:""});return d;});}}
          style={{background:cor+"0d",border:"1px dashed "+cor+"55",borderRadius:9,padding:"8px 0",fontSize:11.5,fontWeight:700,color:cor,cursor:"pointer",fontFamily:"inherit"}}>+ Adicionar item</button>
      </div>}
    </div>;
  }

function PageGestaoProjecao({isMob}){
  const [dados,setDados]=useState(function(){
    try{
      const raw=localStorage.getItem("pixels-projecao-financeira-v2");
      if(raw){ const p=JSON.parse(raw); if(p&&p.receitas) return p; }
    }catch(_){}
    return _projImportarDoFinanceiro();
  });
  const [carregou,setCarregou]=useState(false);
  const _saveT=useRef(null);

  useEffect(function(){
    if(typeof window==="undefined"||!window._sb){setCarregou(true);return;}
    let alive=true;
    window._sb.from("app_data").select("value").eq("key","projecao_financeira").maybeSingle()
      .then(function(r){
        if(!alive)return;
        const v=r&&r.data&&r.data.value;
        // SEMPRE abre com os números atuais do Financeiro (pedido: nunca começar do zero).
        // Continua 100% editável — os rascunhos valem pra sessão e sincronizam entre sócios.
        const _temValor=function(d){ if(!d)return false; return ["receitas","impostos","csp","despDireta","despOp"].some(function(k){ return (d[k]||[]).some(function(x){ var n=parseFloat(String(x&&x.v||"").replace(",",".")); return !isNaN(n)&&n>0; }); }); };
        const _fresh=_projImportarDoFinanceiro();
        if(_temValor(_fresh)) setDados(_fresh);
        else if(v&&v.receitas) setDados(v); // financeiro ainda não carregou → usa o último salvo
        setCarregou(true);
        // Retry: caches do Financeiro podem carregar alguns segundos depois do mount.
        // Só substitui se o usuário ainda não mexeu em nada nessa sessão.
        setTimeout(function(){
          if(!alive||window.__pxProjEditou)return;
          const _f2=_projImportarDoFinanceiro();
          if(_temValor(_f2)) setDados(_f2);
        },3000);
      })
      .catch(function(){ if(alive) setCarregou(true); });
    // Tempo real: quando o OUTRO sócio salva, a projeção atualiza sozinha aqui.
    // (mudança do próprio usuário é ignorada pra não brigar com o que ele digita)
    let ch=null;
    try{
      ch=window._sb.channel("projecao-financeira-rt")
        .on("postgres_changes",{event:"*",schema:"public",table:"app_data",filter:"key=eq.projecao_financeira"},
          function(payload){
            try{
              if(!alive)return;
              const v=payload&&payload.new&&payload.new.value;
              const autor=(payload&&payload.new&&payload.new.updated_by)||"";
              const eu=(typeof CURRENT_USER!=="undefined"&&CURRENT_USER&&CURRENT_USER.name)||"";
              if(v&&v.receitas&&autor&&autor!==eu) setDados(v);
            }catch(_){}
          })
        .subscribe();
    }catch(_){}
    return function(){alive=false; try{ if(ch) window._sb.removeChannel(ch); }catch(_){}};
  },[]);

  function _persist(next){
    try{localStorage.setItem("pixels-projecao-financeira-v2",JSON.stringify(next));}catch(_){}
    if(_saveT.current)clearTimeout(_saveT.current);
    _saveT.current=setTimeout(function(){
      if(typeof window==="undefined"||!window._sb)return;
      window._sb.from("app_data").upsert({key:"projecao_financeira",value:next,updated_at:new Date().toISOString(),updated_by:(typeof CURRENT_USER!=="undefined"&&CURRENT_USER&&CURRENT_USER.name)||""},{onConflict:"key"})
        .then(function(r){ if(r&&r.error)console.warn("projecao save:",r.error.message); })
        .catch(function(e){ console.warn("projecao save:",e); });
    },800);
  }
  function _mut(fn){ window.__pxProjEditou=true; setDados(function(prev){ const next=fn(JSON.parse(JSON.stringify(prev))); _persist(next); return next; }); }

  const _num=function(v){ const n=parseFloat(String(v==null?"":v).replace(",",".")); return isNaN(n)?0:n; };
  const _brlF=function(n){return "R$ "+Number(n||0).toLocaleString("pt-BR",{minimumFractionDigits:2,maximumFractionDigits:2});};
  const _tot=function(sec){ return (dados[sec]||[]).reduce(function(a,it){return a+_num(it.v);},0); };

  const receita=_tot("receitas");
  const impostosT=_tot("impostos");
  const receitaLiq=receita-impostosT;
  const cspT=_tot("csp");
  const lucroBruto=receitaLiq-cspT;
  const despDirT=_tot("despDireta");
  const margemContrib=lucroBruto-despDirT;
  const pctMC=receita>0?(margemContrib/receita)*100:0;
  const despOpT=_tot("despOp");
  const resultado=margemContrib-despOpT;
  const margem=receita>0?resultado/receita:0;
  const META=(typeof GF_META_MARGEM_PCT!=="undefined")?GF_META_MARGEM_PCT:0.5;
  const bateu=margem>=META&&receita>0;


  return <div style={{display:"flex",flexDirection:"column",gap:16,maxWidth:1100,margin:"0 auto",fontFamily:"'Inter',system-ui,sans-serif"}}>
    <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:12,flexWrap:"wrap"}}>
      <div style={{display:"flex",alignItems:"center",gap:11}}>
        <div style={{width:38,height:38,borderRadius:10,background:"linear-gradient(135deg,#0ea5e9,#6366f1)",display:"flex",alignItems:"center",justifyContent:"center"}}>
          <Ico n="trending-up" size={18} color="#fff"/>
        </div>
        <div>
          <div style={{color:"#0f172a",fontWeight:800,fontSize:18,letterSpacing:-.4}}>Projeção financeira</div>
          <div style={{color:"#64748b",fontSize:12,marginTop:2}}>O mesmo DRE do Financeiro, mas de rascunho: edite qualquer número e veja a margem do cenário.</div>
        </div>
      </div>
      <div style={{display:"flex",gap:8}}>
        <button onClick={function(){ if(window.confirm("Importar os gastos e o MRR atuais do Financeiro? A projeção atual será substituída.")) _mut(function(){return _projImportarDoFinanceiro();}); }}
          style={{background:"#7c3aed",border:"none",borderRadius:9,padding:"8px 14px",fontSize:11.5,fontWeight:800,color:"#fff",cursor:"pointer",display:"inline-flex",alignItems:"center",gap:6}}>
          <Ico n="download" size={12} color="#fff"/> Importar do Financeiro
        </button>
        <button onClick={function(){ if(window.confirm("Zerar todos os quadros da projeção?")) _mut(function(){return {receitas:[{l:"",v:""}],impostos:[],csp:[],despDireta:[],despOp:[]};}); }}
          style={{background:"#fff",border:"1px solid #e2e8f0",borderRadius:9,padding:"8px 14px",fontSize:11.5,fontWeight:700,color:"#64748b",cursor:"pointer"}}>Limpar</button>
      </div>
    </div>

    {/* ═══ DRE DE CENÁRIO — mesma cascata do Financeiro ═══ */}
    <section style={{background:"#fff",border:"1px solid #e2e8f0",borderRadius:14,padding:"14px 18px",display:"flex",flexDirection:"column",gap:10}}>
      {/* 1 · Receita — header vermelho com linhas editáveis */}
      <div style={{background:"linear-gradient(90deg,#ef444412,#ef444404)",border:"1px solid #ef444433",borderRadius:11,padding:"12px 16px"}}>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:10,marginBottom:8}}>
          <div style={{display:"flex",alignItems:"center",gap:10}}>
            <span style={{background:"#ef4444",color:"#fff",fontSize:12,fontWeight:800,width:32,height:32,borderRadius:8,display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>1.</span>
            <div style={{color:"#0f172a",fontSize:14,fontWeight:800,letterSpacing:-.2}}>Receita total do cenário</div>
          </div>
          <span style={{color:"#ef4444",fontWeight:800,fontSize:22,letterSpacing:-.6,fontFeatureSettings:"'tnum'"}}>{_brlF(receita)}</span>
        </div>
        <div style={{display:"flex",flexDirection:"column",gap:6}}>
          {(dados.receitas||[]).map(function(it,idx){
            return <div key={idx} style={{display:"flex",alignItems:"center",gap:8,background:"#fff",border:"1px solid #fecaca55",borderRadius:9,padding:"7px 10px"}}>
              <input value={it.l} placeholder="Descrição da receita"
                onChange={function(e){const v=e.target.value;_mut(function(d){d.receitas[idx].l=v;return d;});}}
                style={{flex:1,minWidth:0,border:"none",outline:"none",fontSize:12.5,fontWeight:600,color:"#0f172a",fontFamily:"inherit",background:"transparent"}}/>
              <span style={{color:"#cbd5e1",fontSize:11,fontWeight:700}}>R$</span>
              <input value={it.v} placeholder="0" inputMode="decimal"
                onChange={function(e){const v=e.target.value.replace(/[^0-9.,]/g,"");_mut(function(d){d.receitas[idx].v=v;return d;});}}
                style={{width:110,border:"none",outline:"none",fontSize:13,fontWeight:800,color:"#ef4444",textAlign:"right",fontFamily:"inherit",fontFeatureSettings:"'tnum'",background:"transparent"}}/>
              <button onClick={function(){_mut(function(d){d.receitas.splice(idx,1);return d;});}} title="Remover"
                style={{background:"none",border:"none",color:"#cbd5e1",cursor:"pointer",padding:2,display:"inline-flex"}}>
                <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
              </button>
            </div>;
          })}
          <button onClick={function(){_mut(function(d){(d.receitas=d.receitas||[]).push({l:"",v:""});return d;});}}
            style={{background:"#ef44440d",border:"1px dashed #ef444455",borderRadius:9,padding:"8px 0",fontSize:11.5,fontWeight:700,color:"#ef4444",cursor:"pointer",fontFamily:"inherit"}}>+ Adicionar receita</button>
        </div>
      </div>

      <_ProjSecao pos="2." label="Impostos e deduções" cor="#f97316" sec="impostos" dados={dados} mut={_mut} brl={_brlF} subtitle="Simples, taxas de pagamento e afins"/>
      <_DRELinha kind="subtotal" pos="3." op="=" label="Receita líquida" valor={receitaLiq} cor="#f59e0b" isMob={isMob}/>
      <_ProjSecao pos="4." label="CSP (Custo do Serviço Prestado)" cor="#84cc16" sec="csp" dados={dados} mut={_mut} brl={_brlF} subtitle="Time de entrega, freelancers e produção"/>
      <_DRELinha kind="subtotal" pos="5." op="=" label="Lucro bruto" valor={lucroBruto} cor="#14b8a6" isMob={isMob}/>
      <_ProjSecao pos="6." label="Despesas variáveis diretas" cor="#06b6d4" sec="despDireta" dados={dados} mut={_mut} brl={_brlF} subtitle="Mídia vinculada ao projeto, ferramentas, comissões"/>
      <div style={{background:"transparent",borderTop:"1px dashed #e2e8f0",padding:"12px 16px",display:"flex",alignItems:"center",justifyContent:"space-between",gap:10}}>
        <div style={{display:"flex",alignItems:"center",gap:10}}>
          <span style={{background:"#3b82f6",color:"#fff",fontSize:12,fontWeight:800,width:32,height:32,borderRadius:8,display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>7.</span>
          <span style={{color:"#3b82f6",fontWeight:800,fontSize:16,width:14,textAlign:"center",flexShrink:0}}>=</span>
          <div>
            <div style={{color:"#0f172a",fontSize:14,fontWeight:800,letterSpacing:-.2}}>Margem de contribuição</div>
            <div style={{color:pctMC>=50?"#1d4ed8":"#a16207",fontSize:11.5,fontWeight:700,marginTop:1}}>{pctMC>=50?"Saudável — acima de 50%":"Abaixo de 50% — atenção"}</div>
          </div>
        </div>
        <div style={{textAlign:"right",paddingRight:26}}>
          <div style={{color:"#3b82f6",fontWeight:800,fontSize:22,letterSpacing:-.6,fontFeatureSettings:"'tnum'",lineHeight:1}}>{_brlF(margemContrib)}</div>
          <div style={{color:"#64748b",fontSize:11,fontWeight:700,marginTop:3,fontFeatureSettings:"'tnum'"}}>{pctMC.toFixed(2)}%</div>
        </div>
      </div>
      <_ProjSecao pos="8." label="Despesas operacionais" cor="#6366f1" sec="despOp" dados={dados} mut={_mut} brl={_brlF} subtitle="Salários fixos, contabilidade, softwares, pró-labore"/>

      {/* 9 · Resultado — mesmo card gradiente do Financeiro + meta 50% */}
      <div style={{background:resultado>=0?"linear-gradient(135deg,#7e22ce,#c026d3)":"linear-gradient(135deg,#0f172a,#7f1d1d)",borderRadius:12,padding:"18px 22px",display:"flex",alignItems:"center",justifyContent:"space-between",gap:14,flexWrap:"wrap"}}>
        <div style={{display:"flex",alignItems:"center",gap:14}}>
          <span style={{background:"rgba(255,255,255,0.14)",color:"#fff",fontSize:16,fontWeight:800,width:40,height:40,borderRadius:11,display:"inline-flex",alignItems:"center",justifyContent:"center"}}>9</span>
          <div>
            <div style={{color:"#fff",fontSize:11,fontWeight:800,letterSpacing:.5,textTransform:"uppercase",opacity:.75}}>Resultado do cenário</div>
            <div style={{color:"#fff",fontSize:16,fontWeight:800,letterSpacing:-.3,marginTop:2}}>{resultado>=0?"Lucro projetado":"Prejuízo projetado"}</div>
          </div>
        </div>
        <div style={{textAlign:"right"}}>
          <div style={{color:"#fff",fontWeight:800,fontSize:22,letterSpacing:-.6,fontFeatureSettings:"'tnum'",lineHeight:1}}>{_brlF(resultado)}</div>
          <div style={{display:"flex",alignItems:"center",gap:8,marginTop:6,justifyContent:"flex-end"}}>
            <span style={{color:"#fff",opacity:.75,fontSize:11.5,fontWeight:700,fontFeatureSettings:"'tnum'"}}>{(margem*100).toFixed(1)}% margem</span>
            <span style={{background:bateu?"rgba(74,222,128,.22)":"rgba(251,191,36,.2)",color:bateu?"#86efac":"#fde68a",fontSize:9.5,fontWeight:800,padding:"3px 9px",borderRadius:99,letterSpacing:.4,textTransform:"uppercase"}}>{bateu?"meta 50% batida":"meta 50%"}</span>
          </div>
          <div style={{background:"rgba(255,255,255,.18)",borderRadius:99,height:5,marginTop:8,overflow:"hidden",minWidth:180}}>
            <div style={{width:Math.min(100,Math.max(2,margem/META*100))+"%",height:"100%",background:bateu?"#4ade80":"#fde68a",borderRadius:99,transition:"width .3s"}}/>
          </div>
        </div>
      </div>
    </section>
    {!carregou&&<div style={{color:"#cbd5e1",fontSize:10.5,textAlign:"center"}}>sincronizando…</div>}
  </div>;
}

