/* ── Oculta um membro do TEAM em TODOS os navegadores ───────────────────
   Lista compartilhada em team_data tipo='team_ocultos' (dados={ids:[...]}).
   Usada pra remover membros do cadastro fixo sem login (ex: Ocsana) e pra
   garantir que hardcoded excluídos não voltem no F5. ── */
async function _pixelsOcultarMembro(teamId){
  try{
    const sb=window._sb;
    if(sb){
      let ids=[];
      try{
        const {data}=await sb.from("team_data").select("dados").eq("tipo","team_ocultos").maybeSingle();
        ids=(data&&data.dados&&Array.isArray(data.dados.ids))?data.dados.ids.slice():[];
      }catch(_){}
      if(ids.indexOf(teamId)<0) ids.push(teamId);
      await sb.from("team_data").upsert(
        {tipo:"team_ocultos",dados:{ids:ids},updated_by:(typeof CURRENT_USER!=="undefined"&&CURRENT_USER)?CURRENT_USER.name:""},
        {onConflict:"tipo"});
    }
  }catch(_){}
  try{
    const raw=localStorage.getItem("pixels-team-deleted");
    const l=raw?JSON.parse(raw):[];
    if(l.indexOf(teamId)<0){l.push(teamId);localStorage.setItem("pixels-team-deleted",JSON.stringify(l));}
  }catch(_){}
  try{
    if(typeof TEAM!=="undefined"){
      const i=TEAM.findIndex(t=>t&&t.id===teamId);
      if(i>=0)TEAM.splice(i,1);
    }
    window.dispatchEvent(new CustomEvent("pixels:team-updated"));
  }catch(_){}
}

function CollabProfileModal({user,onClose,livePerms,setLivePerms,tasks:propTasks}){
  // Prioridade: livePerms (localStorage) → ACCESS_STORE (padrão hardcoded) → DEFAULT_PERMS
  const [perms,setPerms]=useState(()=>({
    ...DEFAULT_PERMS,
    ...(ACCESS_STORE[user.id]||{}),
    ...(livePerms?.[user.id]||{}),
  }));
  const [saved,setSaved]=useState(false);
  const [activeTab,setActiveTab]=useState("dashboard");
  const savedTimer=useRef(null);
  const isPartnerUser=user.level===1;

  const flashSaved=()=>{
    if(savedTimer.current)clearTimeout(savedTimer.current);
    setSaved(true);
    savedTimer.current=setTimeout(()=>setSaved(false),2500);
  };

  const _exclTravada=(typeof pxExclusaoBloqueada==="function")&&pxExclusaoBloqueada(user); // social media: exclusão sempre travada
  const toggle=(key)=>{
    if(isPartnerUser)return; // sócios sempre têm tudo
    if(key==="excluirDemanda"&&_exclTravada){if(typeof pixelsToast!=="undefined")pixelsToast.warning("Social media não pode excluir — regra fixa do sistema.");return;}
    setPerms(p=>({...p,[key]:!p[key]}));
    setSaved(false);
  };

  const save=async()=>{
    // 1. Atualiza memória e localStorage imediatamente
    if(_exclTravada&&perms.excluirDemanda){perms.excluirDemanda=false;setPerms(p=>({...p,excluirDemanda:false}));}
    ACCESS_STORE[user.id]={...perms};
    if(setLivePerms) setLivePerms(p=>({...p,[user.id]:{...perms}}));
    try{localStorage.setItem(`pixels-perms-${user.id}`,JSON.stringify(perms));}catch(e){}

    // 2. Salva no Supabase — busca o perfil pelo team_id para obter o UUID real
    try{
      // Primeiro busca o UUID real do perfil pelo team_id
      const {data:profileRow,error:findErr}=await _sb
        .from("profiles")
        .select("id")
        .eq("team_id",user.id)
        .single();

      if(findErr||!profileRow){
        // Perfil não existe — tenta fazer upsert pelo team_id diretamente
        await _sb
          .from("profiles")
          .upsert({team_id:user.id, name:user.name, permissions:perms},{onConflict:"team_id"});
        flashSaved();
        return;
      }

      // Atualiza pelo UUID real (sempre funciona independente de RLS por team_id)
      await _sb
        .from("profiles")
        .update({permissions:perms})
        .eq("id",profileRow.id);

    }catch(e){}

    flashSaved();
  };

  const tasks=(propTasks||[]).filter(t=>t.assignee===user.id);
  const done=tasks.filter(t=>t.status==="aprovado");
  const open=tasks.filter(t=>t.status!=="aprovado"&&t.status!=="pausado");
  const late=open.filter(t=>daysLeft(t.deadline)<0);

  const isMobP=_pxMob();
  const tabInfo=PERM_TABS.find(t=>t.id===activeTab)||{};
  const _itensTab=PERM_GROUPS[activeTab]||[];
  const _tabCor=tabInfo.color||user.color||"#7c3aed";
  const _setTabAll=(v)=>{
    if(isPartnerUser)return;
    const patch={};
    _itensTab.forEach(i=>{ if(i.key) patch[i.key]=v; });
    if(_exclTravada) patch.excluirDemanda=false;
    setPerms(p=>({...p,...patch}));
    setSaved(false);
  };
  const _miniBtn={background:"#fff",border:"1px solid #e2e8f0",borderRadius:8,padding:"6px 11px",fontSize:11,fontWeight:700,color:"#475569",cursor:"pointer",fontFamily:"inherit",whiteSpace:"nowrap"};

  return <div onMouseDown={e=>{if(e.target===e.currentTarget)onClose();}} style={{position:"fixed",inset:0,background:"rgba(15,23,42,0.55)",backdropFilter:"blur(6px)",WebkitBackdropFilter:"blur(6px)",zIndex:300,display:"flex",alignItems:"center",justifyContent:"center",padding:16,fontFamily:"'Inter',system-ui,sans-serif"}}>
    <div onMouseDown={e=>e.stopPropagation()} style={{background:"#fff",borderRadius:20,width:"100%",maxWidth:1040,height:isMobP?"92vh":"min(88vh,760px)",display:"flex",flexDirection:isMobP?"column":"row",overflow:"hidden",boxShadow:"0 24px 70px rgba(15,23,42,.30)"}}>

      {/* ── Sidebar: quem é + categorias ── */}
      <div style={{width:isMobP?"100%":252,flexShrink:0,background:"#fafbfc",borderRight:isMobP?"none":"1px solid #eef0f3",borderBottom:isMobP?"1px solid #eef0f3":"none",display:"flex",flexDirection:"column",minHeight:0}}>
        <div style={{padding:isMobP?"13px 16px 10px":"20px 18px 14px",display:"flex",alignItems:"center",gap:12,borderBottom:"1px solid #eef0f3"}}>
          {typeof UserAvatar==="function"
            ? <UserAvatar user={user} size={44}/>
            : <div style={{width:44,height:44,borderRadius:"50%",background:user.color,color:"#fff",display:"flex",alignItems:"center",justifyContent:"center",fontWeight:800,fontSize:17}}>{user.av}</div>}
          <div style={{minWidth:0,flex:1}}>
            <div style={{color:"#0f172a",fontWeight:800,fontSize:15,letterSpacing:-.3,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{user.name}</div>
            <div style={{color:"#94a3b8",fontSize:11,fontWeight:600,marginTop:1}}>{user.role} · Nível {user.level}</div>
          </div>
        </div>
        <div style={{flex:1,minHeight:0,overflowY:isMobP?"hidden":"auto",overflowX:isMobP?"auto":"hidden",display:"flex",flexDirection:isMobP?"row":"column",gap:2,padding:isMobP?"8px 10px":"10px"}}>
          {PERM_TABS.map(tab=>{
            const items=PERM_GROUPS[tab.id]||[];
            const totalKeys=items.filter(i=>i.key).length;
            const activeCount=items.filter(i=>i.key&&(isPartnerUser?true:perms[i.key])).length;
            const on=activeTab===tab.id;
            return <button key={tab.id} onClick={()=>setActiveTab(tab.id)}
              style={{display:"flex",alignItems:"center",gap:10,padding:"9px 12px",background:on?"#fff":"transparent",border:on?"1px solid #e8ecf1":"1px solid transparent",borderRadius:10,cursor:"pointer",textAlign:"left",whiteSpace:"nowrap",flexShrink:0,boxShadow:on?"0 1px 3px rgba(15,23,42,.06)":"none",transition:"all .12s",fontFamily:"inherit"}}
              onMouseEnter={e=>{if(!on)e.currentTarget.style.background="#f1f5f9";}}
              onMouseLeave={e=>{if(!on)e.currentTarget.style.background="transparent";}}>
              <span style={{width:26,height:26,borderRadius:8,background:on?tab.color+"16":"transparent",display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
                <NavIcon id={tab.navIcon||tab.id} size={14} color={on?tab.color:"#94a3b8"}/>
              </span>
              <span style={{flex:1,fontSize:12.5,fontWeight:on?800:600,color:on?"#0f172a":"#64748b"}}>{tab.label}</span>
              {totalKeys>0&&<span style={{fontSize:10,fontWeight:800,fontFeatureSettings:"'tnum'",color:activeCount>0?tab.color:"#cbd5e1",background:activeCount>0?tab.color+"14":"#f1f5f9",borderRadius:99,padding:"2px 7px"}}>{activeCount}/{totalKeys}</span>}
            </button>;
          })}
        </div>
      </div>

      {/* ── Painel da categoria ── */}
      <div style={{flex:1,display:"flex",flexDirection:"column",minWidth:0,minHeight:0}}>
        <div style={{padding:"14px 22px",borderBottom:"1px solid #f1f5f9",display:"flex",alignItems:"center",gap:8,flexWrap:"wrap"}}>
          <div style={{flex:1,minWidth:140}}>
            <div style={{color:"#0f172a",fontWeight:800,fontSize:16,letterSpacing:-.3}}>{tabInfo.label||"Permissões"}</div>
            <div style={{color:"#94a3b8",fontSize:11.5,fontWeight:500,marginTop:1}}>Clique num item pra ligar ou desligar</div>
          </div>
          {!isPartnerUser&&<button onClick={()=>_setTabAll(true)} style={_miniBtn}
            onMouseEnter={e=>{e.currentTarget.style.borderColor="#86efac";e.currentTarget.style.color="#16a34a";}}
            onMouseLeave={e=>{e.currentTarget.style.borderColor="#e2e8f0";e.currentTarget.style.color="#475569";}}>Ligar tudo</button>}
          {!isPartnerUser&&<button onClick={()=>_setTabAll(false)} style={_miniBtn}
            onMouseEnter={e=>{e.currentTarget.style.borderColor="#fecaca";e.currentTarget.style.color="#dc2626";}}
            onMouseLeave={e=>{e.currentTarget.style.borderColor="#e2e8f0";e.currentTarget.style.color="#475569";}}>Desligar tudo</button>}
          <button onClick={onClose} title="Fechar"
            style={{background:"#f8fafc",border:"1px solid #e2e8f0",borderRadius:9,width:32,height:32,color:"#64748b",cursor:"pointer",display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
          </button>
        </div>

        <div style={{flex:1,minHeight:0,overflowY:"auto",padding:"16px 22px"}}>
          {isPartnerUser&&<div style={{background:"#f5f3ff",border:"1px solid #ddd6fe",borderRadius:12,padding:"11px 15px",color:"#7c3aed",fontSize:12.5,fontWeight:700,marginBottom:14}}>⚡ Sócios têm acesso total e irrestrito ao sistema — nada aqui pode ser desligado.</div>}
          <div style={{display:"grid",gridTemplateColumns:isMobP?"1fr":"1fr 1fr",gap:8}}>
            {_itensTab.map((item,idx)=>{
              if(item.section) return <div key={"s"+idx} style={{gridColumn:isMobP?"auto":"span 2",color:"#94a3b8",fontSize:10,fontWeight:800,textTransform:"uppercase",letterSpacing:.8,marginTop:idx>0?10:0,paddingBottom:5,borderBottom:"1px solid #f1f5f9"}}>{item.section}</div>;
              const _travado=item.key==="excluirDemanda"&&_exclTravada;
              const on=isPartnerUser?true:(_travado?false:(perms[item.key]||false));
              return <div key={item.key} onClick={()=>toggle(item.key)} title={_travado?"Travado: social media nunca exclui":undefined}
                style={{display:"flex",justifyContent:"space-between",alignItems:"center",gap:10,padding:"11px 14px",background:on?_tabCor+"08":"#fff",borderRadius:11,border:"1px solid "+(on?_tabCor+"40":"#eef0f3"),transition:"all .12s",cursor:isPartnerUser?"default":"pointer"}}>
                <div style={{flex:1,minWidth:0}}>
                  <div style={{color:on?"#0f172a":"#64748b",fontSize:13,fontWeight:on?700:600,letterSpacing:-.1}}>{item.label}</div>
                  {item.desc&&<div style={{color:"#94a3b8",fontSize:10.5,marginTop:2,lineHeight:1.4}}>{_travado?"Travado pelo sistema — social media nunca exclui":item.desc}</div>}
                </div>
                <div style={{width:38,height:22,borderRadius:99,background:on?_tabCor:"#e2e8f0",position:"relative",transition:"background .18s",flexShrink:0}}>
                  <div style={{position:"absolute",top:3,left:on?19:3,width:16,height:16,borderRadius:"50%",background:"#fff",transition:"left .18s",boxShadow:"0 1px 3px rgba(15,23,42,.25)"}}/>
                </div>
              </div>;
            })}
          </div>
        </div>

        <div style={{padding:"12px 22px",borderTop:"1px solid #f1f5f9",display:"flex",justifyContent:"flex-end",alignItems:"center",gap:12,background:"#fafbfc"}}>
          {saved&&<span style={{color:"#16a34a",fontSize:12.5,fontWeight:800,display:"inline-flex",alignItems:"center",gap:5}}>
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
            Permissões salvas
          </span>}
          <button onClick={save} disabled={saved}
            style={{background:saved?"#e2e8f0":"#0f172a",color:saved?"#94a3b8":"#fff",border:"none",borderRadius:10,padding:"11px 26px",fontWeight:800,fontSize:13.5,cursor:saved?"default":"pointer",fontFamily:"inherit",boxShadow:saved?"none":"0 4px 14px rgba(15,23,42,.22)",transition:"all .15s"}}>
            {saved?"Salvo":"Salvar permissões"}
          </button>
        </div>
      </div>
    </div>
  </div>;
}

/* ─── Constantes estáticas de CollabProfilePage ─── */
const COLLAB_TABS=[
  {id:"dados",       ico:"user",     label:"Dados"},
  {id:"pessoal",     ico:"home",     label:"Pessoal"},
  {id:"lazer",       ico:"gamepad",  label:"Lazer"},
  {id:"pets",        ico:"paw",      label:"Pets"},
  {id:"curiosidades",ico:"sparkles", label:"Curiosidades"},
  {id:"bio",         ico:"file-text",label:"Bio"},
  {id:"seguranca",   ico:"lock",     label:"Segurança",selfOnly:true},
];

/* ─── LBL — fora do componente para evitar remount a cada render ─── */
function LBL({t}){
  return <div style={{color:"#64748b",fontSize:10,fontWeight:700,textTransform:"uppercase",letterSpacing:.7,marginBottom:6,fontFamily:"\'Inter\',system-ui,sans-serif"}}>{t}</div>;
}

/* ─── COLLAB PROFILE EDIT MODAL ─────────────── */
function CollabProfilePage({user,profile,onSave,onClose}){
  const [activeTab,setActiveTab]=useState("dados");
  const p=profile||{};
  const inp={background:"#fafafa",border:"1px solid #e2e8f0",borderRadius:10,padding:"10px 13px",color:"#0f172a",fontSize:13,outline:"none",width:"100%",boxSizing:"border-box",fontFamily:"\'Inter\',system-ui,sans-serif",transition:"all .15s"};
  const fileRef=useRef(null);

  const [nome,setNome]=useState(p.nome||user.name);
  // Função/cargo: prioriza o que a pessoa salvou (profile_data.funcao); só cai no
  // role do TEAM se ainda não editaram. Antes o role sobrescrevia o valor salvo — o
  // usuário editava, salvava, e ao reabrir voltava pro role (parecia "não salvou").
  const [funcao,setFuncao]=useState((p.funcao&&String(p.funcao).trim())||user.role||"");
  const [telefone,setTelefone]=useState(p.telefone||"");
  const [email,setEmail]=useState(p.email||user.id+"@pixelsmarketing.com.br");
  const [nascimento,setNascimento]=useState(p.nascimento||"");
  const [photo,setPhoto]=useState(p.photo||null);
  const [cidade,setCidade]=useState(p.cidade||"");
  const [estado,setEstado]=useState(p.estado||"");
  const [camiseta,setCamiseta]=useState(p.camiseta||"");
  const [calcado,setCalcado]=useState(p.calcado||"");
  const [smartphone,setSmartphone]=useState(p.smartphone||"");
  const [time,setTime]=useState(p.time||"");
  const [estadoCivil,setEstadoCivil]=useState(p.estadoCivil||"");
  const [filhos,setFilhos]=useState(p.filhos||"");
  const [comidas,setComidas]=useState(p.comidas||["","","","",""]);
  const [bebida,setBebida]=useState(p.bebida||"");
  const [hobbies,setHobbies]=useState(p.hobbies||"");
  const [musica,setMusica]=useState(p.musica||"");
  const [series,setSeries]=useState(p.series||"");
  const [filmes,setFilmes]=useState(p.filmes||"");
  const [viagens,setViagens]=useState(p.viagens||"");
  const [pets,setPets]=useState(p.pets||[{...EMPTY_PET}]);
  const addPet=()=>{if(pets.length<10)setPets(v=>[...v,{...EMPTY_PET}]);};
  const removePet=(i)=>setPets(v=>v.filter((_,idx)=>idx!==i));
  const setPetField=(i,k,val)=>setPets(prev=>prev.map((pt,idx)=>idx===i?{...pt,[k]:val}:pt));
  const [curiosidades,setCuriosidades]=useState(p.curiosidades||"");
  const [medoOuFobia,setMedoOuFobia]=useState(p.medoOuFobia||"");
  const [superpoder,setSuperpoder]=useState(p.superpoder||"");
  const [talento,setTalento]=useState(p.talento||"");
  const [licoesAprendidas,setLicoesAprendidas]=useState(p.licoesAprendidas||"");
  const [bio,setBio]=useState(p.bio||"");
  const [habilidades,setHabilidades]=useState(p.habilidades||"");
  const [objetivos,setObjetivos]=useState(p.objetivos||"");
  const [obs,setObs]=useState(p.obs||"");

  const [uploadingPhoto,setUploadingPhoto]=useState(false);
  const handlePhoto=async(e)=>{
    const file=e.target.files?.[0];
    if(!file)return;
    e.target.value="";
    setUploadingPhoto(true);
    try{
      const sb=window._sb;
      const ext=file.name.split(".").pop()||"jpg";
      const path=`avatars/${user.id}-${Date.now()}.${ext}`;
      const{error}=await sb.storage.from("agency-files").upload(path,file,{upsert:true});
      if(error)throw error;
      const{data}=sb.storage.from("agency-files").getPublicUrl(path);
      setPhoto(data.publicUrl);
      // Atualiza localStorage imediatamente pra todos os UserAvatar refletirem antes do save final
      try{
        const k="pixels-selfprofile-"+user.id;
        const prev=JSON.parse(localStorage.getItem(k)||"{}");
        localStorage.setItem(k,JSON.stringify(Object.assign({},prev,{photo:data.publicUrl})));
        window.dispatchEvent(new CustomEvent("pixels:photo-updated",{detail:{userId:user.id}}));
      }catch(_){}
    }catch(err){
      console.error("Erro upload foto:",err);
      // Fallback: usar base64 comprimido via canvas
      const canvas=document.createElement("canvas");
      const img=new Image();
      img.onload=()=>{
        const MAX=400;
        const ratio=Math.min(MAX/img.width,MAX/img.height,1);
        canvas.width=Math.round(img.width*ratio);
        canvas.height=Math.round(img.height*ratio);
        canvas.getContext("2d").drawImage(img,0,0,canvas.width,canvas.height);
        const dataUrl=canvas.toDataURL("image/jpeg",0.75);
        setPhoto(dataUrl);
        try{
          const k="pixels-selfprofile-"+user.id;
          const prev=JSON.parse(localStorage.getItem(k)||"{}");
          localStorage.setItem(k,JSON.stringify(Object.assign({},prev,{photo:dataUrl})));
          window.dispatchEvent(new CustomEvent("pixels:photo-updated",{detail:{userId:user.id}}));
        }catch(_){}
      };
      img.src=URL.createObjectURL(file);
    }finally{
      setUploadingPhoto(false);
    }
  };

  const [corPerfil,setCorPerfil]=useState(user.color||"#ec4899");
  const _salvarCor=async function(){
    if(corPerfil===user.color) return;
    try{
      if(typeof TEAM!=="undefined"){
        const t=TEAM.find(function(x){return x&&x.id===user.id;});
        if(t) t.color=corPerfil;
      }
      window.dispatchEvent(new CustomEvent("pixels:team-updated"));
    }catch(_){}
    try{
      const sb=window._sb;
      const{data:profileRow}=await sb.from("profiles").select("id").eq("team_id",user.id).maybeSingle();
      if(profileRow) await sb.from("profiles").update({color:corPerfil}).eq("id",profileRow.id);
    }catch(_){}
  };

  const save=()=>{
    _salvarCor();
    onSave(user.id,{nome,funcao,telefone,email,nascimento,photo,cidade,estado,camiseta,calcado,smartphone,time,estadoCivil,filhos,comidas,bebida,hobbies,musica,series,filmes,viagens,pets,curiosidades,medoOuFobia,superpoder,talento,licoesAprendidas,bio,habilidades,objetivos,obs});
    onClose();
  };

  // ═══ Segurança: trocar senha ═══
  const [currentPw,setCurrentPw]=useState("");
  const [newPw,setNewPw]=useState("");
  const [confirmPw,setConfirmPw]=useState("");
  const [showPws,setShowPws]=useState(false);
  const [pwLoading,setPwLoading]=useState(false);
  const [pwMsg,setPwMsg]=useState(null);

  const pwStrength=(()=>{
    const s=newPw;
    if(!s)return null;
    let score=0;
    if(s.length>=8)score++;
    if(s.length>=12)score++;
    if(/[A-Z]/.test(s)&&/[a-z]/.test(s))score++;
    if(/\d/.test(s))score++;
    if(/[^A-Za-z0-9]/.test(s))score++;
    if(score<=2)return{level:"fraca",color:"#dc2626",pct:30};
    if(score<=3)return{level:"média",color:"#eab308",pct:60};
    if(score<=4)return{level:"boa",color:"#16a34a",pct:80};
    return{level:"excelente",color:"#059669",pct:100};
  })();

  const handleChangePassword=async()=>{
    setPwMsg(null);
    if(!currentPw||!newPw||!confirmPw){
      setPwMsg({type:"error",text:"Preencha todos os campos."});return;
    }
    if(newPw.length<8){
      setPwMsg({type:"error",text:"A nova senha deve ter pelo menos 8 caracteres."});return;
    }
    if(newPw!==confirmPw){
      setPwMsg({type:"error",text:"A confirmação não bate com a nova senha."});return;
    }
    if(newPw===currentPw){
      setPwMsg({type:"error",text:"A nova senha tem que ser diferente da atual."});return;
    }
    setPwLoading(true);
    try{
      const sb=window._sb;
      // 1) Verifica a senha atual tentando relogar
      const{data:authData}=await sb.auth.getUser();
      const userEmail=authData?.user?.email;
      if(!userEmail){throw new Error("Email não encontrado na sessão. Faça login novamente.");}
      const{error:loginErr}=await sb.auth.signInWithPassword({email:userEmail,password:currentPw});
      if(loginErr){throw new Error("Senha atual incorreta.");}
      // 2) Atualiza a senha
      const{error:updErr}=await sb.auth.updateUser({password:newPw});
      if(updErr)throw new Error(updErr.message||"Falha ao atualizar a senha.");
      setPwMsg({type:"success",text:"Senha alterada com sucesso! Use a nova senha no próximo login."});
      setCurrentPw("");setNewPw("");setConfirmPw("");
    }catch(e){
      setPwMsg({type:"error",text:e.message||"Erro ao trocar senha."});
    }finally{
      setPwLoading(false);
    }
  };

  return (
    <div style={{position:"fixed",inset:0,background:"rgba(15,15,25,0.65)",zIndex:400,display:"flex",alignItems:"flex-start",justifyContent:"center",padding:"16px",overflowY:"auto",fontFamily:"'Inter',system-ui,sans-serif"}} onClick={onClose}>
      <div onClick={e=>e.stopPropagation()} style={{background:"#fff",borderRadius:20,width:"100%",maxWidth:760,marginTop:8,border:"1px solid #e2e8f0",boxShadow:"0 30px 80px rgba(15,15,25,0.35)",overflow:"hidden"}}>

        {/* ── Header premium ── */}
        <div style={{background:"linear-gradient(135deg,"+user.color+","+user.color+"cc 60%,"+user.color+"99)",padding:"22px 26px",position:"relative",overflow:"hidden"}}>
          {/* Decoração sutil */}
          <div style={{position:"absolute",top:-30,right:-30,width:160,height:160,borderRadius:"50%",background:"rgba(255,255,255,0.08)"}}/>
          <div style={{position:"absolute",bottom:-60,left:120,width:140,height:140,borderRadius:"50%",background:"rgba(255,255,255,0.06)"}}/>
          <div style={{position:"relative",zIndex:1,display:"flex",alignItems:"center",gap:16,flexWrap:"wrap"}}>
            <div onClick={()=>fileRef.current&&fileRef.current.click()} style={{width:68,height:68,borderRadius:18,background:"rgba(255,255,255,0.16)",border:"2px solid rgba(255,255,255,0.55)",overflow:"hidden",cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0,position:"relative",transition:"all .15s",backdropFilter:"blur(6px)"}}
              onMouseEnter={e=>{e.currentTarget.style.transform="scale(1.04)";e.currentTarget.style.borderColor="#fff";}}
              onMouseLeave={e=>{e.currentTarget.style.transform="scale(1)";e.currentTarget.style.borderColor="rgba(255,255,255,0.55)";}}>
              {uploadingPhoto?<Ico n="refresh" size={22} color="#fff"/>:photo?(<img src={photo} alt={user.name} style={{width:"100%",height:"100%",objectFit:"cover"}}/>):(<span style={{color:"#fff",fontWeight:900,fontSize:26,letterSpacing:-.5}}>{user.av}</span>)}
              <div style={{position:"absolute",bottom:0,left:0,right:0,background:"rgba(0,0,0,0.45)",padding:"3px 0",display:"flex",alignItems:"center",justifyContent:"center"}}>
                <Ico n="camera" size={11} color="#fff"/>
              </div>
            </div>
            <input ref={fileRef} type="file" accept="image/*" onChange={handlePhoto} style={{display:"none"}}/>
            <div style={{flex:1,minWidth:0}}>
              <div style={{color:"#fff",fontWeight:800,fontSize:22,letterSpacing:-.5,overflow:"hidden",textOverflow:"ellipsis"}}>{nome||"Sem nome"}</div>
              <div style={{color:"rgba(255,255,255,0.85)",fontSize:12.5,marginTop:3,fontWeight:500}}>{funcao||"—"}</div>
            </div>
            <div style={{display:"flex",gap:8,alignItems:"center"}}>
              <button onClick={onClose} style={{background:"rgba(0,0,0,0.25)",border:"1px solid rgba(255,255,255,0.2)",borderRadius:10,padding:"9px 12px",color:"#fff",cursor:"pointer",display:"flex",alignItems:"center",fontFamily:"inherit",transition:"all .15s"}}
                onMouseEnter={e=>e.currentTarget.style.background="rgba(0,0,0,0.4)"}
                onMouseLeave={e=>e.currentTarget.style.background="rgba(0,0,0,0.25)"}>
                <Ico n="x" size={14} color="#fff"/>
              </button>
            </div>
          </div>
        </div>

        {/* ── Tabs ── */}
        <div style={{display:"flex",gap:3,background:"#fafafa",padding:6,borderBottom:"1px solid #f1f5f9",overflowX:"auto"}}>
          {COLLAB_TABS.filter(t=>!t.selfOnly||user.id===CURRENT_USER.id).map(t=>{
            const active=activeTab===t.id;
            return <button key={t.id} onClick={()=>setActiveTab(t.id)}
              style={{flex:"1 1 0",minWidth:84,background:active?"#fff":"transparent",border:active?"1px solid #e2e8f0":"1px solid transparent",padding:"9px 6px",color:active?user.color:"#64748b",fontWeight:active?700:600,fontSize:11,cursor:"pointer",display:"flex",flexDirection:"column",alignItems:"center",gap:4,borderRadius:10,fontFamily:"'Inter',system-ui,sans-serif",transition:"all .12s",position:"relative",boxShadow:active?"0 2px 8px rgba(15,23,42,0.06)":"none"}}>
              <Ico n={t.ico} size={15} color={active?user.color:"#64748b"}/>
              <span>{t.label}</span>
              {active&&<div style={{position:"absolute",bottom:-7,left:"30%",right:"30%",height:2,background:user.color,borderRadius:2}}/>}
            </button>;
          })}
        </div>

        <div style={{padding:"20px 24px",display:"flex",flexDirection:"column",gap:14}}>

          {activeTab==="dados"&&(<div style={{display:"grid",gridTemplateColumns:_pxMob()?"1fr":"1fr 1fr",gap:12}}>
            <div><LBL t="Nome completo"/><input value={nome} onChange={e=>setNome(e.target.value)} style={inp} placeholder="Nome completo"/></div>
            <div><LBL t="Função / Cargo"/><input value={funcao} onChange={e=>setFuncao(e.target.value)} style={inp} placeholder="Ex: Designer, Editor..."/></div>
            <div><LBL t="Telefone / WhatsApp"/><input value={telefone} onChange={e=>setTelefone(e.target.value)} style={inp} placeholder="(49) 9 9900-0000"/></div>
            <div><LBL t="Data de Nascimento"/><input type="date" value={nascimento} onChange={e=>setNascimento(e.target.value)} style={inp}/></div>
            <div style={{gridColumn:"1/-1"}}><LBL t="E-mail profissional"/><input type="email" value={email} onChange={e=>setEmail(e.target.value)} style={inp} placeholder="email@pixelsmarketing.com.br"/></div>
            <div style={{gridColumn:"1/-1"}}>
              <LBL t="Cor no sistema"/>
              <div style={{display:"flex",gap:8,flexWrap:"wrap",alignItems:"center"}}>
                {["#ec4899","#e040fb","#9F43F6","#7c3aed","#6366f1","#2563eb","#0ea5e9","#0d9488","#16a34a","#f59e0b","#ea580c","#ef4444","#475569"].map(c=>(
                  <button key={c} type="button" onClick={()=>setCorPerfil(c)} title={c}
                    style={{width:30,height:30,borderRadius:9,background:c,border:corPerfil===c?"3px solid #0f172a":"3px solid transparent",cursor:"pointer",padding:0,boxShadow:corPerfil===c?"0 3px 10px "+c+"60":"none",transition:"all .12s"}}/>
                ))}
                <span style={{color:"#94a3b8",fontSize:11,fontWeight:600,marginLeft:4}}>Usada no avatar, cards e por todo o app</span>
              </div>
            </div>
          </div>)}

          {activeTab==="pessoal"&&(<div style={{display:"grid",gridTemplateColumns:_pxMob()?"1fr":"1fr 1fr",gap:12}}>
            <div><LBL t="Cidade onde mora"/><input value={cidade} onChange={e=>setCidade(e.target.value)} style={inp} placeholder="Ex: Chapeco"/></div>
            <div><LBL t="Estado"/><select value={estado} onChange={e=>setEstado(e.target.value)} style={inp}>
              <option value="">Selecionar...</option>
              {["AC","AL","AM","AP","BA","CE","DF","ES","GO","MA","MG","MS","MT","PA","PB","PE","PI","PR","RJ","RN","RO","RR","RS","SC","SE","SP","TO"].map(s=>(<option key={s}>{s}</option>))}
            </select></div>
            <div><LBL t="Estado civil"/><select value={estadoCivil} onChange={e=>setEstadoCivil(e.target.value)} style={inp}>
              <option value="">Selecionar...</option>
              {["Solteiro(a)","Namorando","Noivo(a)","Casado(a)","Divorciado(a)","Viuvo(a)"].map(s=>(<option key={s}>{s}</option>))}
            </select></div>
            <div><LBL t="Tem filhos?"/><select value={filhos} onChange={e=>setFilhos(e.target.value)} style={inp}>
              <option value="">Selecionar...</option>
              <option>Nao</option><option>1 filho</option><option>2 filhos</option><option>3 filhos</option><option>4 ou mais</option>
            </select></div>
            <div><LBL t="Tamanho de camiseta"/><select value={camiseta} onChange={e=>setCamiseta(e.target.value)} style={inp}>
              <option value="">Selecionar...</option>
              {["PP","P","M","G","GG","XGG","XGGGG"].map(s=>(<option key={s}>{s}</option>))}
            </select></div>
            <div><LBL t="Numero de calcado"/><input value={calcado} onChange={e=>setCalcado(e.target.value)} style={inp} placeholder="Ex: 42"/></div>
            <div><LBL t="Smartphone"/><select value={smartphone} onChange={e=>setSmartphone(e.target.value)} style={inp}>
              <option value="">Selecionar...</option>
              <option>Android</option><option>iOS (iPhone)</option><option>Ambos</option>
            </select></div>
            <div><LBL t="Time que torce"/><input value={time} onChange={e=>setTime(e.target.value)} style={inp} placeholder="Ex: Chapecoense, Flamengo..."/></div>
          </div>)}

          {activeTab==="lazer"&&(<div style={{display:"flex",flexDirection:"column",gap:12}}>
            <div>
              <LBL t="5 comidas favoritas"/>
              <div style={{display:"flex",flexDirection:"column",gap:6}}>
                {comidas.map((c,i)=>(<div key={i} style={{display:"flex",alignItems:"center",gap:8}}>
                  <span style={{color:C.td,fontSize:11,fontWeight:700,width:20,flexShrink:0}}>{"#"+(i+1)}</span>
                  <input value={c} onChange={e=>setComidas(v=>v.map((x,j)=>j===i?e.target.value:x))} style={inp} placeholder={"Comida favorita #"+(i+1)}/>
                </div>))}
              </div>
            </div>
            <div style={{display:"grid",gridTemplateColumns:_pxMob()?"1fr":"1fr 1fr",gap:12}}>
              <div><LBL t="Bebida favorita"/><input value={bebida} onChange={e=>setBebida(e.target.value)} style={inp} placeholder="Ex: Cafe, Suco de laranja..."/></div>
              <div><LBL t="Estilo musical"/><input value={musica} onChange={e=>setMusica(e.target.value)} style={inp} placeholder="Ex: Sertanejo, Rock, Funk..."/></div>
            </div>
            <div><LBL t="Principais hobbies"/><textarea value={hobbies} onChange={e=>setHobbies(e.target.value)} rows={2} placeholder="Ex: Jogar videogame, academia, pesca, leitura..." style={{...inp,resize:"vertical",lineHeight:1.6}}/></div>
            <div style={{display:"grid",gridTemplateColumns:_pxMob()?"1fr":"1fr 1fr",gap:12}}>
              <div><LBL t="Series que assiste"/><input value={series} onChange={e=>setSeries(e.target.value)} style={inp} placeholder="Ex: Breaking Bad..."/></div>
              <div><LBL t="Filmes favoritos"/><input value={filmes} onChange={e=>setFilmes(e.target.value)} style={inp} placeholder="Ex: Interestelar..."/></div>
            </div>
            <div><LBL t="Cidades/paises que ja viajou ou quer conhecer"/><textarea value={viagens} onChange={e=>setViagens(e.target.value)} rows={2} placeholder="Ex: Ja fui: Floripa, SP. Quero: Portugal, Japao..." style={{...inp,resize:"vertical",lineHeight:1.6}}/></div>
          </div>)}

          {activeTab==="pets"&&(<div style={{display:"flex",flexDirection:"column",gap:12}}>
            <div style={{color:C.ts,fontSize:12}}>Cadastre ate 10 pets.</div>
            {pets.map((pet,i)=>(<div key={i} style={{background:C.s1,borderRadius:14,padding:"14px 16px",border:"1px solid "+C.b1}}>
              <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:12}}>
                <div style={{color:user.color,fontWeight:800,fontSize:12}}>{"Pet #"+(i+1)}</div>
                {pets.length>1&&(<button onClick={()=>removePet(i)} style={{background:"#ff3d6b18",border:"1px solid #ff3d6b44",borderRadius:8,padding:"3px 10px",color:"#ff3d6b",fontSize:11,fontWeight:700,cursor:"pointer"}}>Remover</button>)}
              </div>
              <div style={{display:"grid",gridTemplateColumns:_pxMob()?"1fr":"1fr 1fr",gap:10}}>
                <div><LBL t="Você tem pet?"/><select value={pet.tem} onChange={e=>setPetField(i,"tem",e.target.value)} style={inp}>
                  <option value="">Selecionar...</option>
                  <option value="sim">Sim, tenho!</option>
                  <option value="nao">Não tenho</option>
                  <option value="quero">Não tenho, mas quero</option>
                </select></div>
                {pet.tem==="sim"&&(<>
                  <div><LBL t="Especie"/><select value={pet.especie} onChange={e=>setPetField(i,"especie",e.target.value)} style={inp}>
                    <option value="">Selecionar...</option>
                    <option>Cachorro</option><option>Gato</option><option>Passaro</option><option>Peixe</option><option>Hamster</option><option>Coelho</option><option>Outro</option>
                  </select></div>
                  <div><LBL t="Nome do pet"/><input value={pet.nome} onChange={e=>setPetField(i,"nome",e.target.value)} style={inp} placeholder="Ex: Rex, Mimi..."/></div>
                  <div><LBL t="Raca"/><input value={pet.raca} onChange={e=>setPetField(i,"raca",e.target.value)} style={inp} placeholder="Ex: Labrador, Vira-lata..."/></div>
                  <div><LBL t="Idade"/><input value={pet.idade} onChange={e=>setPetField(i,"idade",e.target.value)} style={inp} placeholder="Ex: 3 anos"/></div>
                </>)}
              </div>
            </div>))}
            {pets.length<10&&(<button onClick={addPet} style={{background:"transparent",border:"2px dashed "+user.color+"44",borderRadius:14,padding:"12px",color:user.color,fontWeight:700,fontSize:12,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",gap:8}}>
              {"+ Adicionar outro pet"}
            </button>)}
          </div>)}

          {activeTab==="curiosidades"&&(<div style={{display:"flex",flexDirection:"column",gap:12}}>
            <div style={{display:"grid",gridTemplateColumns:_pxMob()?"1fr":"1fr 1fr",gap:12}}>
              <div><LBL t="Tem algum medo ou fobia?"/><input value={medoOuFobia} onChange={e=>setMedoOuFobia(e.target.value)} style={inp} placeholder="Ex: Aranhas, altura..."/></div>
              <div><LBL t="Se tivesse um superpoder?"/><input value={superpoder} onChange={e=>setSuperpoder(e.target.value)} style={inp} placeholder="Ex: Teleporte..."/></div>
              <div><LBL t="Um talento secreto seu?"/><input value={talento} onChange={e=>setTalento(e.target.value)} style={inp} placeholder="Ex: Imitar vozes..."/></div>
              <div><LBL t="Maior licao que ja aprendeu"/><input value={licoesAprendidas} onChange={e=>setLicoesAprendidas(e.target.value)} style={inp} placeholder="Ex: Nunca desistir..."/></div>
            </div>
            <div><LBL t="Outras curiosidades sobre você"/><textarea value={curiosidades} onChange={e=>setCuriosidades(e.target.value)} rows={3} placeholder="Conte algo inusitado, divertido ou marcante sobre você..." style={{...inp,resize:"vertical",lineHeight:1.7}}/></div>
          </div>)}

          {activeTab==="bio"&&(<div style={{display:"flex",flexDirection:"column",gap:12}}>
            <div><LBL t="Sua bio (apresentação geral)"/><textarea value={bio} onChange={e=>setBio(e.target.value)} rows={4} placeholder="Apresente-se: quem e você, de onde vem..." style={{...inp,resize:"vertical",lineHeight:1.7}}/></div>
            <div><LBL t="Habilidades e ferramentas"/><textarea value={habilidades} onChange={e=>setHabilidades(e.target.value)} rows={2} placeholder="Ex: Photoshop, Premiere, Google Ads..." style={{...inp,resize:"vertical",lineHeight:1.7}}/></div>
            <div><LBL t="Objetivos profissionais"/><textarea value={objetivos} onChange={e=>setObjetivos(e.target.value)} rows={2} placeholder="O que você quer alcançar na carreira?" style={{...inp,resize:"vertical",lineHeight:1.7}}/></div>
            <div><LBL t="Observacoes gerais"/><textarea value={obs} onChange={e=>setObs(e.target.value)} rows={2} placeholder="Disponibilidade, preferencias de trabalho..." style={{...inp,resize:"vertical",lineHeight:1.7}}/></div>
          </div>)}

          {/* ═══ ABA SEGURANÇA — trocar senha (só no próprio perfil) ═══ */}
          {activeTab==="seguranca"&&user.id===CURRENT_USER.id&&(<div style={{display:"flex",flexDirection:"column",gap:16,maxWidth:500}}>
            <div style={{background:"#eff6ff",border:"1px solid #bfdbfe",borderRadius:12,padding:"14px 16px",display:"flex",gap:12,alignItems:"flex-start"}}>
              <div style={{width:38,height:38,borderRadius:11,background:"#2563eb",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}><Ico n="lock" size={17} color="#fff"/></div>
              <div>
                <div style={{color:"#1e40af",fontWeight:800,fontSize:13,marginBottom:3}}>Trocar sua senha</div>
                <div style={{color:"#1e40af",fontSize:11,lineHeight:1.5}}>
                  Use uma senha forte com letras maiúsculas, minúsculas, números e símbolos. Mínimo 8 caracteres.
                </div>
              </div>
            </div>

            <div><LBL t="Senha atual"/>
              <input type={showPws?"text":"password"} value={currentPw} onChange={e=>setCurrentPw(e.target.value)}
                style={inp} placeholder="Digite sua senha atual" autoComplete="current-password"/>
            </div>

            <div><LBL t="Nova senha"/>
              <input type={showPws?"text":"password"} value={newPw} onChange={e=>setNewPw(e.target.value)}
                style={inp} placeholder="Mínimo 8 caracteres" autoComplete="new-password"/>
              {pwStrength&&<div style={{marginTop:6}}>
                <div style={{background:"#e5e7eb",borderRadius:99,height:4,overflow:"hidden"}}>
                  <div style={{width:pwStrength.pct+"%",height:"100%",background:pwStrength.color,transition:"width .3s"}}/>
                </div>
                <div style={{color:pwStrength.color,fontSize:10,fontWeight:700,marginTop:4,textTransform:"uppercase",letterSpacing:.5}}>
                  Força: {pwStrength.level}
                </div>
              </div>}
            </div>

            <div><LBL t="Confirmar nova senha"/>
              <input type={showPws?"text":"password"} value={confirmPw} onChange={e=>setConfirmPw(e.target.value)}
                style={inp} placeholder="Digite a nova senha de novo"/>
              {confirmPw&&newPw&&confirmPw!==newPw&&(
                <div style={{color:"#dc2626",fontSize:10.5,fontWeight:700,marginTop:5,display:"inline-flex",alignItems:"center",gap:4}}><Ico n="alert" size={10} color="#dc2626"/> As senhas não batem</div>
              )}
            </div>

            <label style={{display:"flex",alignItems:"center",gap:8,cursor:"pointer",color:C.ts,fontSize:12}}>
              <input type="checkbox" checked={showPws} onChange={e=>setShowPws(e.target.checked)}/>
              Mostrar senhas
            </label>

            {pwMsg&&<div style={{
              background:pwMsg.type==="success"?"#f0fdf4":"#fef2f2",
              border:`1px solid ${pwMsg.type==="success"?"#bbf7d0":"#fecaca"}`,
              color:pwMsg.type==="success"?"#166534":"#991b1b",
              borderRadius:10,padding:"10px 14px",fontSize:12,fontWeight:600}}>
              {pwMsg.text}
            </div>}

            <button onClick={handleChangePassword} disabled={pwLoading||!currentPw||!newPw||!confirmPw}
              style={{background:pwLoading||!currentPw||!newPw||!confirmPw?"#cbd5e1":"linear-gradient(135deg,#2563eb,#1d4ed8)",
                color:"#fff",border:"none",borderRadius:11,padding:"12px 0",
                fontWeight:700,fontSize:13,cursor:pwLoading||!currentPw||!newPw||!confirmPw?"not-allowed":"pointer",
                display:"flex",alignItems:"center",justifyContent:"center",gap:7,
                fontFamily:"'Inter',system-ui,sans-serif",
                boxShadow:pwLoading||!currentPw||!newPw||!confirmPw?"none":"0 6px 18px rgba(37,99,235,.32)",
                transition:"transform .12s"}}>
              {pwLoading?"Alterando...":<><Ico n="lock" size={13} color="#fff"/> Trocar senha</>}
            </button>
          </div>)}

          <div style={{display:"flex",gap:10,marginTop:6,paddingTop:16,borderTop:"1px solid #f1f5f9"}}>
            <button onClick={onClose}
              style={{flex:"0 0 auto",background:"#fff",border:"1px solid #e2e8f0",borderRadius:11,padding:"11px 22px",color:"#475569",fontWeight:600,cursor:"pointer",fontSize:13,fontFamily:"'Inter',system-ui,sans-serif",transition:"all .15s"}}
              onMouseEnter={e=>{e.currentTarget.style.borderColor="#cbd5e1";e.currentTarget.style.background="#f8fafc";}}
              onMouseLeave={e=>{e.currentTarget.style.borderColor="#e2e8f0";e.currentTarget.style.background="#fff";}}>
              Cancelar
            </button>
            <button onClick={save}
              style={{flex:1,background:"linear-gradient(135deg,"+user.color+","+user.color+"cc)",color:"#fff",border:"none",borderRadius:11,padding:"12px 0",fontWeight:700,cursor:"pointer",fontSize:13.5,fontFamily:"'Inter',system-ui,sans-serif",display:"inline-flex",alignItems:"center",justifyContent:"center",gap:7,boxShadow:"0 6px 18px "+user.color+"40",transition:"transform .12s"}}
              onMouseEnter={e=>e.currentTarget.style.transform="translateY(-1px)"}
              onMouseLeave={e=>e.currentTarget.style.transform="translateY(0)"}>
              <Ico n="check" size={14} color="#fff"/> Salvar perfil completo
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

/* ─── Constantes de nível — fora do componente ─── */
const LEVEL_LABELS={1:"Gestão",2:"Coordenação",3:"Colaborador",5:"Cliente"};
const LEVEL_COLORS={1:C.a,2:C.pk,3:C.bl,4:C.yw,5:C.gr};

const LEVEL_FILTER_BUTTONS=[{v:0,l:"Todos"},{v:1,l:"Gestão"},{v:2,l:"Coordenação"},{v:3,l:"Colaborador"}];

const EMPTY_PET={tem:"",nome:"",especie:"",raca:"",idade:""};

const defaultClientAccess=(cl)=>({
  enabled:false,
  login:cl.name.toLowerCase().replace(/\s+/g,".")+".cliente",
  senha:"pixels@"+new Date().getFullYear(),
  modulos:{dashboard:true,demandas:true,calendario:true,chat:true,analises:false,faturamento:false},
  updatedAt:null,
});

const PORTAL_MODULES=[
  {id:"dashboard",   label:"Dashboard",               icon:"home",        desc:"Visão geral da empresa"},
  {id:"demandas",    label:"Demandas",                icon:"kanban",      desc:"Acompanhamento de demandas"},
  {id:"calendario",  label:"Calendário de Publicações",icon:"calendar",   desc:"Calendário linkado ao interno"},
  {id:"chat",        label:"Chat",                    icon:"message",     desc:"Canal exclusivo com a equipe"},
  {id:"analises",    label:"Análises",                icon:"chart",       desc:"Tráfego Pago e Redes Sociais"},
  {id:"faturamento", label:"Faturamento",             icon:"wallet",      desc:"Contratos e faturas"},
];

const MAIN_TABS=[["clientes","Clientes"],["equipe","Time"],["ferramentas","Ferramentas"],["redes","Redes sociais"],["senhas","Senhas"],["storage","Storage"]];

const MEMBER_TABLE_HEADERS=["Colaborador","Função","Nível","Demandas","Status","Ações"];

const CLIENT_TABLE_HEADERS=["Cliente","Email do portal","Unidade(s)","Status","Ações"];

const LEVEL_STRUCTURE=[
  {l:1,name:"Gestão",      c:C.a,  desc:"Acesso total ao sistema. Gerenciam tudo, todos os módulos e permissões."},
  {l:2,name:"Coordenação", c:C.pk, desc:"Coordena equipe, aprova entregas, gerencia clientes."},
  {l:3,name:"Colaborador", c:C.bl, desc:"Designers, editores e gestores. Dashboard próprio, vê só o que foi designado pra ele."},
  {l:5,name:"Clientes",    c:C.gr, desc:"Portal de aprovações e acompanhamento das demandas."},
];

function PageAcessos({livePerms,setLivePerms,onViewAs,onViewAsClient,tasks}){
  const [viewUser,setViewUser]=useState(null);
  const [viewDash,setViewDash]=useState(null);
  const [editCollab,setEditCollab]=useState(null);
  const [editProfile,setEditProfile]=useState(null);

  const [search,setSearch]=useState("");
  const [filterLevel,setFilterLevel]=useState(0);
  const isMePartner=CURRENT_USER.level===1; // renomeado pra não conflitar com global isPartner(uid)
  const _podeSenhas=CURRENT_USER.id==="gustavo"||CURRENT_USER.id==="vinicius"; // cofre de senhas só CEOs
  const myPerms=withPartnerOverride({...DEFAULT_PERMS,...(ACCESS_STORE[CURRENT_USER.id]||{})}, CURRENT_USER.id);
  const [collabProfiles,setCollabProfiles]=useState(()=>{
    // Carrega perfis do localStorage como cache inicial
    const out={};
    TEAM.forEach(u=>{
      try{
        const s=localStorage.getItem("pixels-selfprofile-"+u.id);
        if(s)out[u.id]=JSON.parse(s);
      }catch(e){}
    });
    return out;
  });

  // Carregar perfis do Supabase ao montar (fonte de verdade)
  useEffect(()=>{
    const loadProfiles=async()=>{
      try{
        const sb=window._sb;
        const{data:rows}=await sb.from("profiles").select("id,team_id,profile_data").not("profile_data","is",null);
        if(!rows)return;
        const updates={};
        rows.forEach(row=>{
          if(!row.profile_data)return;
          const _key = row.team_id || row.id;
          if(_key){
            updates[_key]=row.profile_data;
            try{localStorage.setItem("pixels-selfprofile-"+row.team_id,JSON.stringify(row.profile_data));}catch(e){}
          }
        });
        if(Object.keys(updates).length>0){
          setCollabProfiles(p=>({...p,...updates}));
        }
      }catch(e){console.warn("Erro ao carregar perfis do Supabase:",e);}
    };
    loadProfiles();
  },[]);

  // ═════ Cofre de senhas de login do time (só sócios level 1 veem) ═════
  const [loginSecrets,setLoginSecrets]=useState({});
  const [revealPwd,setRevealPwd]=useState({});
  const [resetPwd,setResetPwd]=useState({open:false,teamId:null,nome:"",value:"",busy:false});
  useEffect(()=>{
    if(!isMePartner)return;
    (async()=>{
      try{
        const sb=window._sb;
        const{data:rows}=await sb.from("team_login_secrets").select("team_id,senha,email,updated_at");
        if(rows){
          const m={};
          rows.forEach(r=>{if(r.team_id)m[r.team_id]={senha:r.senha,email:r.email,updated_at:r.updated_at};});
          setLoginSecrets(m);
        }
      }catch(e){console.warn("[acessos] login secrets:",e&&e.message?e.message:e);}
    })();
  },[isMePartner]);
  const _redefinirSenhaSubmit=async()=>{
    const teamId=resetPwd.teamId, nova=resetPwd.value;
    if(!teamId)return;
    if(!nova||nova.length<6){if(typeof pixelsToast!=="undefined")pixelsToast.warning("Senha precisa de no mínimo 6 caracteres.");return;}
    setResetPwd(p=>({...p,busy:true}));
    try{
      const sb=window._sb;
      const{data:sess}=await sb.auth.getSession();
      const tok=sess?.session?.access_token;
      const url=(typeof import.meta!=="undefined"?import.meta.env.VITE_SUPABASE_URL:"")||"https://jffvoojcskwumnphsedq.supabase.co";
      const res=await fetch(url+"/functions/v1/set-collaborator-password",{
        method:"POST",
        headers:{"Authorization":"Bearer "+tok,"Content-Type":"application/json"},
        body:JSON.stringify({team_id:teamId,password:nova}),
      });
      const data=await res.json().catch(()=>({error:"Resposta inválida do servidor"}));
      if(!res.ok){if(typeof pixelsToast!=="undefined")pixelsToast.error(data.error||"Falha ao redefinir senha.");setResetPwd(p=>({...p,busy:false}));return;}
      setLoginSecrets(m=>({...m,[teamId]:Object.assign({},m[teamId]||{},{senha:nova,updated_at:new Date().toISOString()})}));
      setRevealPwd(m=>({...m,[teamId]:true}));
      if(typeof pixelsToast!=="undefined")pixelsToast.success("Senha redefinida! Agora aparece aqui pros sócios.");
      setResetPwd({open:false,teamId:null,nome:"",value:"",busy:false});
    }catch(e){
      if(typeof pixelsToast!=="undefined")pixelsToast.error("Erro: "+(e&&e.message?e.message:e));
      setResetPwd(p=>({...p,busy:false}));
    }
  };

  const [mainTab,setMainTab]=useState("clientes");
  const [teamRev,setTeamRev]=useState(0);
  useEffect(()=>{
    const onTeamUpdate=()=>setTeamRev(r=>r+1);
    window.addEventListener("pixels:team-updated",onTeamUpdate);
    return()=>window.removeEventListener("pixels:team-updated",onTeamUpdate);
  },[]);
  const [novoColabOpen,setNovoColabOpen]=useState(false);
  const [novoColabBusy,setNovoColabBusy]=useState(false);
  const [novoColab,setNovoColab]=useState({
    name:"", email:"", password:"", team_id:"",
    role:"Designer", dash:"designer", color:"#ec4899", av:"", level:3,
    photo_base64:"", photo_mime:""
  });

  // ── NOVO ACESSO CLIENTE (chama Edge Function create-client-user) ──
  // Cria usuário Supabase Auth com user_type='client' e primary_client=<cliente>.
  // Pra cliente logar no portal usando email+senha próprios.
  const [novoClienteOpen,setNovoClienteOpen]=useState(false);
  const [novoClienteBusy,setNovoClienteBusy]=useState(false);
  const [novoCliente,setNovoCliente]=useState({
    client_id:"", client_unit:"", email:"", password:"", name:"", papel:"admin",
    photo_base64:"", photo_mime:""
  });

  // Lista de auth users do tipo "client" carregada do Supabase
  // Map { client_id: [ {id,email,primary_unit,name,photo}, ... ] }
  const [clientAuthUsers,setClientAuthUsers]=useState({});
  const [clientAuthLoading,setClientAuthLoading]=useState(false);
  // Mapa email -> senha (do team_passwords category=cliente) pra sócio consultar
  const [clientPasswordsByEmail,setClientPasswordsByEmail]=useState({});
  const [revealedPasswords,setRevealedPasswords]=useState({});
  const [buscaCliente,setBuscaCliente]=useState("");
  const reloadClientPasswords=async()=>{
    try{
      const sb=window._sb;
      const{data,error}=await sb.from("team_passwords").select("username,password").eq("category","cliente");
      if(error||!data)return;
      const map={};
      data.forEach(r=>{ if(r.username && r.password) map[String(r.username).toLowerCase().trim()]=r.password; });
      setClientPasswordsByEmail(map);
    }catch(e){console.warn("[acessos] reloadClientPasswords:",e);}
  };
  useEffect(()=>{reloadClientPasswords();},[]);
  const reloadClientAuthUsers=async()=>{
    try{
      setClientAuthLoading(true);
      const sb=window._sb;
      // 1) Buscar contatos de todos os clientes (fallback pra foto)
      // Foto do Douglas/Rodrigo foi cadastrada em "Contatos do Cliente" (clients.contatos JSONB)
      // Mapa: contactsByClient[client_id] = [{name, email, photo, ...}]
      let contactsByClient={};
      try{
        const{data:_cdata}=await sb.from("clients").select("client_id,contatos");
        if(Array.isArray(_cdata)){
          _cdata.forEach(function(row){
            const _cid=row.client_id||"";
            const _list=Array.isArray(row.contatos)?row.contatos:[];
            if(_cid && _list.length>0) contactsByClient[_cid]=_list;
          });
        }
      }catch(_e){ console.warn("[acessos] load contatos:", _e && _e.message ? _e.message : _e); }

      // 2) Buscar auth users tipo cliente
      const{data,error}=await sb.from("profiles")
        .select("id,name,primary_client,primary_unit,profile_data,permissions")
        .eq("user_type","client");
      if(error||!data){setClientAuthLoading(false);return;}
      const byClient={};
      data.forEach(p=>{
        const cid=p.primary_client||"";
        if(!cid)return;
        const pd=p.profile_data||{};
        // Fallback de foto: se profile_data.photo vazio, tenta achar em contatos do cliente por email OU nome
        let _photo = pd.photo||"";
        if(!_photo){
          const _contacts = contactsByClient[cid]||[];
          const _uemail = String(pd.email||"").toLowerCase().trim();
          const _uname = String(p.name||"").toLowerCase().trim();
          const _uFirstName = _uname.split(" ")[0];
          const _match = _contacts.find(function(c){
            const _cemail = String(c.email||"").toLowerCase().trim();
            const _cname = String(c.name||"").toLowerCase().trim();
            if(_uemail && _cemail && _uemail===_cemail) return true;
            if(_uname && _cname && _uname===_cname) return true;
            // Match parcial pelo primeiro nome se o contato inclui o primeiro nome
            if(_uFirstName && _cname && _cname.indexOf(_uFirstName)>=0) return true;
            return false;
          });
          if(_match && _match.photo) _photo = _match.photo;
        }
        if(!byClient[cid])byClient[cid]=[];
        byClient[cid].push({
          id:p.id,
          name:p.name||"",
          email:pd.email||"",
          photo:_photo,
          primary_unit:p.primary_unit||"",
          primary_client:cid,
          client_id:cid,
          user_type:"client",
          permissions:p.permissions||{},
        });
      });
      setClientAuthUsers(byClient);
    }catch(e){console.warn("[acessos] reloadClientAuthUsers:",e);}
    finally{setClientAuthLoading(false);}
  };
  useEffect(()=>{reloadClientAuthUsers();},[]);

  // ── Registro de clientes (CLIENTS) — a pagina de Acessos nao carregava os
  // clientes dinamicos do Supabase (Lero Fibras, Construcoes Clem...), entao
  // so aparecia quem estava hardcoded + cache local. Carrega e re-renderiza.
  const [,_bumpClients]=useState(0);
  useEffect(()=>{
    let alive=true;
    const _bump=()=>{ if(alive) _bumpClients(n=>n+1); };
    try{
      if(typeof window.loadDynamicClientsFromSupabase==="function"){
        window.loadDynamicClientsFromSupabase().then(_bump).catch(()=>{});
      }
    }catch(_){}
    try{ window.addEventListener("pixels:clients-registry-updated",_bump); }catch(_){}
    return ()=>{ alive=false; try{ window.removeEventListener("pixels:clients-registry-updated",_bump); }catch(_){} };
  },[]);

  // === Excluir colaborador (Edge Function delete-collaborator) ===
  const revogarColabAcesso = async (teamId, nome) => {
    if(teamId==="vinicius"||teamId==="gustavo"){
      if(typeof pixelsToast!=="undefined")pixelsToast.warning("Sócios não podem ser excluídos.");
      return;
    }
    if(typeof pixelsConfirm==="function"){
      const ok=await pixelsConfirm("Excluir o colaborador '"+nome+"'?\nO acesso dele ao sistema será removido permanentemente.",{okText:"Excluir colaborador",danger:true});
      if(!ok)return;
    }else if(!confirm("Excluir '"+nome+"'?"))return;
    try{
      const sb=window._sb;
      // Membro do cadastro fixo sem login (ex: Ocsana)? Não tem o que excluir no auth —
      // só esconde do app (compartilhado entre todos os navegadores).
      let _temProfile=false;
      try{
        const {data:_pr}=await sb.from("profiles").select("id").eq("team_id",teamId).maybeSingle();
        _temProfile=!!_pr;
      }catch(_){}
      if(!_temProfile){
        await _pixelsOcultarMembro(teamId);
        if(typeof pixelsToast!=="undefined")pixelsToast.success("Colaborador removido.");
        setTimeout(()=>window.location.reload(),1200);
        return;
      }
      await sb.auth.refreshSession().catch(()=>{});
      const{data:sess}=await sb.auth.getSession();
      const tok=sess?.session?.access_token;
      if(!tok){if(typeof pixelsToast!=="undefined")pixelsToast.error("Sessão expirou. Faça logout/login.");return;}
      const url=(typeof import.meta!=="undefined"?import.meta.env.VITE_SUPABASE_URL:"")||"https://jffvoojcskwumnphsedq.supabase.co";
      const res=await fetch(url+"/functions/v1/delete-collaborator",{
        method:"POST",
        headers:{"Authorization":"Bearer "+tok,"Content-Type":"application/json"},
        body:JSON.stringify({team_id:teamId}),
      });
      const data=await res.json();
      if(!res.ok){
        if(typeof pixelsToast!=="undefined")pixelsToast.error(data.error||"Falha ao excluir.");
        return;
      }
      await _pixelsOcultarMembro(teamId);
      if(typeof pixelsToast!=="undefined")pixelsToast.success("Colaborador removido.");
      setTimeout(()=>window.location.reload(),1500);
    }catch(e){
      if(typeof pixelsToast!=="undefined")pixelsToast.error("Erro: "+String(e?.message||e));
    }
  };

  const revogarClienteAcesso=async(authUserId,clientName)=>{
    if(!(await pixelsConfirm(
      "Revogar acesso de "+clientName+"?\nIsso vai apagar o login do cliente. Ele não vai mais conseguir acessar o portal.",
      {okText:"Revogar acesso",danger:true}
    )))return;
    try{
      const sb=window._sb;
      const{data:sess}=await sb.auth.getSession();
      const tok=sess?.session?.access_token;
      const url=(typeof import.meta!=="undefined"?import.meta.env.VITE_SUPABASE_URL:"")||"https://jffvoojcskwumnphsedq.supabase.co";
      const res=await fetch(url+"/functions/v1/delete-client-user",{
        method:"POST",
        headers:{"Authorization":"Bearer "+tok,"Content-Type":"application/json"},
        body:JSON.stringify({user_id:authUserId}),
      });
      const data=await res.json();
      if(!res.ok){
        if(typeof pixelsToast!=="undefined")pixelsToast.error(data.error||"Falha ao revogar acesso.");
        return;
      }
      if(typeof pixelsToast!=="undefined")pixelsToast.success("Acesso revogado.");
      reloadClientAuthUsers();
    }catch(e){
      if(typeof pixelsToast!=="undefined")pixelsToast.error("Erro: "+String(e?.message||e));
    }
  };

  const [clientAccess,setClientAccess]=useState(()=>{
    const acc={};
    CLIENTS.filter(c=>c.status!=="interno").forEach(cl=>{
      try{
        const s=localStorage.getItem("pixels-portal-access-"+cl.id);
        acc[cl.id]=s?JSON.parse(s):defaultClientAccess(cl);
      }catch(e){acc[cl.id]=defaultClientAccess(cl);}
    });
    return acc;
  });

  const [editClientId,setEditClientId]=useState(null);
  const [editClientDraft,setEditClientDraft]=useState(null);

  const saveClientAccess=(clientId,data)=>{
    const updated={...data,updatedAt:new Date().toISOString()};
    setClientAccess(p=>({...p,[clientId]:updated}));
    try{localStorage.setItem("pixels-portal-access-"+clientId,JSON.stringify(updated));}catch(e){}
  };

  const toggleClientEnabled=(clientId)=>{
    const cur=clientAccess[clientId];
    if(!cur)return;
    saveClientAccess(clientId,{...cur,enabled:!cur.enabled});
  };

  const openEditClient=(clientId)=>{
    const cur=clientAccess[clientId];
    if(!cur)return;
    setEditClientId(clientId);
    setEditClientDraft({...cur});
  };

  const saveEditClient=()=>{
    if(!editClientId||!editClientDraft)return;
    saveClientAccess(editClientId,editClientDraft);
    setEditClientId(null);setEditClientDraft(null);
  };

  // filtered team
  const allMembers=TEAM.filter(u=>{
    const matchSearch=search===""||u.name.toLowerCase().includes(search.toLowerCase())||u.role.toLowerCase().includes(search.toLowerCase());
    const matchLevel=filterLevel===0||u.level===filterLevel;
    return matchSearch&&matchLevel;
  });

  const taskCount=(uid)=>(tasks||[]).filter(t=>t.assignee===uid&&!t.deletedAt).length;
  const doneCount=(uid)=>(tasks||[]).filter(t=>t.assignee===uid&&!t.deletedAt&&t.status==="aprovado").length;

  if(viewDash){
    const u=TEAM.find(x=>x.id===viewDash);
    if(!u)return null;
    return <div style={{display:"flex",flexDirection:"column",gap:0}}>
      <button onClick={()=>setViewDash(null)} style={{background:C.b1,border:"none",borderRadius:10,padding:"9px 16px",color:C.ts,cursor:"pointer",fontSize:12,fontWeight:700,alignSelf:"flex-start",marginBottom:16}}>{"<- Voltar"}</button>
      <RenderDash user={u} isViewing={true} tasks={tasks||[]} setTasks={()=>{}}/>
    </div>;
  }

  if(viewUser)return <div style={{display:"flex",flexDirection:"column",gap:0}}>
    <button onClick={()=>setViewUser(null)} style={{background:C.b1,border:"none",borderRadius:10,padding:"9px 16px",color:C.ts,cursor:"pointer",fontSize:12,fontWeight:700,alignSelf:"flex-start",marginBottom:16}}>{"<- Voltar"}</button>
    <RenderDash user={viewUser} isViewing={true} tasks={tasks||[]} setTasks={()=>{}}/>
  </div>;

  const collabUser=editCollab?TEAM.find(u=>u.id===editCollab):null;
  const profileUser=editProfile?TEAM.find(u=>u.id===editProfile):null;

  return (<>
    {collabUser&&(<CollabProfileModal user={collabUser} onClose={()=>setEditCollab(null)} livePerms={livePerms} setLivePerms={setLivePerms} tasks={tasks}/>)}
    {profileUser&&(<CollabProfilePage
      user={profileUser}
      profile={collabProfiles[editProfile]}
      onSave={async(uid,data)=>{
        setCollabProfiles(p=>({...p,[uid]:data}));
        try{localStorage.setItem("pixels-selfprofile-"+uid,JSON.stringify(data));}catch(e){}
        // Salvar no Supabase para persistência permanente
        try{
          const sb=window._sb;
          const{data:profileRow}=await sb.from("profiles").select("id").eq("team_id",uid).single();
          if(profileRow){
            await sb.from("profiles").update({profile_data:data}).eq("id",profileRow.id);
          }
        }catch(e){console.warn("Erro ao salvar perfil no Supabase:",e);}
      }}
      onClose={()=>setEditProfile(null)}
    />)}

    {/* ── NOVO COLABORADOR MODAL ── */}
    {resetPwd.open&&(
      <div onMouseDown={e=>{if(e.target===e.currentTarget)setResetPwd({open:false,teamId:null,nome:"",value:"",busy:false});}}
        style={{position:"fixed",inset:0,background:"rgba(15,23,42,.55)",backdropFilter:"blur(3px)",zIndex:99999,display:"flex",alignItems:"center",justifyContent:"center",padding:20}}>
        <div style={{background:C.card,borderRadius:16,border:"1px solid "+C.b1,width:"100%",maxWidth:400,boxShadow:"0 24px 60px rgba(0,0,0,.28)",overflow:"hidden"}}>
          <div style={{padding:"18px 22px 14px",borderBottom:"1px solid "+C.b1}}>
            <div style={{color:C.tx,fontWeight:800,fontSize:16,letterSpacing:-.2}}>Redefinir senha</div>
            <div style={{color:C.td,fontSize:12,marginTop:3}}>{resetPwd.nome} vai passar a logar com a senha nova.</div>
          </div>
          <div style={{padding:"18px 22px"}}>
            <div style={{color:C.td,fontSize:10.5,fontWeight:700,textTransform:"uppercase",letterSpacing:.7,marginBottom:6}}>Nova senha</div>
            <input autoFocus type="text" value={resetPwd.value} onChange={e=>setResetPwd(p=>({...p,value:e.target.value}))} onKeyDown={e=>{if(e.key==="Enter")_redefinirSenhaSubmit();}} placeholder="mín. 6 caracteres"
              style={{background:C.s1,border:"1px solid "+C.b1,borderRadius:9,padding:"10px 13px",color:C.tx,fontSize:14,fontWeight:600,outline:"none",width:"100%",boxSizing:"border-box",fontFamily:"inherit"}}/>
            <div style={{display:"flex",gap:8,marginTop:16}}>
              <button onClick={()=>setResetPwd({open:false,teamId:null,nome:"",value:"",busy:false})} style={{flex:1,background:C.s1,border:"1px solid "+C.b1,borderRadius:9,padding:"10px",color:C.ts,fontWeight:600,fontSize:13,cursor:"pointer"}}>Cancelar</button>
              <button onClick={_redefinirSenhaSubmit} disabled={resetPwd.busy} style={{flex:1,background:C.a,border:"none",borderRadius:9,padding:"10px",color:"#fff",fontWeight:700,fontSize:13,cursor:resetPwd.busy?"default":"pointer",opacity:resetPwd.busy?.6:1}}>{resetPwd.busy?"Salvando...":"Redefinir"}</button>
            </div>
          </div>
        </div>
      </div>
    )}
    {novoColabOpen&&(()=>{
      const inp={background:C.s1,border:"1px solid "+C.b1,borderRadius:8,padding:"9px 12px",color:C.tx,fontSize:13,outline:"none",width:"100%",boxSizing:"border-box",fontFamily:"inherit"};
      const lbl={color:C.td,fontSize:10.5,fontWeight:700,textTransform:"uppercase",letterSpacing:.7,marginBottom:5};
      const onPickFoto=(file)=>{
        if(!file)return;
        const r=new FileReader();
        r.onload=()=>{
          const b64=String(r.result||"");
          setNovoColab(p=>({...p,photo_base64:b64,photo_mime:file.type||"image/png"}));
        };
        r.readAsDataURL(file);
      };
      const submit=async()=>{
        if(!novoColab.name.trim()||!novoColab.email.trim()||!novoColab.password.trim()||!novoColab.team_id.trim()){
          if(typeof pixelsToast!=="undefined")pixelsToast.warning("Preencha nome, email, senha e ID curto (team_id).");
          return;
        }
        setNovoColabBusy(true);
        try{
          const sb=window._sb;
          const{data:sess}=await sb.auth.getSession();
          const tok=sess?.session?.access_token;
          const url=(typeof import.meta!=="undefined"?import.meta.env.VITE_SUPABASE_URL:"")||"https://jffvoojcskwumnphsedq.supabase.co";
          const payload={
            email:novoColab.email.trim().toLowerCase(),
            password:novoColab.password,
            name:novoColab.name.trim(),
            role:novoColab.role,
            dash:novoColab.dash,
            color:novoColab.color,
            av:novoColab.av||novoColab.name.trim()[0]?.toUpperCase()||"?",
            level:Number(novoColab.level)||3,
            team_id:novoColab.team_id.trim().toLowerCase(),
            photo_base64:novoColab.photo_base64,
            photo_mime:novoColab.photo_mime,
          };
          const res=await fetch(url+"/functions/v1/create-collaborator",{
            method:"POST",
            headers:{"Authorization":"Bearer "+tok,"Content-Type":"application/json"},
            body:JSON.stringify(payload),
          });
          const data=await res.json();
          if(!res.ok){
            if(typeof pixelsToast!=="undefined")pixelsToast.error(data.error||"Falha ao criar colaborador.");
            setNovoColabBusy(false);
            return;
          }
          if(typeof pixelsToast!=="undefined")pixelsToast.success("Colaborador criado! Avise pra logar com email/senha.");
          // Registra a senha no cofre de login (só sócios veem no card do Time)
          try{
            await sb.from("team_login_secrets").upsert({team_id:payload.team_id,senha:payload.password,email:payload.email,updated_by:CURRENT_USER.id,updated_at:new Date().toISOString()},{onConflict:"team_id"});
            setLoginSecrets(m=>({...m,[payload.team_id]:{senha:payload.password,email:payload.email,updated_at:new Date().toISOString()}}));
          }catch(_e){console.warn("[acessos] captura senha login:",_e&&_e.message?_e.message:_e);}
          setNovoColabOpen(false);
          setNovoColabBusy(false);
          setNovoColab({name:"",email:"",password:"",team_id:"",role:"Designer",dash:"designer",color:"#ec4899",av:"",level:3,photo_base64:"",photo_mime:""});
          // Mescla IMEDIATAMENTE no TEAM (sem precisar refresh)
          try{
            if(typeof TEAM!=="undefined" && !TEAM.find(t=>t.id===payload.team_id)){
              TEAM.push({
                id:payload.team_id, name:payload.name, role:payload.role,
                av:payload.av, color:payload.color, level:payload.level,
                status:"online", dash:payload.dash,
                canDelete:false, canPixelsIA:false, pagamentoPorDemanda:(payload.dash==="designer"||payload.dash==="editor"),
                supervisor:["gustavo","vinicius","hellen"],
                _fromSupabase:true,
              });
            }
            if(typeof ACCESS_STORE!=="undefined" && !ACCESS_STORE[payload.team_id]){
              const dashDefaults={designer:ACCESS_STORE.andre,editor:ACCESS_STORE.guilherme,coordinator:ACCESS_STORE.ellen,social:(typeof SOCIAL_MEDIA_PERMS!=="undefined"?SOCIAL_MEDIA_PERMS:ACCESS_STORE.ellen),gestor:ACCESS_STORE.erick,partner:ACCESS_STORE.vinicius};
              ACCESS_STORE[payload.team_id]={...(dashDefaults[payload.dash]||DEFAULT_PERMS)};
            }
            if(data.photo_url){
              const pd={photo:data.photo_url,name:payload.name,role:payload.role};
              localStorage.setItem("pixels-selfprofile-"+payload.team_id,JSON.stringify(pd));
              setCollabProfiles(p=>({...p,[payload.team_id]:pd}));
            }
            window.dispatchEvent(new CustomEvent("pixels:team-updated"));
          }catch(e){console.warn(e);}
          // Recarrega perfis pra pegar profile_data persistido
          try{
            const{data:rows}=await sb.from("profiles").select("id,team_id,profile_data").not("profile_data","is",null);
            const updates={};
            (rows||[]).forEach(row=>{if(row.team_id&&row.profile_data){updates[row.team_id]=row.profile_data;try{localStorage.setItem("pixels-selfprofile-"+row.team_id,JSON.stringify(row.profile_data));}catch(e){}}});
            if(Object.keys(updates).length>0)setCollabProfiles(p=>({...p,...updates}));
          }catch(e){}
        }catch(e){
          if(typeof pixelsToast!=="undefined")pixelsToast.error("Erro de conexao.");
          setNovoColabBusy(false);
        }
      };
      const DASH_OPTS=[
        {id:"designer",label:"Design"},
        {id:"editor",label:"Edição de vídeo"},
        {id:"coordinator",label:"Estratégia"},
        {id:"social",label:"Social media"},
        {id:"gestor",label:"Gestão de mídia"},
        {id:"partner",label:"Gestão"},
      ];
      const CORS=["#ec4899","#e040fb","#9F43F6","#7c3aed","#6366f1","#0ea5e9","#16a34a","#f59e0b","#ef4444","#475569"];
      return(<div style={{position:"fixed",inset:0,background:"rgba(15,15,25,0.6)",zIndex:400,display:"flex",alignItems:"center",justifyContent:"center",padding:16}} onClick={()=>!novoColabBusy&&setNovoColabOpen(false)}>
        <div onClick={e=>e.stopPropagation()} style={{background:C.card,borderRadius:18,width:"100%",maxWidth:560,boxShadow:"0 24px 60px rgba(0,0,0,0.35)",overflow:"hidden",maxHeight:"92vh",display:"flex",flexDirection:"column"}}>
          {/* Header premium */}
          <div style={{background:"linear-gradient(135deg,"+C.a+" 0%,#7c3aed 50%,#1e1b4b 100%)",padding:"22px 26px",display:"flex",alignItems:"center",justifyContent:"space-between",position:"relative",overflow:"hidden"}}>
            <div style={{position:"absolute",top:-40,right:-40,width:160,height:160,borderRadius:"50%",background:"radial-gradient(circle,rgba(255,255,255,.15) 0%,transparent 65%)"}}/>
            <div style={{position:"relative",zIndex:1,display:"flex",alignItems:"center",gap:12}}>
              <div style={{width:42,height:42,borderRadius:11,background:"rgba(255,255,255,.18)",border:"1px solid rgba(255,255,255,.28)",display:"flex",alignItems:"center",justifyContent:"center",backdropFilter:"blur(6px)"}}>
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="M16 21v-2a4 4 0 00-4-4H6a4 4 0 00-4 4v2"/><circle cx="9" cy="7" r="4"/><line x1="19" y1="8" x2="19" y2="14"/><line x1="22" y1="11" x2="16" y2="11"/></svg>
              </div>
              <div>
                <div style={{color:"#fff",fontWeight:800,fontSize:18,letterSpacing:-.3}}>Novo colaborador</div>
                <div style={{color:"rgba(255,255,255,.78)",fontSize:12,marginTop:2,fontWeight:500}}>Cria login + perfil + foto numa só ação</div>
              </div>
            </div>
            <button onClick={()=>!novoColabBusy&&setNovoColabOpen(false)}
              style={{position:"relative",zIndex:1,background:"rgba(255,255,255,.14)",border:"1px solid rgba(255,255,255,.22)",borderRadius:10,width:34,height:34,color:"#fff",cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",backdropFilter:"blur(6px)"}}>
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
            </button>
          </div>

          <div style={{padding:"18px 22px",display:"flex",flexDirection:"column",gap:14,overflowY:"auto"}}>
            {/* Foto */}
            <div style={{display:"flex",alignItems:"center",gap:14}}>
              <div style={{width:72,height:72,borderRadius:"50%",background:novoColab.photo_base64?"url("+novoColab.photo_base64+") center/cover":novoColab.color,display:"flex",alignItems:"center",justifyContent:"center",color:"#fff",fontWeight:900,fontSize:26,border:"3px solid "+C.b1,flexShrink:0}}>
                {!novoColab.photo_base64&&((novoColab.av||novoColab.name[0]||"").toUpperCase()||(<svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" style={{opacity:.85}}><path d="M20 21v-2a4 4 0 00-4-4H8a4 4 0 00-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>))}
              </div>
              <div style={{flex:1}}>
                <div style={lbl}>Foto de perfil (opcional)</div>
                <label style={{display:"inline-block",background:C.s1,border:"1px solid "+C.b1,borderRadius:8,padding:"8px 14px",fontSize:12,fontWeight:600,color:C.ts,cursor:"pointer"}}>
                  {novoColab.photo_base64?"Trocar foto":"Escolher arquivo"}
                  <input type="file" accept="image/*" onChange={e=>onPickFoto(e.target.files?.[0])} style={{display:"none"}}/>
                </label>
                {novoColab.photo_base64&&<button onClick={()=>setNovoColab(p=>({...p,photo_base64:"",photo_mime:""}))} style={{marginLeft:8,background:"transparent",border:"1px solid "+C.b1,borderRadius:8,padding:"7px 12px",fontSize:11,color:C.td,cursor:"pointer"}}>Remover</button>}
              </div>
            </div>

            {/* Nome */}
            <div>
              <div style={lbl}>Nome completo</div>
              <input value={novoColab.name} onChange={e=>setNovoColab(p=>({...p,name:e.target.value,av:p.av||e.target.value[0]?.toUpperCase()||""}))} placeholder="Maria Clara Luz do Nascimento" style={inp}/>
            </div>

            <div style={{display:"grid",gridTemplateColumns:_pxMob()?"1fr":"1fr 1fr",gap:10}}>
              {/* Email */}
              <div>
                <div style={lbl}>E-mail (login)</div>
                <input value={novoColab.email} onChange={e=>setNovoColab(p=>({...p,email:e.target.value}))} placeholder="maria@pixelsmarketing.com.br" style={inp}/>
              </div>
              {/* Senha */}
              <div>
                <div style={lbl}>Senha inicial</div>
                <input value={novoColab.password} onChange={e=>setNovoColab(p=>({...p,password:e.target.value}))} type="text" placeholder="ex: Pixels@2026" style={inp}/>
              </div>
            </div>

            <div style={{display:"grid",gridTemplateColumns:_pxMob()?"1fr":"1fr 1fr",gap:10}}>
              {/* ID curto */}
              <div>
                <div style={lbl}>ID curto (team_id)</div>
                <input value={novoColab.team_id} onChange={e=>setNovoColab(p=>({...p,team_id:e.target.value.toLowerCase().replace(/[^a-z0-9_]/g,"")}))} placeholder="maria" style={inp}/>
                <div style={{color:C.td,fontSize:10,marginTop:3}}>Usado em ACCESS_STORE e tags. Só letras minúsculas.</div>
              </div>
              {/* Função */}
              <div>
                <div style={lbl}>Função (role)</div>
                <input value={novoColab.role} onChange={e=>setNovoColab(p=>({...p,role:e.target.value}))} placeholder="Designer" style={inp}/>
              </div>
            </div>

            <div style={{display:"grid",gridTemplateColumns:_pxMob()?"1fr":"1fr 1fr",gap:10}}>
              {/* Dash */}
              <div>
                <div style={lbl}>Tipo de dashboard</div>
                <select value={novoColab.dash} onChange={e=>setNovoColab(p=>({...p,dash:e.target.value}))} style={{...inp,cursor:"pointer"}}>
                  {DASH_OPTS.map(o=><option key={o.id} value={o.id}>{o.label}</option>)}
                </select>
              </div>
              {/* Nível */}
              <div>
                <div style={lbl}>Nível</div>
                <select value={novoColab.level} onChange={e=>setNovoColab(p=>({...p,level:Number(e.target.value)}))} style={{...inp,cursor:"pointer"}}>
                  <option value={1}>Gestão (1)</option>
                  <option value={2}>Coordenação (2)</option>
                  <option value={3}>Colaborador (3)</option>
                </select>
              </div>
            </div>

            {/* Cor */}
            <div>
              <div style={lbl}>Cor do avatar</div>
              <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
                {CORS.map(c=>(
                  <button key={c} onClick={()=>setNovoColab(p=>({...p,color:c}))}
                    style={{width:30,height:30,borderRadius:"50%",background:c,border:novoColab.color===c?"3px solid #fff":"3px solid transparent",boxShadow:novoColab.color===c?"0 0 0 2px "+c:"0 1px 3px rgba(0,0,0,0.15)",cursor:"pointer",padding:0}}/>
                ))}
                <input type="color" value={novoColab.color} onChange={e=>setNovoColab(p=>({...p,color:e.target.value}))} style={{width:36,height:36,border:"none",background:"transparent",cursor:"pointer",borderRadius:8}}/>
              </div>
            </div>

            {/* Info — sem necessidade de editar arquivos */}
            <div style={{background:"#f0fdf4",border:"1px solid #bbf7d0",borderRadius:10,padding:"10px 12px",fontSize:11.5,color:"#15803d",lineHeight:1.55,display:"flex",gap:8,alignItems:"flex-start"}}>
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#16a34a" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" style={{flexShrink:0,marginTop:1}}><polyline points="20 6 9 17 4 12"/></svg>
              <span>O colaborador aparece automaticamente pra todo mundo. Sem precisar editar arquivos ou rodar deploy.</span>
            </div>

            {/* Botões */}
            <div style={{display:"flex",justifyContent:"flex-end",gap:8,paddingTop:8,borderTop:"1px solid "+C.b1}}>
              <button onClick={()=>!novoColabBusy&&setNovoColabOpen(false)} disabled={novoColabBusy}
                style={{background:"transparent",border:"1px solid "+C.b1,borderRadius:10,padding:"9px 18px",color:C.ts,fontSize:12.5,fontWeight:600,cursor:novoColabBusy?"not-allowed":"pointer",fontFamily:"inherit"}}>Cancelar</button>
              <button onClick={submit} disabled={novoColabBusy}
                style={{background:novoColabBusy?C.b1:C.a,border:"none",borderRadius:10,padding:"9px 22px",color:"#fff",fontSize:12.5,fontWeight:700,cursor:novoColabBusy?"not-allowed":"pointer",fontFamily:"inherit",boxShadow:novoColabBusy?"none":"0 4px 14px "+C.a+"55"}}>
                {novoColabBusy?"Criando…":"Criar colaborador"}
              </button>
            </div>
          </div>
        </div>
      </div>);
    })()}

    {/* CLIENT ACCESS EDIT MODAL antigo removido — agora usamos Supabase Auth real via Edge Function */}

    {/* ── NOVO ACESSO CLIENTE MODAL ── */}
    {novoClienteOpen&&(()=>{
      const inp={background:C.s1,border:"1px solid "+C.b1,borderRadius:8,padding:"9px 12px",color:C.tx,fontSize:13,outline:"none",width:"100%",boxSizing:"border-box",fontFamily:"inherit"};
      const lbl={color:C.td,fontSize:10.5,fontWeight:700,textTransform:"uppercase",letterSpacing:.7,marginBottom:5};
      const _clientesPortal=CLIENTS.filter(c=>c.status!=="interno"&&c.id!=="pixels"&&String(c.name||"").trim());
      const _clSel=_clientesPortal.find(c=>c.id===novoCliente.client_id)||_clientesPortal[0];
      const onPickFoto=(file)=>{
        if(!file)return;
        const r=new FileReader();
        r.onload=()=>{
          const b64=String(r.result||"");
          setNovoCliente(p=>({...p,photo_base64:b64,photo_mime:file.type||"image/png"}));
        };
        r.readAsDataURL(file);
      };
      // Regex simples pra validar formato de email — evita erro cru do Supabase
      const _isValidEmail=(e)=>/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(String(e||"").trim());
      const _emailInvalid = novoCliente.email.trim().length>0 && !_isValidEmail(novoCliente.email);
      const submit=async()=>{
        if(!novoCliente.client_id||!novoCliente.email.trim()||!novoCliente.password.trim()){
          if(typeof pixelsToast!=="undefined")pixelsToast.warning("Preencha cliente, email e senha.");
          return;
        }
        if(!_isValidEmail(novoCliente.email)){
          if(typeof pixelsToast!=="undefined")pixelsToast.error("Email invalido. Use o formato nome@dominio.com (ex: marketing@cliente.com).");
          return;
        }
        if(novoCliente.password.length<6){
          if(typeof pixelsToast!=="undefined")pixelsToast.warning("Senha precisa de no mínimo 6 caracteres.");
          return;
        }
        if(novoCliente.client_id==="bioter" && !novoCliente.client_unit){
          if(typeof pixelsToast!=="undefined")pixelsToast.warning("Escolha a unidade Bioter (ou Grupo Bioter pra ver tudo).");
          return;
        }
        setNovoClienteBusy(true);
        try{
          const sb=window._sb;
          // Refresh do token antes de chamar — evita "Token inválido" se sessão tá velha
          await sb.auth.refreshSession().catch(()=>{});
          const{data:sess}=await sb.auth.getSession();
          const tok=sess?.session?.access_token;
          if(!tok){
            if(typeof pixelsToast!=="undefined")pixelsToast.error("Sua sessão expirou. Faça logout e login de novo.");
            setNovoClienteBusy(false);
            return;
          }
          const url=(typeof import.meta!=="undefined"?import.meta.env.VITE_SUPABASE_URL:"")||"https://jffvoojcskwumnphsedq.supabase.co";

          // === Upload da foto CLIENT-SIDE (evita timeout na Edge Function) ===
          let _photoUrl = "";
          if(novoCliente.photo_base64){
            try{
              const _ext = (novoCliente.photo_mime||"image/png").split("/")[1]||"png";
              const _raw = novoCliente.photo_base64.replace(/^data:[^,]+,/,"");
              const _bin = atob(_raw);
              const _bytes = new Uint8Array(_bin.length);
              for(let i=0;i<_bin.length;i++)_bytes[i]=_bin.charCodeAt(i);
              const _key = "clients/"+novoCliente.client_id+"/avatar."+_ext;
              const{error:_upErr} = await sb.storage.from("profiles").upload(_key,_bytes,{contentType:novoCliente.photo_mime,upsert:true});
              if(_upErr){
                console.warn("[acessos] photo upload:",_upErr);
              }else{
                _photoUrl = url+"/storage/v1/object/public/profiles/"+_key;
              }
            }catch(e){console.warn("[acessos] photo prep:",e);}
          }

          const payload={
            email:novoCliente.email.trim().toLowerCase(),
            password:novoCliente.password,
            client_id:novoCliente.client_id,
            client_unit:novoCliente.client_unit||"",
            name:(novoCliente.name||"").trim()||(_clSel?_clSel.name:novoCliente.client_id),
            papel:novoCliente.papel==="comercial"?"comercial":"admin", // nível do portal (11/09/2026)
            photo_url:_photoUrl,
          };
          // Timeout de 45s — evita ficar "Criando..." infinito
          const _ctrl = new AbortController();
          const _to = setTimeout(()=>_ctrl.abort(), 45000);
          let res, data;
          try{
            res=await fetch(url+"/functions/v1/create-client-user",{
              method:"POST",
              headers:{"Authorization":"Bearer "+tok,"Content-Type":"application/json"},
              body:JSON.stringify(payload),
              signal:_ctrl.signal,
            });
            data=await res.json().catch(()=>({error:"Resposta inválida do servidor"}));
          }catch(e){
            clearTimeout(_to);
            if(typeof pixelsToast!=="undefined"){
              if(e.name==="AbortError")pixelsToast.error("Tempo esgotado (45s). A foto pode estar muito grande — tenta sem foto primeiro.");
              else pixelsToast.error("Erro de rede: "+String(e?.message||e));
            }
            setNovoClienteBusy(false);
            return;
          }
          clearTimeout(_to);
          if(!res.ok){
            if(typeof pixelsToast!=="undefined")pixelsToast.error(data.error||"Falha ao criar acesso cliente.");
            setNovoClienteBusy(false);
            return;
          }
          if(typeof pixelsToast!=="undefined")pixelsToast.success("Acesso criado! "+payload.email+" pode logar agora.",5000);
          // ═════ Auto-registra no Cofre de Senhas pra sócios consultarem depois ═════
          try{
            const _clName = _clSel ? _clSel.name : novoCliente.client_id;
            const _unitTxt = novoCliente.client_unit ? " — "+novoCliente.client_unit : "";
            const _portalUrl = (typeof window!=="undefined" && window.location ? window.location.origin+"/portal" : "");
            const _pwdPayload = {
              label: _clName + _unitTxt + " (Portal cliente)",
              category: "cliente",
              client_id: novoCliente.client_id || null,
              username: payload.email,
              password: novoCliente.password,
              url: _portalUrl,
              notes: novoCliente.name ? ("Contato: "+novoCliente.name) : "",
              author_id: (typeof CURRENT_USER!=="undefined" ? CURRENT_USER.id : ""),
              author_name: (typeof CURRENT_USER!=="undefined" ? CURRENT_USER.name : ""),
              updated_at: new Date().toISOString(),
            };
            const _rvPwd = await sb.from("team_passwords").insert(_pwdPayload);
            if(_rvPwd && _rvPwd.error) console.warn("[acessos] insert team_passwords:", _rvPwd.error.message||_rvPwd.error);
          }catch(_e){ console.warn("[acessos] vault sync:", _e && _e.message ? _e.message : _e); }
          // Liga acesso no painel também (mesmo se foi configurado antes)
          const cur=clientAccess[novoCliente.client_id]||defaultClientAccess(_clSel||{id:novoCliente.client_id,name:""});
          saveClientAccess(novoCliente.client_id,{...cur,enabled:true,login:payload.email});
          reloadClientAuthUsers();
          reloadClientPasswords();
          setNovoClienteOpen(false);
          setNovoClienteBusy(false);
        }catch(e){
          if(typeof pixelsToast!=="undefined")pixelsToast.error("Erro: "+(e.message||e));
          setNovoClienteBusy(false);
        }
      };
      return <div onClick={()=>!novoClienteBusy&&setNovoClienteOpen(false)}
        style={{position:"fixed",inset:0,background:"rgba(15,23,42,.55)",backdropFilter:"blur(6px)",zIndex:9999,display:"flex",alignItems:"flex-start",justifyContent:"center",paddingTop:48,fontFamily:"inherit"}}>
        <div onClick={e=>e.stopPropagation()}
          style={{background:C.card,borderRadius:16,width:"min(540px,94%)",maxHeight:"calc(100vh - 80px)",overflow:"auto",boxShadow:"0 24px 64px rgba(0,0,0,.3)",border:"1px solid "+C.b1}}>
          {/* Header */}
          <div style={{padding:"20px 24px 16px",borderBottom:"1px solid "+C.b1,background:"linear-gradient(135deg,#16a34a14,transparent 60%)",position:"relative"}}>
            <div style={{position:"absolute",left:0,top:0,bottom:0,width:4,background:"#16a34a"}}/>
            <div style={{display:"flex",alignItems:"center",gap:12,marginLeft:6}}>
              <div style={{width:40,height:40,borderRadius:10,background:"linear-gradient(135deg,#16a34a,#15803d)",display:"flex",alignItems:"center",justifyContent:"center",color:"#fff",boxShadow:"0 4px 12px rgba(22,163,74,.35)"}}>
                <svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="M16 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2"/><circle cx="8.5" cy="7" r="4"/><line x1="20" y1="8" x2="20" y2="14"/><line x1="23" y1="11" x2="17" y2="11"/></svg>
              </div>
              <div style={{flex:1,minWidth:0}}>
                <div style={{color:C.tx,fontWeight:800,fontSize:17,letterSpacing:-.3}}>Novo acesso cliente</div>
                <div style={{color:C.td,fontSize:11.5,marginTop:3}}>Cria login Supabase Auth pro cliente acessar o portal</div>
              </div>
            </div>
          </div>

          <div style={{padding:"18px 24px 22px",display:"flex",flexDirection:"column",gap:12}}>
            {/* Cliente vinculado */}
            <div>
              <div style={lbl}>Cliente vinculado *</div>
              <select value={novoCliente.client_id} onChange={e=>setNovoCliente(p=>({...p,client_id:e.target.value,client_unit:""}))} style={{...inp,cursor:"pointer"}}>
                {_clientesPortal.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}
              </select>
            </div>

            {/* Unidades Bioter — multi-select (só aparece quando cliente=bioter) */}
            {novoCliente.client_id==="bioter" && (()=>{
              const _selUnits=(novoCliente.client_unit==="grupo"?["grupo"]:String(novoCliente.client_unit||"").split(",").map(s=>s.trim()).filter(Boolean));
              const _isGrupo=_selUnits.indexOf("grupo")!==-1;
              const _toggleGrupo=()=>{
                setNovoCliente(p=>({...p,client_unit:_isGrupo?"":"grupo"}));
              };
              const _toggleUnit=(uid)=>{
                if(_isGrupo)return; // grupo trava as outras
                const cur=_selUnits.filter(x=>x!=="grupo");
                const next=cur.indexOf(uid)!==-1?cur.filter(x=>x!==uid):[...cur,uid];
                setNovoCliente(p=>({...p,client_unit:next.join(",")}));
              };
              const _allUnits=(typeof BIOTER_UNITS!=="undefined"?BIOTER_UNITS:[]);
              const _rowStyle=(active,disabled)=>({
                display:"flex",alignItems:"center",gap:9,padding:"8px 11px",
                background:active?"#dcfce7":"#fff",
                border:"1px solid "+(active?"#86efac":C.b1),
                borderRadius:8,cursor:disabled?"not-allowed":"pointer",
                opacity:disabled?.5:1,transition:"all .12s",fontSize:12.5,fontWeight:600,color:C.tx,
              });
              return <div>
                <div style={lbl}>Unidades Bioter *</div>
                <div style={{display:"flex",flexDirection:"column",gap:6}}>
                  {/* Grupo Bioter — atalho pra ver tudo */}
                  <label style={_rowStyle(_isGrupo,false)}>
                    <input type="checkbox" checked={_isGrupo} onChange={_toggleGrupo}/>
                    <span style={{fontWeight:700}}>Grupo Bioter</span>
                    <span style={{color:C.td,fontWeight:500,fontSize:11.5}}>— vê todas as unidades</span>
                  </label>
                  {/* Divisor */}
                  <div style={{height:1,background:C.b1,margin:"3px 0"}}/>
                  {/* Cada unidade individualmente — labels "Bioter Chapecó", "Bioter Toledo" etc */}
                  {_allUnits.map(u=>{
                    const active=!_isGrupo&&_selUnits.indexOf(u.id)!==-1;
                    const _lbl = u.id==="paraguay" ? "Bioter Paraguay" : "Bioter "+(u.pickerLabel||u.label.split("/")[0]);
                    return <label key={u.id} style={_rowStyle(active,_isGrupo)}>
                      <input type="checkbox" checked={active} disabled={_isGrupo} onChange={()=>_toggleUnit(u.id)}/>
                      <span>{_lbl}</span>
                    </label>;
                  })}
                </div>
                <div style={{color:C.td,fontSize:10.5,marginTop:6,fontStyle:"italic"}}>
                  Cliente vê apenas dados das unidades marcadas. Marque várias se quiser dar acesso multi-unidade (ex: regional).
                </div>
              </div>;
            })()}

            {/* Email + Senha em grid */}
            <div style={{display:"grid",gridTemplateColumns:_pxMob()?"1fr":"1fr 1fr",gap:10}}>
              <div>
                <div style={lbl}>Email do cliente *</div>
                <input type="email" autoComplete="off" value={novoCliente.email} onChange={e=>setNovoCliente(p=>({...p,email:e.target.value}))}
                  placeholder="marketing@cliente.com"
                  style={{...inp,border:"1px solid "+(_emailInvalid?"#ef4444":C.b1),background:_emailInvalid?"#fef2f2":C.s1}}/>
                {_emailInvalid && <div style={{color:"#dc2626",fontSize:10.5,marginTop:4,fontWeight:600,display:"flex",alignItems:"center",gap:5}}>
                  <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>
                  Formato invalido - use nome@dominio.com
                </div>}
              </div>
              <div>
                <div style={lbl}>Senha *</div>
                <input type="text" value={novoCliente.password} onChange={e=>setNovoCliente(p=>({...p,password:e.target.value}))}
                  placeholder="mín. 6 caracteres" style={inp}/>
              </div>
            </div>

            {/* Nome do contato (opcional) */}
            <div>
              <div style={lbl}>Nome do contato <span style={{color:C.td,fontWeight:500,textTransform:"none",letterSpacing:0}}>(opcional)</span></div>
              <input type="text" value={novoCliente.name} onChange={e=>setNovoCliente(p=>({...p,name:e.target.value}))}
                placeholder={_clSel?_clSel.name:"Ex: Marketing Construschorr"} style={inp}/>
              <div style={{color:C.td,fontSize:10.5,marginTop:4,fontStyle:"italic"}}>Se vazio, usa o nome do cliente vinculado.</div>
            </div>

            {/* Foto (opcional) */}
            <div>
              <div style={lbl}>Foto do contato <span style={{color:C.td,fontWeight:500,textTransform:"none",letterSpacing:0}}>(opcional)</span></div>
              <div style={{display:"flex",alignItems:"center",gap:12}}>
                <label style={{cursor:"pointer",display:"inline-flex",alignItems:"center",gap:7,background:C.s1,border:"1px solid "+C.b1,borderRadius:8,padding:"8px 12px",color:C.ts,fontSize:12,fontWeight:600,transition:"all .12s"}}>
                  <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.3" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg>
                  Escolher arquivo
                  <input type="file" accept="image/*" onChange={e=>onPickFoto(e.target.files?.[0])} style={{display:"none"}}/>
                </label>
                {novoCliente.photo_base64 && <img src={novoCliente.photo_base64} alt="preview" style={{width:40,height:40,borderRadius:8,objectFit:"cover",border:"1px solid "+C.b1}}/>}
              </div>
            </div>

            {/* Nível de acesso no portal (11/09/2026) */}
            <div>
              <div style={lbl}>Nível de acesso *</div>
              <div style={{display:"grid",gridTemplateColumns:_pxMob()?"1fr":"1fr 1fr",gap:8}}>
                {PORTAL_NIVEIS.map(n=>{
                  const on=(novoCliente.papel||"admin")===n.id;
                  return <button key={n.id} type="button" onClick={()=>setNovoCliente(p=>({...p,papel:n.id}))}
                    style={{textAlign:"left",background:on?n.cor+"0f":"#fff",border:"1.5px solid "+(on?n.cor:C.b1),borderRadius:10,padding:"10px 12px",cursor:"pointer",fontFamily:"inherit",display:"flex",flexDirection:"column",gap:3,transition:"all .12s"}}>
                    <span style={{display:"flex",alignItems:"center",gap:7,color:on?n.cor:C.tx,fontWeight:800,fontSize:13}}>
                      <span style={{width:14,height:14,borderRadius:"50%",border:"2px solid "+(on?n.cor:"#cbd5e1"),display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0,boxSizing:"border-box"}}>{on&&<span style={{width:6,height:6,borderRadius:"50%",background:n.cor}}/>}</span>
                      {n.label}
                    </span>
                    <span style={{color:C.td,fontSize:11.5,fontWeight:500,lineHeight:1.4,paddingLeft:21}}>{n.desc}</span>
                  </button>;
                })}
              </div>
            </div>

            {/* Resumo informativo */}
            <div style={{background:"#f0fdf4",border:"1px solid #bbf7d0",borderRadius:9,padding:"10px 12px",display:"flex",gap:9,alignItems:"flex-start"}}>
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#16a34a" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" style={{marginTop:2,flexShrink:0}}><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg>
              <div style={{color:"#166534",fontSize:11.5,lineHeight:1.5,fontWeight:500}}>
                O cliente vai logar em <span style={{fontWeight:700}}>pixels-agency-os.vercel.app</span> com email + senha. O sistema identifica que é cliente automaticamente e mostra só o portal travado em <span style={{fontWeight:700}}>{_clSel?_clSel.name:"—"}</span>.
              </div>
            </div>

            {/* Botões */}
            <div style={{display:"flex",justifyContent:"flex-end",gap:8,marginTop:6}}>
              <button onClick={()=>!novoClienteBusy&&setNovoClienteOpen(false)}
                style={{background:C.s1,border:"1px solid "+C.b1,borderRadius:9,padding:"9px 18px",color:C.ts,fontSize:12,fontWeight:700,cursor:novoClienteBusy?"not-allowed":"pointer",opacity:novoClienteBusy?.6:1,fontFamily:"inherit"}}>
                Cancelar
              </button>
              <button onClick={submit} disabled={novoClienteBusy}
                style={{background:"linear-gradient(135deg,#16a34a,#15803d)",border:"none",borderRadius:9,padding:"9px 22px",color:"#fff",fontSize:12,fontWeight:800,cursor:novoClienteBusy?"not-allowed":"pointer",opacity:novoClienteBusy?.7:1,boxShadow:"0 4px 14px rgba(22,163,74,.45)",fontFamily:"inherit",display:"inline-flex",alignItems:"center",gap:6}}>
                {novoClienteBusy?"Criando...":"Criar acesso"}
              </button>
            </div>
          </div>
        </div>
      </div>;
    })()}

    <div style={{display:"flex",flexDirection:"column",gap:20}}>

      {/* ── MAIN TAB SWITCHER ── */}
      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",flexWrap:"wrap",gap:12}}>
        <div style={{display:"flex",gap:3,background:C.s1,borderRadius:12,padding:3}}>
          {MAIN_TABS.filter(function(t){return t[0]!=="senhas"||_podeSenhas;}).map(([id,lbl])=>(
            <button key={id} onClick={()=>setMainTab(id)}
              style={{background:mainTab===id?"linear-gradient(135deg,"+C.a+","+C.aD+")":"transparent",color:mainTab===id?"#fff":C.ts,border:"none",borderRadius:9,padding:"9px 20px",fontWeight:mainTab===id?700:400,fontSize:13,cursor:"pointer",transition:"all .15s"}}>
              {lbl}
            </button>
          ))}
        </div>
        {mainTab==="equipe"&&<div style={{display:"flex",alignItems:"center",gap:10}}>
          <div style={{color:C.ts,fontSize:12}}>{TEAM.length} membros · {TEAM.filter(u=>u.status==="online").length} online</div>
          {isMePartner&&<button onClick={()=>{setNovoColab({name:"",email:"",password:"",team_id:"",role:"Designer",dash:"designer",color:"#ec4899",av:"",level:3,photo_base64:"",photo_mime:""});setNovoColabOpen(true);}}
            style={{background:"linear-gradient(135deg,"+C.a+","+C.aD+")",border:"none",borderRadius:10,padding:"8px 16px",color:"#fff",fontSize:12,fontWeight:700,cursor:"pointer",display:"inline-flex",alignItems:"center",gap:6,boxShadow:"0 4px 14px "+C.a+"55",fontFamily:"inherit"}}>
            <span style={{fontSize:14,lineHeight:1}}>+</span>Novo colaborador
          </button>}
        </div>}
      </div>

      {/* ══ EQUIPE ══ */}
      {mainTab==="equipe"&&<>
        <div style={{display:"flex",gap:10,alignItems:"center",flexWrap:"wrap",fontFamily:"'Inter',system-ui,sans-serif"}}>
          {/* Busca com SVG moderno */}
          <div style={{position:"relative",display:"inline-flex",alignItems:"center"}}>
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke={C.td} strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"
              style={{position:"absolute",left:11,top:"50%",transform:"translateY(-50%)",pointerEvents:"none"}}>
              <circle cx="11" cy="11" r="7"/><line x1="21" y1="21" x2="16.65" y2="16.65"/>
            </svg>
            <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar colaborador..."
              style={{background:"#fff",border:"1px solid "+C.b1,borderRadius:10,padding:"9px 14px 9px 34px",color:C.tx,fontSize:12.5,outline:"none",width:240,fontFamily:"'Inter',system-ui,sans-serif",fontWeight:500,letterSpacing:-.1,transition:"all .15s"}}
              onFocus={e=>{e.currentTarget.style.borderColor=C.a;e.currentTarget.style.boxShadow="0 0 0 3px "+C.a+"22";}}
              onBlur={e=>{e.currentTarget.style.borderColor=C.b1;e.currentTarget.style.boxShadow="none";}}/>
          </div>
          {/* Filtros por nível */}
          <div style={{display:"inline-flex",gap:3,background:"#fff",border:"1px solid "+C.b1,borderRadius:10,padding:3}}>
            {LEVEL_FILTER_BUTTONS.map(item=>{
              const _on=filterLevel===item.v;
              const _color=LEVEL_COLORS[item.v]||C.a;
              return <button key={item.v} onClick={()=>setFilterLevel(item.v)}
                style={{background:_on?_color:"transparent",border:"none",borderRadius:7,padding:"7px 14px",color:_on?"#fff":C.ts,fontWeight:_on?700:500,fontSize:11.5,letterSpacing:-.1,cursor:"pointer",whiteSpace:"nowrap",transition:"all .15s",fontFamily:"'Inter',system-ui,sans-serif"}}>
                {item.l}
              </button>;
            })}
          </div>
        </div>

      {/* Grid de cards de colaboradores — fotos grandes, sem status nem demandas */}
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(280px,1fr))",gap:14}}>
        {allMembers.map(u=>{
          const lvColor=LEVEL_COLORS[u.level]||C.ts;
          const lvLabel=LEVEL_LABELS[u.level]||"—";
          const photo=collabProfiles[u.id]?.photo;
          const displayName=collabProfiles[u.id]?.nome||u.name;
          return(<div key={u.id}
            style={{background:C.card,borderRadius:16,border:"1px solid "+C.b1,padding:0,transition:"all .15s",display:"flex",flexDirection:"column",position:"relative"}}
            onMouseEnter={e=>{e.currentTarget.style.borderColor=u.color+"66";e.currentTarget.style.boxShadow="0 8px 24px "+u.color+"15";e.currentTarget.style.transform="translateY(-2px)";}}
            onMouseLeave={e=>{e.currentTarget.style.borderColor=C.b1;e.currentTarget.style.boxShadow="none";e.currentTarget.style.transform="translateY(0)";}}>
            {/* Banner com cor do colaborador */}
            <div style={{height:64,background:"linear-gradient(135deg,"+u.color+","+u.color+"99)",position:"relative",borderRadius:"16px 16px 0 0"}}>
              <span style={{position:"absolute",top:10,right:12,background:lvColor,color:"#fff",borderRadius:99,padding:"3px 11px",fontSize:10,fontWeight:800,letterSpacing:.5,textTransform:"uppercase",boxShadow:"0 3px 10px rgba(0,0,0,.18)"}}>{lvLabel}</span>
            </div>
            {/* Foto sobreposta ao banner */}
            <div style={{padding:"0 18px 18px",marginTop:-44,display:"flex",flexDirection:"column",gap:12,position:"relative",zIndex:2}}>
              <div style={{width:88,height:88,borderRadius:"50%",overflow:"hidden",border:"4px solid "+C.card,boxShadow:"0 6px 18px rgba(0,0,0,.12)",background:C.card,flexShrink:0}}>
                {photo
                  ?<img src={photo} alt={u.name} referrerPolicy="no-referrer" style={{width:"100%",height:"100%",objectFit:"cover",display:"block"}}/>
                  :<div style={{width:"100%",height:"100%",background:"linear-gradient(135deg,"+u.color+","+u.color+"99)",display:"flex",alignItems:"center",justifyContent:"center",color:"#fff",fontWeight:900,fontSize:34}}>{u.av}</div>
                }
              </div>
              <div>
                <div style={{color:C.tx,fontWeight:800,fontSize:16,letterSpacing:-.2,lineHeight:1.25}}>{displayName}</div>
                <div style={{color:u.color,fontSize:12.5,fontWeight:600,marginTop:3}}>{(collabProfiles[u.id]&&collabProfiles[u.id].funcao)||u.role}</div>
                <div title="Email de login" style={{color:C.td,fontSize:11,marginTop:4}}>{(loginSecrets[u.id]&&loginSecrets[u.id].email)||(u.id+"@pixelsmarketing.com.br")}</div>
              </div>
              {isMePartner&&(()=>{
                const _sec=loginSecrets[u.id];
                const _rev=!!revealPwd[u.id];
                const _temSenha=!!(_sec&&_sec.senha);
                return <div style={{background:C.s1,border:"1px solid "+C.b1,borderRadius:10,padding:"7px 10px",display:"flex",alignItems:"center",gap:7,marginTop:2}}>
                  <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke={C.td} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{flexShrink:0}}><rect x="3" y="11" width="18" height="11" rx="2"/><path d="M7 11V7a5 5 0 0110 0v4"/></svg>
                  {_temSenha?(<>
                    <span style={{flex:1,fontFamily:"'Inter',system-ui,sans-serif",fontSize:13,color:C.tx,fontWeight:700,letterSpacing:_rev?-.1:2,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{_rev?_sec.senha:"••••••••"}</span>
                    <button title={_rev?"Ocultar":"Mostrar"} onClick={()=>setRevealPwd(m=>({...m,[u.id]:!m[u.id]}))} style={{background:"none",border:"none",cursor:"pointer",color:C.ts,padding:2,display:"flex"}}>
                      {_rev
                        ?<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M17.94 17.94A10.07 10.07 0 0112 20c-7 0-11-8-11-8a18.45 18.45 0 015.06-5.94M9.9 4.24A9.12 9.12 0 0112 4c7 0 11 8 11 8a18.5 18.5 0 01-2.16 3.19m-6.72-1.07a3 3 0 11-4.24-4.24"/><line x1="1" y1="1" x2="23" y2="23"/></svg>
                        :<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>}
                    </button>
                    <button title="Copiar senha" onClick={()=>{try{navigator.clipboard.writeText(_sec.senha);if(typeof pixelsToast!=="undefined")pixelsToast.success("Senha copiada!");}catch(e){}}} style={{background:"none",border:"none",cursor:"pointer",color:C.ts,padding:2,display:"flex"}}>
                      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><rect x="9" y="9" width="13" height="13" rx="2" ry="2"/><path d="M5 15H4a2 2 0 01-2-2V4a2 2 0 012-2h9a2 2 0 012 2v1"/></svg>
                    </button>
                    <button title="Trocar a senha de login desse colaborador" onClick={()=>setResetPwd({open:true,teamId:u.id,nome:displayName,value:"",busy:false})}
                      style={{background:C.a+"12",border:"1px solid "+C.a+"3a",borderRadius:7,padding:"4px 10px",fontSize:10,fontWeight:800,color:C.a,cursor:"pointer",whiteSpace:"nowrap",fontFamily:"'Inter',system-ui,sans-serif",letterSpacing:.2}}>Trocar</button>
                  </>):(<>
                    <span title="As senhas criadas antes desta tela ficam criptografadas no login e não têm como ser recuperadas — nem por nós. Clique em Definir pra registrar uma senha nova (o colaborador passa a logar com ela) e a partir daí ela aparece aqui." style={{flex:1,fontSize:10.5,color:C.td,fontStyle:"italic",cursor:"help"}}>Ainda não registrada</span>
                    <button onClick={()=>setResetPwd({open:true,teamId:u.id,nome:displayName,value:"",busy:false})} style={{background:C.a+"15",border:"1px solid "+C.a+"44",borderRadius:7,padding:"4px 10px",fontSize:10.5,fontWeight:700,color:C.a,cursor:"pointer",whiteSpace:"nowrap"}}>Definir</button>
                  </>)}
                </div>;
              })()}
              {/* Ações — só ícones SVG modernos, sem emojis */}
              <div style={{display:"flex",gap:6,paddingTop:10,borderTop:"1px solid "+C.b1+"66"}}>
                <button onClick={()=>u.level===1?setViewDash(u.id):setViewUser(u)}
                  title="Ver dashboard"
                  style={{flex:1,background:C.s1,border:"1px solid "+C.b1,borderRadius:9,padding:"8px",display:"flex",alignItems:"center",justifyContent:"center",cursor:"pointer",color:C.ts,transition:"all .12s"}}
                  onMouseEnter={e=>{e.currentTarget.style.background=u.color+"15";e.currentTarget.style.color=u.color;e.currentTarget.style.borderColor=u.color+"55";}}
                  onMouseLeave={e=>{e.currentTarget.style.background=C.s1;e.currentTarget.style.color=C.ts;e.currentTarget.style.borderColor=C.b1;}}>
                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1" fill="currentColor"/></svg>
                </button>
                <button onClick={()=>setEditProfile(u.id)}
                  title="Editar perfil"
                  style={{flex:1,background:C.s1,border:"1px solid "+C.b1,borderRadius:9,padding:"8px",display:"flex",alignItems:"center",justifyContent:"center",cursor:"pointer",color:C.ts,transition:"all .12s"}}
                  onMouseEnter={e=>{e.currentTarget.style.background=u.color+"15";e.currentTarget.style.color=u.color;e.currentTarget.style.borderColor=u.color+"55";}}
                  onMouseLeave={e=>{e.currentTarget.style.background=C.s1;e.currentTarget.style.color=C.ts;e.currentTarget.style.borderColor=C.b1;}}>
                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M11 4H4a2 2 0 00-2 2v14a2 2 0 002 2h14a2 2 0 002-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 013 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
                </button>
                {(isMePartner||myPerms?.verDashOutros)&&(<button onClick={()=>onViewAs&&onViewAs(u.id)}
                  title={"Ver como "+u.name}
                  style={{flex:1,background:C.s1,border:"1px solid "+C.b1,borderRadius:9,padding:"8px",display:"flex",alignItems:"center",justifyContent:"center",cursor:"pointer",color:C.ts,transition:"all .12s"}}
                  onMouseEnter={e=>{e.currentTarget.style.background=C.or+"15";e.currentTarget.style.color=C.or;e.currentTarget.style.borderColor=C.or+"55";}}
                  onMouseLeave={e=>{e.currentTarget.style.background=C.s1;e.currentTarget.style.color=C.ts;e.currentTarget.style.borderColor=C.b1;}}>
                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>
                </button>)}
                {isMePartner&&(<button onClick={()=>setEditCollab(u.id)}
                  title="Gerenciar permissões"
                  style={{flex:1,background:C.s1,border:"1px solid "+C.b1,borderRadius:9,padding:"8px",display:"flex",alignItems:"center",justifyContent:"center",cursor:"pointer",color:C.ts,transition:"all .12s"}}
                  onMouseEnter={e=>{e.currentTarget.style.background=C.a+"15";e.currentTarget.style.color=C.a;e.currentTarget.style.borderColor=C.a+"55";}}
                  onMouseLeave={e=>{e.currentTarget.style.background=C.s1;e.currentTarget.style.color=C.ts;e.currentTarget.style.borderColor=C.b1;}}>
                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 00.33 1.82l.06.06a2 2 0 010 2.83 2 2 0 01-2.83 0l-.06-.06a1.65 1.65 0 00-1.82-.33 1.65 1.65 0 00-1 1.51V21a2 2 0 01-2 2 2 2 0 01-2-2v-.09A1.65 1.65 0 009 19.4a1.65 1.65 0 00-1.82.33l-.06.06a2 2 0 01-2.83 0 2 2 0 010-2.83l.06-.06a1.65 1.65 0 00.33-1.82 1.65 1.65 0 00-1.51-1H3a2 2 0 01-2-2 2 2 0 012-2h.09A1.65 1.65 0 004.6 9a1.65 1.65 0 00-.33-1.82l-.06-.06a2 2 0 010-2.83 2 2 0 012.83 0l.06.06a1.65 1.65 0 001.82.33H9a1.65 1.65 0 001-1.51V3a2 2 0 012-2 2 2 0 012 2v.09a1.65 1.65 0 001 1.51 1.65 1.65 0 001.82-.33l.06-.06a2 2 0 012.83 0 2 2 0 010 2.83l-.06.06a1.65 1.65 0 00-.33 1.82V9a1.65 1.65 0 001.51 1H21a2 2 0 012 2 2 2 0 01-2 2h-.09a1.65 1.65 0 00-1.51 1z"/></svg>
                </button>)}
                {isMePartner&&u.id!=="vinicius"&&u.id!=="gustavo"&&(<button onClick={()=>revogarColabAcesso(u.id,displayName)}
                  title="Excluir colaborador"
                  style={{flex:1,background:"#fff",border:"1px solid #fecaca",borderRadius:9,padding:"8px",display:"flex",alignItems:"center",justifyContent:"center",cursor:"pointer",color:"#dc2626",transition:"all .12s"}}
                  onMouseEnter={e=>{e.currentTarget.style.background="#fef2f2";e.currentTarget.style.borderColor="#fca5a5";}}
                  onMouseLeave={e=>{e.currentTarget.style.background="#fff";e.currentTarget.style.borderColor="#fecaca";}}>
                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-2 14a2 2 0 01-2 2H9a2 2 0 01-2-2L5 6"/><path d="M10 11v6M14 11v6"/></svg>
                </button>)}
              </div>
            </div>
          </div>);
        })}
        {allMembers.length===0&&(<div style={{gridColumn:"1 / -1",padding:"60px 20px",textAlign:"center",color:C.td,fontSize:14,background:C.card,borderRadius:16,border:"1px dashed "+C.b1}}>Nenhum colaborador encontrado.</div>)}
      </div>

      {isPartner&&(<div style={{background:C.card,borderRadius:16,border:"1px solid "+C.b1,overflow:"hidden"}}>
        <div style={{padding:"16px 22px",borderBottom:"1px solid "+C.b1,display:"flex",alignItems:"center",gap:12}}>
          <div style={{width:36,height:36,borderRadius:10,background:"linear-gradient(135deg,"+C.a+","+C.aD+")",display:"flex",alignItems:"center",justifyContent:"center",boxShadow:"0 4px 12px "+C.a+"40"}}>
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><rect x="3" y="11" width="18" height="11" rx="2"/><path d="M7 11V7a5 5 0 0110 0v4"/></svg>
          </div>
          <div style={{flex:1}}>
            <div style={{color:C.tx,fontWeight:800,fontSize:15,letterSpacing:-.2}}>Estrutura de níveis</div>
            <div style={{color:C.td,fontSize:11.5,marginTop:1}}>Hierarquia de acesso ao sistema · visível apenas para CEOs</div>
          </div>
        </div>
        <div style={{padding:"6px 0"}}>
          {LEVEL_STRUCTURE.map((lv,idx,arr)=>{
            const members=TEAM.filter(m=>m.level===lv.l);
            const _mostraAv=(m,i)=>{
              const ph=collabProfiles[m.id]?.photo;
              return (<div key={m.id} title={m.name} style={{width:26,height:26,borderRadius:"50%",overflow:"hidden",border:"2px solid "+C.card,marginLeft:i>0?-8:0,cursor:"pointer"}} onClick={()=>setEditProfile(m.id)}>
                {ph?(<img src={ph} alt={m.name} style={{width:"100%",height:"100%",objectFit:"cover"}}/>)
                  :(<div style={{width:"100%",height:"100%",background:m.color+"33",display:"flex",alignItems:"center",justifyContent:"center",color:m.color,fontWeight:900,fontSize:10}}>{m.av}</div>)}
              </div>);
            };
            if(lv.l===3){
              const _norm=d=>d==="video"?"editor":(d||"");
              const SETORES3=[
                {d:"designer",label:"Design",c:"#e040fb"},
                {d:"editor",label:"Edição de vídeo",c:"#0ea5e9"},
                {d:"social",label:"Social media",c:"#ec4899"},
                {d:"coordinator",label:"Estratégia",c:"#8b5cf6"},
                {d:"gestor",label:"Gestão de mídia",c:"#f59e0b"},
              ];
              const usados=new Set();
              const grupos=SETORES3.map(s=>({...s,membros:members.filter(m=>_norm(m.dash)===s.d)})).filter(g=>g.membros.length>0);
              grupos.forEach(g=>g.membros.forEach(m=>usados.add(m.id)));
              const outros=members.filter(m=>!usados.has(m.id));
              if(outros.length)grupos.push({d:"outros",label:"Outros",c:"#94a3b8",membros:outros});
              return (<div key={lv.l} style={{borderBottom:idx<arr.length-1?"1px solid "+C.b1+"44":"none"}}>
                <div style={{display:"flex",alignItems:"center",gap:16,padding:"12px 20px 4px"}}>
                  <div style={{width:28,height:28,borderRadius:8,background:lv.c+"22",border:"1.5px solid "+lv.c+"44",display:"flex",alignItems:"center",justifyContent:"center",color:lv.c,fontWeight:800,fontSize:12,flexShrink:0}}>{lv.l}</div>
                  <div style={{flex:1,minWidth:0}}>
                    <div style={{color:C.tx,fontWeight:600,fontSize:13}}>{lv.name}</div>
                    <div style={{color:C.td,fontSize:11,marginTop:1}}>{lv.desc}</div>
                  </div>
                  <span style={{color:C.td,fontSize:11}}>{members.length+" membro"+(members.length!==1?"s":"")}</span>
                </div>
                <div style={{padding:"2px 20px 10px 64px",display:"flex",flexDirection:"column",gap:2}}>
                  {grupos.map(g=>(
                    <div key={g.d} style={{display:"flex",alignItems:"center",gap:12,padding:"6px 0"}}>
                      <span style={{width:8,height:8,borderRadius:"50%",background:g.c,flexShrink:0}}/>
                      <span style={{flex:1,color:C.ts,fontSize:12.5,fontWeight:600}}>{g.label}</span>
                      <div style={{display:"flex",alignItems:"center"}}>
                        {g.membros.map(_mostraAv)}
                        <span style={{color:C.td,fontSize:11,marginLeft:10,fontFeatureSettings:"'tnum'"}}>{g.membros.length}</span>
                      </div>
                    </div>
                  ))}
                </div>
              </div>);
            }
            return (<div key={lv.l} style={{display:"flex",alignItems:"center",gap:16,padding:"12px 20px",borderBottom:idx<arr.length-1?"1px solid "+C.b1+"44":"none"}}>
              <div style={{width:28,height:28,borderRadius:8,background:lv.c+"22",border:"1.5px solid "+lv.c+"44",display:"flex",alignItems:"center",justifyContent:"center",color:lv.c,fontWeight:800,fontSize:12,flexShrink:0}}>{lv.l}</div>
              <div style={{flex:1,minWidth:0}}>
                <div style={{color:C.tx,fontWeight:600,fontSize:13}}>{lv.name}</div>
                <div style={{color:C.td,fontSize:11,marginTop:1}}>{lv.desc}</div>
              </div>
              <div style={{display:"flex",alignItems:"center"}}>
                {members.length===0&&(<span style={{color:C.td,fontSize:11}}>—</span>)}
                {members.map((m,i)=>{
                  const ph=collabProfiles[m.id]?.photo;
                  return (<div key={m.id} title={m.name} style={{width:26,height:26,borderRadius:"50%",overflow:"hidden",border:"2px solid "+C.card,marginLeft:i>0?-8:0,cursor:"pointer"}} onClick={()=>setEditProfile(m.id)}>
                    {ph?(<img src={ph} alt={m.name} style={{width:"100%",height:"100%",objectFit:"cover"}}/>)
                      :(<div style={{width:"100%",height:"100%",background:m.color+"33",display:"flex",alignItems:"center",justifyContent:"center",color:m.color,fontWeight:900,fontSize:10}}>{m.av}</div>)}
                  </div>);
                })}
                {members.length>0&&(<span style={{color:C.td,fontSize:11,marginLeft:12}}>{members.length+" membro"+(members.length!==1?"s":"")}</span>)}
              </div>
            </div>);
          })}
        </div>
      </div>)}
      </>}

      {/* ══ CLIENTES DO PORTAL — REDESIGN MODERNO ══ */}
      {mainTab==="clientes"&&(
        <div style={{display:"flex",flexDirection:"column",gap:18,width:"100%"}}>
          {(()=>{
            const _clientesPortal=CLIENTS.filter(c=>c.status!=="interno"&&c.id!=="pixels"&&String(c.name||"").trim());
            const _comAcesso=[];
            const _semAcesso=[];
            _clientesPortal.forEach(cl=>{
              const users=clientAuthUsers[cl.id]||[];
              if(users.length>0)users.forEach(u=>_comAcesso.push({cl,user:u}));
              else _semAcesso.push(cl);
            });
            const _unitLabel=(uid)=>{
              if(!uid)return"";
              if(uid==="grupo")return"Grupo Bioter";
              const ids=String(uid).split(",").map(s=>s.trim()).filter(Boolean);
              if(!ids.length)return"";
              const units=(typeof BIOTER_UNITS!=="undefined"?BIOTER_UNITS:[]);
              const labels=ids.map(id=>{
                const u=units.find(x=>x.id===id);
                if(!u)return id;
                if(u.id==="paraguay")return"Paraguay";
                return(u.pickerLabel||u.label.split("/")[0]);
              });
              return labels.join(" + ");
            };
            const _mob=(typeof _pxMob==="function"&&_pxMob());
            const _q=String(buscaCliente||"").toLowerCase().trim();
            const _visiveis=_comAcesso.filter(x=>!_q||[x.cl.name,x.user.name,x.user.email].some(v=>String(v||"").toLowerCase().includes(_q)));
            const _semVis=_semAcesso.filter(c=>!_q||String(c.name||"").toLowerCase().includes(_q));
            const _abrirNovo=(cid)=>{
              const _fc=cid?{id:cid}:(_semAcesso[0]||_clientesPortal[0]||{id:""});
              setNovoCliente({client_id:_fc.id||"",client_unit:"",email:"",password:"",name:"",papel:"admin",photo_base64:"",photo_mime:""});
              setNovoClienteOpen(true);
            };
            const _Stat=({v,l,c,ic})=>(
              <div style={{background:"rgba(255,255,255,.09)",border:"1px solid rgba(255,255,255,.16)",borderRadius:13,padding:"11px 13px",display:"flex",alignItems:"center",gap:10,backdropFilter:"blur(4px)"}}>
                <div style={{width:32,height:32,borderRadius:10,background:c,display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0,boxShadow:"0 4px 12px rgba(0,0,0,.22)"}}>{ic}</div>
                <div style={{minWidth:0}}>
                  <div style={{fontSize:19,fontWeight:800,lineHeight:1,letterSpacing:-.6}}>{v}</div>
                  <div style={{fontSize:10.5,opacity:.72,fontWeight:600,marginTop:3,textTransform:"uppercase",letterSpacing:.4,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{l}</div>
                </div>
              </div>
            );
            return <>
              {/* ══ HERO ══ */}
              <div style={{position:"relative",overflow:"hidden",borderRadius:18,background:"linear-gradient(135deg,#1e1b4b 0%,#4c1d95 46%,#7c3aed 100%)",padding:_mob?"18px 16px":"22px 24px",color:"#fff",boxShadow:"0 16px 38px rgba(76,29,149,.26)"}}>
                <div style={{position:"absolute",right:-50,top:-70,width:230,height:230,borderRadius:"50%",background:"radial-gradient(circle,rgba(255,255,255,.16),transparent 68%)",pointerEvents:"none"}}/>
                <div style={{position:"absolute",left:-40,bottom:-90,width:190,height:190,borderRadius:"50%",background:"radial-gradient(circle,rgba(159,67,246,.35),transparent 70%)",pointerEvents:"none"}}/>
                <div style={{position:"relative",display:"flex",alignItems:_mob?"flex-start":"center",gap:13,flexDirection:_mob?"column":"row"}}>
                  <div style={{width:44,height:44,borderRadius:13,background:"rgba(255,255,255,.15)",border:"1px solid rgba(255,255,255,.24)",display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
                    <svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><rect x="3" y="11" width="18" height="11" rx="2"/><path d="M7 11V7a5 5 0 0110 0v4"/></svg>
                  </div>
                  <div style={{flex:1,minWidth:0}}>
                    <div style={{fontWeight:800,fontSize:_mob?17:19,letterSpacing:-.4}}>Acessos do portal</div>
                    <div style={{fontSize:12.5,opacity:.78,marginTop:3,fontWeight:500}}>Contas de login que os clientes usam pra entrar no portal da Pixels</div>
                  </div>
                  {isPartner && <button onClick={()=>_abrirNovo("")} type="button"
                    style={{background:"#fff",border:"none",borderRadius:11,padding:"10px 16px",color:"#4c1d95",fontSize:12.5,fontWeight:800,cursor:"pointer",display:"inline-flex",alignItems:"center",justifyContent:"center",gap:7,boxShadow:"0 6px 18px rgba(0,0,0,.22)",flexShrink:0,fontFamily:"inherit",letterSpacing:-.1,transition:"all .15s",width:_mob?"100%":"auto"}}
                    onMouseEnter={e=>{e.currentTarget.style.transform="translateY(-1px)";e.currentTarget.style.boxShadow="0 9px 24px rgba(0,0,0,.3)";}}
                    onMouseLeave={e=>{e.currentTarget.style.transform="";e.currentTarget.style.boxShadow="0 6px 18px rgba(0,0,0,.22)";}}>
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
                    Novo acesso
                  </button>}
                </div>
                <div style={{position:"relative",display:"grid",gridTemplateColumns:_mob?"1fr":"repeat(3,minmax(0,1fr))",gap:10,marginTop:16}}>
                  <_Stat v={_comAcesso.length} l="Acessos ativos" c="linear-gradient(135deg,#22c55e,#15803d)"
                    ic={<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round"><path d="M20 6L9 17l-5-5"/></svg>}/>
                  <_Stat v={new Set(_comAcesso.map(x=>x.cl.id)).size+"/"+_clientesPortal.length} l="Clientes com portal" c="linear-gradient(135deg,#a855f7,#6d28d9)"
                    ic={<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><path d="M17 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 00-3-3.87"/></svg>}/>
                  <_Stat v={_semAcesso.length} l="Sem acesso ainda" c="linear-gradient(135deg,#f59e0b,#b45309)"
                    ic={<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="9"/><path d="M12 8v5"/><path d="M12 16.5h.01"/></svg>}/>
                </div>
              </div>

              {/* ══ BUSCA ══ */}
              {(_comAcesso.length+_semAcesso.length)>4 && <div style={{position:"relative",display:"flex",alignItems:"center",maxWidth:_mob?"100%":340}}>
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#94a3b8" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" style={{position:"absolute",left:12,pointerEvents:"none"}}><circle cx="11" cy="11" r="7"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
                <input value={buscaCliente} onChange={e=>setBuscaCliente(e.target.value)} placeholder="Buscar cliente, nome ou e-mail..."
                  style={{width:"100%",background:"#fff",border:"1px solid "+C.b1,borderRadius:11,padding:"10px 14px 10px 35px",color:"#0f172a",fontSize:12.5,outline:"none",fontFamily:"inherit",fontWeight:500,transition:"all .15s"}}
                  onFocus={e=>{e.currentTarget.style.borderColor="#a855f7";e.currentTarget.style.boxShadow="0 0 0 3px rgba(168,85,247,.14)";}}
                  onBlur={e=>{e.currentTarget.style.borderColor=C.b1;e.currentTarget.style.boxShadow="none";}}/>
              </div>}

              {/* ═════ Bloco ATIVOS ═════ */}
              {_visiveis.length>0 && <div>
                <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:11}}>
                  <span style={{color:"#15803d",fontSize:10.5,fontWeight:800,textTransform:"uppercase",letterSpacing:.7,display:"inline-flex",alignItems:"center",gap:7}}>
                    <span style={{width:8,height:8,borderRadius:"50%",background:"#16a34a",boxShadow:"0 0 0 3px rgba(22,163,74,0.18)"}}/>
                    Ativos · {_visiveis.length}
                  </span>
                  <span style={{flex:1,height:1,background:"linear-gradient(90deg,#e2e8f0,transparent)"}}/>
                </div>
                <div style={{display:"grid",gridTemplateColumns:_mob?"1fr":"repeat(auto-fill,minmax(330px,1fr))",gap:12}}>
                  {_visiveis.map(({cl,user})=>{
                    const _isBioter = cl.id==="bioter";
                    // Bioter mostra unidade; outros clientes mostram o nome do cliente
                    const _unitTxt = _isBioter ? (_unitLabel(user.primary_unit)||"—") : (cl.name||"Cliente");
                    return <div key={user.id}
                      style={{background:"#fff",border:"1px solid "+C.b1,borderRadius:14,padding:"14px 16px",display:"flex",flexDirection:"column",gap:11,boxShadow:"0 1px 3px rgba(15,23,42,.04)",transition:"all .15s",position:"relative"}}
                      onMouseEnter={e=>{e.currentTarget.style.borderColor=cl.color+"55";e.currentTarget.style.boxShadow="0 4px 14px "+cl.color+"20";}}
                      onMouseLeave={e=>{e.currentTarget.style.borderColor=C.b1;e.currentTarget.style.boxShadow="0 1px 3px rgba(15,23,42,.04)";}}>
                      {/* Top: logo + nome + status */}
                      <div style={{display:"flex",alignItems:"center",gap:11}}>
                        {/* Logo do cliente + badge circular com foto do usuario (Rodrigo/Douglas/etc) */}
                        <div style={{position:"relative",flexShrink:0}}>
                          <div style={{width:46,height:46,borderRadius:11,background:"#fff",border:"1px solid "+C.b1,display:"flex",alignItems:"center",justifyContent:"center",overflow:"hidden",padding:5}}>
                            <ClientLogo clientId={cl.id} size="md"/>
                          </div>
                          {user.name && <div title={user.name}
                            style={{position:"absolute",right:-5,bottom:-5,width:22,height:22,borderRadius:"50%",border:"2px solid #fff",overflow:"hidden",background:(cl.color||"#64748b"),boxShadow:"0 2px 5px rgba(15,23,42,.18)",display:"flex",alignItems:"center",justifyContent:"center",color:"#fff",fontSize:9.5,fontWeight:800,lineHeight:1}}>
                            {user.photo
                              ? <img src={user.photo} alt="" style={{width:"100%",height:"100%",objectFit:"cover",display:"block"}}/>
                              : String(user.name||"?").trim().charAt(0).toUpperCase()
                            }
                          </div>}
                        </div>
                        <div style={{flex:1,minWidth:0}}>
                          <div style={{color:"#0f172a",fontWeight:800,fontSize:14,letterSpacing:-.2,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{cl.name}</div>
                          {user.name && user.name!==cl.name && <div style={{color:"#64748b",fontSize:11.5,fontWeight:500,marginTop:1,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{user.name}</div>}
                        </div>
                        <span style={{background:"#dcfce7",color:"#15803d",border:"1px solid #16a34a40",fontSize:9.5,fontWeight:800,padding:"3px 8px",borderRadius:99,letterSpacing:.4,textTransform:"uppercase",flexShrink:0}}>Ativo</span>
                      </div>
                      {/* Email */}
                      <div style={{background:"#fafbfc",border:"1px solid #eef0f3",borderRadius:9,padding:"7px 11px",display:"flex",alignItems:"center",gap:7}}>
                        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="#94a3b8" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" style={{flexShrink:0}}><path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z"/><polyline points="22,6 12,13 2,6"/></svg>
                        <span style={{color:"#334155",fontSize:12,fontFamily:"monospace",wordBreak:"break-all",fontWeight:500}}>{user.email||"—"}</span>
                      </div>
                      {/* Senha (do cofre team_passwords) — sócios podem revelar/copiar */}
                      {isPartner && (()=>{
                        const _emailKey=String(user.email||"").toLowerCase().trim();
                        const _pwd=clientPasswordsByEmail[_emailKey]||"";
                        const _revealed=!!revealedPasswords[_emailKey];
                        const _hasPwd=!!_pwd;
                        return <div style={{background:"#fafbfc",border:"1px solid #eef0f3",borderRadius:9,padding:"7px 11px",display:"flex",alignItems:"center",gap:7}}>
                          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="#94a3b8" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" style={{flexShrink:0}}><rect x="3" y="11" width="18" height="11" rx="2"/><path d="M7 11V7a5 5 0 0110 0v4"/></svg>
                          <span style={{color:_hasPwd?"#334155":"#94a3b8",fontSize:12,fontFamily:"monospace",wordBreak:"break-all",fontWeight:500,flex:1,minWidth:0,letterSpacing:_revealed||!_hasPwd?"normal":".15em"}}>
                            {_hasPwd?(_revealed?_pwd:"•".repeat(Math.min(_pwd.length,12))):"sem senha no cofre"}
                          </span>
                          {_hasPwd && <button type="button" onClick={(e)=>{e.stopPropagation();setRevealedPasswords(p=>({...p,[_emailKey]:!p[_emailKey]}));}}
                            title={_revealed?"Ocultar senha":"Mostrar senha"}
                            style={{background:"transparent",border:"none",padding:3,cursor:"pointer",color:"#64748b",borderRadius:5,display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0}}
                            onMouseEnter={e=>e.currentTarget.style.color="#0f172a"}
                            onMouseLeave={e=>e.currentTarget.style.color="#64748b"}>
                            {_revealed
                              ? <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="M17.94 17.94A10.07 10.07 0 0112 20c-7 0-11-8-11-8a18.45 18.45 0 015.06-5.94M9.9 4.24A9.12 9.12 0 0112 4c7 0 11 8 11 8a18.5 18.5 0 01-2.16 3.19m-6.72-1.07a3 3 0 11-4.24-4.24"/><line x1="1" y1="1" x2="23" y2="23"/></svg>
                              : <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>
                            }
                          </button>}
                          {_hasPwd && <button type="button" onClick={(e)=>{
                              e.stopPropagation();
                              try{navigator.clipboard.writeText(_pwd);if(typeof pixelsToast!=="undefined")pixelsToast.success("Senha copiada!",2000);}catch(err){}
                            }}
                            title="Copiar senha"
                            style={{background:"transparent",border:"none",padding:3,cursor:"pointer",color:"#64748b",borderRadius:5,display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0}}
                            onMouseEnter={e=>e.currentTarget.style.color=C.a}
                            onMouseLeave={e=>e.currentTarget.style.color="#64748b"}>
                            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><rect x="9" y="9" width="13" height="13" rx="2" ry="2"/><path d="M5 15H4a2 2 0 01-2-2V4a2 2 0 012-2h9a2 2 0 012 2v1"/></svg>
                          </button>}
                        </div>;
                      })()}
                      {/* Chip unidade / portal exclusivo */}
                      <div style={{display:"flex",alignItems:"center",gap:6,flexWrap:"wrap"}}>
                        {_isBioter
                          ? <span style={{background:"#16a34a15",color:"#15803d",border:"1px solid #16a34a40",borderRadius:8,padding:"4px 10px",fontSize:11,fontWeight:700,display:"inline-flex",alignItems:"center",gap:5}}>
                              <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round"><path d="M20 10c0 6-8 12-8 12s-8-6-8-12a8 8 0 0116 0z"/><circle cx="12" cy="10" r="3"/></svg>
                              {_unitTxt}
                            </span>
                          : <span style={{background:(cl.color||"#64748b")+"15",color:cl.color||"#334155",border:"1px solid "+(cl.color||"#e2e8f0")+"40",borderRadius:8,padding:"4px 10px",fontSize:11,fontWeight:700,display:"inline-flex",alignItems:"center",gap:5}}>
                              <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round"><rect x="3" y="11" width="18" height="11" rx="2"/><path d="M7 11V7a5 5 0 0110 0v4"/></svg>
                              {_unitTxt}
                            </span>
                        }
                      </div>
                      {/* Nível do acesso — Administrador / Comercial (11/09/2026) */}
                      <AcessoNivelPortal user={user} podeEditar={!!isPartner}
                        onSalvo={(papel)=>setClientAuthUsers(prev=>{
                          const nx={...prev};
                          Object.keys(nx).forEach(k=>{ nx[k]=(nx[k]||[]).map(u=>u.id===user.id?{...u,permissions:{...(u.permissions||{}),papel}}:u); });
                          return nx;
                        })}/>
                      {/* Ações */}
                      {isPartner && <div style={{display:"flex",gap:6,paddingTop:9,borderTop:"1px solid #f1f5f9"}}>
                        {onViewAsClient && <button onClick={()=>onViewAsClient(user)} title={"Ver o portal como "+(user.name||cl.name)} type="button"
                          style={{flex:1,background:"#fff",border:"1px solid "+C.b1,borderRadius:9,padding:"7px 12px",color:C.a,fontSize:12,fontWeight:700,cursor:"pointer",display:"inline-flex",alignItems:"center",justifyContent:"center",gap:6,transition:"all .12s",fontFamily:"inherit"}}
                          onMouseEnter={e=>{e.currentTarget.style.background=C.a+"10";e.currentTarget.style.borderColor=C.a+"55";}}
                          onMouseLeave={e=>{e.currentTarget.style.background="#fff";e.currentTarget.style.borderColor=C.b1;}}>
                          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>
                          Ver como
                        </button>}
                        <button onClick={()=>revogarClienteAcesso(user.id,cl.name)} title="Revogar acesso" type="button"
                          style={{background:"#fff",border:"1px solid #fecaca",borderRadius:9,padding:"7px 12px",color:"#dc2626",fontSize:12,fontWeight:700,cursor:"pointer",display:"inline-flex",alignItems:"center",justifyContent:"center",gap:6,transition:"all .12s",fontFamily:"inherit"}}
                          onMouseEnter={e=>{e.currentTarget.style.background="#fef2f2";e.currentTarget.style.borderColor="#fca5a5";}}
                          onMouseLeave={e=>{e.currentTarget.style.background="#fff";e.currentTarget.style.borderColor="#fecaca";}}>
                          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-2 14a2 2 0 01-2 2H9a2 2 0 01-2-2L5 6"/><path d="M10 11v6M14 11v6"/></svg>
                          Revogar
                        </button>
                      </div>}
                    </div>;
                  })}
                </div>
              </div>}

              {/* ══ SEM ACESSO — clientes que ainda não têm login ══ */}
              {_semVis.length>0 && <div>
                <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:11}}>
                  <span style={{color:"#b45309",fontSize:10.5,fontWeight:800,textTransform:"uppercase",letterSpacing:.7,display:"inline-flex",alignItems:"center",gap:7}}>
                    <span style={{width:8,height:8,borderRadius:"50%",background:"#f59e0b",boxShadow:"0 0 0 3px rgba(245,158,11,0.18)"}}/>
                    Sem acesso · {_semVis.length}
                  </span>
                  <span style={{flex:1,height:1,background:"linear-gradient(90deg,#e2e8f0,transparent)"}}/>
                </div>
                <div style={{display:"grid",gridTemplateColumns:_mob?"1fr":"repeat(auto-fill,minmax(250px,1fr))",gap:10}}>
                  {_semVis.map(cl=>(
                    <div key={cl.id}
                      style={{background:"#fff",border:"1px dashed "+C.b1,borderRadius:13,padding:"11px 13px",display:"flex",alignItems:"center",gap:11,transition:"all .15s"}}
                      onMouseEnter={e=>{e.currentTarget.style.borderColor="#f59e0b88";e.currentTarget.style.background="#fffbeb";}}
                      onMouseLeave={e=>{e.currentTarget.style.borderColor=C.b1;e.currentTarget.style.background="#fff";}}>
                      <div style={{width:38,height:38,borderRadius:10,background:"#fff",border:"1px solid "+C.b1,display:"flex",alignItems:"center",justifyContent:"center",overflow:"hidden",padding:4,flexShrink:0}}>
                        <ClientLogo clientId={cl.id} size="sm"/>
                      </div>
                      <div style={{flex:1,minWidth:0}}>
                        <div style={{color:"#0f172a",fontWeight:700,fontSize:12.8,letterSpacing:-.2,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{cl.name}</div>
                        <div style={{color:"#94a3b8",fontSize:10.5,fontWeight:600,marginTop:2}}>sem login no portal</div>
                      </div>
                      {isPartner && <button type="button" onClick={()=>_abrirNovo(cl.id)} title={"Criar acesso pra "+cl.name}
                        style={{background:"#f6f0ff",border:"1px solid #e4d4fd",borderRadius:9,padding:"6px 10px",color:"#7c3aed",fontSize:11.5,fontWeight:800,cursor:"pointer",display:"inline-flex",alignItems:"center",gap:5,flexShrink:0,fontFamily:"inherit",transition:"all .12s"}}
                        onMouseEnter={e=>{e.currentTarget.style.background="#7c3aed";e.currentTarget.style.color="#fff";}}
                        onMouseLeave={e=>{e.currentTarget.style.background="#f6f0ff";e.currentTarget.style.color="#7c3aed";}}>
                        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
                        Criar
                      </button>}
                    </div>
                  ))}
                </div>
              </div>}

              {/* Empty state — quando não há nenhum acesso criado */}
              {_comAcesso.length===0 && <div style={{background:"#fafbfc",border:"1px dashed #e2e8f0",borderRadius:14,padding:"48px 20px",textAlign:"center",color:"#94a3b8",fontSize:13}}>
                <div style={{fontWeight:600,color:"#334155",marginBottom:6}}>Nenhum acesso criado ainda</div>
                <div style={{fontSize:12}}>Clique em <strong style={{color:"#7c3aed"}}>+ Novo acesso</strong> pra liberar o portal pra um cliente.</div>
              </div>}

              {/* Nenhum resultado na busca */}
              {_q && _visiveis.length===0 && _semVis.length===0 && <div style={{background:"#fafbfc",border:"1px dashed #e2e8f0",borderRadius:14,padding:"36px 20px",textAlign:"center",color:"#94a3b8",fontSize:12.5}}>
                Nenhum acesso encontrado pra <strong style={{color:"#334155"}}>{buscaCliente}</strong>.
              </div>}
            </>;
          })()}
        </div>
      )}

      {/* Tab Storage — só admins */}
      {mainTab==="ferramentas"&&isMePartner&&<ToolsVault user={CURRENT_USER}/>}
      {mainTab==="redes"&&typeof PageRedesSociais!=="undefined"&&<PageRedesSociais isMob={typeof _pxMob==="function"?_pxMob():false}/>}
      {mainTab==="senhas"&&_podeSenhas&&<PasswordVault user={CURRENT_USER}/>}
      {mainTab==="storage"&&isPartner&&<StorageManager tasks={tasks}/>}

    </div>
  </>);
}

/* ═══════════════════════════════════════════════════════════════
   TOOLS VAULT — Ferramentas da Pixels (cursos, e-mails, assinaturas).
   Mesma tabela do cofre (team_passwords) com category='ferramenta'
   e um campo `setor` livre pra organizar. Só sócios.
═══════════════════════════════════════════════════════════════ */
function ToolsVault({user}){
  const [items,setItems]     = useState([]);
  const [loading,setLoading] = useState(true);
  const [editing,setEditing] = useState(null);
  const [search,setSearch]   = useState("");
  const [showPwd,setShowPwd] = useState({});
  const [copied,setCopied]   = useState("");

  const PX="#9F43F6", PX_DK="#7c3aed", PX_BG="#f6f0ff", PX_BD="#e4d4fd";
  const INK="#0f172a", MUTE="#64748b", SOFT="#94a3b8", BORD="#eceef3";

  const _load = async function(){
    try{
      setLoading(true);
      const sb=window._sb; if(!sb) return;
      const{data,error}=await sb.from("team_passwords").select("*").eq("category","ferramenta").order("setor",{ascending:true});
      if(!error&&data) setItems(data);
    }catch(e){ console.warn("[ferramentas] load:",e); }
    finally{ setLoading(false); }
  };
  useEffect(function(){ _load(); },[]);

  // Setores já usados viram sugestão no cadastro
  const _setores = Array.from(new Set(items.map(function(i){return (i.setor||"").trim();}).filter(Boolean))).sort();

  const _new   = function(){ setEditing({id:"",label:"",setor:"",username:"",password:"",url:"",notes:""}); };
  const _edit  = function(it){ setEditing(Object.assign({},it)); };
  const _close = function(){ setEditing(null); };

  const _save = async function(){
    if(!editing.label || !editing.label.trim()){
      if(typeof pixelsToast!=="undefined") pixelsToast.warning("Dá um nome pra ferramenta.");
      return;
    }
    try{
      const sb=window._sb;
      const payload={
        label:(editing.label||"").trim(),
        category:"ferramenta",
        setor:(editing.setor||"").trim()||null,
        username:editing.username||"",
        password:editing.password||"",
        url:editing.url||"",
        notes:editing.notes||"",
        author_id:(typeof CURRENT_USER!=="undefined"?CURRENT_USER.id:""),
        author_name:(typeof CURRENT_USER!=="undefined"?CURRENT_USER.name:""),
        updated_at:new Date().toISOString(),
      };
      let r;
      if(editing.id) r=await sb.from("team_passwords").update(payload).eq("id",editing.id);
      else           r=await sb.from("team_passwords").insert(payload);
      if(r&&r.error){
        if(typeof pixelsToast!=="undefined") pixelsToast.error("Erro salvando: "+(r.error.message||""),6000);
        return;
      }
      if(typeof pixelsToast!=="undefined") pixelsToast.success("Ferramenta salva.");
      setEditing(null); _load();
    }catch(e){
      if(typeof pixelsToast!=="undefined") pixelsToast.error("Erro salvando: "+((e&&e.message)||""),6000);
    }
  };

  const _del = async function(it){
    try{
      const sb=window._sb;
      const r=await sb.from("team_passwords").delete().eq("id",it.id);
      if(r&&r.error){ if(typeof pixelsToast!=="undefined") pixelsToast.error("Erro removendo."); return; }
      if(typeof pixelsToast!=="undefined") pixelsToast.success("Removido.");
      _load();
    }catch(_){}
  };

  const _copy = function(txt,key){
    try{
      if(navigator&&navigator.clipboard) navigator.clipboard.writeText(txt||"");
      setCopied(key); setTimeout(function(){ setCopied(""); },1500);
    }catch(_){}
  };

  // Filtro de busca
  const _q=(search||"").trim().toLowerCase();
  const _visiveis = _q
    ? items.filter(function(i){
        const hay=((i.label||"")+" "+(i.setor||"")+" "+(i.username||"")+" "+(i.url||"")+" "+(i.notes||"")).toLowerCase();
        return hay.indexOf(_q)>=0;
      })
    : items;

  // Agrupa por setor
  const _grupos={};
  _visiveis.forEach(function(i){
    const k=(i.setor||"").trim()||"Sem setor";
    if(!_grupos[k]) _grupos[k]=[];
    _grupos[k].push(i);
  });
  const _nomesSetores=Object.keys(_grupos).sort(function(a,b){
    if(a==="Sem setor") return 1;
    if(b==="Sem setor") return -1;
    return a.localeCompare(b,"pt-BR");
  });

  const _inp={width:"100%",padding:"10px 12px",border:"1px solid #e2e8f0",borderRadius:10,fontSize:13,fontFamily:"inherit",outline:"none",boxSizing:"border-box",background:"#fff",color:INK};
  const _lbl={color:SOFT,fontSize:10,fontWeight:800,letterSpacing:.5,textTransform:"uppercase",marginBottom:6};

  return <div style={{display:"flex",flexDirection:"column",gap:16,fontFamily:"'Inter',system-ui,sans-serif"}}>

    {/* ═══ CABEÇALHO ═══ */}
    <div style={{background:"#fff",border:"1px solid "+BORD,borderRadius:16,padding:"18px 20px",display:"flex",alignItems:"center",gap:14,flexWrap:"wrap",boxShadow:"0 1px 3px rgba(15,23,42,.04)"}}>
      <div style={{width:44,height:44,borderRadius:13,background:"linear-gradient(135deg,#9F43F6,#7c3aed)",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0,boxShadow:"0 6px 16px rgba(159,67,246,.28)"}}>
        <Ico n="settings" size={21} color="#fff"/>
      </div>
      <div style={{minWidth:0,flex:1}}>
        <div style={{color:INK,fontSize:17,fontWeight:800,letterSpacing:-.4}}>Ferramentas da Pixels</div>
        <div style={{color:MUTE,fontSize:12.5,marginTop:2}}>Cursos, e-mails, assinaturas e serviços — organizados por setor.</div>
      </div>
      <div style={{position:"relative",flexShrink:0}}>
        <input value={search} onChange={function(e){setSearch(e.target.value);}} placeholder="Buscar ferramenta, setor, e-mail..."
          style={{width:250,padding:"9px 12px 9px 34px",border:"1px solid #e2e8f0",borderRadius:10,fontSize:12.5,fontFamily:"inherit",outline:"none",background:"#fafbfc"}}/>
        <span style={{position:"absolute",left:11,top:"50%",transform:"translateY(-50%)",display:"inline-flex",color:SOFT}}><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><circle cx="11" cy="11" r="8"/><path d="m21 21-4.3-4.3"/></svg></span>
      </div>
      <button onClick={_new}
        style={{background:"linear-gradient(135deg,#9F43F6,#7c3aed)",color:"#fff",border:"none",borderRadius:11,padding:"11px 18px",fontSize:12.5,fontWeight:800,cursor:"pointer",display:"inline-flex",alignItems:"center",gap:8,flexShrink:0,boxShadow:"0 6px 16px rgba(159,67,246,.28)",fontFamily:"inherit"}}>
        <Ico n="plus" size={14} color="#fff"/> Nova ferramenta
      </button>
    </div>

    {/* ═══ AVISO DE SEGURANÇA ═══ */}
    <div style={{background:"#fff7ed",border:"1px solid #fed7aa",borderRadius:12,padding:"11px 15px",display:"flex",alignItems:"center",gap:10}}>
      <Ico n="alert" size={15} color="#c2410c"/>
      <div style={{color:"#9a3412",fontSize:11.5,lineHeight:1.5}}>
        Visível só para sócios. As senhas ficam em texto puro no banco com RLS restringindo a level 1 — não use para dados bancários.
      </div>
    </div>

    {loading&&<div style={{color:SOFT,fontSize:13,padding:"30px 0",textAlign:"center",fontStyle:"italic"}}>Carregando...</div>}

    {!loading&&_visiveis.length===0&&<div style={{background:"#fafbfc",border:"1.5px dashed #e2e8f0",borderRadius:16,padding:"46px 20px",textAlign:"center"}}>
      <div style={{width:48,height:48,borderRadius:14,background:"#fff",border:"1px solid "+BORD,display:"inline-flex",alignItems:"center",justifyContent:"center",marginBottom:12}}>
        <Ico n="settings" size={22} color={SOFT}/>
      </div>
      <div style={{color:INK,fontSize:14,fontWeight:700}}>{_q?"Nada encontrado":"Nenhuma ferramenta cadastrada"}</div>
      <div style={{color:SOFT,fontSize:12,marginTop:5}}>{_q?"Tente outro termo.":"Clique em Nova ferramenta pra cadastrar a primeira."}</div>
    </div>}

    {/* ═══ GRUPOS POR SETOR ═══ */}
    {!loading&&_nomesSetores.map(function(setor){
      const lista=_grupos[setor];
      return <div key={setor}>
        <div style={{display:"flex",alignItems:"center",gap:9,marginBottom:11}}>
          <span style={{background:PX_BG,color:PX_DK,border:"1px solid "+PX_BD,fontSize:11,fontWeight:800,padding:"5px 12px",borderRadius:99,letterSpacing:.3}}>{setor}</span>
          <span style={{color:SOFT,fontSize:11,fontWeight:700}}>{lista.length} {lista.length===1?"item":"itens"}</span>
          <div style={{flex:1,height:1,background:"linear-gradient(90deg,#eceef3,transparent)"}}/>
        </div>
        <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(300px,1fr))",gap:12}}>
          {lista.map(function(it){
            const _k=String(it.id);
            const _show=!!showPwd[_k];
            return <div key={_k} style={{background:"#fff",border:"1px solid "+BORD,borderRadius:14,padding:"15px 16px",boxShadow:"0 1px 2px rgba(15,23,42,.04)",transition:"all .18s",display:"flex",flexDirection:"column",gap:10}}
              onMouseEnter={function(e){e.currentTarget.style.borderColor=PX_BD;e.currentTarget.style.boxShadow="0 8px 20px rgba(88,64,166,.09)";e.currentTarget.style.transform="translateY(-2px)";}}
              onMouseLeave={function(e){e.currentTarget.style.borderColor=BORD;e.currentTarget.style.boxShadow="0 1px 2px rgba(15,23,42,.04)";e.currentTarget.style.transform="";}}>

              <div style={{display:"flex",alignItems:"flex-start",gap:10}}>
                <div style={{width:34,height:34,borderRadius:10,background:PX_BG,border:"1px solid "+PX_BD,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
                  <Ico n="lock" size={15} color={PX_DK}/>
                </div>
                <div style={{minWidth:0,flex:1}}>
                  <div style={{color:INK,fontSize:13.5,fontWeight:800,letterSpacing:-.2,lineHeight:1.3,wordBreak:"break-word"}}>{it.label}</div>
                  {it.url&&<a href={it.url} target="_blank" rel="noreferrer" style={{color:PX_DK,fontSize:11,textDecoration:"none",display:"inline-flex",alignItems:"center",gap:4,marginTop:3}}>
                    <Ico n="link" size={10}/> abrir site
                  </a>}
                </div>
                <div style={{display:"flex",gap:4,flexShrink:0}}>
                  <button onClick={function(){_edit(it);}} title="Editar" style={{background:"transparent",border:"none",color:SOFT,cursor:"pointer",padding:5,borderRadius:7,display:"inline-flex"}}><Ico n="edit" size={13}/></button>
                  <button onClick={function(){ if(window.confirm("Remover \""+it.label+"\"?")) _del(it); }} title="Remover" style={{background:"transparent",border:"none",color:"#f87171",cursor:"pointer",padding:5,borderRadius:7,display:"inline-flex"}}><Ico n="trash" size={13}/></button>
                </div>
              </div>

              {it.username&&<div style={{background:"#fafbfc",border:"1px solid #f1f3f7",borderRadius:9,padding:"8px 10px",display:"flex",alignItems:"center",gap:8}}>
                <Ico n="mail" size={12} color={SOFT}/>
                <span style={{flex:1,minWidth:0,color:INK,fontSize:12,fontFamily:"'JetBrains Mono',monospace",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{it.username}</span>
                <button onClick={function(){_copy(it.username,_k+"-u");}} title="Copiar" style={{background:"transparent",border:"none",color:copied===(_k+"-u")?"#16a34a":SOFT,cursor:"pointer",padding:3,display:"inline-flex"}}>
                  <Ico n={copied===(_k+"-u")?"check":"copy"} size={12}/>
                </button>
              </div>}

              {it.password&&<div style={{background:"#fafbfc",border:"1px solid #f1f3f7",borderRadius:9,padding:"8px 10px",display:"flex",alignItems:"center",gap:8}}>
                <Ico n="lock" size={12} color={SOFT}/>
                <span style={{flex:1,minWidth:0,color:INK,fontSize:12,fontFamily:"'JetBrains Mono',monospace",letterSpacing:_show?0:2,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>
                  {_show?it.password:"••••••••••"}
                </span>
                <button onClick={function(){setShowPwd(function(p){const n=Object.assign({},p); n[_k]=!n[_k]; return n;});}} title={_show?"Ocultar":"Mostrar"} style={{background:"transparent",border:"none",color:_show?PX_DK:SOFT,cursor:"pointer",padding:3,display:"inline-flex"}}>
                  <Ico n="eye" size={12}/>
                </button>
                <button onClick={function(){_copy(it.password,_k+"-p");}} title="Copiar" style={{background:"transparent",border:"none",color:copied===(_k+"-p")?"#16a34a":SOFT,cursor:"pointer",padding:3,display:"inline-flex"}}>
                  <Ico n={copied===(_k+"-p")?"check":"copy"} size={12}/>
                </button>
              </div>}

              {it.notes&&<div style={{color:MUTE,fontSize:11.5,lineHeight:1.45,borderTop:"1px solid #f4f5f8",paddingTop:9}}>{it.notes}</div>}
            </div>;
          })}
        </div>
      </div>;
    })}

    {/* ═══ MODAL DE CADASTRO ═══ */}
    {editing&&<div onMouseDown={_close} style={{position:"fixed",inset:0,zIndex:2000,background:"rgba(15,23,42,.5)",backdropFilter:"blur(3px)",display:"flex",alignItems:"center",justifyContent:"center",padding:20}}>
      <div onMouseDown={function(e){e.stopPropagation();}} style={{background:"#fff",borderRadius:18,width:"min(520px,100%)",maxHeight:"88vh",overflowY:"auto",boxShadow:"0 24px 60px rgba(15,23,42,.28)",fontFamily:"'Inter',system-ui,sans-serif"}}>
        <div style={{padding:"20px 22px",borderBottom:"1px solid "+BORD,display:"flex",alignItems:"center",gap:12}}>
          <div style={{width:38,height:38,borderRadius:11,background:PX_BG,border:"1px solid "+PX_BD,display:"flex",alignItems:"center",justifyContent:"center"}}>
            <Ico n="settings" size={17} color={PX_DK}/>
          </div>
          <div style={{flex:1,minWidth:0}}>
            <div style={{color:INK,fontSize:16,fontWeight:800,letterSpacing:-.3}}>{editing.id?"Editar ferramenta":"Nova ferramenta"}</div>
            <div style={{color:SOFT,fontSize:11.5,marginTop:1}}>Cadastro rápido de acesso da Pixels</div>
          </div>
          <button onClick={_close} style={{background:"transparent",border:"none",color:SOFT,cursor:"pointer",padding:6,display:"inline-flex"}}><Ico n="x" size={17}/></button>
        </div>

        <div style={{padding:"20px 22px",display:"flex",flexDirection:"column",gap:15}}>
          <div>
            <div style={_lbl}>Nome da ferramenta *</div>
            <input value={editing.label||""} onChange={function(e){setEditing(Object.assign({},editing,{label:e.target.value}));}}
              placeholder="ex: Curso de Growth — Hotmart" style={_inp} autoFocus/>
          </div>

          <div>
            <div style={_lbl}>Setor</div>
            <input value={editing.setor||""} onChange={function(e){setEditing(Object.assign({},editing,{setor:e.target.value}));}}
              placeholder="ex: Educação, E-mails, Design..." style={_inp} list="px-setores-sugestao"/>
            <datalist id="px-setores-sugestao">
              {_setores.map(function(x){ return <option key={x} value={x}/>; })}
            </datalist>
            {_setores.length>0&&<div style={{display:"flex",gap:5,flexWrap:"wrap",marginTop:7}}>
              {_setores.map(function(x){
                return <button key={x} onClick={function(){setEditing(Object.assign({},editing,{setor:x}));}}
                  style={{background:editing.setor===x?PX_BG:"#fafbfc",color:editing.setor===x?PX_DK:MUTE,border:"1px solid "+(editing.setor===x?PX_BD:BORD),borderRadius:99,padding:"4px 11px",fontSize:11,fontWeight:700,cursor:"pointer",fontFamily:"inherit"}}>{x}</button>;
              })}
            </div>}
          </div>

          <div style={{display:"grid",gridTemplateColumns:_pxMob()?"1fr":"1fr 1fr",gap:12}}>
            <div>
              <div style={_lbl}>E-mail / usuário</div>
              <input value={editing.username||""} onChange={function(e){setEditing(Object.assign({},editing,{username:e.target.value}));}}
                placeholder="contato@pixels.com.br" style={_inp} autoComplete="off"/>
            </div>
            <div>
              <div style={_lbl}>Senha</div>
              <input value={editing.password||""} onChange={function(e){setEditing(Object.assign({},editing,{password:e.target.value}));}}
                placeholder="••••••••" style={Object.assign({},_inp,{fontFamily:"'JetBrains Mono',monospace"})} autoComplete="new-password"/>
            </div>
          </div>

          <div>
            <div style={_lbl}>Link de acesso</div>
            <input value={editing.url||""} onChange={function(e){setEditing(Object.assign({},editing,{url:e.target.value}));}}
              placeholder="https://..." style={_inp}/>
          </div>

          <div>
            <div style={_lbl}>Observações</div>
            <textarea value={editing.notes||""} onChange={function(e){setEditing(Object.assign({},editing,{notes:e.target.value}));}}
              placeholder="plano contratado, vencimento, quem usa, 2FA..." rows={3}
              style={Object.assign({},_inp,{resize:"vertical",minHeight:70,fontFamily:"inherit"})}/>
          </div>
        </div>

        <div style={{padding:"16px 22px",borderTop:"1px solid "+BORD,display:"flex",justifyContent:"flex-end",gap:9,background:"#fafbfc",borderRadius:"0 0 18px 18px"}}>
          <button onClick={_close} style={{background:"#fff",color:MUTE,border:"1px solid "+BORD,borderRadius:10,padding:"10px 18px",fontSize:12.5,fontWeight:700,cursor:"pointer",fontFamily:"inherit"}}>Cancelar</button>
          <button onClick={_save} style={{background:"linear-gradient(135deg,#9F43F6,#7c3aed)",color:"#fff",border:"none",borderRadius:10,padding:"10px 20px",fontSize:12.5,fontWeight:800,cursor:"pointer",fontFamily:"inherit",boxShadow:"0 5px 14px rgba(159,67,246,.28)"}}>Salvar</button>
        </div>
      </div>
    </div>}
  </div>;
}

/* ─── PASSWORD VAULT (cofre de senhas — só sócios) ─── */
/* ═══ COFRE DE SENHAS — v2 (09/09/2026) ═══════════════════════════════════
   Organizado por SEÇÃO (categoria), linhas compactas em vez de card grande,
   favicon do serviço (Google s2) ou logo do cliente, monograma como fallback.
   Categorias = PV_CATS (id gravado em team_passwords.category). Ids antigos
   (servico/interno/ferramenta) caem em "outro".                             */
const PV_CATS = [
  {id:"cliente",    label:"Clientes",             desc:"Portal e contas dos clientes",        color:"#16a34a", icon:"users"},
  {id:"email",      label:"E-mails & Workspace",  desc:"Gmail, Titan, Locaweb e-mail",       color:"#dc2626", icon:"mail"},
  {id:"sites",      label:"Sites & hospedagem",   desc:"Domínios, WordPress, Vercel, FTP",   color:"#0ea5e9", icon:"globe"},
  {id:"social",     label:"Redes sociais",        desc:"Instagram, Facebook, LinkedIn",      color:"#ec4899", icon:"share"},
  {id:"gestao",     label:"Gestão & operação",    desc:"Asana, CRM, assinatura, IA, freelas",color:"#7c3aed", icon:"grid"},
  {id:"financeiro", label:"Financeiro & fiscal",  desc:"Asaas, Conta Azul, NF, certificado", color:"#f59e0b", icon:"dollar"},
  {id:"criativo",   label:"Criativos & mídia",    desc:"Adobe, bancos de imagem e vídeo",    color:"#f97316", icon:"image"},
  {id:"cursos",     label:"Cursos & comunidades", desc:"Mentorias, plataformas de curso",    color:"#0d9488", icon:"book"},
  {id:"outro",      label:"Outros",               desc:"Sem categoria definida",             color:"#64748b", icon:"lock"},
];
function _pvCat(id){ return PV_CATS.find(function(c){return c.id===id;}) || PV_CATS[PV_CATS.length-1]; }
/* Tom mais escuro da mesma cor — gradiente do cabeçalho da seção */
function _pvEscuro(hex){
  if(!hex||hex[0]!=="#"||hex.length!==7) return hex;
  const r=Math.max(0,parseInt(hex.slice(1,3),16)-38);
  const g=Math.max(0,parseInt(hex.slice(3,5),16)-38);
  const b=Math.max(0,parseInt(hex.slice(5,7),16)-38);
  return "#"+((1<<24)+(r<<16)+(g<<8)+b).toString(16).slice(1);
}
function _PvIco({n,size,color}){
  const s=size||14, c=color||"currentColor";
  const P={fill:"none",stroke:c,strokeWidth:2.2,strokeLinecap:"round",strokeLinejoin:"round",width:s,height:s,viewBox:"0 0 24 24"};
  switch(n){
    case "users":  return <svg {...P}><path d="M17 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 00-3-3.87"/><path d="M16 3.13a4 4 0 010 7.75"/></svg>;
    case "mail":   return <svg {...P}><rect x="2" y="4" width="20" height="16" rx="2"/><path d="M22 7l-10 6L2 7"/></svg>;
    case "globe":  return <svg {...P}><circle cx="12" cy="12" r="10"/><path d="M2 12h20"/><path d="M12 2a15.3 15.3 0 014 10 15.3 15.3 0 01-4 10 15.3 15.3 0 01-4-10 15.3 15.3 0 014-10z"/></svg>;
    case "share":  return <svg {...P}><circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><path d="M8.6 13.5l6.8 4M15.4 6.5l-6.8 4"/></svg>;
    case "grid":   return <svg {...P}><rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/></svg>;
    case "dollar": return <svg {...P}><path d="M12 2v20"/><path d="M17 5.5H9.5a3.5 3.5 0 000 7h5a3.5 3.5 0 010 7H6"/></svg>;
    case "image":  return <svg {...P}><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><path d="M21 15l-5-5L5 21"/></svg>;
    case "book":   return <svg {...P}><path d="M4 19.5A2.5 2.5 0 016.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 014 19.5v-15A2.5 2.5 0 016.5 2z"/></svg>;
    case "copy":   return <svg {...P}><rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 01-2-2V4a2 2 0 012-2h9a2 2 0 012 2v1"/></svg>;
    case "eye":    return <svg {...P}><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>;
    case "eyeoff": return <svg {...P}><path d="M17.94 17.94A10.07 10.07 0 0112 20c-7 0-11-8-11-8a18.45 18.45 0 015.06-5.94M9.9 4.24A9.12 9.12 0 0112 4c7 0 11 8 11 8a18.5 18.5 0 01-2.16 3.19m-6.72-1.07a3 3 0 11-4.24-4.24"/><path d="M1 1l22 22"/></svg>;
    case "ext":    return <svg {...P}><path d="M18 13v6a2 2 0 01-2 2H5a2 2 0 01-2-2V8a2 2 0 012-2h6"/><polyline points="15 3 21 3 21 9"/><line x1="10" y1="14" x2="21" y2="3"/></svg>;
    case "edit":   return <svg {...P}><path d="M11 4H4a2 2 0 00-2 2v14a2 2 0 002 2h14a2 2 0 002-2v-7"/><path d="M18.5 2.5a2.12 2.12 0 013 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>;
    case "trash":  return <svg {...P}><polyline points="3 6 5 6 21 6"/><path d="M19 6l-2 14a2 2 0 01-2 2H9a2 2 0 01-2-2L5 6"/><path d="M10 11v6M14 11v6"/></svg>;
    case "chev":   return <svg {...P}><polyline points="6 9 12 15 18 9"/></svg>;
    case "search": return <svg {...P}><circle cx="11" cy="11" r="7"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>;
    case "plus":   return <svg {...P} strokeWidth="3"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>;
    case "note":   return <svg {...P}><path d="M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/></svg>;
    default:       return <svg {...P}><rect x="3" y="11" width="18" height="11" rx="2"/><path d="M7 11V7a5 5 0 0110 0v4"/></svg>;
  }
}
// Domínio pro favicon: pela URL, senão pelo nome do serviço (mapa), senão nada (monograma)
const _PV_DOMAINS = [
  ["gmail","google.com"],["google workspace","google.com"],["titan","titan.email"],["locaweb","locaweb.com.br"],["hostgator","hostgator.com.br"],
  ["wix","wix.com"],["vercel","vercel.com"],["elementor","elementor.com"],["wordpress","wordpress.org"],
  ["instagram","instagram.com"],["facebook","facebook.com"],["linkedin","linkedin.com"],["tiktok","tiktok.com"],["youtube","youtube.com"],
  ["asana","asana.com"],["clickup","clickup.com"],["trello","trello.com"],["buffer","buffer.com"],["mlabs","mlabs.com.br"],["reportei","reportei.com"],
  ["rd station","rdstation.com"],["ekyte","ekyte.com"],["lusha","lusha.com"],["econodata","econodata.com.br"],["empresaqui","empresaqui.com.br"],
  ["autentique","autentique.com.br"],["d4sign","d4sign.com.br"],["chatgpt","openai.com"],["opus","opus.pro"],["fiverr","fiverr.com"],["workana","workana.com"],
  ["asaas","asaas.com"],["conta azul","contaazul.com"],["paypal","paypal.com"],["adobe","adobe.com"],["freepik","freepik.com"],["motion array","motionarray.com"],
  ["wetransfer","wetransfer.com"],["finclass","finclass.com"],["staage","staage.com"],["cademi","cademi.com.br"],["nova legião","cademi.com.br"],
  ["meta","meta.com"],["canva","canva.com"],["notion","notion.so"],["supabase","supabase.com"],["github","github.com"],["figma","figma.com"],
];
function _pvDomain(it){
  const u=String(it.url||"").trim();
  if(u){ try{ return new URL(u.indexOf("://")>0?u:"https://"+u).hostname; }catch(_){ } }
  const l=String(it.label||"").toLowerCase();
  for(let i=0;i<_PV_DOMAINS.length;i++){ if(l.indexOf(_PV_DOMAINS[i][0])>=0) return _PV_DOMAINS[i][1]; }
  return "";
}
function _PvAvatar({it,cat}){
  const [err,setErr]=useState(false);
  const _cli=(typeof CLIENTS!=="undefined"&&it.client_id)?(CLIENTS.find(function(c){return c.id===it.client_id;})||null):null;
  const box={width:36,height:36,borderRadius:10,flexShrink:0,display:"inline-flex",alignItems:"center",justifyContent:"center",overflow:"hidden",background:"#fff",border:"1px solid #eceff4",boxShadow:"0 1px 2px rgba(15,23,42,.04)"};
  if(_cli) return <div style={Object.assign({},box,{padding:3})}><ClientLogo clientId={_cli.id} size="sm"/></div>;
  const dom=_pvDomain(it);
  if(dom&&!err) return <div style={box}><img src={"https://www.google.com/s2/favicons?domain="+encodeURIComponent(dom)+"&sz=64"} alt="" width={20} height={20} style={{display:"block"}} onError={function(){setErr(true);}}/></div>;
  const ini=String(it.label||"?").replace(/[^A-Za-zÀ-ÿ0-9 ]/g,"").trim().split(/\s+/).slice(0,2).map(function(w){return w[0]||"";}).join("").toUpperCase()||"?";
  return <div style={Object.assign({},box,{background:cat.color+"14",border:"1px solid "+cat.color+"2e",color:cat.color,fontSize:11.5,fontWeight:800,letterSpacing:-.3})}>{ini}</div>;
}

function PasswordVault({user}){
  const [items,setItems] = useState([]);
  const [loading,setLoading] = useState(true);
  const [editing,setEditing] = useState(null); // null | {} pra novo, {id,...} pra editar
  const [search,setSearch] = useState("");
  const [showPwd,setShowPwd] = useState({});
  const [catFilter,setCatFilter] = useState("");
  const [collapsed,setCollapsed] = useState({});
  const [notesOpen,setNotesOpen] = useState({});

  const CATS = PV_CATS;
  const _catOf = function(id){ return _pvCat(id); };

  const _load = async ()=>{
    try{
      setLoading(true);
      const sb=window._sb;
      const{data,error}=await sb.from("team_passwords").select("*").order("label",{ascending:true});
      if(!error&&data)setItems(data);
    }catch(e){console.warn("[vault] load:",e);}
    finally{setLoading(false);}
  };
  useEffect(()=>{_load();},[]);

  const _new = ()=>setEditing({id:"",label:"",category:"gestao",client_id:"",username:"",password:"",url:"",notes:""});
  const _edit = (it)=>setEditing({...it});
  const _close = ()=>setEditing(null);

  const _save = async ()=>{
    if(!editing.label.trim()){
      if(typeof pixelsToast!=="undefined")pixelsToast.warning("Coloca um título (label).");
      return;
    }
    try{
      const sb=window._sb;
      const payload={
        label:editing.label.trim(),
        category:editing.category||"outro",
        client_id:editing.client_id||null,
        username:editing.username||"",
        password:editing.password||"",
        url:editing.url||"",
        notes:editing.notes||"",
        author_id:user.id,
        author_name:user.name,
        updated_at:new Date().toISOString(),
      };
      if(editing.id){
        const{error}=await sb.from("team_passwords").update(payload).eq("id",editing.id);
        if(error){if(typeof pixelsToast!=="undefined")pixelsToast.error(error.message);return;}
      }else{
        const{error}=await sb.from("team_passwords").insert(payload);
        if(error){if(typeof pixelsToast!=="undefined")pixelsToast.error(error.message);return;}
      }
      if(typeof pixelsToast!=="undefined")pixelsToast.success("Salvo.");
      _close();_load();
    }catch(e){
      if(typeof pixelsToast!=="undefined")pixelsToast.error("Erro: "+String(e?.message||e));
    }
  };

  const _delete = async (it)=>{
    const ok = (typeof pixelsConfirm==="function")
      ? await pixelsConfirm("Excluir '"+it.label+"'?",{okText:"Excluir",danger:true})
      : confirm("Excluir?");
    if(!ok)return;
    try{
      const sb=window._sb;
      await sb.from("team_passwords").delete().eq("id",it.id);
      if(typeof pixelsToast!=="undefined")pixelsToast.success("Excluído.");
      _load();
    }catch(e){
      if(typeof pixelsToast!=="undefined")pixelsToast.error("Erro: "+String(e?.message||e));
    }
  };

  const _copy = (txt,what)=>{
    if(!txt)return;
    try{
      navigator.clipboard.writeText(txt);
      if(typeof pixelsToast!=="undefined")pixelsToast.success((what||"Texto")+" copiado.");
    }catch(e){
      if(typeof pixelsToast!=="undefined")pixelsToast.error("Falha ao copiar.");
    }
  };

  const _catId = function(it){ const c=String(it.category||"outro"); return CATS.some(function(x){return x.id===c;})?c:"outro"; };
  const _filtered = items.filter(it=>{
    if(!search.trim())return true;
    const s=search.toLowerCase();
    return String(it.label||"").toLowerCase().includes(s)
        || String(it.username||"").toLowerCase().includes(s)
        || String(it.client_id||"").toLowerCase().includes(s)
        || String(it.url||"").toLowerCase().includes(s)
        || String(it.notes||"").toLowerCase().includes(s);
  });

  const _mob=(typeof _pxMob==="function"&&_pxMob());
  const _cnt = (cid)=>items.filter(it=>_catId(it)===cid).length;
  const _dt = (v)=>{ try{ const d=new Date(v); if(isNaN(d))return""; return String(d.getDate()).padStart(2,"0")+"/"+String(d.getMonth()+1).padStart(2,"0")+"/"+d.getFullYear(); }catch(_){ return ""; } };
  // Seções na ordem de PV_CATS, só as que têm item (após busca/filtro)
  const _secoes = CATS.map(function(c){
    return {cat:c, list:_filtered.filter(function(it){ return _catId(it)===c.id && (!catFilter||catFilter===c.id); })
      .sort(function(a,b){ return String(a.label).localeCompare(String(b.label),"pt-BR"); })};
  }).filter(function(s){ return s.list.length>0; });
  const _total = _secoes.reduce(function(n,s){ return n+s.list.length; },0);

  const _iconBtn = function(title,onClick,ico,hover){
    return <button type="button" title={title} onClick={onClick}
      style={{background:"transparent",border:"none",cursor:"pointer",padding:5,borderRadius:7,color:"#94a3b8",display:"inline-flex",flexShrink:0,transition:"all .12s"}}
      onMouseEnter={function(e){e.currentTarget.style.color=hover||"#7c3aed";e.currentTarget.style.background=(hover||"#7c3aed")+"12";}}
      onMouseLeave={function(e){e.currentTarget.style.color="#94a3b8";e.currentTarget.style.background="transparent";}}>
      <_PvIco n={ico} size={13}/>
    </button>;
  };

  return <div style={{display:"flex",flexDirection:"column",gap:14,width:"100%"}}>

    {/* ══ HERO ══ */}
    <div style={{position:"relative",overflow:"hidden",borderRadius:18,background:"linear-gradient(135deg,#0f172a 0%,#312e81 48%,#6d28d9 100%)",padding:_mob?"16px 16px":"18px 22px",color:"#fff",boxShadow:"0 16px 38px rgba(49,46,129,.28)"}}>
      <div style={{position:"absolute",right:-50,top:-70,width:230,height:230,borderRadius:"50%",background:"radial-gradient(circle,rgba(255,255,255,.14),transparent 68%)",pointerEvents:"none"}}/>
      <div style={{position:"relative",display:"flex",alignItems:_mob?"flex-start":"center",gap:13,flexDirection:_mob?"column":"row"}}>
        <div style={{width:42,height:42,borderRadius:13,background:"rgba(255,255,255,.15)",border:"1px solid rgba(255,255,255,.24)",display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="M12 2l8 4v6c0 5-3.4 8.7-8 10-4.6-1.3-8-5-8-10V6l8-4z"/><circle cx="12" cy="11" r="2.2"/><path d="M12 13.2V16"/></svg>
        </div>
        <div style={{flex:1,minWidth:0}}>
          <div style={{fontWeight:800,fontSize:_mob?17:19,letterSpacing:-.4,display:"flex",alignItems:"center",gap:10}}>Cofre de senhas
            <span style={{background:"rgba(255,255,255,.16)",border:"1px solid rgba(255,255,255,.22)",borderRadius:99,padding:"2px 9px",fontSize:11,fontWeight:800}}>{items.length}</span>
          </div>
          <div style={{fontSize:12.5,opacity:.78,marginTop:3,fontWeight:500}}>Credenciais da agência e dos clientes, por seção — visível só pros sócios · texto puro no Supabase (RLS level 1), nada de banco.</div>
        </div>
        <button onClick={_new} type="button"
          style={{background:"#fff",border:"none",borderRadius:11,padding:"10px 16px",color:"#312e81",fontSize:12.5,fontWeight:800,cursor:"pointer",display:"inline-flex",alignItems:"center",justifyContent:"center",gap:7,boxShadow:"0 6px 18px rgba(0,0,0,.24)",flexShrink:0,fontFamily:"inherit",letterSpacing:-.1,transition:"all .15s",width:_mob?"100%":"auto"}}
          onMouseEnter={e=>{e.currentTarget.style.transform="translateY(-1px)";e.currentTarget.style.boxShadow="0 9px 24px rgba(0,0,0,.32)";}}
          onMouseLeave={e=>{e.currentTarget.style.transform="";e.currentTarget.style.boxShadow="0 6px 18px rgba(0,0,0,.24)";}}>
          <_PvIco n="plus" size={13}/> Nova senha
        </button>
      </div>
    </div>

    {/* ══ BUSCA + SEÇÕES (chips) ══ */}
    <div style={{display:"flex",alignItems:"center",gap:10,flexWrap:"wrap"}}>
      <div style={{position:"relative",display:"flex",alignItems:"center",width:_mob?"100%":300}}>
        <span style={{position:"absolute",left:12,display:"inline-flex",pointerEvents:"none"}}><_PvIco n="search" size={14} color="#94a3b8"/></span>
        <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar título, login, cliente, obs…"
          style={{width:"100%",background:"#fff",border:"1px solid "+C.b1,borderRadius:11,padding:"9px 14px 9px 35px",color:"#0f172a",fontSize:12.5,outline:"none",fontFamily:"inherit",fontWeight:500,transition:"all .15s"}}
          onFocus={e=>{e.currentTarget.style.borderColor="#a855f7";e.currentTarget.style.boxShadow="0 0 0 3px rgba(168,85,247,.14)";}}
          onBlur={e=>{e.currentTarget.style.borderColor=C.b1;e.currentTarget.style.boxShadow="none";}}/>
      </div>
      <div style={{display:"flex",gap:5,flexWrap:"wrap",flex:1,minWidth:0}}>
        {[{id:"",label:"Todas",color:"#0f172a",icon:"lock"}].concat(CATS.filter(function(c){return _cnt(c.id)>0;})).map(c=>{
          const _on=catFilter===c.id;
          const _n=c.id?_cnt(c.id):items.length;
          return <button key={c.id||"all"} type="button" onClick={()=>setCatFilter(_on&&c.id?"":c.id)}
            style={{background:_on?c.color:"#fff",color:_on?"#fff":"#475569",border:"1px solid "+(_on?c.color:"#e2e8f0"),borderRadius:99,padding:"6px 11px 6px 9px",fontSize:11.5,fontWeight:_on?800:600,cursor:"pointer",fontFamily:"inherit",whiteSpace:"nowrap",transition:"all .15s",display:"inline-flex",alignItems:"center",gap:6}}>
            <span style={{display:"inline-flex",color:_on?"#fff":c.color}}><_PvIco n={c.icon} size={12}/></span>
            {c.label}
            <span style={{background:_on?"rgba(255,255,255,.22)":"#f1f5f9",color:_on?"#fff":"#94a3b8",borderRadius:99,padding:"0 6px",fontSize:10,fontWeight:800,lineHeight:1.6}}>{_n}</span>
          </button>;
        })}
      </div>
    </div>

    {/* ══ SEÇÕES ══ */}
    {loading
      ? <div style={{textAlign:"center",color:C.td,fontSize:13,padding:"40px"}}>Carregando…</div>
      : _total===0
        ? <div style={{background:"#fafbfc",border:"1px dashed #e2e8f0",borderRadius:16,padding:"48px 20px",textAlign:"center"}}>
            <div style={{color:"#334155",fontWeight:700,fontSize:14,marginBottom:5}}>{(search||catFilter)?"Nada encontrado":"Nenhuma senha cadastrada ainda"}</div>
            <div style={{color:"#94a3b8",fontSize:12}}>{(search||catFilter)?"Ajuste a busca ou o filtro.":"Clique em + Nova senha pra começar."}</div>
          </div>
        : _secoes.map(function(sec){
            const cat=sec.cat; const _col=!!collapsed[cat.id] && !search;
            return <div key={cat.id} style={{background:"#fff",border:"1px solid #eef0f3",borderRadius:16,overflow:"hidden",boxShadow:"0 1px 2px rgba(15,23,42,.03)"}}>
              {/* cabeçalho da seção — cor sólida */}
              <div onClick={function(){ setCollapsed(function(p){ const n=Object.assign({},p); n[cat.id]=!n[cat.id]; return n; }); }}
                style={{display:"flex",alignItems:"center",gap:13,padding:"14px 18px 14px 16px",background:"linear-gradient(120deg,"+cat.color+" 0%,"+_pvEscuro(cat.color)+" 100%)",color:"#fff",cursor:"pointer",userSelect:"none"}}>
                <div style={{width:34,height:34,borderRadius:11,background:"rgba(255,255,255,.16)",boxShadow:"inset 0 0 0 1px rgba(255,255,255,.24)",display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
                  <_PvIco n={cat.icon} size={16} color="#fff"/>
                </div>
                <div style={{flex:1,minWidth:0}}>
                  <div style={{fontWeight:800,fontSize:14.5,letterSpacing:-.35,lineHeight:1.2}}>{cat.label}</div>
                  <div style={{fontSize:11.5,opacity:.78,fontWeight:500,marginTop:2,letterSpacing:.1}}>{cat.desc}</div>
                </div>
                <span style={{background:"rgba(255,255,255,.18)",boxShadow:"inset 0 0 0 1px rgba(255,255,255,.22)",borderRadius:99,padding:"3px 11px",fontSize:11.5,fontWeight:800,fontVariantNumeric:"tabular-nums"}}>{sec.list.length}</span>
                <span style={{display:"inline-flex",transition:"transform .18s",transform:_col?"rotate(-90deg)":"none",opacity:.8}}><_PvIco n="chev" size={15} color="#fff"/></span>
              </div>
              {/* linhas compactas */}
              {!_col && <div style={{display:"grid",gridTemplateColumns:_mob?"1fr":"repeat(auto-fill,minmax(470px,1fr))",gap:"2px 10px",padding:"10px 12px 12px"}}>
                {sec.list.map(function(it){
                  const showPw=!!showPwd[it.id];
                  const _dom=String(it.url||"").replace(/^https?:\/\//,"").split("/")[0];
                  const _hasNotes=!!String(it.notes||"").trim();
                  const _nOpen=!!notesOpen[it.id];
                  return <div key={it.id} style={{display:"flex",flexDirection:"column",borderRadius:12,transition:"background .14s, box-shadow .14s"}}
                    onMouseEnter={function(e){e.currentTarget.style.background="#f7f8fb";e.currentTarget.style.boxShadow="inset 0 0 0 1px #eceff4";}}
                    onMouseLeave={function(e){e.currentTarget.style.background="transparent";e.currentTarget.style.boxShadow="none";}}>
                    <div style={{display:"flex",alignItems:"center",gap:13,padding:"10px 11px",minHeight:58}}>
                      <_PvAvatar it={it} cat={cat}/>
                      {/* título + login */}
                      <div style={{flex:"1 1 0",minWidth:0}}>
                        <div style={{display:"flex",alignItems:"center",gap:6,minWidth:0}}>
                          <span style={{color:"#0f172a",fontWeight:700,fontSize:13.5,letterSpacing:-.25,lineHeight:1.25,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{it.label}</span>
                          {it.url && <a href={it.url} target="_blank" rel="noopener noreferrer" title={it.url} onClick={function(e){e.stopPropagation();}}
                            style={{color:"#94a3b8",display:"inline-flex",flexShrink:0}} onMouseEnter={function(e){e.currentTarget.style.color=cat.color;}} onMouseLeave={function(e){e.currentTarget.style.color="#94a3b8";}}><_PvIco n="ext" size={11}/></a>}
                        </div>
                        <div style={{display:"flex",alignItems:"center",gap:5,minWidth:0,marginTop:3}}>
                          <span style={{color:it.username?"#7b8794":"#cbd5e1",fontSize:11,fontFamily:"ui-monospace,SFMono-Regular,Menlo,monospace",letterSpacing:-.1,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{it.username||"sem login"}</span>
                          {it.username && <button type="button" title="Copiar login" onClick={function(){_copy(it.username,"Login");}}
                            style={{background:"transparent",border:"none",cursor:"pointer",padding:2,color:"#cbd5e1",display:"inline-flex",flexShrink:0}}
                            onMouseEnter={function(e){e.currentTarget.style.color=cat.color;}} onMouseLeave={function(e){e.currentTarget.style.color="#cbd5e1";}}><_PvIco n="copy" size={10}/></button>}
                        </div>
                      </div>
                      {/* senha */}
                      <div style={{display:"flex",alignItems:"center",gap:3,background:"#f6f8fa",border:"1px solid #e9edf2",borderRadius:10,padding:"5px 5px 5px 12px",flexShrink:0,maxWidth:_mob?150:215}}>
                        <span style={{color:it.password?"#334155":"#cbd5e1",fontSize:11.5,fontFamily:"ui-monospace,SFMono-Regular,Menlo,monospace",fontWeight:500,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap",minWidth:showPw?0:64,letterSpacing:showPw?"normal":".18em"}}>
                          {it.password?(showPw?it.password:"••••••••"):"—"}
                        </span>
                        {it.password && _iconBtn(showPw?"Ocultar":"Mostrar", function(){ setShowPwd(function(p){ const n=Object.assign({},p); n[it.id]=!showPw; return n; }); }, showPw?"eyeoff":"eye", "#0f172a")}
                        {it.password && _iconBtn("Copiar senha", function(){_copy(it.password,"Senha");}, "copy", cat.color)}
                      </div>
                      {/* ações */}
                      <div style={{display:"inline-flex",alignItems:"center",flexShrink:0}}>
                        {_hasNotes && _iconBtn(_nOpen?"Esconder observações":"Ver observações", function(){ setNotesOpen(function(p){ const n=Object.assign({},p); n[it.id]=!_nOpen; return n; }); }, "note", "#f59e0b")}
                        {_iconBtn("Editar", function(){_edit(it);}, "edit", "#7c3aed")}
                        {_iconBtn("Excluir", function(){_delete(it);}, "trash", "#dc2626")}
                      </div>
                    </div>
                    {_nOpen && _hasNotes && <div style={{margin:"0 11px 10px 58px",background:"#fffbeb",border:"1px solid #fde68a",borderRadius:9,padding:"7px 10px",fontSize:11.5,color:"#78350f",lineHeight:1.5,whiteSpace:"pre-wrap"}}>
                      {it.notes}
                      <div style={{color:"#b45309",fontSize:10,marginTop:4,opacity:.8}}>{it.updated_at?"Atualizado em "+_dt(it.updated_at):""}{it.author_name?" · "+it.author_name:""}</div>
                    </div>}
                  </div>;
                })}
              </div>}
            </div>;
          })
    }

    {/* Modal Novo/Editar */}
    {editing && (()=>{
      const _clientesAtivos = CLIENTS.filter(c=>c.status!=="interno");
      return <div style={{position:"fixed",inset:0,background:"rgba(15,23,42,0.7)",zIndex:300,display:"flex",alignItems:"center",justifyContent:"center",padding:16}} onClick={_close}>
        <div onClick={e=>e.stopPropagation()} style={{background:C.card,borderRadius:16,width:"100%",maxWidth:560,boxShadow:"0 20px 60px rgba(0,0,0,.25)",overflow:"hidden"}}>
          <div style={{background:"linear-gradient(135deg,"+C.a+","+C.aD+")",padding:"16px 22px",color:"#fff"}}>
            <div style={{fontSize:15,fontWeight:800,letterSpacing:-.2}}>{editing.id?"Editar senha":"Nova senha"}</div>
            <div style={{fontSize:11,opacity:.85,marginTop:1}}>Anote uma credencial pra consulta futura</div>
          </div>
          <div style={{padding:"16px 22px",display:"flex",flexDirection:"column",gap:11,maxHeight:"70vh",overflowY:"auto"}}>
            {/* Seção */}
            <div>
              <div style={{color:C.td,fontSize:10,fontWeight:700,textTransform:"uppercase",letterSpacing:.6,marginBottom:5}}>Seção</div>
              <div style={{display:"flex",gap:5,flexWrap:"wrap"}}>
                {CATS.map(c=>{
                  const _on=(editing.category||"outro")===c.id;
                  return <button key={c.id} type="button" onClick={()=>setEditing(p=>({...p,category:c.id}))}
                    style={{background:_on?c.color:"#fff",color:_on?"#fff":c.color,border:"1px solid "+(_on?c.color:c.color+"55"),borderRadius:99,padding:"5px 11px 5px 8px",fontSize:11.5,fontWeight:700,cursor:"pointer",fontFamily:"inherit",display:"inline-flex",alignItems:"center",gap:5}}>
                    <_PvIco n={c.icon} size={11}/>{c.label}</button>;
                })}
              </div>
            </div>
            {/* Título */}
            <div>
              <div style={{color:C.td,fontSize:10,fontWeight:700,textTransform:"uppercase",letterSpacing:.6,marginBottom:5}}>Título *</div>
              <input value={editing.label} onChange={e=>setEditing(p=>({...p,label:e.target.value}))} placeholder="Ex: Asana — Gustavo"
                style={{width:"100%",background:C.s1,border:"1px solid "+C.b1,borderRadius:8,padding:"8px 11px",fontSize:13,color:C.tx,outline:"none",boxSizing:"border-box",fontFamily:"inherit"}}/>
            </div>
            {/* Cliente */}
            <div>
              <div style={{color:C.td,fontSize:10,fontWeight:700,textTransform:"uppercase",letterSpacing:.6,marginBottom:5}}>Cliente vinculado (opcional)</div>
              <select value={editing.client_id||""} onChange={e=>setEditing(p=>({...p,client_id:e.target.value}))}
                style={{width:"100%",background:C.s1,border:"1px solid "+C.b1,borderRadius:8,padding:"8px 11px",fontSize:13,color:C.tx,outline:"none",boxSizing:"border-box",fontFamily:"inherit",cursor:"pointer"}}>
                <option value="">— nenhum —</option>
                {_clientesAtivos.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}
              </select>
            </div>
            {/* Usuário + Senha */}
            <div style={{display:"grid",gridTemplateColumns:_pxMob()?"1fr":"1fr 1fr",gap:10}}>
              <div>
                <div style={{color:C.td,fontSize:10,fontWeight:700,textTransform:"uppercase",letterSpacing:.6,marginBottom:5}}>Usuário/Email</div>
                <input value={editing.username||""} onChange={e=>setEditing(p=>({...p,username:e.target.value}))} placeholder="exemplo@cliente.com"
                  style={{width:"100%",background:C.s1,border:"1px solid "+C.b1,borderRadius:8,padding:"8px 11px",fontSize:12.5,color:C.tx,outline:"none",boxSizing:"border-box",fontFamily:"monospace"}}/>
              </div>
              <div>
                <div style={{color:C.td,fontSize:10,fontWeight:700,textTransform:"uppercase",letterSpacing:.6,marginBottom:5}}>Senha</div>
                <input type="text" value={editing.password||""} onChange={e=>setEditing(p=>({...p,password:e.target.value}))} placeholder="senha aqui"
                  style={{width:"100%",background:C.s1,border:"1px solid "+C.b1,borderRadius:8,padding:"8px 11px",fontSize:12.5,color:C.tx,outline:"none",boxSizing:"border-box",fontFamily:"monospace"}}/>
              </div>
            </div>
            {/* URL */}
            <div>
              <div style={{color:C.td,fontSize:10,fontWeight:700,textTransform:"uppercase",letterSpacing:.6,marginBottom:5}}>URL (opcional — define o ícone)</div>
              <input value={editing.url||""} onChange={e=>setEditing(p=>({...p,url:e.target.value}))} placeholder="https://..."
                style={{width:"100%",background:C.s1,border:"1px solid "+C.b1,borderRadius:8,padding:"8px 11px",fontSize:12.5,color:C.tx,outline:"none",boxSizing:"border-box",fontFamily:"inherit"}}/>
            </div>
            {/* Notas */}
            <div>
              <div style={{color:C.td,fontSize:10,fontWeight:700,textTransform:"uppercase",letterSpacing:.6,marginBottom:5}}>Observações</div>
              <textarea value={editing.notes||""} onChange={e=>setEditing(p=>({...p,notes:e.target.value}))} placeholder="Observações adicionais..."
                rows={3} style={{width:"100%",background:C.s1,border:"1px solid "+C.b1,borderRadius:8,padding:"8px 11px",fontSize:12.5,color:C.tx,outline:"none",boxSizing:"border-box",fontFamily:"inherit",resize:"vertical",lineHeight:1.5}}/>
            </div>
            {/* Botões */}
            <div style={{display:"flex",justifyContent:"flex-end",gap:8,paddingTop:6}}>
              <button onClick={_close}
                style={{background:"transparent",border:"1px solid "+C.b1,borderRadius:9,padding:"8px 18px",color:C.ts,fontSize:12,fontWeight:700,cursor:"pointer",fontFamily:"inherit"}}>Cancelar</button>
              <button onClick={_save}
                style={{background:"linear-gradient(135deg,"+C.a+","+C.aD+")",border:"none",borderRadius:9,padding:"8px 22px",color:"#fff",fontSize:12,fontWeight:800,cursor:"pointer",fontFamily:"inherit",boxShadow:"0 4px 14px "+C.a+"55"}}>
                {editing.id?"Salvar":"Adicionar"}
              </button>
            </div>
          </div>
        </div>
      </div>;
    })()}
  </div>;
}

/* ─── STORAGE MANAGER ─────────────────────────── */
function StorageManager({tasks}){
  const [scanning,setScanning]=useState(false);
  const [orphans,setOrphans]=useState(null); // null=não escaneado, []=escaneado
  const [deleting,setDeleting]=useState(false);
  const [log,setLog]=useState([]);

  const scan=async()=>{
    setScanning(true);
    setOrphans(null);
    setLog([]);
    try{
      const sb=window._sb;

      // 1. Coletar todos os storagePaths válidos de tasks ativos + lixeira
      const validPaths=new Set();
      (tasks||[]).forEach(t=>{
        (t.files||[]).forEach(f=>{
          if(f.storagePath)validPaths.add(f.storagePath);
        });
      });

      // 2. Listar arquivos no bucket — pasta tasks/
      const{data:items,error}=await sb.storage.from("agency-files").list("tasks",{limit:1000,offset:0});
      if(error)throw error;

      // 3. Para cada subpasta (id do task), listar arquivos
      const found=[];
      for(const folder of (items||[])){
        const{data:files}=await sb.storage.from("agency-files").list(`tasks/${folder.name}`,{limit:100});
        for(const file of (files||[])){
          const path=`tasks/${folder.name}/${file.name}`;
          if(!validPaths.has(path)){
            found.push({path,name:file.name,folder:folder.name,size:file.metadata?.size||0});
          }
        }
      }
      setOrphans(found);
    }catch(e){
      setLog([`Erro ao escanear: ${e.message}`]);
    }
    setScanning(false);
  };

  const deleteOrphans=async()=>{
    if(!orphans||orphans.length===0)return;
    setDeleting(true);
    const newLog=[];
    try{
      const sb=window._sb;
      const paths=orphans.map(o=>o.path);
      const{error}=await sb.storage.from("agency-files").remove(paths);
      if(error)throw error;
      newLog.push(`✅ ${paths.length} arquivo(s) deletado(s) com sucesso.`);
      setOrphans([]);
    }catch(e){
      newLog.push(`❌ Erro ao deletar: ${e.message}`);
    }
    setLog(newLog);
    setDeleting(false);
  };

  const fmtSize=b=>b>1048576?(b/1048576).toFixed(1)+"MB":b>1024?(b/1024).toFixed(0)+"KB":b+"B";

  return <div style={{display:"flex",flexDirection:"column",gap:16}}>
    {/* Header */}
    <div style={{background:C.card,borderRadius:16,border:"1px solid "+C.b1,padding:"18px 20px"}}>
      <div style={{color:C.tx,fontWeight:800,fontSize:16,marginBottom:4}}>🗂 Gerenciador de Storage</div>
      <div style={{color:C.ts,fontSize:12}}>Escaneia o bucket <strong>agency-files</strong> e identifica arquivos órfãos — arquivos que não pertencem a nenhum cartão ativo ou na lixeira.</div>
    </div>

    {/* Aviso */}
    <div style={{background:C.yw+"18",border:"1px solid "+C.yw+"44",borderRadius:12,padding:"12px 16px",display:"flex",gap:10,alignItems:"flex-start"}}>
      <span style={{fontSize:18}}>⚠️</span>
      <div style={{color:C.ts,fontSize:12}}>
        <strong style={{color:C.tx}}>Atenção:</strong> Revise a lista antes de deletar. Esta ação é <strong>irreversível</strong>. Arquivos de cartões na lixeira são preservados.
      </div>
    </div>

    {/* Botão escanear */}
    <button onClick={scan} disabled={scanning||deleting}
      style={{background:C.a,color:"#fff",border:"none",borderRadius:12,padding:"12px 24px",fontWeight:700,fontSize:14,cursor:scanning?"wait":"pointer",opacity:scanning?0.7:1,display:"flex",alignItems:"center",justifyContent:"center",gap:8}}>
      {scanning?"⏳ Escaneando bucket...":"🔍 Escanear Storage"}
    </button>

    {/* Resultado */}
    {orphans!==null&&<div style={{background:C.card,borderRadius:14,border:"1px solid "+C.b1,overflow:"hidden"}}>
      <div style={{padding:"14px 18px",borderBottom:"1px solid "+C.b1,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
        <div>
          <span style={{color:C.tx,fontWeight:700,fontSize:14}}>
            {orphans.length===0?"✅ Nenhum arquivo órfão encontrado":`🗑 ${orphans.length} arquivo(s) órfão(s) encontrado(s)`}
          </span>
          {orphans.length>0&&<div style={{color:C.ts,fontSize:11,marginTop:2}}>
            Total: {fmtSize(orphans.reduce((s,o)=>s+o.size,0))}
          </div>}
        </div>
        {orphans.length>0&&<button onClick={async()=>{if(await pixelsConfirm(`Deletar permanentemente ${orphans.length} arquivo(s) órfão(s)? Esta ação não pode ser desfeita.`,{okText:"Deletar",danger:true}))deleteOrphans();}}
          disabled={deleting}
          style={{background:C.rd,color:"#fff",border:"none",borderRadius:9,padding:"8px 18px",fontWeight:700,fontSize:12,cursor:deleting?"wait":"pointer",opacity:deleting?0.7:1}}>
          {deleting?"⏳ Deletando...":"🗑 Deletar todos os órfãos"}
        </button>}
      </div>

      {orphans.length>0&&<div style={{maxHeight:320,overflowY:"auto"}}>
        {orphans.map((o,i)=>(
          <div key={o.path} style={{padding:"10px 18px",borderBottom:i<orphans.length-1?"1px solid "+C.b1+"44":"none",display:"flex",justifyContent:"space-between",alignItems:"center",gap:12}}>
            <div style={{minWidth:0}}>
              <div style={{color:C.tx,fontSize:12,fontWeight:600,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{o.name}</div>
              <div style={{color:C.td,fontSize:10,marginTop:2}}>tasks/{o.folder}/</div>
            </div>
            <span style={{color:C.ts,fontSize:11,flexShrink:0}}>{fmtSize(o.size)}</span>
          </div>
        ))}
      </div>}
    </div>}

    {/* Log */}
    {log.length>0&&<div style={{background:C.s1,borderRadius:10,padding:"12px 16px"}}>
      {log.map((l,i)=><div key={i} style={{color:C.ts,fontSize:12}}>{l}</div>)}
    </div>}
  </div>;
}


/* ── NÍVEL DO ACESSO NO PORTAL (11/09/2026) ─────────────────────────────
   Administrador = portal inteiro · Comercial = só a aba Performance (funil + vendas/ROI).
   Fica em profiles.permissions.papel ("admin" | "comercial"; vazio/"dono" = admin).
   Quem grava é a Edge Function acessos-portal (só sócio). O portal esconde as abas
   (13_novidades.jsx, _soPerformance) e o banco trava de verdade
   (_pixels_client_pode('performance'/'portal') nas policies).                     */
const PORTAL_NIVEIS=[
  {id:"admin",     label:"Administrador", desc:"Vê o portal inteiro",                     cor:"#7c3aed"},
  {id:"comercial", label:"Comercial",     desc:"Só Performance: registra leads e vendas", cor:"#0891b2"},
];
function _portalNivelDe(u){
  const p=(u&&u.permissions)||{};
  return String(p.papel||"").toLowerCase()==="comercial"?"comercial":"admin";
}
async function _portalNivelSalvar(userId,papel){
  const sb=window._sb;
  await sb.auth.refreshSession().catch(()=>{});
  const{data:sess}=await sb.auth.getSession();
  const tok=sess&&sess.session&&sess.session.access_token;
  if(!tok) throw new Error("Sua sessão expirou. Faça logout e login de novo.");
  const url=(typeof import.meta!=="undefined"?import.meta.env.VITE_SUPABASE_URL:"")||"https://jffvoojcskwumnphsedq.supabase.co";
  const res=await fetch(url+"/functions/v1/acessos-portal",{
    method:"POST",
    headers:{"Authorization":"Bearer "+tok,"Content-Type":"application/json"},
    body:JSON.stringify({acao:"atualizar",id:userId,papel:papel}),
  });
  const data=await res.json().catch(()=>({}));
  if(!res.ok||data.error) throw new Error(data.error||("Erro "+res.status));
  return data;
}
function AcessoNivelPortal({user,podeEditar,onSalvo}){
  const [salvando,setSalvando]=useState(false);
  const atual=_portalNivelDe(user);
  const trocar=async(id)=>{
    if(!podeEditar||salvando||id===atual)return;
    setSalvando(true);
    try{
      await _portalNivelSalvar(user.id,id);
      if(onSalvo)onSalvo(id);
      if(typeof pixelsToast!=="undefined")pixelsToast.success((user.name||"Acesso")+" agora é "+(id==="comercial"?"Comercial":"Administrador")+".",2500);
    }catch(e){
      if(typeof pixelsToast!=="undefined")pixelsToast.error("Não consegui trocar o nível: "+((e&&e.message)||e));
    }finally{ setSalvando(false); }
  };
  return <div style={{display:"flex",alignItems:"center",gap:8,flexWrap:"wrap"}}>
    <span style={{color:"#94a3b8",fontSize:10,fontWeight:800,textTransform:"uppercase",letterSpacing:.6}}>Nível</span>
    <div role="radiogroup" aria-label="Nível do acesso" style={{display:"inline-flex",background:"#f1f5f9",borderRadius:9,padding:2,gap:2,opacity:salvando?.6:1}}>
      {PORTAL_NIVEIS.map(n=>{
        const on=atual===n.id;
        const off=!podeEditar||salvando;
        return <button key={n.id} type="button" role="radio" aria-checked={on} disabled={off} title={n.desc}
          onClick={()=>trocar(n.id)}
          style={{background:on?"#fff":"transparent",color:on?n.cor:"#64748b",border:"none",borderRadius:7,padding:"5px 11px",fontSize:11.5,fontWeight:on?800:600,cursor:off?"default":"pointer",boxShadow:on?"0 1px 3px rgba(15,23,42,.12)":"none",fontFamily:"inherit",transition:"all .12s"}}>
          {n.label}
        </button>;
      })}
    </div>
    <span style={{color:"#94a3b8",fontSize:11,fontWeight:500}}>{salvando?"salvando…":(atual==="comercial"?"só Performance":"portal inteiro")}</span>
  </div>;
}

