  const rotulo=<span style={{fontSize:11.5,color:ADS.muted,whiteSpace:"nowrap",background:ADS.surface2,borderRadius:8,padding:"6px 10px",fontFeatureSettings:"'tnum'"}}><b style={{color:ADS.ink2,fontWeight:700}}>{P.ini===P.fim?_adsFmtD(P.ini):_adsFmtD(P.ini)+" – "+_adsFmtD(P.fim)}</b><span> · vs. {P.prevIni===P.prevFim?_adsFmtD(P.prevIni):_adsFmtD(P.prevIni)+" – "+_adsFmtD(P.prevFim)}</span></span>;
