// Helpers globais de vendas pontuais (compartilhados com PageGestaoFinanceiro)
const _VP_LS_KEY = "pixels-vendas-pontuais";
function _vpLoad(){
  try{ const s=localStorage.getItem(_VP_LS_KEY); if(s) return JSON.parse(s); }catch(_){}
  return [];
}
function _vpSave(arr){
  try{ localStorage.setItem(_VP_LS_KEY, JSON.stringify(arr)); }catch(_){}
  if(typeof window!=="undefined") window.dispatchEvent(new CustomEvent("pixels-vendas-pontuais-changed"));
}
async function _vpSyncSupabase(arr){
  const sb=window._sb; if(!sb) return {ok:false, err:"Supabase indisponivel - salvou so local"};
  try{
    // Table: vendas_pontuais (id, cliente_id, descricao, valor, mes_ref, data_venda, status, anexos, bioter_unit, created_at, updated_by)
    const payload = arr.map(function(v){return Object.assign({},v,{updated_by:(typeof CURRENT_USER!=="undefined"?CURRENT_USER.name:"system")});});
    const {error} = await sb.from("vendas_pontuais").upsert(payload,{onConflict:"id"});
    if(error) return {ok:false, err:error.message||"Erro Supabase desconhecido"};
    return {ok:true};
  }catch(e){
    return {ok:false, err:(e && e.message)||"Erro de rede"};
  }
}

