// Markers de conteúdo OBSOLETO: se o cache/Supabase tem essas strings, descarta
// e prefere o PB_SEED (que é a fonte autoritativa atualizada).
// Cada item evita que conteúdo legado fantasma sobrescreva o seed novo.
const _PB_STALE_MARKERS = [
  "clínica veterinária", "clinica veterinaria",
  "tutor-animal", "tutor animal",
  "pequenos e médios animais", "pequenos e medios animais",
  "(em construção", "(em construcao",
];
function _pbIsStaleText(text){
  if(!text || typeof text !== "string") return false;
  const lo = text.toLowerCase();
  return _PB_STALE_MARKERS.some(m => lo.indexOf(m) >= 0);
}
// Merge inteligente entre PB_SEED (seed) e cache/remote (override).
// Pra cada campo crítico: se o override está vazio OU contém marker obsoleto,
// mantém o seed. Senão, deixa o override (edição legítima do user) prevalecer.
function _pbMergePreferSeed(seed, override){
  if(!seed && !override) return null;
  if(!seed) return override;
  if(!override) return JSON.parse(JSON.stringify(seed));
  const out = Object.assign({}, seed, override);
  // Campos string de topo
  ["sobre","comunicacao","descricaoCurta"].forEach(function(k){
    if(_pbIsStaleText(override[k]) || !override[k]) out[k] = seed[k] || override[k] || "";
  });
  // Arrays de topo: prefere seed quando override tá vazio
  ["pilares","chamadasAprovadas","chamadasProibidas"].forEach(function(k){
    const ov = override[k];
    if(!Array.isArray(ov) || ov.length===0){
      if(Array.isArray(seed[k])) out[k] = seed[k].slice();
    }
  });
  // Áreas (design/video/midia/social)
  ["design","video","midia","social"].forEach(function(area){
    const sA = seed[area] || {};
    const oA = override[area] || {};
    if(!seed[area] && !override[area]) return;
    const merged = Object.assign({}, sA, oA);
    if(_pbIsStaleText(oA.orientacoes) || !oA.orientacoes) merged.orientacoes = sA.orientacoes || oA.orientacoes || "";
    if(!Array.isArray(oA.checklist) || oA.checklist.length===0){
      if(Array.isArray(sA.checklist)) merged.checklist = sA.checklist.slice();
    }
    out[area] = merged;
  });
  return out;
}

function _pbInitFromCache(){
  try{
    const cache = _pbLoadCache();
    const base = JSON.parse(JSON.stringify(PB_SEED));
    if(cache && typeof cache === "object" && !Array.isArray(cache)){
      Object.keys(cache).forEach(k => {
        if(cache[k] && typeof cache[k]==="object"){
          // Antes era: base[k] = cache[k] (sobrescrevia PB_SEED sem dó)
          // Agora: merge inteligente que preserva PB_SEED quando cache é obsoleto
          base[k] = _pbMergePreferSeed(base[k], cache[k]);
        }
      });
    }
    _pbSaveCache(base);
    return base;
  }catch(e){
    console.warn("[_pbInitFromCache erro]",e);
    return JSON.parse(JSON.stringify(PB_SEED));
  }
}

// Hook: busca playbooks do Supabase + realtime sync
function _usePlaybooksStore(){
  const [store, setStore] = useState(()=>_pbInitFromCache());

  useEffect(()=>{
    let active = true;
    (async ()=>{
      const remote = await _pbLoadFromSupabase();
      if(!active || !remote) return;
      setStore(prev => {
        const next = Object.assign({}, prev);
        // Merge inteligente: PB_SEED prevalece quando remote contém conteúdo obsoleto
        Object.keys(remote).forEach(k => {
          const seedK = PB_SEED[k];
          next[k] = seedK ? _pbMergePreferSeed(seedK, remote[k]) : remote[k];
        });
        _pbSaveCache(next);
        return next;
      });
    })();
    return ()=>{ active = false; };
  }, []);

  useEffect(()=>{
    if(!window._sb) return undefined;
    const ch = window._sb.channel("playbooks-sync")
      .on("postgres_changes", {event:"*", schema:"public", table:"playbooks"}, (payload)=>{
        if(payload.eventType === "DELETE"){
          const cid = payload.old?.client_id;
          if(cid){
            setStore(prev => {
              const next = Object.assign({}, prev);
              delete next[cid];
              _pbSaveCache(next);
              return next;
            });
          }
          return;
        }
        const row = payload.new;
        if(!row?.client_id) return;
        setStore(prev => {
          const seedK = PB_SEED[row.client_id];
          const merged = seedK ? _pbMergePreferSeed(seedK, row.data||{}) : (row.data||{});
          const next = Object.assign({}, prev, {[row.client_id]: merged});
          _pbSaveCache(next);
          return next;
        });
      })
      .subscribe();
    return ()=>{ try{ window._sb.removeChannel(ch); }catch(_){} };
  }, []);

  const updateClient = useCallback(async (clientId, mutFn)=>{
    let newData = null;
    setStore(prev => {
      const cur = prev[clientId] || {};
      const updated = mutFn(JSON.parse(JSON.stringify(cur)));
      newData = updated;
      const next = Object.assign({}, prev, {[clientId]: updated});
      _pbSaveCache(next);
      return next;
    });
    if(newData){
      const ok = await _pbSaveClientToSupabase(clientId, newData);
      if(!ok && typeof pixelsToast!=="undefined") pixelsToast.warning("Salvo só localmente — sem conexão com Supabase.");
    }
  }, []);

  return [store, updateClient];
}

// ── Smooth scroll helper ──
function _pbScrollTo(id){
  try{ const el=document.getElementById(id); if(el) el.scrollIntoView({behavior:"smooth", block:"start"}); }catch(_){}
}


/* ─── _pbProdutoUploadImg — upload de imagem de produto direto pro Supabase Storage.
   Click sincrono (no handler do botão) → file picker → upload → atualiza prod.imgUrl. */
/* ─── _pbTemplateUploadImg — upload de imagem de Template direto pro Supabase Storage.
   Mesmo padrão do produto: click sincrono (gesture context) → file picker → upload → seta imgUrl. */
function _pbTemplateUploadImg(updFn){
  try{
    const inp = document.createElement("input");
    inp.type = "file";
    inp.accept = "image/*";
    inp.style.display = "none";
    inp.onchange = async function(e){
      const file = e.target.files && e.target.files[0];
      if(!file) return;
      try{
        if(!window._sb) throw new Error("Supabase indisponível");
        const ext = (file.name.split(".").pop()||"png").replace(/[^a-zA-Z0-9]/g,"").toLowerCase();
        const rnd = Math.random().toString(36).slice(2,11);
        const path = "playbook-templates/"+Date.now()+"-"+rnd+"."+ext;
        if(typeof pixelsToast!=="undefined") pixelsToast.info("Enviando imagem...",1500);
        const {error} = await window._sb.storage.from("agency-files").upload(path, file, {cacheControl:"3600", upsert:false});
        if(error) throw error;
        const {data:pub} = window._sb.storage.from("agency-files").getPublicUrl(path);
        if(pub && pub.publicUrl){
          updFn({imgUrl: pub.publicUrl});
          if(typeof pixelsToast!=="undefined") pixelsToast.success("Imagem subida!",2000);
        }
      }catch(err){
        console.warn("[upload template]", err);
        if(typeof pixelsToast!=="undefined") pixelsToast.error("Erro: "+(err && err.message||"desconhecido"));
      }
    };
    document.body.appendChild(inp);
    inp.click();
    setTimeout(()=>{try{document.body.removeChild(inp);}catch(_){}}, 60000);
  }catch(err){
    console.warn(err);
  }
}

function _pbProdutoUploadImg(pi, updFn){
  try{
    const inp = document.createElement("input");
    inp.type = "file";
    inp.accept = "image/*";
    inp.style.display = "none";
    inp.onchange = async function(e){
      const file = e.target.files && e.target.files[0];
      if(!file) return;
      try{
        if(!window._sb) throw new Error("Supabase indisponível");
        const ext = (file.name.split(".").pop()||"png").replace(/[^a-zA-Z0-9]/g,"").toLowerCase();
        const rnd = Math.random().toString(36).slice(2,11);
        const path = "playbook-produtos/"+Date.now()+"-"+rnd+"."+ext;
        const {error} = await window._sb.storage.from("agency-files").upload(path, file, {cacheControl:"3600", upsert:false});
        if(error) throw error;
        const {data:pub} = window._sb.storage.from("agency-files").getPublicUrl(path);
        if(pub && pub.publicUrl){
          updFn(pi, {imgUrl: pub.publicUrl});
          if(typeof pixelsToast!=="undefined") pixelsToast.success("Imagem subida.",1500);
        }
      }catch(err){
        console.warn("[upload produto]", err);
        if(typeof pixelsToast!=="undefined") pixelsToast.error("Erro: "+(err && err.message||"desconhecido"));
      }
    };
    document.body.appendChild(inp);
    inp.click();
    setTimeout(()=>{try{document.body.removeChild(inp);}catch(_){}}, 60000);
  }catch(err){
    console.warn(err);
  }
}

// ═══════════════════════════════════════════════════════════════
//  PagePlaybooks — Estratégia > Playbooks
// ═══════════════════════════════════════════════════════════════
// ═══ CADEIRAS (09/09/2026) — o playbook volta a ser separado por função ═══
// Os DADOS continuam unificados (um playbook por cliente, gravado na raiz); o que muda
// é a VISÃO: cada cadeira enxerga só os blocos que precisa. Admin/Hellen alternam entre
// as cadeiras por abas. Quem tem uma cadeira só (designer, editor, social, Erick) já
// cai direto nela, sem abas.
const PB_CADEIRAS = [
  {id:"estrategia", label:"Estratégia",   icon:"target",      color:"#7c3aed",
   blocos:null}, // null = TODOS os blocos (a estrategista vê o playbook inteiro)
  {id:"social", label:"Social media",     icon:"users",       color:"#ec4899",
   blocos:["pb-sobre","pb-comunicacao","pb-marcacoes","pb-social","pb-chamadas","pb-contatos","pb-produtos","pb-briefing-auto","pb-checklist"]},
  {id:"design", label:"Design",           icon:"image",       color:"#9F43F6",
   blocos:["pb-sobre","pb-designer","pb-equipe","pb-orientacoes-visuais","pb-templates","pb-chamadas","pb-contatos","pb-produtos","pb-checklist"]},
  {id:"video",  label:"Edição de vídeo",  icon:"play",        color:"#0ea5e9",
   blocos:["pb-sobre","pb-time","pb-processos","pb-equipe","pb-orientacoes-visuais","pb-contatos","pb-produtos","pb-checklist"]},
  {id:"midia",  label:"Gestão de mídia",  icon:"trending-up", color:"#16a34a",
   blocos:["pb-sobre","pb-comunicacao","pb-produtos","pb-chamadas","pb-contatos","pb-briefing-auto","pb-checklist"]},
];
let _PB_CADEIRA_ATUAL = null; // id da cadeira em exibição (null = tudo)
function _pbBlocoVisivel(id){
  if(!_PB_CADEIRA_ATUAL) return true;
  const c = PB_CADEIRAS.find(function(x){ return x.id===_PB_CADEIRA_ATUAL; });
  return !c || !c.blocos || c.blocos.indexOf(id)>=0;
}
function _pbCadeirasDoUsuario(u){
  const isAdmin = u.level===1 || u.id==="ellen";
  if(isAdmin) return PB_CADEIRAS.slice();
  const ids = [];
  if(u.dash==="coordinator") ids.push("estrategia"); // estrategista: playbook inteiro
  if(u.dash==="social") ids.push("social");
  if(u.dash==="designer") ids.push("design");
  if(u.dash==="editor") ids.push("video");
  if(u.id==="erick" || u.dash==="gestor") ids.push("midia");
  return PB_CADEIRAS.filter(function(c){ return ids.indexOf(c.id)>=0; });
}

function PagePlaybooks({isMob, perms, viewingAs}){
  const effectiveUser = viewingAs ? (TEAM.find(u=>u.id===viewingAs)||CURRENT_USER) : CURRENT_USER;
  const isSocio = effectiveUser.level === 1;
  const isHellen = effectiveUser.id === "ellen";
  const isAdmin = isSocio || isHellen;
  const isFreelaDesign = effectiveUser.dash === "designer";
  const isFreelaVideo  = effectiveUser.dash === "editor";
  const isFreelaMidia  = effectiveUser.id === "erick";
  const isSocial       = effectiveUser.dash === "social"; // social media (Luiza e futuras contratações)

  // UNIFICADO: sem sub-abas de área. Um playbook por cliente com tudo junto.
  const isEstrategista = effectiveUser.dash === "coordinator";
  const _accessOK = isAdmin || isFreelaDesign || isFreelaVideo || isFreelaMidia || isSocial || isEstrategista;
  const _cadeiras = _pbCadeirasDoUsuario(effectiveUser);
  const [cadeira, setCadeira] = useState(function(){
    try{ const _s=localStorage.getItem("pixels-pb-cadeira"); if(_s&&_cadeiras.some(function(c){return c.id===_s;})) return _s; }catch(_){}
    return _cadeiras[0] ? _cadeiras[0].id : null;
  });
  useEffect(function(){ try{ if(cadeira) localStorage.setItem("pixels-pb-cadeira",cadeira); }catch(_){} },[cadeira]);
  const _cadeiraCfg = _cadeiras.find(function(c){return c.id===cadeira;}) || _cadeiras[0] || null;
  _PB_CADEIRA_ATUAL = _cadeiraCfg ? _cadeiraCfg.id : null;
  const [openClient, setOpenClient] = useState(null);
  const [search, setSearch] = useState("");
  const [store, _updateClient] = _usePlaybooksStore();
  // editMode SEMPRE true pra admins — tudo editável inline com auto-save
  const [editMode, setEditMode] = useState(true);
  // Re-render quando clientes dinâmicos carregarem do Supabase (evita Agroforte sumir no F5)
  const [_clientsTick, setClientsTick] = useState(0);
  useEffect(function(){
    // Dispara reload do Supabase caso ainda nao tenha rodado
    if(typeof window.loadDynamicClientsFromSupabase === "function"){
      try{ window.loadDynamicClientsFromSupabase().catch(function(){}); }catch(_){}
    }
    function _bump(){ setClientsTick(function(t){return t+1;}); }
    window.addEventListener("pixels:clients-registry-updated", _bump);
    return function(){ window.removeEventListener("pixels:clients-registry-updated", _bump); };
  }, []);

  if(!_accessOK){
    return <div style={{padding:24,fontFamily:PB_INTER,color:PB_MUTE}}>Você não tem acesso aos playbooks.</div>;
  }

  // ── Drawer detalhe ──
  if(openClient){
    const clCfg = (CLIENTS||[]).find(c=>c.id===openClient) || {id:openClient,name:openClient};
    const data = store[openClient] || {};
    // Dados unificados (area="all"); a cadeira só filtra os blocos visíveis
    const areaCfg = _cadeiraCfg ? {label:_cadeiraCfg.label, icon:_cadeiraCfg.icon, color:_cadeiraCfg.color} : {label:"Playbook", icon:"file-text", color:PB_PURPLE_DK};
    return <PlaybookDetalhe
      cl={clCfg} area={"all"} areaCfg={areaCfg} data={data}
      cadeiras={_cadeiras} cadeira={_cadeiraCfg?_cadeiraCfg.id:null} onSwitchCadeira={setCadeira}
      isAdmin={isAdmin} editMode={editMode} setEditMode={setEditMode}
      onBack={()=>{setOpenClient(null);}}
      onSwitchClient={(newId)=>{ setOpenClient(newId); }}
      onUpdate={(patch)=>_updateClient(openClient, cur => Object.assign({}, cur, patch))}
      onUpdateArea={(areaPatch)=>_updateClient(openClient, cur => Object.assign({}, cur, areaPatch))}
      isMob={isMob}/>;
  }

  // ── Lista de clientes ──
  const clientList = (CLIENTS||[]).filter(c=>{
    if(c.status==="interno") return false;
    if(!search) return true;
    return c.name.toLowerCase().includes(search.toLowerCase());
  });

  return <div style={{display:"flex",flexDirection:"column",gap:16,fontFamily:PB_INTER}}>

    {/* ══ Header — mesmo estilo Carteira de clientes ══ */}
    <div style={{position:"relative",background:"linear-gradient(135deg, #0f172a 0%, #1e293b 45%, #312e81 100%)",borderRadius:20,padding:isMob?"18px 20px":"20px 28px",overflow:"hidden",display:"flex",alignItems:"center",justifyContent:"space-between",gap:16,flexWrap:"wrap",boxShadow:"0 12px 32px rgba(15,23,42,0.15)"}}>
      <div style={{position:"absolute",top:-60,right:-60,width:180,height:180,borderRadius:"50%",background:"radial-gradient(circle, rgba(124,58,237,0.28) 0%, transparent 65%)",filter:"blur(16px)",pointerEvents:"none"}}/>
      <div style={{position:"absolute",bottom:-40,left:-30,width:140,height:140,borderRadius:"50%",background:"radial-gradient(circle, rgba(14,165,233,0.20) 0%, transparent 65%)",filter:"blur(16px)",pointerEvents:"none"}}/>
      <div style={{minWidth:0,flex:1,position:"relative",zIndex:1}}>
        <div style={{display:"inline-flex",alignItems:"center",gap:6,background:"rgba(255,255,255,0.06)",backdropFilter:"blur(12px)",border:"1px solid rgba(255,255,255,0.1)",borderRadius:99,padding:"3px 10px 3px 6px",marginBottom:8}}>
          <div style={{width:20,height:20,borderRadius:6,background:"linear-gradient(135deg,"+PB_PURPLE+","+PB_PURPLE_DK+")",display:"flex",alignItems:"center",justifyContent:"center"}}>
            <Ico n="file-text" size={11} color="#fff"/>
          </div>
          <span style={{color:"#cbd5e1",fontSize:10.5,fontWeight:700,letterSpacing:.6,textTransform:"uppercase"}}>Central de playbooks</span>
        </div>
        <div style={{color:"#fff",fontWeight:800,fontSize:isMob?22:26,letterSpacing:-.8,lineHeight:1.15}}>Playbooks</div>
        <div style={{color:"#94a3b8",fontSize:12,marginTop:4,fontWeight:500,lineHeight:1.4}}>{_cadeiraCfg ? ("Visão de "+_cadeiraCfg.label+" — só o que essa cadeira precisa.") : "Um playbook por cliente."}</div>
      </div>
      <div style={{display:"flex",gap:10,alignItems:"center",position:"relative",zIndex:1}}>
        <div style={{position:"relative",display:"inline-flex",alignItems:"center"}}>
          <span style={{position:"absolute",left:12,top:"50%",transform:"translateY(-50%)",color:search?"#fff":"#94a3b8",pointerEvents:"none",display:"flex"}}>
            <Ico n="search" size={13} color="currentColor"/>
          </span>
          <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar cliente..."
            style={{background:"rgba(255,255,255,0.06)",backdropFilter:"blur(12px)",border:"1px solid "+(search?"rgba(255,255,255,0.25)":"rgba(255,255,255,0.10)"),borderRadius:10,padding:"0 32px 0 34px",color:"#fff",fontSize:12.5,fontWeight:500,outline:"none",width:260,height:38,boxSizing:"border-box",fontFamily:"inherit",transition:"all .15s"}}/>
        </div>
      </div>
    </div>

    {/* ══ Cadeiras (Social media / Design / Vídeo / Mídia) — só aparece pra quem tem mais de uma ══ */}
    {_cadeiras.length>1 && <div style={{display:"flex",gap:4,background:"#fff",border:"1px solid "+PB_BORDER,borderRadius:14,padding:5,overflowX:"auto"}}>
      {_cadeiras.map(function(c){
        const on = c.id===cadeira;
        return <button key={c.id} type="button" onClick={function(){ setCadeira(c.id); }}
          style={{flex:1,minWidth:130,display:"inline-flex",alignItems:"center",justifyContent:"center",gap:8,padding:"10px 14px",borderRadius:10,border:"none",cursor:"pointer",fontFamily:PB_INTER,fontSize:12.5,fontWeight:on?800:600,
            background:on?c.color:"transparent",color:on?"#fff":"#475569",boxShadow:on?("0 6px 16px "+c.color+"44"):"none",transition:"all .15s",whiteSpace:"nowrap"}}
          onMouseEnter={function(e){ if(!on) e.currentTarget.style.background="#f1f5f9"; }}
          onMouseLeave={function(e){ if(!on) e.currentTarget.style.background="transparent"; }}>
          <Ico n={c.icon} size={14} color={on?"#fff":c.color}/>{c.label}
        </button>;
      })}
    </div>}

    {/* ══ Grid de clientes — mesmo estilo Carteira ══ */}
    {clientList.length === 0
      ? <div style={{background:"#fff",borderRadius:14,padding:"50px 24px",textAlign:"center",border:"1px dashed "+PB_BORDER}}>
          <div style={{color:PB_SOFT,fontSize:13}}>Nenhum cliente encontrado.</div>
        </div>
      : <div style={{display:"grid",gridTemplateColumns:isMob?"1fr":"repeat(auto-fill,minmax(280px,1fr))",gap:14}}>
          {clientList.map(cl=>{
            const data = store[cl.id] || {};
            // Playbook OK se tem QUALQUER dado preenchido (sobre, contatos, produtos, orientações etc.)
            const hasArea = !!(data.sobre || data.comunicacao || (Array.isArray(data.produtos)&&data.produtos.length>0)
              || (data.contatos && Object.keys(data.contatos).some(function(k){return data.contatos[k];}))
              || (data.contatos_by_unit && Object.keys(data.contatos_by_unit).length>0)
              || (Array.isArray(data.orientacoes_visuais)&&data.orientacoes_visuais.length>0)
              || (Array.isArray(data.templates)&&data.templates.length>0)
              // Legacy: dados antigos por área
              || (data.design && (data.design.templates||data.design.orientacoes_visuais||data.design.checklist))
              || (data.video && (data.video.processos||data.video.orientacoes_visuais||data.video.checklist))
              || (data.social && (data.social.perfis||data.social.orientacoes_visuais||data.social.checklist)));
            const _accentCl = cl.color || "#94a3b8";
            const _logoSrc = (typeof CLIENT_LOGOS!=="undefined" && CLIENT_LOGOS[cl.id]) || cl.logoUrl || null;
            const hasLogo = !!_logoSrc;
return <div key={cl.id} onClick={()=>setOpenClient(cl.id)}
              style={{background:"#fff",border:"1px solid #eef0f3",borderRadius:20,padding:0,boxShadow:"0 4px 14px rgba(15,23,42,0.04)",display:"flex",flexDirection:"column",transition:"all .25s cubic-bezier(.4,0,.2,1)",cursor:"pointer",overflow:"hidden",position:"relative",fontFamily:PB_INTER}}
              onMouseEnter={e=>{e.currentTarget.style.boxShadow="0 24px 48px rgba(15,23,42,0.12)";e.currentTarget.style.borderColor=_accentCl+"66";e.currentTarget.style.transform="translateY(-6px)";}}
              onMouseLeave={e=>{e.currentTarget.style.boxShadow="0 4px 14px rgba(15,23,42,0.04)";e.currentTarget.style.borderColor="#eef0f3";e.currentTarget.style.transform="translateY(0)";}}>

              {/* COVER gradient da cor do cliente + bolinhas — sem badge de status */}
              <div style={{position:"relative",height:100,background:"linear-gradient(135deg, "+_accentCl+" 0%, "+_accentCl+"cc 100%)",overflow:"hidden"}}>
                <div style={{position:"absolute",inset:0,background:"radial-gradient(circle at 1px 1px, rgba(255,255,255,0.18) 1px, transparent 0)",backgroundSize:"12px 12px",opacity:.5}}/>
              </div>

              {/* LOGO flutuante */}
              <div style={{margin:"-32px 0 0 20px",width:64,height:64,borderRadius:16,background:"#fff",border:"3px solid #fff",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0,overflow:"hidden",boxShadow:"0 8px 20px rgba(15,23,42,0.12)",zIndex:2,position:"relative"}}>
                {hasLogo
                  ? <img src={_logoSrc} alt={cl.name} style={{maxWidth:"75%",maxHeight:"75%",objectFit:"contain",display:"block"}}/>
                  : <span style={{color:_accentCl,fontWeight:900,fontSize:22,letterSpacing:-.6}}>{cl.abbr||cl.name.slice(0,2).toUpperCase()}</span>
                }
              </div>

              {/* NOME + SETOR — mesmíssimo dado do Editar cliente, sem inventar descrição */}
              <div style={{padding:"14px 20px 6px",flex:"1 0 auto",display:"flex",flexDirection:"column"}}>
                <div style={{color:"#0f172a",fontWeight:800,fontSize:18,letterSpacing:-.5,lineHeight:1.15,marginBottom:6}}>{cl.name}</div>
                {cl.sector && <div style={{color:"#64748b",fontSize:13,fontWeight:500,lineHeight:1.4}}>{cl.sector}</div>}
              </div>

              {/* RODAPÉ — cidade (esquerda) + Abrir playbook (direita) */}
              {(function(){
                // Cidade/UF: prioridade cl.cidade → CLIENT_PROFILES[id].cidade
                const _profile = (typeof CLIENT_PROFILES!=="undefined" && CLIENT_PROFILES[cl.id]) || null;
                const _cid = cl.cidade || (_profile && _profile.cidade) || "";
                const _uf = cl.estado || (_profile && _profile.estado) || "";
                const _cidadeUf = _cid ? [_cid,_uf].filter(Boolean).join("/") : null;
                return <div style={{padding:"12px 20px 20px",display:"flex",alignItems:"center",justifyContent:"space-between",gap:8,flexWrap:"wrap",marginTop:"auto"}}>
                  {_cidadeUf
                    ? <span style={{display:"inline-flex",alignItems:"center",gap:5,background:"#f8fafc",color:"#475569",fontWeight:700,fontSize:11.5,padding:"5px 10px",borderRadius:8,border:"1px solid #e2e8f0"}}>
                        <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 10c0 7-9 13-9 13S3 17 3 10a9 9 0 0118 0z"/><circle cx="12" cy="10" r="3"/></svg>
                        {_cidadeUf}
                      </span>
                    : <span/>
                  }
                  <span style={{display:"inline-flex",alignItems:"center",gap:5,background:"#f8fafc",color:"#475569",fontWeight:700,fontSize:11.5,padding:"5px 10px",borderRadius:8,border:"1px solid #e2e8f0",marginLeft:"auto"}}>
                    Abrir playbook
                    <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><polyline points="9 18 15 12 9 6"/></svg>
                  </span>
                </div>;
              })()}
            </div>;
          })}
        </div>
    }
  </div>;
}

// ═══════════════════════════════════════════════════════════════
//  _PbVideoProcesses — Processos técnicos GLOBAIS de Edição de Vídeo
//  Sincronizado entre clientes via Supabase team_data tipo='video_processes'
//  Mirror em localStorage pra carregar offline + persistir entre sessões
// ═══════════════════════════════════════════════════════════════
const _PB_VP_KEY = "pixels-video-processes";

// Seed: primeiro processo já cadastrado (Compressor de Banda Simples).
const _PB_VP_SEED = [
  {
    id: "compressor-audio",
    title: "Compressão de áudio (Single-band Compressor)",
    descricao: "Aplicar em TODO vídeo final. Sem isso, o áudio do reels fica baixo no feed do Instagram e perde pra concorrência. O objetivo é deixar o som no limite máximo possível sem distorcer.",
    passos: [
      "Abrir o painel Audio Track Mixer (Mixer da Faixa de Áudio) — atalho Shift+9 no Premiere",
      "Na track de áudio principal (geralmente A1), clicar no triângulo pra abrir os slots de efeito",
      "Adicionar o efeito Single-band Compressor (Compressor de Banda Simples)",
      "Escolher o preset Vocal Attacker (no Premiere PT-BR continua em inglês — pode aparecer como 'Vocal Attacker' ou similar; o som de voz fica mais 'à frente')",
      "Aumentar o Output Gain (Ganho de Saída) gradualmente até o medidor chegar bem perto do vermelho — quase batendo, mas SEM bater no vermelho",
      "Conferir tocando o vídeo inteiro: se em algum momento o pico estourar (vermelho), reduzir 1-2 dB e testar de novo",
      "Exportar normalmente — o som vai sair alto e limpo no Instagram"
    ]
  }
];

// Normaliza passo: string legada → {text, img} object
function _pbNormStep(s){
  if(!s) return {text:"", img:""};
  if(typeof s === "string") return {text:s, img:""};
  return {text: s.text||"", img: s.img||""};
}
// Upload de imagem de passo pro Supabase Storage (mesma pattern do _pbTemplateUploadImg)
function _pbStepUploadImg(cb){
  try{
    const inp = document.createElement("input");
    inp.type = "file";
    inp.accept = "image/*";
    inp.style.display = "none";
    inp.onchange = async function(e){
      const file = e.target.files && e.target.files[0];
      if(!file) return;
      try{
        if(!window._sb) throw new Error("Supabase indisponível");
        const ext = (file.name.split(".").pop()||"png").replace(/[^a-zA-Z0-9]/g,"").toLowerCase();
        const rnd = Math.random().toString(36).slice(2,11);
        const path = "playbook-passos/"+Date.now()+"-"+rnd+"."+ext;
        if(typeof pixelsToast!=="undefined") pixelsToast.info("Enviando imagem...",1500);
        const {error} = await window._sb.storage.from("agency-files").upload(path, file, {cacheControl:"3600", upsert:false});
        if(error) throw error;
        const {data:pub} = window._sb.storage.from("agency-files").getPublicUrl(path);
        if(pub && pub.publicUrl){
          cb(pub.publicUrl);
          if(typeof pixelsToast!=="undefined") pixelsToast.success("Imagem subida!",1500);
        }
      }catch(err){
        console.warn("[upload passo]", err);
        if(typeof pixelsToast!=="undefined") pixelsToast.error("Erro: "+(err && err.message||"desconhecido"));
      }
    };
    document.body.appendChild(inp);
    inp.click();
    setTimeout(function(){try{document.body.removeChild(inp);}catch(_){}}, 60000);
  }catch(err){ console.warn(err); }
}

// Ícones disponíveis pro processo técnico — cada um com id + nome do Ico
const _PB_PROC_ICONS = [
  {id:"play",     label:"Play"},
  {id:"film",     label:"Vídeo"},
  {id:"camera",   label:"Câmera"},
  {id:"image",    label:"Imagem"},
  // Áudio (3 opções)
  {id:"music",    label:"Música"},
  {id:"volume2",  label:"Som"},
  {id:"mic",      label:"Microfone"},
  {id:"sparkles", label:"Efeitos"},
  {id:"edit",     label:"Editar"},
  {id:"scissors", label:"Cortar"},
  {id:"fileText", label:"Roteiro"},
  {id:"check",    label:"Concluir"},
  {id:"flag",     label:"Bandeira"},
  {id:"eye",      label:"Revisar"},
  {id:"pin",      label:"Marco"},
  {id:"package",  label:"Pacote"},
  {id:"alert",    label:"Atenção"},
  {id:"upload",   label:"Export"}
];
// Fallback quando o processo nao tem icone salvo — usa um padrao rotativo por index
function _pbProcIcon(proc, idx){
  if(proc && proc.icon) return proc.icon;
  const _defaults = ["play","music","edit","sparkles","scissors","film","check"];
  return _defaults[idx % _defaults.length];
}

function _PbVideoProcesses({isAdmin}){
  const [processes, setProcesses] = useState(function(){
    try{ const r=localStorage.getItem(_PB_VP_KEY); if(r) return JSON.parse(r); }catch(_){}
    return _PB_VP_SEED;
  });
  const [editing, setEditing] = useState(null); // null | {idx, draft}
  const [expanded, setExpanded] = useState({}); // {idx: true/false}
  const [stepLb, setStepLb] = useState(null); // URL da imagem em lightbox
  useEffect(function(){
    if(!stepLb) return;
    const _esc = function(e){ if(e.key==="Escape") setStepLb(null); };
    document.addEventListener("keydown", _esc);
    return function(){ document.removeEventListener("keydown", _esc); };
  },[stepLb]);

  // Pull do Supabase no mount (sobrescreve seed local)
  useEffect(function(){
    if(!window._sb) return;
    window._sb.from("team_data").select("dados").eq("tipo","video_processes").single().then(function(r){
      if(r.data && Array.isArray(r.data.dados) && r.data.dados.length>0){
        setProcesses(r.data.dados);
        try{ localStorage.setItem(_PB_VP_KEY, JSON.stringify(r.data.dados)); }catch(_){}
      }
    }).catch(function(){});
  },[]);

  function _persist(next){
    setProcesses(next);
    try{ localStorage.setItem(_PB_VP_KEY, JSON.stringify(next)); }catch(_){}
    if(window._sb){
      window._sb.from("team_data").upsert({tipo:"video_processes",dados:next,updated_by:CURRENT_USER.name},{onConflict:"tipo"}).then(function(){}).catch(function(){});
    }
  }

  function _toggle(idx){ setExpanded(function(p){return Object.assign({},p,{[idx]:!p[idx]});}); }

  function _new(){
    setEditing({idx:-1, draft:{id:"p-"+Date.now(), title:"", descricao:"", passos:[{text:"",img:""}]}});
  }
  function _edit(idx){
    // Normaliza passos legados (string) pra {text,img} ao entrar em edit
    var _draft = JSON.parse(JSON.stringify(processes[idx]));
    _draft.passos = (_draft.passos||[]).map(_pbNormStep);
    setEditing({idx, draft:_draft});
  }
  function _del(idx){
    if(typeof pixelsConfirm==="function"){
      pixelsConfirm({title:"Excluir processo", message:"Tem certeza? Essa ação não pode ser desfeita.", danger:true}).then(function(ok){
        if(ok){ _persist(processes.filter(function(_,i){return i!==idx;})); }
      });
    }else{
      if(window.confirm("Excluir esse processo?")){
        _persist(processes.filter(function(_,i){return i!==idx;}));
      }
    }
  }
  function _save(){
    if(!editing) return;
    var d = editing.draft;
    if(!d.title.trim()){ if(typeof pixelsToast!=="undefined")pixelsToast.warning("Coloca um título no processo"); return; }
    var cleanPassos = (d.passos||[]).map(function(s){
      var n = _pbNormStep(s);
      return {text: (n.text||"").trim(), img: n.img||""};
    }).filter(function(p){ return p.text || p.img; });
    var clean = Object.assign({},d,{passos:cleanPassos});
    var next;
    if(editing.idx===-1){ next = processes.concat([clean]); }
    else { next = processes.map(function(p,i){return i===editing.idx?clean:p;}); }
    _persist(next);
    setEditing(null);
    if(typeof pixelsToast!=="undefined")pixelsToast.success("Processo salvo!");
  }
  function _setDraft(patch){ setEditing(function(p){return Object.assign({},p,{draft:Object.assign({},p.draft,patch)});}); }
  function _setStepText(i,val){ _setDraft({passos:editing.draft.passos.map(function(s,idx){ if(idx!==i) return s; var n=_pbNormStep(s); return Object.assign({},n,{text:val}); })}); }
  function _setStepImg(i,url){ _setDraft({passos:editing.draft.passos.map(function(s,idx){ if(idx!==i) return s; var n=_pbNormStep(s); return Object.assign({},n,{img:url}); })}); }
  function _addStep(){ _setDraft({passos:(editing.draft.passos||[]).concat([{text:"",img:""}])});}
  function _delStep(i){ _setDraft({passos:editing.draft.passos.filter(function(_,idx){return idx!==i;})});}

  // Renderiza modal de edição
  if(editing){
    return <div style={{display:"flex",flexDirection:"column",gap:14}}>
      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:10,paddingBottom:12,borderBottom:"1px solid "+PB_BORDER2}}>
        <div style={{color:PB_INK,fontWeight:800,fontSize:14}}>{editing.idx===-1?"Novo processo":"Editar processo"}</div>
        <div style={{display:"flex",gap:8}}>
          <button onClick={function(){setEditing(null);}} style={{background:"#fafbfc",border:"1px solid #e2e8f0",borderRadius:9,padding:"7px 14px",color:"#475569",fontSize:12,fontWeight:600,cursor:"pointer",fontFamily:"inherit"}}>Cancelar</button>
          <button onClick={_save} style={{background:"linear-gradient(135deg, "+PB_PURPLE+" 0%, "+PB_PURPLE_DK+" 100%)",border:"none",borderRadius:9,padding:"7px 16px",color:"#fff",fontSize:12,fontWeight:700,cursor:"pointer",fontFamily:"inherit",boxShadow:"0 4px 12px rgba(159,67,246,.4)"}}>Salvar</button>
        </div>
      </div>
      <div>
        <div style={{color:PB_SOFT,fontSize:10.5,fontWeight:800,letterSpacing:.4,textTransform:"uppercase",marginBottom:6}}>Título</div>
        <input value={editing.draft.title} onChange={function(e){_setDraft({title:e.target.value});}}
          placeholder="Ex: Compressão de áudio (Single-band Compressor)"
          style={_pbInpStyle()}/>
      </div>
      <div>
        <div style={{color:PB_SOFT,fontSize:10.5,fontWeight:800,letterSpacing:.4,textTransform:"uppercase",marginBottom:6}}>Ícone</div>
        <div style={{display:"flex",flexWrap:"wrap",gap:6}}>
          {_PB_PROC_ICONS.map(function(_ic){
            const _active = (editing.draft.icon||"") === _ic.id;
            return <button key={_ic.id} type="button" onClick={function(){_setDraft({icon:_ic.id});}} title={_ic.label}
              style={{width:40,height:40,borderRadius:9,background:_active?"#0284c7":"#f8fafc",border:"1px solid "+(_active?"#0284c7":"#e2e8f0"),display:"inline-flex",alignItems:"center",justifyContent:"center",cursor:"pointer",transition:"all .12s",boxShadow:_active?"0 4px 12px rgba(2,132,199,.3)":"none"}}
              onMouseEnter={function(e){if(!_active){e.currentTarget.style.borderColor="#0284c7";e.currentTarget.style.background="#eff6ff";}}}
              onMouseLeave={function(e){if(!_active){e.currentTarget.style.borderColor="#e2e8f0";e.currentTarget.style.background="#f8fafc";}}}>
              <Ico n={_ic.id} size={16} color={_active?"#fff":"#0284c7"}/>
            </button>;
          })}
        </div>
      </div>
      <div>
        <div style={{color:PB_SOFT,fontSize:10.5,fontWeight:800,letterSpacing:.4,textTransform:"uppercase",marginBottom:6}}>Descrição / contexto</div>
        <_PbAutoTextarea value={editing.draft.descricao} onChange={function(e){_setDraft({descricao:e.target.value});}} rows={3}
          placeholder="Por que esse processo existe, quando aplicar, qual o objetivo..."
          style={_pbInpStyle()}/>
      </div>
      <div>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:6}}>
          <div style={{color:PB_SOFT,fontSize:10.5,fontWeight:800,letterSpacing:.4,textTransform:"uppercase"}}>Passos numerados</div>
          <button onClick={_addStep} style={{background:"#fafbfc",border:"1px solid #e2e8f0",borderRadius:8,padding:"5px 10px",color:"#475569",fontSize:11,fontWeight:600,cursor:"pointer",fontFamily:"inherit",display:"inline-flex",alignItems:"center",gap:5}}>
            <Ico n="plus" size={11} color="currentColor"/> Adicionar passo
          </button>
        </div>
        <div style={{display:"flex",flexDirection:"column",gap:8}}>
          {(editing.draft.passos||[]).map(function(rawStep,i){
            var step = _pbNormStep(rawStep);
            return <div key={i} style={{display:"flex",gap:8,alignItems:"flex-start",background:"#fafbfc",border:"1px solid "+PB_BORDER2,borderRadius:10,padding:10}}>
              <div style={{flexShrink:0,width:26,height:26,borderRadius:"50%",background:"#0ea5e914",color:"#0284c7",display:"flex",alignItems:"center",justifyContent:"center",fontSize:12,fontWeight:800,marginTop:4}}>{i+1}</div>
              <div style={{flex:1,display:"flex",flexDirection:"column",gap:8,minWidth:0}}>
                <_PbAutoTextarea value={step.text} onChange={function(e){_setStepText(i,e.target.value);}} rows={2}
                  placeholder={"Passo "+(i+1)+"..."}
                  style={Object.assign({},_pbInpStyle(),{minHeight:48})}/>
                {step.img ? (
                  <div style={{position:"relative",width:180,borderRadius:9,overflow:"hidden",background:"#f8fafc",border:"1px solid #e2e8f0"}}>
                    <img src={step.img} alt="" referrerPolicy="no-referrer" style={{width:"100%",display:"block",maxHeight:180,objectFit:"cover"}}/>
                    <button onClick={function(){_setStepImg(i,"");}} title="Remover imagem"
                      style={{position:"absolute",top:5,right:5,background:"rgba(15,23,42,.75)",border:"none",borderRadius:99,width:22,height:22,color:"#fff",cursor:"pointer",display:"inline-flex",alignItems:"center",justifyContent:"center",fontSize:13,fontWeight:700,lineHeight:1,padding:0}}>×</button>
                  </div>
                ) : (
                  <button onClick={function(){_pbStepUploadImg(function(url){_setStepImg(i,url);});}}
                    style={{alignSelf:"flex-start",background:"#fff",border:"1.5px dashed #cbd5e1",borderRadius:8,padding:"6px 12px",color:"#64748b",fontSize:11.5,fontWeight:700,cursor:"pointer",fontFamily:"inherit",display:"inline-flex",alignItems:"center",gap:6,transition:"all .12s"}}
                    onMouseEnter={function(e){e.currentTarget.style.borderColor="#0ea5e9";e.currentTarget.style.color="#0284c7";e.currentTarget.style.background="#f0f9ff";}}
                    onMouseLeave={function(e){e.currentTarget.style.borderColor="#cbd5e1";e.currentTarget.style.color="#64748b";e.currentTarget.style.background="#fff";}}>
                    <Ico n="image" size={12} color="currentColor"/> Adicionar imagem
                  </button>
                )}
              </div>
              <button onClick={function(){_delStep(i);}} title="Remover passo"
                style={{flexShrink:0,background:"transparent",border:"none",color:"#94a3b8",cursor:"pointer",padding:6,marginTop:2}}>
                <Ico n="x" size={13} color="currentColor"/>
              </button>
            </div>;
          })}
        </div>
      </div>
    </div>;
  }

  // Renderiza lista de processos (modo visualização)
  return <div style={{display:"flex",flexDirection:"column",gap:10}}>
    {processes.length===0 && <_PbEmpty icon="play" text="Nenhum processo cadastrado ainda." sub={isAdmin?"Adicione o primeiro com o botão abaixo.":""}/>}
    {processes.map(function(proc,idx){
      var open = !!expanded[idx];
      return <div key={proc.id||idx} style={{background:"#fafbfc",border:"1px solid "+PB_BORDER2,borderRadius:12,overflow:"hidden"}}>
        <div onClick={function(){_toggle(idx);}} style={{padding:"12px 14px",display:"flex",alignItems:"center",gap:10,cursor:"pointer",userSelect:"none"}}>
          <div style={{width:32,height:32,borderRadius:9,background:"#0ea5e914",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
            <Ico n={_pbProcIcon(proc, idx)} size={16} color="#0284c7"/>
          </div>
          <div style={{flex:1,minWidth:0}}>
            <div style={{color:PB_INK,fontWeight:700,fontSize:13.5,letterSpacing:-.2}}>{proc.title}</div>
            {proc.descricao && !open && <div style={{color:PB_MUTE,fontSize:11.5,marginTop:2,lineHeight:1.4,display:"-webkit-box",WebkitLineClamp:1,WebkitBoxOrient:"vertical",overflow:"hidden"}}>{proc.descricao}</div>}
          </div>
          <div style={{flexShrink:0,display:"flex",alignItems:"center",gap:6}}>
            {Array.isArray(proc.passos) && proc.passos.length>0 && <span style={{background:"#fff",border:"1px solid "+PB_BORDER2,borderRadius:99,padding:"2px 9px",fontSize:10.5,fontWeight:700,color:"#475569"}}>{proc.passos.length} passo{proc.passos.length>1?"s":""}</span>}
            <Ico n={open?"chevron-up":"chevron-down"} size={15} color="#94a3b8"/>
          </div>
        </div>
        {open && <div style={{padding:"4px 14px 16px",borderTop:"1px solid "+PB_BORDER2,background:"#fff"}}>
          {proc.descricao && <div style={{color:PB_TEXT,fontSize:13,lineHeight:1.6,marginTop:12,marginBottom:14,whiteSpace:"pre-wrap"}}>{proc.descricao}</div>}
          {Array.isArray(proc.passos) && proc.passos.length>0 && <div style={{display:"flex",flexDirection:"column",gap:8}}>
            {proc.passos.map(function(rawStep,si){
              var step = _pbNormStep(rawStep);
              return <div key={si} style={{display:"flex",gap:10,alignItems:"flex-start"}}>
                <div style={{flexShrink:0,width:24,height:24,borderRadius:"50%",background:"#0ea5e914",color:"#0284c7",display:"flex",alignItems:"center",justifyContent:"center",fontSize:11,fontWeight:800,marginTop:1}}>{si+1}</div>
                <div style={{flex:1,minWidth:0,display:"flex",flexDirection:"column",gap:8}}>
                  <div style={{color:PB_TEXT,fontSize:13,lineHeight:1.55}}>{step.text}</div>
                  {step.img && <img src={step.img} alt="" referrerPolicy="no-referrer"
                    onClick={function(){setStepLb(step.img);}}
                    style={{maxWidth:420,width:"100%",borderRadius:10,border:"1px solid #e2e8f0",background:"#f8fafc",cursor:"zoom-in",display:"block",boxShadow:"0 1px 3px rgba(15,23,42,.05)"}}/>}
                </div>
              </div>;
            })}
          </div>}
          {isAdmin && <div style={{display:"flex",gap:8,marginTop:16,paddingTop:12,borderTop:"1px solid "+PB_BORDER2}}>
            <button onClick={function(){_edit(idx);}} style={{background:"#fafbfc",border:"1px solid #e2e8f0",borderRadius:9,padding:"6px 13px",color:"#475569",fontSize:11.5,fontWeight:600,cursor:"pointer",fontFamily:"inherit",display:"inline-flex",alignItems:"center",gap:5}}>
              <Ico n="edit" size={11} color="currentColor"/> Editar
            </button>
            <button onClick={function(){_del(idx);}} style={{background:"transparent",border:"1px solid #fecaca",borderRadius:9,padding:"6px 13px",color:"#dc2626",fontSize:11.5,fontWeight:600,cursor:"pointer",fontFamily:"inherit",display:"inline-flex",alignItems:"center",gap:5}}>
              <Ico n="trash" size={11} color="currentColor"/> Excluir
            </button>
          </div>}
        </div>}
      </div>;
    })}
    {stepLb && <div onClick={function(){setStepLb(null);}}
      style={{position:"fixed",inset:0,background:"rgba(15,23,42,0.92)",zIndex:9999,display:"flex",alignItems:"center",justifyContent:"center",padding:24,backdropFilter:"blur(4px)",cursor:"zoom-out"}}>
      <button type="button" onClick={function(e){e.stopPropagation();setStepLb(null);}}
        style={{position:"absolute",top:20,right:20,background:"rgba(255,255,255,0.14)",border:"none",borderRadius:99,width:44,height:44,color:"#fff",cursor:"pointer",display:"inline-flex",alignItems:"center",justifyContent:"center",fontSize:22,fontWeight:600,lineHeight:1,padding:0}}
        title="Fechar (ESC)">×</button>
      <img src={stepLb} alt="" referrerPolicy="no-referrer" onClick={function(e){e.stopPropagation();}}
        style={{maxWidth:"92vw",maxHeight:"88vh",borderRadius:12,boxShadow:"0 20px 60px rgba(0,0,0,0.5)",cursor:"default",objectFit:"contain",display:"block"}}/>
    </div>}
    {isAdmin && <button onClick={_new}
      style={{background:"linear-gradient(135deg, "+PB_PURPLE+" 0%, "+PB_PURPLE_DK+" 100%)",border:"none",borderRadius:11,padding:"10px 16px",color:"#fff",fontSize:12.5,fontWeight:700,cursor:"pointer",fontFamily:"inherit",boxShadow:"0 6px 16px rgba(159,67,246,.4)",display:"inline-flex",alignItems:"center",justifyContent:"center",gap:7,alignSelf:"flex-start"}}>
      <Ico n="plus" size={13} color="#fff"/> Novo processo
    </button>}
  </div>;
}

// ═══════════════════════════════════════════════════════════════
//  PlaybookDetalhe — página de um cliente/área específica
// ═══════════════════════════════════════════════════════════════
function PlaybookDetalhe({cl, area, areaCfg, data, isAdmin, editMode, setEditMode, onBack, onSwitchClient, onUpdate, onUpdateArea, isMob, cadeiras, cadeira, onSwitchCadeira}){
  _PB_CADEIRA_ATUAL = cadeira || null; // PlaybookBlock consulta isso pra se esconder
  // UNIFICADO: quando area==="all", areaData = MERGE de root + legacy por área.
  // Orientações visuais são mescladas de todas as áreas numa lista única.
  const areaData = (function(){
    if(area !== "all") return data[area] || {};
    const _design = data.design || {};
    const _video = data.video || {};
    const _social = data.social || {};
    // Templates: root primeiro, senão design (era só design que tinha)
    const _templates = Array.isArray(data.templates) ? data.templates : (Array.isArray(_design.templates) ? _design.templates : []);
    // Orientações visuais: MESCLA (root + design + video + social), dedup por id
    const _ovMerged = [];
    const _seen = {};
    [data.orientacoes_visuais, _design.orientacoes_visuais, _video.orientacoes_visuais, _social.orientacoes_visuais].forEach(function(arr){
      if(Array.isArray(arr)) arr.forEach(function(it){
        if(it && it.id && !_seen[it.id]){ _seen[it.id]=true; _ovMerged.push(it); }
      });
    });
    // Checklist: root, senão pega do design/video/social (o mais preenchido)
    let _chk = Array.isArray(data.checklist) ? data.checklist : null;
    if(!_chk){
      const _candidates = [_design.checklist, _video.checklist, _social.checklist].filter(function(x){return Array.isArray(x)&&x.length>0;});
      _chk = _candidates[0] || [];
    }
    return Object.assign({}, _design, _video, _social, data, {
      templates: _templates,
      orientacoes_visuais: _ovMerged,
      checklist: _chk,
      // Social: perfis, cadencia, mix vêm de _social
      perfis: (data.perfis || _social.perfis || []),
      cadencia: (data.cadencia || _social.cadencia || null),
      mix: (data.mix || _social.mix || null),
      particularidades: (data.particularidades || _social.particularidades || ""),
      restricoes: (data.restricoes || _social.restricoes || "")
    });
  })();

  // Edição inline
  const [editSobre,setEditSobre] = useState(data.sobre||"");
  const [editComm,setEditComm]   = useState(data.comunicacao||"");
  const [editInstrDesigner,setEditInstrDesigner] = useState(data.instrucoesDesigner||"");
  const [editChk,setEditChk]     = useState((areaData.checklist||[]).join("\n"));
  // Contatos: campos pra colocar nas artes e vídeos (telefone, WhatsApp, etc)
  const [editContatos,setEditContatos] = useState(data.contatos||{telefone:"",whatsapp:"",endereco:"",site:"",instagram:"",email:""});
  // Produtos: lista editável. Pra Bioter, cada produto tem array de unidades onde se aplica.
  const [editProdutos,setEditProdutos] = useState(Array.isArray(data.produtos)?data.produtos:[]);
  // Bioter: contatos POR UNIDADE — cada unidade tem dados próprios.
  // Estrutura: {chapeco:{telefone,whatsapp,...}, toledo:{...}, ...}
  const [editContatosByUnit,setEditContatosByUnit] = useState(data.contatos_by_unit||{});
  // Tab de unidade ativa (Bioter only) — controla qual unidade está sendo visualizada/editada
  const _firstUnitId = (typeof BIOTER_UNITS!=="undefined"&&BIOTER_UNITS[0])?BIOTER_UNITS[0].id:"";
  const [_unitTab,setUnitTab] = useState(_firstUnitId);
  // Filtro independente pra aba Produtos (nao compartilha com Contatos)
  const _unitTabProd=_unitTab, setUnitTabProd=setUnitTab; // UNIFICADO: um seletor de unidade no topo governa Contatos e Produtos
  // Lightbox pra ver imagem de produto expandida (sem abrir nova aba)
  const [_prodLightbox,setProdLightbox] = useState(null);
  useEffect(function(){
    if(!_prodLightbox) return;
    const _esc = function(e){ if(e.key==="Escape") setProdLightbox(null); };
    document.addEventListener("keydown", _esc);
    return function(){ document.removeEventListener("keydown", _esc); };
  }, [_prodLightbox]);

  useEffect(()=>{
    setEditSobre(data.sobre||"");
    setEditComm(data.comunicacao||"");
    setEditInstrDesigner(data.instrucoesDesigner||"");
    setEditChk((areaData.checklist||[]).join("\n"));
    setEditContatos(data.contatos||{telefone:"",whatsapp:"",endereco:"",site:"",instagram:"",email:""});
    setEditProdutos(Array.isArray(data.produtos)?data.produtos:[]);
    setEditContatosByUnit(data.contatos_by_unit||{});
  },[cl.id,area,editMode]);

  const handleSave = ()=>{
    onUpdate({sobre:editSobre, comunicacao:editComm, contatos:editContatos, contatos_by_unit:editContatosByUnit, produtos:editProdutos});
    onUpdateArea({checklist:editChk.split("\n").map(s=>s.trim()).filter(Boolean)});
    // editMode fica sempre true (edicao inline). Nao volta pra modo leitura.
    if(typeof pixelsToast!=="undefined") pixelsToast.success("Playbook salvo!");
  };

  // ── AUTO-SAVE CENTRAL — debounce 800ms ──
  // Sempre que qualquer estado editável muda, salva sozinho no Supabase.
  // Guarda contra: (1) primeira render (não salvar valores iniciais),
  //                (2) troca de cliente/area (que reseta os states via useEffect).
  const _autosaveSkipRef = useRef(true);
  useEffect(function(){
    // Reset flag ao trocar cliente/area — a próxima mudança dos states
    // vem do useEffect de reset, não de edição do usuário.
    _autosaveSkipRef.current = true;
    const _t = setTimeout(function(){ _autosaveSkipRef.current = false; }, 500);
    return function(){ clearTimeout(_t); };
  },[cl.id, area]);
  useEffect(function(){
    if(_autosaveSkipRef.current) return;
    const _tid = setTimeout(function(){
      try{
        const _patch = {};
        if((editSobre||"") !== (data.sobre||"")) _patch.sobre = editSobre;
        if((editComm||"") !== (data.comunicacao||"")) _patch.comunicacao = editComm;
        if(JSON.stringify(editContatos||{}) !== JSON.stringify(data.contatos||{})) _patch.contatos = editContatos;
        if(JSON.stringify(editContatosByUnit||{}) !== JSON.stringify(data.contatos_by_unit||{})) _patch.contatos_by_unit = editContatosByUnit;
        if(JSON.stringify(editProdutos||[]) !== JSON.stringify(data.produtos||[])) _patch.produtos = editProdutos;
        if(Object.keys(_patch).length > 0){
          onUpdate(_patch);
        }
        const _chkArr = (editChk||"").split("\n").map(function(s){return s.trim();}).filter(Boolean);
        const _curChk = Array.isArray(areaData.checklist) ? areaData.checklist : [];
        if(JSON.stringify(_chkArr) !== JSON.stringify(_curChk)){
          onUpdateArea({checklist:_chkArr});
        }
      }catch(err){ console.warn("[playbook autosave]", err); }
    }, 800);
    return function(){ clearTimeout(_tid); };
  // eslint-disable-next-line
  },[editSobre, editComm, editContatos, editContatosByUnit, editProdutos, editChk]);

  // Helper Bioter contatos por unidade: ler/escrever
  const _contatosForUnit=function(unitId){
    if(!unitId)return editContatos||{};
    return (editContatosByUnit||{})[unitId] || {};
  };
  const _setContatosForUnit=function(unitId, patch){
    if(!unitId){setEditContatos(function(p){return Object.assign({},p||{},patch);});return;}
    setEditContatosByUnit(function(p){
      const cur=(p||{})[unitId] || {};
      return Object.assign({},p||{},{[unitId]:Object.assign({},cur,patch)});
    });
  };
  // Helper produtos: adicionar/remover/atualizar
  const _produtoAdd=function(){setEditProdutos(function(p){return p.concat([{nome:"",descricao:"",unidades:[],imgUrls:[]}]);});};
  const _produtoUpd=function(idx,patch){setEditProdutos(function(p){return p.map(function(it,i){return i===idx?Object.assign({},it,patch):it;});});};
  const _produtoDel=function(idx){setEditProdutos(function(p){return p.filter(function(_,i){return i!==idx;});});};
  // Adiciona uma nova imagem ao array imgUrls do produto (migra imgUrl legado se existir)
  const _produtoAddImgToArr=function(idx,url){
    setEditProdutos(function(p){return p.map(function(it,i){
      if(i!==idx) return it;
      const legacy = it.imgUrl && !(Array.isArray(it.imgUrls) && it.imgUrls.length) ? [it.imgUrl] : [];
      const cur = Array.isArray(it.imgUrls) ? it.imgUrls : legacy;
      return Object.assign({},it,{imgUrls:cur.concat([url]), imgUrl: it.imgUrl || url});
    });});
  };
  const _produtoRemoveImg=function(idx,imgIdx){
    setEditProdutos(function(p){return p.map(function(it,i){
      if(i!==idx) return it;
      const legacy = it.imgUrl && !(Array.isArray(it.imgUrls) && it.imgUrls.length) ? [it.imgUrl] : [];
      const cur = Array.isArray(it.imgUrls) ? it.imgUrls.slice() : legacy;
      cur.splice(imgIdx,1);
      return Object.assign({},it,{imgUrls:cur, imgUrl: cur[0] || ""});
    });});
  };
  const _produtoToggleUnit=function(idx,unitId){
    setEditProdutos(function(p){return p.map(function(it,i){
      if(i!==idx) return it;
      const cur=Array.isArray(it.unidades)?it.unidades:[];
      const has=cur.indexOf(unitId)>=0;
      let next;
      if(has){
        // Removendo — se ficar vazio, volta pra "coringa" (aparece em todas)
        next = cur.filter(function(u){return u!==unitId;});
      } else {
        // Adicionando. Se era coringa (sem unidades) e a aba ativa eh outra,
        // inclui a aba atual TAMBEM pra o produto nao sumir de onde o usuario
        // estava mexendo.
        next = cur.concat([unitId]);
        if(cur.length===0 && _unitTab && _unitTab!==unitId && next.indexOf(_unitTab)<0){
          next.push(_unitTab);
        }
      }
      return Object.assign({},it,{unidades:next});
    });});
  };
  // Reordena produtos dentro de UMA unidade Bioter e persiste em prod.ordemPorUnidade[unitId]
  const _produtoReorderInUnit=function(unitId, srcIdx, dstIdx){
    if(!unitId || srcIdx===dstIdx) return;
    setEditProdutos(function(prods){
      const filtered=[];
      prods.forEach(function(p,gi){
        const u=Array.isArray(p.unidades)?p.unidades:[];
        if(u.length===0 || u.indexOf(unitId)>=0){
          const _ord=(p.ordemPorUnidade&&typeof p.ordemPorUnidade[unitId]==="number")?p.ordemPorUnidade[unitId]:999+gi;
          filtered.push({gi:gi, ord:_ord});
        }
      });
      filtered.sort(function(a,b){return a.ord-b.ord;});
      if(srcIdx<0||srcIdx>=filtered.length||dstIdx<0||dstIdx>=filtered.length) return prods;
      const moved=filtered.splice(srcIdx,1)[0];
      filtered.splice(dstIdx,0,moved);
      const newProds=prods.slice();
      filtered.forEach(function(f,newIdx){
        const cur=newProds[f.gi]||{};
        const curOrd=cur.ordemPorUnidade||{};
        newProds[f.gi]=Object.assign({},cur,{ordemPorUnidade:Object.assign({},curOrd,{[unitId]:newIdx})});
      });
      return newProds;
    });
  };
  const _dragProdRef=useRef({unitId:null, srcIdx:-1});
  // Indicador visual de drop position durante drag de produto
  const [_dropIdx, setDropIdx] = useState(-1);
  const _isBioter=cl.id==="bioter";

  // Estado local dos checkboxes (lembra entre navegações)
  const checklistArr = areaData.checklist || [];
  const chkKey = "pixels-pbchk-"+cl.id+"-"+area;
  const [checks, setChecks] = useState(()=>{
    try{ const r=localStorage.getItem(chkKey); if(r) return JSON.parse(r); }catch(_){}
    return {};
  });
  useEffect(()=>{
    try{ const r=localStorage.getItem(chkKey); setChecks(r?JSON.parse(r):{}); }catch(_){ setChecks({}); }
  },[cl.id,area]);
  const toggleCheck = (idx)=>{
    const next = Object.assign({}, checks, {[idx]: !checks[idx]});
    setChecks(next);
    try{ localStorage.setItem(chkKey, JSON.stringify(next)); }catch(_){}
  };
  const totalCheck = checklistArr.length;
  const doneCheck  = checklistArr.reduce((acc,_,i)=>acc + (checks[i]?1:0), 0);
  const allDone    = totalCheck>0 && doneCheck === totalCheck;

  // Refs (links) + Documentos (uploads)
  const refs = areaData.refs || [];
  const docs = areaData.docs || [];
  // State do modal de documento de texto — DEVE estar no topo (regras de hooks)
  const [_txtOpen,_setTxtOpen] = useState(null);

  // Tem template?
  const templates = (areaData.templates||[]);
  const hasTemplate = (area==="all" || area==="design") && (templates.length>0 || editMode);

  // Anchors visíveis nesta área
  const SECTIONS = [
    {id:"pb-sobre",        label:"Sobre",        icon:"building"},
    {id:"pb-comunicacao",  label:"Comunicação",  icon:"sparkles"},
    {id:"pb-designer",     label:"Designer",     icon:"image"},
    {id:"pb-equipe",       label:"Orientações",  icon:"sparkles"},
    {id:"pb-contatos",     label:"Contatos",     icon:"phone"},
    {id:"pb-produtos",     label:"Produtos/serviços", icon:"package"},
  ];
  // UNIFICADO: Orientacoes ja incluida no topo. Nao push denovo.
  // (Placeholder pra manter estrutura do if abaixo — nao adiciona nada duplicado)
  if(false){}
  const _pbProcTopo = _PB_CADEIRA_ATUAL==="video"; // Edição de vídeo: processos técnicos no topo
  if(area==="all" || area==="video"){ const _sp={id:"pb-processos", label:"Processos", icon:"play"}; if(_pbProcTopo) SECTIONS.unshift(_sp); else SECTIONS.push(_sp); }
  if(area==="all" || area==="social") SECTIONS.push({id:"pb-social", label:"Social", icon:"users"});
  SECTIONS.push({id:"pb-orientacoes-visuais", label:"Visuais", icon:"image"});
  if(area==="all" || hasTemplate) SECTIONS.push({id:"pb-templates", label:"Templates", icon:"image"});
  SECTIONS.push({id:"pb-checklist", label:"Checklist", icon:"checkCircle"});
  // Cadeira: só os atalhos dos blocos que ela enxerga
  const SECTIONS_VIS = SECTIONS.filter(function(sec){ return _pbBlocoVisivel(sec.id); });

  // ─────────── Layout ───────────
  return <div style={{background:PB_BG,margin:isMob?-12:-16,padding:isMob?12:20,minHeight:"100%",fontFamily:PB_INTER}}>
    <div style={{display:"flex",flexDirection:"column",gap:14,maxWidth:1280,margin:"0 auto"}}>

      {/* ══════════ HEADER PREMIUM — clean, sem neon ══════════ */}
      <div style={{background:"#fff",border:"1px solid #eef0f3",borderRadius:18,padding:isMob?"18px 18px 20px":"24px 28px 26px",position:"relative",overflow:"hidden",boxShadow:"0 1px 2px rgba(15,23,42,.04), 0 8px 24px rgba(15,23,42,.04)"}}>
        <div style={{position:"absolute",top:0,left:0,right:0,height:4,background:"linear-gradient(90deg, "+PB_PURPLE+", "+PB_PURPLE_DK+")"}}/>

        <div style={{position:"relative",zIndex:1,display:"flex",alignItems:"flex-start",gap:isMob?12:16,flexWrap:"wrap",justifyContent:"space-between"}}>
          <div style={{display:"flex",alignItems:"flex-start",gap:isMob?12:16,minWidth:0,flex:1}}>
            <button onClick={onBack} title="Voltar"
              style={{background:"#fafbfc",border:"1px solid #e2e8f0",borderRadius:12,width:40,height:40,display:"flex",alignItems:"center",justifyContent:"center",color:"#475569",cursor:"pointer",flexShrink:0}}>
              <Ico n="chevron-left" size={18} color="#475569"/>
            </button>
            <div style={{width:isMob?56:64,height:isMob?56:64,borderRadius:16,background:"#fafbfc",border:"1px solid #eef0f3",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0,overflow:"hidden"}}>
              <ClientLogo clientId={cl.id} size="lg"/>
            </div>
            <div style={{minWidth:0,paddingTop:2}}>
              <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:8,flexWrap:"wrap"}}>
                <span style={{background:areaCfg.color+"14",color:areaCfg.color,border:"1px solid "+areaCfg.color+"33",borderRadius:8,padding:"3px 10px",fontSize:10,fontWeight:800,letterSpacing:.4,textTransform:"uppercase",display:"inline-flex",alignItems:"center",gap:5}}>
                  <Ico n={areaCfg.icon} size={11} color={areaCfg.color}/>{areaCfg.label}
                </span>
                {cl.sector && <span style={{background:"#f1f5f9",color:"#475569",border:"1px solid #e2e8f0",borderRadius:8,padding:"3px 10px",fontSize:10,fontWeight:700,letterSpacing:.4,textTransform:"uppercase"}}>{cl.sector}</span>}
              </div>
              <div style={{color:"#0f172a",fontWeight:800,fontSize:isMob?22:30,letterSpacing:-.7,lineHeight:1.1}}>{cl.name}</div>
            </div>
          </div>
        </div>
      </div>

      {/* ══════════ BARRINHA DE CLIENTES — troca de playbook em 1 clique ══════════ */}
      {typeof onSwitchClient === "function" && (function(){
        const _all = (typeof CLIENTS!=="undefined"?CLIENTS:[]).filter(function(c){return c.status!=="interno";});
        if(_all.length<=1) return null;
        return <div style={{background:"#fff",border:"1px solid "+PB_BORDER,borderRadius:12,padding:8,display:"flex",gap:6,overflowX:"auto",boxShadow:"0 1px 2px rgba(15,23,42,.03)"}}>
          {_all.map(function(c){
            const _active = c.id === cl.id;
            const _cor = c.color || "#7c3aed";
            const _logoSrc = (typeof CLIENT_LOGOS!=="undefined" && CLIENT_LOGOS[c.id]) || null;
            const _initials = (c.name||"?").trim().split(" ").map(function(w){return w[0]||"";}).slice(0,2).join("").toUpperCase();
            return <button key={c.id}
              onClick={function(){ if(!_active) onSwitchClient(c.id); }}
              title={_active?c.name+" (aqui)":"Ir pra playbook: "+c.name}
              style={{background:_active?_cor+"12":"#fff",border:"1.5px solid "+(_active?_cor:"#e2e8f0"),borderRadius:10,padding:"6px 12px 6px 5px",fontSize:12.5,fontWeight:_active?700:600,color:_active?_cor:"#475569",cursor:_active?"default":"pointer",fontFamily:"inherit",display:"inline-flex",alignItems:"center",gap:7,whiteSpace:"nowrap",flexShrink:0,transition:"all .12s",boxShadow:_active?"0 2px 8px "+_cor+"22":"none"}}
              onMouseEnter={function(e){if(!_active){e.currentTarget.style.borderColor=_cor+"66";e.currentTarget.style.background=_cor+"06";e.currentTarget.style.color=_cor;}}}
              onMouseLeave={function(e){if(!_active){e.currentTarget.style.borderColor="#e2e8f0";e.currentTarget.style.background="#fff";e.currentTarget.style.color="#475569";}}}>
              <span style={{width:22,height:22,borderRadius:6,background:_logoSrc?"#fff":_cor,border:"1px solid "+(_logoSrc?"#e2e8f0":"transparent"),display:"inline-flex",alignItems:"center",justifyContent:"center",overflow:"hidden",flexShrink:0,padding:_logoSrc?2:0}}>
                {_logoSrc
                  ? <img src={_logoSrc} alt="" style={{maxWidth:"100%",maxHeight:"100%",objectFit:"contain"}}/>
                  : <span style={{color:"#fff",fontSize:9.5,fontWeight:800,letterSpacing:-.2}}>{_initials}</span>
                }
              </span>
              <span>{c.name}</span>
              {_active ? <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke={_cor} strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" style={{flexShrink:0}}><polyline points="20 6 9 17 4 12"/></svg> : null}
            </button>;
          })}
        </div>;
      })()}

      {/* ══ Cadeiras dentro do detalhe (admin/Hellen alternam sem voltar pra lista) ══ */}
      {Array.isArray(cadeiras) && cadeiras.length>1 && <div style={{display:"flex",gap:4,background:"#fff",border:"1px solid "+PB_BORDER,borderRadius:14,padding:5,overflowX:"auto"}}>
        {cadeiras.map(function(c){
          const on = c.id===cadeira;
          return <button key={c.id} type="button" onClick={function(){ if(typeof onSwitchCadeira==="function") onSwitchCadeira(c.id); }}
            style={{flex:1,minWidth:130,display:"inline-flex",alignItems:"center",justifyContent:"center",gap:8,padding:"9px 14px",borderRadius:10,border:"none",cursor:"pointer",fontFamily:PB_INTER,fontSize:12.5,fontWeight:on?800:600,
              background:on?c.color:"transparent",color:on?"#fff":"#475569",boxShadow:on?("0 6px 16px "+c.color+"44"):"none",transition:"all .15s",whiteSpace:"nowrap"}}
            onMouseEnter={function(e){ if(!on) e.currentTarget.style.background="#f1f5f9"; }}
            onMouseLeave={function(e){ if(!on) e.currentTarget.style.background="transparent"; }}>
            <Ico n={c.icon} size={14} color={on?"#fff":c.color}/>{c.label}
          </button>;
        })}
      </div>}

      {/* ══════════ ANCORAS / NAV RÁPIDO ══════════ */}
      <div style={{background:"#fff",border:"1px solid "+PB_BORDER,borderRadius:14,padding:5,display:"flex",gap:2,overflowX:isMob?"auto":"hidden",position:"sticky",top:8,zIndex:5,boxShadow:"0 2px 10px rgba(15,23,42,.04)"}}>
        {SECTIONS_VIS.map(s=>(
          <button key={s.id} onClick={()=>_pbScrollTo(s.id)}
            style={{flex:isMob?"0 0 auto":"1 1 0",minWidth:0,background:"transparent",border:"none",borderRadius:9,padding:"7px 6px",fontSize:11.5,fontWeight:600,color:PB_TEXT,cursor:"pointer",fontFamily:"inherit",display:"inline-flex",alignItems:"center",justifyContent:"center",gap:5,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis",transition:"all .15s"}}
            onMouseEnter={e=>{e.currentTarget.style.background=PB_PURPLE_BG;e.currentTarget.style.color=PB_PURPLE_DK;}}
            onMouseLeave={e=>{e.currentTarget.style.background="transparent";e.currentTarget.style.color=PB_TEXT;}}>
            <Ico n={s.icon} size={12} color="currentColor"/><span style={{overflow:"hidden",textOverflow:"ellipsis"}}>{s.label}</span>
          </button>
        ))}
      </div>

      {/* ══════════ UNIDADE ATIVA (Grupo Bioter) — seletor ÚNICO que governa o playbook todo ══════════ */}
      {_isBioter&&typeof BIOTER_UNITS!=="undefined"&&<div style={{background:"#fff",border:"1px solid "+PB_BORDER,borderRadius:14,padding:"10px 14px",display:"flex",alignItems:"center",gap:10,flexWrap:"wrap",position:"sticky",top:54,zIndex:4,boxShadow:"0 2px 10px rgba(15,23,42,.05)"}}>
        <span style={{color:PB_SOFT,fontSize:10,fontWeight:800,letterSpacing:.6,textTransform:"uppercase"}}>Unidade</span>
        <div style={{display:"inline-flex",background:"#f1f5f9",border:"1px solid #e2e8f0",borderRadius:10,padding:3,gap:2,flexWrap:"wrap"}}>
          {BIOTER_UNITS.map(function(u){
            const active=_unitTab===u.id;
            return <button key={u.id} type="button" onClick={function(){setUnitTab(u.id);}}
              style={{background:active?"#0f172a":"transparent",border:"none",color:active?"#fff":"#475569",borderRadius:8,padding:"6px 13px",fontSize:12,fontWeight:active?800:600,cursor:"pointer",fontFamily:PB_INTER,letterSpacing:-.1,transition:"all .12s",boxShadow:active?"0 2px 6px rgba(15,23,42,.25)":"none"}}
              onMouseEnter={function(e){if(!active)e.currentTarget.style.background="rgba(15,23,42,.06)";}}
              onMouseLeave={function(e){if(!active)e.currentTarget.style.background="transparent";}}>
              {u.pickerLabel||u.label}
            </button>;
          })}
        </div>
        <span style={{color:"#94a3b8",fontSize:10.5,fontWeight:600}}>Contatos e Produtos abaixo mostram só essa unidade</span>
      </div>}

      {/* ══════════ GRID 2 COLUNAS ══════════ */}
      <div style={{display:"grid",gridTemplateColumns:isMob?"1fr":"1fr 320px",gap:14,alignItems:"start"}}>

        {/* ───── COLUNA PRINCIPAL ───── */}
        <div style={{display:"flex",flexDirection:"column",gap:34,minWidth:0}}>

          {/* Edição de vídeo: Processos técnicos vêm PRIMEIRO (o editor abre o playbook por eles) */}
          {_pbProcTopo && (area==="all" || area==="video") && <PlaybookBlock id="pb-processos" title="Processos técnicos de vídeo" subtitle="Etapas obrigatórias pra todo vídeo da agência (aplica em todos os clientes)" icon="play" color="#0ea5e9">
            <_PbVideoProcesses isAdmin={isAdmin}/>
          </PlaybookBlock>}

          {/* Sobre a empresa */}
          <PlaybookBlock id="pb-sobre" title="Sobre a empresa" subtitle="Quem é o cliente, onde atua e posicionamento" icon="building" color={PB_PURPLE}>
            {editMode
              ? <_PbAutoTextarea value={editSobre} onChange={e=>setEditSobre(e.target.value)} onBlur={function(){if((editSobre||"")!==(data.sobre||"")) onUpdate({sobre:editSobre});}} rows={5}
                  placeholder="Quem é o cliente, o que vende, onde atua, posicionamento principal..."
                  style={_pbInpStyle()}/>
              : (function(){
                  const _s = data.sobre || _pbAutoSobre(cl.id);
                  return _s
                    ? <PbProse text={_s}/>
                    : <_PbEmpty icon="building" text="Sem descrição cadastrada." sub={isAdmin?"Preencha abaixo pra cadastrar.":""}/>;
                })()
            }
          </PlaybookBlock>

          {/* Dados do Briefing — auto, read-only, copiável */}
          <_PbBriefingAuto clientId={cl.id}/>

          <PlaybookBlock id="pb-contatos" title="Contatos" subtitle={_isBioter?"Dados de cada unidade — pra colocar nas artes e vídeos do post daquela unidade":"Dados pra colocar nas artes e vídeos"} icon="phone" color="#0d9488">
            {_isBioter && typeof BIOTER_UNITS!=="undefined" && (function(){
              const _u=BIOTER_UNITS.find(function(x){return x.id===_unitTab;});
              return <div style={{marginBottom:14,paddingBottom:12,borderBottom:"1px solid "+PB_BORDER2,display:"flex",alignItems:"center",gap:8}}>
                <span style={{background:"#0f172a",color:"#fff",borderRadius:99,padding:"5px 14px",fontSize:11.5,fontWeight:800,letterSpacing:-.1}}>{(_u&&(_u.pickerLabel||_u.label))||_unitTab}</span>
                <span style={{color:"#94a3b8",fontSize:11,fontWeight:600}}>unidade ativa — troque no seletor fixo do topo</span>
              </div>;
            })()}
            {(function(){
              const _currentUnit = _isBioter ? _unitTab : null;
              // ── Normaliza contatos pra sempre ser array ──
              // Backcompat: se vier objeto único {nome/whatsapp/email/telefone,...} vira [obj].
              // Se vier array, mantém.
              const _norm = function(raw){
                if(!raw) return [];
                if(Array.isArray(raw)) return raw.filter(Boolean);
                if(typeof raw==="object"){
                  const hasAny = raw.nome||raw.whatsapp||raw.email||raw.telefone||raw.site||raw.instagram||raw.endereco;
                  return hasAny ? [{
                    nome: raw.nome||"",
                    whatsapp: raw.whatsapp||raw.telefone||"",
                    email: raw.email||"",
                  }] : [];
                }
                return [];
              };
              // Lista atual (edição usa state; leitura usa data)
              const listEdit = editMode
                ? (_isBioter ? _norm(editContatosByUnit[_currentUnit]) : _norm(editContatos))
                : [];
              const listRead = !editMode
                ? (_isBioter ? _norm((data.contatos_by_unit||{})[_currentUnit]) : _norm(data.contatos))
                : [];
              // Setter que salva array
              const _saveList = function(newList){
                if(_isBioter){
                  setEditContatosByUnit(function(p){return Object.assign({},p||{},{[_currentUnit]:newList});});
                } else {
                  setEditContatos(newList);
                }
              };
              const _updateAt = function(idx, patch){
                const cur = [...listEdit];
                cur[idx] = Object.assign({}, cur[idx]||{}, patch);
                _saveList(cur);
              };
              const _removeAt = function(idx){
                const cur = listEdit.filter(function(_,i){return i!==idx;});
                _saveList(cur);
              };
              const _addNew = function(){
                _saveList([...listEdit, {nome:"", whatsapp:"", email:""}]);
              };

              const FIELDS = [
                {key:"nome",     label:"Nome",     ph:"Ex: Rodrigo Silva",       icon:"user"},
                {key:"whatsapp", label:"WhatsApp", ph:"(00) 0 0000-0000",        icon:"phone"},
                {key:"email",    label:"E-mail",   ph:"contato@cliente.com.br",  icon:"mail"},
              ];

              if(editMode){
                // Se ainda não tem nenhum contato, mostra 1 card em branco pronto pra preencher.
                // Quando o usuário digitar, _updateAt cria o item no state.
                const displayList = listEdit.length > 0 ? listEdit : [{nome:"",whatsapp:"",email:""}];
                return <div style={{display:"flex",flexDirection:"column",gap:12}}>
                  {displayList.map(function(ct,idx){
                    return <div key={(_currentUnit||"c")+"-"+idx} style={{background:"#fafbfc",border:"1px solid "+PB_BORDER2,borderRadius:10,padding:"12px 14px",position:"relative"}}>
                      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:10}}>
                        <div style={{color:"#0d9488",fontSize:10.5,fontWeight:800,letterSpacing:.5,textTransform:"uppercase"}}>Contato {idx+1}</div>
                        <button type="button" onClick={function(){_removeAt(idx);}} title="Remover contato"
                          style={{background:"#fff",border:"1px solid #fecaca",color:"#dc2626",borderRadius:7,padding:"4px 9px",fontSize:11,fontWeight:700,cursor:"pointer",fontFamily:PB_INTER,display:"inline-flex",alignItems:"center",gap:4,transition:"all .12s"}}
                          onMouseEnter={function(e){e.currentTarget.style.background="#fef2f2";}}
                          onMouseLeave={function(e){e.currentTarget.style.background="#fff";}}>
                          <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-2 14a2 2 0 01-2 2H9a2 2 0 01-2-2L5 6"/></svg>
                          Remover
                        </button>
                      </div>
                      <div style={{display:"grid",gridTemplateColumns:isMob?"1fr":"1fr 1fr",gap:10}}>
                        {FIELDS.map(function(f){
                          const isNome=f.key==="nome";
                          return <div key={f.key} style={isNome?{gridColumn:isMob?"auto":"span 2"}:{}}>
                            <div style={{color:PB_SOFT,fontSize:10.5,fontWeight:800,letterSpacing:.5,textTransform:"uppercase",marginBottom:5}}>{f.label}</div>
                            <input type="text" placeholder={f.ph}
                              value={ct[f.key]||""}
                              onChange={function(e){_updateAt(idx,{[f.key]:e.target.value});}}
                              style={{width:"100%",border:"1px solid "+PB_BORDER,borderRadius:9,padding:"9px 12px",fontSize:13,color:PB_TEXT,fontFamily:PB_INTER,outline:"none",boxSizing:"border-box"}}/>
                          </div>;
                        })}
                      </div>
                    </div>;
                  })}
                  <button type="button" onClick={_addNew}
                    style={{background:"linear-gradient(135deg,#0d9488,#14b8a6)",color:"#fff",border:"none",borderRadius:10,padding:"10px 18px",fontSize:12.5,fontWeight:700,cursor:"pointer",fontFamily:PB_INTER,display:"inline-flex",alignItems:"center",justifyContent:"center",gap:7,alignSelf:"flex-start",boxShadow:"0 4px 12px rgba(13,148,136,0.30)",letterSpacing:-.1,transition:"all .15s"}}
                    onMouseEnter={function(e){e.currentTarget.style.transform="translateY(-1px)";e.currentTarget.style.boxShadow="0 6px 16px rgba(13,148,136,0.40)";}}
                    onMouseLeave={function(e){e.currentTarget.style.transform="";e.currentTarget.style.boxShadow="0 4px 12px rgba(13,148,136,0.30)";}}>
                    <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round"><path d="M12 5v14M5 12h14"/></svg>
                    Adicionar contato
                  </button>
                </div>;
              }

              // ── Modo leitura ──
              if(listRead.length===0) return <_PbEmpty icon="phone" text={_isBioter?"Nenhum contato cadastrado pra esta unidade.":"Nenhum contato cadastrado."} sub={isAdmin?"Preencha abaixo pra cadastrar.":""}/>;
              return <div style={{display:"flex",flexDirection:"column",gap:12}}>
                {listRead.map(function(ct,idx){
                  const items = FIELDS.filter(function(it){return ct[it.key];});
                  if(items.length===0) return null;
                  return <div key={idx} style={{background:"#f0fdfa",border:"1px solid #99f6e4",borderRadius:12,padding:"12px 14px"}}>
                    {ct.nome && <div style={{color:"#134e4a",fontSize:14,fontWeight:800,letterSpacing:-.2,marginBottom:9,display:"flex",alignItems:"center",gap:8}}>
                      <div style={{width:28,height:28,borderRadius:8,background:"#0d9488",color:"#fff",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
                        <Ico n="user" size={13}/>
                      </div>
                      {ct.nome}
                    </div>}
                    <div style={{display:"grid",gridTemplateColumns:isMob?"1fr":"1fr 1fr",gap:8}}>
                      {items.filter(function(it){return it.key!=="nome";}).map(function(it){
                        return <div key={it.key} style={{display:"flex",alignItems:"center",gap:9,background:"#fff",border:"1px solid #99f6e480",borderRadius:9,padding:"7px 10px"}}>
                          <div style={{width:26,height:26,borderRadius:7,background:"#0d9488",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}><Ico n={it.icon} size={11} color="#fff"/></div>
                          <div style={{minWidth:0,flex:1}}>
                            <div style={{color:"#134e4a",fontSize:9,fontWeight:800,letterSpacing:.4,textTransform:"uppercase"}}>{it.label}</div>
                            <div style={{color:"#0f172a",fontSize:12.5,fontWeight:600,marginTop:1,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{ct[it.key]}</div>
                          </div>
                          <button type="button" onClick={function(){try{navigator.clipboard.writeText(ct[it.key]||"");if(typeof pixelsToast!=="undefined")pixelsToast.success("Copiado!",1500);}catch(_){}}} title="Copiar"
                            style={{background:"transparent",border:"none",color:"#0d9488",cursor:"pointer",padding:3,borderRadius:5,display:"inline-flex",alignItems:"center"}}>
                            <Ico n="copy" size={12}/>
                          </button>
                        </div>;
                      })}
                    </div>
                  </div>;
                })}
              </div>;
            })()}
          </PlaybookBlock>


          {/* Equipe do cliente — pessoas DA EMPRESA (cliente) que aparecem nos conteúdos */}
          <PlaybookBlock id="pb-time" title="Equipe do cliente" subtitle="Funcionários e sócios da empresa que aparecem nos vídeos — nome e cargo certos pro GC" icon="users" color="#6366f1">
            {(function(){
              const _eq=Array.isArray(data.equipe)?data.equipe:[];
              const _upd=function(lista){ onUpdate({equipe:lista}); };
              const _inic=function(n){
                const _p=String(n||"").trim().split(/\s+/).filter(Boolean);
                if(!_p.length)return "?";
                return (_p[0][0]+(_p.length>1?_p[_p.length-1][0]:"")).toUpperCase();
              };
              if(!editMode){
                return _eq.length===0
                  ? <_PbEmpty icon="users" text="Ninguém cadastrado ainda." sub={isAdmin?"Ative o modo edição pra cadastrar as pessoas da empresa (nome + cargo pro GC).":""}/>
                  : <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(230px,1fr))",gap:10}}>
                      {_eq.map(function(m,i){
                        return <div key={i} style={{display:"flex",alignItems:"flex-start",gap:11,background:"#fafbfc",border:"1px solid #eef0f3",borderRadius:12,padding:"11px 13px"}}>
                          <span style={{width:36,height:36,borderRadius:"50%",background:"#6366f114",border:"1px solid #6366f12b",color:"#6366f1",display:"inline-flex",alignItems:"center",justifyContent:"center",fontSize:12,fontWeight:800,flexShrink:0}}>{_inic(m.nome)}</span>
                          <div style={{minWidth:0}}>
                            <div style={{color:"#0f172a",fontSize:13,fontWeight:700,letterSpacing:-.15}}>{m.nome||"—"}</div>
                            <div style={{color:"#6366f1",fontSize:11,fontWeight:700,marginTop:1}}>{m.cargo||"—"}</div>
                            {m.obs?<div style={{color:"#94a3b8",fontSize:10.5,fontWeight:500,marginTop:3,lineHeight:1.45}}>{m.obs}</div>:null}
                          </div>
                        </div>;
                      })}
                    </div>;
              }
              return <div style={{display:"flex",flexDirection:"column",gap:8}}>
                {_eq.map(function(m,i){
                  return <div key={"eq"+i} style={{display:"flex",alignItems:"center",gap:9,background:"#fff",border:"1px solid #eef0f3",borderRadius:11,padding:"8px 11px",flexWrap:"wrap"}}>
                    <span style={{width:28,height:28,borderRadius:"50%",background:"#6366f114",border:"1px solid #6366f12b",color:"#6366f1",display:"inline-flex",alignItems:"center",justifyContent:"center",fontSize:10,fontWeight:800,flexShrink:0}}>{_inic(m.nome)}</span>
                    <input defaultValue={m.nome||""} placeholder="Nome da pessoa"
                      onBlur={function(e){const v=e.target.value;if(v!==(m.nome||""))_upd(_eq.map(function(x,j){return j===i?Object.assign({},x,{nome:v}):x;}));}}
                      style={{width:170,background:"#fff",border:"1px solid #e2e8f0",borderRadius:8,padding:"7px 11px",fontSize:12.5,fontWeight:700,color:"#0f172a",outline:"none",fontFamily:PB_INTER}}/>
                    <input defaultValue={m.cargo||""} placeholder="Cargo — ex: Sócio-diretor · Engenheira"
                      onBlur={function(e){const v=e.target.value;if(v!==(m.cargo||""))_upd(_eq.map(function(x,j){return j===i?Object.assign({},x,{cargo:v}):x;}));}}
                      style={{width:210,background:"#fff",border:"1px solid #e2e8f0",borderRadius:8,padding:"7px 11px",fontSize:12.5,color:"#0f172a",outline:"none",fontFamily:PB_INTER}}/>
                    <input defaultValue={m.obs||""} placeholder="Obs pro editor (opcional) — ex: como escrever no GC, onde aparece"
                      onBlur={function(e){const v=e.target.value;if(v!==(m.obs||""))_upd(_eq.map(function(x,j){return j===i?Object.assign({},x,{obs:v}):x;}));}}
                      style={{flex:1,minWidth:170,background:"#fff",border:"1px solid #e2e8f0",borderRadius:8,padding:"7px 11px",fontSize:12.5,color:"#0f172a",outline:"none",fontFamily:PB_INTER}}/>
                    <button type="button" onClick={function(){_upd(_eq.filter(function(_,j){return j!==i;}));}} title="Remover"
                      style={{background:"none",border:"none",color:"#cbd5e1",cursor:"pointer",padding:3,display:"inline-flex"}}
                      onMouseEnter={function(e){e.currentTarget.style.color="#dc2626";}}
                      onMouseLeave={function(e){e.currentTarget.style.color="#cbd5e1";}}>
                      <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
                    </button>
                  </div>;
                })}
                <button type="button" onClick={function(){_upd(_eq.concat([{nome:"",cargo:"",obs:""}]));}}
                  style={{background:"#6366f10d",border:"1px dashed #6366f155",borderRadius:10,padding:"9px 0",fontSize:11.5,fontWeight:800,color:"#6366f1",cursor:"pointer",fontFamily:PB_INTER}}>+ Adicionar pessoa</button>
              </div>;
            })()}
          </PlaybookBlock>

          {/* Marcar no post (@) — DIFERENTE do GC: aqui vão os @ pra marcar na publicação */}
          <PlaybookBlock id="pb-marcacoes" title="Marcar no post (@)" subtitle="Perfis pra marcar na publicação — @ do cliente, sócios, parceiros (não é o GC)" icon="tag" color="#0ea5e9">
            {(function(){
              // Bioter: marcações são POR UNIDADE (segue o seletor do topo) — igual aos Contatos.
              const _mk=_isBioter
                ? (Array.isArray((data.marcacoes_by_unit||{})[_unitTab])?data.marcacoes_by_unit[_unitTab]:[])
                : (Array.isArray(data.marcacoes)?data.marcacoes:[]);
              const _upd=function(lista){
                if(_isBioter) onUpdate({marcacoes_by_unit: Object.assign({},data.marcacoes_by_unit||{},{[_unitTab]:lista})});
                else onUpdate({marcacoes:lista});
              };
              const _uAtual=_isBioter&&typeof BIOTER_UNITS!=="undefined"?BIOTER_UNITS.find(function(x){return x.id===_unitTab;}):null;
              const _fmtAt=function(a){var v=String(a||"").trim();if(!v)return "";return "@"+v.replace(/^@+/,"");};
              const _chipUnidade=_isBioter?<div style={{marginBottom:12,display:"flex",alignItems:"center",gap:8}}>
                <span style={{background:"#0f172a",color:"#fff",borderRadius:99,padding:"5px 14px",fontSize:11.5,fontWeight:800,letterSpacing:-.1}}>{(_uAtual&&(_uAtual.pickerLabel||_uAtual.label))||_unitTab}</span>
                <span style={{color:"#94a3b8",fontSize:11,fontWeight:600}}>@ desta unidade — troque no seletor do topo</span>
              </div>:null;
              if(!editMode){
                const _vis=_mk.filter(function(m){return m&&(m.arroba||m.nome);});
                if(_vis.length===0) return <React.Fragment>{_chipUnidade}<_PbEmpty icon="tag" text="Nenhum @ cadastrado ainda." sub={isAdmin?"Ative o modo edição pra cadastrar os perfis pra marcar no post.":""}/></React.Fragment>;
                return <React.Fragment>{_chipUnidade}<div style={{display:"flex",flexWrap:"wrap",gap:8}}>
                      {_vis.map(function(m,i){
                        const _a=_fmtAt(m.arroba);
                        return <button key={i} type="button" title="Clique pra copiar o @"
                          onClick={function(){try{navigator.clipboard.writeText(_a||m.nome||"");if(typeof pixelsToast!=="undefined")pixelsToast.success("Copiado: "+(_a||m.nome));}catch(e){}}}
                          style={{display:"inline-flex",alignItems:"center",gap:8,background:"#f0f9ff",border:"1px solid #bae6fd",borderRadius:99,padding:"7px 13px",cursor:"pointer",fontFamily:PB_INTER}}>
                          <span style={{color:"#0284c7",fontSize:13,fontWeight:800,letterSpacing:-.2}}>{_a||"—"}</span>
                          {m.nome?<span style={{color:"#94a3b8",fontSize:11,fontWeight:600}}>· {m.nome}</span>:null}
                          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="#94a3b8" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><rect x="9" y="9" width="13" height="13" rx="2" ry="2"/><path d="M5 15H4a2 2 0 01-2-2V4a2 2 0 012-2h9a2 2 0 012 2v1"/></svg>
                        </button>;
                      })}
                    </div></React.Fragment>;
              }
              return <div style={{display:"flex",flexDirection:"column",gap:8}}>
                {_chipUnidade}
                {_mk.map(function(m,i){
                  return <div key={"mk"+(_isBioter?_unitTab:"")+i} style={{display:"flex",alignItems:"center",gap:9,background:"#fff",border:"1px solid #eef0f3",borderRadius:11,padding:"8px 11px",flexWrap:"wrap"}}>
                    <span style={{color:"#0284c7",fontSize:15,fontWeight:800,flexShrink:0}}>@</span>
                    <input defaultValue={String(m.arroba||"").replace(/^@+/,"")} placeholder="usuario (sem @) — ex: construschorr"
                      onBlur={function(e){const v=e.target.value.trim().replace(/^@+/,"");if(v!==String(m.arroba||"").replace(/^@+/,""))_upd(_mk.map(function(x,j){return j===i?Object.assign({},x,{arroba:v}):x;}));}}
                      style={{width:200,background:"#fff",border:"1px solid #e2e8f0",borderRadius:8,padding:"7px 11px",fontSize:12.5,fontWeight:700,color:"#0f172a",outline:"none",fontFamily:PB_INTER}}/>
                    <input defaultValue={m.nome||""} placeholder="Quem é (opcional) — ex: Perfil da empresa · Sócio João"
                      onBlur={function(e){const v=e.target.value;if(v!==(m.nome||""))_upd(_mk.map(function(x,j){return j===i?Object.assign({},x,{nome:v}):x;}));}}
                      style={{flex:1,minWidth:170,background:"#fff",border:"1px solid #e2e8f0",borderRadius:8,padding:"7px 11px",fontSize:12.5,color:"#0f172a",outline:"none",fontFamily:PB_INTER}}/>
                    <button type="button" onClick={function(){_upd(_mk.filter(function(_,j){return j!==i;}));}} title="Remover"
                      style={{background:"none",border:"none",color:"#cbd5e1",cursor:"pointer",padding:3,display:"inline-flex"}}
                      onMouseEnter={function(e){e.currentTarget.style.color="#dc2626";}}
                      onMouseLeave={function(e){e.currentTarget.style.color="#cbd5e1";}}>
                      <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
                    </button>
                  </div>;
                })}
                <button type="button" onClick={function(){_upd(_mk.concat([{arroba:"",nome:""}]));}}
                  style={{background:"#0ea5e90d",border:"1px dashed #0ea5e955",borderRadius:10,padding:"9px 0",fontSize:11.5,fontWeight:800,color:"#0284c7",cursor:"pointer",fontFamily:PB_INTER}}>+ Adicionar @</button>
              </div>;
            })()}
          </PlaybookBlock>

          {/* Comunicação da marca */}
          <PlaybookBlock id="pb-comunicacao" title="Comunicação da marca" subtitle="Tom de voz, estilo e linguagem" icon="sparkles" color="#0ea5e9">
            {editMode
              ? <_PbAutoTextarea value={editComm} onChange={e=>setEditComm(e.target.value)} onBlur={function(){if((editComm||"")!==(data.comunicacao||"")) onUpdate({comunicacao:editComm});}} rows={5}
                  placeholder="Tom de voz, estilo de mensagem, tipo de linguagem, o que a marca transmite..."
                  style={_pbInpStyle()}/>
              : (data.comunicacao
                  ? <PbProse text={data.comunicacao}/>
                  : <_PbEmpty icon="sparkles" text="Sem orientação de comunicação cadastrada." sub={isAdmin?"Preencha abaixo pra cadastrar.":""}/>)
            }
            {!editMode && Array.isArray(data.pilares) && data.pilares.length>0 && <div style={{marginTop:14,paddingTop:14,borderTop:"1px solid "+PB_BORDER2}}>
              <div style={{color:PB_SOFT,fontSize:10.5,fontWeight:800,letterSpacing:.5,textTransform:"uppercase",marginBottom:9}}>Pilares de comunicação</div>
              <div style={{display:"flex",flexWrap:"wrap",gap:7}}>
                {data.pilares.map((p,i)=>(
                  <span key={i} style={{background:"#e0f2fe",color:"#075985",border:"1px solid #bae6fd",borderRadius:99,padding:"4px 11px",fontSize:12,fontWeight:600,letterSpacing:-.1}}>{p}</span>
                ))}
              </div>
            </div>}
          </PlaybookBlock>

          {/* Instruções pro designer — no que focar nas imagens/artes deste cliente (03/09/2026) */}
          <PlaybookBlock id="pb-designer" title="Instruções pro designer" subtitle="O que as imagens e artes deste cliente devem mostrar — e o que evitar" icon="image" color="#ea580c">
            {editMode
              ? <_PbAutoTextarea value={editInstrDesigner} onChange={e=>setEditInstrDesigner(e.target.value)} onBlur={function(){if((editInstrDesigner||"")!==(data.instrucoesDesigner||"")) onUpdate({instrucoesDesigner:editInstrDesigner});}} rows={7}
                  placeholder="Ex.: focar no produto X, evitar imagem de IA, usar banco de imagens, mostrar obra pronta..."
                  style={_pbInpStyle()}/>
              : (data.instrucoesDesigner
                  ? <PbProse text={data.instrucoesDesigner}/>
                  : <_PbEmpty icon="image" text="Sem instruções pro designer cadastradas." sub={isAdmin?"Ative o modo de edição pra escrever.":""}/>)
            }
          </PlaybookBlock>

          {/* Orientacoes — Logo, paleta, fontes, tom de voz — inteira aqui no topo apos Comunicacao */}
          {/* Seções por cadeira: Design/Vídeo não precisam de tom de voz, hashtags e CTA (isso é Social/Comunicação).
              null = todas (Estratégia, sócios sem aba). */}
          {(function(){
            const _secs = _PB_CADEIRA_ATUAL==="video"  ? ["logos","paleta","fontes","siteredes"]
                        : _PB_CADEIRA_ATUAL==="design" ? ["logos","paleta","fontes","naofazer","siteredes"]
                        : null;
            const _sub = _secs ? "Logo, paleta de cores, fontes e links oficiais — referência única usada nos cartões"
                               : "Logo, paleta de cores, fontes, tom de voz — referência única usada nos cartões";
            return typeof COrientacoes==="function" && <PlaybookBlock id="pb-equipe" title="Orientações" subtitle={_sub} icon="sparkles" color={PB_PURPLE_DK}>
              <COrientacoes key={"orient-"+cl.id+"-"+(_PB_CADEIRA_ATUAL||"all")} cl={cl} sections={_secs||undefined}/>
            </PlaybookBlock>;
          })()}

          {/* Contatos — telefone, WhatsApp, endereço, site, redes sociais.
              Pra Bioter: cada unidade tem seus próprios contatos (Chapecó, Toledo, Castro...). */}

          {/* Produtos — lista do que trabalhamos pro cliente.
              Bioter: cada produto pode ter unidades específicas (varia por região). */}
          <PlaybookBlock id="pb-produtos" title="Produtos/serviços" subtitle={_isBioter?"Produtos por unidade — filtra pra ver os produtos daquela unidade":"Produtos e serviços trabalhados pelo cliente"} icon="package" color="#f59e0b">
            {_isBioter && typeof BIOTER_UNITS!=="undefined" && <div style={{marginBottom:14,paddingBottom:14,borderBottom:"1px solid "+PB_BORDER2}}>
              <div style={{color:PB_SOFT,fontSize:10,fontWeight:800,letterSpacing:.6,textTransform:"uppercase",marginBottom:7}}>Filtrar por unidade</div>
              <div style={{display:"inline-flex",background:"#f1f5f9",border:"1px solid #e2e8f0",borderRadius:10,padding:3,gap:2,flexWrap:"wrap"}}>
                {BIOTER_UNITS.map(function(u){
                  const active=_unitTabProd===u.id;
                  return <button key={u.id} type="button" onClick={function(){setUnitTabProd(u.id);}}
                    style={{background:active?"#0f172a":"transparent",border:"none",color:active?"#fff":"#475569",borderRadius:8,padding:"6px 12px",fontSize:12,fontWeight:active?700:600,cursor:"pointer",fontFamily:PB_INTER,letterSpacing:-.1,transition:"all .12s",boxShadow:active?"0 2px 6px rgba(15,23,42,.25)":"none"}}
                    onMouseEnter={function(e){if(!active) e.currentTarget.style.background="rgba(15,23,42,.06)";}}
                    onMouseLeave={function(e){if(!active) e.currentTarget.style.background="transparent";}}>
                    {u.pickerLabel||u.label}
                  </button>;
                })}
              </div>
            </div>}
            {editMode
              ? (function(){
                  // Filtro por unidade ativo? Se sim, mostra apenas produtos daquela unidade + habilita drag
                  const _editUnitFilter = _isBioter && _unitTabProd;
                  let _visibleEdit;
                  if(_editUnitFilter){
                    _visibleEdit=[];
                    (editProdutos||[]).forEach(function(p,gi){
                      const u=Array.isArray(p.unidades)?p.unidades:[];
                      if(u.length===0 || u.indexOf(_unitTabProd)>=0){
                        const _ord=(p.ordemPorUnidade&&typeof p.ordemPorUnidade[_unitTabProd]==="number")?p.ordemPorUnidade[_unitTabProd]:999+gi;
                        _visibleEdit.push({prod:p, gi:gi, ord:_ord});
                      }
                    });
                    _visibleEdit.sort(function(a,b){return a.ord-b.ord;});
                  } else {
                    _visibleEdit=(editProdutos||[]).map(function(p,gi){return {prod:p, gi:gi, ord:gi};});
                  }
                  return <div style={{display:"flex",flexDirection:"column",gap:10}}>
                  {_editUnitFilter && _visibleEdit.length>1 && <div style={{background:"#faf5ff",border:"1px dashed "+PB_PURPLE+"55",borderRadius:10,padding:"9px 13px",fontSize:12,color:PB_PURPLE_DK,fontWeight:600,display:"inline-flex",alignItems:"center",gap:8,alignSelf:"flex-start"}}>
                    <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><line x1="8" y1="6" x2="21" y2="6"/><line x1="8" y1="12" x2="21" y2="12"/><line x1="8" y1="18" x2="21" y2="18"/><line x1="3" y1="6" x2="3.01" y2="6"/><line x1="3" y1="12" x2="3.01" y2="12"/><line x1="3" y1="18" x2="3.01" y2="18"/></svg>
                    Arraste os cards pra ordenar por relevância nesta unidade
                  </div>}
                  {_visibleEdit.map(function(_item,filteredIdx){
                    const prod=_item.prod;
                    const pi=_item.gi;
                    const _dref = _dragProdRef.current;
                    const _isDragging = _dref.unitId===_unitTabProd && _dref.srcIdx===filteredIdx;
                    // Onde renderizar o indicador: ANTES do card alvo se movendo pra cima, ANTES tambem se movendo pra baixo (indicador aparece na posicao de insercao)
                    const _showDropBefore = _editUnitFilter && _dropIdx===filteredIdx && _dref.srcIdx>=0 && _dref.srcIdx!==filteredIdx;
                    return <React.Fragment key={pi}>
                      {_showDropBefore && <div style={{height:8,margin:"2px 0",background:"transparent",border:"2.5px dashed "+PB_PURPLE,borderRadius:99,boxShadow:"0 0 12px "+PB_PURPLE+"55",transition:"all .12s"}}/>}
                    <div
                      onDragOver={_editUnitFilter?function(e){e.preventDefault();e.dataTransfer.dropEffect="move";if(_dropIdx!==filteredIdx) setDropIdx(filteredIdx);}:undefined}
                      onDragLeave={_editUnitFilter?function(e){
                        // Só limpa se saiu de verdade do card (nao pra um filho)
                        var _rt = e.relatedTarget;
                        if(_rt && e.currentTarget.contains(_rt)) return;
                      }:undefined}
                      onDrop={_editUnitFilter?function(e){
                        e.preventDefault();
                        const dref=_dragProdRef.current;
                        if(dref.unitId===_unitTabProd && dref.srcIdx>=0 && dref.srcIdx!==filteredIdx){
                          _produtoReorderInUnit(_unitTabProd, dref.srcIdx, filteredIdx);
                        }
                        _dragProdRef.current={unitId:null,srcIdx:-1};
                        setDropIdx(-1);
                      }:undefined}
                      style={{background:"#fff",border:"1px solid "+(_isDragging?PB_PURPLE:"#e2e8f0"),borderRadius:14,padding:0,display:"flex",flexDirection:"column",cursor:"default",transition:"opacity .12s, border-color .12s",overflow:"hidden",boxShadow:"0 1px 2px rgba(15,23,42,.03)",opacity:_isDragging?0.35:1}}>
                    {/* Header — draggable APENAS aqui pra nao conflitar com inputs internos */}
                    {_editUnitFilter ? <div
                      draggable={true}
                      onDragStart={function(e){
                        _dragProdRef.current={unitId:_unitTabProd, srcIdx:filteredIdx};
                        e.dataTransfer.effectAllowed="move";
                        try{e.dataTransfer.setData("text/plain",String(filteredIdx));}catch(_){}
                        // Force re-render pra mostrar opacity via state
                        setDropIdx(filteredIdx);
                      }}
                      onDragEnd={function(e){
                        _dragProdRef.current={unitId:null,srcIdx:-1};
                        setDropIdx(-1);
                      }}
                      style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:10,padding:"12px 16px",background:"linear-gradient(90deg, #7c3aed 0%, #8b5cf6 100%)",color:"#fff",cursor:"grab",userSelect:"none"}}
                      onMouseDown={function(e){e.currentTarget.style.cursor="grabbing";}}
                      onMouseUp={function(e){e.currentTarget.style.cursor="grab";}}>
                      <div style={{display:"inline-flex",alignItems:"center",gap:10,fontSize:13,fontWeight:800,letterSpacing:-.1,minWidth:0,flex:1}}>
                        <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor" style={{opacity:.9,flexShrink:0}}><circle cx="9" cy="5" r="1.7"/><circle cx="15" cy="5" r="1.7"/><circle cx="9" cy="12" r="1.7"/><circle cx="15" cy="12" r="1.7"/><circle cx="9" cy="19" r="1.7"/><circle cx="15" cy="19" r="1.7"/></svg>
                        <span style={{background:"rgba(255,255,255,0.22)",padding:"3px 10px",borderRadius:99,fontSize:11,fontWeight:800,letterSpacing:.4,textTransform:"uppercase",flexShrink:0}}>Posição {filteredIdx+1}</span>
                        <span style={{fontWeight:800,fontSize:14,letterSpacing:-.2,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap",minWidth:0}}>{prod.nomePrincipalPt || prod.nome || "Sem nome"}</span>
                        {!(typeof _pxMob==="function"&&_pxMob())&&<span style={{opacity:.7,fontWeight:600,fontSize:11,letterSpacing:.1,flexShrink:0}}>· arraste pra reordenar</span>}
                      </div>
                      {/* Mobile: setas ▲▼ no lugar do arraste */}
                      {(typeof _pxMob==="function"&&_pxMob())&&<span style={{display:"inline-flex",gap:4,flexShrink:0}}>
                        <button type="button" draggable={false} disabled={filteredIdx===0} onClick={function(e){e.stopPropagation();_produtoReorderInUnit(_unitTabProd,filteredIdx,filteredIdx-1);}} title="Subir"
                          style={{background:"rgba(255,255,255,0.18)",border:"none",color:"#fff",borderRadius:8,width:36,height:36,display:"inline-flex",alignItems:"center",justifyContent:"center",opacity:filteredIdx===0?.35:1}}>▲</button>
                        <button type="button" draggable={false} disabled={filteredIdx>=_visibleEdit.length-1} onClick={function(e){e.stopPropagation();_produtoReorderInUnit(_unitTabProd,filteredIdx,filteredIdx+1);}} title="Descer"
                          style={{background:"rgba(255,255,255,0.18)",border:"none",color:"#fff",borderRadius:8,width:36,height:36,display:"inline-flex",alignItems:"center",justifyContent:"center",opacity:filteredIdx>=_visibleEdit.length-1?.35:1}}>▼</button>
                      </span>}
                      <button type="button" onClick={function(){_produtoDel(pi);}} title="Remover produto"
                        draggable={false}
                        onMouseDown={function(e){e.stopPropagation();}}
                        style={{background:"rgba(255,255,255,0.15)",border:"none",color:"#fff",cursor:"pointer",padding:"6px 8px",display:"inline-flex",alignItems:"center",justifyContent:"center",borderRadius:8,transition:"background .12s"}}
                        onMouseEnter={function(e){e.currentTarget.style.background="rgba(220,38,38,0.85)";}}
                        onMouseLeave={function(e){e.currentTarget.style.background="rgba(255,255,255,0.15)";}}>
                        <Ico n="trash" size={14}/>
                      </button>
                    </div> : <div style={{display:"flex",justifyContent:"flex-end",padding:"8px 8px 0 8px"}}>
                      <button type="button" onClick={function(){_produtoDel(pi);}} title="Remover produto"
                        style={{background:"transparent",border:"none",color:"#cbd5e1",cursor:"pointer",padding:4,display:"inline-flex",alignItems:"center",justifyContent:"center",borderRadius:6}}
                        onMouseEnter={function(e){e.currentTarget.style.background="#fee2e2";e.currentTarget.style.color="#dc2626";}}
                        onMouseLeave={function(e){e.currentTarget.style.background="transparent";e.currentTarget.style.color="#cbd5e1";}}>
                        <Ico n="trash" size={14}/>
                      </button>
                    </div>}
                    <div style={{display:"flex",flexDirection:"column",gap:14,padding:_editUnitFilter?"14px 16px 16px 16px":"4px 16px 16px 16px"}}>
                      {/* Galeria grandona de imagens do produto */}
                      {(function(){
                        const _urls = Array.isArray(prod.imgUrls) && prod.imgUrls.length ? prod.imgUrls : (prod.imgUrl?[prod.imgUrl]:[]);
                        return <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
                          {_urls.map(function(_url,_ii){
                            return <div key={_ii} style={{position:"relative",width:130,height:130,borderRadius:12,overflow:"hidden",background:"#f8fafc",border:"1px solid #e2e8f0",flexShrink:0}}>
                              <img src={_url} alt="" referrerPolicy="no-referrer" loading="lazy" decoding="async" onClick={function(){setProdLightbox({urls:_urls, idx:_ii});}} style={{width:"100%",height:"100%",objectFit:"cover",display:"block",cursor:"zoom-in"}}/>
                              <button type="button" onClick={function(e){e.stopPropagation();_produtoRemoveImg(pi,_ii);}} title="Remover foto"
                                style={{position:"absolute",top:5,right:5,background:"rgba(15,23,42,.75)",border:"none",borderRadius:99,width:22,height:22,color:"#fff",cursor:"pointer",display:"inline-flex",alignItems:"center",justifyContent:"center",fontSize:14,fontWeight:700,lineHeight:1,padding:0}}>×</button>
                            </div>;
                          })}
                          <button type="button" onClick={function(){_pbProdutoUploadImg(pi,function(_pi,_patch){ if(_patch && _patch.imgUrl){ _produtoAddImgToArr(_pi, _patch.imgUrl); } });}}
                            style={{width:130,height:130,borderRadius:12,background:"#fafbfc",border:"1.5px dashed #cbd5e1",cursor:"pointer",padding:0,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",gap:6,color:"#64748b",fontFamily:PB_INTER,transition:"all .12s",flexShrink:0}}
                            onMouseEnter={function(e){e.currentTarget.style.borderColor=PB_PURPLE;e.currentTarget.style.background="#faf5ff";e.currentTarget.style.color=PB_PURPLE;}}
                            onMouseLeave={function(e){e.currentTarget.style.borderColor="#cbd5e1";e.currentTarget.style.background="#fafbfc";e.currentTarget.style.color="#64748b";}}>
                            <Ico n="image" size={22} color="currentColor"/>
                            <span style={{fontSize:10.5,fontWeight:800,letterSpacing:.3,textTransform:"uppercase"}}>+ {_urls.length>0?"Outra foto":"Adicionar foto"}</span>
                          </button>
                        </div>;
                      })()}
                      {/* Grid PT | ES — ES so aparece na aba Paraguay (Bioter) */}
                      {(function(){
                        const _showEsEdit = _isBioter && _unitTabProd === "paraguay";
                        return <div style={{display:"grid",gridTemplateColumns:_showEsEdit?"1fr 1fr":"1fr",gap:10}}>
                          <div style={{background:"#f8fafc",border:"1px solid #e2e8f0",borderRadius:10,padding:"10px 12px",display:"flex",flexDirection:"column",gap:7}}>
                            <div style={{display:"inline-flex",alignItems:"center",gap:6,fontSize:10.5,fontWeight:800,color:"#005825",letterSpacing:.4,textTransform:"uppercase"}}>
                              <svg width="16" height="11.2" viewBox="0 0 20 14"><rect width="20" height="14" fill="#009c3b"/><polygon points="10,2 18,7 10,12 2,7" fill="#ffdf00"/><circle cx="10" cy="7" r="2.6" fill="#002776"/></svg>
                              Português
                            </div>
                            <input type="text" placeholder="Nome principal (PT)" value={prod.nomePrincipalPt!==undefined?prod.nomePrincipalPt:(prod.nome||"")}
                              onChange={function(e){_produtoUpd(pi,{nomePrincipalPt:e.target.value, nome:e.target.value});}}
                              style={{width:"100%",border:"1px solid "+PB_BORDER,borderRadius:8,padding:"8px 11px",fontSize:13,fontWeight:700,color:PB_TEXT,fontFamily:PB_INTER,outline:"none",boxSizing:"border-box",background:"#fff"}}/>
                            <input type="text" placeholder="Outros nomes (ex: Fossa, Biofábrica)" value={Array.isArray(prod.nomesPt)?prod.nomesPt.join(", "):(prod.nomesPt||"")}
                              onChange={function(e){_produtoUpd(pi,{nomesPt:e.target.value});}}
                              style={{width:"100%",border:"1px solid "+PB_BORDER,borderRadius:8,padding:"7px 11px",fontSize:12,color:PB_TEXT,fontFamily:PB_INTER,outline:"none",boxSizing:"border-box",background:"#fff"}}/>
                          </div>
                          {_showEsEdit && <div style={{background:"#f8fafc",border:"1px solid #e2e8f0",borderRadius:10,padding:"10px 12px",display:"flex",flexDirection:"column",gap:7}}>
                            <div style={{display:"inline-flex",alignItems:"center",gap:6,fontSize:10.5,fontWeight:800,color:"#7f1414",letterSpacing:.4,textTransform:"uppercase"}}>
                              <svg width="16" height="11.2" viewBox="0 0 20 14"><rect width="20" height="4.66" fill="#d52b1e"/><rect y="4.66" width="20" height="4.66" fill="#fff"/><rect y="9.32" width="20" height="4.66" fill="#0038a8"/></svg>
                              Español
                            </div>
                            <input type="text" placeholder="Nombre principal (ES)" value={prod.nomePrincipalEs||""}
                              onChange={function(e){_produtoUpd(pi,{nomePrincipalEs:e.target.value});}}
                              style={{width:"100%",border:"1px solid "+PB_BORDER,borderRadius:8,padding:"8px 11px",fontSize:13,fontWeight:700,color:PB_TEXT,fontFamily:PB_INTER,outline:"none",boxSizing:"border-box",background:"#fff"}}/>
                            <input type="text" placeholder="Otros nombres (ej: Estanque, Laguna)" value={Array.isArray(prod.nomesEs)?prod.nomesEs.join(", "):(prod.nomesEs||"")}
                              onChange={function(e){_produtoUpd(pi,{nomesEs:e.target.value});}}
                              style={{width:"100%",border:"1px solid "+PB_BORDER,borderRadius:8,padding:"7px 11px",fontSize:12,color:PB_TEXT,fontFamily:PB_INTER,outline:"none",boxSizing:"border-box",background:"#fff"}}/>
                          </div>}
                        </div>;
                      })()}
                      <_PbAutoTextarea placeholder="Descrição / explicação rápida do produto..." value={prod.descricao||""}
                        onChange={function(e){_produtoUpd(pi,{descricao:e.target.value});}}
                        rows={2}
                        style={{width:"100%",border:"1px solid "+PB_BORDER,borderRadius:8,padding:"9px 12px",fontSize:13,color:PB_TEXT,fontFamily:PB_INTER,outline:"none",boxSizing:"border-box",background:"#fff",lineHeight:1.5}}/>
                      {_isBioter&&typeof BIOTER_UNITS!=="undefined"&&<div>
                        <div style={{color:PB_SOFT,fontSize:10,fontWeight:800,letterSpacing:.5,textTransform:"uppercase",marginBottom:7}}>Unidades onde se aplica</div>
                        <div style={{display:"flex",flexWrap:"wrap",gap:6}}>
                          {BIOTER_UNITS.map(function(u){
                            const active=Array.isArray(prod.unidades)&&prod.unidades.indexOf(u.id)>=0;
                            return <button type="button" key={u.id} onClick={function(){_produtoToggleUnit(pi,u.id);}}
                              style={{background:active?u.color:"#fff",border:"1px solid "+(active?u.color:"#e2e8f0"),color:active?"#fff":"#475569",borderRadius:99,padding:"4px 12px",fontSize:11.5,fontWeight:active?800:600,cursor:"pointer",fontFamily:PB_INTER,transition:"all .12s"}}>
                              {u.pickerLabel||u.label}
                            </button>;
                          })}
                        </div>
                      </div>}
                    </div>
                  </div>
                  </React.Fragment>;})}
                  <button onClick={_produtoAdd}
                    style={{background:"#fff",border:"1.5px dashed #cbd5e1",borderRadius:12,padding:"14px 18px",color:"#64748b",fontSize:13,fontWeight:700,cursor:"pointer",fontFamily:PB_INTER,display:"inline-flex",alignItems:"center",justifyContent:"center",gap:8,transition:"all .12s"}}
                    onMouseEnter={function(e){e.currentTarget.style.borderColor=PB_PURPLE;e.currentTarget.style.background="#faf5ff";e.currentTarget.style.color=PB_PURPLE;}}
                    onMouseLeave={function(e){e.currentTarget.style.borderColor="#cbd5e1";e.currentTarget.style.background="#fff";e.currentTarget.style.color="#64748b";}}>
                    <Ico n="plus" size={14}/> Adicionar produto
                  </button>
                </div>;
                })()
              : (function(){
                  // Sort por ordemPorUnidade quando filtro ativo
                  const _allProds = Array.isArray(data.produtos)?data.produtos:[];
                  const _filtered = (_isBioter && _unitTabProd)
                    ? _allProds.filter(function(p){
                        const u = Array.isArray(p.unidades)?p.unidades:[];
                        return u.length===0 || u.indexOf(_unitTabProd)>=0;
                      }).map(function(p,idx){
                        const _ord=(p.ordemPorUnidade&&typeof p.ordemPorUnidade[_unitTabProd]==="number")?p.ordemPorUnidade[_unitTabProd]:999+idx;
                        return {p:p, ord:_ord};
                      }).sort(function(a,b){return a.ord-b.ord;}).map(function(x){return x.p;})
                    : _allProds;
                  return _filtered.length>0
                    ? <div style={{display:"flex",flexDirection:"column",gap:8}}>
                      {_filtered.map(function(prod,pi){
                        const unitsList=Array.isArray(prod.unidades)?prod.unidades:[];
                        const unitObjs=_isBioter&&typeof BIOTER_UNITS!=="undefined"?BIOTER_UNITS.filter(function(u){return unitsList.indexOf(u.id)>=0;}):[];
                        const _hasFilter = _isBioter && _unitTabProd;
                        const _viewUrls = Array.isArray(prod.imgUrls) && prod.imgUrls.length ? prod.imgUrls : (prod.imgUrl?[prod.imgUrl]:[]);
                        return <div key={pi} style={{background:"#fff",border:"1px solid #e2e8f0",borderRadius:14,padding:16,display:"flex",gap:16,alignItems:"flex-start",boxShadow:"0 1px 2px rgba(15,23,42,.03)",transition:"box-shadow .15s, border-color .15s"}}
                          onMouseEnter={function(e){e.currentTarget.style.borderColor="#cbd5e1";e.currentTarget.style.boxShadow="0 4px 12px rgba(15,23,42,.06)";}}
                          onMouseLeave={function(e){e.currentTarget.style.borderColor="#e2e8f0";e.currentTarget.style.boxShadow="0 1px 2px rgba(15,23,42,.03)";}}>
                          {_viewUrls.length>0
                            ? <div style={{display:"flex",flexDirection:"column",gap:6,flexShrink:0}}>
                                <img src={_viewUrls[0]} alt={prod.nome||""} referrerPolicy="no-referrer" loading="lazy" decoding="async" onClick={function(){setProdLightbox({urls:_viewUrls, idx:0});}} style={{width:160,height:160,borderRadius:12,objectFit:"cover",border:"1px solid #e2e8f0",background:"#f8fafc",display:"block",cursor:"zoom-in"}}/>
                                {_viewUrls.length>1 && <div style={{display:"flex",gap:5,flexWrap:"wrap",maxWidth:160}}>
                                  {_viewUrls.slice(1,5).map(function(_u,_ii){
                                    return <img key={_ii} src={_u} alt="" referrerPolicy="no-referrer" loading="lazy" decoding="async" onClick={function(){setProdLightbox({urls:_viewUrls, idx:_ii+1});}} style={{width:36,height:36,borderRadius:7,objectFit:"cover",border:"1px solid #e2e8f0",background:"#f8fafc",display:"block",cursor:"zoom-in"}}/>;
                                  })}
                                  {_viewUrls.length>5 && <div onClick={function(){setProdLightbox({urls:_viewUrls, idx:5});}} style={{width:36,height:36,borderRadius:7,background:"#f1f5f9",border:"1px solid #e2e8f0",display:"flex",alignItems:"center",justifyContent:"center",color:"#64748b",fontSize:11,fontWeight:800,cursor:"zoom-in"}}>+{_viewUrls.length-5}</div>}
                                </div>}
                              </div>
                            : <div style={{width:160,height:160,borderRadius:12,background:"#f8fafc",border:"1px solid #e2e8f0",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0,color:"#cbd5e1"}}><Ico n="package" size={40} color="currentColor"/></div>
                          }
                          <div style={{flex:1,minWidth:0}}>
                            {!_hasFilter && _isBioter && (unitObjs.length>0 || unitsList.length===0) && <div style={{display:"flex",gap:4,flexWrap:"wrap",marginBottom:8}}>
                              {unitObjs.map(function(u){return <span key={u.id} style={{background:u.color+"18",color:u.color,border:"1px solid "+u.color+"55",borderRadius:99,padding:"2px 9px",fontSize:10,fontWeight:800,letterSpacing:.2}}>{u.pickerLabel||u.label}</span>;})}
                              {unitsList.length===0 && <span style={{background:"#f1f5f9",color:"#64748b",border:"1px solid #e2e8f0",borderRadius:99,padding:"2px 9px",fontSize:10,fontWeight:700,letterSpacing:.2,textTransform:"uppercase"}}>Todas as unidades</span>}
                            </div>}
                            {(function(){
                              const _nomePt=prod.nomePrincipalPt||prod.nome||"";
                              const _nomeEs=prod.nomePrincipalEs||"";
                              // Parse defensivo — aceita string com vírgula OU array (legado)
                              const _parseNomes=function(x){
                                if(Array.isArray(x)) return x.filter(function(s){return s && String(s).trim();}).map(function(s){return String(s).trim();});
                                if(typeof x==="string") return x.split(",").map(function(s){return s.trim();}).filter(Boolean);
                                return [];
                              };
                              const _outrosPt=_parseNomes(prod.nomesPt);
                              const _outrosEs=_parseNomes(prod.nomesEs);
                              const _hasPt=_nomePt||_outrosPt.length>0;
                              // Espanhol só aparece quando aba selecionada é Paraguay
                              const _showEs = _isBioter && _unitTabProd==="paraguay";
                              const _hasEs=_showEs && (_nomeEs||_outrosEs.length>0);
                              if(!_hasPt && !_hasEs) return <div style={{color:"#94a3b8",fontSize:13,fontStyle:"italic"}}>(sem nome)</div>;
                              return <div style={{display:"grid",gridTemplateColumns:(_hasPt&&_hasEs)?"1fr 1fr":"1fr",gap:10}}>
                                {_hasPt && <div style={{background:"#f0fdf4",border:"1px solid #86efac",borderRadius:9,padding:"9px 11px"}}>
                                  <div style={{display:"inline-flex",alignItems:"center",gap:5,marginBottom:5,fontSize:10,fontWeight:800,color:"#005825",letterSpacing:.4,textTransform:"uppercase"}}>
                                    <svg width="14" height="10" viewBox="0 0 20 14"><rect width="20" height="14" fill="#009c3b"/><polygon points="10,2 18,7 10,12 2,7" fill="#ffdf00"/><circle cx="10" cy="7" r="2.6" fill="#002776"/></svg>
                                    Português
                                  </div>
                                  <div style={{color:"#0f172a",fontWeight:800,fontSize:14,letterSpacing:-.2,lineHeight:1.25}}>{_nomePt||"—"}</div>
                                  {_outrosPt.length>0 && <div style={{color:"#475569",fontSize:11.5,fontWeight:500,marginTop:3,lineHeight:1.4}}>{_outrosPt.join(" · ")}</div>}
                                </div>}
                                {_hasEs && <div style={{background:"#fef2f2",border:"1px solid #fca5a5",borderRadius:9,padding:"9px 11px"}}>
                                  <div style={{display:"inline-flex",alignItems:"center",gap:5,marginBottom:5,fontSize:10,fontWeight:800,color:"#7f1414",letterSpacing:.4,textTransform:"uppercase"}}>
                                    <svg width="14" height="10" viewBox="0 0 20 14"><rect width="20" height="4.66" fill="#d52b1e"/><rect y="4.66" width="20" height="4.66" fill="#fff"/><rect y="9.32" width="20" height="4.66" fill="#0038a8"/></svg>
                                    Español
                                  </div>
                                  <div style={{color:"#0f172a",fontWeight:800,fontSize:14,letterSpacing:-.2,lineHeight:1.25,fontStyle:"italic"}}>{_nomeEs||"—"}</div>
                                  {_outrosEs.length>0 && <div style={{color:"#475569",fontSize:11.5,fontWeight:500,marginTop:3,lineHeight:1.4,fontStyle:"italic"}}>{_outrosEs.join(" · ")}</div>}
                                </div>}
                              </div>;
                            })()}
                            {prod.descricao&&<div style={{color:"#475569",fontSize:12.5,lineHeight:1.5,marginTop:8}}>{prod.descricao}</div>}
                          </div>
                        </div>;
                      })}
                    </div>
                    : <_PbEmpty icon="package" text={_isBioter?"Nenhum produto cadastrado pra esta unidade.":"Nenhum produto cadastrado."} sub={isAdmin?"Use o botão abaixo pra adicionar.":""}/>;
                })()
            }
                    </PlaybookBlock>

          {/* Exemplos de chamadas (aprovadas + proibidas) */}
          {!editMode && (Array.isArray(data.chamadasAprovadas)&&data.chamadasAprovadas.length>0 || Array.isArray(data.chamadasProibidas)&&data.chamadasProibidas.length>0) &&
            <PlaybookBlock id="pb-chamadas" title="Exemplos de chamadas" subtitle="Aprovadas e proibidas para os cards" icon="messageCircle" color="#10b981">
              {Array.isArray(data.chamadasAprovadas)&&data.chamadasAprovadas.length>0 && <div style={{marginBottom:14}}>
                <div style={{display:"inline-flex",alignItems:"center",gap:6,background:"#dcfce7",color:"#166534",borderRadius:99,padding:"3px 10px",fontSize:10.5,fontWeight:800,letterSpacing:.4,textTransform:"uppercase",marginBottom:10}}>
                  <Ico n="check" size={12} color="#166534"/> Aprovadas
                </div>
                <div style={{display:"flex",flexDirection:"column",gap:7}}>
                  {data.chamadasAprovadas.map((s,i)=>(
                    <div key={i} style={{background:"#f0fdf4",border:"1px solid #bbf7d0",borderRadius:9,padding:"9px 12px",color:"#14532d",fontSize:13,lineHeight:1.5,fontWeight:500}}>{s}</div>
                  ))}
                </div>
              </div>}
              {Array.isArray(data.chamadasProibidas)&&data.chamadasProibidas.length>0 && <div>
                <div style={{display:"inline-flex",alignItems:"center",gap:6,background:"#fee2e2",color:"#991b1b",borderRadius:99,padding:"3px 10px",fontSize:10.5,fontWeight:800,letterSpacing:.4,textTransform:"uppercase",marginBottom:10}}>
                  <Ico n="x" size={12} color="#991b1b"/> Evitar
                </div>
                <div style={{display:"flex",flexDirection:"column",gap:7}}>
                  {data.chamadasProibidas.map((s,i)=>(
                    <div key={i} style={{background:"#fef2f2",border:"1px solid #fecaca",borderRadius:9,padding:"9px 12px",color:"#7f1d1d",fontSize:13,lineHeight:1.5,fontWeight:500,textDecoration:"line-through",textDecorationColor:"#fca5a5"}}>{s}</div>
                  ))}
                </div>
              </div>}
            </PlaybookBlock>}

          {/* Templates específicos (só design) — vários templates por playbook (ex: Ajuste de template, Carrossel, Story...) */}
          {hasTemplate && _pbBlocoVisivel("pb-templates") && <div id="pb-templates" style={{display:"flex",flexDirection:"column",gap:14}}>
            <div style={{display:"flex",alignItems:"center",gap:11,paddingBottom:4,borderBottom:"1px solid "+PB_BORDER2,marginBottom:2}}>
              <div style={{width:32,height:32,borderRadius:9,background:PB_PURPLE_BG,border:"1px solid "+PB_PURPLE_BD,display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
                <Ico n="image" size={15} color={PB_PURPLE_DK}/>
              </div>
              <div style={{minWidth:0}}>
                <div style={{color:PB_INK,fontWeight:800,fontSize:16,letterSpacing:-.3}}>Templates</div>
                <div style={{color:PB_MUTE,fontSize:12,marginTop:2}}>Referências visuais reutilizáveis pros formatos deste cliente</div>
              </div>
            </div>
            {templates.map(tpl=>(
              <PlaybookTemplateBlock key={tpl.id} tpl={tpl} isAdmin={isAdmin} editMode={editMode}
                onUpdate={(patch)=>onUpdateArea({templates:(areaData.templates||[]).map(t=>t.id===tpl.id?Object.assign({},t,patch):t)})}
                onRemove={()=>{if(typeof pixelsConfirm==="function"){pixelsConfirm({title:"Excluir este template?",message:'"'+(tpl.title||"Template")+'" será removido.',confirmLabel:"Excluir",danger:true,onConfirm:function(){onUpdateArea({templates:(areaData.templates||[]).filter(t=>t.id!==tpl.id)});}});}else if(confirm("Excluir este template?")){onUpdateArea({templates:(areaData.templates||[]).filter(t=>t.id!==tpl.id)});}}}/>
            ))}
            {editMode && isAdmin && <button type="button" onClick={()=>{
              const _id="tpl-"+Date.now();
              const _newTpl={id:_id,title:"Novo template",subtitle:"Descreva pra que serve",imgUrl:"",descricao:"",rules:[],summary:""};
              onUpdateArea({templates:[...(areaData.templates||[]),_newTpl]});
            }} style={{background:"#fff",border:"1.5px dashed "+PB_PURPLE_BD,borderRadius:14,padding:"16px 20px",color:PB_PURPLE_DK,fontSize:13,fontWeight:700,cursor:"pointer",fontFamily:PB_INTER,display:"inline-flex",alignItems:"center",justifyContent:"center",gap:8,transition:"all .15s"}}
              onMouseEnter={e=>{e.currentTarget.style.background=PB_PURPLE_BG;e.currentTarget.style.borderColor=PB_PURPLE;}}
              onMouseLeave={e=>{e.currentTarget.style.background="#fff";e.currentTarget.style.borderColor=PB_PURPLE_BD;}}>
              <Ico n="plus" size={15} color={PB_PURPLE_DK}/> Adicionar novo template
            </button>}
            {templates.length===0 && !editMode && <_PbEmpty icon="image" text="Nenhum template cadastrado." sub={isAdmin?"Use o botão abaixo pra adicionar templates.":""}/>}
          </div>}

          {/* Orientações para a equipe — só na área Design.
              Logos, paleta de cores copiável, fontes, tom de voz, hashtags, CTA,
              não-fazer e redes sociais. Mesma fonte (Supabase clients.orientacoes)
              que o card de cada cliente lê — alterações refletem em todo lugar. */}
          {/* Bloco Orientacoes ja renderizado no topo apos Comunicacao. Aqui: nada. */}

          {/* Processos técnicos — GLOBAIS pra todos os vídeos (sincronizado entre clientes via team_data) */}
          {!_pbProcTopo && (area==="all" || area==="video") && <PlaybookBlock id="pb-processos" title="Processos técnicos de vídeo" subtitle="Etapas obrigatórias pra todo vídeo da agência (aplica em todos os clientes)" icon="play" color="#0ea5e9">
            <_PbVideoProcesses isAdmin={isAdmin}/>
          </PlaybookBlock>}

          {/* Configuração de publicação — Social Media (perfis a marcar, cadência, particularidades) */}
          {(area==="all" || area==="social") && <PlaybookBlock id="pb-social" title="Publicação social" subtitle="Perfis a marcar, cadência, tipos de post e particularidades desse cliente" icon="users" color="#ec4899">
            <_PbSocialConfig areaData={areaData} isAdmin={isAdmin} editMode={editMode} onUpdate={onUpdateArea} clientId={cl.id}/>
          </PlaybookBlock>}

          {/* Orientações visuais — imagem + descrição por área. Aparece nos cards do setor correspondente. */}
          <PlaybookBlock id="pb-orientacoes-visuais" title="Orientações visuais" subtitle={area==="all" ? "Referências pra equipe — aparecem automaticamente nos cards deste cliente" : ("Referências visuais desta área — aparecem automaticamente nos cards de "+areaCfg.label)} icon="image" color={areaCfg.color||PB_PURPLE_DK}>
            <_PbVisualOrientations areaData={areaData} isAdmin={isAdmin} editMode={editMode} onUpdate={onUpdateArea} areaColor={areaCfg.color||PB_PURPLE_DK}/>
          </PlaybookBlock>

        </div>

        {/* ───── COLUNA LATERAL ───── */}
        <div style={{display:"flex",flexDirection:"column",gap:14,minWidth:0}}>

          {/* Resumo rápido */}
          <div style={{background:"#fff",border:"1px solid "+PB_BORDER,borderRadius:14,padding:"14px 16px",fontFamily:PB_INTER}}>
            <div style={{color:PB_SOFT,fontSize:10,fontWeight:800,letterSpacing:.6,textTransform:"uppercase",marginBottom:10}}>Resumo</div>
            <div style={{display:"flex",flexDirection:"column",gap:9}}>
              <PbMini icon="building" label="Cliente" value={cl.name}/>
              {cl.sector && <PbMini icon="tag" label="Setor" value={cl.sector}/>}
              <PbMini icon={areaCfg.icon} label="Área" value={areaCfg.label}/>
              <PbMini icon="checkCircle" label="Checklist" value={totalCheck>0?(doneCheck+"/"+totalCheck+" conferidos"):"sem itens"}/>
            </div>
          </div>

          {/* Google Drive — link clicável pra pasta do cliente */}
          {(function(){
            const _driveUrl = (data && data.driveUrl) || "";
            const _hasDrive = !!_driveUrl.trim();
            return <div style={{background:"#fff",border:"1px solid "+PB_BORDER,borderRadius:14,padding:"14px 16px",fontFamily:PB_INTER}}>
              <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:editMode?10:(_hasDrive?10:0)}}>
                <div style={{width:34,height:34,borderRadius:9,background:"#eff6ff",border:"1px solid #bfdbfe",display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
                  <svg width="17" height="15" viewBox="0 0 87 78" xmlns="http://www.w3.org/2000/svg"><path d="M14.5 78L0 52.5L28 4H57L43 28.5L14.5 78Z" fill="#0066DA"/><path d="M43 28.5L57 4H87L72.5 28.5L43 28.5Z" fill="#EA4335"/><path d="M43 28.5L14.5 78H72.5L87 52.5L43 28.5Z" fill="#00832D"/><path d="M28 4L14.5 27L43 28.5L28 4Z" fill="#FFBA00"/></svg>
                </div>
                <div style={{minWidth:0,flex:1}}>
                  <div style={{color:PB_INK,fontWeight:800,fontSize:13.5,letterSpacing:-.2}}>Google Drive</div>
                  <div style={{color:PB_MUTE,fontSize:11,marginTop:1}}>pasta do cliente</div>
                </div>
              </div>
              {editMode && isAdmin
                ? <input type="url" value={_driveUrl}
                    onChange={function(e){ if(typeof onUpdate==="function") onUpdate({driveUrl: e.target.value}); }}
                    placeholder="Cole aqui: https://drive.google.com/…"
                    style={{width:"100%",background:"#fafafa",border:"1px solid "+PB_BORDER,borderRadius:9,padding:"9px 12px",color:PB_INK,fontSize:12.5,outline:"none",fontFamily:PB_INTER,boxSizing:"border-box"}}/>
                : (_hasDrive
                    ? <a href={_driveUrl} target="_blank" rel="noreferrer"
                        style={{display:"flex",alignItems:"center",justifyContent:"center",gap:7,background:"#eff6ff",border:"1px solid #bfdbfe",borderRadius:10,padding:"10px 14px",color:"#1e40af",fontSize:12.5,fontWeight:700,cursor:"pointer",textDecoration:"none",transition:"all .12s"}}
                        onMouseEnter={function(e){e.currentTarget.style.background="#dbeafe";e.currentTarget.style.borderColor="#93c5fd";}}
                        onMouseLeave={function(e){e.currentTarget.style.background="#eff6ff";e.currentTarget.style.borderColor="#bfdbfe";}}>
                        Abrir pasta no Drive
                        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><path d="M18 13v6a2 2 0 01-2 2H5a2 2 0 01-2-2V8a2 2 0 012-2h6"/><polyline points="15 3 21 3 21 9"/><line x1="10" y1="14" x2="21" y2="3"/></svg>
                      </a>
                    : <div style={{color:PB_SOFT,fontSize:11.5,fontStyle:"italic",padding:"6px 2px"}}>Nenhum link cadastrado{isAdmin?" — clique em Editar pra adicionar":""}.</div>
                  )
              }
            </div>;
          })()}

          {/* Checklist com progresso */}
          {_pbBlocoVisivel("pb-checklist") && <div id="pb-checklist" style={{background:"#fff",border:"1px solid "+PB_BORDER,borderRadius:14,padding:"14px 16px",fontFamily:PB_INTER}}>
            <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:12}}>
              <div style={{width:36,height:36,borderRadius:11,background:"linear-gradient(135deg,#334155 0%,#0f172a 100%)",display:"flex",alignItems:"center",justifyContent:"center",boxShadow:"0 4px 12px rgba(15,23,42,.28)"}}>
                <Ico n="checkCircle" size={17} color="#fff"/>
              </div>
              <div style={{flex:1,minWidth:0}}>
                <div style={{color:"#0f172a",fontWeight:800,fontSize:13.5,letterSpacing:-.2}}>Checklist</div>
                <div style={{color:"#64748b",fontSize:11,marginTop:1,fontWeight:600}}>antes de entregar</div>
              </div>
            </div>

            {editMode
              ? (function(){
                  const _items = (editChk||"").split("\n").map(s=>s).filter(()=>true);
                  // Garantir pelo menos uma linha vazia
                  const _list = _items.length===0 ? [""] : _items;
                  return <div style={{display:"flex",flexDirection:"column",gap:7}}>
                    {_list.map(function(item, idx){
                      return <div key={idx} style={{display:"flex",alignItems:"center",gap:7}}>
                        <div style={{color:"#94a3b8",fontSize:10.5,fontWeight:800,minWidth:18,textAlign:"center"}}>{idx+1}</div>
                        <input type="text" value={item}
                          placeholder="Conferi o..."
                          onChange={function(e){
                            const _v = e.target.value;
                            const _arr = _list.slice();
                            _arr[idx] = _v;
                            setEditChk(_arr.join("\n"));
                          }}
                          onKeyDown={function(e){
                            if(e.key==="Enter"){
                              e.preventDefault();
                              const _arr = _list.slice();
                              _arr.splice(idx+1, 0, "");
                              setEditChk(_arr.join("\n"));
                            }
                          }}
                          style={{flex:1,background:"#fafafa",border:"1px solid "+PB_BORDER,borderRadius:9,padding:"9px 12px",color:PB_INK,fontSize:13,outline:"none",fontFamily:PB_INTER,boxSizing:"border-box"}}/>
                        <button type="button" onClick={function(){
                          const _arr = _list.slice();
                          _arr.splice(idx,1);
                          setEditChk(_arr.join("\n"));
                        }} title="Remover" style={{background:"transparent",border:"none",color:"#94a3b8",cursor:"pointer",padding:6,borderRadius:7,display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0}}
                          onMouseEnter={e=>{e.currentTarget.style.color="#dc2626";e.currentTarget.style.background="#fef2f2";}}
                          onMouseLeave={e=>{e.currentTarget.style.color="#94a3b8";e.currentTarget.style.background="transparent";}}>
                          <Ico n="trash" size={13}/>
                        </button>
                      </div>;
                    })}
                    <button type="button" onClick={function(){
                      const _arr = _list.slice();
                      _arr.push("");
                      setEditChk(_arr.join("\n"));
                    }} style={{marginTop:3,background:"transparent",border:"1px dashed "+PB_BORDER,borderRadius:9,padding:"8px 12px",color:PB_PURPLE_DK,fontSize:12,fontWeight:700,cursor:"pointer",fontFamily:PB_INTER,display:"inline-flex",alignItems:"center",justifyContent:"center",gap:5}}>
                      <Ico n="plus" size={12}/> Adicionar item
                    </button>
                  </div>;
                })()
              : totalCheck === 0
                ? <_PbEmpty icon="checkCircle" text="Sem checklist cadastrado."/>
                : <>
                    {/* Barra de progresso */}
                    <div style={{marginBottom:12}}>
                      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:6}}>
                        <span style={{color:PB_MUTE,fontSize:10.5,fontWeight:700,letterSpacing:.3,textTransform:"uppercase"}}>Progresso</span>
                        <span style={{color:allDone?"#15803d":PB_INK,fontSize:12,fontWeight:800}}>{doneCheck}/{totalCheck}</span>
                      </div>
                      <div style={{height:7,background:"#f1f5f9",borderRadius:99,overflow:"hidden"}}>
                        <div style={{width:(totalCheck?Math.round(100*doneCheck/totalCheck):0)+"%",height:"100%",background:allDone?"linear-gradient(90deg, #16a34a, #22c55e)":"linear-gradient(90deg, "+PB_PURPLE+", "+PB_PURPLE_DK+")",transition:"width .25s"}}/>
                      </div>
                    </div>

                    {/* Itens */}
                    <div style={{display:"flex",flexDirection:"column",gap:4}}>
                      {checklistArr.map((item,i)=>{
                        const on = !!checks[i];
                        return <div key={i} onClick={()=>toggleCheck(i)}
                          style={{display:"flex",alignItems:"flex-start",gap:9,padding:"7px 8px",borderRadius:9,cursor:"pointer",background:on?"#f0fdf4":"transparent",transition:"background .15s"}}
                          onMouseEnter={e=>{if(!on)e.currentTarget.style.background="#f8fafc";}}
                          onMouseLeave={e=>{if(!on)e.currentTarget.style.background="transparent";}}>
                          <div style={{width:18,height:18,borderRadius:6,border:on?"2px solid #16a34a":"2px solid #cbd5e1",background:on?"#16a34a":"#fff",flexShrink:0,marginTop:1,display:"flex",alignItems:"center",justifyContent:"center",transition:"all .15s"}}>
                            {on && <Ico n="check" size={11} color="#fff"/>}
                          </div>
                          <span style={{color:on?"#15803d":PB_TEXT,fontSize:12.5,lineHeight:1.45,fontWeight:on?600:500,textDecoration:on?"line-through":"none",textDecorationColor:"#86efac"}}>{item}</span>
                        </div>;
                      })}
                    </div>

                    {/* Banner "Tudo conferido" */}
                    {allDone && <div style={{marginTop:12,background:"linear-gradient(135deg, #dcfce7 0%, #bbf7d0 100%)",border:"1px solid #86efac",borderRadius:11,padding:"10px 12px",display:"flex",alignItems:"center",gap:9}}>
                      <div style={{width:30,height:30,borderRadius:8,background:"#16a34a",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
                        <Ico n="check" size={15} color="#fff"/>
                      </div>
                      <div>
                        <div style={{color:"#14532d",fontSize:12.5,fontWeight:800,letterSpacing:-.1}}>Tudo conferido!</div>
                        <div style={{color:"#166534",fontSize:10.5,marginTop:1,fontWeight:600}}>Pode mandar pra aprovação.</div>
                      </div>
                    </div>}
                  </>
            }
          </div>}

          {/* Materiais (Links + Documentos) */}
          <div style={{background:"#fff",border:"1px solid "+PB_BORDER,borderRadius:14,padding:"14px 16px",fontFamily:PB_INTER}}>
            <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:12}}>
              <div style={{width:36,height:36,borderRadius:11,background:"linear-gradient(135deg, #6366f1 0%, #4338ca 100%)",display:"flex",alignItems:"center",justifyContent:"center",boxShadow:"0 4px 12px rgba(99,102,241,.32)"}}>
                <Ico n="folder" size={16} color="#fff"/>
              </div>
              <div style={{flex:1,minWidth:0}}>
                <div style={{color:PB_INK,fontWeight:800,fontSize:13.5,letterSpacing:-.2}}>Materiais</div>
                <div style={{color:PB_MUTE,fontSize:11,marginTop:1}}>links e documentos do cliente</div>
              </div>
            </div>

            {/* ── Sub-seção LINKS ── */}
            <div style={{marginBottom:14}}>
              <div style={{color:PB_MUTE,fontSize:10,fontWeight:800,textTransform:"uppercase",letterSpacing:.6,marginBottom:8,display:"flex",alignItems:"center",gap:6}}>
                <Ico n="link" size={11} color={PB_MUTE}/>Links
              </div>
              {refs.length === 0
                ? <div style={{background:"#fafafa",border:"1px dashed "+PB_BORDER,borderRadius:10,padding:"12px",textAlign:"center"}}>
                    <div style={{color:PB_SOFT,fontSize:10.5,fontWeight:600}}>Nenhum link ainda</div>
                    {isAdmin && <button onClick={()=>{
                        const url = prompt("URL do link:");
                        if(!url) return;
                        const title = prompt("Título (opcional):") || url;
                        onUpdateArea({refs:[...refs, {url:url.trim(), title:title.trim()}]});
                      }} style={{marginTop:8,background:"transparent",border:"1px solid "+PB_BORDER,borderRadius:7,padding:"5px 11px",color:PB_PURPLE,fontSize:10.5,fontWeight:700,cursor:"pointer",fontFamily:"inherit",display:"inline-flex",alignItems:"center",gap:4}}>
                      <Ico n="plus" size={10} color={PB_PURPLE}/> Adicionar link
                    </button>}
                  </div>
                : <div style={{display:"flex",flexDirection:"column",gap:5}}>
                    {refs.map((r,i)=>(
                      <a key={i} href={r.url} target="_blank" rel="noopener noreferrer"
                        style={{background:"#fafafa",border:"1px solid "+PB_BORDER,borderRadius:8,padding:"7px 10px",textDecoration:"none",display:"flex",alignItems:"center",gap:8,transition:"all .15s"}}
                        onMouseEnter={e=>{e.currentTarget.style.borderColor=PB_PURPLE;e.currentTarget.style.background=PB_PURPLE_BG;}}
                        onMouseLeave={e=>{e.currentTarget.style.borderColor=PB_BORDER;e.currentTarget.style.background="#fafafa";}}>
                        <Ico n="link" size={12} color={PB_PURPLE}/>
                        <div style={{flex:1,minWidth:0,overflow:"hidden"}}>
                          <div style={{color:PB_INK,fontSize:11.5,fontWeight:600,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{r.title||r.url}</div>
                          {r.title && <div style={{color:PB_SOFT,fontSize:9.5,marginTop:1,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{r.url}</div>}
                        </div>
                        {isAdmin && <button onClick={(e)=>{e.preventDefault();e.stopPropagation(); if(confirm("Remover este link?")) onUpdateArea({refs:refs.filter((_,j)=>j!==i)});}} title="Remover"
                          style={{background:"transparent",border:"none",cursor:"pointer",padding:3,borderRadius:5,color:PB_SOFT}}>
                          <Ico n="x" size={11} color="currentColor"/>
                        </button>}
                      </a>
                    ))}
                    {isAdmin && <button onClick={()=>{
                        const url = prompt("URL do link:");
                        if(!url) return;
                        const title = prompt("Título (opcional):") || url;
                        onUpdateArea({refs:[...refs, {url:url.trim(), title:title.trim()}]});
                      }} style={{marginTop:2,background:"transparent",border:"1px dashed "+PB_BORDER,borderRadius:8,padding:"5px 10px",color:PB_PURPLE,fontSize:10.5,fontWeight:700,cursor:"pointer",fontFamily:"inherit",display:"inline-flex",alignItems:"center",justifyContent:"center",gap:4}}>
                      <Ico n="plus" size={10} color={PB_PURPLE}/> Adicionar link
                    </button>}
                  </div>
              }
            </div>

            {/* ── Sub-seção DOCUMENTOS (uploads pra Supabase) ── */}
            <div>
              <div style={{color:PB_MUTE,fontSize:10,fontWeight:800,textTransform:"uppercase",letterSpacing:.6,marginBottom:8,display:"flex",alignItems:"center",gap:6}}>
                <Ico n="file" size={11} color={PB_MUTE}/>Documentos
              </div>
              {(()=>{
                // Helpers
                const _docExt = (name)=>{const m=String(name||"").match(/\.([a-z0-9]{1,5})$/i); return m?m[1].toLowerCase():"";};
                const _docColor = (ext)=>{
                  const m={pdf:"#dc2626",doc:"#2563eb",docx:"#2563eb",xls:"#16a34a",xlsx:"#16a34a",ppt:"#ea580c",pptx:"#ea580c",png:"#7c3aed",jpg:"#7c3aed",jpeg:"#7c3aed",zip:"#475569",txt:"#7c3aed"};
                  return m[ext]||"#64748b";
                };
                const _fmtSize=(b)=>{if(!b)return"";const k=1024;if(b<k)return b+" B";if(b<k*k)return (b/k).toFixed(1)+" KB";return (b/k/k).toFixed(1)+" MB";};

                // === Upload de arquivo ===
                const _uploadDoc = async (file, title)=>{
                  if(!file) return;
                  try{
                    const sb=window._sb;
                    const ext=_docExt(file.name);
                    const key="playbooks/"+(cl.id||"_")+"/"+area+"/"+Date.now()+"-"+file.name.replace(/[^a-z0-9._-]/gi,"_");
                    const {error:upErr} = await sb.storage.from("agency-files").upload(key, file, {contentType:file.type||"application/octet-stream", upsert:false});
                    if(upErr){if(typeof pixelsToast!=="undefined")pixelsToast.error("Erro no upload: "+upErr.message); return;}
                    const {data:pub} = sb.storage.from("agency-files").getPublicUrl(key);
                    const newDoc={
                      id:"doc-"+Date.now()+"-"+Math.random().toString(36).slice(2,7),
                      kind:"file",
                      title:(title||file.name).trim(),
                      fileName:file.name,
                      url:pub?.publicUrl||"",
                      storagePath:key,
                      size:file.size||0,
                      ext:ext,
                      type:file.type||"",
                      at:new Date().toISOString(),
                    };
                    onUpdateArea({docs:[newDoc,...docs]});
                    if(typeof pixelsToast!=="undefined")pixelsToast.success("Documento adicionado.");
                  }catch(e){
                    if(typeof pixelsToast!=="undefined")pixelsToast.error("Erro: "+String(e?.message||e));
                  }
                };
                const _onPickFile = (e)=>{
                  const file = e.target.files?.[0];
                  if(!file) return;
                  const title = prompt("Título do documento (opcional):", file.name) || file.name;
                  _uploadDoc(file, title);
                  e.target.value="";
                };

                // === Criar/Editar documento de texto inline ===
                // _txtOpen/_setTxtOpen vêm do escopo do componente (hooks no topo)
                // null=fechado, {} = novo, {id,...} = editando

                const _newText = ()=>{
                  _setTxtOpen({id:"", title:"", body:""});
                };
                const _editText = (d)=>{
                  _setTxtOpen({id:d.id, title:d.title||"", body:d.body||""});
                };
                const _saveText = ()=>{
                  const t = (_txtOpen.title||"").trim();
                  const b = (_txtOpen.body||"").trim();
                  if(!t){
                    if(typeof pixelsToast!=="undefined")pixelsToast.warning("Coloca um título.");
                    return;
                  }
                  if(_txtOpen.id){
                    // editar existente
                    const next = docs.map(x=>x.id===_txtOpen.id?{...x,title:t,body:b,updatedAt:new Date().toISOString()}:x);
                    onUpdateArea({docs:next});
                    if(typeof pixelsToast!=="undefined")pixelsToast.success("Documento atualizado.");
                  }else{
                    // criar novo
                    const newDoc = {
                      id:"doc-"+Date.now()+"-"+Math.random().toString(36).slice(2,7),
                      kind:"text",
                      title:t,
                      body:b,
                      at:new Date().toISOString(),
                    };
                    onUpdateArea({docs:[newDoc,...docs]});
                    if(typeof pixelsToast!=="undefined")pixelsToast.success("Documento criado.");
                  }
                  _setTxtOpen(null);
                };

                // === Remover ===
                const _removeDoc = async (d)=>{
                  if(!confirm("Remover '"+(d.title||d.fileName)+"'?")) return;
                  try{
                    if(d.storagePath){
                      const sb=window._sb;
                      await sb.storage.from("agency-files").remove([d.storagePath]).catch(()=>{});
                    }
                  }catch(e){}
                  onUpdateArea({docs:docs.filter(x=>x.id!==d.id)});
                  if(typeof pixelsToast!=="undefined")pixelsToast.success("Documento removido.");
                };

                return <>
                  {docs.length===0
                    ? <div style={{background:"#fafafa",border:"1px dashed "+PB_BORDER,borderRadius:10,padding:"12px",textAlign:"center"}}>
                        <div style={{color:PB_SOFT,fontSize:10.5,fontWeight:600,marginBottom:8}}>Nenhum documento ainda</div>
                        {isAdmin && <div style={{display:"flex",gap:5,justifyContent:"center",flexWrap:"wrap"}}>
                          <button onClick={_newText} style={{background:PB_PURPLE,border:"none",borderRadius:7,padding:"5px 11px",color:"#fff",fontSize:10.5,fontWeight:700,cursor:"pointer",fontFamily:"inherit",display:"inline-flex",alignItems:"center",gap:4}}>
                            <Ico n="plus" size={10} color="#fff"/> Documento de texto
                          </button>
                          <label style={{background:"transparent",border:"1px solid "+PB_BORDER,borderRadius:7,padding:"5px 11px",color:PB_PURPLE,fontSize:10.5,fontWeight:700,cursor:"pointer",fontFamily:"inherit",display:"inline-flex",alignItems:"center",gap:4}}>
                            <Ico n="plus" size={10} color={PB_PURPLE}/> Anexar arquivo
                            <input type="file" onChange={_onPickFile} style={{display:"none"}}/>
                          </label>
                        </div>}
                      </div>
                    : <div style={{display:"flex",flexDirection:"column",gap:5}}>
                        {docs.map(d=>{
                          const isText = d.kind==="text";
                          const cor = isText ? PB_PURPLE : _docColor(d.ext);
                          const tag = isText ? "TXT" : (d.ext||"DOC");
                          return <div key={d.id}
                            style={{background:"#fafafa",border:"1px solid "+PB_BORDER,borderRadius:8,padding:"7px 10px",display:"flex",alignItems:"center",gap:8,transition:"all .15s"}}
                            onMouseEnter={e=>{e.currentTarget.style.borderColor=cor;e.currentTarget.style.background=cor+"08";}}
                            onMouseLeave={e=>{e.currentTarget.style.borderColor=PB_BORDER;e.currentTarget.style.background="#fafafa";}}>
                            <div style={{width:24,height:24,borderRadius:6,background:cor+"18",color:cor,display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0,fontSize:9,fontWeight:800,letterSpacing:.3,textTransform:"uppercase"}}>
                              {tag}
                            </div>
                            <div style={{flex:1,minWidth:0,overflow:"hidden",cursor:isText?"pointer":"default"}}
                              onClick={isText?()=>_editText(d):null}>
                              <div style={{color:PB_INK,fontSize:11.5,fontWeight:600,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{d.title||d.fileName}</div>
                              <div style={{color:PB_SOFT,fontSize:9.5,marginTop:1,display:"flex",alignItems:"center",gap:6}}>
                                {!isText && d.size>0 && <span>{_fmtSize(d.size)}</span>}
                                {isText && d.body && <span style={{overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{String(d.body).slice(0,40)}{d.body.length>40?"…":""}</span>}
                                {d.at && <span>{new Date(d.at).toLocaleDateString("pt-BR")}</span>}
                              </div>
                            </div>
                            {!isText && <a href={d.url} target="_blank" rel="noopener noreferrer" title="Abrir/baixar"
                              style={{background:"transparent",border:"none",cursor:"pointer",padding:4,borderRadius:5,color:PB_PURPLE,textDecoration:"none",display:"inline-flex"}}>
                              <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>
                            </a>}
                            {isText && isAdmin && <button onClick={()=>_editText(d)} title="Editar texto"
                              style={{background:"transparent",border:"none",cursor:"pointer",padding:4,borderRadius:5,color:PB_PURPLE,display:"inline-flex"}}>
                              <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><path d="M11 4H4a2 2 0 00-2 2v14a2 2 0 002 2h14a2 2 0 002-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 013 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
                            </button>}
                            {isAdmin && <button onClick={()=>_removeDoc(d)} title="Remover"
                              style={{background:"transparent",border:"none",cursor:"pointer",padding:3,borderRadius:5,color:PB_SOFT}}>
                              <Ico n="x" size={11} color="currentColor"/>
                            </button>}
                          </div>;
                        })}
                        {isAdmin && <div style={{display:"flex",gap:5,marginTop:2}}>
                          <button onClick={_newText} style={{flex:1,background:"transparent",border:"1px dashed "+PB_BORDER,borderRadius:8,padding:"5px 10px",color:PB_PURPLE,fontSize:10.5,fontWeight:700,cursor:"pointer",fontFamily:"inherit",display:"inline-flex",alignItems:"center",justifyContent:"center",gap:4}}>
                            <Ico n="plus" size={10} color={PB_PURPLE}/> Documento de texto
                          </button>
                          <label style={{flex:1,background:"transparent",border:"1px dashed "+PB_BORDER,borderRadius:8,padding:"5px 10px",color:PB_PURPLE,fontSize:10.5,fontWeight:700,cursor:"pointer",fontFamily:"inherit",display:"inline-flex",alignItems:"center",justifyContent:"center",gap:4}}>
                            <Ico n="plus" size={10} color={PB_PURPLE}/> Anexar arquivo
                            <input type="file" onChange={_onPickFile} style={{display:"none"}}/>
                          </label>
                        </div>}
                      </div>
                  }

                  {/* === Modal Documento de Texto === */}
                  {_txtOpen && <div style={{position:"fixed",inset:0,background:"rgba(15,23,42,0.65)",zIndex:400,display:"flex",alignItems:"center",justifyContent:"center",padding:16}}
                    onClick={()=>_setTxtOpen(null)}>
                    <div onClick={e=>e.stopPropagation()} style={{background:"#fff",borderRadius:14,width:"100%",maxWidth:640,boxShadow:"0 20px 60px rgba(0,0,0,.2)",overflow:"hidden",fontFamily:PB_INTER,display:"flex",flexDirection:"column",maxHeight:"85vh"}}>
                      <div style={{background:"linear-gradient(135deg, #6366f1 0%, #4338ca 100%)",padding:"16px 20px",color:"#fff"}}>
                        <div style={{fontSize:14,fontWeight:800,letterSpacing:-.2}}>{_txtOpen.id?"Editar documento":"Novo documento de texto"}</div>
                        <div style={{fontSize:11,opacity:.85,marginTop:1}}>Notas, decisões, ideias — escreva tudo aqui sem precisar subir arquivo</div>
                      </div>
                      <div style={{padding:"16px 20px",display:"flex",flexDirection:"column",gap:11,overflow:"auto",flex:1}}>
                        <div>
                          <div style={{color:PB_MUTE,fontSize:10,fontWeight:800,textTransform:"uppercase",letterSpacing:.6,marginBottom:5}}>Título *</div>
                          <input value={_txtOpen.title} onChange={e=>_setTxtOpen(p=>({...p,title:e.target.value}))}
                            placeholder="Ex: Ata reunião Meta 30/06" autoFocus
                            style={{width:"100%",background:"#fff",border:"1px solid "+PB_BORDER,borderRadius:8,padding:"8px 11px",fontSize:13,color:PB_INK,fontFamily:"inherit",outline:"none",boxSizing:"border-box"}}/>
                        </div>
                        <div style={{flex:1,display:"flex",flexDirection:"column"}}>
                          <div style={{color:PB_MUTE,fontSize:10,fontWeight:800,textTransform:"uppercase",letterSpacing:.6,marginBottom:5}}>Conteúdo</div>
                          <_PbAutoTextarea value={_txtOpen.body} onChange={e=>_setTxtOpen(p=>({...p,body:e.target.value}))}
                            placeholder="Escreva aqui as decisões da reunião, pontos discutidos, próximos passos, ideias..."
                            rows={12}
                            style={{width:"100%",background:"#fff",border:"1px solid "+PB_BORDER,borderRadius:8,padding:"10px 12px",fontSize:13,color:PB_INK,fontFamily:"'Inter',system-ui,sans-serif",outline:"none",boxSizing:"border-box",lineHeight:1.6,minHeight:220}}/>
                        </div>
                      </div>
                      <div style={{padding:"12px 20px",borderTop:"1px solid "+PB_BORDER,display:"flex",justifyContent:"flex-end",gap:8}}>
                        <button onClick={()=>_setTxtOpen(null)}
                          style={{background:"transparent",border:"1px solid "+PB_BORDER,borderRadius:8,padding:"7px 14px",color:PB_MUTE,fontSize:12,fontWeight:700,cursor:"pointer",fontFamily:"inherit"}}>Cancelar</button>
                        <button onClick={_saveText}
                          style={{background:PB_PURPLE,border:"none",borderRadius:8,padding:"7px 18px",color:"#fff",fontSize:12,fontWeight:800,cursor:"pointer",fontFamily:"inherit"}}>
                          Salvar
                        </button>
                      </div>
                    </div>
                  </div>}
                </>;
              })()}
            </div>
          </div>

        </div>
      </div>
    </div>

    {/* ═════ Lightbox de produto (fullscreen, mesma aba) ═════ */}
    {_prodLightbox && (function(){
      const _lbUrls = Array.isArray(_prodLightbox.urls) ? _prodLightbox.urls : [];
      const _lbIdx = Math.max(0, Math.min(_prodLightbox.idx||0, _lbUrls.length-1));
      const _lbUrl = _lbUrls[_lbIdx];
      const _go = function(delta){
        const _n = _lbUrls.length;
        if(_n<=1) return;
        const _next = ((_lbIdx+delta)%_n + _n) % _n;
        setProdLightbox({urls:_lbUrls, idx:_next});
      };
      return <div onClick={function(){setProdLightbox(null);}}
        style={{position:"fixed",inset:0,background:"rgba(15,23,42,0.92)",zIndex:9999,display:"flex",alignItems:"center",justifyContent:"center",padding:24,backdropFilter:"blur(4px)",cursor:"zoom-out"}}>
        <button type="button" onClick={function(e){e.stopPropagation();setProdLightbox(null);}}
          style={{position:"absolute",top:20,right:20,background:"rgba(255,255,255,0.14)",border:"none",borderRadius:99,width:44,height:44,color:"#fff",cursor:"pointer",display:"inline-flex",alignItems:"center",justifyContent:"center",fontSize:22,fontWeight:600,lineHeight:1,padding:0}}
          title="Fechar (ESC)">×</button>
        {_lbUrls.length>1 && <button type="button" onClick={function(e){e.stopPropagation();_go(-1);}}
          style={{position:"absolute",left:20,top:"50%",transform:"translateY(-50%)",background:"rgba(255,255,255,0.14)",border:"none",borderRadius:99,width:52,height:52,color:"#fff",cursor:"pointer",display:"inline-flex",alignItems:"center",justifyContent:"center",padding:0}}
          title="Anterior">
          <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><polyline points="15 18 9 12 15 6"/></svg>
        </button>}
        {_lbUrls.length>1 && <button type="button" onClick={function(e){e.stopPropagation();_go(1);}}
          style={{position:"absolute",right:20,top:"50%",transform:"translateY(-50%)",background:"rgba(255,255,255,0.14)",border:"none",borderRadius:99,width:52,height:52,color:"#fff",cursor:"pointer",display:"inline-flex",alignItems:"center",justifyContent:"center",padding:0}}
          title="Próxima">
          <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><polyline points="9 18 15 12 9 6"/></svg>
        </button>}
        {_lbUrls.length>1 && <div style={{position:"absolute",bottom:22,left:"50%",transform:"translateX(-50%)",background:"rgba(255,255,255,0.14)",color:"#fff",padding:"6px 14px",borderRadius:99,fontSize:12.5,fontWeight:700,letterSpacing:.3,fontFamily:PB_INTER}}>{_lbIdx+1} / {_lbUrls.length}</div>}
        <img src={_lbUrl} alt="" referrerPolicy="no-referrer" onClick={function(e){e.stopPropagation();}}
          style={{maxWidth:"92vw",maxHeight:"88vh",borderRadius:12,boxShadow:"0 20px 60px rgba(0,0,0,0.5)",cursor:"default",objectFit:"contain",display:"block"}}/>
      </div>;
    })()}

  </div>;
}

// ─── Bloco genérico (com id pra ancora + subtitle) ──────────
/* ── _PbBriefingAuto: puxa AUTOMÁTICO do Briefing (clients.briefing_data) os dados
   não-confidenciais que a produção usa: identidade (razão social, CNPJ, cidade,
   endereço, WhatsApp/e-mail empresarial), site e tom de voz. Read-only — edita no
   Briefing. Clique num valor copia. NADA de logins/senhas/orçamento aqui. ── */
function _PbBriefingAuto({clientId}){
  const [bd,setBd]=useState(null);
  const [copiado,setCopiado]=useState("");
  useEffect(function(){
    let vivo=true;
    (async function(){
      try{
        if(!window._sb||!clientId) return;
        const {data}=await window._sb.from("clients").select("briefing_data").eq("client_id",clientId).maybeSingle();
        if(!vivo) return;
        let _b=(data&&data.briefing_data)||null;
        // Formato por unidade (Bioter): usa o "grupo" como base
        if(_b&&_b.grupo&&typeof _b.grupo==="object"&&!_b.identidade) _b=_b.grupo;
        setBd(_b);
      }catch(_){ if(vivo)setBd(null); }
    })();
    return function(){vivo=false;};
  },[clientId]);
  const _g=function(sec,fid){ try{ const v=bd&&bd[sec]&&bd[sec][fid]; return (v&&String(v).trim())?String(v).trim():""; }catch(_){ return ""; } };
  const itens=[
    {l:"Razão social",        v:_g("identidade","nome_empresarial")},
    {l:"CNPJ",                v:_g("identidade","cnpj")},
    {l:"Cidade",              v:_g("identidade","cidade")},
    {l:"Endereço",            v:_g("identidade","endereco")},
    {l:"WhatsApp empresarial",v:_g("identidade","whatsapp_empresarial")},
    {l:"E-mail empresarial",  v:_g("identidade","email_empresarial")},
    {l:"Site",                v:_g("processo","site")},
    {l:"Tom de voz",          v:_g("orcamento","tom_voz")},
  ].filter(function(x){return x.v;});
  if(itens.length===0) return null;
  const _copiar=async function(v){
    try{ await navigator.clipboard.writeText(v); setCopiado(v); setTimeout(function(){setCopiado("");},1400); }catch(_){}
  };
  return <PlaybookBlock id="pb-briefing-auto" title="Dados do Briefing" subtitle="Puxado automático das respostas do Briefing — clique pra copiar; edita lá no Briefing" icon="fileText" color="#0d9488">
    <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(230px,1fr))",gap:8}}>
      {itens.map(function(x,i){
        const _on=copiado===x.v;
        return <button key={i} type="button" onClick={function(){_copiar(x.v);}} title="Clique pra copiar"
          style={{background:_on?"#f0fdfa":"#fafbfc",border:"1px solid "+(_on?"#5eead4":"#eef0f3"),borderRadius:11,padding:"10px 13px",textAlign:"left",cursor:"copy",fontFamily:"inherit",transition:"all .12s",minWidth:0}}>
          <div style={{color:_on?"#0d9488":"#94a3b8",fontSize:9.5,fontWeight:800,letterSpacing:.5,textTransform:"uppercase"}}>{_on?"Copiado ✓":x.l}</div>
          <div style={{color:"#0f172a",fontSize:12.5,fontWeight:600,marginTop:3,lineHeight:1.45,wordBreak:"break-word"}}>{x.v}</div>
        </button>;
      })}
    </div>
  </PlaybookBlock>;
}

function PlaybookBlock({id, title, subtitle, icon, color, children}){
  const _visivel = _pbBlocoVisivel(id); // cadeira não enxerga este bloco (checado depois dos hooks)
  // Cabeçalho SÓLIDO seguindo o rainbow da Linha de produção (mesmo padrão dos Scripts
  // e das sub-seções de Orientações): a cor vem da POSIÇÃO do bloco entre os blocos
  // visíveis na página (lida do DOM), então esconder bloco por cadeira rebalanceia sozinho.
  // `color` virou legado (só fallback). Texto sempre branco.
  const _ref = useRef(null);
  const [_pos, _setPos] = useState({i:0, n:1});
  useEffect(function(){
    if(!_visivel) return;
    const calc = function(){
      try{
        const all = Array.prototype.slice.call(document.querySelectorAll("[data-pb-block]"));
        const i = all.indexOf(_ref.current);
        if(i>=0) _setPos(function(p){ return (p.i===i && p.n===all.length) ? p : {i:i, n:all.length}; });
      }catch(_){}
    };
    calc();
    try{ window.dispatchEvent(new CustomEvent("pixels:pb-blocks")); }catch(_){}
    window.addEventListener("pixels:pb-blocks", calc);
    return function(){
      window.removeEventListener("pixels:pb-blocks", calc);
      setTimeout(function(){ try{ window.dispatchEvent(new CustomEvent("pixels:pb-blocks")); }catch(_){} }, 0);
    };
  },[_visivel]);
  if(!_visivel) return null;
  const _c = (typeof _pxCorSequencial==="function") ? _pxCorSequencial(_pos.i, _pos.n) : (color || "#7c3aed");
  return <div id={id} ref={_ref} data-pb-block="1" style={{background:"#fff",border:"1px solid #e6eaf0",borderRadius:18,padding:0,overflow:"hidden",fontFamily:PB_INTER,boxShadow:"0 1px 2px rgba(15,23,42,.03), 0 8px 24px -12px rgba(15,23,42,.10)",scrollMarginTop:80}}>
    <div style={{display:"flex",alignItems:"center",gap:12,padding:"12px 18px 12px 14px",background:"linear-gradient(120deg,"+_c+" 0%,"+_pbDarken(_c)+" 100%)"}}>
      <div style={{width:34,height:34,borderRadius:10,background:"rgba(255,255,255,.16)",boxShadow:"inset 0 0 0 1px rgba(255,255,255,.22)",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
        <Ico n={icon} size={17} color="#fff" strokeWidth={2.3}/>
      </div>
      <div style={{flex:1,minWidth:0}}>
        <div style={{color:"#fff",fontWeight:800,fontSize:14.5,letterSpacing:-.3,lineHeight:1.2}}>{title}</div>
        {subtitle && <div style={{color:"rgba(255,255,255,.78)",fontSize:11.5,marginTop:2,fontWeight:500,lineHeight:1.35}}>{subtitle}</div>}
      </div>
    </div>
    <div style={{padding:"18px 20px 20px"}}>{children}</div>
  </div>;
}

// Pequeno darken pra gradiente (evita usar lib)
function _pbDarken(hex){
  if(!hex || hex[0]!=="#" || hex.length!==7) return hex;
  const r=Math.max(0,parseInt(hex.slice(1,3),16)-30);
  const g=Math.max(0,parseInt(hex.slice(3,5),16)-30);
  const b=Math.max(0,parseInt(hex.slice(5,7),16)-30);
  return "#"+((1<<24)+(r<<16)+(g<<8)+b).toString(16).slice(1);
}

// ─── Prose component: detecta "O que manter" / "O que evitar" e quebra em blocos visuais ──
// ── _pbAutoSobre — descrição automática a partir de CLIENT_PROFILES ──
// Usada como fallback quando o Playbook ainda não tem "sobre" preenchido.
// Formata: "{Nome fantasia} — {segmento}, com sede em {cidade}/{UF}."
function _pbAutoSobre(clId){
  try{
    const p = (typeof CLIENT_PROFILES!=="undefined") ? CLIENT_PROFILES[clId] : null;
    if(!p) return "";
    const nome = p.nome_fantasia || p.name || "";
    const seg = p.segmento || "";
    const cidUF = (p.cidade && p.estado) ? (p.cidade + "/" + p.estado) : (p.cidade || "");
    if(!nome && !seg) return "";
    let parts = [];
    if(nome) parts.push(nome);
    if(seg) parts.push("— " + seg[0].toLowerCase() + seg.slice(1));
    let sentence = parts.join(" ");
    if(cidUF) sentence += (sentence?", com sede em ":"Sede em ") + cidUF;
    if(sentence && !/[.!?]$/.test(sentence)) sentence += ".";
    return sentence;
  }catch(e){ return ""; }
}

function PbProse({text}){
  if(!text) return null;
  const paragraphs = text.split(/\n\s*\n/);
  return <div style={{display:"flex",flexDirection:"column",gap:10}}>
    {paragraphs.map((p,i)=>{
      const lower = p.toLowerCase();
      if(lower.startsWith("o que manter") || lower.startsWith("manter:")){
        return <PbHighlight key={i} kind="manter" text={p}/>;
      }
      if(lower.startsWith("o que evitar") || lower.startsWith("evitar:")){
        return <PbHighlight key={i} kind="evitar" text={p}/>;
      }
      return <div key={i} style={{color:PB_TEXT,fontSize:13.2,lineHeight:1.65,whiteSpace:"pre-wrap"}}>{p}</div>;
    })}
  </div>;
}

// ─── Bloco "manter" / "evitar" ────────────────────────────
function PbHighlight({kind, text}){
  const isManter = kind === "manter";
  const cfg = isManter
    ? {bg:"#f0fdf4", bd:"#bbf7d0", ico:"check",     iconBg:"#16a34a", labelColor:"#15803d", title:"O que manter"}
    : {bg:"#fef2f2", bd:"#fecaca", ico:"x",         iconBg:"#dc2626", labelColor:"#b91c1c", title:"O que evitar"};
  // remove o "O que manter:" do conteúdo
  let body = text.replace(/^o que manter[:\s]*/i, "").replace(/^manter[:\s]*/i, "")
                 .replace(/^o que evitar[:\s]*/i, "").replace(/^evitar[:\s]*/i, "");
  return <div style={{background:cfg.bg,border:"1px solid "+cfg.bd,borderRadius:12,padding:"12px 14px",display:"flex",gap:11}}>
    <div style={{width:30,height:30,borderRadius:9,background:cfg.iconBg,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0,boxShadow:"0 3px 10px "+cfg.iconBg+"55"}}>
      <Ico n={cfg.ico} size={15} color="#fff" strokeWidth={2.5}/>
    </div>
    <div style={{flex:1,minWidth:0}}>
      <div style={{color:cfg.labelColor,fontSize:10.5,fontWeight:800,letterSpacing:.5,textTransform:"uppercase",marginBottom:5}}>{cfg.title}</div>
      <div style={{color:PB_INK,fontSize:12.8,lineHeight:1.6,whiteSpace:"pre-wrap",fontWeight:500}}>{body}</div>
    </div>
  </div>;
}

// ─── Linha de resumo lateral ──────────────────────────────
function PbMini({icon, label, value}){
  return <div style={{display:"flex",alignItems:"center",gap:9}}>
    <div style={{width:30,height:30,borderRadius:9,background:PB_PURPLE_BG,border:"1px solid "+PB_PURPLE_BD,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
      <Ico n={icon} size={13} color={PB_PURPLE_DK}/>
    </div>
    <div style={{flex:1,minWidth:0}}>
      <div style={{color:PB_SOFT,fontSize:9.5,fontWeight:800,letterSpacing:.5,textTransform:"uppercase"}}>{label}</div>
      <div style={{color:PB_INK,fontSize:12,fontWeight:700,letterSpacing:-.1,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{value}</div>
    </div>
  </div>;
}

// ─── Bloco específico de template ── MINIMAL
function PlaybookTemplateBlock({tpl, isAdmin, editMode, onUpdate, onRemove, onSaveImg}){
  const [tmpTitle,setTmpTitle] = useState(tpl.title||"");
  const [tmpDesc,setTmpDesc] = useState(tpl.descricao||"");
  const [_lbOpen, setLbOpen] = useState(false);
  const _update = onUpdate || (function(patch){if(patch.imgUrl!==undefined&&typeof onSaveImg==="function")onSaveImg(patch.imgUrl);});
  useEffect(function(){ setTmpTitle(tpl.title||""); }, [tpl.title, editMode]);
  useEffect(function(){ setTmpDesc(tpl.descricao||""); }, [tpl.descricao, editMode]);
  useEffect(function(){
    if(!_lbOpen) return;
    const _esc = function(e){ if(e.key==="Escape") setLbOpen(false); };
    document.addEventListener("keydown", _esc);
    return function(){ document.removeEventListener("keydown", _esc); };
  }, [_lbOpen]);

  return <div style={{background:"#fff",border:"1px solid #e2e8f0",borderRadius:14,padding:16,fontFamily:PB_INTER,boxShadow:"0 1px 2px rgba(15,23,42,.03)",display:"flex",flexDirection:"column",gap:14,scrollMarginTop:80}}>
    {/* Header limpo */}
    <div style={{display:"flex",alignItems:"center",gap:12}}>
      <div style={{width:34,height:34,borderRadius:9,background:PB_PURPLE_BG,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0,border:"1px solid "+PB_PURPLE_BD}}>
        <Ico n="image" size={15} color={PB_PURPLE_DK}/>
      </div>
      {editMode && isAdmin
        ? <input value={tmpTitle} onChange={function(e){setTmpTitle(e.target.value);}} onBlur={function(){if(tmpTitle!==tpl.title)_update({title:tmpTitle});}}
            placeholder="Nome do template"
            style={{flex:1,background:"transparent",border:"none",outline:"none",fontSize:16,fontWeight:800,color:PB_INK,letterSpacing:-.3,fontFamily:PB_INTER,padding:0,minWidth:0}}/>
        : <div style={{flex:1,color:PB_INK,fontWeight:800,fontSize:16,letterSpacing:-.3,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{tpl.title||"(sem nome)"}</div>
      }
      {editMode && isAdmin && typeof onRemove==="function" && <button type="button" onClick={onRemove} title="Excluir template"
        style={{background:"transparent",border:"none",color:"#cbd5e1",cursor:"pointer",padding:6,borderRadius:7,flexShrink:0,display:"inline-flex",alignItems:"center",justifyContent:"center",transition:"all .12s"}}
        onMouseEnter={function(e){e.currentTarget.style.background="#fee2e2";e.currentTarget.style.color="#dc2626";}}
        onMouseLeave={function(e){e.currentTarget.style.background="transparent";e.currentTarget.style.color="#cbd5e1";}}>
        <Ico n="trash" size={15}/>
      </button>}
    </div>

    {/* Foto */}
    {tpl.imgUrl
      ? <div style={{position:"relative",background:"#fafbfc",borderRadius:11,overflow:"hidden",border:"1px solid #eef0f3",display:"flex",alignItems:"center",justifyContent:"center",minHeight:200}}>
          <img src={tpl.imgUrl} alt="" referrerPolicy="no-referrer"
            onClick={function(){ setLbOpen(true); }}
            style={{maxWidth:"100%",maxHeight:420,display:"block",objectFit:"contain",cursor:"zoom-in"}}/>
          {editMode && isAdmin && <button type="button" onClick={function(){_pbTemplateUploadImg(_update);}}
            style={{position:"absolute",top:8,right:8,background:"rgba(15,23,42,0.78)",border:"none",borderRadius:8,padding:"6px 12px",color:"#fff",fontSize:11.5,fontWeight:700,cursor:"pointer",fontFamily:"inherit",display:"inline-flex",alignItems:"center",gap:6,backdropFilter:"blur(4px)"}}>
            <Ico n="upload" size={12} color="#fff"/> Trocar
          </button>}
        </div>
      : (editMode && isAdmin
          ? <button type="button" onClick={function(){_pbTemplateUploadImg(_update);}}
              style={{background:"#fafbfc",border:"1.5px dashed #cbd5e1",borderRadius:11,padding:"40px 20px",color:"#64748b",fontSize:13,fontWeight:700,cursor:"pointer",fontFamily:"inherit",display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",gap:9,transition:"all .12s"}}
              onMouseEnter={function(e){e.currentTarget.style.borderColor=PB_PURPLE;e.currentTarget.style.background="#faf5ff";e.currentTarget.style.color=PB_PURPLE_DK;}}
              onMouseLeave={function(e){e.currentTarget.style.borderColor="#cbd5e1";e.currentTarget.style.background="#fafbfc";e.currentTarget.style.color="#64748b";}}>
              <Ico n="image" size={24} color="currentColor"/>
              <span>+ Adicionar imagem de referência</span>
            </button>
          : null
        )
    }

    {/* Descrição simples do template */}
    {editMode && isAdmin
      ? <_PbAutoTextarea value={tmpDesc} onChange={function(e){setTmpDesc(e.target.value);}} onBlur={function(){if(tmpDesc!==(tpl.descricao||""))_update({descricao:tmpDesc});}}
          placeholder="Descreva o template (curto): pra que serve, quando usar, o que manter…"
          rows={2}
          style={{width:"100%",background:"#fafbfc",border:"1px solid #e2e8f0",borderRadius:10,padding:"10px 12px",fontSize:13,color:PB_TEXT,fontFamily:PB_INTER,outline:"none",boxSizing:"border-box",lineHeight:1.55}}/>
      : (tpl.descricao && <div style={{background:"#fafbfc",border:"1px solid #eef0f3",borderRadius:10,padding:"10px 12px",color:PB_TEXT,fontSize:13,lineHeight:1.6,whiteSpace:"pre-wrap"}}>{tpl.descricao}</div>)
    }

    {/* Lightbox pra ver a imagem grande */}
    {_lbOpen && tpl.imgUrl && <div onClick={function(){setLbOpen(false);}}
      style={{position:"fixed",inset:0,background:"rgba(15,23,42,0.92)",zIndex:9999,display:"flex",alignItems:"center",justifyContent:"center",padding:24,backdropFilter:"blur(4px)",cursor:"zoom-out"}}>
      <button type="button" onClick={function(e){e.stopPropagation();setLbOpen(false);}}
        style={{position:"absolute",top:20,right:20,background:"rgba(255,255,255,0.14)",border:"none",borderRadius:99,width:44,height:44,color:"#fff",cursor:"pointer",display:"inline-flex",alignItems:"center",justifyContent:"center",fontSize:22,fontWeight:600,lineHeight:1,padding:0}}
        title="Fechar (ESC)">×</button>
      <img src={tpl.imgUrl} alt="" referrerPolicy="no-referrer" onClick={function(e){e.stopPropagation();}}
        style={{maxWidth:"92vw",maxHeight:"88vh",borderRadius:12,boxShadow:"0 20px 60px rgba(0,0,0,0.5)",cursor:"default",objectFit:"contain",display:"block"}}/>
    </div>}
  </div>;
}

/* ─── _TemplateImageWithAnnotations — imagem do Template com canvas SVG de setas/formas/texto ───
   Coordenadas em PERCENTUAL (0-100) pra ficar responsivo em qualquer tamanho.
   Salva em tpl.annotations: [{type:"arrow"|"rect"|"circle"|"text", x1,y1,x2,y2, color, text?}] */
function _TemplateImageWithAnnotations({tpl, editMode, isAdmin, onSaveAnnotations}){
  const _wrapRef = useRef(null);
  const _imgRef = useRef(null);
  const [_tool, _setTool] = useState(null); // null | "arrow" | "rect" | "circle" | "text"
  const [_color, _setColor] = useState("#ef4444");
  const [_drag, _setDrag] = useState(null); // {x1,y1,x2,y2}
  const [_anns, _setAnns] = useState(Array.isArray(tpl.annotations) ? tpl.annotations : []);
  useEffect(()=>{ _setAnns(Array.isArray(tpl.annotations) ? tpl.annotations : []); },[tpl.id, tpl.annotations]);

  const _commit = function(arr){
    _setAnns(arr);
    if(typeof onSaveAnnotations==="function") onSaveAnnotations(arr);
  };
  const _pointPct = function(e){
    const r = _wrapRef.current ? _wrapRef.current.getBoundingClientRect() : null;
    if(!r) return {x:0,y:0};
    return { x: ((e.clientX-r.left)/r.width)*100, y: ((e.clientY-r.top)/r.height)*100 };
  };
  const _onMouseDown = function(e){
    if(!editMode || !isAdmin || !_tool) return;
    e.preventDefault();
    const p = _pointPct(e);
    if(_tool==="text"){
      const txt = prompt("Texto da anotação:");
      if(!txt) return;
      _commit(_anns.concat([{type:"text",x1:p.x,y1:p.y,x2:p.x,y2:p.y,color:_color,text:txt}]));
      return;
    }
    _setDrag({x1:p.x,y1:p.y,x2:p.x,y2:p.y});
  };
  const _onMouseMove = function(e){
    if(!_drag) return;
    const p = _pointPct(e);
    _setDrag(Object.assign({},_drag,{x2:p.x,y2:p.y}));
  };
  const _onMouseUp = function(){
    if(!_drag || !_tool) return;
    _commit(_anns.concat([Object.assign({},_drag,{type:_tool,color:_color})]));
    _setDrag(null);
  };
  const _removeAnn = function(idx){
    _commit(_anns.filter(function(_,i){return i!==idx;}));
  };
  const _clearAll = function(){
    if(_anns.length===0) return;
    _commit([]);
  };

  const _renderShape = function(a, idx){
    const stroke = a.color || "#ef4444";
    if(a.type==="arrow"){
      // linha + cabeça da seta
      const dx = a.x2 - a.x1, dy = a.y2 - a.y1;
      const len = Math.sqrt(dx*dx + dy*dy) || 1;
      const ux = dx/len, uy = dy/len;
      const head = 2.5; // % comprimento da cabeça
      const px = -uy, py = ux;
      const hx1 = a.x2 - ux*head + px*head*.6;
      const hy1 = a.y2 - uy*head + py*head*.6;
      const hx2 = a.x2 - ux*head - px*head*.6;
      const hy2 = a.y2 - uy*head - py*head*.6;
      return <g key={idx}>
        <line x1={a.x1+"%"} y1={a.y1+"%"} x2={a.x2+"%"} y2={a.y2+"%"} stroke={stroke} strokeWidth="3" strokeLinecap="round"/>
        <polygon points={a.x2+"%,"+a.y2+"% "+hx1+"%,"+hy1+"% "+hx2+"%,"+hy2+"%"} fill={stroke}/>
      </g>;
    }
    if(a.type==="rect"){
      const x = Math.min(a.x1,a.x2), y = Math.min(a.y1,a.y2);
      const w = Math.abs(a.x2-a.x1), h = Math.abs(a.y2-a.y1);
      return <rect key={idx} x={x+"%"} y={y+"%"} width={w+"%"} height={h+"%"} fill="none" stroke={stroke} strokeWidth="3" rx="6"/>;
    }
    if(a.type==="circle"){
      const cx = (a.x1+a.x2)/2, cy = (a.y1+a.y2)/2;
      const rx = Math.abs(a.x2-a.x1)/2, ry = Math.abs(a.y2-a.y1)/2;
      return <ellipse key={idx} cx={cx+"%"} cy={cy+"%"} rx={rx+"%"} ry={ry+"%"} fill="none" stroke={stroke} strokeWidth="3"/>;
    }
    if(a.type==="text"){
      return <text key={idx} x={a.x1+"%"} y={a.y1+"%"} fill={stroke} fontSize="20" fontWeight="700" fontFamily="Inter,system-ui,sans-serif" style={{paintOrder:"stroke",stroke:"#fff",strokeWidth:"4px"}}>{a.text||""}</text>;
    }
    return null;
  };

  const _toolBtn = function(toolId, label, iconN){
    const active = _tool===toolId;
    return <button type="button" key={toolId} onClick={()=>_setTool(active?null:toolId)}
      style={{background:active?PB_PURPLE:"#fff",color:active?"#fff":"#475569",border:"1px solid "+(active?PB_PURPLE:"#e2e8f0"),borderRadius:8,padding:"6px 11px",fontSize:11.5,fontWeight:700,cursor:"pointer",fontFamily:PB_INTER,display:"inline-flex",alignItems:"center",gap:5,transition:"all .12s"}}>
      <Ico n={iconN} size={12} color="currentColor"/>{label}
    </button>;
  };

  const COLORS = ["#ef4444","#0ea5e9","#16a34a","#f59e0b","#7c3aed","#0f172a"];

  return <div>
    {/* Toolbar (só em editMode + admin) */}
    {editMode && isAdmin && <div style={{display:"flex",flexWrap:"wrap",gap:6,marginBottom:10,padding:"8px 10px",background:"#fafafa",border:"1px solid "+PB_BORDER,borderRadius:9,alignItems:"center"}}>
      {_toolBtn("arrow","Seta","send")}
      {_toolBtn("rect","Retângulo","layers")}
      {_toolBtn("circle","Círculo","dot")}
      {_toolBtn("text","Texto","file-text")}
      <div style={{height:24,width:1,background:"#e2e8f0",margin:"0 4px"}}/>
      {COLORS.map(c=>(
        <button type="button" key={c} onClick={()=>_setColor(c)} title={c}
          style={{width:22,height:22,borderRadius:"50%",background:c,border:_color===c?"2px solid #0f172a":"2px solid #fff",boxShadow:"0 0 0 1px #e2e8f0",cursor:"pointer"}}/>
      ))}
      <div style={{flex:1}}/>
      {_anns.length>0 && <button type="button" onClick={_clearAll}
        style={{background:"#fee2e2",border:"1px solid #fecaca",color:"#dc2626",borderRadius:8,padding:"6px 11px",fontSize:11.5,fontWeight:700,cursor:"pointer",fontFamily:PB_INTER,display:"inline-flex",alignItems:"center",gap:5}}>
        <Ico n="trash" size={12}/> Limpar tudo ({_anns.length})
      </button>}
    </div>}

    {/* Container imagem + SVG overlay */}
    <div ref={_wrapRef} onMouseDown={_onMouseDown} onMouseMove={_onMouseMove} onMouseUp={_onMouseUp} onMouseLeave={_onMouseUp}
      style={{position:"relative",borderRadius:14,overflow:"hidden",border:"1px solid "+PB_PURPLE_BD,background:"#fafafa",cursor:editMode&&isAdmin&&_tool?"crosshair":"default",userSelect:"none"}}>
      <img ref={_imgRef} src={tpl.imgUrl} alt="" referrerPolicy="no-referrer"
        onError={e=>{e.currentTarget.style.display="none";const ph=e.currentTarget.nextElementSibling;if(ph)ph.style.display="flex";}}
        style={{maxWidth:"100%",maxHeight:560,objectFit:"contain",display:"block",margin:"0 auto",pointerEvents:"none"}}/>
      <div style={{display:"none",flexDirection:"column",alignItems:"center",justifyContent:"center",gap:8,padding:40,color:PB_SOFT,textAlign:"center"}}>
        <Ico n="image" size={28} color="#cbd5e1"/>
        <div style={{fontSize:12,fontWeight:600}}>Imagem indisponível</div>
        <a href={tpl.imgUrl} target="_blank" rel="noopener noreferrer" style={{color:PB_PURPLE,fontSize:11,fontWeight:700,textDecoration:"none"}}>Abrir URL</a>
      </div>

      {/* SVG overlay com as anotações */}
      <svg style={{position:"absolute",inset:0,width:"100%",height:"100%",pointerEvents:"none"}} preserveAspectRatio="none">
        {_anns.map(_renderShape)}
        {_drag && _renderShape(Object.assign({},_drag,{type:_tool,color:_color}), "drag")}
      </svg>

      {/* Hint quando nenhuma ferramenta ativa em editMode */}
      {editMode && isAdmin && !_tool && _anns.length===0 && <div style={{position:"absolute",top:8,right:8,background:"rgba(15,23,42,.85)",color:"#fff",fontSize:10.5,fontWeight:600,padding:"4px 10px",borderRadius:99,pointerEvents:"none"}}>
        Escolha uma ferramenta acima
      </div>}
    </div>

    {/* Lista de anotações pra remover individualmente (só em editMode) */}
    {editMode && isAdmin && _anns.length>0 && <div style={{marginTop:8,display:"flex",flexWrap:"wrap",gap:5}}>
      {_anns.map((a,i)=>(
        <span key={i} style={{display:"inline-flex",alignItems:"center",gap:5,background:"#fff",border:"1px solid #e2e8f0",borderRadius:99,padding:"3px 4px 3px 10px",fontSize:11,fontWeight:600,color:"#475569"}}>
          <span style={{width:10,height:10,borderRadius:"50%",background:a.color||"#ef4444"}}/>
          {a.type==="text"?'"'+(a.text||"").slice(0,20)+'"':a.type}
          <button type="button" onClick={()=>_removeAnn(i)} title="Remover"
            style={{background:"transparent",border:"none",color:"#94a3b8",cursor:"pointer",padding:2,borderRadius:99,width:18,height:18,display:"inline-flex",alignItems:"center",justifyContent:"center"}}>
            <Ico n="x" size={10} color="currentColor"/>
          </button>
        </span>
      ))}
    </div>}
  </div>;
}

// Adivinha ícone pra cada seção do template
function _pbSecIcon(sectionName){
  const s = (sectionName||"").toLowerCase();
  if(s.includes("texto") || s.includes("legenda")) return "fileText";
  if(s.includes("mapa") || s.includes("localiz")) return "pin";
  if(s.includes("enquadr") || s.includes("foto") || s.includes("imagem")) return "camera";
  if(s.includes("limpeza") || s.includes("valoriz")) return "sparkles";
  if(s.includes("leitura")) return "eye";
  if(s.includes("ritmo") || s.includes("video") || s.includes("vídeo")) return "play";
  if(s.includes("cor")) return "image";
  if(s.includes("tipograf") || s.includes("fonte")) return "fileText";
  return "check";
}

// ── Auto-expand textarea ──────────────────────────────
// Cresce automaticamente conforme o conteudo — sem scroll interno chato.
function _PbAutoTextarea({value, onChange, onBlur, placeholder, style, rows}){
  const _ref = useRef(null);
  const _fit = function(){
    const el = _ref.current;
    if(!el) return;
    el.style.height = "auto";
    el.style.height = (el.scrollHeight + 2) + "px";
  };
  useEffect(_fit, [value]);
  useEffect(function(){
    setTimeout(_fit, 0);
  // eslint-disable-next-line
  }, []);
  // Auto-bullet: "- " ou "* " no inicio de linha vira "• "
  function _handleChange(e){
    const el = e.target;
    const _v = el.value;
    const _pos = el.selectionStart;
    // Detecta se o usuario digitou "- " ou "* " no comeco de uma linha
    // Pega os 2 chars ANTES do cursor
    if(_pos >= 2){
      const _last2 = _v.slice(_pos-2, _pos);
      if(_last2 === "- " || _last2 === "* "){
        // Verifica se esta no comeco de linha (char anterior é \n ou é o comeco do texto)
        const _prev = _pos-2 > 0 ? _v[_pos-3] : "\n";
        if(_prev === "\n" || _pos === 2){
          const _newVal = _v.slice(0, _pos-2) + "• " + _v.slice(_pos);
          // Sintetiza um novo event pra manter o contrato do onChange
          const _newEvent = Object.assign({}, e, {target: Object.assign({}, e.target, {value:_newVal})});
          // Aplica o valor via ref e reposiciona cursor DEPOIS que o React re-render
          if(typeof onChange === "function") onChange(_newEvent);
          setTimeout(function(){
            if(_ref.current){
              _ref.current.setSelectionRange(_pos, _pos);
              _fit();
            }
          }, 0);
          return;
        }
      }
    }
    if(typeof onChange === "function") onChange(e);
  }
  return <textarea ref={_ref} value={value} onChange={_handleChange} onBlur={onBlur}
    placeholder={placeholder} rows={rows||3}
    onInput={_fit}
    style={Object.assign({},style||{},{overflow:"hidden",resize:"none",minHeight:80})}/>;
}

// ── Empty state ──────────────────────────────────────

function _PbEmpty({icon, text, sub}){
  return <div style={{background:"#fafafa",border:"1px dashed "+PB_BORDER,borderRadius:12,padding:"20px 18px",textAlign:"center"}}>
    {icon && <Ico n={icon} size={24} color="#cbd5e1"/>}
    <div style={{color:PB_MUTE,fontSize:12.5,marginTop:icon?8:0,fontWeight:600}}>{text}</div>
    {sub && <div style={{color:PB_SOFT,fontSize:11,marginTop:4,lineHeight:1.45}}>{sub}</div>}
  </div>;
}

function _pbInpStyle(){
  return {background:"#fafafa",border:"1px solid "+PB_BORDER,borderRadius:10,padding:"10px 13px",color:PB_INK,fontSize:13,outline:"none",width:"100%",boxSizing:"border-box",fontFamily:PB_INTER,resize:"vertical",lineHeight:1.6};
}

// ═══════════════════════════════════════════════════════════════
//  _PbVisualOrientations — Orientações visuais por área
//  Lista de {id, title, description, imgUrl, createdAt}. Salva no
//  areaData.orientacoes_visuais via onUpdate. Consumido pelo CardModal
//  filtrado por setor (design/video/midia/social).
// ═══════════════════════════════════════════════════════════════
function _PbVisualOrientations({areaData, isAdmin, editMode, onUpdate, areaColor}){
  const _color = areaColor || PB_PURPLE_DK;
  const _list = Array.isArray(areaData && areaData.orientacoes_visuais) ? areaData.orientacoes_visuais : [];

  function _save(nextList){
    if(typeof onUpdate==="function") onUpdate({orientacoes_visuais: nextList});
  }
  function _add(){
    const _id = "orv-"+Date.now()+"-"+Math.random().toString(36).slice(2,7);
    const _new = {id:_id, title:"Nova orientação", description:"", imgUrl:"", createdAt:new Date().toISOString()};
    _save([..._list, _new]);
  }
  function _update(id, patch){
    _save(_list.map(function(it){ return it.id===id ? Object.assign({},it,patch) : it; }));
  }
  function _remove(id){
    const _item = _list.find(function(it){return it.id===id;});
    if(!_item){ return; }
    // Se é placeholder recém-criado (título default, sem imagem e sem descrição), apaga direto
    const _isPlaceholder = (_item.title==="Nova orientação" || !_item.title) && !_item.imgUrl && !_item.description;
    function _doDelete(){
      const _next = _list.filter(function(it){return it.id!==id;});
      _save(_next);
      if(typeof pixelsToast!=="undefined") pixelsToast.info("Orientação removida",1500);
    }
    if(_isPlaceholder){ _doDelete(); return; }
    const _title = _item.title || "Orientação";
    if(typeof pixelsConfirm==="function"){
      pixelsConfirm({title:"Excluir orientação visual?",message:'"'+_title+'" será removida.',confirmLabel:"Excluir",danger:true,onConfirm:_doDelete});
    }else if(window.confirm('Excluir "'+_title+'"?')){ _doDelete(); }
  }

  if(_list.length===0 && !editMode){
    return <_PbEmpty icon="image" text="Nenhuma orientação visual cadastrada." sub={isAdmin?"Edite o playbook para adicionar imagens de referência (ex: como posicionar o piso, cor correta, layout etc).":""}/>;
  }

  return <div style={{display:"flex",flexDirection:"column",gap:12}}>
    {_list.map(function(item){
      return <_PbVisualOrientItem key={item.id} item={item} editMode={editMode} isAdmin={isAdmin}
        color={_color}
        onUpdate={function(patch){_update(item.id, patch);}}
        onRemove={function(){_remove(item.id);}}/>;
    })}
    {editMode && isAdmin && <button type="button" onClick={_add}
      style={{background:"#fff",border:"1.5px dashed "+_color+"66",borderRadius:12,padding:"14px 18px",color:_color,fontSize:13,fontWeight:700,cursor:"pointer",fontFamily:PB_INTER,display:"inline-flex",alignItems:"center",justifyContent:"center",gap:8,transition:"all .15s"}}
      onMouseEnter={function(e){e.currentTarget.style.background=_color+"0d";e.currentTarget.style.borderColor=_color;}}
      onMouseLeave={function(e){e.currentTarget.style.background="#fff";e.currentTarget.style.borderColor=_color+"66";}}>
      <Ico n="plus" size={15} color={_color}/> Adicionar orientação visual
    </button>}
  </div>;
}

function _PbVisualOrientItem({item, editMode, isAdmin, color, onUpdate, onRemove}){
  const _color = color || PB_PURPLE_DK;
  const [tTitle,setTTitle] = useState(item.title||"");
  const [tDesc,setTDesc]   = useState(item.description||"");
  useEffect(function(){ setTTitle(item.title||""); setTDesc(item.description||""); }, [item.id, item.title, item.description, editMode]);

  return <div style={{background:"#fff",border:"1px solid "+PB_BORDER,borderRadius:14,padding:0,overflow:"hidden",boxShadow:"0 2px 8px rgba(15,23,42,.04)",display:"grid",gridTemplateColumns:_pxMob()?"1fr":"180px 1fr",gap:0,alignItems:"stretch"}}>
    {/* Imagem */}
    <div style={{background:"#fafafa",borderRight:"1px solid "+PB_BORDER2,minHeight:140,display:"flex",alignItems:"center",justifyContent:"center",position:"relative"}}>
      {item.imgUrl
        ? <img src={item.imgUrl} alt={item.title||""} style={{width:"100%",height:"100%",objectFit:"cover",maxHeight:200,display:"block"}} referrerPolicy="no-referrer" onError={function(e){e.currentTarget.style.display="none";}}/>
        : <div style={{padding:14,textAlign:"center"}}>
            <Ico n="image" size={26} color="#cbd5e1"/>
            <div style={{color:PB_MUTE,fontSize:10.5,marginTop:5,fontWeight:600,letterSpacing:.2}}>Sem imagem</div>
          </div>
      }
      {editMode && isAdmin && <button type="button" onClick={function(){_pbTemplateUploadImg(function(patch){onUpdate({imgUrl:patch.imgUrl});});}}
        style={{position:"absolute",bottom:6,right:6,background:"rgba(15,23,42,.86)",border:"none",borderRadius:8,padding:"5px 9px",color:"#fff",fontSize:10.5,fontWeight:700,cursor:"pointer",display:"inline-flex",alignItems:"center",gap:5,backdropFilter:"blur(6px)"}}>
        <Ico n="upload" size={11} color="#fff"/> {item.imgUrl?"Trocar":"Subir"}
      </button>}
    </div>
    {/* Texto */}
    <div style={{padding:"14px 16px",display:"flex",flexDirection:"column",gap:8,minWidth:0}}>
      <div style={{display:"flex",alignItems:"flex-start",gap:8}}>
        {editMode && isAdmin
          ? <input type="text" value={tTitle} onChange={function(e){setTTitle(e.target.value);}} onBlur={function(){if(tTitle!==item.title) onUpdate({title:tTitle});}}
              placeholder="Título curto (ex: Posição correta do piso)"
              style={{flex:1,background:"#fafafa",border:"1px solid "+PB_BORDER,borderRadius:8,padding:"7px 11px",color:PB_INK,fontSize:13.5,fontWeight:700,letterSpacing:-.15,outline:"none",fontFamily:PB_INTER}}/>
          : <div style={{flex:1,color:PB_INK,fontSize:14,fontWeight:800,letterSpacing:-.25,lineHeight:1.2}}>{item.title||"(sem título)"}</div>
        }
        {editMode && isAdmin && <button type="button" onClick={onRemove} title="Excluir"
          style={{background:"#fef2f2",border:"1px solid #fecaca",borderRadius:8,width:28,height:28,color:"#b91c1c",cursor:"pointer",display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
          <Ico n="trash" size={13} color="#b91c1c"/>
        </button>}
      </div>
      {editMode && isAdmin
        ? <_PbAutoTextarea value={tDesc} onChange={function(e){setTDesc(e.target.value);}} onBlur={function(){if(tDesc!==item.description) onUpdate({description:tDesc});}} rows={4}
            placeholder="Descreva o que a imagem representa e como aplicar (aparece nos cards do setor)."
            style={Object.assign({},_pbInpStyle(),{minHeight:80,fontSize:12.5})}/>
        : (item.description
            ? <div style={{color:PB_TEXT,fontSize:12.5,lineHeight:1.55,whiteSpace:"pre-wrap"}}>{item.description}</div>
            : <div style={{color:PB_MUTE,fontSize:11.5,fontStyle:"italic"}}>Sem descrição.</div>
          )
      }
    </div>
  </div>;
}

// ═══════════════════════════════════════════════════════════════
//  _PbSocialConfig — Configuração de publicação (Social Media)
//  Perfis a marcar, cadência semanal, mix de tipos, particularidades,
//  restrições. Salva no areaData via onUpdate(patch).
// ═══════════════════════════════════════════════════════════════
function _PbSocialConfig({areaData, isAdmin, editMode, onUpdate, clientId}){
  const PINK    = "#ec4899";
  const PINK_DK = "#db2777";
  const _isBioterCli = clientId === "bioter";
  const _units = (_isBioterCli && typeof BIOTER_UNITS!=="undefined") ? BIOTER_UNITS : [];

  const _perfisInit = Array.isArray(areaData && areaData.perfis) ? areaData.perfis : [];
  const _cadenciaInit = (areaData && areaData.cadencia) || {postsSemana:"", stories:"", reels:""};
  const _mixInit = (areaData && areaData.mix) || {arte:"", carrossel:"", reel:"", fotoObra:"", story:""};
  const _particularidadesInit = (areaData && areaData.particularidades) || "";
  const _restricoesInit = (areaData && areaData.restricoes) || "";

  const [perfis, setPerfis] = useState(_perfisInit);
  const [cadencia, setCadencia] = useState(_cadenciaInit);
  const [mix, setMix] = useState(_mixInit);
  const [particularidades, setParticularidades] = useState(_particularidadesInit);
  const [restricoes, setRestricoes] = useState(_restricoesInit);

  // Sync do state local SO ao trocar de cliente. Nao dispara por areaData
  // pra evitar loop de sync durante digitacao (auto-save volta pra areaData,
  // aciona useEffect, reseta o input no meio do digitar — cursor pula, texto some).
  useEffect(function(){
    var _initPerfis = Array.isArray(areaData && areaData.perfis) ? areaData.perfis : [];
    // Auto-migracao: se cliente Bioter, atribui perfis orfaos (sem unitId) pra primeira unidade
    var _isBio = clientId==="bioter";
    var _firstUnit = (typeof BIOTER_UNITS!=="undefined" && BIOTER_UNITS[0]) ? BIOTER_UNITS[0].id : "";
    if(_isBio && _firstUnit){
      var _hasOrfaos = _initPerfis.some(function(p){ return !p.unitId; });
      if(_hasOrfaos){
        _initPerfis = _initPerfis.map(function(p){
          return p.unitId ? p : Object.assign({}, p, {unitId:_firstUnit});
        });
        // Persiste a migracao silenciosamente (bem-comportado: async, sem toast)
        setTimeout(function(){
          if(typeof onUpdate==="function") onUpdate({perfis:_initPerfis});
        }, 0);
      }
    }
    setPerfis(_initPerfis);
    setCadencia((areaData && areaData.cadencia) || {postsSemana:"", stories:"", reels:""});
    setMix((areaData && areaData.mix) || {arte:"", carrossel:"", reel:"", fotoObra:"", story:""});
    setParticularidades((areaData && areaData.particularidades) || "");
    setRestricoes((areaData && areaData.restricoes) || "");
  // eslint-disable-next-line
  },[clientId]);

  function _save(patch){ if(typeof onUpdate==="function") onUpdate(patch); }

  // Debounce de save de perfis pra evitar race condition (digitacao rapida
  // gerava saves em paralelo e o ultimo response do Supabase sobrescrevia
  // valores mais novos). 500ms depois da ultima tecla, agrupa e salva 1 vez so.
  const _perfisSaveTimer = useRef(null);
  const _perfisDirtyRef = useRef(false);
  useEffect(function(){
    if(!_perfisDirtyRef.current) return;
    clearTimeout(_perfisSaveTimer.current);
    _perfisSaveTimer.current = setTimeout(function(){
      _perfisDirtyRef.current = false;
      if(typeof onUpdate==="function") onUpdate({perfis: perfis});
    }, 500);
    return function(){ clearTimeout(_perfisSaveTimer.current); };
  }, [perfis]);
  // Flush ao desmontar (evita perder o save se sair rapido)
  useEffect(function(){
    return function(){
      if(_perfisDirtyRef.current){
        clearTimeout(_perfisSaveTimer.current);
        if(typeof onUpdate==="function") onUpdate({perfis: perfis});
      }
    };
  // eslint-disable-next-line
  }, []);

  // ── Perfis ─────────────────────────────
  const PLATAFORMAS = [
    {id:"instagram", label:"Instagram", color:"#e1306c"},
    {id:"tiktok",    label:"TikTok",    color:"#111827"},
    {id:"youtube",   label:"YouTube",   color:"#dc2626"},
    {id:"linkedin",  label:"LinkedIn",  color:"#0a66c2"},
    {id:"facebook",  label:"Facebook",  color:"#1877f2"}
  ];
  function _platCfg(id){ return PLATAFORMAS.find(function(p){return p.id===id;}) || PLATAFORMAS[0]; }

  function _perfilAdd(unitId){
    var _new = {plataforma:"instagram", handle:"", nome:"", papel:""};
    if(unitId) _new.unitId = unitId;
    _perfisDirtyRef.current = true;
    setPerfis(function(cur){ return cur.concat([_new]); });
  }
  function _perfilSet(i, patch){
    _perfisDirtyRef.current = true;
    setPerfis(function(cur){
      return cur.map(function(p,idx){ return idx===i ? Object.assign({},p,patch) : p; });
    });
  }
  function _perfilDel(i){
    _perfisDirtyRef.current = true;
    setPerfis(function(cur){ return cur.filter(function(_,idx){ return idx!==i; }); });
  }

  function _cadenciaSet(patch){
    var next = Object.assign({},cadencia,patch);
    setCadencia(next); _save({cadencia:next});
  }
  function _mixSet(patch){
    var next = Object.assign({},mix,patch);
    setMix(next); _save({mix:next});
  }

  const CADENCIA_FIELDS = [
    {key:"postsSemana", label:"Posts / semana", ph:"ex: 4"},
    {key:"stories",     label:"Stories / semana", ph:"ex: 6"},
    {key:"reels",       label:"Reels / semana", ph:"ex: 2"}
  ];
  const MIX_FIELDS = [
    {key:"arte",      label:"Arte única",  icon:"image"},
    {key:"carrossel", label:"Carrossel",   icon:"layers"},
    {key:"reel",      label:"Reel / Vídeo",icon:"play"},
    {key:"fotoObra",  label:"Foto de obra",icon:"camera"},
    {key:"story",     label:"Story",       icon:"sparkles"}
  ];

  return <div style={{display:"flex",flexDirection:"column",gap:20}}>

    {/* ── Perfis pra marcar ── */}
    {(function(){
      // Helper: renderiza 1 card de perfil (view ou edit). Reusado tanto em Bioter
      // (dentro de cada coluna de unidade) quanto no fluxo simples nao-bioter.
      function _renderPerfilCard(p, i){
        var _cfg = _platCfg(p.plataforma);
        var _handleClean = String(p.handle||"").replace(/^@+/,"");
        if(!editMode || !isAdmin){
          return <div key={i} style={{display:"flex",alignItems:"center",gap:8,background:"#fafbfc",border:"1px solid "+PB_BORDER2,borderRadius:10,padding:"10px 14px"}}>
            <span style={{color:_cfg.color,fontWeight:800,fontSize:16,flexShrink:0,lineHeight:1}}>@</span>
            <div style={{flex:1,minWidth:0,color:PB_INK,fontWeight:700,fontSize:14.5,letterSpacing:-.2,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>
              {_handleClean || <span style={{color:PB_SOFT,fontWeight:500,fontStyle:"italic"}}>sem @</span>}
            </div>
          </div>;
        }
        return <div key={i} style={{background:"#fafbfc",border:"1px solid "+PB_BORDER2,borderRadius:10,padding:"9px 11px",display:"flex",gap:7,alignItems:"center"}}>
          <div style={{flex:1,display:"flex",alignItems:"center",background:"#fff",border:"1px solid "+PB_BORDER2,borderRadius:8,overflow:"hidden",height:34,minWidth:0}}>
            <span style={{color:_cfg.color,fontWeight:800,fontSize:15,padding:"0 4px 0 12px",userSelect:"none"}}>@</span>
            <input value={_handleClean} onChange={function(e){_perfilSet(i,{handle:e.target.value.replace(/^@+/,"").replace(/\s/g,"")});}}
              placeholder="usuario"
              style={{flex:1,border:"none",outline:"none",background:"transparent",fontSize:14,fontFamily:"inherit",color:PB_INK,padding:"0 10px 0 2px",minWidth:0,fontWeight:700,letterSpacing:-.1}}/>
          </div>
          <button type="button" onClick={function(){_perfilDel(i);}} title="Remover perfil"
            style={{background:"transparent",border:"none",color:"#94a3b8",cursor:"pointer",padding:5,borderRadius:7,flexShrink:0,display:"inline-flex",alignItems:"center",justifyContent:"center",transition:"all .12s"}}
            onMouseEnter={function(e){e.currentTarget.style.background="#fee2e2";e.currentTarget.style.color="#dc2626";}}
            onMouseLeave={function(e){e.currentTarget.style.background="transparent";e.currentTarget.style.color="#94a3b8";}}>
            <Ico n="x" size={12} color="currentColor"/>
          </button>
        </div>;
      }

      // Header comum
      var _header = <div style={{display:"flex",alignItems:"flex-start",justifyContent:"space-between",gap:10,marginBottom:12}}>
        <div style={{minWidth:0}}>
          <div style={{color:PB_INK,fontWeight:800,fontSize:13.5,letterSpacing:-.2}}>Perfis pra marcar</div>
          <div style={{color:PB_MUTE,fontSize:11.5,marginTop:3,lineHeight:1.45}}>
            {_isBioterCli
              ? "Contas oficiais + parceiros que devem ser marcados, separados por unidade."
              : "Contas oficiais + parceiros que devem ser marcados nas publicações desse cliente."}
          </div>
        </div>
        {!_isBioterCli && editMode && isAdmin && <button onClick={function(){_perfilAdd();}} type="button"
          style={{background:PINK+"14",color:PINK_DK,border:"1px solid "+PINK+"33",borderRadius:9,padding:"7px 13px",fontSize:11.5,fontWeight:700,cursor:"pointer",fontFamily:"inherit",display:"inline-flex",alignItems:"center",gap:5,flexShrink:0,whiteSpace:"nowrap",transition:"all .15s"}}
          onMouseEnter={function(e){e.currentTarget.style.background=PINK;e.currentTarget.style.color="#fff";}}
          onMouseLeave={function(e){e.currentTarget.style.background=PINK+"14";e.currentTarget.style.color=PINK_DK;}}>
          <Ico n="plus" size={12} color="currentColor"/> Adicionar perfil
        </button>}
      </div>;

      // ── BIOTER: colunas por unidade ──
      if(_isBioterCli){
        // Perfis sem unitId caem em coluna "geral" (compatibilidade backward)
        var _perfisOrfaos = perfis.filter(function(p){ return !p.unitId; });
        return <div>
          {_header}
<div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(340px,1fr))",gap:12}}>
            {_units.map(function(u){
              var _unitPerfis = perfis.map(function(p,idx){ return {p:p,idx:idx}; }).filter(function(x){ return x.p.unitId===u.id; });
              return <div key={u.id} style={{background:"#fff",border:"1px solid "+PB_BORDER2,borderRadius:12,padding:"12px 12px 10px",display:"flex",flexDirection:"column",gap:9,minWidth:0}}>
                <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:8}}>
                  <div style={{display:"flex",alignItems:"center",gap:8,minWidth:0}}>
                    <div style={{width:22,height:22,borderRadius:6,background:u.color,color:"#fff",display:"inline-flex",alignItems:"center",justifyContent:"center",fontSize:9.5,fontWeight:800,flexShrink:0,letterSpacing:.3}}>{u.abbr||u.label.slice(0,2)}</div>
                    <div style={{color:PB_INK,fontWeight:800,fontSize:12.5,letterSpacing:-.1,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{u.pickerLabel||u.label}</div>
                    {_unitPerfis.length>0 && <span style={{background:"#f1f5f9",color:"#64748b",fontSize:10,fontWeight:700,padding:"1px 7px",borderRadius:99,flexShrink:0}}>{_unitPerfis.length}</span>}
                  </div>
                </div>
                <div style={{display:"flex",flexDirection:"column",gap:7}}>
                  {_unitPerfis.length===0 && <div style={{color:PB_SOFT,fontSize:11,fontStyle:"italic",padding:"6px 2px",lineHeight:1.4}}>{editMode&&isAdmin?"Sem perfis. Adicione abaixo.":"Sem perfis."}</div>}
                  {_unitPerfis.map(function(x){ return _renderPerfilCard(x.p, x.idx); })}
                </div>
                {editMode && isAdmin && <button onClick={function(){_perfilAdd(u.id);}} type="button"
                  style={{background:"transparent",color:u.color,border:"1px dashed "+u.color+"66",borderRadius:8,padding:"7px 10px",fontSize:11,fontWeight:700,cursor:"pointer",fontFamily:"inherit",display:"inline-flex",alignItems:"center",justifyContent:"center",gap:5,width:"100%",transition:"all .15s",marginTop:2}}
                  onMouseEnter={function(e){e.currentTarget.style.background=u.color+"0d";e.currentTarget.style.borderStyle="solid";}}
                  onMouseLeave={function(e){e.currentTarget.style.background="transparent";e.currentTarget.style.borderStyle="dashed";}}>
                  <Ico n="plus" size={11} color="currentColor"/> Adicionar perfil
                </button>}
              </div>;
            })}
          </div>
        </div>;
      }

      // ── NAO-BIOTER: lista simples ──
      return <div>
        {_header}
        {perfis.length===0
          ? <_PbEmpty icon="users"
              text="Nenhum perfil cadastrado ainda."
              sub={editMode && isAdmin ? "Adicione o primeiro perfil com o botão acima." : (isAdmin ? "Use o botão abaixo pra adicionar." : "")}/>
          : <div style={{display:"flex",flexDirection:"column",gap:8}}>
              {perfis.map(function(p,i){ return _renderPerfilCard(p, i); })}
            </div>
        }
      </div>;
    })()}

    {/* ── Cadência semanal ── */}
    <div>
      <div style={{color:PB_INK,fontWeight:800,fontSize:13.5,letterSpacing:-.2,marginBottom:4}}>Cadência semanal</div>
      <div style={{color:PB_MUTE,fontSize:11.5,marginBottom:10,lineHeight:1.45}}>Quantos posts, stories e reels por semana esperamos entregar.</div>

      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(160px,1fr))",gap:10}}>
        {CADENCIA_FIELDS.map(function(f){
          return <div key={f.key} style={{background:"#fafbfc",border:"1px solid "+PB_BORDER2,borderRadius:10,padding:"10px 12px"}}>
            <div style={{color:PB_SOFT,fontSize:10.5,fontWeight:800,letterSpacing:.4,textTransform:"uppercase",marginBottom:4}}>{f.label}</div>
            {editMode && isAdmin
              ? <input value={cadencia[f.key]||""} onChange={function(e){var v={};v[f.key]=e.target.value;_cadenciaSet(v);}}
                  placeholder={f.ph}
                  style={Object.assign({},_pbInpStyle(),{padding:"6px 8px",fontSize:15,fontWeight:800,color:PB_INK,background:"#fff"})}/>
              : <div style={{color:PB_INK,fontWeight:800,fontSize:17,letterSpacing:-.3}}>
                  {cadencia[f.key] || <span style={{color:PB_SOFT,fontWeight:600,fontSize:13}}>—</span>}
                </div>
            }
          </div>;
        })}
      </div>
    </div>

    {/* ── Mix de tipos ── */}
    <div>
      <div style={{color:PB_INK,fontWeight:800,fontSize:13.5,letterSpacing:-.2,marginBottom:4}}>Mix de tipos de post</div>
      <div style={{color:PB_MUTE,fontSize:11.5,marginBottom:10,lineHeight:1.45}}>Quantos de cada tipo entram no mix semanal ou mensal.</div>

      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(150px,1fr))",gap:8}}>
        {MIX_FIELDS.map(function(m){
          return <div key={m.key} style={{background:"#fafbfc",border:"1px solid "+PB_BORDER2,borderRadius:10,padding:"9px 11px",display:"flex",alignItems:"center",gap:9}}>
            <div style={{width:30,height:30,borderRadius:8,background:PINK+"14",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
              <Ico n={m.icon} size={14} color={PINK_DK}/>
            </div>
            <div style={{flex:1,minWidth:0}}>
              <div style={{color:PB_SOFT,fontSize:9.5,fontWeight:800,letterSpacing:.4,textTransform:"uppercase"}}>{m.label}</div>
              {editMode && isAdmin
                ? <input value={mix[m.key]||""} onChange={function(e){var v={};v[m.key]=e.target.value;_mixSet(v);}}
                    placeholder="—"
                    style={Object.assign({},_pbInpStyle(),{padding:"3px 6px",fontSize:14,fontWeight:800,color:PB_INK,background:"#fff",marginTop:2})}/>
                : <div style={{color:PB_INK,fontWeight:800,fontSize:15,marginTop:1}}>
                    {mix[m.key] || <span style={{color:PB_SOFT,fontWeight:600,fontSize:12}}>—</span>}
                  </div>
              }
            </div>
          </div>;
        })}
      </div>
    </div>

    {/* ── Particularidades ── */}
    <div>
      <div style={{color:PB_INK,fontWeight:800,fontSize:13.5,letterSpacing:-.2,marginBottom:4}}>Particularidades das publicações</div>
      <div style={{color:PB_MUTE,fontSize:11.5,marginBottom:10,lineHeight:1.45}}>Detalhes específicos desse cliente: hashtags, tom de voz, formato de legenda, chamada de ação padrão, horários preferidos…</div>

      {editMode && isAdmin
        ? <_PbAutoTextarea value={particularidades}
            onChange={function(e){setParticularidades(e.target.value);}}
            onBlur={function(){_save({particularidades:particularidades});}}
            rows={5}
            placeholder="Ex: Sempre incluir hashtag #Bioter + hashtag da cidade. CTA padrão: 'fale com um consultor'. Evitar posts entre 22h e 6h…"
            style={_pbInpStyle()}/>
        : (particularidades
            ? <div style={{background:"#fafbfc",border:"1px solid "+PB_BORDER2,borderRadius:10,padding:"12px 14px",color:PB_TEXT,fontSize:13,lineHeight:1.6,whiteSpace:"pre-wrap"}}>{particularidades}</div>
            : <_PbEmpty icon="sparkles" text="Sem particularidades cadastradas." sub={isAdmin?"Preencha abaixo pra cadastrar.":""}/>
          )
      }
    </div>

    {/* ── Restrições ── */}
    <div>
      <div style={{color:PB_INK,fontWeight:800,fontSize:13.5,letterSpacing:-.2,marginBottom:4}}>Restrições · o que NÃO fazer</div>
      <div style={{color:PB_MUTE,fontSize:11.5,marginBottom:10,lineHeight:1.45}}>Regras, tabus, palavras proibidas, concorrentes que não podem ser mencionados…</div>

      {editMode && isAdmin
        ? <_PbAutoTextarea value={restricoes}
            onChange={function(e){setRestricoes(e.target.value);}}
            onBlur={function(){_save({restricoes:restricoes});}}
            rows={4}
            placeholder="Ex: Nunca mencionar concorrente X. Não usar tom informal. Evitar emojis. Nunca prometer prazo de entrega em post público…"
            style={_pbInpStyle()}/>
        : (restricoes
            ? <div style={{background:"#fef2f2",border:"1px solid #fecaca",borderRadius:10,padding:"12px 14px",color:"#7f1d1d",fontSize:13,lineHeight:1.6,whiteSpace:"pre-wrap"}}>{restricoes}</div>
            : <_PbEmpty icon="alert" text="Sem restrições cadastradas." sub={isAdmin?"Preencha abaixo pra cadastrar.":""}/>
          )
      }
    </div>

  </div>;
}

/* ── Normalizador de texto das tarefas/etapas ──
   Regra da casa (pedido 2026-09-01): sem pontuação e símbolos (!?.:; emojis...),
   sem CAIXA ALTA, espaços colapsados, primeira letra maiúscula.
   Mantém letras acentuadas, números e hífen (pré-moldados etc). ── */
function pxDemTexto(v){
  var s=String(v==null?"":v);
  s=s.replace(/[^0-9A-Za-z\u00C0-\u00FF\s\-]/g,"");
  s=s.replace(/\s+/g," ").trim();
  if(!s) return s;
  var letras=s.replace(/[^A-Za-z\u00C0-\u00FF]/g,"");
  if(letras.length>3&&letras===letras.toUpperCase()) s=s.toLowerCase();
  return s.charAt(0).toUpperCase()+s.slice(1);
}
/* ═══════════════════════════════════════════════════════════════════════
   DEMANDAS DO CLIENTE — Estrategia > Clientes > aba Demandas
   ───────────────────────────────────────────────────────────────────────
   Uma DEMANDA e um projeto/entrega maior (site, campanha, captacao...) que
   se quebra em TAREFAS. O progresso e sempre derivado das tarefas — nunca
   digitado a mao.

   Diferenca pra aba Producao: Producao e o fluxo operacional de pecas
   (cards que viram post/video). Demandas e o projeto que atravessa varias
   areas e responsaveis ate ficar pronto.

   Banco: client_demandas (tarefas em jsonb). A tabela client_milestones
   (marcos) NAO foi tocada — segue alimentando calendario, agenda e
   dashboard. O historico de marcos aparece no fim desta aba.

   Reuso: UserAvatar, Ico, TEAM, pixelsToast, pixelsConfirm, _pxMob.
═══════════════════════════════════════════════════════════════════════ */

const _DEM_FF = "'Inter',system-ui,-apple-system,sans-serif";

/* ── Catalogos ───────────────────────────────────────────────────────── */
// Preparado pra crescer: e so somar um item aqui que filtro, formulario e
// chip do card passam a conhecer a categoria nova.
const DEM_CATEGORIAS = [
  {id:"estrategia", label:"Estratégia",        cor:"#7c3aed", ico:"target"},
  {id:"social",     label:"Social media",      cor:"#ec4899", ico:"users"},
  {id:"conteudo",   label:"Conteúdo",          cor:"#f59e0b", ico:"fileText"},
  {id:"design",     label:"Design",            cor:"#a855f7", ico:"sparkles"},
  {id:"video",      label:"Vídeo / captação",  cor:"#0ea5e9", ico:"play"},
  {id:"roteiro",    label:"Roteiro",           cor:"#0891b2", ico:"mic"},
  {id:"trafego",    label:"Campanha",          cor:"#2563eb", ico:"funnel"},
  {id:"conjunto",   label:"Conjunto de anúncio",cor:"#7c3aed", ico:"layers"},
  {id:"anuncio",    label:"Anúncio",           cor:"#dc2626", ico:"image"},
  {id:"site",       label:"Site",              cor:"#0d9488", ico:"globe"},
  {id:"landing",    label:"Landing page",      cor:"#059669", ico:"table"},
  {id:"branding",   label:"Branding",          cor:"#db2777", ico:"sparkles"},
  {id:"grafico",    label:"Material gráfico",  cor:"#ea580c", ico:"image"},
  {id:"crm",        label:"CRM / automação",   cor:"#4f46e5", ico:"layers"},
  {id:"campanha",   label:"Campanha (antigo)", cor:"#dc2626", ico:"flame", legado:true},
  {id:"evento",     label:"Evento",            cor:"#16a34a", ico:"calendar"},
  {id:"reuniao",    label:"Reunião",           cor:"#0284c7", ico:"users"},
  {id:"operacional",label:"Operacional",       cor:"#475569", ico:"settings"},
  {id:"outros",     label:"Outros",            cor:"#64748b", ico:"folder"},
];
// Categorias que vivem na GESTÃO DE MÍDIA (fora da central de Demandas)
const _DEM_CATS_MIDIA=["trafego","conjunto","anuncio","campanha"];
function _demCat(id){
  return DEM_CATEGORIAS.find(function(c){return c.id===id;}) || DEM_CATEGORIAS[DEM_CATEGORIAS.length-1];
}

const DEM_STATUS = [
  // Cores no espírito da Linha de produção (rainbow): slate → amber → rosa → lime → verde → slate
  {id:"nao_iniciada", label:"Não iniciada",      cor:"#94a3b8", bg:"#f1f5f9", ico:"inbox"},
  {id:"andamento",    label:"Em andamento",      cor:"#f59e0b", bg:"#fffbeb", ico:"play"},
  {id:"aguardando",   label:"Aguardando cliente",cor:"#ec4899", bg:"#fdf2f8", ico:"clock"},
  {id:"revisao",      label:"Em revisão",        cor:"#84cc16", bg:"#f7fee7", ico:"eye"},
  {id:"concluida",    label:"Concluída",         cor:"#16a34a", bg:"#f0fdf4", ico:"check"},
  {id:"pausada",      label:"Pausada",           cor:"#64748b", bg:"#f8fafc", ico:"moreHor"},
];
function _demSt(id){
  return DEM_STATUS.find(function(s){return s.id===id;}) || DEM_STATUS[0];
}

// Status de TAREFA — enxuto de proposito
const DEM_TSTATUS = [
  {id:"afazer",     label:"A fazer",      cor:"#94a3b8", bg:"#f8fafc"},
  {id:"andamento",  label:"Em andamento", cor:"#2563eb", bg:"#eff6ff"},
  {id:"aguardando", label:"Aguardando",   cor:"#b45309", bg:"#fffbeb"},
  {id:"revisao",    label:"Em revisão",   cor:"#7c3aed", bg:"#f5f3ff"},
  {id:"concluida",  label:"Concluída",    cor:"#15803d", bg:"#f0fdf4"},
];
function _demTSt(id){
  return DEM_TSTATUS.find(function(s){return s.id===id;}) || DEM_TSTATUS[0];
}

const DEM_PRIOS = [
  {id:"baixa",   label:"Baixa",   cor:"#94a3b8"},
  {id:"normal",  label:"Normal",  cor:"#64748b"},
  {id:"alta",    label:"Alta",    cor:"#ea580c"},
  {id:"urgente", label:"Urgente", cor:"#dc2626"},
];
function _demPrio(id){
  return DEM_PRIOS.find(function(p){return p.id===id;}) || DEM_PRIOS[1];
}

/* ── Utilitarios de data ─────────────────────────────────────────────── */
function _demHoje(){
  const d=new Date();
  return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0");
}
function _demBR(iso){
  if(!iso) return "";
  const p=String(iso).split("-");
  return p.length===3 ? (p[2]+"/"+p[1]+"/"+p[0]) : "";
}
function _demBRCurto(iso){
  if(!iso) return "";
  const d=String(iso).slice(0,10).split("-");
  return d.length===3 ? (d[2]+"/"+d[1]) : "";
}
// "20/08 às 14:32" a partir de um ISO completo (ou so a data, se nao tiver hora)
function _demQuando(iso){
  if(!iso) return "";
  try{
    const s=String(iso);
    const base=_demBRCurto(s);
    if(s.length>10){
      const d=new Date(s);
      if(!isNaN(d)) return base+" às "+String(d.getHours()).padStart(2,"0")+":"+String(d.getMinutes()).padStart(2,"0");
    }
    return base;
  }catch(_){ return ""; }
}
// Quantos dias faltam (negativo = atrasado)
function _demDias(iso){
  if(!iso) return null;
  try{
    const a=new Date(iso+"T12:00:00");
    const b=new Date(_demHoje()+"T12:00:00");
    return Math.round((a-b)/86400000);
  }catch(_){ return null; }
}
// Sinal de prazo — discreto de proposito: so vira vermelho quando ja passou.
function _demPrazoTom(iso, concluida){
  if(!iso || concluida) return null;
  const d=_demDias(iso);
  if(d===null) return null;
  if(d<0)  return {tom:"atrasado", cor:"#dc2626", bg:"#fef2f2", bd:"#fecaca", txt:(d===-1?"1 dia atrasado":(Math.abs(d)+" dias atrasado"))};
  if(d===0) return {tom:"hoje",    cor:"#b45309", bg:"#fffbeb", bd:"#fde68a", txt:"vence hoje"};
  if(d<=3)  return {tom:"perto",   cor:"#b45309", bg:"#fffbeb", bd:"#fde68a", txt:(d===1?"falta 1 dia":("faltam "+d+" dias"))};
  return null;
}

/* ── Progresso: SEMPRE derivado das tarefas ──────────────────────────── */
function _demProgresso(d){
  const ts=Array.isArray(d&&d.tarefas)?d.tarefas:[];
  const tot=ts.length;
  const ok=ts.filter(function(t){return t&&t.status==="concluida";}).length;
  // Demanda concluída = 100%, independente das etapas marcadas
  if(d&&d.status==="concluida") return {total:tot, feitas:ok, pct:100};
  return {total:tot, feitas:ok, pct: tot>0 ? Math.round(ok/tot*100) : 0};
}

// Data de conclusao da demanda: a maior done_at das etapas; sem etapas, updated_at.
function _demConcluidaEm(d){
  const ts=Array.isArray(d&&d.tarefas)?d.tarefas:[];
  let max="";
  ts.forEach(function(t){ if(t&&t.done_at&&String(t.done_at)>max) max=String(t.done_at); });
  return max || (d&&d.updated_at) || "";
}

// Bolinha de prioridade — substitui o chip escrito (pedido do time: menos texto)
// Cliente da demanda pro card: nome na cor do cliente + logo. Bioter resolve
// a UNIDADE (client_id raiz "bioter" + campo unidade → "Bioter Chapecó" etc).
const _DEM_BIOTER_UNIDADES={chapeco:"Chapecó",toledo:"Toledo",castro:"Castro",gloria:"Glória",uberlandia:"Uberlândia",paraguay:"Paraguay"};
function _demCliChip(d){
  const all=(typeof CLIENTS!=="undefined")?CLIENTS:[];
  const raiz=all.find(function(x){return x.id===d.client_id;});
  if(!raiz) return null;
  let nome=raiz.name, cor=raiz.color||"#64748b", idLogo=raiz.id, logoUrl=raiz.logoUrl;
  if(d.client_id==="bioter"){
    // "Bioter" seco (sem "Grupo") + unidade com acento certo
    const _un=(d.unidade&&d.unidade!=="grupo")?String(d.unidade):"";
    let u=_un?all.find(function(x){return x.id==="bioter_"+_un;}):null;
    if(!u&&_un&&typeof BIOTER_GROUP_UNITS!=="undefined"&&Array.isArray(BIOTER_GROUP_UNITS))
      u=BIOTER_GROUP_UNITS.find(function(x){return x.id==="bioter_"+_un;})||null;
    const _unNome=_un?(_DEM_BIOTER_UNIDADES[_un]||( _un.charAt(0).toUpperCase()+_un.slice(1) )):"";
    nome="Bioter"+(_unNome?(" · "+_unNome):"");
    if(u){ cor=u.color||cor; idLogo=u.id; logoUrl=u.logoUrl||logoUrl; }
  }
  // Pixels (demandas internas): a logo já diz tudo — sem texto
  if(raiz.id==="pixels"||raiz.id==="interno") nome="";
  const L=(typeof CLIENT_LOGOS!=="undefined"&&CLIENT_LOGOS)?CLIENT_LOGOS:{};
  return {nome:nome, cor:cor, logo:L[idLogo]||logoUrl||L[raiz.id]||raiz.logoUrl||null, titulo:nome||raiz.name};
}
// Demanda que nasceu no portal do cliente (solicitação) — fica sincronizada lá.
function _demDoPortal(d){ return /(^|:)portal_/.test(String((d&&d.created_by)||"")); }
// Chip "Portal" (veio do cliente) ou "No portal" (interna que foi enviada pro portal)
function _DemPortalTag({d, mini}){
  const _doPortal=_demDoPortal(d);
  if(!_doPortal && !d.portal_visivel) return null;
  const _fs=mini?9:10, _pad=mini?"0 6px":"1px 8px";
  if(_doPortal) return <span title="Solicitada pelo cliente no portal — sincronizada automaticamente lá"
    style={{background:"#eff6ff",color:"#2563eb",border:"1px solid #bfdbfe",borderRadius:99,padding:_pad,
      fontSize:_fs,fontWeight:800,whiteSpace:"nowrap",display:"inline-flex",alignItems:"center",gap:4,flexShrink:0}}>
    <svg width={mini?8:9} height={mini?8:9} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"/><line x1="2" y1="12" x2="22" y2="12"/><path d="M12 2a15.3 15.3 0 014 10 15.3 15.3 0 01-4 10 15.3 15.3 0 01-4-10 15.3 15.3 0 014-10z"/></svg>
    Portal
  </span>;
  return <span title="Demanda interna enviada pro portal — o cliente está vendo"
    style={{background:"#f0fdfa",color:"#0d9488",border:"1px solid #99f6e4",borderRadius:99,padding:_pad,
      fontSize:_fs,fontWeight:800,whiteSpace:"nowrap",display:"inline-flex",alignItems:"center",gap:4,flexShrink:0}}>
    <svg width={mini?8:9} height={mini?8:9} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>
    No portal
  </span>;
}
function _DemPrioDot({prio}){
  if(!prio || prio.id==="normal" || prio.id==="baixa") return null;
  return <span title={"Prioridade "+prio.label}
    style={{width:9,height:9,borderRadius:"50%",background:prio.cor,flexShrink:0,
      boxShadow:"0 0 0 3px "+prio.cor+"22"}}/>;
}

function _demMembro(id){
  try{
    if(!id || typeof TEAM==="undefined") return null;
    return TEAM.find(function(u){return u.id===id;}) || null;
  }catch(_){ return null; }
}

function _demNovoId(){
  return "t-"+Date.now()+"-"+Math.random().toString(36).slice(2,6);
}

/* ═══ CHIP DE STATUS ═══ */
function _DemChip({def, size}){
  const _s = size==="sm";
  return <span style={{background:def.bg,color:def.cor,border:"1px solid "+def.cor+"2e",borderRadius:99,
    padding:_s?"2px 8px":"3px 10px",fontSize:_s?10:10.5,fontWeight:800,letterSpacing:.2,
    whiteSpace:"nowrap",flexShrink:0,fontFamily:_DEM_FF}}>{def.label}</span>;
}

/* ═══ BARRA DE PROGRESSO ═══ */
function _DemBarra({pct, cor, altura}){
  const _h = altura || 7;
  const _completo = pct>=100;
  return <div style={{background:"#f1f5f9",borderRadius:99,height:_h,overflow:"hidden",width:"100%"}}>
    <div style={{width:Math.max(0,Math.min(100,pct))+"%",height:"100%",borderRadius:99,
      background:_completo?"linear-gradient(90deg,#16a34a,#22c55e)":"linear-gradient(90deg,"+cor+","+cor+"bb)",
      transition:"width .35s ease"}}/>
  </div>;
}

/* ═══ SELECT PADRAO ═══ */
const _DEM_LBL = {color:"#94a3b8",fontSize:10,fontWeight:800,textTransform:"uppercase",letterSpacing:.7,marginBottom:6};
const _DEM_INP = {width:"100%",background:"#fff",border:"1px solid #e2e8f0",borderRadius:10,padding:"9px 12px",
  color:"#0f172a",fontSize:12.5,fontWeight:600,outline:"none",fontFamily:_DEM_FF,boxSizing:"border-box",transition:"all .12s"};
function _demFoco(e){ e.currentTarget.style.borderColor="#a855f7"; e.currentTarget.style.boxShadow="0 0 0 3px rgba(168,85,247,.13)"; }
function _demBlur(e){ e.currentTarget.style.borderColor="#e2e8f0"; e.currentTarget.style.boxShadow="none"; }

/* ═══════════════════════════════════════════════════════════════════════
   CARD DA DEMANDA — horizontal, expande em linha (accordion)
═══════════════════════════════════════════════════════════════════════ */
function _DemandaCard({d, aberto, onToggle, onEditar, onExcluir, onSalvar, onPortal, onContexto, onPatchDemanda, canEdit, isMob, corCliente, mostrarCliente}){
  const _cli = mostrarCliente && typeof CLIENTS!=="undefined"
    ? CLIENTS.find(function(c){ return c.id===d.client_id; })
    : null;
  const cat=_demCat(d.categoria);
  const st=_demSt(d.status);
  const prio=_demPrio(d.prioridade);
  const prog=_demProgresso(d);
  const resp=_demMembro(d.responsavel);
  const _concluida = d.status==="concluida";
  const _prazo=_demPrazoTom(d.prazo,_concluida);

  return <div style={{background:"#fff",border:"1px solid "+(aberto?"#d3d9e2":"#e8ebf0"),borderRadius:14,
    boxShadow:aberto?"0 8px 24px rgba(15,23,42,.08)":"0 1px 3px rgba(15,23,42,.04)",
    overflow:"hidden",transition:"border-color .15s, box-shadow .15s",fontFamily:_DEM_FF}}>

    {/* ── Linha principal (clicavel) ── */}
    <div onClick={onToggle} title={aberto?"Fechar":"Ver etapas"}
      onContextMenu={onContexto?function(e){ e.preventDefault(); onContexto(d, e.clientX, e.clientY); }:undefined}
      style={{display:"flex",alignItems:isMob?"stretch":"center",gap:isMob?11:16,padding:isMob?"14px 15px":"15px 18px",
        cursor:"pointer",flexDirection:isMob?"column":"row"}}
      onMouseEnter={function(e){ if(!aberto) e.currentTarget.style.background="#fcfcfd"; }}
      onMouseLeave={function(e){ e.currentTarget.style.background="transparent"; }}>

      {/* Titulo + meta — enxuto: logo do cliente, bolinha de prioridade, titulo, data */}
      <div style={{flex:isMob?"none":"1 1 240px",minWidth:0}}>
        <div style={{display:"flex",alignItems:"center",gap:8,flexWrap:"wrap"}}>
          {mostrarCliente && (function(){
            const _chip=_demCliChip(d);
            if(!_chip) return null;
            return <span title={_chip.titulo} style={{display:"inline-flex",alignItems:"center",gap:6,minWidth:0,flexShrink:0,
              background:"linear-gradient(135deg,"+_chip.cor+"1f,"+_chip.cor+"0d)",
              border:"1px solid "+_chip.cor+"40",borderRadius:99,padding:"3.5px 11px 3.5px 7px",
              backdropFilter:"blur(6px)",WebkitBackdropFilter:"blur(6px)",
              boxShadow:"inset 0 1px 0 rgba(255,255,255,.5)"}}>
              {_chip.logo&&<img src={_chip.logo} alt="" style={{height:13,maxWidth:50,objectFit:"contain",flexShrink:0}}/>}
              {(!!_chip.nome||!_chip.logo)&&<span style={{color:_chip.cor,fontSize:9.5,fontWeight:800,letterSpacing:.7,textTransform:"uppercase",minWidth:0,
                overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap",maxWidth:150}}>{_chip.nome||_chip.titulo}</span>}
            </span>;
          })()}
          <span style={{color:"#0f172a",fontWeight:400,fontSize:14,letterSpacing:-.1,lineHeight:1.3,
            textDecoration:_concluida?"line-through":"none",opacity:_concluida?.7:1}}>{d.titulo}</span>
          <_DemPortalTag d={d}/>
        </div>
        <div style={{display:"flex",alignItems:"center",gap:8,marginTop:5,flexWrap:"wrap"}}>
          <span style={{color:"#94a3b8",fontSize:10.5,fontWeight:600,display:"inline-flex",alignItems:"center",gap:4}}>
            {typeof Ico==="function"&&<Ico n={cat.ico||"folder"} size={10} color="#94a3b8"/>}
            {cat.label}
          </span>
          {d.prazo && !_concluida && <span title={"Prazo final: "+_demBR(d.prazo)}
            style={{color:_prazo?_prazo.cor:"#64748b",fontSize:11,fontWeight:800,display:"inline-flex",alignItems:"center",gap:4,fontFeatureSettings:"'tnum'"}}>
            {typeof Ico==="function"&&<Ico n="flame" size={11} color="currentColor"/>}
            {_demBRCurto(d.prazo)}{d.hora?(" · "+String(d.hora).slice(0,5)):""}
          </span>}
          {d.cidade&&<span title={"Cidade: "+d.cidade}
            style={{color:"#64748b",fontSize:10.5,fontWeight:700,display:"inline-flex",alignItems:"center",gap:3}}>
            <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0118 0z"/><circle cx="12" cy="10" r="3"/></svg>
            {d.cidade}
          </span>}
          {_prazo && !_concluida && (function(){
            const _dd=_demDias(d.prazo);
            return (_dd!==null&&_dd<0)
              ? <span style={{color:"#dc2626",fontSize:10.5,fontWeight:800,whiteSpace:"nowrap",fontFeatureSettings:"'tnum'"}}>{Math.abs(_dd)}d atraso</span>
              : null;
          })()}
          {_concluida && <span title={"Concluída em "+_demBR(_demConcluidaEm(d))}
            style={{background:"#f0fdf4",color:"#15803d",border:"1px solid #bbf7d0",borderRadius:99,
              padding:"2px 9px",fontSize:10.5,fontWeight:800,display:"inline-flex",alignItems:"center",gap:4,fontFeatureSettings:"'tnum'"}}>
            <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
            Concluída em {_demBRCurto(_demConcluidaEm(d))}
          </span>}
        </div>
      </div>

      {/* Responsavel */}
      <div style={{display:"flex",alignItems:"center",gap:7,minWidth:isMob?0:110,flexShrink:0}}>
        {resp
          ? <>
              <UserAvatar user={resp} size={24} border={false}/>
              <span style={{color:"#475569",fontSize:12,fontWeight:700,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{String(resp.name||"").split(" ")[0]}</span>
            </>
          : <span style={{color:"#cbd5e1",fontSize:11.5,fontWeight:600,fontStyle:"italic"}}>sem responsável</span>}
      </div>

      {/* Progresso — GRANDE: e o que diz se tem coisa pra concluir ali dentro */}
      <div style={{minWidth:isMob?0:190,flexShrink:0}}>
        <div style={{display:"flex",alignItems:"baseline",justifyContent:"space-between",gap:8,marginBottom:6}}>
          {prog.total>0
            ? <span style={{color:"#0f172a",fontSize:13,fontWeight:800,fontFeatureSettings:"'tnum'",letterSpacing:-.2}}>
                {prog.feitas}<span style={{color:"#94a3b8",fontWeight:700}}>/{prog.total}</span>
                <span style={{color:"#64748b",fontSize:11,fontWeight:700,marginLeft:5}}>etapas</span>
              </span>
            : <span/>}
          <span style={{color:prog.pct>=100?"#16a34a":"#7c3aed",fontSize:14,fontWeight:800,letterSpacing:-.3,fontFeatureSettings:"'tnum'"}}>{prog.pct}%</span>
        </div>
        <_DemBarra pct={prog.pct} cor={prog.pct>=100?"#16a34a":"#7c3aed"} altura={8}/>
      </div>

      {/* Status + chevron */}
      <div style={{display:"flex",alignItems:"center",gap:10,flexShrink:0,justifyContent:isMob?"space-between":"flex-end"}}>
        <_DemChip def={st}/>
        <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#94a3b8" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round"
          style={{flexShrink:0,transition:"transform .18s",transform:aberto?"rotate(180deg)":"rotate(0deg)"}}>
          <polyline points="6 9 12 15 18 9"/>
        </svg>
      </div>
    </div>

    {/* ── Corpo expandido ── */}
    {aberto && <_DemandaDetalhe d={d} cat={cat} prog={prog} canEdit={canEdit} isMob={isMob}
      onEditar={onEditar} onExcluir={onExcluir} onSalvar={onSalvar} onPortal={onPortal} onPatchDemanda={onPatchDemanda}/>}
  </div>;
}

/* ═══════════════════════════════════════════════════════════════════════
   DETALHE — cabecalho + lista de tarefas
═══════════════════════════════════════════════════════════════════════ */
function _DemandaDetalhe({d, cat, prog, canEdit, isMob, onEditar, onExcluir, onSalvar, onPortal, onPatchDemanda}){
  const [novaAberta,setNovaAberta]=useState(false);
  const [rascunho,setRascunho]=useState({nome:"",resp:"",prazo:"",status:"afazer",obs:""});
  const [editId,setEditId]=useState(null);
  const [dragId,setDragId]=useState(null);
  const [overId,setOverId]=useState(null);

  const tarefas=Array.isArray(d.tarefas)?d.tarefas:[];
  // Ref sempre com a versão MAIS RECENTE — operações em sequência (ex: "Todas:"
  // pessoa e depois data) compõem em vez de uma sobrescrever a outra.
  const _tarefasRef=useRef(tarefas);
  _tarefasRef.current=tarefas;
  const _agora=function(){ return Array.isArray(_tarefasRef.current)?_tarefasRef.current:[]; };

  const _persistTarefas=function(lista){
    _tarefasRef.current=lista;
    onSalvar(Object.assign({},d,{tarefas:lista}));
  };
  const _addTarefa=function(){
    const _n=pxDemTexto(rascunho.nome);
    if(!_n){ if(typeof pixelsToast!=="undefined") pixelsToast.warning("Dá um nome pra tarefa."); return; }
    const _t=Object.assign({id:_demNovoId(), done_at:"", done_by:""}, rascunho, {nome:_n});
    if(_t.status==="concluida"){
      _t.done_at=new Date().toISOString();
      _t.done_by=(typeof CURRENT_USER!=="undefined"&&CURRENT_USER)?CURRENT_USER.id:"";
    }
    _persistTarefas(_agora().concat([_t]));
    setRascunho({nome:"",resp:"",prazo:"",status:"afazer",obs:""});
    setNovaAberta(false);
  };
  const _patchTarefa=function(id, patch){
    _persistTarefas(_agora().map(function(t){
      if(t.id!==id) return t;
      const _novo=Object.assign({},t,patch);
      // Concluir carimba QUEM e QUANDO automaticamente; desmarcar limpa.
      if(patch.status==="concluida" && t.status!=="concluida"){
        _novo.done_at=new Date().toISOString();
        _novo.done_by=(typeof CURRENT_USER!=="undefined"&&CURRENT_USER)?CURRENT_USER.id:"";
      }
      if(patch.status && patch.status!=="concluida"){ _novo.done_at=""; _novo.done_by=""; }
      return _novo;
    }));
  };
  const _delTarefa=async function(t){
    let ok=true;
    if(typeof pixelsConfirm==="function"){
      ok=await pixelsConfirm({title:"Excluir tarefa?",message:'"'+(t.nome||"")+'" será removida da demanda.',danger:true});
    }
    if(!ok) return;
    _persistTarefas(_agora().filter(function(x){return x.id!==t.id;}));
  };
  // Reordenar: as tarefas ja vivem num array jsonb, entao e so trocar de lugar.
  const _mover=function(fromId,toId){
    if(!fromId||!toId||fromId===toId) return;
    const arr=_agora().slice();
    const fi=arr.findIndex(function(x){return x.id===fromId;});
    const ti=arr.findIndex(function(x){return x.id===toId;});
    if(fi<0||ti<0) return;
    const it=arr.splice(fi,1)[0];
    arr.splice(ti,0,it);
    _persistTarefas(arr);
  };

  const resp=_demMembro(d.responsavel);
  const prio=_demPrio(d.prioridade);
  const _proxima=tarefas.find(function(t){return t.status!=="concluida";});

  return <div style={{borderTop:"1px solid #f1f5f9",background:"#fcfcfd",padding:isMob?"15px 15px 17px":"17px 20px 19px",
    display:"flex",flexDirection:"column",gap:15}}>

    {/* ── Cabecalho de dados — EDITÁVEL direto na ficha (autosave) ── */}
    {(canEdit&&onPatchDemanda)?(function(){
      const _cel={background:"#fff",border:"1px solid #eef0f3",borderRadius:10,padding:"8px 11px",minWidth:0};
      const _lb={color:"#94a3b8",fontSize:9.5,fontWeight:800,textTransform:"uppercase",letterSpacing:.6,marginBottom:4};
      const _sel={width:"100%",background:"transparent",border:"none",outline:"none",cursor:"pointer",
        color:"#0f172a",fontSize:12.5,fontWeight:800,fontFamily:_DEM_FF,letterSpacing:-.15,padding:0};
      return <>
      <input key={"tt"+d.id} defaultValue={d.titulo||""} placeholder="Título da demanda"
        onBlur={function(e){ const v=String(e.target.value||"").trim(); if(v&&v!==d.titulo) onPatchDemanda(d,{titulo:v}); }}
        style={{width:"100%",background:"#fff",border:"1px solid #eef0f3",borderRadius:10,padding:"10px 13px",
          fontSize:14,fontWeight:600,color:"#0f172a",outline:"none",fontFamily:_DEM_FF,boxSizing:"border-box"}}/>
      <div style={{display:"grid",gridTemplateColumns:isMob?"1fr 1fr":"repeat(auto-fit,minmax(140px,1fr))",gap:10}}>
        <div style={_cel}>
          <div style={_lb}>Categoria</div>
          <select value={d.categoria||"outros"} onChange={function(e){onPatchDemanda(d,{categoria:e.target.value});}} style={_sel}>
            {DEM_CATEGORIAS.map(function(c){return <option key={c.id} value={c.id}>{c.label}</option>;})}
          </select>
        </div>
        <div style={_cel}>
          <div style={_lb}>Status</div>
          <select value={d.status||"nao_iniciada"} onChange={function(e){onPatchDemanda(d,{status:e.target.value});}} style={_sel}>
            {DEM_STATUS.map(function(st){return <option key={st.id} value={st.id}>{st.label}</option>;})}
          </select>
        </div>
        <div style={_cel}>
          <div style={_lb}>Prioridade</div>
          <select value={d.prioridade||"normal"} onChange={function(e){onPatchDemanda(d,{prioridade:e.target.value});}}
            style={Object.assign({},_sel,{color:prio.cor})}>
            {DEM_PRIOS.map(function(pp){return <option key={pp.id} value={pp.id}>{pp.label}</option>;})}
          </select>
        </div>
        <div style={_cel}>
          <div style={_lb}>Responsável</div>
          <div style={{display:"flex",alignItems:"center",gap:6}}>
            <_DemRespPicker mini valor={d.responsavel||""} onChange={function(v){onPatchDemanda(d,{responsavel:v});}}/>
            <span style={{color:"#0f172a",fontSize:12,fontWeight:700,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>
              {(resp&&String(resp.name||"").split(" ")[0])||"—"}</span>
          </div>
        </div>
        <div style={_cel}>
          <div style={_lb}>Início</div>
          <_DemDataInput compacto valor={d.data_inicio||""} placeholder="Definir"
            onChange={function(v){onPatchDemanda(d,{data_inicio:v||null});}}/>
        </div>
        <div style={_cel}>
          <div style={_lb}>Prazo final</div>
          <_DemDataInput compacto valor={d.prazo||""} placeholder="Definir"
            onChange={function(v){onPatchDemanda(d,{prazo:v||null});}}/>
        </div>
      </div>
      <textarea key={"dd"+d.id} defaultValue={d.descricao||""} rows={2} placeholder="Descrição / objetivo da demanda…"
        onBlur={function(e){ const v=String(e.target.value||""); if(v!==(d.descricao||"")) onPatchDemanda(d,{descricao:v}); }}
        style={{width:"100%",background:"#fff",border:"1px solid #eef0f3",borderRadius:11,padding:"10px 13px",
          color:"#475569",fontSize:12.5,lineHeight:1.6,outline:"none",resize:"vertical",fontFamily:_DEM_FF,boxSizing:"border-box"}}/>
      </>;
    })():<>
    <div style={{display:"grid",gridTemplateColumns:isMob?"1fr 1fr":"repeat(auto-fit,minmax(120px,1fr))",gap:10}}>
      {[
        {l:"Início",     v:_demBR(d.data_inicio)||"—"},
        {l:"Prazo final",v:(_demBR(d.prazo)||"—")+(d.hora?(" às "+String(d.hora).slice(0,5)):"")},
        (d.cidade?{l:"Cidade",v:d.cidade}:null),
        {l:"Prioridade", v:prio.label, cor:prio.cor},
        {l:"Responsável",v:(resp&&resp.name)||"—"},
        {l:"Progresso",  v:prog.pct+"%", cor:prog.pct>=100?"#16a34a":cat.cor},
      ].filter(Boolean).map(function(x,i){
        return <div key={i} style={{background:"#fff",border:"1px solid #eef0f3",borderRadius:10,padding:"9px 12px"}}>
          <div style={{color:"#94a3b8",fontSize:9.5,fontWeight:800,textTransform:"uppercase",letterSpacing:.6}}>{x.l}</div>
          <div style={{color:x.cor||"#0f172a",fontSize:12.5,fontWeight:800,marginTop:3,letterSpacing:-.15,fontFeatureSettings:"'tnum'",
            overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{x.v}</div>
        </div>;
      })}
    </div>
    {d.descricao && <div style={{background:"#fff",border:"1px solid #eef0f3",borderRadius:11,padding:"11px 14px",
      color:"#475569",fontSize:12.5,lineHeight:1.6,whiteSpace:"pre-wrap"}}>{d.descricao}</div>}
    {/* Anexos enviados pelo cliente no portal (client_demandas.anexos) */}
    {Array.isArray(d.anexos)&&d.anexos.length>0&&<div style={{background:"#fff",border:"1px solid #eef0f3",borderRadius:11,padding:"10px 14px"}}>
      <div style={{color:"#94a3b8",fontSize:9.5,fontWeight:800,letterSpacing:.6,textTransform:"uppercase",marginBottom:8}}>Anexos do cliente · {d.anexos.length}</div>
      <div style={{display:"flex",flexDirection:"column",gap:6}}>
        {d.anexos.map(function(a,i){
          const _t=String(a.type||"");
          const _ico=_t.indexOf("video/")===0?"film":_t.indexOf("image/")===0?"image":"file";
          const _mb=a.size?(a.size<1024*1024?Math.max(1,Math.round(a.size/1024))+" KB":(a.size/1024/1024).toFixed(a.size<10*1024*1024?1:0)+" MB"):"";
          return <a key={(a.path||a.url||"")+i} href={a.url} target="_blank" rel="noopener noreferrer"
            style={{display:"flex",alignItems:"center",gap:10,padding:"8px 10px",borderRadius:9,background:"#f8fafc",border:"1px solid #f1f5f9",textDecoration:"none",color:"inherit"}}
            onMouseEnter={function(e){e.currentTarget.style.borderColor="#c4b5fd";e.currentTarget.style.background="#faf5ff";}}
            onMouseLeave={function(e){e.currentTarget.style.borderColor="#f1f5f9";e.currentTarget.style.background="#f8fafc";}}>
            <span style={{width:26,height:26,borderRadius:7,background:"#ede9fe",display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0}}><Ico n={_ico} size={12} color="#7c3aed"/></span>
            <span style={{flex:1,minWidth:0,color:"#0f172a",fontSize:12.5,fontWeight:600,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{a.name||"arquivo"}</span>
            {_mb&&<span style={{color:"#94a3b8",fontSize:10.5,flexShrink:0}}>{_mb}</span>}
            <Ico n="download" size={12} color="#94a3b8"/>
          </a>;
        })}
      </div>
    </div>}
    </>}

    {/* ── Tarefas ── */}
    <div>
      <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:10,flexWrap:"wrap"}}>
        <span style={{color:"#0f172a",fontSize:12,fontWeight:800,letterSpacing:-.1,display:"inline-flex",alignItems:"center",gap:7}}>
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke={cat.cor} strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><polyline points="9 11 12 14 22 4"/><path d="M21 12v7a2 2 0 01-2 2H5a2 2 0 01-2-2V5a2 2 0 012-2h11"/></svg>
          Etapas
        </span>
        <span style={{color:"#94a3b8",fontSize:11,fontWeight:700,fontFeatureSettings:"'tnum'"}}>{prog.feitas}/{prog.total}</span>
        <span style={{flex:1,height:1,background:"linear-gradient(90deg,#e2e8f0,transparent)"}}/>
        {canEdit&&tarefas.length>1&&<span title="Aplica em TODAS as etapas de uma vez"
          style={{display:"inline-flex",alignItems:"center",gap:6,flexShrink:0,background:"#f8fafc",
            border:"1px solid #eef0f3",borderRadius:99,padding:"3px 10px 3px 12px"}}>
          <span style={{color:"#94a3b8",fontSize:9.5,fontWeight:800,textTransform:"uppercase",letterSpacing:.4}}>Todas:</span>
          <_DemRespPicker mini valor="" onChange={function(v){
            _persistTarefas(_agora().map(function(t){ return Object.assign({},t,{resp:v}); }));
            if(typeof pixelsToast!=="undefined") pixelsToast.success(v?"Responsável aplicado em todas as etapas.":"Responsável removido de todas as etapas.");
          }}/>
          <_DemDataInput compacto valor="" placeholder="Data" onChange={function(v){
            _persistTarefas(_agora().map(function(t){ return Object.assign({},t,{prazo:v}); }));
            if(typeof pixelsToast!=="undefined") pixelsToast.success(v?"Prazo aplicado em todas as etapas.":"Prazo removido de todas as etapas.");
          }}/>
        </span>}
        {canEdit && <button type="button" onClick={function(){setNovaAberta(!novaAberta);}}
          style={{background:novaAberta?"#f1f5f9":"#fff",border:"1px solid "+cat.cor+"44",borderRadius:9,padding:"6px 12px",
            color:cat.cor,fontSize:11.5,fontWeight:800,cursor:"pointer",fontFamily:_DEM_FF,display:"inline-flex",alignItems:"center",gap:6,flexShrink:0}}>
          <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
          Adicionar tarefa
        </button>}
      </div>

      {/* Form rapido de nova tarefa */}
      {novaAberta && canEdit && <div style={{background:"#fff",border:"1.5px solid "+cat.cor+"44",borderRadius:11,padding:"12px 13px",marginBottom:10,
        display:"grid",gridTemplateColumns:isMob?"1fr":"minmax(0,2fr) 130px 120px 110px auto",gap:8,alignItems:"end"}}>
        <div>
          <div style={_DEM_LBL}>Tarefa</div>
          <input autoFocus value={rascunho.nome} placeholder="Ex: Desenvolvimento do layout"
            onChange={function(e){setRascunho(Object.assign({},rascunho,{nome:e.target.value}));}}
            onKeyDown={function(e){ if(e.key==="Enter") _addTarefa(); }}
            onFocus={_demFoco} onBlur={_demBlur} style={_DEM_INP}/>
        </div>
        <div>
          <div style={_DEM_LBL}>Responsável</div>
          <div style={{display:"flex",alignItems:"center",minHeight:34}}>
            <_DemRespPicker mini valor={rascunho.resp} onChange={function(v){setRascunho(Object.assign({},rascunho,{resp:v}));}}/>
          </div>
        </div>
        <div>
          <div style={_DEM_LBL}>Prazo</div>
          <_DemDataInput valor={rascunho.prazo} onChange={function(v){setRascunho(Object.assign({},rascunho,{prazo:v}));}} placeholder="Prazo"/>
        </div>
        <div>
          <div style={_DEM_LBL}>Status</div>
          <select value={rascunho.status}
            onChange={function(e){setRascunho(Object.assign({},rascunho,{status:e.target.value}));}}
            onFocus={_demFoco} onBlur={_demBlur} style={Object.assign({},_DEM_INP,{cursor:"pointer"})}>
            {DEM_TSTATUS.map(function(s){return <option key={s.id} value={s.id}>{s.label}</option>;})}
          </select>
        </div>
        <div style={{display:"flex",gap:6}}>
          <button type="button" onClick={_addTarefa}
            style={{background:"linear-gradient(135deg,#a855f7,#7c3aed)",color:"#fff",border:"none",borderRadius:9,padding:"9px 15px",
              fontSize:12,fontWeight:800,cursor:"pointer",fontFamily:_DEM_FF,whiteSpace:"nowrap"}}>Adicionar</button>
          <button type="button" onClick={function(){setNovaAberta(false);}}
            style={{background:"#fff",color:"#64748b",border:"1px solid #e2e8f0",borderRadius:9,padding:"9px 12px",
              fontSize:12,fontWeight:700,cursor:"pointer",fontFamily:_DEM_FF}}>Cancelar</button>
        </div>
      </div>}

      {/* Lista */}
      {tarefas.length===0
        ? <div style={{background:"#fff",border:"1px dashed #e2e8f0",borderRadius:11,padding:"26px 18px",textAlign:"center",
            color:"#94a3b8",fontSize:12.5}}>
            Nenhuma etapa ainda.{canEdit?" Quebre a demanda em tarefas pra acompanhar o progresso.":""}
          </div>
        : <div style={{display:"flex",flexDirection:"column",gap:6}}>
            {tarefas.map(function(t){
              return <_DemTarefaLinha key={t.id} t={t} cat={cat} canEdit={canEdit} isMob={isMob}
                emEdicao={editId===t.id}
                setEmEdicao={function(v){setEditId(v?t.id:null);}}
                onPatch={function(p){_patchTarefa(t.id,p);}}
                onDel={function(){_delTarefa(t);}}
                proxima={_proxima&&_proxima.id===t.id}
                dragId={dragId} overId={overId}
                onDragStart={function(){setDragId(t.id);}}
                onDragOver={function(){ setOverId(function(p){return p===t.id?p:t.id;}); }}
                onDrop={function(){ _mover(dragId,t.id); setDragId(null); setOverId(null); }}
                onDragEnd={function(){ setDragId(null); setOverId(null); }}/>;
            })}
          </div>
      }
    </div>

    {/* ── Acoes da demanda ── */}
    {canEdit && <div style={{display:"flex",justifyContent:"flex-end",alignItems:"center",gap:7,paddingTop:4,flexWrap:"wrap"}}>
      {onPortal && !_demDoPortal(d) && <button type="button" onClick={function(){onPortal(d);}}
        title={d.portal_visivel?"O cliente está vendo essa demanda no portal — clique pra tirar de lá":"Libera essa demanda pro cliente acompanhar no portal"}
        style={{background:d.portal_visivel?"#f0fdfa":"#fff",border:"1px solid "+(d.portal_visivel?"#5eead4":"#e2e8f0"),borderRadius:9,
          padding:"8px 14px",color:d.portal_visivel?"#0d9488":"#475569",fontSize:12,fontWeight:700,cursor:"pointer",
          fontFamily:_DEM_FF,display:"inline-flex",alignItems:"center",gap:6,marginRight:"auto"}}>
        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>
        {d.portal_visivel?"No portal do cliente · Remover":"Enviar pro portal do cliente"}
      </button>}
      {onPortal && _demDoPortal(d) && <span title="Veio pelo portal — sincronizada automaticamente lá"
        style={{color:"#2563eb",fontSize:11,fontWeight:700,display:"inline-flex",alignItems:"center",gap:5,marginRight:"auto"}}>
        <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"/><line x1="2" y1="12" x2="22" y2="12"/><path d="M12 2a15.3 15.3 0 014 10 15.3 15.3 0 01-4 10 15.3 15.3 0 01-4-10 15.3 15.3 0 014-10z"/></svg>
        Veio pelo portal · sempre sincronizada
      </span>}
      {!onPatchDemanda&&<button type="button" onClick={onEditar}
        style={{background:"#fff",border:"1px solid #e2e8f0",borderRadius:9,padding:"8px 14px",color:"#475569",
          fontSize:12,fontWeight:700,cursor:"pointer",fontFamily:_DEM_FF,display:"inline-flex",alignItems:"center",gap:6}}
        onMouseEnter={function(e){e.currentTarget.style.borderColor=cat.cor+"66";e.currentTarget.style.color=cat.cor;}}
        onMouseLeave={function(e){e.currentTarget.style.borderColor="#e2e8f0";e.currentTarget.style.color="#475569";}}>
        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><path d="M11 4H4a2 2 0 00-2 2v14a2 2 0 002 2h14a2 2 0 002-2v-7"/><path d="M18.5 2.5a2.12 2.12 0 013 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
        Editar demanda
      </button>}
      <button type="button" onClick={onExcluir}
        style={{background:"#fff",border:"1px solid #fecaca",borderRadius:9,padding:"8px 12px",color:"#dc2626",
          fontSize:12,fontWeight:700,cursor:"pointer",fontFamily:_DEM_FF,display:"inline-flex",alignItems:"center",gap:6}}
        onMouseEnter={function(e){e.currentTarget.style.background="#fef2f2";}}
        onMouseLeave={function(e){e.currentTarget.style.background="#fff";}}>
        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-2 14a2 2 0 01-2 2H9a2 2 0 01-2-2L5 6"/><path d="M10 11v6M14 11v6"/></svg>
        Excluir
      </button>
    </div>}
  </div>;
}

/* ═══ LINHA DA TAREFA ═══ */
function _DemTarefaLinha({t, cat, canEdit, isMob, emEdicao, setEmEdicao, onPatch, onDel, proxima,
                          dragId, overId, onDragStart, onDragOver, onDrop, onDragEnd}){
  const [podeArrastar,setPodeArrastar]=useState(false);
  const [notaAberta,setNotaAberta]=useState(false);
  const st=_demTSt(t.status);
  const resp=_demMembro(t.resp);
  const _feita=t.status==="concluida";
  const _prazo=_demPrazoTom(t.prazo,_feita);
  const _arrastando=dragId===t.id;
  const _alvo=overId===t.id && dragId && dragId!==t.id;

  // Um clique no circulo alterna concluida <-> a fazer
  const _toggle=function(e){
    e.stopPropagation();
    if(!canEdit) return;
    onPatch({status:_feita?"afazer":"concluida"});
  };

  return <div
    draggable={podeArrastar}
    onDragStart={function(e){ onDragStart(); try{e.dataTransfer.effectAllowed="move";}catch(_){}}}
    onDragOver={function(e){ e.preventDefault(); try{e.dataTransfer.dropEffect="move";}catch(_){} onDragOver(); }}
    onDrop={function(e){ e.preventDefault(); e.stopPropagation(); onDrop(); }}
    onDragEnd={function(){ setPodeArrastar(false); onDragEnd(); }}
    style={{background:"#fff",border:"1px solid "+(_alvo?cat.cor:(proxima&&!_feita?cat.cor+"3d":"#eef0f3")),
      borderRadius:10,padding:isMob?"10px 12px":"9px 13px",display:"flex",alignItems:isMob?"flex-start":"center",
      gap:11,opacity:_arrastando?.4:1,flexWrap:"wrap",flexDirection:isMob?"column":"row",
      boxShadow:_alvo?("0 0 0 3px "+cat.cor+"26"):"none",transition:"border-color .12s, opacity .12s"}}>

    <div style={{display:"flex",alignItems:"center",gap:10,flex:1,minWidth:0,width:isMob?"100%":"auto"}}>
      {/* Handle */}
      {canEdit && <span title="Arraste pra reordenar"
        onMouseDown={function(){setPodeArrastar(true);}}
        onMouseUp={function(){setPodeArrastar(false);}}
        style={{cursor:"grab",color:"#cbd5e1",display:"inline-flex",flexShrink:0}}>
        <svg width="11" height="11" viewBox="0 0 24 24" fill="currentColor" style={{pointerEvents:"none"}}>
          <circle cx="9" cy="6" r="1.6"/><circle cx="15" cy="6" r="1.6"/>
          <circle cx="9" cy="12" r="1.6"/><circle cx="15" cy="12" r="1.6"/>
          <circle cx="9" cy="18" r="1.6"/><circle cx="15" cy="18" r="1.6"/>
        </svg>
      </span>}

      {/* Circulo de conclusao */}
      <button type="button" onClick={_toggle} disabled={!canEdit}
        title={_feita?"Marcar como a fazer":"Marcar como concluída"}
        style={{width:20,height:20,borderRadius:"50%",flexShrink:0,padding:0,
          border:"2px solid "+(_feita?"#16a34a":"#cbd5e1"),background:_feita?"#16a34a":"#fff",
          cursor:canEdit?"pointer":"default",display:"inline-flex",alignItems:"center",justifyContent:"center",transition:"all .12s"}}>
        {_feita && <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="3.5" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12"/></svg>}
      </button>

      {/* Nome */}
      {emEdicao && canEdit
        ? <input autoFocus defaultValue={t.nome}
            onBlur={function(e){ const v=pxDemTexto(e.target.value); if(v&&v!==t.nome) onPatch({nome:v}); setEmEdicao(false); }}
            onKeyDown={function(e){ if(e.key==="Enter") e.currentTarget.blur(); if(e.key==="Escape") setEmEdicao(false); }}
            style={Object.assign({},_DEM_INP,{padding:"5px 9px",fontSize:12.5})}/>
        : <span onClick={function(){ if(canEdit) setEmEdicao(true); }}
            title={canEdit?"Clique pra renomear":""}
            style={{flex:1,minWidth:0,color:_feita?"#94a3b8":"#0f172a",fontSize:12.5,fontWeight:700,lineHeight:1.35,
              textDecoration:_feita?"line-through":"none",cursor:canEdit?"text":"default",
              overflow:"hidden",textOverflow:"ellipsis"}}>
            {t.nome}
            {proxima&&!_feita&&<span style={{background:cat.cor+"14",color:cat.cor,fontSize:9,fontWeight:800,
              padding:"1px 6px",borderRadius:99,marginLeft:7,letterSpacing:.3,textTransform:"uppercase"}}>agora</span>}
          </span>}
      {canEdit && <button type="button" title={(t.obs&&String(t.obs).trim())?"Editar explicação da etapa":"Explicar o que essa etapa representa"}
        onClick={function(e){e.stopPropagation();setNotaAberta(function(v){return !v;});}}
        style={{background:notaAberta?cat.cor+"18":"transparent",border:"none",borderRadius:6,padding:"3px",cursor:"pointer",flexShrink:0,color:(t.obs&&String(t.obs).trim())?cat.cor:"#cbd5e1",display:"inline-flex",alignItems:"center"}}
        onMouseEnter={function(e){if(!notaAberta)e.currentTarget.style.color=cat.cor;}}
        onMouseLeave={function(e){if(!notaAberta)e.currentTarget.style.color=(t.obs&&String(t.obs).trim())?cat.cor:"#cbd5e1";}}>
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg>
      </button>}
    </div>

    {/* Responsavel · prazo · status · excluir */}
    <div style={{display:"flex",alignItems:"center",gap:9,flexShrink:0,flexWrap:"wrap",
      width:isMob?"100%":"auto",paddingLeft:isMob?31:0}}>
      {canEdit
        ? <_DemRespPicker mini valor={t.resp} onChange={function(v){onPatch({resp:v});}}/>
        : (resp
            ? <span style={{display:"inline-flex",alignItems:"center",gap:5}}>
                <UserAvatar user={resp} size={20} border={false}/>
                <span style={{color:"#475569",fontSize:11.5,fontWeight:700}}>{String(resp.name||"").split(" ")[0]}</span>
              </span>
            : <span style={{color:"#cbd5e1",fontSize:11,fontStyle:"italic"}}>—</span>)}

      {canEdit
        ? <_DemDataInput compacto valor={t.prazo||""} onChange={function(v){onPatch({prazo:v});}} placeholder="Prazo"/>
        : (t.prazo && <span style={{color:_prazo?_prazo.cor:"#64748b",fontSize:11,fontWeight:700,fontFeatureSettings:"'tnum'"}}>{_demBRCurto(t.prazo)}</span>)}

      {canEdit
        ? <select value={t.status} onChange={function(e){onPatch({status:e.target.value});}}
            style={{background:st.bg,color:st.cor,border:"1px solid "+st.cor+"2e",borderRadius:99,padding:"4px 9px",
              fontSize:10.5,fontWeight:800,outline:"none",fontFamily:_DEM_FF,cursor:"pointer",appearance:"none",textAlign:"center"}}>
            {DEM_TSTATUS.map(function(s){return <option key={s.id} value={s.id}>{s.label}</option>;})}
          </select>
        : <_DemChip def={st} size="sm"/>}

      {/* Quem concluiu + quando — carimbado no clique do check */}
      {_feita && t.done_at && (function(){
        const _quem=_demMembro(t.done_by);
        const _tit=(_quem?("Concluída por "+_quem.name):"Concluída")+" em "+_demQuando(t.done_at);
        return <span title={_tit}
          style={{display:"inline-flex",alignItems:"center",gap:5,background:"#f0fdf4",border:"1px solid #bbf7d0",borderRadius:99,padding:"2px 8px 2px 3px",flexShrink:0}}>
          {_quem
            ? <UserAvatar user={_quem} size={17} border={false}/>
            : <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="#16a34a" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12"/></svg>}
          <span style={{color:"#15803d",fontSize:9.5,fontWeight:800,fontFeatureSettings:"'tnum'",whiteSpace:"nowrap"}}>{_demQuando(t.done_at)}</span>
        </span>;
      })()}

      {canEdit && <button type="button" onClick={onDel} title="Excluir tarefa"
        style={{background:"transparent",border:"none",padding:4,borderRadius:6,color:"#cbd5e1",cursor:"pointer",display:"inline-flex",flexShrink:0}}
        onMouseEnter={function(e){e.currentTarget.style.color="#dc2626";e.currentTarget.style.background="#fef2f2";}}
        onMouseLeave={function(e){e.currentTarget.style.color="#cbd5e1";e.currentTarget.style.background="transparent";}}>
        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-2 14a2 2 0 01-2 2H9a2 2 0 01-2-2L5 6"/></svg>
      </button>}
    </div>

    {/* Explicação da etapa (o que ela representa) — recolhida por padrão pra não poluir */}
    {(notaAberta || (t.obs && String(t.obs).trim())) && <div style={{width:"100%",paddingLeft:isMob?0:41,marginTop:2}}>
      {canEdit && notaAberta
        ? <textarea autoFocus defaultValue={t.obs||""} placeholder="Explique o que essa etapa representa / o que precisa acontecer pra concluir"
            onClick={function(e){e.stopPropagation();}}
            onBlur={function(e){var v=e.target.value;if((v||"")!==(t.obs||""))onPatch({obs:v});setNotaAberta(false);}}
            onKeyDown={function(e){if(e.key==="Escape")setNotaAberta(false);}}
            style={Object.assign({},_DEM_INP,{minHeight:54,resize:"vertical",fontSize:12,fontWeight:500,lineHeight:1.5,color:"#475569"})}/>
        : ((t.obs && String(t.obs).trim())
            ? <div onClick={function(){if(canEdit)setNotaAberta(true);}} title={canEdit?"Clique pra editar":""}
                style={{background:"#f8fafc",border:"1px solid #eef0f3",borderRadius:9,padding:"8px 11px",fontSize:11.5,color:"#64748b",lineHeight:1.5,whiteSpace:"pre-wrap",cursor:canEdit?"text":"default",display:"flex",gap:7,alignItems:"flex-start"}}>
                <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="#94a3b8" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" style={{flexShrink:0,marginTop:1}}><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg>
                <span>{t.obs}</span>
              </div>
            : null)}
    </div>}
  </div>;
}

/* ═══ SELECT DE RESPONSAVEL — usa o TEAM que ja existe ═══ */
/* ═══ LIXEIRA (30 dias) — soft delete em client_demandas.deleted_at ═══ */
const _DEM_LIXEIRA_DIAS=30;
function _demDiasRestantes(deletedAt){
  try{
    const _fim=new Date(deletedAt).getTime()+_DEM_LIXEIRA_DIAS*86400000;
    return Math.max(0, Math.ceil((_fim-Date.now())/86400000));
  }catch(_){ return _DEM_LIXEIRA_DIAS; }
}
// Purga o que passou de 30 dias — roda no máximo 1x por hora por sessão
function _demPurgarLixeira(sb){
  try{
    const _agora=Date.now();
    if(window.__pxDemPurgaTs && (_agora-window.__pxDemPurgaTs)<3600000) return;
    window.__pxDemPurgaTs=_agora;
    const _corte=new Date(_agora-_DEM_LIXEIRA_DIAS*86400000).toISOString();
    sb.from("client_demandas").delete().lt("deleted_at",_corte).then(function(){}).catch(function(){});
  }catch(_){}
}
/* Menu de contexto (botão direito no card) */
function _DemCtxMenu({ctx, onAbrir, onExcluir, onFechar}){
  if(!ctx) return null;
  const _it={display:"flex",alignItems:"center",gap:9,padding:"9px 14px",fontSize:12.5,fontWeight:600,
    cursor:"pointer",color:"#334155",fontFamily:_DEM_FF,whiteSpace:"nowrap"};
  return <div onMouseDown={onFechar} onContextMenu={function(e){e.preventDefault();onFechar();}}
    style={{position:"fixed",inset:0,zIndex:440}}>
    <div onMouseDown={function(e){e.stopPropagation();}}
      style={{position:"fixed",top:Math.min(ctx.y,(typeof window!=="undefined"?window.innerHeight:800)-120),
        left:Math.min(ctx.x,(typeof window!=="undefined"?window.innerWidth:1200)-230),
        background:"#fff",border:"1px solid #e2e8f0",borderRadius:12,boxShadow:"0 18px 46px rgba(15,23,42,.20)",
        padding:5,minWidth:210,overflow:"hidden"}}>
      <div style={_it}
        onClick={function(){ onFechar(); onAbrir(ctx.d); }}
        onMouseEnter={function(e){e.currentTarget.style.background="#f8fafc";}}
        onMouseLeave={function(e){e.currentTarget.style.background="transparent";}}>
        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="#64748b" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><polyline points="15 3 21 3 21 9"/><polyline points="9 21 3 21 3 15"/><line x1="21" y1="3" x2="14" y2="10"/><line x1="3" y1="21" x2="10" y2="14"/></svg>
        Abrir demanda
      </div>
      <div style={{height:1,background:"#f1f5f9",margin:"3px 6px"}}/>
      <div style={Object.assign({},_it,{color:"#dc2626"})}
        onClick={function(){ onFechar(); onExcluir(ctx.d); }}
        onMouseEnter={function(e){e.currentTarget.style.background="#fef2f2";}}
        onMouseLeave={function(e){e.currentTarget.style.background="transparent";}}>
        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-2 14a2 2 0 01-2 2H9a2 2 0 01-2-2L5 6"/><path d="M10 11v6M14 11v6"/></svg>
        Excluir · Lixeira (30 dias)
      </div>
    </div>
  </div>;
}
/* Lixeira — bloco recolhível no rodapé */
function _DemLixeira({lista, mostrarCliente, onRestaurar, onExcluirDef}){
  const [aberto,setAberto]=useState(false);
  if(!lista.length) return null;
  return <div style={{background:"#fff",border:"1px solid #eef0f3",borderRadius:14,overflow:"hidden"}}>
    <div onClick={function(){setAberto(!aberto);}}
      style={{padding:"12px 17px",display:"flex",alignItems:"center",gap:11,cursor:"pointer",
        background:aberto?"#fafbfc":"#fff",transition:"background .12s"}}>
      <div style={{width:28,height:28,borderRadius:9,background:"#fef2f2",border:"1px solid #fecaca",
        display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="#dc2626" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-2 14a2 2 0 01-2 2H9a2 2 0 01-2-2L5 6"/><path d="M10 11v6M14 11v6"/></svg>
      </div>
      <div style={{flex:1,minWidth:0}}>
        <div style={{color:"#0f172a",fontWeight:800,fontSize:12.5,letterSpacing:-.15}}>Lixeira</div>
        <div style={{color:"#94a3b8",fontSize:10.5,marginTop:1,fontWeight:600}}>Itens somem de vez depois de {_DEM_LIXEIRA_DIAS} dias</div>
      </div>
      <span style={{background:"#fef2f2",color:"#dc2626",border:"1px solid #fecaca",fontSize:10.5,fontWeight:800,
        borderRadius:99,padding:"1px 9px",fontFeatureSettings:"'tnum'",flexShrink:0}}>{lista.length}</span>
      <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="#94a3b8" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round"
        style={{flexShrink:0,transition:"transform .18s",transform:aberto?"rotate(180deg)":"rotate(0deg)"}}>
        <polyline points="6 9 12 15 18 9"/>
      </svg>
    </div>
    {aberto&&<div style={{borderTop:"1px solid #f1f5f9"}}>
      {lista.map(function(d,i){
        const _chip=mostrarCliente?_demCliChip(d):null;
        const _rest=_demDiasRestantes(d.deleted_at);
        return <div key={d.id} style={{display:"flex",alignItems:"center",gap:10,padding:"10px 17px",
          borderTop:i>0?"1px solid #f8fafc":"none",flexWrap:"wrap"}}>
          {_chip&&_chip.logo&&<img src={_chip.logo} alt="" title={_chip.titulo} style={{height:13,maxWidth:50,objectFit:"contain",flexShrink:0}}/>}
          <div style={{flex:1,minWidth:150}}>
            <div style={{color:"#64748b",fontSize:12,fontWeight:500,textDecoration:"line-through"}}>{d.titulo}</div>
            <div style={{color:"#b6bec9",fontSize:10,fontWeight:600,marginTop:1,fontFeatureSettings:"'tnum'"}}>
              some em {_rest} dia{_rest===1?"":"s"}
            </div>
          </div>
          <button type="button" onClick={function(){onRestaurar(d);}}
            style={{background:"#fff",color:"#0d9488",border:"1px solid #99f6e4",borderRadius:8,padding:"5px 11px",
              fontSize:10.5,fontWeight:800,cursor:"pointer",fontFamily:_DEM_FF,flexShrink:0}}>Restaurar</button>
          <button type="button" onClick={function(){onExcluirDef(d);}}
            style={{background:"#fff",color:"#dc2626",border:"1px solid #fecaca",borderRadius:8,padding:"5px 11px",
              fontSize:10.5,fontWeight:800,cursor:"pointer",fontFamily:_DEM_FF,flexShrink:0}}>Excluir agora</button>
        </div>;
      })}
    </div>}
  </div>;
}

/* ═══ CALENDÁRIO MODERNO — popover próprio, nada do nativo do navegador ═══ */
const _DEM_MESES=["Janeiro","Fevereiro","Março","Abril","Maio","Junho","Julho","Agosto","Setembro","Outubro","Novembro","Dezembro"];
function _DemDataInput({valor, onChange, placeholder, compacto}){
  const [aberto,setAberto]=useState(false);
  const [pos,setPos]=useState({top:100,left:100});
  const _ref=useRef(null);
  const _abrir=function(e){
    if(aberto){ setAberto(false); return; }
    try{
      const r=e.currentTarget.getBoundingClientRect();
      const vw=window.innerWidth, vh=window.innerHeight, W=302, H=332;
      let left=compacto?(r.right-W):r.left;
      left=Math.max(8, Math.min(left, vw-W-8));
      let top=r.bottom+6;
      if(top+H>vh-8) top=Math.max(8, r.top-H-6);
      setPos({top:top,left:left});
    }catch(_){ setPos({top:100,left:100}); }
    setAberto(true);
  };
  const _hoje=new Date();
  const _selD=valor?new Date(String(valor).slice(0,10)+"T12:00:00"):null;
  const [mes,setMes]=useState(function(){ const b=_selD||_hoje; return new Date(b.getFullYear(),b.getMonth(),1); });
  useEffect(function(){
    if(!aberto) return undefined;
    const b=_selD||_hoje; setMes(new Date(b.getFullYear(),b.getMonth(),1));
    const h=function(e){ if(_ref.current&&!_ref.current.contains(e.target)) setAberto(false); };
    const k=function(e){ if(e.key==="Escape") setAberto(false); };
    document.addEventListener("mousedown",h); document.addEventListener("keydown",k);
    return function(){ document.removeEventListener("mousedown",h); document.removeEventListener("keydown",k); };
  },[aberto]);
  const _ymd=function(d){ return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0"); };
  const _mesmoDia=function(a,b){ return a&&b&&a.getFullYear()===b.getFullYear()&&a.getMonth()===b.getMonth()&&a.getDate()===b.getDate(); };
  const _dias=(function(){
    const out=[]; const ini=new Date(mes.getFullYear(),mes.getMonth(),1);
    for(let i=0;i<ini.getDay();i++) out.push(null);
    const n=new Date(mes.getFullYear(),mes.getMonth()+1,0).getDate();
    for(let d=1;d<=n;d++) out.push(new Date(mes.getFullYear(),mes.getMonth(),d));
    return out;
  })();
  const _navBtn={background:"transparent",border:"none",borderRadius:8,width:26,height:26,cursor:"pointer",
    color:"#64748b",display:"inline-flex",alignItems:"center",justifyContent:"center",fontFamily:_DEM_FF};
  return <div ref={_ref} style={{position:"relative",width:compacto?"auto":"100%"}}>
    {/* Campo — o retângulo INTEIRO abre o calendário */}
    <button type="button" onClick={_abrir}
      style={compacto
        ? {background:"#fff",border:"1px solid "+(aberto?"#a78bfa":"#e2e8f0"),borderRadius:8,padding:"4px 9px",
           fontSize:11,fontWeight:700,color:valor?"#475569":"#94a3b8",cursor:"pointer",fontFamily:_DEM_FF,
           display:"inline-flex",alignItems:"center",gap:5,fontFeatureSettings:"'tnum'",whiteSpace:"nowrap"}
        : Object.assign({},_DEM_INP,{cursor:"pointer",display:"flex",alignItems:"center",gap:8,textAlign:"left",
           color:valor?"#0f172a":"#94a3b8",fontWeight:valor?600:500,
           borderColor:aberto?"#a78bfa":"#e2e8f0",boxShadow:aberto?"0 0 0 3px rgba(167,139,250,.18)":"none"})}>
      <svg width={compacto?10:13} height={compacto?10:13} viewBox="0 0 24 24" fill="none" stroke={valor?"#7c3aed":"#94a3b8"} strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" style={{flexShrink:0}}><rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>
      {valor?_demBR(valor):(placeholder||"Escolher data")}
    </button>
    {/* Popover */}
    {aberto&&<div style={{position:"fixed",top:pos.top,left:pos.left,
      zIndex:500,width:302,background:"#fff",
      border:"1px solid #e8ebf0",borderRadius:14,boxShadow:"0 18px 46px rgba(15,23,42,.16)",padding:"11px 13px 9px",
      fontFamily:_DEM_FF}}>
      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:7}}>
        <button type="button" style={_navBtn} onClick={function(){setMes(new Date(mes.getFullYear(),mes.getMonth()-1,1));}}
          onMouseEnter={function(e){e.currentTarget.style.background="#f5f3ff";e.currentTarget.style.color="#7c3aed";}}
          onMouseLeave={function(e){e.currentTarget.style.background="transparent";e.currentTarget.style.color="#64748b";}}>
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.8" strokeLinecap="round" strokeLinejoin="round"><polyline points="15 18 9 12 15 6"/></svg>
        </button>
        <span style={{color:"#0f172a",fontSize:12.5,fontWeight:800,letterSpacing:-.15}}>{_DEM_MESES[mes.getMonth()]} {mes.getFullYear()}</span>
        <button type="button" style={_navBtn} onClick={function(){setMes(new Date(mes.getFullYear(),mes.getMonth()+1,1));}}
          onMouseEnter={function(e){e.currentTarget.style.background="#f5f3ff";e.currentTarget.style.color="#7c3aed";}}
          onMouseLeave={function(e){e.currentTarget.style.background="transparent";e.currentTarget.style.color="#64748b";}}>
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.8" strokeLinecap="round" strokeLinejoin="round"><polyline points="9 18 15 12 9 6"/></svg>
        </button>
      </div>
      <div style={{display:"grid",gridTemplateColumns:"repeat(7,1fr)",gap:3,marginBottom:2}}>
        {["D","S","T","Q","Q","S","S"].map(function(l,i){
          return <span key={i} style={{textAlign:"center",color:"#b6bec9",fontSize:9.5,fontWeight:800}}>{l}</span>;
        })}
      </div>
      <div style={{display:"grid",gridTemplateColumns:"repeat(7,1fr)",gap:3}}>
        {_dias.map(function(d,i){
          if(!d) return <span key={"v"+i}/>;
          const _sel=_mesmoDia(d,_selD), _tj=_mesmoDia(d,_hoje);
          return <button key={i} type="button"
            onClick={function(){ onChange(_ymd(d)); setAberto(false); }}
            style={{border:"none",borderRadius:8,height:26,cursor:"pointer",fontFamily:_DEM_FF,
              fontSize:11.5,fontWeight:_sel?800:600,fontFeatureSettings:"'tnum'",transition:"all .1s",
              background:_sel?"linear-gradient(135deg,#a855f7,#7c3aed)":"transparent",
              color:_sel?"#fff":(_tj?"#7c3aed":"#334155"),
              boxShadow:_sel?"0 4px 10px rgba(124,58,237,.30)":(_tj?"inset 0 0 0 1.5px #c4b5fd":"none")}}
            onMouseEnter={function(e){ if(!_sel) e.currentTarget.style.background="#f5f3ff"; }}
            onMouseLeave={function(e){ if(!_sel) e.currentTarget.style.background="transparent"; }}>
            {d.getDate()}
          </button>;
        })}
      </div>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginTop:7,paddingTop:7,borderTop:"1px solid #f4f6f8"}}>
        <button type="button" onClick={function(){ onChange(""); setAberto(false); }}
          style={{background:"transparent",border:"none",color:"#94a3b8",fontSize:11,fontWeight:700,cursor:"pointer",fontFamily:_DEM_FF,padding:"3px 4px"}}
          onMouseEnter={function(e){e.currentTarget.style.color="#dc2626";}}
          onMouseLeave={function(e){e.currentTarget.style.color="#94a3b8";}}>Limpar</button>
        <button type="button" onClick={function(){ onChange(_ymd(_hoje)); setAberto(false); }}
          style={{background:"#f5f3ff",border:"1px solid #ddd6fe",borderRadius:8,color:"#7c3aed",fontSize:11,fontWeight:800,cursor:"pointer",fontFamily:_DEM_FF,padding:"4px 12px"}}>Hoje</button>
      </div>
    </div>}
  </div>;
}

/* ═══ RESPONSÁVEL POR CARINHA — clica na foto, sem digitar nome ═══ */
function _DemRespPicker({valor, onChange, mini}){
  const _time=(typeof TEAM!=="undefined")?TEAM:[];
  const _m=_demMembro(valor);
  const [aberto,setAberto]=useState(false);
  const [pos,setPos]=useState({top:100,left:100});
  const _ref=useRef(null);
  const _abrirMini=function(e){
    if(aberto){ setAberto(false); return; }
    try{
      const r=e.currentTarget.getBoundingClientRect();
      const vw=window.innerWidth, vh=window.innerHeight, W=236, H=120;
      let left=Math.max(8, Math.min(r.right-W, vw-W-8));
      let top=r.bottom+6;
      if(top+H>vh-8) top=Math.max(8, r.top-H-6);
      setPos({top:top,left:left});
    }catch(_){ setPos({top:100,left:100}); }
    setAberto(true);
  };
  useEffect(function(){
    if(!aberto) return undefined;
    const h=function(e){ if(_ref.current&&!_ref.current.contains(e.target)) setAberto(false); };
    document.addEventListener("click",h);
    return function(){ document.removeEventListener("click",h); };
  },[aberto]);
  const _rosto=function(u,size,sel,dim){
    const _op=(dim&&valor&&!sel)?.55:1;
    return <button key={u?u.id:"none"} type="button" title={u?u.name:"Sem responsável"}
      onClick={function(e){ e.stopPropagation(); e.preventDefault(); onChange(u?u.id:""); setAberto(false); }}
      style={{border:"none",background:"transparent",padding:2,borderRadius:"50%",cursor:"pointer",lineHeight:0,
        boxShadow:sel?"0 0 0 2.5px #7c3aed":"0 0 0 1px #e2e8f0",opacity:_op,transition:"all .12s",flexShrink:0}}
      onMouseEnter={function(e){e.currentTarget.style.opacity="1";e.currentTarget.style.boxShadow=sel?"0 0 0 2.5px #7c3aed":"0 0 0 2px #c4b5fd";}}
      onMouseLeave={function(e){e.currentTarget.style.opacity=String(_op);e.currentTarget.style.boxShadow=sel?"0 0 0 2.5px #7c3aed":"0 0 0 1px #e2e8f0";}}>
      {u
        ? <UserAvatar user={u} size={size} border={false}/>
        : <span style={{width:size,height:size,borderRadius:"50%",background:"#f8fafc",border:"1.5px dashed #cbd5e1",
            display:"inline-flex",alignItems:"center",justifyContent:"center",color:"#94a3b8",fontSize:size*.44,fontWeight:700,boxSizing:"border-box"}}>—</span>}
    </button>;
  };
  if(!mini){
    // Fileira de carinhas direto no formulário
    return <div style={{display:"flex",alignItems:"center",gap:6,flexWrap:"wrap",minHeight:38}}>
      {_rosto(null,30,!valor,true)}
      {_time.map(function(u){ return _rosto(u,30,valor===u.id,true); })}
      {_m&&<span style={{color:"#475569",fontSize:11.5,fontWeight:700,marginLeft:3}}>{String(_m.name||"").split(" ")[0]}</span>}
    </div>;
  }
  // mini: avatar atual + popover de carinhas
  return <div ref={_ref} style={{position:"relative",display:"inline-flex",flexShrink:0}}>
    <button type="button" onClick={_abrirMini} title={_m?_m.name:"Definir responsável"}
      style={{border:"none",background:"transparent",padding:2,borderRadius:"50%",cursor:"pointer",lineHeight:0,
        boxShadow:_m?"0 0 0 1.5px #e2e8f0":"none"}}>
      {_m
        ? <UserAvatar user={_m} size={26} border={false}/>
        : <span style={{width:26,height:26,borderRadius:"50%",background:"#f8fafc",border:"1.5px dashed #cbd5e1",
            display:"inline-flex",alignItems:"center",justifyContent:"center",boxSizing:"border-box"}}>
            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="#94a3b8" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><path d="M20 21v-2a4 4 0 00-4-4H8a4 4 0 00-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>
          </span>}
    </button>
    {aberto&&<div style={{position:"fixed",top:pos.top,left:pos.left,zIndex:500,background:"#fff",
      border:"1px solid #dfe3ea",borderRadius:12,boxShadow:"0 16px 44px rgba(15,23,42,.22)",padding:9,
      display:"flex",gap:6,flexWrap:"wrap",width:236}}>
      {_rosto(null,30,!valor,false)}
      {_time.map(function(u){ return _rosto(u,30,valor===u.id,false); })}
    </div>}
  </div>;
}

function _DemSelectResp({valor, onChange, compacto}){
  const _time=(typeof TEAM!=="undefined")?TEAM:[];
  const _m=_demMembro(valor);
  return <div style={{position:"relative",display:"inline-flex",alignItems:"center",flexShrink:0}}>
    {compacto && _m && <span style={{position:"absolute",left:5,pointerEvents:"none",display:"inline-flex"}}>
      <UserAvatar user={_m} size={18} border={false}/>
    </span>}
    <select value={valor||""} onChange={function(e){onChange(e.target.value);}}
      onFocus={_demFoco} onBlur={_demBlur}
      style={compacto
        ? {background:"#fff",border:"1px solid #e2e8f0",borderRadius:99,padding:_m?"4px 8px 4px 27px":"4px 10px",
           fontSize:11,fontWeight:700,color:_m?"#475569":"#94a3b8",outline:"none",fontFamily:_DEM_FF,cursor:"pointer",
           appearance:"none",maxWidth:132}
        : Object.assign({},_DEM_INP,{cursor:"pointer"})}>
      <option value="">{compacto?"—":"Sem responsável"}</option>
      {_time.map(function(u){
        return <option key={u.id} value={u.id}>{String(u.name||"").split(" ")[0]}</option>;
      })}
    </select>
  </div>;
}

/* ═══════════════════════════════════════════════════════════════════════
   MODAL — nova / editar demanda
═══════════════════════════════════════════════════════════════════════ */
/* Seletor de horário próprio (nada de dropdown nativo feio) — mesmo estilo do _DemDataInput:
   popover fixed com clamp/flip, pills de hora (0-23) e minutos (passo 5). Valor "HH:MM". */
function _DemHoraInput({valor, onChange, placeholder}){
  const [aberto,setAberto]=useState(false);
  const [pos,setPos]=useState({top:100,left:100});
  const _ref=useRef(null);
  const W=252, H=318;
  const _abrir=function(e){
    if(aberto){ setAberto(false); return; }
    try{
      const r=e.currentTarget.getBoundingClientRect();
      const vw=window.innerWidth, vh=window.innerHeight;
      let left=Math.max(8, Math.min(r.left, vw-W-8));
      let top=r.bottom+6;
      if(top+H>vh-8) top=Math.max(8, r.top-H-6);
      setPos({top:top,left:left});
    }catch(_){ setPos({top:100,left:100}); }
    setAberto(true);
  };
  useEffect(function(){
    if(!aberto) return undefined;
    const h=function(e){ if(_ref.current&&!_ref.current.contains(e.target)) setAberto(false); };
    const k=function(e){ if(e.key==="Escape") setAberto(false); };
    document.addEventListener("mousedown",h); document.addEventListener("keydown",k);
    return function(){ document.removeEventListener("mousedown",h); document.removeEventListener("keydown",k); };
  },[aberto]);
  const _v=String(valor||"");
  const _hSel=_v?parseInt(_v.slice(0,2),10):null;
  const _mSel=_v?parseInt(_v.slice(3,5),10):null;
  const _pad=function(n){ return String(n).padStart(2,"0"); };
  const _setH=function(h){ onChange(_pad(h)+":"+(_mSel!=null?_pad(_mSel):"00")); };
  const _setM=function(m){ onChange((_hSel!=null?_pad(_hSel):"09")+":"+_pad(m)); setAberto(false); };
  const _pill=function(on){
    return {border:"none",borderRadius:8,padding:0,height:26,fontSize:11.5,cursor:"pointer",fontFamily:_DEM_FF,
      fontFeatureSettings:"'tnum'",fontWeight:on?800:600,transition:"all .1s",
      background:on?"linear-gradient(135deg,#a855f7,#7c3aed)":"#f8fafc",
      color:on?"#fff":"#475569",boxShadow:on?"0 3px 8px rgba(124,58,237,.35)":"none"};
  };
  const _lbl={color:"#94a3b8",fontSize:9.5,fontWeight:800,letterSpacing:.6,textTransform:"uppercase",margin:"2px 1px 5px"};
  return <div ref={_ref} style={{position:"relative",width:"100%"}}>
    <button type="button" onClick={_abrir}
      style={Object.assign({},_DEM_INP,{cursor:"pointer",display:"flex",alignItems:"center",gap:8,textAlign:"left",
        color:_v?"#0f172a":"#94a3b8",fontWeight:_v?600:500,fontFeatureSettings:"'tnum'",
        borderColor:aberto?"#a78bfa":"#e2e8f0",boxShadow:aberto?"0 0 0 3px rgba(167,139,250,.18)":"none"})}>
      <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke={_v?"#7c3aed":"#94a3b8"} strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" style={{flexShrink:0}}><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>
      {_v||placeholder||"—"}
    </button>
    {aberto&&<div style={{position:"fixed",top:pos.top,left:pos.left,zIndex:500,width:W,background:"#fff",
      border:"1px solid #e8ebf0",borderRadius:14,boxShadow:"0 18px 46px rgba(15,23,42,.16)",padding:"11px 13px 12px",
      fontFamily:_DEM_FF,boxSizing:"border-box"}}>
      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:6}}>
        <span style={{color:"#0f172a",fontSize:12,fontWeight:800,letterSpacing:-.2,display:"inline-flex",alignItems:"center",gap:6}}>
          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="#7c3aed" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>
          {_v||"Horário"}
        </span>
        {_v&&<button type="button" onClick={function(){onChange("");setAberto(false);}}
          style={{background:"none",border:"none",color:"#94a3b8",fontSize:10.5,fontWeight:700,cursor:"pointer",fontFamily:_DEM_FF,padding:"3px 5px",borderRadius:7}}
          onMouseEnter={function(e){e.currentTarget.style.color="#dc2626";}}
          onMouseLeave={function(e){e.currentTarget.style.color="#94a3b8";}}>Limpar</button>}
      </div>
      <div style={_lbl}>Hora</div>
      <div style={{display:"grid",gridTemplateColumns:"repeat(6,1fr)",gap:4}}>
        {Array.from({length:24},function(_,h){
          const on=_hSel===h;
          return <button key={h} type="button" onClick={function(){_setH(h);}} style={_pill(on)}
            onMouseEnter={function(e){if(!on)e.currentTarget.style.background="#f5f3ff";}}
            onMouseLeave={function(e){if(!on)e.currentTarget.style.background="#f8fafc";}}>{_pad(h)}</button>;
        })}
      </div>
      <div style={Object.assign({},_lbl,{marginTop:9})}>Minutos</div>
      <div style={{display:"grid",gridTemplateColumns:"repeat(6,1fr)",gap:4}}>
        {Array.from({length:12},function(_,i){
          const m=i*5, on=_mSel===m;
          return <button key={m} type="button" onClick={function(){_setM(m);}} style={_pill(on)}
            onMouseEnter={function(e){if(!on)e.currentTarget.style.background="#f5f3ff";}}
            onMouseLeave={function(e){if(!on)e.currentTarget.style.background="#f8fafc";}}>:{_pad(m)}</button>;
        })}
      </div>
    </div>}
  </div>;
}

/* Botão "Enviar pro Checkpoint" auto-suficiente — checa/insere/remove em client_milestones
   via metrics->>from_demanda. Aparece na ficha da demanda quando ela está concluída. */
function _DemCkBtn({d}){
  const sb=(typeof window!=="undefined")?window._sb:null;
  const [st,setSt]=useState("check"); // check | fora | dentro | busy
  useEffect(function(){
    let vivo=true;
    (async function(){
      try{
        if(!sb||!d||!d.id||!d.client_id){ if(vivo)setSt("fora"); return; }
        const r=await sb.from("client_milestones").select("id")
          .eq("client_id",d.client_id).eq("metrics->>from_demanda",String(d.id)).limit(1);
        if(!vivo) return;
        setSt(r&&r.data&&r.data.length?"dentro":"fora");
      }catch(_){ if(vivo)setSt("fora"); }
    })();
    return function(){vivo=false;};
  },[d&&d.id]);
  const _enviar=async function(){
    if(!sb||st==="busy") return;
    setSt("busy");
    try{
      const _quando=(typeof _demConcluidaEm==="function")?_demConcluidaEm(d):null;
      const _data=_quando?String(_quando).slice(0,10):new Date().toISOString().slice(0,10);
      const _met={from_demanda:d.id};
      if(d.cidade) _met.city=d.cidade;
      if(d.unidade&&d.unidade!=="grupo") _met.unit=d.unidade;
      const r=await sb.from("client_milestones").insert({
        client_id:d.client_id, date:_data, type:"entrega",
        title:d.titulo||"Entrega", description:d.descricao||null, metrics:_met,
        created_by:(typeof CURRENT_USER!=="undefined"&&CURRENT_USER)?CURRENT_USER.name:""
      });
      if(r&&r.error) throw r.error;
      setSt("dentro");
      if(typeof pixelsToast!=="undefined") pixelsToast.success("Enviada pros Checkpoints do cliente.");
    }catch(e){
      setSt("fora");
      if(typeof pixelsToast!=="undefined") pixelsToast.error("Erro enviando: "+((e&&e.message)||""),4500);
    }
  };
  const _desfazer=async function(){
    if(!sb||st==="busy") return;
    let ok=true;
    if(typeof pxExclusaoBloqueada==="function"&&pxExclusaoBloqueada(CURRENT_USER)){if(typeof pixelsToast!=="undefined")pixelsToast.warning("Você não tem permissão para remover.");return;}
    if(typeof pixelsConfirm==="function")
      ok=await pixelsConfirm({title:"Tirar dos Checkpoints?",message:'"'+(d.titulo||"")+'" sai dos Checkpoints do cliente.',danger:true});
    if(!ok) return;
    setSt("busy");
    try{
      const r=await sb.from("client_milestones").delete()
        .eq("client_id",d.client_id).eq("metrics->>from_demanda",String(d.id));
      if(r&&r.error) throw r.error;
      setSt("fora");
      if(typeof pixelsToast!=="undefined") pixelsToast.success("Removida dos Checkpoints.");
    }catch(e){
      setSt("dentro");
      if(typeof pixelsToast!=="undefined") pixelsToast.error("Erro removendo: "+((e&&e.message)||""),4500);
    }
  };
  if(st==="check") return null;
  const _dentro=st==="dentro";
  const _busy=st==="busy";
  return <button type="button" disabled={_busy} onClick={_dentro?_desfazer:_enviar}
    title={_dentro?"Está nos Checkpoints do cliente — clique pra desfazer":"Registra essa entrega nos Checkpoints do cliente (calendário e portal)"}
    style={_dentro
      ? {background:"#f0fdfa",color:"#0d9488",border:"1px solid #99f6e4",borderRadius:9,padding:"7px 13px",fontSize:11,fontWeight:800,whiteSpace:"nowrap",display:"inline-flex",alignItems:"center",gap:6,cursor:_busy?"wait":"pointer",fontFamily:_DEM_FF,opacity:_busy?.6:1}
      : {background:"#fff",color:"#0d9488",border:"1px solid #5eead4",borderRadius:9,padding:"7px 13px",fontSize:11,fontWeight:800,whiteSpace:"nowrap",display:"inline-flex",alignItems:"center",gap:6,cursor:_busy?"wait":"pointer",fontFamily:_DEM_FF,opacity:_busy?.6:1}}>
    {_dentro
      ? <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
      : <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round"><path d="M8.21 13.89 7 23l5-3 5 3-1.21-9.12"/><circle cx="12" cy="8" r="6"/></svg>}
    {_busy?"Aguarde…":(_dentro?"No Checkpoint · desfazer":"Enviar pro Checkpoint")}
  </button>;
}

function _DemandaModal({inicial, onSalvar, onFechar, isMob, clientes, cats, semCats, onPortal}){
  const [pv,setPv]=useState(!!(inicial&&inicial.portal_visivel));
  const _novo=!inicial || !inicial.id;
  // Categorias visíveis: `cats` restringe, `semCats` exclui (central esconde as de mídia)
  const _catsVisiveis=DEM_CATEGORIAS.filter(function(c){
    if(c.legado&&!(inicial&&inicial.categoria===c.id)) return false;
    if(Array.isArray(cats)&&cats.length) return cats.indexOf(c.id)>=0;
    if(Array.isArray(semCats)&&semCats.length) return semCats.indexOf(c.id)<0;
    return true;
  });
  const [f,setF]=useState(function(){
    const _base=Object.assign({
      titulo:"", categoria:(Array.isArray(cats)&&cats.length)?cats[0]:"outros", descricao:"", status:"nao_iniciada",
      prioridade:"normal", responsavel:"", data_inicio:_demHoje(), prazo:"", hora:"", cidade:"", resumo:"",
    }, inicial||{});
    // Editando demanda de unidade Bioter: o select de cliente usa "bioter::<unidade>"
    if(_base.client_id==="bioter"&&_base.unidade&&_base.unidade!=="grupo")
      _base.client_id="bioter::"+_base.unidade;
    return _base;
  });
  const set=function(k,v){ setF(function(p){return Object.assign({},p,{[k]:v});}); };
  const cat=_demCat(f.categoria);
  // Etapas dentro do modal — na criação E na edição (ficha única)
  const [etapas,setEtapas]=useState(function(){
    const _ts=(inicial&&Array.isArray(inicial.tarefas))?inicial.tarefas:[];
    return _ts.map(function(t){ return Object.assign({},t); });
  });
  const _checkEtapa=function(id){
    setEtapas(function(p){ return p.map(function(t){
      if(t.id!==id) return t;
      if(t.status==="concluida") return Object.assign({},t,{status:"afazer",done_at:"",done_by:""});
      return Object.assign({},t,{status:"concluida",done_at:new Date().toISOString(),
        done_by:(typeof CURRENT_USER!=="undefined"&&CURRENT_USER)?CURRENT_USER.id:""});
    }); });
  };
  const _addEtapa=function(){ setEtapas(function(p){ return p.concat([{id:_demNovoId(),nome:"",resp:"",prazo:"",status:"afazer",obs:"",done_at:"",done_by:""}]); }); };
  const _setEtapa=function(id,k,v){ setEtapas(function(p){ return p.map(function(t){ return t.id===id?Object.assign({},t,{[k]:v}):t; }); }); };
  const _delEtapa=function(id){ setEtapas(function(p){ return p.filter(function(t){ return t.id!==id; }); }); };
  const [notaForm,setNotaForm]=useState({}); // etapas do form com a caixa de explicação aberta

  if(typeof useEscToClose==="function") useEscToClose(true, onFechar);

  const _salvar=function(){
    if(!String(f.titulo||"").trim()){
      if(typeof pixelsToast!=="undefined") pixelsToast.warning("Dá um nome pra demanda.");
      return;
    }
    const _ts=etapas.filter(function(t){ return String(t.nome||"").trim(); })
      .map(function(t){ return Object.assign({},t,{nome:String(t.nome).trim()}); });
    onSalvar(Object.assign({},f,{tarefas:_ts}));
  };

  return <div onMouseDown={function(e){ if(e.target===e.currentTarget) onFechar(); }}
    style={{position:"fixed",inset:0,background:"rgba(15,23,42,.55)",backdropFilter:"blur(4px)",zIndex:500,
      display:"flex",alignItems:"center",justifyContent:"center",padding:16,fontFamily:_DEM_FF}}>
    <div onMouseDown={function(e){e.stopPropagation();}}
      style={{background:"#fff",borderRadius:18,width:"100%",maxWidth:620,maxHeight:"92vh",overflow:"auto",
        boxShadow:"0 24px 64px rgba(15,23,42,.28)"}}>

      {/* Header */}
      <div style={{background:"linear-gradient(135deg,#1e1b4b 0%,#4c1d95 52%,"+cat.cor+" 100%)",padding:"18px 22px",
        color:"#fff",display:"flex",justifyContent:"space-between",alignItems:"flex-start",gap:12,position:"relative",overflow:"hidden"}}>
        <div style={{position:"absolute",right:-40,top:-60,width:180,height:180,borderRadius:"50%",
          background:"radial-gradient(circle,rgba(255,255,255,.14),transparent 70%)",pointerEvents:"none"}}/>
        <div style={{display:"flex",alignItems:"center",gap:12,position:"relative",minWidth:0}}>
          <div style={{width:38,height:38,borderRadius:11,background:"rgba(255,255,255,.15)",
            border:"1px solid rgba(255,255,255,.24)",display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
            <Ico n={cat.ico} size={18} color="#fff"/>
          </div>
          <div style={{minWidth:0}}>
            <div style={{fontWeight:800,fontSize:16,letterSpacing:-.3}}>{_novo?"Nova demanda":"Editar demanda"}</div>
            <div style={{fontSize:11.5,opacity:.78,marginTop:2,fontWeight:500}}>Depois é só quebrar em tarefas — o progresso se calcula sozinho</div>
          </div>
        </div>
        <button onClick={onFechar} title="Fechar"
          style={{background:"rgba(255,255,255,.14)",border:"1px solid rgba(255,255,255,.2)",borderRadius:9,width:30,height:30,
            color:"#fff",cursor:"pointer",display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0,position:"relative"}}>
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
        </button>
      </div>

      <div style={{padding:"20px 22px 22px",display:"flex",flexDirection:"column",gap:13}}>
        {/* Cliente — so na central (na aba do cliente ele e implicito) */}
        {Array.isArray(clientes)&&clientes.length>0&&<div>
          <div style={_DEM_LBL}>Cliente</div>
          <select value={f.client_id||""} onChange={function(e){set("client_id",e.target.value);}}
            onFocus={_demFoco} onBlur={_demBlur} style={Object.assign({},_DEM_INP,{cursor:"pointer"})}>
            <option value="">Escolher cliente...</option>
            {clientes.map(function(c){return <option key={c.id} value={c.id}>{c.name}</option>;})}
          </select>
        </div>}
        <div>
          <div style={_DEM_LBL}>Nome da demanda</div>
          <input autoFocus value={f.titulo} placeholder="Ex: Novo site institucional"
            onChange={function(e){set("titulo",e.target.value);}}
            onFocus={_demFoco} onBlur={_demBlur} style={Object.assign({},_DEM_INP,{fontSize:14,fontWeight:700})}/>
        </div>

        <div>
          <div style={_DEM_LBL}>Categoria</div>
          <div style={{display:"flex",gap:5,flexWrap:"wrap"}}>
            {_catsVisiveis.map(function(c){
              const _on=f.categoria===c.id;
              return <button key={c.id} type="button" onClick={function(){set("categoria",c.id);}}
                style={{background:_on?c.cor:"#fff",color:_on?"#fff":"#64748b",border:"1px solid "+(_on?c.cor:"#e2e8f0"),
                  borderRadius:99,padding:"6px 12px",fontSize:11.5,fontWeight:_on?800:600,cursor:"pointer",
                  fontFamily:_DEM_FF,transition:"all .12s",display:"inline-flex",alignItems:"center",gap:5}}>
                <Ico n={c.ico} size={12} color={_on?"#fff":c.cor}/>{c.label}
              </button>;
            })}
          </div>
        </div>

        <div>
          <div style={_DEM_LBL}>Descrição / objetivo</div>
          <textarea rows={3} value={f.descricao} placeholder="O que precisa ser entregue e por quê"
            onChange={function(e){set("descricao",e.target.value);}}
            onFocus={_demFoco} onBlur={_demBlur}
            style={Object.assign({},_DEM_INP,{fontWeight:500,resize:"vertical",minHeight:70,lineHeight:1.55})}/>
        </div>

        <div style={{paddingTop:12,borderTop:"1px solid #f1f5f9"}}>
          <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:8,flexWrap:"wrap"}}>
            <div style={Object.assign({},_DEM_LBL,{marginBottom:0})}>Etapas</div>
            <span style={{color:"#cbd5e1",fontSize:10.5,fontWeight:600}}>quebra a demanda em tarefas — dá pra completar depois</span>
            <span style={{flex:1}}/>
            {etapas.length>1&&<span title="Aplica em TODAS as etapas de uma vez"
              style={{display:"inline-flex",alignItems:"center",gap:6,flexShrink:0,background:"#f8fafc",
                border:"1px solid #eef0f3",borderRadius:99,padding:"3px 10px 3px 12px"}}>
              <span style={{color:"#94a3b8",fontSize:9.5,fontWeight:800,textTransform:"uppercase",letterSpacing:.4}}>Todas:</span>
              <_DemRespPicker mini valor="" onChange={function(v){
                setEtapas(function(p){ return p.map(function(t){ return Object.assign({},t,{resp:v}); }); });
                if(typeof pixelsToast!=="undefined") pixelsToast.success(v?"Responsável aplicado em todas as etapas.":"Responsável removido de todas.");
              }}/>
              <_DemDataInput compacto valor="" placeholder="Data" onChange={function(v){
                setEtapas(function(p){ return p.map(function(t){ return Object.assign({},t,{prazo:v}); }); });
                if(typeof pixelsToast!=="undefined") pixelsToast.success(v?"Prazo aplicado em todas as etapas.":"Prazo removido de todas.");
              }}/>
            </span>}
          </div>
          {etapas.length>0&&<div style={{display:"flex",flexDirection:"column",gap:6,marginBottom:7}}>
            {etapas.map(function(t,i){
              const _ok=t.status==="concluida";
              const _notaOn=!!notaForm[t.id];
              const _temObs=!!(t.obs&&String(t.obs).trim());
              return <div key={t.id} style={{display:"flex",flexDirection:"column",gap:5}}>
                <div style={{display:"grid",gridTemplateColumns:isMob?"20px 1fr auto":"20px minmax(0,1fr) 44px 118px auto",gap:6,alignItems:"center"}}>
                <span onClick={function(){_checkEtapa(t.id);}} title={_ok?"Desmarcar":"Concluir etapa"}
                  style={{width:17,height:17,borderRadius:"50%",cursor:"pointer",
                    background:_ok?"#16a34a":"#fff",border:_ok?"1.5px solid #16a34a":"1.5px solid #cbd5e1",
                    display:"inline-flex",alignItems:"center",justifyContent:"center",transition:"all .12s"}}>
                  {_ok&&<svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="3.4" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12"/></svg>}
                </span>
                <input value={t.nome} placeholder={"Etapa "+(i+1)+" — ex: Briefing com o cliente"} autoFocus={!t.nome}
                  onChange={function(e){_setEtapa(t.id,"nome",e.target.value);}}
                  onKeyDown={function(e){ if(e.key==="Enter"){ e.preventDefault(); _addEtapa(); } }}
                  onFocus={_demFoco} onBlur={function(e){_setEtapa(t.id,"nome",pxDemTexto(e.target.value));_demBlur(e);}} style={_DEM_INP}/>
                {!isMob&&<div style={{display:"flex",justifyContent:"center"}}>
                  <_DemRespPicker mini valor={t.resp} onChange={function(v){_setEtapa(t.id,"resp",v);}}/>
                </div>}
                {!isMob&&<_DemDataInput compacto valor={t.prazo} onChange={function(v){_setEtapa(t.id,"prazo",v);}} placeholder="Prazo"/>}
                <div style={{display:"flex",alignItems:"center",gap:1,justifyContent:"flex-end"}}>
                  <button type="button" title={_temObs?"Editar explicação da etapa":"Explicar o que essa etapa representa"}
                    onClick={function(){setNotaForm(function(m){var n=Object.assign({},m);n[t.id]=!m[t.id];return n;});}}
                    style={{background:_notaOn?"#7c3aed18":"transparent",border:"none",borderRadius:6,color:_temObs?"#7c3aed":"#cbd5e1",cursor:"pointer",padding:"6px 4px",display:"inline-flex",alignItems:"center"}}
                    onMouseEnter={function(e){if(!_notaOn)e.currentTarget.style.color="#7c3aed";}}
                    onMouseLeave={function(e){if(!_notaOn)e.currentTarget.style.color=_temObs?"#7c3aed":"#cbd5e1";}}>
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg>
                  </button>
                  <button type="button" onClick={function(){_delEtapa(t.id);}} title="Remover etapa"
                    style={{background:"transparent",border:"none",color:"#cbd5e1",cursor:"pointer",padding:"6px 4px",
                      display:"inline-flex",alignItems:"center"}}
                    onMouseEnter={function(e){e.currentTarget.style.color="#dc2626";}}
                    onMouseLeave={function(e){e.currentTarget.style.color="#cbd5e1";}}>
                    <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
                  </button>
                </div>
                </div>
                {(_notaOn||_temObs)&&<div style={{paddingLeft:isMob?0:23}}>
                  <textarea value={t.obs||""} placeholder="Explique o que essa etapa representa / o que precisa acontecer pra concluir (opcional)"
                    onChange={function(e){_setEtapa(t.id,"obs",e.target.value);}}
                    onFocus={_demFoco} onBlur={_demBlur}
                    style={Object.assign({},_DEM_INP,{minHeight:_notaOn?50:0,padding:"7px 11px",fontSize:11.5,fontWeight:500,lineHeight:1.5,color:"#475569",resize:"vertical",background:"#f8fafc"})}/>
                </div>}
              </div>;
            })}
          </div>}
          <button type="button" onClick={_addEtapa}
            style={{background:"#fff",border:"1px dashed #cbd5e1",borderRadius:9,padding:"8px 12px",width:"100%",
              color:"#64748b",fontSize:11.5,fontWeight:700,cursor:"pointer",fontFamily:_DEM_FF,
              display:"flex",alignItems:"center",justifyContent:"center",gap:6,transition:"all .12s"}}
            onMouseEnter={function(e){e.currentTarget.style.borderColor="#a78bfa";e.currentTarget.style.color="#7c3aed";}}
            onMouseLeave={function(e){e.currentTarget.style.borderColor="#cbd5e1";e.currentTarget.style.color="#64748b";}}>
            <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
            {etapas.length?"Mais uma etapa":"Adicionar etapas"}
          </button>
        </div>

        <div style={{display:"grid",gridTemplateColumns:isMob?"1fr":"1fr 1fr",gap:10,paddingTop:12,borderTop:"1px solid #f1f5f9"}}>
          <div>
            <div style={_DEM_LBL}>Responsável principal</div>
            <_DemRespPicker valor={f.responsavel} onChange={function(v){set("responsavel",v);}}/>
          </div>
          <div>
            <div style={_DEM_LBL}>Prioridade</div>
            <div style={{display:"flex",gap:5}}>
              {DEM_PRIOS.map(function(p){
                const _on=f.prioridade===p.id;
                return <button key={p.id} type="button" onClick={function(){set("prioridade",p.id);}}
                  style={{flex:1,background:_on?p.cor:"#fff",color:_on?"#fff":"#64748b",
                    border:"1px solid "+(_on?p.cor:"#e2e8f0"),borderRadius:9,padding:"9px 6px",fontSize:11.5,
                    fontWeight:_on?800:600,cursor:"pointer",fontFamily:_DEM_FF,transition:"all .12s"}}>{p.label}</button>;
              })}
            </div>
          </div>
        </div>

        <div style={{display:"grid",gridTemplateColumns:isMob?"1fr 1fr":"1fr 1fr .72fr 1fr",gap:10}}>
          <div>
            <div style={_DEM_LBL}>Data de início</div>
            <_DemDataInput valor={f.data_inicio||""} onChange={function(v){set("data_inicio",v);}} placeholder="Hoje"/>
          </div>
          <div>
            <div style={_DEM_LBL}>Prazo final</div>
            <_DemDataInput valor={f.prazo||""} onChange={function(v){set("prazo",v);}} placeholder="Sem prazo"/>
          </div>
          <div>
            <div style={_DEM_LBL}>Horário</div>
            <_DemHoraInput valor={f.hora||""} onChange={function(v){set("hora",v);}} placeholder="—"/>
          </div>
          <div>
            <div style={_DEM_LBL}>Status</div>
            <select value={f.status} onChange={function(e){set("status",e.target.value);}}
              onFocus={_demFoco} onBlur={_demBlur} style={Object.assign({},_DEM_INP,{cursor:"pointer"})}>
              {DEM_STATUS.map(function(s){return <option key={s.id} value={s.id}>{s.label}</option>;})}
            </select>
          </div>
        </div>

        <div style={{marginTop:12}}>
          <div style={_DEM_LBL}>Cidade (opcional)</div>
          <div style={{position:"relative"}}>
            <span style={{position:"absolute",left:12,top:"50%",transform:"translateY(-50%)",color:f.cidade?"#7c3aed":"#94a3b8",pointerEvents:"none",display:"inline-flex"}}>
              <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.3" strokeLinecap="round" strokeLinejoin="round"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0118 0z"/><circle cx="12" cy="10" r="3"/></svg>
            </span>
            <input type="text" value={f.cidade||""} onChange={function(e){set("cidade",e.target.value);}}
              onFocus={_demFoco} onBlur={_demBlur} placeholder="Ex.: Chapecó, Curitiba..."
              style={Object.assign({},_DEM_INP,{paddingLeft:36})}/>
          </div>
        </div>

        <div style={{marginTop:12}}>
          <div style={_DEM_LBL}>{f.categoria==="reuniao"?"Ata da reunião (o cliente vê no portal)":"Resumo (o cliente vê no portal)"}</div>
          <textarea value={f.resumo||""} onChange={function(e){set("resumo",e.target.value);}}
            onFocus={_demFoco} onBlur={_demBlur} rows={4}
            placeholder={"Um tópico por linha — ex:\nDefinimos o calendário de setembro\nCliente vai enviar as fotos da obra\nPróxima reunião dia 15"}
            style={Object.assign({},_DEM_INP,{resize:"vertical",minHeight:86,lineHeight:1.6})}/>
        </div>
      </div>

      <div style={{padding:"14px 22px 18px",borderTop:"1px solid #f1f5f9",display:"flex",justifyContent:"space-between",alignItems:"center",gap:8,flexWrap:"wrap"}}>
        <div style={{display:"flex",alignItems:"center",minHeight:34,gap:7,flexWrap:"wrap"}}>
          {(!_novo&&inicial&&inicial.id)&&(
            _demDoPortal(inicial)
              ? <span title="Veio pelo portal — sincronizada automaticamente lá"
                  style={{color:"#2563eb",fontSize:11,fontWeight:700,display:"inline-flex",alignItems:"center",gap:5}}>
                  <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"/><line x1="2" y1="12" x2="22" y2="12"/><path d="M12 2a15.3 15.3 0 014 10 15.3 15.3 0 01-4 10 15.3 15.3 0 01-4-10 15.3 15.3 0 014-10z"/></svg>
                  Veio pelo portal · sempre sincronizada
                </span>
              : (typeof onPortal==="function")&&<button type="button"
                  onClick={function(){ onPortal(Object.assign({},inicial,{portal_visivel:pv})); setPv(!pv); }}
                  title={pv?"O cliente está vendo essa demanda no portal — clique pra tirar de lá":"Libera essa demanda pro cliente acompanhar no portal"}
                  style={{background:pv?"#f0fdfa":"#fff",border:"1px solid "+(pv?"#5eead4":"#e2e8f0"),borderRadius:9,
                    padding:"7px 13px",color:pv?"#0d9488":"#475569",fontSize:11,fontWeight:800,cursor:"pointer",
                    fontFamily:_DEM_FF,display:"inline-flex",alignItems:"center",gap:6,whiteSpace:"nowrap"}}>
                  <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>
                  {pv?"No portal · Remover":"Enviar pro portal"}
                </button>
          )}
          {(!_novo&&f.status==="concluida"&&inicial&&inicial.id&&inicial.client_id)
            &&<_DemCkBtn d={Object.assign({},inicial,{titulo:f.titulo||inicial.titulo,descricao:f.descricao})}/>}
        </div>
        <div style={{display:"flex",gap:8}}>
        <button onClick={onFechar} type="button"
          style={{background:"#fff",color:"#64748b",border:"1px solid #e2e8f0",borderRadius:10,padding:"10px 18px",
            fontWeight:700,fontSize:13,cursor:"pointer",fontFamily:_DEM_FF}}>Cancelar</button>
        <button onClick={_salvar} type="button"
          style={{background:"linear-gradient(135deg,#a855f7,#7c3aed)",color:"#fff",border:"none",borderRadius:10,
            padding:"10px 22px",fontWeight:800,fontSize:13,cursor:"pointer",fontFamily:_DEM_FF,
            boxShadow:"0 6px 16px rgba(124,58,237,.32)",display:"inline-flex",alignItems:"center",gap:7}}>
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.8" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
          {_novo?"Criar demanda":"Salvar"}
        </button>
        </div>
      </div>
    </div>
  </div>;
}

/* ═══ QUADRO (kanban por status) — compartilhado pela aba do cliente e pela
   central. Arrastar entre colunas muda o status; clique abre as etapas. ═══ */
function _DemandasQuadro({lista, canEdit, onMudarStatus, onAbrir, onSalvar, onContexto, mostrarCliente}){
  const [dragDem,setDragDem]=useState(null);
  const [overCol,setOverCol]=useState(null);
  const [abertoId,setAbertoId]=useState(null); // card expandido DENTRO do kanban (etapas inline)
  // Marca/desmarca etapa direto do kanban, com carimbo de quem/quando
  const _checkTarefa=function(d,t){
    if(!canEdit||!onSalvar) return;
    const _ts=(Array.isArray(d.tarefas)?d.tarefas:[]).map(function(x){
      if(x.id!==t.id) return x;
      if(x.status==="concluida") return Object.assign({},x,{status:"afazer",done_at:"",done_by:""});
      return Object.assign({},x,{status:"concluida",done_at:new Date().toISOString(),
        done_by:(typeof CURRENT_USER!=="undefined"&&CURRENT_USER)?CURRENT_USER.id:""});
    });
    onSalvar(Object.assign({},d,{tarefas:_ts}));
  };
  return <div style={{display:"grid",gridTemplateColumns:"repeat("+DEM_STATUS.length+",minmax(200px,1fr))",gap:10,overflowX:"auto",paddingBottom:6}}>
              {DEM_STATUS.map(function(st){
                const _cards=lista.filter(function(d){ return (d.status||"nao_iniciada")===st.id; });
                const _alvo=overCol===st.id && dragDem;
                return <div key={st.id}
                  onDragOver={function(e){ if(!canEdit) return; e.preventDefault(); try{e.dataTransfer.dropEffect="move";}catch(_){} setOverCol(function(p){return p===st.id?p:st.id;}); }}
                  onDrop={function(e){ if(!canEdit) return; e.preventDefault(); onMudarStatus(dragDem, st.id); setDragDem(null); setOverCol(null); }}
                  style={{background:_alvo?st.bg:"#f8fafc",border:"1px solid "+(_alvo?st.cor+"66":"#eef0f3"),borderRadius:14,
                    padding:0,display:"flex",flexDirection:"column",gap:0,minHeight:200,transition:"all .12s",overflow:"hidden"}}>
                  <div style={{display:"flex",alignItems:"center",gap:7,padding:"8px 12px",background:st.cor}}>
                    {typeof Ico==="function"&&<Ico n={st.ico||"dot"} size={13} color="#fff"/>}
                    <span style={{color:"#fff",fontSize:12,fontWeight:700,letterSpacing:.1,flex:1,minWidth:0,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{st.label}</span>
                    <span style={{background:"rgba(255,255,255,.25)",color:"#fff",fontSize:10.5,fontWeight:700,borderRadius:99,padding:"0 8px",fontFeatureSettings:"'tnum'"}}>{_cards.length}</span>
                  </div>
                  <div style={{display:"flex",flexDirection:"column",gap:8,padding:"10px 9px",flex:1}}>
                  {_cards.map(function(d){
                    const cat=_demCat(d.categoria);
                    const prog=_demProgresso(d);
                    const resp=_demMembro(d.responsavel);
                    const prio=_demPrio(d.prioridade);
                    const _dd=_demDias(d.prazo);
                    const _late=d.status!=="concluida"&&_dd!==null&&_dd<0;
                    const _perto=d.status!=="concluida"&&_dd!==null&&_dd>=0&&_dd<=3;
                    const _dragging=dragDem&&dragDem.id===d.id;
                    const _chip=mostrarCliente?_demCliChip(d):null;
                    const _exp=abertoId===d.id;
                    return <div key={d.id}
                      draggable={canEdit}
                      onDragStart={function(e){ setDragDem(d); try{e.dataTransfer.effectAllowed="move";}catch(_){} }}
                      onDragEnd={function(){ setDragDem(null); setOverCol(null); }}
                      onClick={function(){ if(onAbrir) onAbrir(d); }}
                      onContextMenu={onContexto?function(e){ e.preventDefault(); onContexto(d, e.clientX, e.clientY); }:undefined}
                      title="Clique pra abrir a demanda · arraste pra mudar o status"
                      style={{background:"#fff",border:"1px solid "+(_exp?"#d3d9e2":"#e8ebf0"),borderRadius:10,
                        padding:"11px 12px",cursor:canEdit?"grab":"pointer",display:"flex",flexDirection:"column",gap:8,
                        opacity:_dragging?.4:1,boxShadow:"0 1px 2px rgba(15,23,42,.04)",transition:"box-shadow .12s, opacity .12s"}}
                      onMouseEnter={function(e){e.currentTarget.style.boxShadow="0 5px 14px rgba(15,23,42,.09)";}}
                      onMouseLeave={function(e){e.currentTarget.style.boxShadow="0 1px 2px rgba(15,23,42,.04)";}}>

                      {/* Linha do cliente: logo em proporção natural (nada de caixinha) */}
                      {_chip&&<div style={{display:"flex",alignItems:"center",minHeight:20}}>
                        <span title={_chip.titulo} style={{display:"inline-flex",alignItems:"center",gap:6,maxWidth:"100%",
                          background:"linear-gradient(135deg,"+_chip.cor+"1f,"+_chip.cor+"0d)",
                          border:"1px solid "+_chip.cor+"40",borderRadius:99,padding:"3.5px 10px 3.5px 6px",
                          backdropFilter:"blur(6px)",WebkitBackdropFilter:"blur(6px)",
                          boxShadow:"inset 0 1px 0 rgba(255,255,255,.5)"}}>
                          {_chip.logo&&<img src={_chip.logo} alt="" style={{height:12,maxWidth:46,objectFit:"contain",flexShrink:0}}/>}
                          {(!!_chip.nome||!_chip.logo)&&<span style={{color:_chip.cor,fontSize:9,fontWeight:800,letterSpacing:.7,textTransform:"uppercase",minWidth:0,
                            overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{_chip.nome||_chip.titulo}</span>}
                        </span>
                      </div>}

                      {/* Titulo — regular, respirado */}
                      <div style={{display:"flex",alignItems:"flex-start",gap:6}}>
                        <span style={{color:"#1e293b",fontSize:13,fontWeight:400,letterSpacing:-.05,lineHeight:1.4,flex:1,minWidth:0}}>{d.titulo}</span>
                        <_DemPortalTag d={d} mini={true}/>
                      </div>

                      {/* Meta discreta: categoria · data (cor só quando importa) */}
                      <div style={{display:"flex",alignItems:"center",gap:6,color:"#94a3b8",fontSize:10.5,fontWeight:600}}>
                        <span style={{display:"inline-flex",alignItems:"center",gap:4}}>
                          {typeof Ico==="function"&&<Ico n={cat.ico||"folder"} size={10} color="#94a3b8"/>}
                          {cat.label}
                        </span>
                        {d.prazo&&<span title={"Prazo de entrega: "+_demBR(d.prazo)}
                          style={{color:_late?"#dc2626":(_perto?"#b45309":"#94a3b8"),fontWeight:(_late||_perto)?800:600,
                          fontFeatureSettings:"'tnum'",display:"inline-flex",alignItems:"center",gap:3}}>
                          {typeof Ico==="function"&&<Ico n="flame" size={10} color={_late?"#dc2626":(_perto?"#b45309":"#b6bec9")}/>}
                          {_demBRCurto(d.prazo)}{_late?(" · "+Math.abs(_dd)+"d atraso"):""}
                        </span>}
                      </div>

                      {/* Rodape: responsavel + progresso — clique AQUI expande as etapas no card */}
                      <div onClick={function(e){ e.stopPropagation(); setAbertoId(_exp?null:d.id); }}
                        title={_exp?"Recolher etapas":"Ver as etapas aqui no card"}
                        style={{display:"flex",alignItems:"center",gap:7,paddingTop:8,borderTop:"1px solid #f4f6f8",cursor:"pointer"}}>
                        {resp&&<UserAvatar user={resp} size={18} border={false}/>}
                        {prog.total>0
                          ? <span style={{color:"#334155",fontSize:11.5,fontWeight:800,fontFeatureSettings:"'tnum'",flexShrink:0}}>{prog.feitas}/{prog.total}</span>
                          : null}
                        <div style={{flex:1,minWidth:0}}>
                          <_DemBarra pct={prog.pct} cor={prog.pct>=100?"#16a34a":"#7c3aed"} altura={5}/>
                        </div>
                        <span style={{color:prog.pct>=100?"#16a34a":"#64748b",fontSize:11.5,fontWeight:800,fontFeatureSettings:"'tnum'",flexShrink:0}}>{prog.pct}%</span>
                        <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="#c2cad6" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round"
                          style={{flexShrink:0,transition:"transform .18s",transform:_exp?"rotate(180deg)":"rotate(0deg)"}}>
                          <polyline points="6 9 12 15 18 9"/>
                        </svg>
                      </div>

                      {/* Etapas expandidas DENTRO do kanban */}
                      {_exp&&<div onClick={function(e){e.stopPropagation();}}
                        style={{borderTop:"1px solid #f4f6f8",paddingTop:8,display:"flex",flexDirection:"column",gap:4,cursor:"default"}}>
                        {(Array.isArray(d.tarefas)?d.tarefas:[]).length===0
                          ? <div style={{color:"#b45309",fontSize:10.5,fontWeight:700,padding:"2px 0"}}>Sem etapas ainda — abre a demanda pra criar.</div>
                          : (Array.isArray(d.tarefas)?d.tarefas:[]).map(function(t){
                              const _ok=t.status==="concluida";
                              const _tr=_demMembro(t.resp);
                              return <div key={t.id} style={{display:"flex",alignItems:"center",gap:7,padding:"2px 0"}}>
                                <span onClick={function(){_checkTarefa(d,t);}}
                                  title={canEdit?(_ok?"Desmarcar":"Concluir etapa"):""}
                                  style={{width:15,height:15,borderRadius:"50%",flexShrink:0,cursor:canEdit?"pointer":"default",
                                    background:_ok?"#16a34a":"#fff",border:_ok?"1.5px solid #16a34a":"1.5px solid #cbd5e1",
                                    display:"inline-flex",alignItems:"center",justifyContent:"center",transition:"all .12s"}}>
                                  {_ok&&<svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="3.4" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12"/></svg>}
                                </span>
                                <span style={{flex:1,minWidth:0,color:_ok?"#94a3b8":"#334155",fontSize:11.5,fontWeight:500,lineHeight:1.35,
                                  textDecoration:_ok?"line-through":"none",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{t.nome}</span>
                                {t.prazo&&!_ok&&<span style={{color:"#94a3b8",fontSize:9.5,fontWeight:700,fontFeatureSettings:"'tnum'",flexShrink:0}}>{_demBRCurto(t.prazo)}</span>}
                                {_tr&&<UserAvatar user={_tr} size={15} border={false}/>}
                              </div>;
                            })}
                        <button type="button" onClick={function(){ if(onAbrir) onAbrir(d); }}
                          style={{background:"#fff",border:"1px solid #e2e8f0",borderRadius:8,padding:"7px 10px",marginTop:5,
                            color:"#475569",fontSize:11,fontWeight:700,cursor:"pointer",fontFamily:_DEM_FF,width:"100%",
                            display:"flex",alignItems:"center",justifyContent:"center",gap:6,transition:"all .12s"}}
                          onMouseEnter={function(e){e.currentTarget.style.borderColor="#c4b5fd";e.currentTarget.style.color="#7c3aed";e.currentTarget.style.background="#faf8ff";}}
                          onMouseLeave={function(e){e.currentTarget.style.borderColor="#e2e8f0";e.currentTarget.style.color="#475569";e.currentTarget.style.background="#fff";}}>
                          <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><polyline points="15 3 21 3 21 9"/><polyline points="9 21 3 21 3 15"/><line x1="21" y1="3" x2="14" y2="10"/><line x1="3" y1="21" x2="10" y2="14"/></svg>
                          Abrir demanda completa
                        </button>
                      </div>}
                    </div>;
                  })}
                  {_cards.length===0&&<div style={{color:_alvo?st.cor:"#cbd5e1",fontSize:10.5,fontWeight:700,textAlign:"center",padding:"16px 4px",border:"1.5px dashed "+(_alvo?st.cor+"77":"#e2e8f0"),borderRadius:10,transition:"all .12s"}}>
                    {_alvo?"Solte aqui":"—"}
                  </div>}
                  </div>
                </div>;
              })}
            </div>;
}

/* ═══════════════════════════════════════════════════════════════════════
   HISTÓRICO DE ENTREGAS — demandas concluídas saem da lista/quadro e
   ficam aqui, recolhidas. Dá pra enviar as importantes pros Checkpoints
   (client_milestones, tipo "entrega") — sem duplicar: a demanda de origem
   fica gravada em metrics.from_demanda.
═══════════════════════════════════════════════════════════════════════ */
function _demBRData(iso){
  if(!iso) return "";
  const d=String(iso).slice(0,10).split("-");
  return d.length===3 ? (d[2]+"/"+d[1]+"/"+d[0]) : "";
}
function _DemHistorico({lista, canEdit, mostrarCliente, onAbrir}){
  const sb=(typeof window!=="undefined")?window._sb:null;
  const [aberto,setAberto]=useState(false);
  const [enviados,setEnviados]=useState(null);   // null=carregando | {demandaId:true}
  const [enviando,setEnviando]=useState("");

  const _carregarEnviados=async function(){
    if(!sb||!lista.length){ setEnviados({}); return; }
    try{
      const _cids=[];
      lista.forEach(function(d){ if(d.client_id&&_cids.indexOf(d.client_id)<0) _cids.push(d.client_id); });
      const r=await sb.from("client_milestones").select("id,metrics").in("client_id",_cids);
      const m={};
      ((r&&r.data)||[]).forEach(function(row){
        const fd=row&&row.metrics&&row.metrics.from_demanda;
        if(fd) m[fd]=true;
      });
      setEnviados(m);
    }catch(_){ setEnviados({}); }
  };
  useEffect(function(){ if(aberto&&enviados===null) _carregarEnviados(); },[aberto]);

  const _desfazer=async function(d){
    if(!sb||enviando) return;
    let ok=true;
    if(typeof pxExclusaoBloqueada==="function"&&pxExclusaoBloqueada(CURRENT_USER)){if(typeof pixelsToast!=="undefined")pixelsToast.warning("Você não tem permissão para remover.");return;}
    if(typeof pixelsConfirm==="function")
      ok=await pixelsConfirm({title:"Tirar dos Checkpoints?",message:'"'+(d.titulo||"")+'" sai dos Checkpoints do cliente. A entrega continua aqui no histórico.',danger:true});
    if(!ok) return;
    setEnviando(d.id);
    try{
      const r=await sb.from("client_milestones").delete()
        .eq("client_id",d.client_id).eq("metrics->>from_demanda",String(d.id));
      if(r&&r.error) throw r.error;
      setEnviados(function(p){ const n=Object.assign({},p||{}); delete n[d.id]; return n; });
      if(typeof pixelsToast!=="undefined") pixelsToast.success("Removida dos Checkpoints.");
    }catch(e){
      if(typeof pixelsToast!=="undefined") pixelsToast.error("Erro removendo: "+((e&&e.message)||""),4500);
    }
    setEnviando("");
  };
  const _enviar=async function(d){
    if(!sb||enviando) return;
    setEnviando(d.id);
    try{
      const _quando=_demConcluidaEm(d);
      const _data=_quando?String(_quando).slice(0,10):new Date().toISOString().slice(0,10);
      const _met={from_demanda:d.id};
      if(d.cidade) _met.city=d.cidade;
      if(d.unidade&&d.unidade!=="grupo") _met.unit=d.unidade;
      const r=await sb.from("client_milestones").insert({
        client_id:d.client_id, date:_data, type:"entrega",
        title:d.titulo||"Entrega", description:d.descricao||null,
        metrics:_met,
        created_by:(typeof CURRENT_USER!=="undefined"&&CURRENT_USER)?CURRENT_USER.name:""
      });
      if(r&&r.error) throw r.error;
      setEnviados(function(p){ const n=Object.assign({},p||{}); n[d.id]=true; return n; });
      if(typeof pixelsToast!=="undefined") pixelsToast.success("Enviada pros Checkpoints do cliente.");
    }catch(e){
      if(typeof pixelsToast!=="undefined") pixelsToast.error("Erro enviando: "+((e&&e.message)||""),4500);
    }
    setEnviando("");
  };

  if(!lista.length) return null;
  return <div style={{background:"#fff",border:"1px solid #eef0f3",borderRadius:14,overflow:"hidden"}}>
    <div onClick={function(){setAberto(!aberto);}}
      style={{padding:"13px 17px",display:"flex",alignItems:"center",gap:11,cursor:"pointer",
        background:aberto?"#fafbfc":"#fff",transition:"background .12s"}}>
      <div style={{width:30,height:30,borderRadius:9,background:"#dcfce7",border:"1px solid #86efac",
        display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#16a34a" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
      </div>
      <div style={{flex:1,minWidth:0}}>
        <div style={{color:"#0f172a",fontWeight:800,fontSize:13,letterSpacing:-.2}}>Histórico de entregas</div>
        <div style={{color:"#94a3b8",fontSize:11,marginTop:1,fontWeight:600}}>Demandas concluídas — as mais importantes podem virar Checkpoints</div>
      </div>
      <span style={{background:"#dcfce7",color:"#15803d",border:"1px solid #86efac",fontSize:11,fontWeight:800,
        borderRadius:99,padding:"2px 9px",fontFeatureSettings:"'tnum'",flexShrink:0}}>{lista.length}</span>
      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#94a3b8" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round"
        style={{flexShrink:0,transition:"transform .18s",transform:aberto?"rotate(180deg)":"rotate(0deg)"}}>
        <polyline points="6 9 12 15 18 9"/>
      </svg>
    </div>
    {aberto&&<div style={{borderTop:"1px solid #f1f5f9"}}>
      {lista.map(function(d,i){
        const cat=_demCat(d.categoria);
        const _cli=mostrarCliente?(typeof CLIENTS!=="undefined"?CLIENTS:[]).find(function(c){return c.id===d.client_id;}):null;
        const _ja=enviados&&enviados[d.id];
        return <div key={d.id} style={{display:"flex",alignItems:"center",gap:10,padding:"11px 17px",
          borderTop:i>0?"1px solid #f8fafc":"none",flexWrap:"wrap"}}>
          {_cli&&<span title={_cli.name}
            style={{width:24,height:24,display:"inline-flex",alignItems:"center",justifyContent:"center",
              overflow:"hidden",flexShrink:0,background:"#fff",border:"1px solid #eef0f3",borderRadius:7,padding:2}}>
            {typeof ClientLogo==="function"?<ClientLogo clientId={_cli.id} size="sm"/>:null}
          </span>}
          <div onClick={function(){ if(onAbrir) onAbrir(d); }}
            style={{flex:1,minWidth:160,cursor:onAbrir?"pointer":"default"}}>
            <div style={{color:"#0f172a",fontSize:12.5,fontWeight:400,letterSpacing:-.05,lineHeight:1.35,display:"flex",alignItems:"center",gap:6,flexWrap:"wrap"}}>{d.titulo} <_DemPortalTag d={d} mini={true}/></div>
            <div style={{color:cat.cor,fontSize:10,fontWeight:700,marginTop:1}}>{cat.label}</div>
          </div>
          <span style={{background:"#dcfce7",color:"#15803d",border:"1px solid #86efac",borderRadius:99,
            padding:"3px 10px",fontSize:11,fontWeight:800,whiteSpace:"nowrap",display:"inline-flex",alignItems:"center",gap:5,flexShrink:0}}>
            <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
            Concluída em {_demBRData(_demConcluidaEm(d))||"—"}
          </span>
          {canEdit&&(
            _ja
              ? <button type="button" disabled={!!enviando} onClick={function(){_desfazer(d);}}
                  title="Está nos Checkpoints do cliente — clique pra desfazer o envio"
                  style={{background:"#f0fdfa",color:"#0d9488",border:"1px solid #99f6e4",borderRadius:9,
                    padding:"5px 11px",fontSize:10.5,fontWeight:800,whiteSpace:"nowrap",display:"inline-flex",alignItems:"center",gap:5,flexShrink:0,
                    cursor:enviando?"wait":"pointer",fontFamily:_DEM_FF,opacity:enviando===d.id?.6:1,transition:"all .12s"}}
                  onMouseEnter={function(e){e.currentTarget.style.background="#fef2f2";e.currentTarget.style.borderColor="#fecaca";e.currentTarget.style.color="#dc2626";}}
                  onMouseLeave={function(e){e.currentTarget.style.background="#f0fdfa";e.currentTarget.style.borderColor="#99f6e4";e.currentTarget.style.color="#0d9488";}}>
                  <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
                  {enviando===d.id?"Removendo…":"No Checkpoint · desfazer"}
                </button>
              : <button type="button" disabled={!!enviando} onClick={function(){_enviar(d);}}
                  title="Registra essa entrega nos Checkpoints do cliente (aparece no calendário e no portal)"
                  style={{background:"#fff",color:"#0d9488",border:"1px solid #5eead4",borderRadius:9,
                    padding:"5px 11px",fontSize:10.5,fontWeight:800,cursor:enviando?"wait":"pointer",fontFamily:_DEM_FF,
                    whiteSpace:"nowrap",display:"inline-flex",alignItems:"center",gap:5,flexShrink:0,opacity:enviando===d.id?.6:1}}>
                  <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round"><path d="M8.21 13.89 7 23l5-3 5 3-1.21-9.12"/><circle cx="12" cy="8" r="6"/></svg>
                  {enviando===d.id?"Enviando…":"Enviar pro Checkpoint"}
                </button>
          )}
        </div>;
      })}
    </div>}
  </div>;
}

/* ═══════════════════════════════════════════════════════════════════════
   ABA DEMANDAS — componente principal
═══════════════════════════════════════════════════════════════════════ */
function CDemandas({cl, canEdit, selUnit}){
  const sb=(typeof window!=="undefined")?window._sb:null;
  const isMob=(typeof _pxMob==="function")?_pxMob():false;
  const _cor=(cl&&cl.color)||"#7c3aed";

  // Bioter: demandas ficam no client_id raiz, a unidade vai no campo `unidade`
  const _rootId=(cl&&cl.id&&cl.id.indexOf("bioter_")===0) ? "bioter" : ((cl&&cl.id)||"");
  const _isBioter=_rootId==="bioter";
  const _unidade=(cl&&cl.id&&cl.id.indexOf("bioter_")===0)
    ? cl.id.slice("bioter_".length)
    : (selUnit||"grupo");

  const [demandas,setDemandas]=useState([]);
  const [loading,setLoading]=useState(true);
  const [abertas,setAbertas]=useState({});
  const [quadroAberto,setQuadroAberto]=useState(null); // demanda aberta em modal (clique no quadro)
  const [lixeira,setLixeira]=useState([]);             // soft-deletadas (30 dias)
  const [ctxMenu,setCtxMenu]=useState(null);           // {d,x,y} — botão direito no card
  const [modal,setModal]=useState(null);       // null | {} novo | {...} editar
  const [busca,setBusca]=useState("");
  const [fStatus,setFStatus]=useState("");
  const [fResp,setFResp]=useState("");
  const [fCat,setFCat]=useState("");
  const [fPrazo,setFPrazo]=useState("");
  const [verMarcos,setVerMarcos]=useState(false);
  // Vista: lista (detalhe/etapas) ou quadro (kanban por status). Persistida.
  const _VISTA_KEY="pixels-demandas-vista";
  const [vista,setVista]=useState(function(){
    try{ return localStorage.getItem(_VISTA_KEY)||"lista"; }catch(_){ return "lista"; }
  });
  const _mudarVista=function(v){ setVista(v); try{ localStorage.setItem(_VISTA_KEY,v); }catch(_){} };

  const _carregar=async function(){
    if(!sb||!_rootId){ setLoading(false); return; }
    try{
      const r=await sb.from("client_demandas").select("*").eq("client_id",_rootId)
        .order("ordem",{ascending:true}).order("created_at",{ascending:false});
      const _rows=(r&&r.data)||[];
      setDemandas(_rows.filter(function(x){return !x.deleted_at;}));
      setLixeira(_rows.filter(function(x){return !!x.deleted_at;}));
      _demPurgarLixeira(sb);
    }catch(e){ console.warn("[demandas] load:", (e&&e.message)||e); }
    setLoading(false);
  };

  useEffect(function(){
    let alive=true;
    _carregar();
    if(!sb) return function(){alive=false;};
    let ch=null;
    try{
      ch=sb.channel("demandas-rt-"+_rootId)
        .on("postgres_changes",{event:"*",schema:"public",table:"client_demandas",filter:"client_id=eq."+_rootId},
          function(){ if(alive) _carregar(); })
        .subscribe();
    }catch(_){}
    return function(){
      alive=false;
      try{ if(ch) sb.removeChannel(ch); }catch(_){}
    };
  },[_rootId]);

  /* ── Persistencia ── */
  // Autosave campo a campo (edição inline na ficha da demanda)
  const _patchDemanda=async function(d,patch){
    setDemandas(function(prev){ return prev.map(function(x){ return x.id===d.id?Object.assign({},x,patch):x; }); });
    if(!sb) return;
    try{
      const r=await sb.from("client_demandas")
        .update(Object.assign({},patch,{updated_at:new Date().toISOString()})).eq("id",d.id);
      if(r&&r.error) throw r.error;
    }catch(e){
      if(typeof pixelsToast!=="undefined") pixelsToast.error("Erro salvando alteração.",4000);
      _carregar();
    }
  };
  const _salvarDemanda=async function(dados){
    if(!sb) return;
    const _payload={
      client_id:_rootId,
      titulo:String(dados.titulo||"").trim(),
      categoria:dados.categoria||"outros",
      descricao:dados.descricao||"",
      status:dados.status||"nao_iniciada",
      prioridade:dados.prioridade||"normal",
      responsavel:dados.responsavel||"",
      data_inicio:dados.data_inicio||null,
      prazo:dados.prazo||null,
      hora:dados.hora||null,
      cidade:dados.cidade||null,
      resumo:dados.resumo||null,
      // Editando: preserva a unidade original da demanda (não muda de unidade
      // só porque a edição foi feita vendo o grupo). Criando: usa a unidade da vista.
      unidade:_isBioter?((dados.id&&typeof dados.unidade==="string")?dados.unidade:(_unidade==="grupo"?"":_unidade||"")):"",
      tarefas:Array.isArray(dados.tarefas)?dados.tarefas:[],
      updated_at:new Date().toISOString(),
    };
    try{
      if(dados.id){
        const r=await sb.from("client_demandas").update(_payload).eq("id",dados.id);
        if(r&&r.error) throw r.error;
      }else{
        _payload.created_by=(typeof CURRENT_USER!=="undefined"&&CURRENT_USER)?CURRENT_USER.name:"";
        const r=await sb.from("client_demandas").insert(_payload);
        if(r&&r.error) throw r.error;
        if(typeof pixelsToast!=="undefined") pixelsToast.success("Demanda criada.");
      }
      setModal(null);
      _carregar();
    }catch(e){
      if(typeof pixelsToast!=="undefined") pixelsToast.error("Erro salvando: "+((e&&e.message)||""),5500);
    }
  };

  // Salvar so as tarefas (usado pelo detalhe) — otimista pra nao piscar
  const _salvarTarefas=async function(d){
    setDemandas(function(prev){
      return prev.map(function(x){ return x.id===d.id ? Object.assign({},x,{tarefas:d.tarefas}) : x; });
    });
    if(!sb) return;
    try{
      await sb.from("client_demandas")
        .update({tarefas:d.tarefas, updated_at:new Date().toISOString()})
        .eq("id",d.id);
    }catch(e){
      if(typeof pixelsToast!=="undefined") pixelsToast.error("Erro salvando tarefas.",4000);
      _carregar();
    }
  };

  // Arrastar no quadro = mudar o status da demanda
  const _mudarStatusDemanda=async function(d, novo){
    if(!d || d.status===novo) return;
    setDemandas(function(prev){
      return prev.map(function(x){ return x.id===d.id ? Object.assign({},x,{status:novo}) : x; });
    });
    if(!sb) return;
    try{
      await sb.from("client_demandas")
        .update({status:novo, updated_at:new Date().toISOString()})
        .eq("id",d.id);
    }catch(e){
      if(typeof pixelsToast!=="undefined") pixelsToast.error("Erro mudando status.",4000);
      _carregar();
    }
  };


  // Envia/remove a demanda do portal do cliente. Demanda que veio do portal
  // (created_by "portal_...") fica sempre sincronizada — nao passa por aqui.
  const _togglePortal=async function(d){
    if(!d||_demDoPortal(d)) return;
    const _novo=!d.portal_visivel;
    setDemandas(function(prev){
      return prev.map(function(x){ return x.id===d.id ? Object.assign({},x,{portal_visivel:_novo}) : x; });
    });
    if(!sb) return;
    try{
      const r=await sb.from("client_demandas")
        .update({portal_visivel:_novo, updated_at:new Date().toISOString()})
        .eq("id",d.id);
      if(r&&r.error) throw r.error;
      if(typeof pixelsToast!=="undefined")
        pixelsToast.success(_novo?"Demanda liberada no portal do cliente.":"Demanda removida do portal do cliente.");
    }catch(e){
      if(typeof pixelsToast!=="undefined") pixelsToast.error("Erro atualizando portal.",4000);
      _carregar();
    }
  };

  const _excluirDemanda=async function(d){
    if(typeof pxExclusaoBloqueada==="function"&&pxExclusaoBloqueada(CURRENT_USER)){if(typeof pixelsToast!=="undefined")pixelsToast.warning("Você não tem permissão para excluir.");return;}
    let ok=true;
    if(typeof pixelsConfirm==="function"){
      ok=await pixelsConfirm({title:"Mandar pra Lixeira?",message:'"'+(d.titulo||"")+'" fica '+_DEM_LIXEIRA_DIAS+' dias na Lixeira (dá pra restaurar) e depois some de vez.',danger:true});
    }
    if(!ok) return;
    try{
      const r=await sb.from("client_demandas")
        .update({deleted_at:new Date().toISOString(),updated_at:new Date().toISOString()}).eq("id",d.id);
      if(r&&r.error) throw r.error;
      if(typeof pixelsToast!=="undefined") pixelsToast.success("Foi pra Lixeira — "+_DEM_LIXEIRA_DIAS+" dias pra restaurar.");
      setQuadroAberto(null);
      _carregar();
    }catch(e){
      if(typeof pixelsToast!=="undefined") pixelsToast.error("Erro excluindo.",4000);
    }
  };
  const _restaurarDemanda=async function(d){
    try{
      const r=await sb.from("client_demandas")
        .update({deleted_at:null,updated_at:new Date().toISOString()}).eq("id",d.id);
      if(r&&r.error) throw r.error;
      if(typeof pixelsToast!=="undefined") pixelsToast.success("Demanda restaurada.");
      _carregar();
    }catch(e){ if(typeof pixelsToast!=="undefined") pixelsToast.error("Erro restaurando.",4000); }
  };
  const _excluirDefinitivo=async function(d){
    if(typeof pxExclusaoBloqueada==="function"&&pxExclusaoBloqueada(CURRENT_USER)){if(typeof pixelsToast!=="undefined")pixelsToast.warning("Você não tem permissão para excluir.");return;}
    let ok=true;
    if(typeof pixelsConfirm==="function"){
      ok=await pixelsConfirm({title:"Excluir DE VEZ?",message:'"'+(d.titulo||"")+'" será apagada agora, sem volta.',danger:true});
    }
    if(!ok) return;
    try{
      await sb.from("client_demandas").delete().eq("id",d.id);
      if(typeof pixelsToast!=="undefined") pixelsToast.success("Excluída definitivamente.");
      _carregar();
    }catch(e){ if(typeof pixelsToast!=="undefined") pixelsToast.error("Erro excluindo.",4000); }
  };

  /* ── Filtro por unidade (Bioter) ── */
  const _daUnidade=!_isBioter ? demandas : demandas.filter(function(d){
    if(_unidade==="grupo") return true;
    const u=d.unidade||"grupo";
    return u==="grupo" || u===_unidade;
  });

  /* ── Resumo operacional ── */
  const _resumo=(function(){
    const r={total:_daUnidade.length, andamento:0, aguardando:0, concluidas:0, atrasadas:0};
    _daUnidade.forEach(function(d){
      if(d.status==="andamento")  r.andamento++;
      if(d.status==="aguardando") r.aguardando++;
      if(d.status==="concluida")  r.concluidas++;
      const _dd=_demDias(d.prazo);
      if(d.status!=="concluida" && _dd!==null && _dd<0) r.atrasadas++;
    });
    return r;
  })();

  /* ── Filtros ── */
  const _q=String(busca||"").toLowerCase().trim();
  const _lista=_daUnidade.filter(function(d){
    if(_q && String(d.titulo||"").toLowerCase().indexOf(_q)<0 && String(d.descricao||"").toLowerCase().indexOf(_q)<0) return false;
    if(fStatus && d.status!==fStatus) return false;
    if(fCat && d.categoria!==fCat) return false;
    if(fResp){
      const _naTarefa=(Array.isArray(d.tarefas)?d.tarefas:[]).some(function(t){return t&&t.resp===fResp;});
      if(d.responsavel!==fResp && !_naTarefa) return false;
    }
    if(fPrazo){
      const _dd=_demDias(d.prazo);
      if(fPrazo==="atrasado" && !(d.status!=="concluida" && _dd!==null && _dd<0)) return false;
      if(fPrazo==="semana"   && !(_dd!==null && _dd>=0 && _dd<=7))  return false;
      if(fPrazo==="mes"      && !(_dd!==null && _dd>=0 && _dd<=30)) return false;
      if(fPrazo==="sem"      && d.prazo) return false;
    }
    return true;
  });

  const _temFiltro=!!(_q||fStatus||fCat||fResp||fPrazo);
  // Concluidas saem da lista/quadro e vivem no Historico de entregas.
  const _ativas=_lista.filter(function(d){ return d.status!=="concluida"; });
  const _concluidas=_lista.filter(function(d){ return d.status==="concluida"; })
    .slice().sort(function(a,b){ return String(_demConcluidaEm(b)).localeCompare(String(_demConcluidaEm(a))); });
  const _limpar=function(){ setBusca(""); setFStatus(""); setFCat(""); setFResp(""); setFPrazo(""); };

  const _time=(typeof TEAM!=="undefined")?TEAM:[];

  const _selEstilo={background:"#fff",border:"1px solid #e2e8f0",borderRadius:9,padding:"8px 11px",
    fontSize:11.5,fontWeight:700,color:"#475569",outline:"none",fontFamily:_DEM_FF,cursor:"pointer"};

  return <div style={{display:"flex",flexDirection:"column",gap:14,fontFamily:_DEM_FF}}>

    {/* ══ HEADER + RESUMO ══ */}
    <div style={{display:"flex",alignItems:"flex-start",justifyContent:"space-between",gap:14,flexWrap:"wrap"}}>
      <div style={{minWidth:0}}>
        <div style={{fontSize:18,fontWeight:800,color:"#0f172a",letterSpacing:-.3}}>Demandas</div>
        <div style={{fontSize:13,color:"#64748b",marginTop:3}}>Projetos e entregas maiores, com etapas, responsáveis e prazos.</div>
      </div>
      {canEdit && <button type="button" onClick={function(){setModal({});}}
        style={{background:"linear-gradient(135deg,#a855f7,#7c3aed)",color:"#fff",border:"none",borderRadius:10,
          padding:"10px 17px",fontSize:12.5,fontWeight:800,cursor:"pointer",fontFamily:_DEM_FF,
          display:"inline-flex",alignItems:"center",gap:7,boxShadow:"0 6px 16px rgba(124,58,237,.30)",flexShrink:0,transition:"all .12s"}}
        onMouseEnter={function(e){e.currentTarget.style.transform="translateY(-1px)";}}
        onMouseLeave={function(e){e.currentTarget.style.transform="";}}>
        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
        Nova demanda
      </button>}
    </div>

    {/* Resumo compacto */}
    <div style={{display:"grid",gridTemplateColumns:isMob?"repeat(2,1fr)":"repeat(5,minmax(0,1fr))",gap:9}}>
      {[
        {l:"Demandas",     v:_resumo.total,      c:"#0f172a"},
        {l:"Em andamento", v:_resumo.andamento,  c:"#d97706"},
        {l:"Aguardando",   v:_resumo.aguardando, c:"#db2777"},
        {l:"Concluídas",   v:_resumo.concluidas, c:"#15803d"},
        {l:"Atrasadas",    v:_resumo.atrasadas,  c:"#dc2626"},
      ].map(function(x,i){
        const _zero=!x.v;
        return <div key={i} style={{background:"#fff",border:"1px solid #eef0f3",borderRadius:11,padding:"11px 13px",
          boxShadow:"0 1px 2px rgba(15,23,42,.03)"}}>
          <div style={{color:_zero?"#cbd5e1":x.c,fontSize:21,fontWeight:800,letterSpacing:-.7,lineHeight:1,fontFeatureSettings:"'tnum'"}}>{x.v}</div>
          <div style={{color:"#94a3b8",fontSize:10,fontWeight:700,textTransform:"uppercase",letterSpacing:.5,marginTop:4}}>{x.l}</div>
        </div>;
      })}
    </div>

    {/* ══ FILTROS ══ */}
    <div style={{display:"flex",gap:8,flexWrap:"wrap",alignItems:"center"}}>
      <div style={{position:"relative",display:"flex",alignItems:"center",flex:isMob?"1 1 100%":"0 1 260px"}}>
        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="#94a3b8" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" style={{position:"absolute",left:11,pointerEvents:"none"}}><circle cx="11" cy="11" r="7"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
        <input value={busca} onChange={function(e){setBusca(e.target.value);}} placeholder="Buscar demanda..."
          onFocus={_demFoco} onBlur={_demBlur}
          style={Object.assign({},_DEM_INP,{padding:"8px 12px 8px 32px",fontSize:12,fontWeight:600})}/>
      </div>
      <select value={fStatus} onChange={function(e){setFStatus(e.target.value);}} style={_selEstilo}>
        <option value="">Todos os status</option>
        {DEM_STATUS.map(function(s){return <option key={s.id} value={s.id}>{s.label}</option>;})}
      </select>
      <select value={fCat} onChange={function(e){setFCat(e.target.value);}} style={_selEstilo}>
        <option value="">Todas as categorias</option>
        {DEM_CATEGORIAS.map(function(c){return <option key={c.id} value={c.id}>{c.label}</option>;})}
      </select>
      <select value={fResp} onChange={function(e){setFResp(e.target.value);}} style={_selEstilo}>
        <option value="">Todos responsáveis</option>
        {_time.map(function(u){return <option key={u.id} value={u.id}>{String(u.name||"").split(" ")[0]}</option>;})}
      </select>
      <select value={fPrazo} onChange={function(e){setFPrazo(e.target.value);}} style={_selEstilo}>
        <option value="">Qualquer prazo</option>
        <option value="atrasado">Atrasadas</option>
        <option value="semana">Próximos 7 dias</option>
        <option value="mes">Próximos 30 dias</option>
        <option value="sem">Sem prazo</option>
      </select>
      {_temFiltro && <button type="button" onClick={_limpar}
        style={{background:"transparent",border:"none",color:"#7c3aed",fontSize:11.5,fontWeight:800,cursor:"pointer",
          fontFamily:_DEM_FF,padding:"8px 4px"}}>Limpar filtros</button>}

      {/* Vista: Lista | Quadro */}
      <div style={{marginLeft:"auto",display:"inline-flex",gap:2,background:"#fff",border:"1px solid #e2e8f0",borderRadius:10,padding:3}}>
        {[
          {id:"lista",  label:"Lista",  ico:<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round"><line x1="8" y1="6" x2="21" y2="6"/><line x1="8" y1="12" x2="21" y2="12"/><line x1="8" y1="18" x2="21" y2="18"/><line x1="3" y1="6" x2="3.01" y2="6"/><line x1="3" y1="12" x2="3.01" y2="12"/><line x1="3" y1="18" x2="3.01" y2="18"/></svg>},
          {id:"quadro", label:"Quadro", ico:<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><rect x="3" y="3" width="5" height="18" rx="1"/><rect x="10" y="3" width="5" height="12" rx="1"/><rect x="17" y="3" width="5" height="15" rx="1"/></svg>},
        ].map(function(v){
          const _on=vista===v.id;
          return <button key={v.id} type="button" onClick={function(){_mudarVista(v.id);}}
            style={{background:_on?"linear-gradient(135deg,#a855f7,#7c3aed)":"transparent",color:_on?"#fff":"#64748b",
              border:"none",borderRadius:8,padding:"7px 13px",fontSize:11.5,fontWeight:_on?800:600,cursor:"pointer",
              fontFamily:_DEM_FF,display:"inline-flex",alignItems:"center",gap:6,transition:"all .12s"}}>
            {v.ico}{v.label}
          </button>;
        })}
      </div>
    </div>

    {/* ══ LISTA ══ */}
    {loading
      ? <div style={{textAlign:"center",color:"#94a3b8",fontSize:13,padding:"40px"}}>Carregando…</div>
      : _lista.length===0
        ? <div style={{background:"#fafbfc",border:"1px dashed #e2e8f0",borderRadius:14,padding:"46px 20px",textAlign:"center"}}>
            <div style={{color:"#334155",fontWeight:700,fontSize:14,marginBottom:5}}>
              {_temFiltro ? "Nada encontrado com esses filtros" : "Nenhuma demanda ainda"}
            </div>
            <div style={{color:"#94a3b8",fontSize:12.5}}>
              {_temFiltro
                ? "Ajuste a busca ou limpe os filtros."
                : (canEdit ? "Crie a primeira demanda e quebre ela em etapas." : "A equipe ainda não cadastrou demandas.")}
            </div>
          </div>
        : (vista==="quadro" && !isMob)
          ? <_DemandasQuadro lista={_lista} canEdit={canEdit} onSalvar={_salvarTarefas}
              onMudarStatus={_mudarStatusDemanda}
              onContexto={canEdit?function(d,x,y){ setCtxMenu({d:d,x:x,y:y}); }:null}
              onAbrir={function(d){ setModal(d); }}/>
          : <div style={{display:"flex",flexDirection:"column",gap:10}}>
            {_lista.map(function(d){
              return <_DemandaCard key={d.id} d={d} isMob={isMob} canEdit={canEdit} corCliente={_cor}
                aberto={!!abertas[d.id]}
                onToggle={function(){ setAbertas(function(p){ const n=Object.assign({},p); n[d.id]=!n[d.id]; return n; }); }}
                onEditar={function(){ setModal(d); }}
                onExcluir={function(){ _excluirDemanda(d); }}
                onContexto={canEdit?function(dd,x,y){ setCtxMenu({d:dd,x:x,y:y}); }:null}
                onSalvar={_salvarTarefas} onPortal={_togglePortal}/>;
            })}
          </div>
    }

    {/* ══ HISTÓRICO DE ENTREGAS ══ */}
    <_DemHistorico lista={_concluidas} canEdit={canEdit}
      onAbrir={function(d){ setModal(d); }}/>

    {/* ══ LIXEIRA (30 dias) ══ */}
    {canEdit&&<_DemLixeira lista={lixeira} onRestaurar={_restaurarDemanda} onExcluirDef={_excluirDefinitivo}/>}

    {/* ══ HISTORICO DE MARCOS ══
        Os marcos continuam existindo em client_milestones — alimentam o
        calendario, a agenda de eventos e o dashboard. Ficam aqui embaixo,
        recolhidos, pra nao competir com as demandas. */}
    <div style={{background:"#fff",border:"1px solid #eef0f3",borderRadius:14,overflow:"hidden"}}>
      <div onClick={function(){setVerMarcos(!verMarcos);}}
        style={{padding:"13px 17px",display:"flex",alignItems:"center",gap:11,cursor:"pointer",
          background:verMarcos?"#fafbfc":"#fff",transition:"background .12s"}}>
        <div style={{width:30,height:30,borderRadius:9,background:_cor+"12",border:"1px solid "+_cor+"2e",
          display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
          <Ico n="flame" size={14} color={_cor}/>
        </div>
        <div style={{flex:1,minWidth:0}}>
          <div style={{color:"#0f172a",fontWeight:800,fontSize:13,letterSpacing:-.2}}>Checkpoints do projeto</div>
          <div style={{color:"#94a3b8",fontSize:11,marginTop:1,fontWeight:600}}>Acontecimentos e conquistas — aparecem também no calendário</div>
        </div>
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#94a3b8" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round"
          style={{flexShrink:0,transition:"transform .18s",transform:verMarcos?"rotate(180deg)":"rotate(0deg)"}}>
          <polyline points="6 9 12 15 18 9"/>
        </svg>
      </div>
      {verMarcos && <div style={{borderTop:"1px solid #f1f5f9",padding:"15px 17px 17px"}}>
        {typeof CMarcos==="function"
          ? <CMarcos cl={cl} canEdit={canEdit} selUnit={selUnit}/>
          : <div style={{color:"#94a3b8",fontSize:12.5}}>Checkpoints indisponíveis.</div>}
      </div>}
    </div>

    {/* Modal de demanda aberta (clique no quadro / no histórico) */}
    {quadroAberto&&(function(){
      const _d=demandas.find(function(x){return x.id===quadroAberto;});
      if(!_d) return null;
      return <div onClick={function(){setQuadroAberto(null);}}
        style={{position:"fixed",inset:0,zIndex:420,background:"rgba(15,23,42,.55)",backdropFilter:"blur(5px)",
          display:"flex",alignItems:"flex-start",justifyContent:"center",padding:"56px 16px 30px",overflowY:"auto"}}>
        <div onClick={function(e){e.stopPropagation();}} style={{width:"min(860px,100%)"}}>
          <_DemandaCard d={_d} isMob={isMob} canEdit={canEdit} corCliente={_cor}
            aberto={true}
            onToggle={function(){ setQuadroAberto(null); }}
            onEditar={function(){ setModal(_d); setQuadroAberto(null); }}
            onExcluir={function(){ setQuadroAberto(null); _excluirDemanda(_d); }}
            onSalvar={_salvarTarefas} onPortal={_togglePortal}/>
        </div>
      </div>;
    })()}

    <_DemCtxMenu ctx={ctxMenu} onFechar={function(){setCtxMenu(null);}}
      onAbrir={function(d){ setModal(d); }} onExcluir={_excluirDemanda}/>

    {modal && <_DemandaModal inicial={modal} isMob={isMob} onPortal={_togglePortal}
      onSalvar={_salvarDemanda} onFechar={function(){setModal(null);}}/>}
  </div>;
}


/* ═══════════════════════════════════════════════════════════════════════
   CENTRAL DE DEMANDAS — Estrategia > Demandas
   ───────────────────────────────────────────────────────────────────────
   Visao de comando de TODAS as demandas de TODOS os clientes (client_demandas).
   Fora daqui: arte/video (Linha de producao) e trafego (Gestao de midia).
   Reusa _DemandaCard/_DemandaDetalhe com o badge do cliente ligado.
═══════════════════════════════════════════════════════════════════════ */
function CDemandasCentral({isMob, somenteCategorias, titulo, subtitulo, canEditProp, embutida}){
  const sb=(typeof window!=="undefined")?window._sb:null;
  const _mob=(typeof _pxMob==="function")?_pxMob():!!isMob;

  const [demandas,setDemandas]=useState([]);
  const [loading,setLoading]=useState(true);
  const [abertas,setAbertas]=useState({});
  const [quadroAberto,setQuadroAberto]=useState(null); // demanda aberta em modal (clique no quadro)
  const [lixeira,setLixeira]=useState([]);             // soft-deletadas (30 dias)
  const [ctxMenu,setCtxMenu]=useState(null);           // {d,x,y} — botão direito no card
  const [modal,setModal]=useState(null);
  const [busca,setBusca]=useState("");
  const [fCliente,setFCliente]=useState("");
  const [fStatus,setFStatus]=useState("");
  const [fResp,setFResp]=useState("");
  const [fCat,setFCat]=useState("");
  const [fPrazo,setFPrazo]=useState("");

  // Central e SO dos socios (a rota ja bloqueia; aqui e cinto de seguranca).
  // Na Gestão de mídia, canEditProp libera também o gestor de mídia.
  const canEdit=(typeof canEditProp==="boolean")
    ? canEditProp
    : ((typeof CURRENT_USER!=="undefined"&&CURRENT_USER)?CURRENT_USER.level===1:false);
  // Escopo: com somenteCategorias, só elas (Gestão de mídia); sem, a central
  // esconde as categorias de mídia (tráfego/campanha vivem lá).
  const _soCats=(Array.isArray(somenteCategorias)&&somenteCategorias.length)?somenteCategorias:null;
  const _noEscopo=function(d){
    const c=d.categoria||"outros";
    return _soCats ? _soCats.indexOf(c)>=0 : _DEM_CATS_MIDIA.indexOf(c)<0;
  };

  // Vista da central: quadro por status e o DEFAULT — e a leitura de "onde cada
  // coisa esta" que uma central de comando pede. Lista fica pra varredura fina.
  const _VISTA_KEY="pixels-demandas-central-vista";
  const [vista,setVista]=useState(function(){
    try{ return localStorage.getItem(_VISTA_KEY)||"quadro"; }catch(_){ return "quadro"; }
  });
  const _mudarVista=function(v){ setVista(v); try{ localStorage.setItem(_VISTA_KEY,v); }catch(_){} };

  const _carregar=async function(){
    if(!sb){ setLoading(false); return; }
    try{
      const r=await sb.from("client_demandas").select("*")
        .order("updated_at",{ascending:false});
      const _rows=(r&&r.data)||[];
      setDemandas(_rows.filter(function(x){return !x.deleted_at;}));
      setLixeira(_rows.filter(function(x){return !!x.deleted_at;}));
      _demPurgarLixeira(sb);
    }catch(e){ console.warn("[demandas central] load:", (e&&e.message)||e); }
    setLoading(false);
  };

  useEffect(function(){
    let alive=true;
    _carregar();
    // Garante que os clientes dinamicos estao no registro (badges/filtro)
    try{
      if(typeof window.loadDynamicClientsFromSupabase==="function")
        window.loadDynamicClientsFromSupabase().catch(function(){});
    }catch(_){}
    if(!sb) return function(){alive=false;};
    let ch=null;
    try{
      ch=sb.channel("demandas-central-rt")
        .on("postgres_changes",{event:"*",schema:"public",table:"client_demandas"},
          function(){ if(alive) _carregar(); })
        .subscribe();
    }catch(_){}
    return function(){ alive=false; try{ if(ch) sb.removeChannel(ch); }catch(_){} };
  },[]);

  const _salvarTarefas=async function(d){
    setDemandas(function(prev){
      return prev.map(function(x){ return x.id===d.id ? Object.assign({},x,{tarefas:d.tarefas}) : x; });
    });
    if(!sb) return;
    try{
      await sb.from("client_demandas")
        .update({tarefas:d.tarefas, updated_at:new Date().toISOString()})
        .eq("id",d.id);
    }catch(e){
      if(typeof pixelsToast!=="undefined") pixelsToast.error("Erro salvando tarefas.",4000);
      _carregar();
    }
  };

  // Autosave campo a campo (edição inline na ficha da demanda)
  const _patchDemanda=async function(d,patch){
    setDemandas(function(prev){ return prev.map(function(x){ return x.id===d.id?Object.assign({},x,patch):x; }); });
    if(!sb) return;
    try{
      const r=await sb.from("client_demandas")
        .update(Object.assign({},patch,{updated_at:new Date().toISOString()})).eq("id",d.id);
      if(r&&r.error) throw r.error;
    }catch(e){
      if(typeof pixelsToast!=="undefined") pixelsToast.error("Erro salvando alteração.",4000);
      _carregar();
    }
  };
  const _salvarDemanda=async function(dados){
    if(!sb) return;
    let _cid=dados.client_id || fCliente;
    let _unidNova="";
    if(String(_cid||"").indexOf("bioter::")===0){ _unidNova=String(_cid).slice(8); _cid="bioter"; }
    if(!dados.id && !_cid){
      if(typeof pixelsToast!=="undefined") pixelsToast.warning("Escolhe o cliente da demanda.");
      return;
    }
    const _payload={
      titulo:String(dados.titulo||"").trim(),
      categoria:dados.categoria||"outros",
      descricao:dados.descricao||"",
      status:dados.status||"nao_iniciada",
      prioridade:dados.prioridade||"normal",
      responsavel:dados.responsavel||"",
      data_inicio:dados.data_inicio||null,
      prazo:dados.prazo||null,
      hora:dados.hora||null,
      cidade:dados.cidade||null,
      resumo:dados.resumo||null,
      updated_at:new Date().toISOString(),
    };
    if(Array.isArray(dados.tarefas)) _payload.tarefas=dados.tarefas;
    try{
      if(dados.id){
        // Se o select de cliente veio no form, permite MOVER a demanda de cliente/unidade
        if(_cid){ _payload.client_id=_cid; _payload.unidade=_unidNova; }
        const r=await sb.from("client_demandas").update(_payload).eq("id",dados.id);
        if(r&&r.error) throw r.error;
      }else{
        _payload.client_id=_cid;
        _payload.unidade=_unidNova;
        _payload.tarefas=Array.isArray(dados.tarefas)?dados.tarefas:[];
        _payload.created_by=(typeof CURRENT_USER!=="undefined"&&CURRENT_USER)?CURRENT_USER.name:"";
        const r=await sb.from("client_demandas").insert(_payload);
        if(r&&r.error) throw r.error;
        if(typeof pixelsToast!=="undefined") pixelsToast.success("Demanda criada.");
      }
      setModal(null);
      _carregar();
    }catch(e){
      if(typeof pixelsToast!=="undefined") pixelsToast.error("Erro salvando: "+((e&&e.message)||""),5500);
    }
  };

  const _mudarStatusDemanda=async function(d, novo){
    if(!d || d.status===novo) return;
    setDemandas(function(prev){
      return prev.map(function(x){ return x.id===d.id ? Object.assign({},x,{status:novo}) : x; });
    });
    if(!sb) return;
    try{
      await sb.from("client_demandas")
        .update({status:novo, updated_at:new Date().toISOString()})
        .eq("id",d.id);
    }catch(e){
      if(typeof pixelsToast!=="undefined") pixelsToast.error("Erro mudando status.",4000);
      _carregar();
    }
  };


  // Envia/remove a demanda do portal do cliente. Demanda que veio do portal
  // (created_by "portal_...") fica sempre sincronizada — nao passa por aqui.
  const _togglePortal=async function(d){
    if(!d||_demDoPortal(d)) return;
    const _novo=!d.portal_visivel;
    setDemandas(function(prev){
      return prev.map(function(x){ return x.id===d.id ? Object.assign({},x,{portal_visivel:_novo}) : x; });
    });
    if(!sb) return;
    try{
      const r=await sb.from("client_demandas")
        .update({portal_visivel:_novo, updated_at:new Date().toISOString()})
        .eq("id",d.id);
      if(r&&r.error) throw r.error;
      if(typeof pixelsToast!=="undefined")
        pixelsToast.success(_novo?"Demanda liberada no portal do cliente.":"Demanda removida do portal do cliente.");
    }catch(e){
      if(typeof pixelsToast!=="undefined") pixelsToast.error("Erro atualizando portal.",4000);
      _carregar();
    }
  };

  const _excluirDemanda=async function(d){
    if(typeof pxExclusaoBloqueada==="function"&&pxExclusaoBloqueada(CURRENT_USER)){if(typeof pixelsToast!=="undefined")pixelsToast.warning("Você não tem permissão para excluir.");return;}
    let ok=true;
    if(typeof pixelsConfirm==="function"){
      ok=await pixelsConfirm({title:"Mandar pra Lixeira?",message:'"'+(d.titulo||"")+'" fica '+_DEM_LIXEIRA_DIAS+' dias na Lixeira (dá pra restaurar) e depois some de vez.',danger:true});
    }
    if(!ok) return;
    try{
      const r=await sb.from("client_demandas")
        .update({deleted_at:new Date().toISOString(),updated_at:new Date().toISOString()}).eq("id",d.id);
      if(r&&r.error) throw r.error;
      if(typeof pixelsToast!=="undefined") pixelsToast.success("Foi pra Lixeira — "+_DEM_LIXEIRA_DIAS+" dias pra restaurar.");
      setQuadroAberto(null);
      _carregar();
    }catch(e){
      if(typeof pixelsToast!=="undefined") pixelsToast.error("Erro excluindo.",4000);
    }
  };
  const _restaurarDemanda=async function(d){
    try{
      const r=await sb.from("client_demandas")
        .update({deleted_at:null,updated_at:new Date().toISOString()}).eq("id",d.id);
      if(r&&r.error) throw r.error;
      if(typeof pixelsToast!=="undefined") pixelsToast.success("Demanda restaurada.");
      _carregar();
    }catch(e){ if(typeof pixelsToast!=="undefined") pixelsToast.error("Erro restaurando.",4000); }
  };
  const _excluirDefinitivo=async function(d){
    if(typeof pxExclusaoBloqueada==="function"&&pxExclusaoBloqueada(CURRENT_USER)){if(typeof pixelsToast!=="undefined")pixelsToast.warning("Você não tem permissão para excluir.");return;}
    let ok=true;
    if(typeof pixelsConfirm==="function"){
      ok=await pixelsConfirm({title:"Excluir DE VEZ?",message:'"'+(d.titulo||"")+'" será apagada agora, sem volta.',danger:true});
    }
    if(!ok) return;
    try{
      await sb.from("client_demandas").delete().eq("id",d.id);
      if(typeof pixelsToast!=="undefined") pixelsToast.success("Excluída definitivamente.");
      _carregar();
    }catch(e){ if(typeof pixelsToast!=="undefined") pixelsToast.error("Erro excluindo.",4000); }
  };

  const _clientes=(typeof CLIENTS!=="undefined"?CLIENTS:[])
    .filter(function(c){ return c && String(c.name||"").trim(); })
    .slice()
    .sort(function(a,b){ return String(a.name||"").localeCompare(String(b.name||""),"pt-BR",{sensitivity:"base"}); });
  // Pro modal de criação: Bioter abre em Grupo + cada unidade (valor "bioter::<unidade>")
  const _clientesOpcoes=(function(){
    const out=[];
    _clientes.forEach(function(c){
      if(c.id==="bioter"){
        out.push({id:"bioter",name:"Grupo Bioter (todas as unidades)"});
        const us=(typeof BIOTER_GROUP_UNITS!=="undefined"&&Array.isArray(BIOTER_GROUP_UNITS))?BIOTER_GROUP_UNITS:[];
        us.forEach(function(u){
          out.push({id:"bioter::"+String(u.id||"").replace("bioter_",""),name:"   · "+u.name});
        });
      }else out.push({id:c.id,name:c.name});
    });
    return out;
  })();

  /* ── Resumo global ── */
  const _escopo=demandas.filter(_noEscopo);
  const _resumo=(function(){
    const r={total:_escopo.length, andamento:0, aguardando:0, concluidas:0, atrasadas:0};
    _escopo.forEach(function(d){
      if(d.status==="andamento")  r.andamento++;
      if(d.status==="aguardando") r.aguardando++;
      if(d.status==="concluida")  r.concluidas++;
      const _dd=_demDias(d.prazo);
      if(d.status!=="concluida" && _dd!==null && _dd<0) r.atrasadas++;
    });
    return r;
  })();

  /* ── Filtros ── */
  const _q=String(busca||"").toLowerCase().trim();
  const _lista=_escopo.filter(function(d){
    if(fCliente && d.client_id!==fCliente) return false;
    if(_q){
      const _cli=_clientes.find(function(c){return c.id===d.client_id;});
      const _alvo=(String(d.titulo||"")+" "+String(d.descricao||"")+" "+((_cli&&_cli.name)||"")).toLowerCase();
      if(_alvo.indexOf(_q)<0) return false;
    }
    if(fStatus && d.status!==fStatus) return false;
    if(fCat && d.categoria!==fCat) return false;
    if(fResp){
      const _naTarefa=(Array.isArray(d.tarefas)?d.tarefas:[]).some(function(t){return t&&t.resp===fResp;});
      if(d.responsavel!==fResp && !_naTarefa) return false;
    }
    if(fPrazo){
      const _dd=_demDias(d.prazo);
      if(fPrazo==="atrasado" && !(d.status!=="concluida" && _dd!==null && _dd<0)) return false;
      if(fPrazo==="semana"   && !(_dd!==null && _dd>=0 && _dd<=7))  return false;
      if(fPrazo==="mes"      && !(_dd!==null && _dd>=0 && _dd<=30)) return false;
      if(fPrazo==="sem"      && d.prazo) return false;
    }
    return true;
  });

  const _temFiltro=!!(_q||fCliente||fStatus||fCat||fResp||fPrazo);
  const _ativas=_lista.filter(function(d){ return d.status!=="concluida"; });
  const _concluidas=_lista.filter(function(d){ return d.status==="concluida"; })
    .slice().sort(function(a,b){ return String(_demConcluidaEm(b)).localeCompare(String(_demConcluidaEm(a))); });
  const _limpar=function(){ setBusca(""); setFCliente(""); setFStatus(""); setFCat(""); setFResp(""); setFPrazo(""); };
  const _time=(typeof TEAM!=="undefined")?TEAM:[];
  const _selEstilo={background:"#fff",border:"1px solid #e2e8f0",borderRadius:9,padding:"8px 11px",
    fontSize:11.5,fontWeight:700,color:"#475569",outline:"none",fontFamily:_DEM_FF,cursor:"pointer"};

  return <div style={{display:"flex",flexDirection:"column",gap:14,fontFamily:_DEM_FF,
    padding:embutida?0:(_mob?"14px 12px":"22px 26px"),
    maxWidth:embutida?"none":(vista==="quadro"?1560:1280),margin:"0 auto",width:"100%",boxSizing:"border-box"}}>

    {/* Header */}
    <div style={{display:"flex",alignItems:"flex-start",justifyContent:"space-between",gap:14,flexWrap:"wrap"}}>
      <div style={{minWidth:0}}>
        <div style={{fontSize:19,fontWeight:800,color:"#0f172a",letterSpacing:-.35}}>{titulo||"Demandas"}</div>
        <div style={{fontSize:13,color:"#64748b",marginTop:3}}>{subtitulo||"Central de comando — projetos e entregas de todos os clientes. Arte e vídeo vivem na Linha de produção; tráfego e campanhas, na Gestão de mídia."}</div>
      </div>
      {canEdit && <button type="button" onClick={function(){setModal({});}}
        style={{background:"linear-gradient(135deg,#a855f7,#7c3aed)",color:"#fff",border:"none",borderRadius:10,
          padding:"10px 17px",fontSize:12.5,fontWeight:800,cursor:"pointer",fontFamily:_DEM_FF,
          display:"inline-flex",alignItems:"center",gap:7,boxShadow:"0 6px 16px rgba(124,58,237,.30)",flexShrink:0}}>
        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
        Nova demanda
      </button>}
    </div>

    {/* Resumo */}
    <div style={{display:"grid",gridTemplateColumns:_mob?"repeat(2,1fr)":"repeat(5,minmax(0,1fr))",gap:9}}>
      {[
        {l:"Demandas",     v:_resumo.total,      c:"#0f172a"},
        {l:"Em andamento", v:_resumo.andamento,  c:"#d97706"},
        {l:"Aguardando",   v:_resumo.aguardando, c:"#db2777"},
        {l:"Concluídas",   v:_resumo.concluidas, c:"#15803d"},
        {l:"Atrasadas",    v:_resumo.atrasadas,  c:"#dc2626"},
      ].map(function(x,i){
        const _zero=!x.v;
        return <div key={i} style={{background:"#fff",border:"1px solid #eef0f3",borderRadius:11,padding:"11px 13px",boxShadow:"0 1px 2px rgba(15,23,42,.03)"}}>
          <div style={{color:_zero?"#cbd5e1":x.c,fontSize:21,fontWeight:800,letterSpacing:-.7,lineHeight:1,fontFeatureSettings:"'tnum'"}}>{x.v}</div>
          <div style={{color:"#94a3b8",fontSize:10,fontWeight:700,textTransform:"uppercase",letterSpacing:.5,marginTop:4}}>{x.l}</div>
        </div>;
      })}
    </div>

    {/* Filtros */}
    <div style={{display:"flex",gap:8,flexWrap:"wrap",alignItems:"center"}}>
      <div style={{position:"relative",display:"flex",alignItems:"center",flex:_mob?"1 1 100%":"0 1 240px"}}>
        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="#94a3b8" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" style={{position:"absolute",left:11,pointerEvents:"none"}}><circle cx="11" cy="11" r="7"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
        <input value={busca} onChange={function(e){setBusca(e.target.value);}} placeholder="Buscar demanda ou cliente..."
          onFocus={_demFoco} onBlur={_demBlur}
          style={Object.assign({},_DEM_INP,{padding:"8px 12px 8px 32px",fontSize:12,fontWeight:600})}/>
      </div>
      <select value={fCliente} onChange={function(e){setFCliente(e.target.value);}} style={Object.assign({},_selEstilo,fCliente?{borderColor:"#a855f7",color:"#7c3aed"}:{})}>
        <option value="">Todos os clientes</option>
        {_clientes.map(function(c){return <option key={c.id} value={c.id}>{c.name}</option>;})}
      </select>
      <select value={fStatus} onChange={function(e){setFStatus(e.target.value);}} style={_selEstilo}>
        <option value="">Todos os status</option>
        {DEM_STATUS.map(function(st){return <option key={st.id} value={st.id}>{st.label}</option>;})}
      </select>
      <select value={fCat} onChange={function(e){setFCat(e.target.value);}} style={_selEstilo}>
        <option value="">Todas as categorias</option>
        {DEM_CATEGORIAS.filter(function(c){return _soCats?_soCats.indexOf(c.id)>=0:_DEM_CATS_MIDIA.indexOf(c.id)<0;})
          .map(function(c){return <option key={c.id} value={c.id}>{c.label}</option>;})}
      </select>
      <select value={fResp} onChange={function(e){setFResp(e.target.value);}} style={_selEstilo}>
        <option value="">Todos responsáveis</option>
        {_time.map(function(u){return <option key={u.id} value={u.id}>{String(u.name||"").split(" ")[0]}</option>;})}
      </select>
      <select value={fPrazo} onChange={function(e){setFPrazo(e.target.value);}} style={_selEstilo}>
        <option value="">Qualquer prazo</option>
        <option value="atrasado">Atrasadas</option>
        <option value="semana">Próximos 7 dias</option>
        <option value="mes">Próximos 30 dias</option>
        <option value="sem">Sem prazo</option>
      </select>
      {_temFiltro && <button type="button" onClick={_limpar}
        style={{background:"transparent",border:"none",color:"#7c3aed",fontSize:11.5,fontWeight:800,cursor:"pointer",fontFamily:_DEM_FF,padding:"8px 4px"}}>Limpar filtros</button>}

      <div style={{marginLeft:"auto",display:"inline-flex",gap:2,background:"#fff",border:"1px solid #e2e8f0",borderRadius:10,padding:3}}>
        {[
          {id:"quadro", label:"Quadro", ico:<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><rect x="3" y="3" width="5" height="18" rx="1"/><rect x="10" y="3" width="5" height="12" rx="1"/><rect x="17" y="3" width="5" height="15" rx="1"/></svg>},
          {id:"lista",  label:"Lista",  ico:<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round"><line x1="8" y1="6" x2="21" y2="6"/><line x1="8" y1="12" x2="21" y2="12"/><line x1="8" y1="18" x2="21" y2="18"/><line x1="3" y1="6" x2="3.01" y2="6"/><line x1="3" y1="12" x2="3.01" y2="12"/><line x1="3" y1="18" x2="3.01" y2="18"/></svg>},
        ].map(function(v){
          const _on=vista===v.id;
          return <button key={v.id} type="button" onClick={function(){_mudarVista(v.id);}}
            style={{background:_on?"linear-gradient(135deg,#a855f7,#7c3aed)":"transparent",color:_on?"#fff":"#64748b",
              border:"none",borderRadius:8,padding:"7px 13px",fontSize:11.5,fontWeight:_on?800:600,cursor:"pointer",
              fontFamily:_DEM_FF,display:"inline-flex",alignItems:"center",gap:6,transition:"all .12s"}}>
            {v.ico}{v.label}
          </button>;
        })}
      </div>
    </div>

    {/* Lista */}
    {loading
      ? <div style={{textAlign:"center",color:"#94a3b8",fontSize:13,padding:"40px"}}>Carregando…</div>
      : _lista.length===0
        ? <div style={{background:"#fafbfc",border:"1px dashed #e2e8f0",borderRadius:14,padding:"46px 20px",textAlign:"center"}}>
            <div style={{color:"#334155",fontWeight:700,fontSize:14,marginBottom:5}}>
              {_temFiltro?"Nada encontrado com esses filtros":"Nenhuma demanda ainda"}
            </div>
            <div style={{color:"#94a3b8",fontSize:12.5}}>
              {_temFiltro?"Ajuste a busca ou limpe os filtros.":"As demandas criadas nos clientes (e as solicitadas pelo portal) aparecem todas aqui."}
            </div>
          </div>
        : (vista==="quadro" && !_mob)
          ? <_DemandasQuadro lista={_lista} canEdit={canEdit} mostrarCliente={true} onSalvar={_salvarTarefas}
              onMudarStatus={_mudarStatusDemanda}
              onContexto={canEdit?function(d,x,y){ setCtxMenu({d:d,x:x,y:y}); }:null}
              onAbrir={function(d){ setModal(d); }}/>
          : <div style={{display:"flex",flexDirection:"column",gap:10}}>
            {_lista.map(function(d){
              return <_DemandaCard key={d.id} d={d} isMob={_mob} canEdit={canEdit} mostrarCliente={true}
                aberto={!!abertas[d.id]}
                onToggle={function(){ setAbertas(function(p){ const n=Object.assign({},p); n[d.id]=!n[d.id]; return n; }); }}
                onEditar={function(){ setModal(d); }}
                onExcluir={function(){ _excluirDemanda(d); }}
                onContexto={canEdit?function(dd,x,y){ setCtxMenu({d:dd,x:x,y:y}); }:null}
                onSalvar={_salvarTarefas} onPortal={_togglePortal}/>;
            })}
          </div>
    }

    {/* ══ HISTÓRICO DE ENTREGAS ══ */}
    <_DemHistorico lista={_concluidas} canEdit={canEdit} mostrarCliente={true}
      onAbrir={function(d){ setModal(d); }}/>

    {/* ══ LIXEIRA (30 dias) ══ */}
    {canEdit&&<_DemLixeira lista={lixeira} mostrarCliente={true} onRestaurar={_restaurarDemanda} onExcluirDef={_excluirDefinitivo}/>}

    {/* Modal de demanda aberta (clique no quadro / no histórico) */}
    {quadroAberto&&(function(){
      const _d=demandas.find(function(x){return x.id===quadroAberto;});
      if(!_d) return null;
      return <div onClick={function(){setQuadroAberto(null);}}
        style={{position:"fixed",inset:0,zIndex:420,background:"rgba(15,23,42,.55)",backdropFilter:"blur(5px)",
          display:"flex",alignItems:"flex-start",justifyContent:"center",padding:"56px 16px 30px",overflowY:"auto"}}>
        <div onClick={function(e){e.stopPropagation();}} style={{width:"min(860px,100%)"}}>
          <_DemandaCard d={_d} isMob={_mob} canEdit={canEdit} mostrarCliente={true}
            aberto={true}
            onToggle={function(){ setQuadroAberto(null); }}
            onEditar={function(){ setModal(_d); setQuadroAberto(null); }}
            onExcluir={function(){ setQuadroAberto(null); _excluirDemanda(_d); }}
            onSalvar={_salvarTarefas} onPortal={_togglePortal}/>
        </div>
      </div>;
    })()}

    <_DemCtxMenu ctx={ctxMenu} onFechar={function(){setCtxMenu(null);}}
      onAbrir={function(d){ setModal(d); }} onExcluir={_excluirDemanda}/>

    {modal && <_DemandaModal inicial={modal} isMob={_mob} onPortal={_togglePortal}
      clientes={_clientesOpcoes}
      cats={_soCats} semCats={_soCats?null:_DEM_CATS_MIDIA}
      onSalvar={_salvarDemanda} onFechar={function(){setModal(null);}}/>}
  </div>;
}

/* ═══════════════════════════════════════════════════════════════════════
   29_conquistas.jsx — ÁLBUM DE CONQUISTAS (Portal do Cliente)
   ───────────────────────────────────────────────────────────────────────
   Cartas colecionáveis estilo álbum de figurinhas / FIFA. Cada conquista
   é uma carta: bloqueada (a caminho) ou desbloqueada (conquistamos!).
   Tudo escrito em "nós" — fizemos, alcançamos, vendemos JUNTOS.

   · Tabela: client_conquistas (agency ALL, cliente só leitura via RLS)
   · Só os SÓCIOS editam — e só pelo lado da agência; no portal do
     cliente não aparece NENHUM controle de edição.
   · Carta recém-desbloqueada aparece VIRADA (verso brilhando); o clique
     revela com flip + confete + som (_pxSomConfete, o mesmo estouro das
     cartinhas de bônus do comercial). "Visto" fica no localStorage.
   · Bioter: cartas moram em client_id="bioter", campo `unidade` segmenta
     (grupo aparece em todas as unidades) — mesmo padrão de demandas/checkpoints.
═══════════════════════════════════════════════════════════════════════ */

const _CQ_FF="'Inter',system-ui,-apple-system,sans-serif";
const _CQ_CUT="polygon(22px 0, 100% 0, 100% calc(100% - 22px), calc(100% - 22px) 100%, 0 100%, 0 22px)";
const _CQ_CUT_IN="polygon(21px 0, 100% 0, 100% calc(100% - 21px), calc(100% - 21px) 100%, 0 100%, 0 21px)";
const _CQ_HEX="polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%)";
const _CQ_ICONES=["award","star","target","trendingUp","dollar","users","heart","flame","zap","megaphone","flag","sparkles"];
const _CQ_OURO="#f0b429", _CQ_OURO2="#ffd868";

function _cqBR(d){
  if(!d) return "";
  const p=String(d).slice(0,10).split("-");
  return p.length===3?(p[2]+"/"+p[1]+"/"+p[0]):"";
}
function _cqVistasKey(clId){ return "pixels-conq-vistas-"+clId; }
function _cqLerVistas(clId){
  try{ const v=JSON.parse(localStorage.getItem(_cqVistasKey(clId))||"[]"); return Array.isArray(v)?v:[]; }catch(_){ return []; }
}
function _cqDesmarcarVista(clId,id){
  try{ const l=_cqLerVistas(clId).filter(function(x){return x!==id;}); localStorage.setItem(_cqVistasKey(clId),JSON.stringify(l)); }catch(_){}
}
function _cqMarcarVista(clId,id){
  try{
    const v=_cqLerVistas(clId);
    if(v.indexOf(id)<0){ v.push(id); localStorage.setItem(_cqVistasKey(clId),JSON.stringify(v)); }
  }catch(_){}
}

/* ── Modal de edição (só sócios, só na agência) ── */
function _CqModal({inicial, isMob, onSalvar, onFechar, destino}){
  const _e=inicial||{};
  const [titulo,setTitulo]=useState(_e.titulo||"");
  const [descricao,setDescricao]=useState(_e.descricao||"");
  const [icone,setIcone]=useState(_e.icone||"award");
  const [tema,setTema]=useState(_e.tema||"roxo");
  const [desb,setDesb]=useState(!!_e.desbloqueada);
  const [dataDesb,setDataDesb]=useState(_e.unlocked_at||new Date().toISOString().slice(0,10));
  const [salvando,setSalvando]=useState(false);
  const _inp={width:"100%",background:"#fff",border:"1px solid #e2e8f0",borderRadius:9,padding:"9px 12px",
    fontSize:13,color:"#0f172a",outline:"none",fontFamily:_CQ_FF,boxSizing:"border-box"};
  const _lbl={color:"#94a3b8",fontSize:10,fontWeight:800,textTransform:"uppercase",letterSpacing:.6,marginBottom:5};
  const _salvar=async function(){
    if(!String(titulo||"").trim()){ if(typeof pixelsToast!=="undefined") pixelsToast.warning("Dá um título pra conquista."); return; }
    setSalvando(true);
    await onSalvar({id:_e.id, titulo:titulo.trim(), descricao:descricao.trim(), icone:icone, tema:tema,
      desbloqueada:desb, unlocked_at:desb?(dataDesb||new Date().toISOString().slice(0,10)):null});
    setSalvando(false);
  };
  return <div onMouseDown={function(e){ if(e.target===e.currentTarget) onFechar(); }} style={{position:"fixed",inset:0,zIndex:430,background:"rgba(15,23,42,.58)",backdropFilter:"blur(6px)",
    display:"flex",alignItems:"flex-start",justifyContent:"center",padding:"70px 16px 30px",overflowY:"auto",fontFamily:_CQ_FF}}>
    <div onMouseDown={function(e){e.stopPropagation();}}
      style={{background:"#fff",borderRadius:16,width:"min(560px,100%)",padding:isMob?"20px 18px":"24px 26px",
        boxShadow:"0 32px 80px rgba(15,23,42,.32)",display:"flex",flexDirection:"column",gap:14}}>
      <div>
        <div style={{fontSize:17,fontWeight:800,color:"#0f172a",letterSpacing:-.3}}>{_e.id?"Editar conquista":"Nova conquista"}</div>
        <div style={{fontSize:12,color:"#94a3b8",marginTop:2}}>Escreve em "nós": Alcançamos, Vendemos, Conquistamos — é uma vitória do time com o cliente.</div>
        {destino&&<div style={{marginTop:7,display:"inline-flex",alignItems:"center",gap:6,background:"#f5f3ff",border:"1px solid #ddd6fe",
          borderRadius:99,padding:"3px 11px",fontSize:10.5,fontWeight:800,color:"#7c3aed"}}>
          <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0118 0z"/><circle cx="12" cy="10" r="3"/></svg>
          Vai pro álbum de: {destino}
        </div>}
      </div>
      <div>
        <div style={_lbl}>Título</div>
        <input autoFocus value={titulo} onChange={function(e){setTitulo(e.target.value);}}
          placeholder='Ex: Alcançamos 1.000 seguidores' style={_inp}/>
      </div>
      <div>
        <div style={_lbl}>Descrição (opcional)</div>
        <textarea value={descricao} onChange={function(e){setDescricao(e.target.value);}} rows={2}
          placeholder='Ex: Primeiro grande marco da comunidade que estamos construindo juntos.'
          style={Object.assign({},_inp,{resize:"vertical",lineHeight:1.5})}/>
      </div>
      <div style={{display:"grid",gridTemplateColumns:isMob?"1fr":"1fr 180px",gap:12}}>
        <div>
          <div style={_lbl}>Ícone</div>
          <div style={{display:"flex",flexWrap:"wrap",gap:6}}>
            {_CQ_ICONES.map(function(ic){
              const _on=icone===ic;
              return <button key={ic} type="button" onClick={function(){setIcone(ic);}}
                style={{width:36,height:36,borderRadius:9,cursor:"pointer",display:"inline-flex",alignItems:"center",justifyContent:"center",
                  background:_on?"linear-gradient(135deg,#a855f7,#7c3aed)":"#f8fafc",border:_on?"1px solid #7c3aed":"1px solid #e2e8f0"}}>
                {typeof Ico==="function"&&<Ico n={ic} size={16} color={_on?"#fff":"#64748b"}/>}
              </button>;
            })}
          </div>
        </div>
        <div>
          <div style={_lbl}>Tema da carta</div>
          <div style={{display:"flex",gap:6}}>
            {[{id:"roxo",l:"Roxa",bg:"linear-gradient(135deg,#43197e,#180730)"},{id:"ouro",l:"Dourada",bg:"linear-gradient(135deg,#6b4204,#241501)"}].map(function(t){
              const _on=tema===t.id;
              return <button key={t.id} type="button" onClick={function(){setTema(t.id);}}
                style={{flex:1,borderRadius:9,cursor:"pointer",padding:"8px 6px",background:t.bg,color:"#fff",fontSize:11.5,fontWeight:800,
                  fontFamily:_CQ_FF,border:_on?"2px solid "+_CQ_OURO:"2px solid transparent",opacity:_on?1:.55}}>{t.l}</button>;
            })}
          </div>
        </div>
      </div>
      <div style={{background:"#fafbfc",border:"1px solid #eef0f3",borderRadius:11,padding:"11px 13px",
        display:"flex",alignItems:"center",gap:12,flexWrap:"wrap"}}>
        <label style={{display:"inline-flex",alignItems:"center",gap:8,cursor:"pointer",fontSize:12.5,fontWeight:700,color:"#0f172a"}}>
          <input type="checkbox" checked={desb} onChange={function(e){setDesb(e.target.checked);}} style={{width:15,height:15,accentColor:"#7c3aed",cursor:"pointer"}}/>
          Já conquistamos!
        </label>
        {desb&&<span style={{display:"inline-flex",alignItems:"center",gap:7}}>
          <span style={{color:"#94a3b8",fontSize:11,fontWeight:700}}>em</span>
          <input type="date" value={dataDesb} onChange={function(e){setDataDesb(e.target.value);}}
            style={Object.assign({},_inp,{width:"auto",padding:"6px 9px",fontSize:12})}/>
        </span>}
        {!desb&&<span style={{color:"#94a3b8",fontSize:11.5}}>Fica no álbum como carta a conquistar — quando desbloquear, o cliente vê a festa.</span>}
      </div>
      <div style={{display:"flex",justifyContent:"flex-end",gap:8,marginTop:2}}>
        <button type="button" onClick={onFechar}
          style={{background:"#fff",color:"#64748b",border:"1px solid #e2e8f0",borderRadius:9,padding:"9px 16px",
            fontSize:12.5,fontWeight:700,cursor:"pointer",fontFamily:_CQ_FF}}>Cancelar</button>
        <button type="button" disabled={salvando} onClick={_salvar}
          style={{background:"linear-gradient(135deg,#a855f7,#7c3aed)",color:"#fff",border:"none",borderRadius:9,padding:"9px 18px",
            fontSize:12.5,fontWeight:800,cursor:salvando?"wait":"pointer",fontFamily:_CQ_FF,opacity:salvando?.6:1}}>
          {salvando?"Salvando…":"Salvar conquista"}</button>
      </div>
    </div>
  </div>;
}

/* ── Carta do álbum ── */
function _CqCarta({c, nova, revelada, onRevelar, canEdit, onEditar, onExcluir, onToggleDesb, onResetReveal, isMob}){
  const _ouro=c.tema==="ouro";
  const _bg=_ouro
    ? "linear-gradient(158deg,#6b4204 0%,#4a2c02 42%,#241501 100%)"
    : "linear-gradient(158deg,#43197e 0%,#2d1058 42%,#180730 100%)";
  const _moldOk=_ouro
    ? "linear-gradient(150deg,rgba(255,216,104,.95) 0%,rgba(240,180,41,.6) 30%,rgba(255,216,104,.35) 62%,rgba(255,216,104,.85) 100%)"
    : "linear-gradient(150deg,rgba(255,216,104,.95) 0%,rgba(240,180,41,.55) 28%,rgba(120,60,200,.35) 62%,rgba(255,216,104,.75) 100%)";
  const _somb=_ouro?"rgba(90,56,4,.4)":"rgba(43,16,85,.34)";
  const _desb=!!c.desbloqueada;

  /* ── VERSO — conquista nova esperando ser revelada ── */
  if(nova && !revelada){
    return <div onClick={onRevelar} title="Toque para revelar"
      style={{clipPath:_CQ_CUT,padding:"1.5px",cursor:"pointer",
        background:"linear-gradient(150deg,"+_CQ_OURO2+","+_CQ_OURO+" 40%,#9F43F6 75%,"+_CQ_OURO2+")",
        filter:"drop-shadow(0 14px 30px rgba(159,67,246,.35))",animation:"pxCqPulse 1.8s ease-in-out infinite"}}>
      <div style={{clipPath:_CQ_CUT_IN,position:"relative",overflow:"hidden",minHeight:isMob?218:248,
        background:"linear-gradient(158deg,#2a0f52 0%,#180730 60%,#0d041c 100%)",
        display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",gap:12,padding:"20px 14px"}}>
        <div style={{position:"absolute",inset:0,pointerEvents:"none",opacity:.07,
          backgroundImage:"repeating-linear-gradient(135deg,#fff 0 1px,transparent 1px 9px)"}}/>
        <div style={{position:"absolute",top:"-40%",left:"-60%",width:"70%",height:"180%",transform:"rotate(18deg)",
          background:"linear-gradient(90deg,transparent,rgba(255,255,255,.16),transparent)",animation:"pxCqShine 2.4s ease-in-out infinite"}}/>
        <div style={{width:64,height:64,clipPath:_CQ_HEX,background:"linear-gradient(150deg,"+_CQ_OURO2+","+_CQ_OURO+")",
          display:"flex",alignItems:"center",justifyContent:"center"}}>
          <div style={{width:58,height:58,clipPath:_CQ_HEX,background:"#1c0a38",display:"flex",alignItems:"center",justifyContent:"center"}}>
            <span style={{color:_CQ_OURO2,fontSize:26,fontWeight:900,fontFamily:_CQ_FF}}>?</span>
          </div>
        </div>
        <div style={{textAlign:"center"}}>
          <div style={{color:_CQ_OURO2,fontSize:10.5,fontWeight:900,letterSpacing:2.4,textTransform:"uppercase"}}>Nova conquista</div>
          <div style={{color:"rgba(255,255,255,.72)",fontSize:11.5,fontWeight:600,marginTop:5}}>Toque para revelar</div>
        </div>
      </div>
    </div>;
  }

  /* ── FRENTE ── */
  return <div style={{clipPath:_CQ_CUT,padding:"1.5px",position:"relative",
    background:_desb?_moldOk:"linear-gradient(150deg,#f0f2f7,#e4e8f0 55%,#f0f2f7)",
    filter:_desb?"drop-shadow(0 14px 28px "+_somb+")":"drop-shadow(0 6px 16px rgba(15,23,42,.07))",
    animation:revelada?"pxCqReveal .6s cubic-bezier(.34,1.3,.5,1) both":"none",
    transition:"transform .2s cubic-bezier(.4,0,.2,1), filter .2s"}}
    onMouseEnter={function(e){e.currentTarget.style.transform="translateY(-4px)";}}
    onMouseLeave={function(e){e.currentTarget.style.transform="";}}>
    <div style={{clipPath:_CQ_CUT_IN,position:"relative",overflow:"hidden",minHeight:isMob?218:248,boxSizing:"border-box",
      background:_desb?_bg:"linear-gradient(168deg,#ffffff 0%,#f8fafc 60%,#f1f4f9 100%)",
      padding:"18px 15px 15px",display:"flex",flexDirection:"column",alignItems:"center",gap:10}}>
      {/* textura só nas desbloqueadas; bloqueada ganha um halo de cor sutil */}
      {_desb&&<div style={{position:"absolute",inset:0,pointerEvents:"none",opacity:.06,
        backgroundImage:"repeating-linear-gradient(135deg,#fff 0 1px,transparent 1px 9px)"}}/>}
      {!_desb&&<div style={{position:"absolute",inset:0,pointerEvents:"none",
        background:"radial-gradient(120% 85% at 50% -12%,"+(_ouro?"rgba(240,180,41,.10)":"rgba(159,67,246,.09)")+", transparent 58%)"}}/>}
      {_desb&&<div style={{position:"absolute",top:"-40%",left:"-60%",width:"55%",height:"180%",transform:"rotate(18deg)",pointerEvents:"none",
        background:"linear-gradient(90deg,transparent,rgba(255,255,255,.10),transparent)",animation:"pxCqShine 3.6s ease-in-out infinite"}}/>}

      {/* medalhão hexagonal */}
      <div style={{width:58,height:58,clipPath:_CQ_HEX,flexShrink:0,marginTop:4,
        background:_desb?("linear-gradient(150deg,"+_CQ_OURO2+","+_CQ_OURO+")"):("linear-gradient(150deg,"+(_ouro?"#f4e3b8":"#e2d5f7")+",#dde2ea)"),
        display:"flex",alignItems:"center",justifyContent:"center"}}>
        <div style={{width:52,height:52,clipPath:_CQ_HEX,background:_desb?(_ouro?"#3d2603":"#2a0f52"):"#ffffff",
          display:"flex",alignItems:"center",justifyContent:"center"}}>
          {_desb
            ? (typeof Ico==="function"&&<Ico n={c.icone||"award"} size={24} color={_CQ_OURO2}/>)
            : <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke={_ouro?"#d9a821":"#a678e8"} strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" style={{opacity:.75}}><rect x="3" y="11" width="18" height="11" rx="2"/><path d="M7 11V7a5 5 0 0110 0v4"/></svg>}
        </div>
      </div>

      {/* título + descrição */}
      <div style={{textAlign:"center",flex:1,minWidth:0,width:"100%",position:"relative"}}>
        <div style={{color:_desb?"#fff":"#1e293b",fontSize:14,fontWeight:800,letterSpacing:-.2,lineHeight:1.3,
          textShadow:_desb?"0 1px 8px rgba(0,0,0,.35)":"none"}}>{c.titulo}</div>
        {c.descricao&&<div style={{color:_desb?"rgba(255,255,255,.68)":"#8a93a3",fontSize:11,fontWeight:500,lineHeight:1.45,marginTop:5}}>{c.descricao}</div>}
      </div>

      {/* rodapé: estado */}
      {_desb
        ? <span style={{background:"rgba(240,180,41,.16)",border:"1px solid rgba(240,180,41,.5)",color:_CQ_OURO2,
            borderRadius:99,padding:"3px 11px",fontSize:10,fontWeight:800,letterSpacing:.4,display:"inline-flex",alignItems:"center",gap:5,whiteSpace:"nowrap"}}>
            <svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
            Conquistamos em {_cqBR(c.unlocked_at)||"—"}
          </span>
        : <span style={{background:"#fff",border:"1px solid "+(_ouro?"#f0e2bd":"#e6dcf5"),color:_ouro?"#c09122":"#9d7bd8",
            borderRadius:99,padding:"3.5px 12px",fontSize:9.5,fontWeight:800,letterSpacing:.6,whiteSpace:"nowrap",textTransform:"uppercase",
            boxShadow:"0 1px 3px rgba(15,23,42,.05)"}}>Vamos conquistar juntos</span>}

      {/* ── controles do sócio (nunca aparecem pro cliente) ── */}
      {canEdit&&<div style={{display:"flex",gap:5,width:"100%",justifyContent:"center",position:"relative",flexWrap:"wrap"}}>
        <button type="button" onClick={onToggleDesb}
          title={_desb?"Voltar pra bloqueada":"Desbloquear agora — o cliente vê a revelação com festa"}
          style={{background:_desb?"transparent":"linear-gradient(135deg,"+_CQ_OURO2+","+_CQ_OURO+")",
            color:_desb?(_ouro?"#ffd868":"#c4b5fd"):"#3b2603",border:_desb?"1px solid rgba(255,255,255,.28)":"none",
            borderRadius:8,padding:"5px 11px",fontSize:10.5,fontWeight:800,cursor:"pointer",fontFamily:_CQ_FF}}>
          {_desb?"Bloquear":"Desbloquear"}
        </button>
        {_desb&&typeof onResetReveal==="function"&&<button type="button" onClick={onResetReveal} title="Vira a carta de novo — o cliente revela com festa outra vez"
          style={{background:"transparent",border:"1px solid rgba(255,216,104,.5)",borderRadius:8,
            padding:"5px 9px",color:_CQ_OURO2,fontSize:10.5,fontWeight:800,cursor:"pointer",fontFamily:_CQ_FF,display:"inline-flex",alignItems:"center",gap:4}}>
          <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round"><path d="M23 4v6h-6"/><path d="M20.49 15a9 9 0 1 1-2.12-9.36L23 10"/></svg>
          Revelar de novo
        </button>}
        <button type="button" onClick={onEditar} title="Editar conquista"
          style={{background:"transparent",border:"1px solid "+(_desb?"rgba(255,255,255,.28)":"#dbe0e8"),borderRadius:8,
            padding:"5px 9px",color:_desb?"rgba(255,255,255,.8)":"#64748b",fontSize:10.5,fontWeight:700,cursor:"pointer",fontFamily:_CQ_FF}}>Editar</button>
        <button type="button" onClick={onExcluir} title="Excluir conquista"
          style={{background:"transparent",border:"1px solid "+(_desb?"rgba(255,150,150,.4)":"#fecaca"),borderRadius:8,
            padding:"5px 9px",color:_desb?"#fca5a5":"#dc2626",fontSize:10.5,fontWeight:700,cursor:"pointer",fontFamily:_CQ_FF}}>Excluir</button>
      </div>}
    </div>
  </div>;
}

/* ═══ ÁLBUM — componente principal ═══ */
function CConquistasAlbum({cl, canEdit, selUnit, isMob}){
  const sb=(typeof window!=="undefined")?window._sb:null;

  // Bioter: cartas moram no client_id raiz; `unidade` segmenta
  const _rootId=(cl&&cl.id&&cl.id.indexOf("bioter_")===0)?"bioter":((cl&&cl.id)||"");
  const _unidade=(cl&&cl.id&&cl.id.indexOf("bioter_")===0)?cl.id.slice("bioter_".length):(selUnit||"grupo");
  const _isBioter=_rootId==="bioter";
  const _cor=(cl&&cl.color)||"#9F43F6";

  const [cartas,setCartas]=useState([]);
  const [loading,setLoading]=useState(true);
  const [modal,setModal]=useState(null);          // null | {} nova | {...} editar
  const [vistas,setVistas]=useState(function(){ return _cqLerVistas(_rootId); });
  const [reveladas,setReveladas]=useState({});    // {id:true} — anim de flip nesta sessão
  const [confete,setConfete]=useState(false);

  // Peças do confete — sorteadas uma vez (mesmo esquema das cartinhas do comercial)
  const _confPecas=useMemo(function(){
    const cores=["#f0b429","#ffd868","#9F43F6","#c084fc","#ffffff","#22c55e","#ff8fab"];
    const anims=["pxCqConfA","pxCqConfB","pxCqConfC"];
    const out=[];
    for(let i=0;i<70;i++){
      const redondo=i%4===0;
      out.push({i:i,left:Math.round(Math.random()*100),
        w:redondo?7:(4+Math.round(Math.random()*5)),h:redondo?7:(9+Math.round(Math.random()*9)),
        cor:cores[i%cores.length],raio:redondo?"50%":"1px",rot:Math.round(Math.random()*360),
        anim:anims[i%anims.length],dur:(1.5+Math.random()*1.3).toFixed(2),delay:(Math.random()*0.45).toFixed(2)});
    }
    return out;
  },[]);

  // Trilha padrão de vendas — vem automático em TODO cliente, ordem crescente.
  // (sócio pode desbloquear/editar/excluir depois)
  // Lane TOTAL (acumulado) — ordem crescente
  const _TRILHA_VENDAS=[
    "R$ 100 mil em vendas a partir do canal digital",
    "R$ 500 mil em vendas a partir do canal digital",
    "R$ 1 milhão em vendas a partir do canal digital",
    "R$ 5 milhões em vendas a partir do canal digital",
    "R$ 10 milhões em vendas a partir do canal digital",
    "R$ 50 milhões em vendas a partir do canal digital",
    "R$ 100 milhões em vendas a partir do canal digital",
  ];
  // Lane MENSAL — quanto batemos dentro de um mês
  const _TRILHA_MENSAL=[
    "R$ 10 mil em vendas no mês a partir do canal digital",
    "R$ 25 mil em vendas no mês a partir do canal digital",
    "R$ 50 mil em vendas no mês a partir do canal digital",
    "R$ 100 mil em vendas no mês a partir do canal digital",
    "R$ 250 mil em vendas no mês a partir do canal digital",
    "R$ 500 mil em vendas no mês a partir do canal digital",
    "R$ 1 milhão em vendas no mês a partir do canal digital",
    "R$ 2 milhões em vendas no mês a partir do canal digital",
  ];
  // Identifica a carta de venda pelo VALOR (não pelo texto exato) + se é mensal.
  // Retorna "t:100000" (total) / "m:50000" (mensal) / null (não é carta de venda).
  const _tierVenda=function(titulo){
    const t=String(titulo||"").toLowerCase();
    if(t.indexOf("digital")<0||t.indexOf("venda")<0) return null;
    const m=t.match(/r?\$?\s*([\d.,]+)\s*(mil(?!h)|milh|bilh)?/);
    if(!m) return null;
    let n=parseFloat(String(m[1]).replace(/\./g,"").replace(",","."));
    if(isNaN(n)||n<=0) return null;
    if(m[2]==="mil") n*=1e3;
    else if(m[2]==="milh") n*=1e6;
    else if(m[2]==="bilh") n*=1e9;
    const mensal=/no m[eê]s/.test(t);
    return (mensal?"m:":"t:")+n;
  };
  const _tierValor=function(k){ return k?parseFloat(k.slice(2)):NaN; };
  const _seedTentado=useRef(false);
  const _carregar=async function(){
    if(!sb||!_rootId){ setLoading(false); return; }
    try{
      const r=await sb.from("client_conquistas").select("*").eq("client_id",_rootId)
        .order("ordem",{ascending:true}).order("created_at",{ascending:true});
      let _lista=(r&&r.data)||[];
      // Auto-seed 1x: só sócio cria; cria as cartas de venda que faltam (dedup por título normalizado)
      if(canEdit && !_seedTentado.current){
        _seedTentado.current=true;
        const _tiersTem={}; _lista.forEach(function(c){ const _t=_tierVenda(c.titulo); if(_t)_tiersTem[_t]=true; });
        const _faltam=_TRILHA_VENDAS.concat(_TRILHA_MENSAL).filter(function(t){ return !_tiersTem[_tierVenda(t)]; });
        if(_faltam.length>0){
          const _base=_lista.length;
          const _rows=_faltam.map(function(t,i){
            return {client_id:_rootId,unidade:"",titulo:t,descricao:"",icone:"dollar",tema:"ouro",
              desbloqueada:false,unlocked_at:null,ordem:_base+i,
              created_by:(typeof CURRENT_USER!=="undefined"&&CURRENT_USER)?CURRENT_USER.name:"seed"};
          });
          try{
            const _ins=await sb.from("client_conquistas").insert(_rows).select("*");
            if(_ins&&!_ins.error&&_ins.data) _lista=_lista.concat(_ins.data);
          }catch(_){}
        }
      }
      setCartas(_lista);
    }catch(e){ console.warn("[conquistas] load:",(e&&e.message)||e); }
    setLoading(false);
  };
  useEffect(function(){
    let alive=true;
    _carregar();
    if(!sb) return function(){alive=false;};
    let ch=null;
    try{
      ch=sb.channel("conquistas-rt-"+_rootId)
        .on("postgres_changes",{event:"*",schema:"public",table:"client_conquistas",filter:"client_id=eq."+_rootId},
          function(){ if(alive) _carregar(); })
        .subscribe();
    }catch(_){}
    return function(){ alive=false; try{ if(ch) sb.removeChannel(ch); }catch(_){} };
  },[_rootId]);

  /* Unidade: "grupo" vê tudo; unidade específica vê grupo + as dela */
  const _visiveis=!_isBioter?cartas:cartas.filter(function(c){
    if(_unidade==="grupo"||_unidade==="_minhas_") return true;
    const u=c.unidade||"grupo";
    return u==="grupo"||u===_unidade;
  });
  const _desb=_visiveis.filter(function(c){return c.desbloqueada;});
  const _pct=_visiveis.length?Math.round(_desb.length/_visiveis.length*100):0;

  /* ── Revelar carta nova: som + confete + flip ── */
  const _revelar=function(c){
    try{ if(typeof _pxSomConfete==="function") _pxSomConfete(); }catch(_){}
    setReveladas(function(p){ const n=Object.assign({},p); n[c.id]=true; return n; });
    _cqMarcarVista(_rootId,c.id);
    setVistas(_cqLerVistas(_rootId));
    setConfete(false);
    setTimeout(function(){ setConfete(true); },20);
    setTimeout(function(){ setConfete(false); },3600);
  };

  /* ── Reset de revelação: vira a carta de novo pra reexplodir a festa ── */
  const _resetRevelacao=function(c){
    _cqDesmarcarVista(_rootId,c.id);
    setVistas(_cqLerVistas(_rootId));
    setReveladas(function(p){ const n=Object.assign({},p); delete n[c.id]; return n; });
    setConfete(false);
    if(typeof pixelsToast!=="undefined") pixelsToast.success("Carta virada — o cliente revela de novo com festa.",2500);
  };

  /* ── CRUD (sócios) ── */
  const _salvar=async function(dados){
    if(!sb) return;
    const _payload={titulo:dados.titulo,descricao:dados.descricao,icone:dados.icone,tema:dados.tema,
      desbloqueada:dados.desbloqueada,unlocked_at:dados.unlocked_at,updated_at:new Date().toISOString()};
    try{
      if(dados.id){
        const r=await sb.from("client_conquistas").update(_payload).eq("id",dados.id);
        if(r&&r.error) throw r.error;
      }else{
        _payload.client_id=_rootId;
        _payload.unidade=(_isBioter&&_unidade!=="grupo"&&_unidade!=="_minhas_")?_unidade:"";
        _payload.ordem=cartas.length;
        _payload.created_by=(typeof CURRENT_USER!=="undefined"&&CURRENT_USER)?CURRENT_USER.name:"";
        const r=await sb.from("client_conquistas").insert(_payload);
        if(r&&r.error) throw r.error;
      }
      if(typeof pixelsToast!=="undefined") pixelsToast.success("Conquista salva.");
      setModal(null);
      _carregar();
    }catch(e){ if(typeof pixelsToast!=="undefined") pixelsToast.error("Erro salvando: "+((e&&e.message)||""),5000); }
  };
  const _excluir=async function(c){
    let ok=true;
    if(typeof pixelsConfirm==="function")
      ok=await pixelsConfirm({title:"Excluir conquista?",message:'"'+(c.titulo||"")+'" sai do álbum do cliente.',danger:true});
    if(!ok) return;
    try{
      await sb.from("client_conquistas").delete().eq("id",c.id);
      if(typeof pixelsToast!=="undefined") pixelsToast.success("Conquista excluída.");
      _carregar();
    }catch(e){ if(typeof pixelsToast!=="undefined") pixelsToast.error("Erro excluindo.",4000); }
  };
  const _toggleDesb=async function(c){
    const _novo=!c.desbloqueada;
    setCartas(function(prev){ return prev.map(function(x){
      return x.id===c.id?Object.assign({},x,{desbloqueada:_novo,unlocked_at:_novo?new Date().toISOString().slice(0,10):null}):x; }); });
    try{
      const r=await sb.from("client_conquistas")
        .update({desbloqueada:_novo,unlocked_at:_novo?new Date().toISOString().slice(0,10):null,updated_at:new Date().toISOString()})
        .eq("id",c.id);
      if(r&&r.error) throw r.error;
      if(typeof pixelsToast!=="undefined")
        pixelsToast.success(_novo?"Desbloqueada! O cliente vai ver a revelação no portal.":"Carta voltou pra bloqueada.");
    }catch(e){ if(typeof pixelsToast!=="undefined") pixelsToast.error("Erro atualizando.",4000); _carregar(); }
  };

  return <div style={{display:"flex",flexDirection:"column",gap:18,fontFamily:_CQ_FF,position:"relative"}}>
    <style>{"@keyframes pxCqReveal{0%{opacity:0;transform:rotateY(88deg) scale(.9)}55%{opacity:1;transform:rotateY(-8deg) scale(1.03)}100%{opacity:1;transform:none}}"
      +"@keyframes pxCqPulse{0%,100%{transform:scale(1)}50%{transform:scale(1.028)}}"
      +"@keyframes pxCqShine{0%{left:-60%}55%{left:120%}100%{left:120%}}"
      +"@keyframes pxCqConfA{0%{opacity:1;transform:translate(0,-20px) rotate(0deg)}100%{opacity:0;transform:translate(-70px,560px) rotate(680deg)}}"
      +"@keyframes pxCqConfB{0%{opacity:1;transform:translate(0,-20px) rotate(0deg)}100%{opacity:0;transform:translate(80px,580px) rotate(-720deg)}}"
      +"@keyframes pxCqConfC{0%{opacity:1;transform:translate(0,-20px) rotate(0deg)}100%{opacity:0;transform:translate(12px,600px) rotate(520deg)}}"
      +"@keyframes pxCqFlash{0%{opacity:0}18%{opacity:.85}100%{opacity:0}}"}</style>

    {/* ── Header ── */}
    <div style={{display:"flex",alignItems:"flex-start",justifyContent:"space-between",gap:14,flexWrap:"wrap"}}>
      <div style={{minWidth:0}}>
        <div style={{fontSize:19,fontWeight:800,color:"#0f172a",letterSpacing:-.35,display:"flex",alignItems:"center",gap:9}}>
          {typeof Ico==="function"&&<Ico n="star" size={19} color={_CQ_OURO}/>}
          Conquistas
        </div>
        <div style={{fontSize:13,color:"#64748b",marginTop:3}}>Nosso álbum de vitórias — cada carta é algo que conquistamos juntos.</div>
      </div>
      {canEdit&&<button type="button" onClick={function(){setModal({});}}
        style={{background:"linear-gradient(135deg,#a855f7,#7c3aed)",color:"#fff",border:"none",borderRadius:10,
          padding:"10px 17px",fontSize:12.5,fontWeight:800,cursor:"pointer",fontFamily:_CQ_FF,
          display:"inline-flex",alignItems:"center",gap:7,boxShadow:"0 6px 16px rgba(124,58,237,.30)",flexShrink:0}}>
        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
        Nova conquista
      </button>}
    </div>

    {/* ── Progresso do álbum ── */}
    {_visiveis.length>0&&<div style={{background:"linear-gradient(158deg,#2a0f52 0%,#180730 100%)",borderRadius:14,
      padding:isMob?"13px 15px":"14px 20px",display:"flex",alignItems:"center",gap:14,flexWrap:"wrap",position:"relative",overflow:"hidden"}}>
      <div style={{position:"absolute",inset:0,pointerEvents:"none",opacity:.06,
        backgroundImage:"repeating-linear-gradient(135deg,#fff 0 1px,transparent 1px 9px)"}}/>
      <span style={{color:_CQ_OURO2,fontSize:20,fontWeight:900,letterSpacing:-.5,fontFeatureSettings:"'tnum'",flexShrink:0}}>
        {_desb.length}<span style={{color:"rgba(255,255,255,.45)",fontSize:14,fontWeight:700}}>/{_visiveis.length}</span>
      </span>
      <div style={{flex:1,minWidth:120}}>
        <div style={{color:"rgba(255,255,255,.8)",fontSize:11,fontWeight:700,marginBottom:5,letterSpacing:.3}}>
          {_pct>=100?"Álbum completo — e ainda estamos só começando!":"cartas desbloqueadas do nosso álbum"}
        </div>
        <div style={{height:8,background:"rgba(255,255,255,.12)",borderRadius:99,overflow:"hidden"}}>
          <div style={{width:_pct+"%",height:"100%",borderRadius:99,transition:"width .5s",
            background:"linear-gradient(90deg,"+_CQ_OURO+","+_CQ_OURO2+")"}}/>
        </div>
      </div>
      <span style={{color:_CQ_OURO2,fontSize:14,fontWeight:800,fontFeatureSettings:"'tnum'",flexShrink:0}}>{_pct}%</span>
    </div>}

    {/* ── Grid do álbum ── */}
    {loading
      ? <div style={{textAlign:"center",color:"#94a3b8",fontSize:13,padding:"40px"}}>Abrindo o álbum…</div>
      : _visiveis.length===0
        ? <div style={{background:"#fafbfc",border:"1px dashed #e2e8f0",borderRadius:14,padding:"50px 20px",textAlign:"center"}}>
            <div style={{fontSize:26,marginBottom:8}}>🏆</div>
            <div style={{color:"#334155",fontWeight:700,fontSize:14,marginBottom:5}}>O álbum ainda está sendo preparado</div>
            <div style={{color:"#94a3b8",fontSize:12.5}}>
              {canEdit?"Crie as primeiras cartas — os objetivos que vamos conquistar com esse cliente.":"Em breve as nossas primeiras conquistas aparecem aqui."}
            </div>
          </div>
        : <div style={{position:"relative"}}>
            {/* CONFETE — mesma festa das cartinhas de bônus */}
            {confete&&<div style={{position:"absolute",left:0,right:0,top:-40,bottom:-40,pointerEvents:"none",overflow:"hidden",zIndex:9}}>
              <div style={{position:"absolute",left:"50%",top:"30%",transform:"translate(-50%,-50%)",width:520,height:520,borderRadius:"50%",
                background:"radial-gradient(circle,rgba(255,216,104,.55) 0%,rgba(240,180,41,.20) 38%,rgba(240,180,41,0) 70%)",
                animation:"pxCqFlash .85s ease-out both"}}/>
              {_confPecas.map(function(p){
                return <div key={p.i} style={{position:"absolute",left:p.left+"%",top:0,width:p.w,height:p.h,background:p.cor,
                  borderRadius:p.raio,transform:"rotate("+p.rot+"deg)",opacity:0,
                  animation:p.anim+" "+p.dur+"s cubic-bezier(.18,.62,.42,1) "+p.delay+"s both",boxShadow:"0 1px 2px rgba(15,23,42,.14)"}}/>;
              })}
            </div>}
            {(function(){
              const _renderCartas=function(list){
                return <div style={{display:"grid",gridTemplateColumns:isMob?"repeat(auto-fill,minmax(160px,1fr))":"repeat(auto-fill,minmax(215px,1fr))",gap:isMob?11:16}}>
                  {list.map(function(c){
                    const _nova=c.desbloqueada&&vistas.indexOf(c.id)<0&&!reveladas[c.id];
                    return <_CqCarta key={c.id} c={c} isMob={isMob}
                      nova={c.desbloqueada&&vistas.indexOf(c.id)<0}
                      revelada={!!reveladas[c.id]}
                      onRevelar={function(){_revelar(c);}}
                      canEdit={canEdit&&!_nova}
                      onEditar={function(){setModal(c);}}
                      onExcluir={function(){_excluir(c);}}
                      onToggleDesb={function(){_toggleDesb(c);}}
                      onResetReveal={function(){_resetRevelacao(c);}}/>;
                  })}
                </div>;
              };
              const _laneHead=function(lbl,sub,cor,count,total){
                return <div style={{display:"flex",alignItems:"center",gap:9,margin:"4px 0 12px"}}>
                  <span style={{width:30,height:30,borderRadius:9,background:"linear-gradient(135deg,"+cor+","+cor+"bb)",display:"inline-flex",alignItems:"center",justifyContent:"center",boxShadow:"0 3px 10px "+cor+"44",flexShrink:0}}>
                    <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="2.3" strokeLinecap="round" strokeLinejoin="round"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/></svg>
                  </span>
                  <div>
                    <div style={{color:"#0f172a",fontWeight:800,fontSize:14.5,letterSpacing:-.25,lineHeight:1.2}}>{lbl}</div>
                    <div style={{color:"#94a3b8",fontSize:11,fontWeight:600}}>{sub}</div>
                  </div>
                  <span style={{background:cor+"14",color:cor,borderRadius:99,padding:"2px 10px",fontSize:11,fontWeight:800,fontFeatureSettings:"'tnum'"}}>{count}/{total}</span>
                  <span style={{flex:1,height:1,background:"linear-gradient(90deg,#e8ebf0,transparent)"}}/>
                </div>;
              };
              const _byVal=function(a,b){ return _tierValor(_tierVenda(a.titulo))-_tierValor(_tierVenda(b.titulo)); };
              const _tot=_visiveis.filter(function(c){const k=_tierVenda(c.titulo);return k&&k[0]==="t";}).sort(_byVal);
              const _men=_visiveis.filter(function(c){const k=_tierVenda(c.titulo);return k&&k[0]==="m";}).sort(_byVal);
              const _out=_visiveis.filter(function(c){return !_tierVenda(c.titulo);});
              return <div style={{display:"flex",flexDirection:"column",gap:22}}>
                {/* Mês primeiro (meta mais próxima), totais depois — pedido de 02/09 */}
                {_men.length>0&&<div>
                  {_laneHead("Conquistas do mês","Quanto batemos dentro de um único mês","#7c3aed",_men.filter(function(c){return c.desbloqueada;}).length,_men.length)}
                  {_renderCartas(_men)}
                </div>}
                {_tot.length>0&&<div>
                  {_laneHead("Conquistas totais","Vendas acumuladas a partir do canal digital","#f0b429",_tot.filter(function(c){return c.desbloqueada;}).length,_tot.length)}
                  {_renderCartas(_tot)}
                </div>}
                {_out.length>0&&<div>
                  {_laneHead("Outras conquistas","Marcos especiais fora da régua de vendas","#0ea5e9",_out.filter(function(c){return c.desbloqueada;}).length,_out.length)}
                  {_renderCartas(_out)}
                </div>}
              </div>;
            })()}
          </div>
    }

    {modal&&<_CqModal inicial={modal} isMob={isMob} onSalvar={_salvar} onFechar={function(){setModal(null);}}
      destino={(!modal.id)&&_isBioter
        ? ((_unidade!=="grupo"&&_unidade!=="_minhas_")
            ? ("Bioter "+((typeof _DEM_BIOTER_UNIDADES!=="undefined"&&_DEM_BIOTER_UNIDADES[_unidade])||_unidade)+" (só essa unidade)")
            : "Grupo Bioter (todas as unidades)")
        : null}/>}
  </div>;
}

// ======= 30_matriz.jsx =======
/* ═══════════════════════════════════════════════════════════════════════
   MATRIZ DE RESPONSABILIDADES — Estratégia > Matriz de Responsabilidades
   Cadeiras da empresa: responsável, missão, atribuições, entregas e interfaces.
   Tabela: responsibility_roles (jsonb pras listas — mesmo padrão do resto).
   Edição: sócios + Hellen. Visual segue o padrão das telas de Estratégia.
   ═══════════════════════════════════════════════════════════════════════ */
const _MTZ_FF="'Inter',system-ui,sans-serif";
const _MTZ_INP={width:"100%",background:"#fff",border:"1px solid #e2e8f0",borderRadius:10,padding:"10px 13px",fontSize:13,color:"#0f172a",outline:"none",boxSizing:"border-box",fontFamily:_MTZ_FF};
const _MTZ_LBL={color:"#94a3b8",fontSize:10.5,fontWeight:800,letterSpacing:.6,textTransform:"uppercase",marginBottom:6};
function _mtzRespUser(r){
  if(!r) return null;
  if(r.responsavel_uid){ const u=(typeof TEAM!=="undefined"?TEAM:[]).find(function(x){return x.id===r.responsavel_uid;}); if(u) return u; }
  return null;
}
function _mtzBR(iso){
  if(!iso) return "";
  try{ const d=new Date(iso); if(isNaN(d.getTime()))return ""; return String(d.getDate()).padStart(2,"0")+"/"+String(d.getMonth()+1).padStart(2,"0")+"/"+d.getFullYear(); }catch(_){ return ""; }
}
/* Seções dentro das atribuições: item que começa com "## " é o título da seção.
   Continua sendo array de texto no banco — cadeira sem seção fica igual antes. */
/* Ícone da cadeira, escolhido pelo nome (sem campo novo no banco) */
function _MtzIcone({nome, size, color}){
  const n=String(nome||"").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"");
  const sz=size||18, c=color||"currentColor";
  const P={strokeWidth:2,stroke:c,fill:"none",strokeLinecap:"round",strokeLinejoin:"round"};
  let d;
  // (16/09/2026) Diretores: ícone do CARGO, nada de coroa.
  if(/growth|crescimento/.test(n)) d=<g {...P}><path d="M3 20h18"/><path d="M5 16l4.5-4.5 3.5 3.5L20 7"/><path d="M15 7h5v5"/></g>; // gráfico subindo
  else if(/executiv/.test(n)) d=<g {...P}><path d="M12 14l3.5-3.5"/><path d="M3.5 17a9 9 0 1 1 17 0"/><circle cx="12" cy="14" r="1.4" fill={c}/><path d="M7 17h10"/></g>; // painel de controle (operação)
  else if(/projeto|gerente|coordena|operac/.test(n)) d=<g {...P}><rect x="3" y="7" width="18" height="13" rx="2.5"/><path d="M8 7V5.5A2.5 2.5 0 0 1 10.5 3h3A2.5 2.5 0 0 1 16 5.5V7"/><path d="M3 12.5h18"/><path d="M10.5 12.5v1.5h3v-1.5"/></g>;
  else if(/rede|social|midias sociais/.test(n)) d=<g {...P}><path d="M3 11v2a1 1 0 0 0 1 1h2l5 4V6L6 10H4a1 1 0 0 0-1 1z"/><path d="M15.5 8.5a5 5 0 0 1 0 7"/><path d="M18.5 5.5a9 9 0 0 1 0 13"/></g>;
  else if(/trafego|midia|ads|anuncio/.test(n)) d=<g {...P}><circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1.3" fill={c}/></g>;
  else if(/design|arte|criacao/.test(n)) d=<g {...P}><path d="M12 19l7-7 3 3-7 7-3-3z"/><path d="M18 13l-1.5-7.5L2 2l3.5 14.5L13 18l5-5z"/><path d="M2 2l7.586 7.586"/><circle cx="11" cy="11" r="2"/></g>;
  else if(/video|edicao|editor/.test(n)) d=<g {...P}><rect x="2.5" y="6" width="13" height="12" rx="2.5"/><path d="M15.5 10.5l6-3.5v10l-6-3.5"/></g>;
  else if(/comercial|venda/.test(n)) d=<g {...P}><path d="M3 17l6-6 4 4 8-8"/><path d="M15 7h6v6"/></g>;
  else if(/financ/.test(n)) d=<g {...P}><path d="M12 2v20"/><path d="M17 5.5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/></g>;
  else if(/direc|socio|ceo|diretor/.test(n)) d=<g {...P}><rect x="4" y="3" width="16" height="18" rx="2"/><path d="M9 21v-4h6v4"/><path d="M8 7h2M14 7h2M8 11h2M14 11h2"/></g>; // prédio (sem coroa)
  else if(/conteudo|estrateg|copy|redac/.test(n)) d=<g {...P}><path d="M12 20h9"/><path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4z"/></g>;
  else d=<g {...P}><path d="M12 2L2 7l10 5 10-5-10-5z"/><path d="M2 17l10 5 10-5"/><path d="M2 12l10 5 10-5"/></g>;
  return <svg width={sz} height={sz} viewBox="0 0 24 24" style={{display:"block",flexShrink:0}}>{d}</svg>;
}
function _mtzEhSecao(s){ return /^##\s*/.test(String(s||"")); }
function _mtzTituloSecao(s){ return String(s||"").replace(/^##\s*/,""); }
function _mtzQtd(lst){ return (lst||[]).filter(function(a){return !_mtzEhSecao(a);}).length; }
function _mtzGrupos(lst){
  const out=[]; let cur=null;
  (lst||[]).forEach(function(a){
    if(_mtzEhSecao(a)){ cur={titulo:_mtzTituloSecao(a),itens:[]}; out.push(cur); return; }
    if(!cur){ cur={titulo:null,itens:[]}; out.push(cur); }
    cur.itens.push(a);
  });
  return out.filter(function(g){return g.titulo||g.itens.length;});
}
/* Editor de lista dinâmica (atribuições / entregas) — linha + X + adicionar */
function _MtzListaEdit({itens, onChange, placeholder, addLabel, comSecoes}){
  const _set=function(i,v){ onChange(itens.map(function(x,j){return j===i?(_mtzEhSecao(x)?"## "+v:v):x;})); };
  const _del=function(i){ onChange(itens.filter(function(_,j){return j!==i;})); };
  const _add=function(){ onChange(itens.concat([""])); };
  const _addSecao=function(){ onChange(itens.concat(["## "])); };
  // + dentro da seção: entra no fim dela (antes da próxima seção)
  const _addNa=function(i){ let k=i+1; while(k<itens.length&&!_mtzEhSecao(itens[k])) k++; const n=itens.slice(); n.splice(k,0,""); onChange(n); };
  return <div style={{display:"flex",flexDirection:"column",gap:6}}>
    {itens.map(function(v,i){
      if(comSecoes&&_mtzEhSecao(v)) return <div key={i} style={{display:"flex",alignItems:"center",gap:7,marginTop:i>0?10:0}}>
        <input value={_mtzTituloSecao(v)} placeholder="Nome da seção (ex: Onboarding)" onChange={function(e){_set(i,e.target.value);}}
          style={Object.assign({},_MTZ_INP,{padding:"8px 12px",fontSize:12,fontWeight:800,textTransform:"uppercase",letterSpacing:.5,color:"#6d28d9",background:"#f5f3ff",borderColor:"#ddd6fe"})}/>
        <button type="button" onClick={function(){_addNa(i);}} title="Adicionar atribuição nesta seção"
          style={{background:"#7c3aed",border:"none",color:"#fff",cursor:"pointer",borderRadius:8,width:26,height:26,display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0,fontWeight:800,fontSize:15,lineHeight:1}}>+</button>
        <button type="button" onClick={function(){_del(i);}} title="Remover seção (as atribuições ficam)"
          style={{background:"none",border:"none",color:"#cbd5e1",cursor:"pointer",padding:4,display:"inline-flex",flexShrink:0}}
          onMouseEnter={function(e){e.currentTarget.style.color="#dc2626";}}
          onMouseLeave={function(e){e.currentTarget.style.color="#cbd5e1";}}>
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
        </button>
      </div>;
      return <div key={i} style={{display:"flex",alignItems:"center",gap:7}}>
        <input value={v} placeholder={placeholder} onChange={function(e){_set(i,e.target.value);}}
          style={Object.assign({},_MTZ_INP,{padding:"8px 12px",fontSize:12.5})}/>
        <button type="button" onClick={function(){_del(i);}} title="Remover"
          style={{background:"none",border:"none",color:"#cbd5e1",cursor:"pointer",padding:4,display:"inline-flex",flexShrink:0}}
          onMouseEnter={function(e){e.currentTarget.style.color="#dc2626";}}
          onMouseLeave={function(e){e.currentTarget.style.color="#cbd5e1";}}>
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
        </button>
      </div>;
    })}
    <div style={{display:"flex",gap:6}}>
      <button type="button" onClick={_add}
        style={{flex:1,background:"#7c3aed0d",border:"1px dashed #7c3aed55",borderRadius:10,padding:"9px 0",fontSize:11.5,fontWeight:800,color:"#7c3aed",cursor:"pointer",fontFamily:_MTZ_FF}}>+ {addLabel}</button>
      {comSecoes&&<button type="button" onClick={_addSecao}
        style={{background:"#fff",border:"1px dashed #7c3aed55",borderRadius:10,padding:"9px 14px",fontSize:11.5,fontWeight:800,color:"#6d28d9",cursor:"pointer",fontFamily:_MTZ_FF}}>+ Seção</button>}
    </div>
  </div>;
}
/* Modal de criação/edição */
function _MtzForm({inicial, cadeiras, onSalvar, onFechar}){
  const _novo=!(inicial&&inicial.id);
  const [f,setF]=useState(function(){
    return {
      nome:(inicial&&inicial.nome)||"",
      responsavel_nome:(inicial&&inicial.responsavel_nome)||"",
      responsavel_uid:(inicial&&inicial.responsavel_uid)||"",
      missao:(inicial&&inicial.missao)||"",
      atribuicoes:(inicial&&Array.isArray(inicial.atribuicoes))?inicial.atribuicoes.slice():[],
      entregas:(inicial&&Array.isArray(inicial.entregas))?inicial.entregas.slice():[],
      interfaces:(inicial&&Array.isArray(inicial.interfaces))?inicial.interfaces.slice():[],
    };
  });
  const set=function(k,v){ setF(function(p){ const n=Object.assign({},p); n[k]=v; return n; }); };
  const [novaInterface,setNovaInterface]=useState("");
  if(typeof useEscToClose==="function") useEscToClose(true,onFechar);
  const _salvar=function(){
    if(!String(f.nome||"").trim()){ if(typeof pixelsToast!=="undefined")pixelsToast.warning("Dá um nome pra cadeira."); return; }
    if(!String(f.missao||"").trim()){ if(typeof pixelsToast!=="undefined")pixelsToast.warning("Escreve a missão da cadeira."); return; }
    onSalvar(Object.assign({},f,{
      atribuicoes:f.atribuicoes.map(function(s){return String(s).trim();}).filter(function(s){return s&&!(_mtzEhSecao(s)&&!_mtzTituloSecao(s).trim());}),
      entregas:f.entregas.map(function(s){return String(s).trim();}).filter(Boolean),
      interfaces:f.interfaces.map(function(s){return String(s).trim();}).filter(Boolean),
    }));
  };
  const _outras=(cadeiras||[]).filter(function(c){ return !inicial||c.id!==inicial.id; });
  return <div onMouseDown={function(e){ if(e.target===e.currentTarget) onFechar(); }}
    style={{position:"fixed",inset:0,background:"rgba(15,23,42,.55)",backdropFilter:"blur(4px)",zIndex:500,display:"flex",alignItems:"center",justifyContent:"center",padding:16,fontFamily:_MTZ_FF}}>
    <div onMouseDown={function(e){e.stopPropagation();}}
      style={{background:"#fff",borderRadius:18,width:"100%",maxWidth:640,maxHeight:"92vh",overflow:"auto",boxShadow:"0 24px 64px rgba(15,23,42,.28)"}}>
      <div style={{background:"linear-gradient(135deg,#1e1b4b 0%,#4c1d95 55%,#7c3aed 100%)",padding:"18px 22px",color:"#fff",display:"flex",justifyContent:"space-between",alignItems:"center",gap:12}}>
        <div style={{display:"flex",alignItems:"center",gap:12,minWidth:0}}>
          <div style={{width:38,height:38,borderRadius:11,background:"rgba(255,255,255,.15)",border:"1px solid rgba(255,255,255,.24)",display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
            <Ico n="layers" size={18} color="#fff"/>
          </div>
          <div style={{minWidth:0}}>
            <div style={{fontWeight:800,fontSize:16,letterSpacing:-.3}}>{_novo?"Nova cadeira":"Editar cadeira"}</div>
            <div style={{fontSize:11.5,opacity:.78,marginTop:2,fontWeight:500}}>Quem faz o quê na operação — preto no branco</div>
          </div>
        </div>
        <button onClick={onFechar} title="Fechar"
          style={{background:"rgba(255,255,255,.14)",border:"1px solid rgba(255,255,255,.2)",borderRadius:9,width:30,height:30,color:"#fff",cursor:"pointer",display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
        </button>
      </div>
      <div style={{padding:"18px 22px",display:"flex",flexDirection:"column",gap:15}}>
        <div>
          <div style={_MTZ_LBL}>Nome da cadeira *</div>
          <input value={f.nome} onChange={function(e){set("nome",e.target.value);}} placeholder="Ex: Estratégia de Conteúdo e Coordenação de Produção" style={_MTZ_INP}/>
        </div>
        <div>
          <div style={_MTZ_LBL}>Responsável</div>
          <div style={{display:"flex",alignItems:"center",gap:8,flexWrap:"wrap"}}>
            {(typeof TEAM!=="undefined"?TEAM:[]).map(function(u){
              const _sel=f.responsavel_uid===u.id;
              return <button key={u.id} type="button" title={u.name}
                onClick={function(){ if(_sel){set("responsavel_uid","");}else{setF(function(p){return Object.assign({},p,{responsavel_uid:u.id,responsavel_nome:p.responsavel_nome||u.name});});} }}
                style={{width:34,height:34,borderRadius:"50%",padding:0,border:"none",background:"none",cursor:"pointer",flexShrink:0,opacity:(!f.responsavel_uid||_sel)?1:.35,boxShadow:_sel?"0 0 0 2px #fff,0 0 0 4px #7c3aed":"none",transition:"all .12s"}}>
                {typeof UserAvatar==="function"?<UserAvatar user={u} size={34}/>:<span/>}
              </button>;
            })}
            <input value={f.responsavel_nome} onChange={function(e){set("responsavel_nome",e.target.value);}} placeholder="Nome do responsável"
              style={Object.assign({},_MTZ_INP,{width:210})}/>
          </div>
        </div>
        <div>
          <div style={_MTZ_LBL}>Missão da cadeira *</div>
          <textarea value={f.missao} onChange={function(e){set("missao",e.target.value);}} rows={3}
            placeholder="O principal objetivo dessa função, em 1 ou 2 linhas..."
            style={Object.assign({},_MTZ_INP,{resize:"vertical",minHeight:72,lineHeight:1.6})}/>
        </div>
        <div>
          <div style={_MTZ_LBL}>Atribuições</div>
          <_MtzListaEdit itens={f.atribuicoes} onChange={function(v){set("atribuicoes",v);}} placeholder="Ex: Agendar publicações" addLabel="Adicionar atribuição" comSecoes={true}/>
        </div>
      </div>
      <div style={{padding:"14px 22px 18px",borderTop:"1px solid #f1f5f9",display:"flex",justifyContent:"flex-end",gap:8}}>
        <button onClick={onFechar} type="button"
          style={{background:"#fff",color:"#64748b",border:"1px solid #e2e8f0",borderRadius:10,padding:"10px 18px",fontWeight:700,fontSize:13,cursor:"pointer",fontFamily:_MTZ_FF}}>Cancelar</button>
        <button onClick={_salvar} type="button"
          style={{background:"linear-gradient(135deg,#a855f7,#7c3aed)",color:"#fff",border:"none",borderRadius:10,padding:"10px 22px",fontWeight:800,fontSize:13,cursor:"pointer",fontFamily:_MTZ_FF,boxShadow:"0 6px 16px rgba(124,58,237,.32)"}}>
          {_novo?"Criar cadeira":"Salvar"}
        </button>
      </div>
    </div>
  </div>;
}
/* Modal de detalhe */
function _MtzDetalhe({r, canEdit, onEditar, onExcluir, onFechar}){
  const u=_mtzRespUser(r);
  if(typeof useEscToClose==="function") useEscToClose(true,onFechar);
  const _Sec=function(p){
    return <div>
      <div style={{color:p.cor||"#94a3b8",fontSize:10,fontWeight:800,letterSpacing:.6,textTransform:"uppercase",marginBottom:7}}>{p.t}</div>
      {p.children}
    </div>;
  };
  return <div onMouseDown={function(e){ if(e.target===e.currentTarget) onFechar(); }}
    style={{position:"fixed",inset:0,background:"rgba(15,23,42,.55)",backdropFilter:"blur(4px)",zIndex:490,display:"flex",alignItems:"center",justifyContent:"center",padding:16,fontFamily:_MTZ_FF}}>
    <div onMouseDown={function(e){e.stopPropagation();}}
      style={{background:"#fff",borderRadius:18,width:"100%",maxWidth:680,maxHeight:"92vh",overflow:"auto",boxShadow:"0 24px 64px rgba(15,23,42,.28)"}}>
      <div style={{padding:"20px 24px 16px",borderBottom:"1px solid #f1f5f9",display:"flex",alignItems:"flex-start",gap:14}}>
        <div style={{width:44,height:44,borderRadius:12,background:"linear-gradient(135deg,#7c3aed,#4c1d95)",display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0,boxShadow:"0 5px 14px rgba(124,58,237,.3)",color:"#fff"}}>
          <_MtzIcone nome={r.nome} size={20}/>
        </div>
        <div style={{flex:1,minWidth:0}}>
          <div style={{color:"#0f172a",fontWeight:800,fontSize:18,letterSpacing:-.4,lineHeight:1.25}}>{r.nome}</div>
          <div style={{display:"flex",alignItems:"center",gap:8,marginTop:7}}>
            {u&&typeof UserAvatar==="function"
              ? <UserAvatar user={u} size={24}/>
              : <span style={{width:24,height:24,borderRadius:"50%",background:"#7c3aed14",border:"1px solid #7c3aed2b",color:"#7c3aed",display:"inline-flex",alignItems:"center",justifyContent:"center",fontSize:10,fontWeight:800}}>{String(r.responsavel_nome||"?").charAt(0).toUpperCase()}</span>}
            <span style={{color:"#475569",fontSize:13,fontWeight:700}}>{r.responsavel_nome||"—"}</span>
            {r.updated_at&&<span style={{color:"#cbd5e1",fontSize:11,fontWeight:600,marginLeft:4}}>· atualizada em {_mtzBR(r.updated_at)}</span>}
          </div>
        </div>
        <button onClick={onFechar} title="Fechar"
          style={{background:"#f8fafc",border:"1px solid #e2e8f0",borderRadius:9,width:32,height:32,color:"#64748b",cursor:"pointer",display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
        </button>
      </div>
      <div style={{padding:"18px 24px",display:"flex",flexDirection:"column",gap:18}}>
        {r.missao&&<div style={{background:"#faf5ff",border:"1px solid #ede9fe",borderRadius:12,padding:"13px 16px",color:"#4c1d95",fontSize:13.5,lineHeight:1.65,fontWeight:500}}>{r.missao}</div>}
        {_mtzQtd(r.atribuicoes)>0&&<_Sec t="Atribuições" cor="#7c3aed">
          <div style={{display:"flex",flexDirection:"column",gap:20}}>
          {_mtzGrupos(r.atribuicoes).map(function(g,gi){
            return <div key={gi}>
              {g.titulo&&<div style={{display:"flex",alignItems:"center",gap:8,marginBottom:7}}>
                <span style={{color:"#6d28d9",fontSize:11.5,fontWeight:800,letterSpacing:-.1}}>{g.titulo}</span>
                <span style={{flex:1,height:1,background:"#ede9fe"}}/>
              </div>}
              <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(260px,1fr))",gap:"10px 24px"}}>
                {g.itens.map(function(a,i){
                  return <div key={i} style={{display:"flex",alignItems:"flex-start",gap:7}}>
                    <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="#7c3aed" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" style={{flexShrink:0,marginTop:3}}><polyline points="20 6 9 17 4 12"/></svg>
                    <span style={{color:"#334155",fontSize:12.5,lineHeight:1.5,fontWeight:500}}>{a}</span>
                  </div>;
                })}
              </div>
            </div>;
          })}
          </div>
        </_Sec>}
      </div>
      {canEdit&&<div style={{padding:"12px 24px 18px",borderTop:"1px solid #f1f5f9",display:"flex",justifyContent:"space-between",alignItems:"center",gap:8}}>
        <button onClick={onExcluir} type="button"
          style={{background:"#fff",border:"1px solid #fecaca",color:"#dc2626",borderRadius:10,padding:"9px 16px",fontSize:12.5,fontWeight:700,cursor:"pointer",fontFamily:_MTZ_FF,display:"inline-flex",alignItems:"center",gap:6}}>
          <Ico n="trash" size={13}/>Excluir
        </button>
        <button onClick={onEditar} type="button"
          style={{background:"#0f172a",color:"#fff",border:"none",borderRadius:10,padding:"9px 20px",fontSize:12.5,fontWeight:800,cursor:"pointer",fontFamily:_MTZ_FF}}>Editar</button>
      </div>}
    </div>
  </div>;
}
function PageMatrizResponsabilidades({isMob}){
  const sb=(typeof window!=="undefined")?window._sb:null;
  const _u=(typeof CURRENT_USER!=="undefined")?CURRENT_USER:null;
  const canEdit=!!(_u&&(_u.level===1||_u.id==="ellen"));
  const [cadeiras,setCadeiras]=useState([]);
  const [loading,setLoading]=useState(true);
  const [busca,setBusca]=useState("");
  const [vista,setVista]=useState("cadeiras"); // cadeiras | fluxo
  const [detalhe,setDetalhe]=useState(null);
  const [form,setForm]=useState(null); // null | {} novo | cadeira
  const _carregar=async function(){
    try{
      if(!sb){setLoading(false);return;}
      const {data,error}=await sb.from("responsibility_roles").select("*").order("ordem",{ascending:true}).order("created_at",{ascending:true});
      if(error) throw error;
      setCadeiras(data||[]);
    }catch(e){
      console.warn("[matriz]",e&&e.message);
      if(typeof pixelsToast!=="undefined")pixelsToast.error("Erro carregando a matriz.",3500);
    }
    setLoading(false);
  };
  useEffect(function(){ _carregar(); },[]);
  const _salvar=async function(dados){
    try{
      if(!sb) return;
      if(form&&form.id){
        const {error}=await sb.from("responsibility_roles").update(Object.assign({},dados,{updated_at:new Date().toISOString()})).eq("id",form.id);
        if(error) throw error;
        if(typeof pixelsToast!=="undefined")pixelsToast.success("Cadeira atualizada.");
      }else{
        const {error}=await sb.from("responsibility_roles").insert(Object.assign({},dados,{ordem:cadeiras.length,created_by:_u?_u.name:""}));
        if(error) throw error;
        if(typeof pixelsToast!=="undefined")pixelsToast.success("Cadeira criada.");
      }
      setForm(null); setDetalhe(null);
      _carregar();
    }catch(e){
      if(typeof pixelsToast!=="undefined")pixelsToast.error("Erro salvando: "+((e&&e.message)||""),4000);
    }
  };
  const _excluir=async function(r){
    let ok=true;
    if(typeof pixelsConfirm==="function")
      ok=await pixelsConfirm({title:"Excluir cadeira?",message:'"'+r.nome+'" será removida da matriz. Essa ação não pode ser desfeita.',confirmLabel:"Excluir",danger:true});
    if(!ok) return;
    try{
      if(!sb) return;
      const {error}=await sb.from("responsibility_roles").delete().eq("id",r.id);
      if(error) throw error;
      setDetalhe(null);
      if(typeof pixelsToast!=="undefined")pixelsToast.success("Cadeira excluída.");
      _carregar();
    }catch(e){
      if(typeof pixelsToast!=="undefined")pixelsToast.error("Erro excluindo: "+((e&&e.message)||""),4000);
    }
  };
  const _q=busca.trim().toLowerCase();
  const _norm=function(s){ try{ return String(s||"").toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g,""); }catch(_){ return String(s||"").toLowerCase(); } };
  const _qn=_norm(_q);
  const visiveis=cadeiras.filter(function(r){
    if(!_qn) return true;
    if(_norm(r.nome).indexOf(_qn)>=0) return true;
    if(_norm(r.responsavel_nome).indexOf(_qn)>=0) return true;
    if((r.atribuicoes||[]).some(function(a){return _norm(a).indexOf(_qn)>=0;})) return true;
    if((r.entregas||[]).some(function(a){return _norm(a).indexOf(_qn)>=0;})) return true;
    return false;
  });
  // LADO A LADO (16/09/2026, Vinicius: "não tem como deixar tudo visível lado a lado?")
  // Tela usa a largura toda; cada cadeira é uma coluna. Com 3+ cadeiras entra o modo compacto
  // (banner menor, atribuições em 1 coluna) pra caber tudo; se a tela for estreita, rola de lado.
  const _cmp=!isMob&&vista==="cadeiras"&&visiveis.length>=3;
  return <div style={{display:"flex",flexDirection:"column",gap:14,fontFamily:_MTZ_FF,maxWidth:_cmp?"none":1400,width:"100%",boxSizing:"border-box",margin:"0 auto",padding:isMob?"14px":"18px"}}>
    {/* Header */}
    <div style={{background:"#fff",border:"1px solid #eef0f3",borderRadius:16,padding:"20px 24px",display:"flex",alignItems:"center",gap:14,position:"relative",overflow:"hidden",flexWrap:"wrap"}}>
      <div style={{position:"absolute",top:0,left:0,right:0,height:4,background:"linear-gradient(90deg,#a855f7,#7c3aed)"}}/>
      <div style={{width:46,height:46,borderRadius:13,background:"linear-gradient(135deg,#a855f7,#7c3aed)",display:"flex",alignItems:"center",justifyContent:"center",color:"#fff",boxShadow:"0 6px 16px rgba(124,58,237,.25)"}}>
        <Ico n="layers" size={22} color="#fff"/>
      </div>
      <div style={{flex:1,minWidth:200}}>
        <div style={{color:"#0f172a",fontWeight:800,fontSize:21,letterSpacing:-.5}}>Matriz de Responsabilidades</div>
        <div style={{color:"#64748b",fontSize:13,marginTop:3}}>Estrutura de cadeiras, responsáveis e atribuições da operação.</div>
      </div>
      {canEdit&&<button type="button" onClick={function(){setForm({});}}
        style={{background:"linear-gradient(135deg,#a855f7,#7c3aed)",color:"#fff",border:"none",borderRadius:10,padding:"10px 16px",fontSize:12.5,fontWeight:700,cursor:"pointer",fontFamily:_MTZ_FF,boxShadow:"0 4px 14px rgba(124,58,237,.32)",display:"inline-flex",alignItems:"center",gap:6,whiteSpace:"nowrap"}}>
        <Ico n="plus" size={13} color="#fff"/> Nova cadeira
      </button>}
    </div>
    {/* Busca + vistas */}
    <div style={{display:"flex",gap:10,alignItems:"center",flexWrap:"wrap"}}>
      <div style={{position:"relative",display:"inline-flex",alignItems:"center",flex:1,minWidth:240,maxWidth:420}}>
        <span style={{position:"absolute",left:13,color:busca?"#0f172a":"#94a3b8",pointerEvents:"none",display:"flex"}}>
          <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
        </span>
        <input type="text" value={busca} onChange={function(e){setBusca(e.target.value);}} placeholder="Buscar cadeira ou responsabilidade..."
          style={{background:"#fff",border:"1px solid "+(busca?"#0f172a":"#e2e8f0"),borderRadius:11,padding:"0 14px 0 38px",fontSize:13,fontWeight:500,color:"#0f172a",outline:"none",width:"100%",height:40,boxSizing:"border-box",fontFamily:_MTZ_FF}}/>
      </div>
      <div style={{display:"inline-flex",background:"#f1f5f9",borderRadius:11,padding:3,gap:2}}>
        {[{id:"cadeiras",l:"Cadeiras"},{id:"fluxo",l:"Fluxo"}].map(function(v){
          const _on=vista===v.id;
          return <button key={v.id} type="button" onClick={function(){setVista(v.id);}}
            style={{background:_on?"#fff":"transparent",color:_on?"#0f172a":"#64748b",border:"none",borderRadius:9,padding:"8px 16px",fontSize:12.5,fontWeight:_on?800:600,cursor:"pointer",fontFamily:_MTZ_FF,boxShadow:_on?"0 1px 3px rgba(15,23,42,.08)":"none",transition:"all .12s"}}>{v.l}</button>;
        })}
      </div>
    </div>
    {loading&&<div style={{padding:"48px 0",textAlign:"center",color:"#94a3b8",fontSize:13}}>Carregando a matriz…</div>}
    {!loading&&visiveis.length===0&&<div style={{background:"#fff",border:"1px solid #eef0f3",borderRadius:16,padding:"48px 24px",textAlign:"center"}}>
      <div style={{color:"#0f172a",fontWeight:800,fontSize:15,marginBottom:6}}>{_q?"Nenhuma cadeira bate com essa busca":"Nenhuma cadeira cadastrada ainda"}</div>
      <div style={{color:"#64748b",fontSize:12.5}}>{_q?"Tenta outro termo — a busca olha nome, responsável, atribuições e entregas.":(canEdit?'Clica em "+ Nova cadeira" pra começar.':"Os sócios vão cadastrar as cadeiras em breve.")}</div>
    </div>}
    {/* ── VISTA CADEIRAS ── */}
    {!loading&&vista==="cadeiras"&&visiveis.length>0&&<div style={{overflowX:_cmp?"auto":"visible",paddingBottom:_cmp?6:0}}><div style={{display:"grid",gridTemplateColumns:isMob?"1fr":(_cmp?("repeat("+visiveis.length+",minmax(300px,1fr))"):"repeat(auto-fill,minmax(480px,1fr))"),gap:_cmp?12:14,alignItems:"start"}}>
      {visiveis.map(function(r){
        const u=_mtzRespUser(r);
        const _atr=(r.atribuicoes||[]);
        const cor=(u&&u.color)||"#7c3aed";
        return <div key={r.id} onClick={function(){setDetalhe(r);}}
          style={{background:"#fff",border:"1px solid #e8ebf0",borderRadius:18,overflow:"hidden",cursor:"pointer",display:"flex",flexDirection:"column",transition:"all .18s",boxShadow:"0 2px 8px rgba(15,23,42,.04)"}}
          onMouseEnter={function(e){e.currentTarget.style.transform="translateY(-3px)";e.currentTarget.style.boxShadow="0 14px 34px "+cor+"22";e.currentTarget.style.borderColor=cor+"55";}}
          onMouseLeave={function(e){e.currentTarget.style.transform="";e.currentTarget.style.boxShadow="0 2px 8px rgba(15,23,42,.04)";e.currentTarget.style.borderColor="#e8ebf0";}}>
          {/* Banner com a cor do responsável */}
          <div style={{background:"linear-gradient(135deg,"+cor+" 0%,"+cor+"b8 100%)",padding:isMob?"20px 18px":(_cmp?"16px 16px":"24px 26px"),display:"flex",alignItems:"center",gap:isMob?16:(_cmp?12:22),position:"relative",overflow:"hidden"}}>
            <div style={{position:"absolute",top:-40,right:-40,width:170,height:170,borderRadius:"50%",background:"rgba(255,255,255,0.12)",filter:"blur(2px)",pointerEvents:"none"}}/>
            <div style={{position:"absolute",bottom:-60,right:90,width:120,height:120,borderRadius:"50%",background:"rgba(255,255,255,0.07)",pointerEvents:"none"}}/>
            <div style={{width:isMob?84:(_cmp?62:108),height:isMob?84:(_cmp?62:108),borderRadius:"50%",overflow:"hidden",border:(_cmp?"3px":"4px")+" solid rgba(255,255,255,0.95)",boxShadow:"0 10px 24px rgba(0,0,0,.22)",flexShrink:0,background:"#fff",display:"flex",alignItems:"center",justifyContent:"center",position:"relative"}}>
              {u&&typeof UserAvatar==="function"
                ? <UserAvatar user={u} size={isMob?76:(_cmp?56:100)} border={false}/>
                : <span style={{color:cor,fontSize:34,fontWeight:900}}>{String(r.responsavel_nome||"?").charAt(0).toUpperCase()}</span>}
            </div>
            <div style={{minWidth:0,position:"relative",display:"flex",flexDirection:"column",gap:10}}>
              <div style={{display:"flex",alignItems:"center",gap:11}}>
                <span style={{width:38,height:38,borderRadius:11,background:"rgba(255,255,255,.2)",border:"1px solid rgba(255,255,255,.32)",boxShadow:"inset 0 1px 0 rgba(255,255,255,.25)",display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0,color:"#fff"}}>
                  <_MtzIcone nome={r.nome} size={19}/>
                </span>
                <div style={{color:"#fff",fontWeight:800,fontSize:isMob?17:(_cmp?15:20),letterSpacing:-.4,lineHeight:1.2,textShadow:"0 1px 3px rgba(0,0,0,.12)"}}>{r.nome}</div>
              </div>
              <div style={{alignSelf:"flex-start",color:"#fff",fontSize:12,fontWeight:700,display:"inline-flex",alignItems:"center",gap:6,background:"rgba(255,255,255,.18)",border:"1px solid rgba(255,255,255,.26)",borderRadius:99,padding:"5px 12px 5px 10px"}}>
                <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><path d="M20 21v-2a4 4 0 00-4-4H8a4 4 0 00-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>
                {r.responsavel_nome||"—"}
              </div>
            </div>
          </div>
          <div style={{padding:isMob?"18px 16px 20px":(_cmp?"14px 14px 16px":"22px 24px 24px"),display:"flex",flexDirection:"column",gap:_cmp?14:20,flex:1}}>
            {r.missao&&<div style={{background:cor+"0a",borderLeft:"3px solid "+cor,borderRadius:"0 12px 12px 0",padding:_cmp?"10px 12px":"14px 18px",color:"#475569",fontSize:_cmp?12:13,lineHeight:_cmp?1.55:1.7,fontWeight:500}}>{r.missao}</div>}
            {_atr.length>0&&<div>
              <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:12}}>
                <span style={{color:"#0f172a",fontSize:11,fontWeight:800,letterSpacing:.5,textTransform:"uppercase"}}>Atribuições</span>
                <span style={{flex:1,height:1,background:"linear-gradient(90deg,#e8ebf0,transparent)"}}/>
              </div>
              {_atr.some(_mtzEhSecao)?<div style={{background:"#f8fafc",border:"1px solid #eef1f5",borderRadius:14,padding:isMob?"16px 14px":(_cmp?"14px 12px":"20px 22px"),display:"flex",flexDirection:"column",gap:_cmp?16:24}}>
                {_mtzGrupos(_atr).map(function(g,gi){
                  return <div key={gi}>
                    {g.titulo&&<div style={{display:"flex",alignItems:"center",gap:8,marginBottom:13}}>
                      <span style={{width:3,height:14,borderRadius:2,background:cor,flexShrink:0}}/>
                      <span style={{color:"#0f172a",fontSize:11.5,fontWeight:800,letterSpacing:.4,textTransform:"uppercase"}}>{g.titulo}</span>
                      <span style={{flex:1,height:1,background:"linear-gradient(90deg,#e2e8f0,transparent)",marginLeft:4}}/>
                    </div>}
                    <div style={{display:"grid",gridTemplateColumns:(isMob||_cmp)?"1fr":"1fr 1fr",gap:_cmp?"8px":"13px 28px"}}>
                      {g.itens.map(function(a,i){
                        return <div key={i} style={{display:"flex",alignItems:"flex-start",gap:7}}>
                          <span style={{width:15,height:15,borderRadius:5,background:"#16a34a15",display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0,marginTop:2}}>
                            <svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke="#16a34a" strokeWidth="3.4" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
                          </span>
                          <span style={{color:"#334155",fontSize:_cmp?12:12.5,lineHeight:1.5,fontWeight:500}}>{a}</span>
                        </div>;
                      })}
                    </div>
                  </div>;
                })}
              </div>
              :<div style={{background:"#f8fafc",border:"1px solid #eef1f5",borderRadius:14,padding:isMob?"16px 14px":"20px 22px",display:"flex",gap:28}}>
                {((isMob||_cmp)?[_atr]:[_atr.slice(0,Math.ceil(_atr.length/2)),_atr.slice(Math.ceil(_atr.length/2))]).map(function(_col,_ci){
                  return <div key={_ci} style={{flex:1,minWidth:0,display:"flex",flexDirection:"column",gap:13}}>
                    {_col.map(function(a,i){
                      return <div key={i} style={{display:"flex",alignItems:"flex-start",gap:7}}>
                        <span style={{width:15,height:15,borderRadius:5,background:"#16a34a15",display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0,marginTop:2}}>
                          <svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke="#16a34a" strokeWidth="3.4" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
                        </span>
                        <span style={{color:"#334155",fontSize:_cmp?12:12.5,lineHeight:1.5,fontWeight:500}}>{a}</span>
                      </div>;
                    })}
                  </div>;
                })}
              </div>}
            </div>}
          </div>
        </div>;
      })}
    </div></div>}
    {/* ── VISTA FLUXO — cadeia vertical simples (por ordem), preparada pra crescer ── */}
    {!loading&&vista==="fluxo"&&visiveis.length>0&&<div style={{background:"#fff",border:"1px solid #eef0f3",borderRadius:16,padding:"28px 24px",display:"flex",flexDirection:"column",alignItems:"center",gap:0}}>
      {visiveis.map(function(r,i){
        const u=_mtzRespUser(r);
        return <Fragment key={r.id}>
          {i>0&&<div style={{display:"flex",flexDirection:"column",alignItems:"center",padding:"2px 0"}}>
            <div style={{width:2,height:22,background:"#e2e8f0"}}/>
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#cbd5e1" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round" style={{marginTop:-4}}><polyline points="6 9 12 15 18 9"/></svg>
          </div>}
          <div onClick={function(){setDetalhe(r);}}
            style={{background:"#fafbfc",border:"1px solid #eef0f3",borderRadius:14,padding:"14px 20px",display:"flex",alignItems:"center",gap:12,cursor:"pointer",width:isMob?"100%":420,maxWidth:"100%",transition:"all .12s"}}
            onMouseEnter={function(e){e.currentTarget.style.borderColor="#c4b5fd";e.currentTarget.style.background="#faf5ff";}}
            onMouseLeave={function(e){e.currentTarget.style.borderColor="#eef0f3";e.currentTarget.style.background="#fafbfc";}}>
            {u&&typeof UserAvatar==="function"
              ? <UserAvatar user={u} size={34}/>
              : <span style={{width:34,height:34,borderRadius:"50%",background:"#7c3aed14",border:"1px solid #7c3aed2b",color:"#7c3aed",display:"inline-flex",alignItems:"center",justifyContent:"center",fontSize:12,fontWeight:800,flexShrink:0}}>{String(r.responsavel_nome||"?").charAt(0).toUpperCase()}</span>}
            <div style={{minWidth:0,flex:1}}>
              <div style={{color:"#0f172a",fontWeight:800,fontSize:13.5,letterSpacing:-.2,lineHeight:1.3}}>{r.nome}</div>
              <div style={{color:"#94a3b8",fontSize:11,fontWeight:600,marginTop:2}}>{r.responsavel_nome||"—"}</div>
            </div>
          </div>
        </Fragment>;
      })}
      <div style={{color:"#cbd5e1",fontSize:11,fontWeight:600,marginTop:18}}>O fluxo segue a ordem das cadeiras — conforme a estrutura crescer (Direção, Produção, Gestão de mídia), os níveis entram aqui.</div>
    </div>}
    {detalhe&&<_MtzDetalhe r={detalhe} canEdit={canEdit}
      onEditar={function(){setForm(detalhe);}}
      onExcluir={function(){_excluir(detalhe);}}
      onFechar={function(){setDetalhe(null);}}/>}
    {form&&<_MtzForm inicial={form.id?form:null} cadeiras={cadeiras}
      onSalvar={_salvar} onFechar={function(){setForm(null);}}/>}
  </div>;
}

// ======= 31_roteiros.jsx =======
/* ═══════════════════════════════════════════════════════════════════════
   ROTEIROS — sidebar, logo abaixo da Linha de produção (ideia do Vinicius, 16/09/2026)
   Criador de roteiros de vídeo pra mandar pro cliente gravar.
   • Aba Roteiros: um clique → a IA escreve 5 roteiros de 90s sobre 5 ASSUNTOS diferentes
     pro cliente escolhido, no formato Abertura / Desenvolvimento / Fechamento com CTA.
     Cada um fica inteiro na tela, com "Copiar pro WhatsApp" e um olho que manda pro portal.
   • Aba Trends: a Luiza cadastra a trend (título + do que se trata) e clica pra gerar
     5 ideias adaptando a trend pro cliente.
   • Portal do cliente › "Sugestões de conteúdo" mostra os roteiros marcados com o olho.
   Mesma inteligência da Linha de produção: antes de escrever, a IA lê playbook, foco do
   mês, regras aprendidas, vídeos aprovados do cliente e os roteiros que já existem aqui
   (pra não repetir assunto). Tabelas: roteiros_video, roteiros_trends (RLS agência;
   cliente só lê o que está visível no portal).
   ═══════════════════════════════════════════════════════════════════════ */
const _RT_FF="'Inter',system-ui,sans-serif";
const _RT_AC="#7c3aed";

function _rtTexto(r,semCabecalho){
  const py=String(r.unidade||"")==="paraguay";
  const L=py?{a:"Apertura",d:"Desarrollo",f:"Cierre"}:{a:"Abertura",d:"Desenvolvimento",f:"Fechamento"};
  return (semCabecalho?"":("🎬 *"+(r.assunto||"Roteiro")+"*\n\n"))+
    "*"+L.a+"*\n"+(r.abertura||"")+"\n\n*"+L.d+"*\n"+(r.desenvolvimento||"")+"\n\n*"+L.f+"*\n"+(r.fechamento||"");
}
function _rtPalavras(r){ return ((r.abertura||"")+" "+(r.desenvolvimento||"")+" "+(r.fechamento||"")).trim().split(/\s+/).filter(Boolean).length; }
function _rtCopiar(txt,msg){ try{ navigator.clipboard.writeText(txt); if(typeof pixelsToast!=="undefined") pixelsToast.success(msg||"Copiado!",1800); }catch(_){} }

/* ── GERADOR ──
   Devolve [{assunto,abertura,desenvolvimento,fechamento}] × quantos.
   trend = {titulo,descricao} quando vem da aba Trends. */
async function pxGerarRoteiros(opts){
  const client=String((opts&&opts.client)||""), unit=String((opts&&opts.unit)||"");
  const clienteNome=String((opts&&opts.clienteNome)||client);
  const trend=(opts&&opts.trend)||null;
  const jaFeitos=Array.isArray(opts&&opts.jaFeitos)?opts.jaFeitos:[];
  const quantos=Math.max(1,Math.min(5,(opts&&opts.quantos)||5));
  if(typeof askIA!=="function") throw new Error("Pixels IA indisponível neste ambiente.");
  const py=unit==="paraguay";
  const fake={id:"roteiros-"+client, client:client, bioterUnit:unit, title:"Roteiro de vídeo", contentType:"video", tags:[]};
  const ctx=(typeof pxContextoCopy==="function")?await pxContextoCopy(client,unit,fake):null;
  let ex=[]; try{ if(typeof pxExemplosEstilo==="function") ex=await pxExemplosEstilo(fake,unit); }catch(_){}
  const pb=(ctx&&ctx.playbook)||{}, regras=(ctx&&ctx.regras)||[], foco=(ctx&&ctx.foco_do_mes)||[], aprov=(ctx&&ctx.aprovadas)||[], recus=(ctx&&ctx.recusadas)||[];

  const sys="Você escreve roteiros de vídeo pra empresas do agronegócio e da construção no Brasil, na voz de cada marca. "+
    "O roteiro é a FALA que o dono ou o técnico da empresa vai gravar olhando pra câmera. Escreve como gente que conhece o campo e a obra: "+
    "direto, concreto, sem jargão de marketing e sem frase de efeito vazia. Nunca inventa número, cidade, prazo, garantia ou depoimento que não tenha sido informado. "+
    (py?"ESCREVA AS FALAS EM ESPANHOL (é a unidade do Paraguai); os rótulos ficam em português.":"Escreva em português do Brasil.")+
    " Responda EXATAMENTE no formato pedido, texto puro, sem markdown, sem comentário antes nem depois.";

  let u="CLIENTE: "+clienteNome+(unit?(" — unidade "+unit):"")+"\n\n";
  if(pb.descricao||pb.sobre) u+="SOBRE A EMPRESA:\n"+_pxCtxTxt(pb.descricao||pb.sobre)+"\n\n";
  if(pb.comunicacao) u+="TOM DE VOZ DA MARCA:\n"+_pxCtxTxt(pb.comunicacao)+"\n\n";
  if(pb.pilares&&pb.pilares.length) u+="PILARES DE CONTEÚDO: "+_pxCtxTxt(pb.pilares)+"\n\n";
  if(pb.produtos&&pb.produtos.length) u+="PRODUTOS E SERVIÇOS: "+_pxCtxTxt(pb.produtos).slice(0,900)+"\n\n";
  if(pb.chamadas_proibidas&&pb.chamadas_proibidas.length) u+="⛔ CHAMADAS PROIBIDAS (nunca usar, nem parecido): "+_pxCtxTxt(pb.chamadas_proibidas)+"\n\n";
  if(regras.length){ u+="REGRAS APRENDIDAS COM O FEEDBACK DA AGÊNCIA (obrigatórias):\n"; regras.forEach(function(r){ u+="- ["+String(r.tipo||"").toUpperCase()+"] "+r.regra+"\n"; }); u+="\n"; }
  if(foco.length){
    u+="FOCO DO MÊS / TRIMESTRE (Planejamento com o cliente):\n";
    foco.slice(0,3).forEach(function(f){ const p=[]; if(f.objetivo)p.push("objetivo: "+f.objetivo); if(_pxCtxTxt(f.produtos_foco))p.push("produtos em foco: "+_pxCtxTxt(f.produtos_foco)); if(_pxCtxTxt(f.campanhas))p.push("campanhas: "+_pxCtxTxt(f.campanhas)); if(p.length) u+="- "+(f.mes||"?")+"/"+(f.ano||"?")+" — "+p.join("; ")+"\n"; });
    u+="\n";
  }
  if(ex.length){
    u+="VÍDEOS JÁ APROVADOS DESTE CLIENTE (é este o padrão que a agência aprova — siga o molde, não o conteúdo):\n";
    ex.filter(function(e){return e.mesmo_cliente;}).slice(0,3).forEach(function(e){ u+="--- "+e.titulo+"\n"+String(e.briefing||"").slice(0,600)+"\n"; });
    u+="\n";
  }
  if(aprov.length){ u+="LEGENDAS JÁ APROVADAS (o tom que funciona):\n"; aprov.slice(0,4).forEach(function(a){ u+="---\n"+_pxHtmlParaTexto(a.legenda).slice(0,400)+"\n"; }); u+="\n"; }
  if(recus.length){ u+="RECUSADAS E O MOTIVO (não repetir o erro):\n"; recus.slice(0,4).forEach(function(r){ if(r.feedback) u+="- "+(r.titulo||"")+": "+r.feedback+"\n"; }); u+="\n"; }
  if(jaFeitos.length){ u+="⛔ ASSUNTOS QUE JÁ TÊM ROTEIRO (NÃO repita nem chegue perto):\n"; jaFeitos.slice(0,40).forEach(function(a){ u+="- "+a+"\n"; }); u+="\n"; }
  if(trend){
    u+="TREND DO MOMENTO (a social media explicou):\n"+"Título: "+(trend.titulo||"")+"\n"+"Do que se trata: "+(trend.descricao||"")+"\n\n";
    u+="TAREFA: escreva "+quantos+" IDEIAS DE ROTEIRO que adaptem ESSA TREND pra "+clienteNome+" — cada uma encaixa a trend num assunto diferente do negócio do cliente (produto, rotina, bastidor, dúvida do cliente, resultado). A trend é o formato/gancho; o conteúdo é da marca. Nunca invente que a marca fez algo que não fez.\n";
  }else{
    u+="TAREFA: escreva "+quantos+" ROTEIROS sobre "+quantos+" ASSUNTOS TOTALMENTE DIFERENTES entre si pra "+clienteNome+" (ex.: um produto específico, uma dúvida frequente do cliente, um bastidor da rotina, um erro comum no campo/obra, um resultado que o serviço entrega). Nada de dois roteiros sobre a mesma coisa com outras palavras.\n";
  }
  u+=(typeof PX_ROTEIRO_FALA_REGRAS!=="undefined"?PX_ROTEIRO_FALA_REGRAS:"REGRAS: 90 segundos falados (200 a 240 palavras), 3 partes contínuas, frases completas, sem marcação de tempo nem instrução de câmera.\n");
  u+="- A ABERTURA prende em uma ou duas frases e apresenta o assunto. O DESENVOLVIMENTO é o complemento: explica com fatos reais da empresa. O FECHAMENTO amarra a ideia e termina com o CTA — convida a chamar a empresa.\n";
  u+="- Se algum exemplo acima contrariar as REGRAS, valem as REGRAS.\n\n";
  u+="FORMATO EXATO DA RESPOSTA ("+quantos+" blocos):\n";
  for(let i=1;i<=quantos;i++){ u+="===ROTEIRO "+i+"===\nASSUNTO: (3 a 7 palavras, em português)\nABERTURA:\n(fala)\nDESENVOLVIMENTO:\n(fala)\nFECHAMENTO:\n(fala)\n"; }

  const data=await askIA({model:PX_IA_MODELO,max_tokens:4200,system:sys,messages:[{role:"user",content:u}]});
  let txt=((data&&data.content)||[]).map(function(b){return (b&&b.text)||"";}).join("").trim();
  txt=txt.replace(/^```(?:text)?\s*/i,"").replace(/```\s*$/,"").replace(/\*\*/g,"");
  const blocos=txt.split(/===\s*ROTEIRO\s*\d+\s*===/i).map(function(b){return b.trim();}).filter(Boolean);
  const out=[];
  blocos.forEach(function(b){
    const pega=function(rot,prox){ const re=new RegExp("(?:"+rot+")\\s*:\\s*([\\s\\S]*?)(?=\\n\\s*(?:"+prox+")\\s*:|$)","i"); const m=b.match(re); return m?m[1].trim():""; };
    const r={assunto:pega("ASSUNTO","ABERTURA|APERTURA").replace(/^["“]|["”]$/g,"").replace(/\.$/,""),
      abertura:pega("ABERTURA|APERTURA","DESENVOLVIMENTO|DESARROLLO"),
      desenvolvimento:pega("DESENVOLVIMENTO|DESARROLLO","FECHAMENTO|CIERRE"),
      fechamento:pega("FECHAMENTO|CIERRE","NUNCA_ACHA_ISSO_AQUI")};
    if(r.abertura&&r.desenvolvimento&&r.fechamento) out.push(r);
  });
  if(!out.length) throw new Error("A IA respondeu num formato inesperado. Tente de novo.");
  return out.slice(0,quantos);
}

/* ── CARD DE UM ROTEIRO (agência e portal usam o mesmo) ── */
function RoteiroCard({r, cor, agencia, onPortal, onEnviado, onExcluir, isMob}){
  const [aberto,setAberto]=useState(true);
  const py=String(r.unidade||"")==="paraguay";
  const L=py?["Apertura","Desarrollo","Cierre"]:["Abertura","Desenvolvimento","Fechamento"];
  const partes=[["a",L[0],r.abertura],["d",L[1],r.desenvolvimento],["f",L[2],r.fechamento]];
  const _c=cor||_RT_AC;
  const _pill=function(on,c){ return {background:on?c:"#fff",color:on?"#fff":"#475569",border:"1px solid "+(on?c:"#e2e8f0"),borderRadius:99,padding:"6px 11px",fontSize:11.5,fontWeight:700,cursor:"pointer",fontFamily:_RT_FF,display:"inline-flex",alignItems:"center",gap:5,transition:"all .12s"}; };
  const dt=r.created_at?new Date(r.created_at):null;
  return <div style={{background:"#fff",border:"1px solid "+(r.visivel_portal?_c+"66":"#e8ebf0"),borderRadius:16,overflow:"hidden",boxShadow:"0 2px 8px rgba(15,23,42,.04)",borderTop:"4px solid "+_c}}>
    <div style={{padding:"14px 16px 10px",display:"flex",alignItems:"flex-start",gap:10,flexWrap:"wrap"}}>
      <div style={{flex:1,minWidth:200}}>
        <div style={{display:"flex",alignItems:"center",gap:8,flexWrap:"wrap"}}>
          <span style={{width:26,height:26,borderRadius:8,background:_c,color:"#fff",display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0}}><Ico n="video" size={13} color="#fff"/></span>
          <span style={{color:"#0f172a",fontWeight:800,fontSize:15,letterSpacing:-.3}}>{r.assunto||"Roteiro"}</span>
          {r.origem==="trend"&&<span style={{background:"#fdf2f8",color:"#be185d",border:"1px solid #fbcfe8",borderRadius:99,padding:"2px 8px",fontSize:10,fontWeight:800,textTransform:"uppercase",letterSpacing:.4}}>Trend</span>}
          {r.status==="enviado"&&<span style={{background:"#ecfdf5",color:"#047857",border:"1px solid #a7f3d0",borderRadius:99,padding:"2px 8px",fontSize:10,fontWeight:800,textTransform:"uppercase",letterSpacing:.4}}>Enviado</span>}
        </div>
        <div style={{color:"#94a3b8",fontSize:11,fontWeight:600,marginTop:4}}>~90 segundos · {_rtPalavras(r)} palavras{dt?(" · "+dt.toLocaleDateString("pt-BR")):""}{r.trend_titulo?(" · trend: "+r.trend_titulo):""}</div>
      </div>
      <div style={{display:"flex",gap:6,flexWrap:"wrap",alignItems:"center"}}>
        <button type="button" onClick={function(){_rtCopiar(_rtTexto(r),"Roteiro copiado — é só colar no WhatsApp");}} style={_pill(true,"#16a34a")}>
          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 01-2-2V4a2 2 0 012-2h9a2 2 0 012 2v1"/></svg>
          {agencia?"Copiar pro WhatsApp":"Copiar roteiro"}
        </button>
        {agencia&&<button type="button" title={r.visivel_portal?"Está no portal do cliente (Sugestões de conteúdo). Clique pra tirar.":"Mostrar no portal do cliente, em Sugestões de conteúdo"} onClick={onPortal} style={_pill(!!r.visivel_portal,"#0ea5e9")}>
          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>
          {r.visivel_portal?"No portal":"Portal"}
        </button>}
        {agencia&&<button type="button" title={r.status==="enviado"?"Voltar pra sugestão":"Marcar como enviado pro cliente"} onClick={onEnviado} style={_pill(r.status==="enviado","#7c3aed")}>
          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
          {r.status==="enviado"?"Enviado":"Enviado?"}
        </button>}
        {agencia&&<button type="button" title="Excluir" onClick={onExcluir} style={{background:"none",border:"none",color:"#e2b3b3",cursor:"pointer",padding:5,display:"inline-flex",borderRadius:7}}
          onMouseEnter={function(e){e.currentTarget.style.color="#dc2626";}} onMouseLeave={function(e){e.currentTarget.style.color="#e2b3b3";}}>
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-2 14a2 2 0 01-2 2H9a2 2 0 01-2-2L5 6"/></svg></button>}
        <button type="button" onClick={function(){setAberto(!aberto);}} title={aberto?"Recolher":"Abrir"} style={{background:"none",border:"none",color:"#94a3b8",cursor:"pointer",padding:5,display:"inline-flex"}}>
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round" style={{transform:aberto?"rotate(180deg)":"none",transition:"transform .15s"}}><polyline points="6 9 12 15 18 9"/></svg></button>
      </div>
    </div>
    {aberto&&<div style={{padding:"0 16px 16px",display:"grid",gridTemplateColumns:isMob?"1fr":"1fr 1.4fr 1fr",gap:10}}>
      {partes.map(function(p,i){
        return <div key={p[0]} style={{background:"#f8fafc",border:"1px solid #eef1f5",borderRadius:12,padding:"12px 14px",display:"flex",flexDirection:"column",gap:6,minWidth:0}}>
          <div style={{display:"flex",alignItems:"center",gap:7}}>
            <span style={{width:18,height:18,borderRadius:"50%",background:_c,color:"#fff",fontSize:10,fontWeight:800,display:"inline-flex",alignItems:"center",justifyContent:"center"}}>{i+1}</span>
            <span style={{color:"#0f172a",fontSize:11,fontWeight:800,textTransform:"uppercase",letterSpacing:.5}}>{p[1]}</span>
            {i===2&&<span style={{color:"#94a3b8",fontSize:10,fontWeight:700}}>· com CTA</span>}
          </div>
          <div style={{color:"#334155",fontSize:13,lineHeight:1.65,whiteSpace:"pre-wrap"}}>{p[2]}</div>
        </div>;
      })}
    </div>}
  </div>;
}

/* ── PÁGINA DA AGÊNCIA ── */
function PageRoteiros({isMob}){
  const sb=(typeof window!=="undefined")?window._sb:null;
  const _u=(typeof CURRENT_USER!=="undefined")?CURRENT_USER:null;
  const _lista=(typeof CLIENTS!=="undefined"?CLIENTS:[]).filter(function(c){return c&&c.status!=="interno"&&c.status!=="encerrado"&&String(c.name||"").trim();})
    .slice().sort(function(a,b){return String(a.name||"").localeCompare(String(b.name||""),"pt-BR",{sensitivity:"base"});});
  const _unidades=(typeof BIOTER_UNITS!=="undefined"?BIOTER_UNITS:[]);
  const [clId,setClId]=useState(function(){ try{ const s=localStorage.getItem("pixels-roteiros-cliente"); if(s&&_lista.some(function(c){return c.id===s;})) return s; }catch(_){} return _lista[0]?_lista[0].id:""; });
  const [unit,setUnit]=useState(function(){ try{ return localStorage.getItem("pixels-roteiros-unidade")||""; }catch(_){ return ""; } });
  const [aba,setAba]=useState("roteiros");
  const [roteiros,setRoteiros]=useState([]);
  const [trends,setTrends]=useState([]);
  const [loading,setLoading]=useState(true);
  const [gerando,setGerando]=useState("");   // "" | "ia" | trendId
  const [filtro,setFiltro]=useState("todos"); // todos | sugestao | enviado
  const [trendForm,setTrendForm]=useState(null);
  const [trendCliente,setTrendCliente]=useState({}); // trendId -> {client,unit}
  useEffect(function(){ try{ localStorage.setItem("pixels-roteiros-cliente",clId||""); localStorage.setItem("pixels-roteiros-unidade",unit||""); }catch(_){} },[clId,unit]);
  const cl=_lista.find(function(c){return c.id===clId;})||null;
  const isBioter=clId==="bioter";
  const _cor=(cl&&/^#[0-9a-f]{6}$/i.test(cl.color||""))?cl.color:_RT_AC;
  const _logo=cl&&((typeof CLIENT_LOGOS!=="undefined"&&CLIENT_LOGOS[cl.id])||cl.logoUrl||null);
  const _nomeCl=function(id,un){ const c=_lista.find(function(x){return x.id===id;}); const n=c?c.name:id; if(id==="bioter"&&un){ const x=_unidades.find(function(y){return y.id===un;}); return "Bioter "+(x?(x.pickerLabel||x.label):un); } return n; };

  const _carregar=async function(){
    if(!sb) { setLoading(false); return; }
    try{
      const [a,b]=await Promise.all([
        sb.from("roteiros_video").select("*").neq("status","descartado").order("created_at",{ascending:false}).limit(600),
        sb.from("roteiros_trends").select("*").eq("ativa",true).order("created_at",{ascending:false}),
      ]);
      if(!a.error) setRoteiros(a.data||[]);
      if(!b.error) setTrends(b.data||[]);
    }catch(e){ console.warn("[roteiros]",e&&e.message); }
    setLoading(false);
  };
  useEffect(function(){
    _carregar();
    let ch=null,t=null; const rec=function(){ clearTimeout(t); t=setTimeout(_carregar,400); };
    try{ if(sb) ch=sb.channel("roteiros-rt").on("postgres_changes",{event:"*",schema:"public",table:"roteiros_video"},rec).on("postgres_changes",{event:"*",schema:"public",table:"roteiros_trends"},rec).subscribe(); }catch(_){}
    return function(){ clearTimeout(t); try{ if(ch) sb.removeChannel(ch); }catch(_){} };
  },[]);

  const _trendTitulo=function(id){ const t=trends.find(function(x){return x.id===id;}); return t?t.titulo:""; };
  const doCliente=roteiros.filter(function(r){ return r.client_id===clId && (!isBioter || String(r.unidade||"")===String(unit||"")); });
  const visiveis=doCliente.filter(function(r){ return filtro==="todos"||r.status===filtro; }).map(function(r){ return Object.assign({},r,{trend_titulo:_trendTitulo(r.trend_id)}); });

  const _gerar=async function(trend,clientAlvo,unitAlvo){
    const cId=clientAlvo||clId, uId=(cId==="bioter")?(unitAlvo||""):"";
    if(!cId){ pixelsToast.warning("Escolhe o cliente."); return; }
    const chave=trend?trend.id:"ia";
    setGerando(chave);
    try{
      const ja=roteiros.filter(function(r){return r.client_id===cId&&String(r.unidade||"")===uId;}).map(function(r){return r.assunto;}).filter(Boolean);
      const lista=await pxGerarRoteiros({client:cId,unit:uId,clienteNome:_nomeCl(cId,uId),trend:trend?{titulo:trend.titulo,descricao:trend.descricao}:null,jaFeitos:ja,quantos:5});
      const lote=Date.now().toString(36);
      const rows=lista.map(function(r){ return {client_id:cId,unidade:uId,origem:trend?"trend":"ia",trend_id:trend?trend.id:null,lote:lote,assunto:r.assunto,abertura:r.abertura,desenvolvimento:r.desenvolvimento,fechamento:r.fechamento,status:"sugestao",visivel_portal:false,created_by:(_u&&_u.name)||""}; });
      const ins=await sb.from("roteiros_video").insert(rows).select("*");
      if(ins.error) throw ins.error;
      setRoteiros(function(p){ return (ins.data||[]).concat(p); });
      pixelsToast.success(lista.length+" roteiros prontos pra "+_nomeCl(cId,uId)+".",3000);
      if(trend){ setAba("roteiros"); setClId(cId); if(cId==="bioter") setUnit(uId); }
    }catch(e){ pixelsToast.error("Não deu: "+((e&&e.message)||e),5000); }
    setGerando("");
  };
  const _patch=async function(r,patch){
    setRoteiros(function(p){ return p.map(function(x){ return x.id===r.id?Object.assign({},x,patch):x; }); });
    const up=await sb.from("roteiros_video").update(Object.assign({},patch,{updated_at:new Date().toISOString()})).eq("id",r.id);
    if(up.error){ pixelsToast.error("Não salvou: "+up.error.message); _carregar(); }
  };
  const _excluir=async function(r){
    const ok=(typeof pixelsConfirm==="function")?await pixelsConfirm({title:"Excluir roteiro?",message:'"'+(r.assunto||"Roteiro")+'" sai da lista e do portal.',confirmLabel:"Excluir",danger:true}):window.confirm("Excluir?");
    if(!ok) return;
    setRoteiros(function(p){ return p.filter(function(x){ return x.id!==r.id; }); });
    await sb.from("roteiros_video").update({status:"descartado",visivel_portal:false,updated_at:new Date().toISOString()}).eq("id",r.id);
  };
  const _salvarTrend=async function(){
    const f=trendForm||{};
    if(!String(f.titulo||"").trim()){ pixelsToast.warning("Dá um nome pra trend."); return; }
    if(String(f.descricao||"").trim().length<15){ pixelsToast.warning("Explica do que se trata a trend (é isso que a IA usa)."); return; }
    const row={titulo:f.titulo.trim(),descricao:f.descricao.trim(),link:String(f.link||"").trim(),created_by:(_u&&_u.name)||"",updated_at:new Date().toISOString()};
    const r=f.id?await sb.from("roteiros_trends").update(row).eq("id",f.id):await sb.from("roteiros_trends").insert(row);
    if(r.error){ pixelsToast.error("Não salvou: "+r.error.message); return; }
    setTrendForm(null); _carregar(); pixelsToast.success("Trend salva.",2000);
  };
  const _excluirTrend=async function(t){
    const ok=(typeof pixelsConfirm==="function")?await pixelsConfirm({title:"Excluir trend?",message:'"'+t.titulo+'" sai da lista. Os roteiros já gerados continuam.',confirmLabel:"Excluir",danger:true}):window.confirm("Excluir?");
    if(!ok) return;
    await sb.from("roteiros_trends").update({ativa:false}).eq("id",t.id); _carregar();
  };

  const _inp={width:"100%",background:"#fff",border:"1px solid #e2e8f0",borderRadius:10,padding:"10px 13px",fontSize:13,color:"#0f172a",outline:"none",boxSizing:"border-box",fontFamily:_RT_FF};
  const _lbl={color:"#94a3b8",fontSize:10.5,fontWeight:800,letterSpacing:.6,textTransform:"uppercase",marginBottom:6};
  const _btnGerar=function(label,on,busy,cor){ return {background:busy?"#e2e8f0":("linear-gradient(135deg,"+(cor||_RT_AC)+","+(cor||_RT_AC)+"cc)"),color:busy?"#94a3b8":"#fff",border:"none",borderRadius:12,padding:"12px 18px",fontSize:13,fontWeight:800,cursor:busy?"default":"pointer",fontFamily:_RT_FF,display:"inline-flex",alignItems:"center",gap:8,boxShadow:busy?"none":("0 6px 18px "+(cor||_RT_AC)+"44"),whiteSpace:"nowrap"}; };
  const Spin=function(){ return <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" style={{animation:"pxspin 1s linear infinite"}}><path d="M21 12a9 9 0 11-6.2-8.56"/></svg>; };

  return <div style={{display:"flex",flexDirection:"column",gap:14,fontFamily:_RT_FF,maxWidth:1400,margin:"0 auto",padding:isMob?"14px":"18px"}}>
    <style>{"@keyframes pxspin{to{transform:rotate(360deg)}}"}</style>
    {/* Header */}
    <div style={{background:"#fff",border:"1px solid #eef0f3",borderRadius:16,padding:"20px 24px",display:"flex",alignItems:"center",gap:14,position:"relative",overflow:"hidden",flexWrap:"wrap"}}>
      <div style={{position:"absolute",top:0,left:0,right:0,height:4,background:"linear-gradient(90deg,#a855f7,#7c3aed)"}}/>
      <div style={{width:46,height:46,borderRadius:13,background:"linear-gradient(135deg,#a855f7,#7c3aed)",display:"flex",alignItems:"center",justifyContent:"center",boxShadow:"0 6px 16px rgba(124,58,237,.25)"}}><Ico n="video" size={22} color="#fff"/></div>
      <div style={{flex:1,minWidth:220}}>
        <div style={{color:"#0f172a",fontWeight:800,fontSize:21,letterSpacing:-.5}}>Roteiros</div>
        <div style={{color:"#64748b",fontSize:13,marginTop:3}}>Roteiros de vídeo de 90 segundos pro cliente gravar — abertura, desenvolvimento e fechamento com CTA. O que for marcado com o olho aparece no portal, em Sugestões de conteúdo.</div>
      </div>
      <div style={{display:"inline-flex",background:"#f1f5f9",borderRadius:11,padding:3,gap:2}}>
        {[{id:"roteiros",l:"Roteiros"},{id:"trends",l:"Trends"}].map(function(v){ const on=aba===v.id; return <button key={v.id} type="button" onClick={function(){setAba(v.id);}} style={{background:on?"#fff":"transparent",color:on?"#0f172a":"#64748b",border:"none",borderRadius:9,padding:"8px 16px",fontSize:12.5,fontWeight:on?800:600,cursor:"pointer",fontFamily:_RT_FF,boxShadow:on?"0 1px 3px rgba(15,23,42,.08)":"none"}}>{v.l}{v.id==="trends"&&trends.length?(" · "+trends.length):""}</button>; })}
      </div>
    </div>

    {aba==="roteiros"&&<>
      {/* Cliente + unidade + gerar */}
      <div style={{background:"#fff",border:"1px solid #eef0f3",borderRadius:16,padding:"14px 16px",display:"flex",alignItems:"center",gap:12,flexWrap:"wrap"}}>
        <label style={{display:"inline-flex",alignItems:"center",gap:8,background:"#f8fafc",border:"1px solid #e2e8f0",borderRadius:10,padding:"6px 10px 6px 6px"}}>
          <span style={{width:28,height:28,borderRadius:7,background:"#fff",border:"1px solid "+_cor+"33",display:"inline-flex",alignItems:"center",justifyContent:"center",overflow:"hidden",flexShrink:0}}>
            {_logo?<img src={_logo} alt="" style={{width:"82%",height:"82%",objectFit:"contain"}}/>:<span style={{color:_cor,fontSize:9,fontWeight:900}}>{String((cl&&cl.name)||"?").slice(0,2).toUpperCase()}</span>}
          </span>
          <span style={{color:"#94a3b8",fontSize:10.5,fontWeight:700,letterSpacing:.4,textTransform:"uppercase"}}>Cliente</span>
          <select value={clId} onChange={function(e){setClId(e.target.value); setUnit("");}} style={{border:"none",background:"transparent",color:"#0f172a",fontSize:13,fontWeight:800,outline:"none",cursor:"pointer",fontFamily:"inherit",maxWidth:240}}>
            {_lista.map(function(c){return <option key={c.id} value={c.id}>{c.name}</option>;})}
          </select>
        </label>
        {isBioter&&<div style={{display:"flex",gap:5,flexWrap:"wrap"}}>
          {[{id:"",label:"Grupo"}].concat(_unidades.map(function(u){return {id:u.id,label:u.pickerLabel||u.label};})).map(function(u){ const on=(unit||"")===u.id; return <button key={u.id||"g"} type="button" onClick={function(){setUnit(u.id);}} style={{background:on?"#0f172a":"#fff",color:on?"#fff":"#475569",border:"1px solid "+(on?"#0f172a":"#e2e8f0"),borderRadius:99,padding:"6px 12px",fontSize:11.5,fontWeight:on?800:600,cursor:"pointer",fontFamily:_RT_FF}}>{u.label}</button>; })}
        </div>}
        <span style={{flex:1}}/>
        <div style={{display:"inline-flex",background:"#f1f5f9",borderRadius:9,padding:2,gap:2}}>
          {[{id:"todos",l:"Todos"},{id:"sugestao",l:"Sugestões"},{id:"enviado",l:"Enviados"}].map(function(v){ const on=filtro===v.id; return <button key={v.id} type="button" onClick={function(){setFiltro(v.id);}} style={{background:on?"#fff":"transparent",color:on?"#0f172a":"#64748b",border:"none",borderRadius:7,padding:"6px 11px",fontSize:11.5,fontWeight:on?800:600,cursor:"pointer",fontFamily:_RT_FF}}>{v.l}</button>; })}
        </div>
        <button type="button" disabled={!!gerando} onClick={function(){_gerar(null);}} style={_btnGerar("",true,!!gerando,_cor)}>
          {gerando==="ia"?<><Spin/> Escrevendo 5 roteiros…</>:<><Ico n="sparkles" size={14} color="#fff"/> Gerar 5 roteiros</>}
        </button>
      </div>
      {gerando==="ia"&&<div style={{background:_cor+"0d",border:"1px dashed "+_cor+"66",borderRadius:14,padding:"14px 18px",color:"#475569",fontSize:12.5,lineHeight:1.6}}>
        Lendo o playbook, o foco do mês, as regras aprendidas e os vídeos já aprovados de <b>{_nomeCl(clId,unit)}</b>… Os 5 roteiros vão sair sobre 5 assuntos diferentes dos {doCliente.length} que já existem aqui. Leva uns 30 a 60 segundos.
      </div>}
      {loading&&<div style={{padding:"40px 0",textAlign:"center",color:"#94a3b8",fontSize:13}}>Carregando…</div>}
      {!loading&&visiveis.length===0&&<div style={{background:"#fff",border:"1px dashed #e2e8f0",borderRadius:16,padding:"44px 24px",textAlign:"center"}}>
        <div style={{color:"#0f172a",fontWeight:800,fontSize:15,marginBottom:6}}>Nenhum roteiro pra {_nomeCl(clId,unit)} ainda</div>
        <div style={{color:"#64748b",fontSize:12.5}}>Clica em "Gerar 5 roteiros". A IA escreve com base no playbook, no foco do mês e no que já foi aprovado pra esse cliente.</div>
      </div>}
      {!loading&&visiveis.length>0&&<div style={{display:"flex",flexDirection:"column",gap:12}}>
        {visiveis.map(function(r){ return <RoteiroCard key={r.id} r={r} cor={_cor} agencia={true} isMob={isMob}
          onPortal={function(){_patch(r,{visivel_portal:!r.visivel_portal});}}
          onEnviado={function(){_patch(r,{status:r.status==="enviado"?"sugestao":"enviado"});}}
          onExcluir={function(){_excluir(r);}}/>; })}
      </div>}
    </>}

    {aba==="trends"&&<>
      <div style={{background:"#fff",border:"1px solid #eef0f3",borderRadius:16,padding:"14px 16px",display:"flex",alignItems:"center",gap:12,flexWrap:"wrap"}}>
        <div style={{flex:1,minWidth:220,color:"#475569",fontSize:12.5,lineHeight:1.5}}>Cadastre a trend e explique do que se trata. Depois, em cada trend, escolha o cliente e clique em <b>Gerar 5 ideias</b>: a IA adapta a trend pro negócio dele, no mesmo formato de 90s.</div>
        <button type="button" onClick={function(){setTrendForm({titulo:"",descricao:"",link:""});}} style={_btnGerar("",true,false,"#db2777")}><Ico n="plus" size={13} color="#fff"/> Nova trend</button>
      </div>
      {trendForm&&<div style={{background:"#fff",border:"1px solid #fbcfe8",borderRadius:16,padding:"18px 20px",display:"flex",flexDirection:"column",gap:12,boxShadow:"0 8px 24px rgba(219,39,119,.08)"}}>
        <div style={{color:"#0f172a",fontWeight:800,fontSize:15}}>{trendForm.id?"Editar trend":"Nova trend"}</div>
        <div><div style={_lbl}>Nome da trend *</div><input value={trendForm.titulo} onChange={function(e){setTrendForm(Object.assign({},trendForm,{titulo:e.target.value}));}} placeholder='ex: "POV: você chega na obra e…"' style={_inp}/></div>
        <div><div style={_lbl}>Do que se trata *</div><textarea value={trendForm.descricao} onChange={function(e){setTrendForm(Object.assign({},trendForm,{descricao:e.target.value}));}} rows={4} placeholder="Explica a trend como você explicaria pra um colega: qual é o formato, o áudio ou o gancho, por que está funcionando, que tipo de vídeo as pessoas estão fazendo com ela." style={Object.assign({},_inp,{resize:"vertical",lineHeight:1.55})}/></div>
        <div><div style={_lbl}>Link de referência (opcional)</div><input value={trendForm.link||""} onChange={function(e){setTrendForm(Object.assign({},trendForm,{link:e.target.value}));}} placeholder="https://instagram.com/reel/…" style={_inp}/></div>
        <div style={{display:"flex",justifyContent:"flex-end",gap:8}}>
          <button type="button" onClick={function(){setTrendForm(null);}} style={{background:"#f1f5f9",border:"none",borderRadius:9,padding:"10px 16px",color:"#475569",fontWeight:600,fontSize:13,cursor:"pointer",fontFamily:_RT_FF}}>Cancelar</button>
          <button type="button" onClick={_salvarTrend} style={{background:"#db2777",border:"none",borderRadius:9,padding:"10px 20px",color:"#fff",fontWeight:800,fontSize:13,cursor:"pointer",fontFamily:_RT_FF}}>Salvar trend</button>
        </div>
      </div>}
      {!loading&&trends.length===0&&!trendForm&&<div style={{background:"#fff",border:"1px dashed #e2e8f0",borderRadius:16,padding:"44px 24px",textAlign:"center"}}>
        <div style={{color:"#0f172a",fontWeight:800,fontSize:15,marginBottom:6}}>Nenhuma trend cadastrada</div>
        <div style={{color:"#64748b",fontSize:12.5}}>Viu uma trend que combina com os clientes? Cadastra aqui e gera as ideias.</div>
      </div>}
      {trends.map(function(t){
        const sel=trendCliente[t.id]||{client:clId,unit:""};
        const gerados=roteiros.filter(function(r){return r.trend_id===t.id;});
        const busy=gerando===t.id;
        const cSel=_lista.find(function(c){return c.id===sel.client;});
        const corSel=(cSel&&/^#[0-9a-f]{6}$/i.test(cSel.color||""))?cSel.color:_RT_AC;
        return <div key={t.id} style={{background:"#fff",border:"1px solid #e8ebf0",borderRadius:16,overflow:"hidden",boxShadow:"0 2px 8px rgba(15,23,42,.04)"}}>
          <div style={{padding:"14px 16px",background:"linear-gradient(135deg,#fdf2f8,#fff)",borderBottom:"1px solid #fce7f3",display:"flex",gap:12,alignItems:"flex-start",flexWrap:"wrap"}}>
            <span style={{width:36,height:36,borderRadius:10,background:"#db2777",color:"#fff",display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0,boxShadow:"0 4px 10px rgba(219,39,119,.3)"}}><Ico n="zap" size={17} color="#fff"/></span>
            <div style={{flex:1,minWidth:220}}>
              <div style={{color:"#0f172a",fontWeight:800,fontSize:15,letterSpacing:-.3}}>{t.titulo}</div>
              <div style={{color:"#475569",fontSize:12.5,lineHeight:1.55,marginTop:4,whiteSpace:"pre-wrap"}}>{t.descricao}</div>
              <div style={{color:"#94a3b8",fontSize:11,fontWeight:600,marginTop:6,display:"flex",gap:10,flexWrap:"wrap"}}>
                {t.link&&<a href={t.link} target="_blank" rel="noreferrer" style={{color:"#db2777",fontWeight:700,textDecoration:"none"}}>Ver referência ↗</a>}
                <span>por {t.created_by||"—"} · {new Date(t.created_at).toLocaleDateString("pt-BR")}</span>
                <span>{gerados.length} ideia{gerados.length===1?"":"s"} gerada{gerados.length===1?"":"s"}</span>
              </div>
            </div>
            <div style={{display:"flex",gap:6,alignItems:"center",flexWrap:"wrap"}}>
              <select value={sel.client} onChange={function(e){ const v=e.target.value; setTrendCliente(Object.assign({},trendCliente,{[t.id]:{client:v,unit:""}})); }} style={{background:"#fff",border:"1px solid #e2e8f0",borderRadius:9,padding:"8px 10px",fontSize:12.5,fontWeight:700,color:"#0f172a",fontFamily:_RT_FF,outline:"none"}}>
                {_lista.map(function(c){return <option key={c.id} value={c.id}>{c.name}</option>;})}
              </select>
              {sel.client==="bioter"&&<select value={sel.unit||""} onChange={function(e){ setTrendCliente(Object.assign({},trendCliente,{[t.id]:{client:sel.client,unit:e.target.value}})); }} style={{background:"#fff",border:"1px solid #e2e8f0",borderRadius:9,padding:"8px 10px",fontSize:12.5,fontWeight:700,color:"#0f172a",fontFamily:_RT_FF,outline:"none"}}>
                <option value="">Grupo</option>{_unidades.map(function(u){return <option key={u.id} value={u.id}>{u.pickerLabel||u.label}</option>;})}
              </select>}
              <button type="button" disabled={!!gerando} onClick={function(){_gerar(t,sel.client,sel.unit);}} style={_btnGerar("",true,!!gerando,corSel)}>
                {busy?<><Spin/> Criando…</>:<><Ico n="sparkles" size={13} color="#fff"/> Gerar 5 ideias</>}
              </button>
              <button type="button" title="Editar" onClick={function(){setTrendForm({id:t.id,titulo:t.titulo,descricao:t.descricao,link:t.link||""});}} style={{background:"none",border:"none",color:"#94a3b8",cursor:"pointer",padding:5,display:"inline-flex"}}><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="M11 4H4a2 2 0 00-2 2v14a2 2 0 002 2h14a2 2 0 002-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 013 3L12 15l-4 1 1-4 9.5-9.5z"/></svg></button>
              <button type="button" title="Excluir trend" onClick={function(){_excluirTrend(t);}} style={{background:"none",border:"none",color:"#e2b3b3",cursor:"pointer",padding:5,display:"inline-flex"}}><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-2 14a2 2 0 01-2 2H9a2 2 0 01-2-2L5 6"/></svg></button>
            </div>
          </div>
          {gerados.length>0&&<div style={{padding:12,display:"flex",flexDirection:"column",gap:10,background:"#fafbfc"}}>
            {gerados.map(function(r){ const c=_lista.find(function(x){return x.id===r.client_id;}); const cc=(c&&/^#[0-9a-f]{6}$/i.test(c.color||""))?c.color:_RT_AC;
              return <div key={r.id}><div style={{color:"#94a3b8",fontSize:10.5,fontWeight:800,textTransform:"uppercase",letterSpacing:.5,margin:"0 0 5px 4px"}}>{_nomeCl(r.client_id,r.unidade)}</div>
                <RoteiroCard r={Object.assign({},r,{trend_titulo:""})} cor={cc} agencia={true} isMob={isMob} onPortal={function(){_patch(r,{visivel_portal:!r.visivel_portal});}} onEnviado={function(){_patch(r,{status:r.status==="enviado"?"sugestao":"enviado"});}} onExcluir={function(){_excluir(r);}}/></div>; })}
          </div>}
        </div>;
      })}
    </>}
  </div>;
}

/* ── PORTAL DO CLIENTE › Sugestões de conteúdo ── */
function PortalSugestoesConteudo({cl, selUnit, isMob}){
  const sb=(typeof window!=="undefined")?window._sb:null;
  const [lista,setLista]=useState(null);
  const cid=String((cl&&cl.id)||"").replace(/^bioter_.*/,"bioter");
  const unitFiltro=(cid==="bioter")?String(selUnit||""):"";
  const _cor=(cl&&/^#[0-9a-f]{6}$/i.test(cl.color||""))?cl.color:_RT_AC;
  const _carregar=async function(){
    if(!sb||!cid){ setLista([]); return; }
    const r=await sb.from("roteiros_video").select("*").eq("client_id",cid).eq("visivel_portal",true).neq("status","descartado").order("created_at",{ascending:false}).limit(100);
    setLista(r.error?[]:(r.data||[]));
  };
  useEffect(function(){
    _carregar();
    let ch=null,t=null; const rec=function(){ clearTimeout(t); t=setTimeout(_carregar,400); };
    try{ if(sb) ch=sb.channel("portal-roteiros-"+cid).on("postgres_changes",{event:"*",schema:"public",table:"roteiros_video"},rec).subscribe(); }catch(_){}
    return function(){ clearTimeout(t); try{ if(ch) sb.removeChannel(ch); }catch(_){} };
  },[cid]);
  const vis=(lista||[]).filter(function(r){ if(cid!=="bioter") return true; if(!unitFiltro||unitFiltro==="grupo"||unitFiltro==="_minhas_") return true; return String(r.unidade||"")===unitFiltro||!r.unidade; });
  return <div style={{display:"flex",flexDirection:"column",gap:14,fontFamily:_RT_FF}}>
    <div style={{background:"#fff",border:"1px solid #eef0f3",borderRadius:16,padding:"18px 22px",display:"flex",alignItems:"center",gap:14,flexWrap:"wrap"}}>
      <div style={{width:44,height:44,borderRadius:12,background:_cor,display:"flex",alignItems:"center",justifyContent:"center",boxShadow:"0 6px 16px "+_cor+"44"}}><Ico n="video" size={20} color="#fff"/></div>
      <div style={{flex:1,minWidth:200}}>
        <div style={{color:"#0f172a",fontWeight:800,fontSize:19,letterSpacing:-.4}}>Sugestões de conteúdo</div>
        <div style={{color:"#64748b",fontSize:12.5,marginTop:3}}>Roteiros de vídeo de 90 segundos pensados pra sua empresa. É só escolher, gravar e mandar pra gente — ou pedir ajustes.</div>
      </div>
    </div>
    {lista===null&&<div style={{padding:"30px 0",textAlign:"center",color:"#94a3b8",fontSize:13}}>Carregando…</div>}
    {lista!==null&&vis.length===0&&<div style={{background:"#fff",border:"1px dashed #e2e8f0",borderRadius:16,padding:"40px 24px",textAlign:"center",color:"#64748b",fontSize:13}}>Em breve a equipe da Pixels publica aqui as sugestões de vídeo pra sua empresa.</div>}
    {vis.map(function(r){ return <RoteiroCard key={r.id} r={r} cor={_cor} agencia={false} isMob={isMob}/>; })}
  </div>;
}
